-- ------------------------------------------------------------------------
-- 0002_reports_history.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Reports = visit history: one row per VISIT, keyed by UID (not one per UCN).
-- Run in the Supabase SQL Editor as postgres. This drops the one-per-UCN
-- uniqueness, adds a unique `uid`, clears the deduped reports, and lets you
-- re-import all visit rows.
-- ===========================================================================

-- 1) Drop the one-report-per-UCN constraint (created by `unique (ucn)`).
alter table public.reports drop constraint if exists reports_ucn_key;

-- 2) Add the visit UID and make it the natural key.
alter table public.reports add column if not exists uid text;
create unique index if not exists reports_uid_key on public.reports (uid) where uid is not null;
-- reports_ucn_idx (ucn) was here; a prefix of reports_ucn_entry_idx (ucn, updated_at desc, id desc).
-- Removed 2026-10-05; 0382 drops it where it exists.

-- 3) Clear the earlier de-duped load so the full visit history can be re-imported.
truncate table public.reports;

-- After running this, re-import reports.csv from Admin Config → Bulk Data Import
-- (now one row per visit, ~17,392 rows).

-- ------------------------------------------------------------------------
-- 0003_call_requests.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Call Requests (Request Registration) — engineers raise a request; it becomes
-- a Pending Registration until a UCN is assigned. REQID starts at 20000 (R…),
-- UniqueID = REQID-Product-SerialNo.
-- ===========================================================================

create sequence if not exists public.call_req_seq start 20000;

create table if not exists public.call_requests (
  id                       bigint generated always as identity primary key,
  reqid                    text unique,                 -- R20000, R20001, …
  unique_key               text,                        -- REQID-Product-SerialNo
  submitted_at             timestamptz not null default now(),
  email                    text default '',
  engineer                 text default '',
  call_type                text default '',
  party_name               text default '',
  state                    text default '',
  city                     text default '',
  address                  text default '',
  customer_contact_details text default '',
  customer_contact_number  text default '',
  product                  text default '',
  serial_no                text default '',
  standard_complaint       text default '',
  reported_problem         text default '',
  installation_report      text default '',
  kyc                      text default '',
  call_attended            text default '',             -- Yes / No
  attended_date            date,
  plan_date                date,
  additional_comments      text default '',
  ucn                      text default '',             -- back-filled on registration
  status                   text default 'Pending',
  created_by               uuid references auth.users (id),
  created_at               timestamptz not null default now()
);
create index if not exists call_requests_pending_idx on public.call_requests (ucn);

-- Assign REQID + UniqueID + submitter on insert.
create or replace function public.call_requests_biu()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.reqid is null or new.reqid = '' then
    new.reqid := 'R' || nextval('public.call_req_seq')::text;
  end if;
  new.unique_key := new.reqid || '-' || coalesce(nullif(new.product,''),'NA') || '-' || coalesce(nullif(new.serial_no,''),'NA');
  if new.created_by is null then new.created_by := auth.uid(); end if;
  if coalesce(new.email,'') = '' then new.email := auth.email(); end if;
  return new;
end $$;
drop trigger if exists call_requests_biu on public.call_requests;
create trigger call_requests_biu before insert on public.call_requests
  for each row execute function public.call_requests_biu();

alter table public.call_requests enable row level security;
drop policy if exists cr_read on public.call_requests;
create policy cr_read on public.call_requests for select using (
  public.is_admin() or created_by = auth.uid() or lower(email) = lower(auth.email())
  or lower(trim(engineer)) in (select lower(trim(n)) from public.visible_engineer_names() as v(n))
);
drop policy if exists cr_insert on public.call_requests;
create policy cr_insert on public.call_requests for insert with check (auth.role() = 'authenticated');
drop policy if exists cr_update on public.call_requests;
create policy cr_update on public.call_requests for update using (auth.role() = 'authenticated') with check (auth.role() = 'authenticated');

-- ------------------------------------------------------------------------
-- 0004_user_directory.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- User Master → user_directory: the engineer/manager directory (names +
-- reporting hierarchy) that drives who-sees-what. Separate from auth logins
-- (profiles): a person is scoped by matching their login email to a directory
-- row, then by the RM/RGM tree (by name). Admins (profiles.role='admin') see all.
-- ===========================================================================

create table if not exists public.user_directory (
  id                 bigint generated always as identity primary key,
  name               text not null,               -- User Name (matches "Call Allocated To")
  email              text default '',
  gmail              text default '',
  designation        text default '',
  reporting_manager  text default '',             -- RM name
  regional_manager   text default '',             -- RGM name
  region             text default '',
  validity           boolean not null default true,
  extra              jsonb not null default '{}'
);
create index if not exists user_directory_email_idx on public.user_directory (lower(email));
create index if not exists user_directory_gmail_idx on public.user_directory (lower(gmail));
create index if not exists user_directory_name_idx  on public.user_directory (lower(name));

alter table public.user_directory enable row level security;
drop policy if exists ud_read on public.user_directory;
create policy ud_read on public.user_directory for select using (auth.role() = 'authenticated');
drop policy if exists ud_admin_write on public.user_directory;
create policy ud_admin_write on public.user_directory for all using (public.is_admin()) with check (public.is_admin());

-- The signed-in user's directory name (by login email or gmail).
create or replace function public.my_dir_name()
returns text language sql stable security definer set search_path = public as $$
  select name from public.user_directory
   where lower(email) = lower(auth.email()) or lower(gmail) = lower(auth.email())
   limit 1;
$$;

-- Names the current user may see: their own + everyone in their reporting
-- sub-tree (recursive over reporting_manager / regional_manager, by name).
create or replace function public.visible_engineer_names()
returns setof text language sql stable security definer set search_path = public as $$
  with recursive me as (
    select name from public.user_directory
     where lower(email) = lower(auth.email()) or lower(gmail) = lower(auth.email())
  ),
  tree as (
    select d.name from public.user_directory d where d.name in (select name from me)
    union
    select c.name from public.user_directory c
      join tree t
        on lower(c.reporting_manager) = lower(t.name)
        or lower(c.regional_manager)  = lower(t.name)
  )
  select name from tree where coalesce(name,'') <> '';
$$;

-- can_see_call() already uses visible_engineer_names(), so call scoping now
-- follows the directory automatically (admins still bypass via is_admin()).

-- ------------------------------------------------------------------------
-- 0029_engineer_address.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- An engineer's delivery address, on the User Master.
--
-- The Declaration form that travels with the parcel ("TO WHOMSOEVER IT MAY
-- CONCERN") addresses it to the engineer. The User Master is where that
-- belongs — its sheet already has ADDRESS / CITY / STATE / Contact No columns,
-- and the User Master screen already showed City, State and Contact — but
-- user_directory never carried them, so on Supabase those columns were blank
-- and the form had nothing to read.
--
-- The four join the directory row, beside the name every other module already
-- refers to an engineer by, so one address serves every future document.
--
-- WHO MAY WRITE THEM is a separate migration (0030_engineer_address_write),
-- because its policy calls has_perm(), which the RBAC module defines and which
-- applies after this one. The columns themselves belong here, with the rest of
-- the User Master.
-- ===========================================================================

alter table public.user_directory
  add column if not exists address text default '',
  add column if not exists city    text default '',
  add column if not exists state   text default '',
  add column if not exists phone   text default '';

-- A directory imported before these were columns put them in `extra` (the
-- in-app importer kept every unmapped sheet column there). Lift them across,
-- so an existing deployment does not have to re-import to address a parcel.
--
-- The write guard is dropped first when it exists: this is a data migration,
-- not somebody editing the directory, and auth.uid() is NULL in the SQL
-- editor, so the guard would refuse it. It is put back below — and on a first
-- run there is nothing to put back, since 0030 has not created it yet.
drop trigger if exists user_directory_address_guard on public.user_directory;

update public.user_directory u
   set address = coalesce(nullif(btrim(u.address), ''),
                          nullif(btrim(u.extra ->> 'ADDRESS'), ''),
                          nullif(btrim(u.extra ->> 'Address'), ''), ''),
       city    = coalesce(nullif(btrim(u.city), ''),
                          nullif(btrim(u.extra ->> 'CITY'), ''),
                          nullif(btrim(u.extra ->> 'City'), ''), ''),
       state   = coalesce(nullif(btrim(u.state), ''),
                          nullif(btrim(u.extra ->> 'STATE'), ''),
                          nullif(btrim(u.extra ->> 'State'), ''), ''),
       phone   = coalesce(nullif(btrim(u.phone), ''),
                          nullif(btrim(u.extra ->> 'Contact  No'), ''),
                          nullif(btrim(u.extra ->> 'Contact No'), ''),
                          nullif(btrim(u.extra ->> 'Contact'), ''), '')
 where u.extra <> '{}'::jsonb;

do $$
begin
  if to_regprocedure('public.user_directory_address_guard()') is not null then
    create trigger user_directory_address_guard
      before update on public.user_directory
      for each row execute function public.user_directory_address_guard();
  end if;
end $$;

-- ------------------------------------------------------------------------
-- 0068_app_user_names.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Who is `created_by`?
--
-- Every quality record stamps `auth.uid()` into created_by / recorded_by /
-- reported_by, and the tables show that raw UUID: Material Returns reads
-- "6680c358-d798-41d0-8f1d-fd543a1c96c5" where it should read "Rithi Admin".
-- The name lives in `profiles`, but its read policy is
--   id = auth.uid() or is_admin() or has_perm('users.manage')
-- so an engineer can only ever resolve their own id — which is why the app
-- cannot do the lookup client-side today.
--
-- `app_user_names` is the narrowest thing that fixes it: id -> display name,
-- and nothing else. No email, no role, no manager, no permissions. Every
-- signed-in user may read it, which discloses no more than `user_directory`
-- (0004) already does — that lists everyone's name to any authenticated user.
--
-- READ-ONLY BY CONSTRUCTION. The RLS bypass lives in a SECURITY DEFINER
-- function and the view merely selects from it, which makes the view
-- non-auto-updatable: no INSERT / UPDATE / DELETE can be routed through it into
-- `profiles`, whatever privileges Supabase's default grants hand out. A plain
-- `select ... from profiles` view would have been auto-updatable and, running
-- as its owner, would have let any signed-in user rewrite or delete every
-- profile row straight past the policy above. The grants below are belt to that
-- braces, not the mechanism.
-- ===========================================================================

create or replace function public.app_user_names_rows()
returns table (id uuid, name text)
language sql stable security definer set search_path = public as $$
  select p.id, coalesce(nullif(trim(p.full_name), ''), p.email, '')
    from public.profiles p;
$$;
-- EXECUTE is checked against the CALLER even inside a view that runs as its
-- owner (owner rights cover table access, not function execute), so the reader
-- needs it. It hands out exactly what the view does — id and name — so this is
-- the same disclosure, not a wider one. anon gets neither.
revoke all on function public.app_user_names_rows() from public, anon;
grant execute on function public.app_user_names_rows() to authenticated;

create or replace view public.app_user_names as
  select id, name from public.app_user_names_rows();

revoke all on public.app_user_names from public, anon, authenticated;
grant select on public.app_user_names to authenticated;

-- ------------------------------------------------------------------------
-- 0092_visible_engineers_by_name.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A REPORTING MANAGER WHO SEES NOTHING, WHILE THE SCREEN SAYS "15 engineers".
--
-- Two implementations of one rule, disagreeing:
--
--   * the CLIENT finds the signed-in person in the User Master by their email,
--     their gmail OR their username, then walks the reporting tree — which is
--     how the header can say "Team view · 15 engineers";
--   * `visible_engineer_names()` matches on email or gmail and NOTHING ELSE.
--     A User Master row whose address has gone stale (or who signs in with a
--     different one) resolves to no row, so the tree is empty and the database
--     returns no calls at all. The screen names a team it cannot read.
--
-- So the lookup falls back to the person's NAME, from their own profile — the
-- name the User Master is keyed on everywhere else in this system. It is a
-- FALLBACK, not a widening: when the address matches, nothing changes, and the
-- name is only consulted when it resolves to no row at all.
-- ===========================================================================

create or replace function public.visible_engineer_names()
returns setof text language sql stable security definer set search_path = public as $$
  with recursive me as (
    select name from public.user_directory
     where lower(email) = lower(auth.email()) or lower(gmail) = lower(auth.email())
  ),
  -- Only when the address finds nobody: the name on the caller's own profile.
  me_by_name as (
    select d.name from public.user_directory d
      join public.profiles p on p.id = auth.uid()
     where not exists (select 1 from me)
       and lower(btrim(d.name)) = lower(btrim(coalesce(p.full_name, '')))
       and btrim(coalesce(p.full_name, '')) <> ''
  ),
  root as (
    select name from me
    union
    select name from me_by_name
  ),
  tree as (
    select d.name from public.user_directory d where d.name in (select name from root)
    union
    select c.name from public.user_directory c
      join tree t
        on lower(c.reporting_manager) = lower(t.name)
        or lower(c.regional_manager)  = lower(t.name)
  )
  select name from tree where coalesce(name,'') <> '';
$$;

-- ------------------------------------------------------------------------
-- 0212_visible_engineers_no_blank_match.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A BLANK NAME IS NOT A MANAGER, AND MUST NOT MATCH ONE.
--
-- Reported from use (2026-09-18): "Why is a Regional Manager able to see
-- everyone's call and every spare request?"
--
-- `visible_engineer_names()` walks the directory DOWNWARDS from the caller —
-- everyone whose reporting_manager or regional_manager is the caller, then
-- everyone under them. The walk matched on name equality with nothing
-- excluding the EMPTY STRING from either side. So when the caller's own row in
-- `user_directory` has a blank `name` — which is what a partial import, a
-- trimmed cell or a directory row keyed only by email leaves — the recursion
-- asks for everyone whose manager is '' and gets every row that has no manager
-- recorded.
--
-- MEASURED, not reasoned about. A regional manager with three of his own and
-- five strangers, run before and after:
--
--   name present : ENG ONE, ENG TWO, ENG THREE, HARSH RM      <- correct
--   name blank   : ENG TWO, ENG THREE, STRANGER A, STRANGER B <- wrong BOTH ways
--
-- Note the second line carefully: it is not "sees everyone", it is worse than
-- that to diagnose. Two strangers are pulled IN, and one of his own team is
-- pushed OUT — because the root no longer matches the people who name him.
-- Nobody looking at that list could tell it was a fault rather than a region.
--
-- THE FIX IS ONE CONDITION, AND IT ONLY EVER NARROWS. A tree node with a blank
-- name stops recursing. A caller whose directory row has no name now sees no
-- team at all, which is the honest answer: the directory does not say who they
-- are, so it cannot say who reports to them. They still see their own calls
-- through the other branches of the read policy, which match on user id and
-- email rather than on name.
--
-- The comparison itself is left EXACTLY as it was. Adding btrim() to both
-- sides would also make ' HARSH RM ' match 'HARSH RM', and that is a WIDENING
-- — more rows visible, not fewer. It may well be wanted, but it is a different
-- decision from closing a leak and does not belong in the same change.
-- ===========================================================================
create or replace function public.visible_engineer_names()
returns setof text
language sql
stable
security definer
set search_path to 'public'
as $$
  with recursive me as (
    select name from public.user_directory
     where lower(email) = lower(auth.email()) or lower(gmail) = lower(auth.email())
  ),
  -- Only when the address finds nobody: the name on the caller's own profile.
  me_by_name as (
    select d.name from public.user_directory d
      join public.profiles p on p.id = auth.uid()
     where not exists (select 1 from me)
       and lower(btrim(d.name)) = lower(btrim(coalesce(p.full_name, '')))
       and btrim(coalesce(p.full_name, '')) <> ''
  ),
  root as (
    select name from me
    union
    select name from me_by_name
  ),
  tree as (
    select d.name from public.user_directory d where d.name in (select name from root)
    union
    select c.name from public.user_directory c
      join tree t
        -- THE GUARD. Without it, '' = '' and every unmanaged row joins the team.
        on btrim(coalesce(t.name, '')) <> ''
       and (lower(c.reporting_manager) = lower(t.name)
         or lower(c.regional_manager)  = lower(t.name))
  )
  select name from tree where coalesce(name,'') <> '';
$$;

-- ------------------------------------------------------------------------
-- 0257_directory_rename_carries_the_team.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- CORRECTING A MANAGER'S NAME NO LONGER EMPTIES THEIR TEAM (finding 23).
--
-- The reporting tree is built from NAMES: `user_directory.reporting_manager`
-- and `.regional_manager` hold a manager's name, and `visible_engineer_names()`
-- matches them against `name`, case-insensitively. Nothing carried a change of
-- that name, so correcting a spelling on User Master left every engineer
-- pointing at a name nobody holds any more. Measured: the Reporting Manager
-- saw 3 people before one edit and 1 after — themselves — and lost every
-- call, spare request, visit and review their team's names scope, with no
-- error anywhere.
--
-- THE USER'S DECISION (2026-09-30): "Carry the rename". When a directory
-- row's name changes, every row naming the OLD name as its Reporting or
-- Regional Manager is updated to the NEW name in the same statement.
--
-- THREE LIMITS, each on purpose:
--
--   1. A BLANK OLD NAME CARRIES NOTHING. Naming somebody who had no name would
--      otherwise rewrite every row with no manager recorded — the blank-name
--      trap 0212 closed on the read side.
--   2. IF ANOTHER ROW STILL CARRIES THE OLD NAME, NOTHING IS CARRIED. Two
--      directory rows with one name are two people the tree already cannot
--      tell apart; the rows naming it still resolve to the one who kept it,
--      and moving them to the renamed person would be a guess.
--   3. A CHANGE OF CASE ONLY CARRIES NOTHING. The tree compares with lower(),
--      so "ravi kumar" -> "Ravi Kumar" breaks nothing and rewriting the team
--      would be writes for no reason.
--
-- IT MATCHES EXACTLY AS THE TREE DOES — lower(), no trimming. A btrim() here
-- would also rewrite a row naming ' Ravi ', which the tree does NOT count as
-- Ravi's today, and so WIDEN a team; this migration only keeps one.
--
-- THE RECORDS filed under the old name — calls, requests, spares,
-- consumption, hand stock — are 0259's, a second trigger: the user first chose
-- to leave them, then (same day, once told that call visibility is by name
-- too) "Rename existing records".
--
-- SECURITY INVOKER. Only an ADMINISTRATOR can change a name at all —
-- `user_directory_address_guard` refuses anybody else any column but the
-- address — and an administrator may write every row, so the cascade can never
-- be partly refused. Running as the caller also stamps sys_updated_by with the
-- person who renamed.
-- ===========================================================================

create or replace function public.user_directory_carry_rename()
returns trigger language plpgsql set search_path = public as $$
begin
  if btrim(coalesce(old.name, '')) = ''
     or lower(old.name) = lower(coalesce(new.name, '')) then
    return null;
  end if;
  if exists (select 1 from public.user_directory d
              where d.id <> new.id and lower(d.name) = lower(old.name)) then
    return null;
  end if;

  update public.user_directory d
     set reporting_manager = new.name
   where d.id <> new.id
     and lower(d.reporting_manager) = lower(old.name);

  update public.user_directory d
     set regional_manager = new.name
   where d.id <> new.id
     and lower(d.regional_manager) = lower(old.name);

  return null;
end $$;

comment on function public.user_directory_carry_rename() is
  'When a User Master name changes, rows naming the old name as Reporting or Regional Manager follow it (finding 23). Not when the old name was blank, is still held by another row, or only its case changed.';

drop trigger if exists user_directory_carry_rename on public.user_directory;
create trigger user_directory_carry_rename
  after update of name on public.user_directory
  for each row execute function public.user_directory_carry_rename();

-- ------------------------------------------------------------------------
-- 0259_directory_rename_carries_the_records.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A RENAME ALSO CARRIES THE PERSON'S RECORDS (finding 23, second half).
--
-- 0257 moves the TEAM: the rows that name a renamed person as their manager.
-- It left work already filed under the old name where it was, and that is not
-- only hand stock. Who may SEE a call is decided by the allottee's NAME
-- (`calls_scoped_read`: lower(trim(allocated_to)) in visible_engineer_names()),
-- and so is a spare request, a consumption line, a stock transfer and the rest
-- -- so after a rename the person, and their manager, stopped seeing
-- everything allotted to the old spelling, and their hand stock split into two
-- balances.
--
-- THE USER'S DECISION (2026-09-30): "Rename existing records".
--
-- WHAT MOVES — every column that decides whose a record IS, matched exactly as
-- its own read policy matches it (lower(btrim()) on both sides):
--
--   calls ............ field_calls / installation_calls / pm_calls.allocated_to
--   requests ......... call_requests.engineer, pending_registrations.engineer
--   spares ........... spare_requests.engineer, spare_dispatches.engineer
--   consumption ...... spare_consumption.engineer, spare_consumption_history.engineer
--   hand stock ....... handstock_opening.engineer, spare_issue_history.engineer,
--                      material_returns.engineer,
--                      stock_transfers.from_engineer / .to_engineer
--   who looks after .. parties.service_engineer, products.service_engineer
--
-- The last two are not history but POINTERS: a new call's Allocated To is
-- filled from the customer's Service Engineer, so a stale name there would
-- allot every new call to a name nobody can see — the same fault again.
--
-- WHAT DOES NOT MOVE, on purpose: who DID something — rm_by, dispatched_by,
-- received_by, recorded_by, a visit report's engineer, a feedback's engineer,
-- the sale's engineer, and spare_request_engineer_log (a log of changes of
-- engineer, which a rename must not rewrite). Those are signatures on a
-- record, and nothing's visibility or stock is decided by them.
--
-- THE SAME THREE LIMITS AS 0257: nothing moves when the old name was blank,
-- when only its case or surrounding space changed (every reader compares
-- lower(btrim())), or when another User Master row still carries the old name
-- — two people with one name, whose records cannot be told apart here.
--
-- GUARDS. Four triggers refuse or react to exactly this change: a consumption
-- line's engineer cannot change, a dispatched request's engineer cannot
-- change, an answered call request is frozen, and a changed allottee sends
-- "Call allotted to you". Each is taught to recognise THIS rename (0260,
-- 0261, 0262) by a TICKET filed here, in the same pattern as rename_part()
-- (0196): a row keyed on the transaction, in a table with row-level security
-- on, no policy and no grants, so only this definer function can write one.
-- A set_config flag would be forgeable by anybody who can update a row.
-- Every other guard still runs; the renamer is an administrator (only an
-- administrator can change a name — user_directory_address_guard), which is
-- what those guards already let through.
--
-- EACH TABLE IS GUARDED BY to_regclass() and updated by dynamic SQL, so a
-- project missing a module still renames what it has. The audit triggers on
-- the quality tables record every row moved.
-- ===========================================================================

create table if not exists public.engineer_rename_ticket (
  txid     bigint primary key,
  old_key  text not null,
  new_name text not null,
  at       timestamptz not null default now()
);
alter table public.engineer_rename_ticket enable row level security;
revoke all on public.engineer_rename_ticket from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on public.engineer_rename_ticket from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on public.engineer_rename_ticket from anon';
  end if;
end $$;
-- THE FIVE SYSTEM COLUMNS (0244), like every other table. Where 0244 has
-- already run -- the live project, a build in migration order -- they are
-- attached here; on a fresh apply of the bundles, `sys_columns` runs last and
-- attaches them to every table then.
do $$ begin
  if to_regprocedure('public.sys_columns_attach(regclass)') is not null then
    perform public.sys_columns_attach('public.engineer_rename_ticket'::regclass);
  end if;
end $$;

comment on table public.engineer_rename_ticket is
  'The capability that lets a User Master rename move the records filed under the old name past the guards that refuse a change of engineer (0259). RLS on with NO policy and no grants: only the definer-owned rename trigger writes one, keyed on its own transaction.';

-- Is THIS transaction renaming `p_old` to `p_new`? Asked by the guards. It
-- answers only about the caller's own transaction, so it discloses nothing.
create or replace function public.engineer_rename_in_progress(p_old text, p_new text)
returns boolean language plpgsql stable security definer set search_path = public as $$
begin
  return exists (
    select 1 from public.engineer_rename_ticket t
     where t.txid = txid_current()
       and t.old_key = lower(btrim(coalesce(p_old, '')))
       and t.new_name = coalesce(p_new, ''));
end $$;
revoke execute on function public.engineer_rename_in_progress(text, text) from public, anon;
grant  execute on function public.engineer_rename_in_progress(text, text) to authenticated;

create or replace function public.user_directory_carry_rename_records()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  old_key text := lower(btrim(coalesce(old.name, '')));
  new_nm  text := btrim(coalesce(new.name, ''));
  target  record;
begin
  if old_key = '' or new_nm = '' or old_key = lower(new_nm) then
    return null;
  end if;
  if exists (select 1 from public.user_directory d
              where d.id <> new.id and lower(btrim(d.name)) = old_key) then
    return null;
  end if;

  insert into public.engineer_rename_ticket (txid, old_key, new_name)
  values (txid_current(), old_key, new_nm)
  on conflict (txid) do update set old_key = excluded.old_key,
                                   new_name = excluded.new_name, at = now();

  for target in
    select * from (values
      ('field_calls', 'allocated_to'), ('installation_calls', 'allocated_to'), ('pm_calls', 'allocated_to'),
      ('call_requests', 'engineer'), ('pending_registrations', 'engineer'),
      ('spare_requests', 'engineer'), ('spare_dispatches', 'engineer'),
      ('spare_consumption', 'engineer'), ('spare_consumption_history', 'engineer'),
      ('handstock_opening', 'engineer'), ('spare_issue_history', 'engineer'),
      ('material_returns', 'engineer'),
      ('stock_transfers', 'from_engineer'), ('stock_transfers', 'to_engineer'),
      ('parties', 'service_engineer'), ('products', 'service_engineer')
    ) v(tbl, col)
  loop
    if to_regclass('public.' || target.tbl) is not null
       and exists (select 1 from information_schema.columns c
                    where c.table_schema = 'public' and c.table_name = target.tbl
                      and c.column_name = target.col) then
      execute format('update public.%I set %I = $1 where lower(btrim(%I)) = $2',
                     target.tbl, target.col, target.col)
        using new_nm, old_key;
    end if;
  end loop;

  delete from public.engineer_rename_ticket where txid = txid_current();
  return null;
end $$;
revoke execute on function public.user_directory_carry_rename_records() from public, anon, authenticated;

comment on function public.user_directory_carry_rename_records() is
  'When a User Master name changes, the records filed under the old name -- calls allotted to it, requests, spares, consumption, hand stock, and the Party Master / Product Database service engineer -- follow it (0259, finding 23). Not when the old name was blank, only its case or spacing changed, or another row still holds it.';

drop trigger if exists user_directory_carry_rename_records on public.user_directory;
create trigger user_directory_carry_rename_records
  after update of name on public.user_directory
  for each row execute function public.user_directory_carry_rename_records();

-- ------------------------------------------------------------------------
-- 0267_rename_carries_adjustments.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A USER MASTER RENAME CARRIES THE HAND STOCK ADJUSTMENTS TOO.
--
-- 0259 (finding 23) moves every record filed under a person's old name to the
-- new one when their User Master name is corrected -- calls, requests, spares,
-- consumption, hand stock. 0266 adds a table filed by engineer name,
-- `handstock_adjustments`; without joining that list, an engineer whose name
-- was corrected would keep their stock but lose their adjustments, and the
-- balance would split in two. The function below is 0259's VERBATIM with that
-- one table added to the list. The table's absence is tolerated exactly as
-- 0259 tolerates any other (to_regclass), so this can run before 0266.
-- ===========================================================================

create or replace function public.user_directory_carry_rename_records()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  old_key text := lower(btrim(coalesce(old.name, '')));
  new_nm  text := btrim(coalesce(new.name, ''));
  target  record;
begin
  if old_key = '' or new_nm = '' or old_key = lower(new_nm) then
    return null;
  end if;
  if exists (select 1 from public.user_directory d
              where d.id <> new.id and lower(btrim(d.name)) = old_key) then
    return null;
  end if;

  insert into public.engineer_rename_ticket (txid, old_key, new_name)
  values (txid_current(), old_key, new_nm)
  on conflict (txid) do update set old_key = excluded.old_key,
                                   new_name = excluded.new_name, at = now();

  for target in
    select * from (values
      ('field_calls', 'allocated_to'), ('installation_calls', 'allocated_to'), ('pm_calls', 'allocated_to'),
      ('call_requests', 'engineer'), ('pending_registrations', 'engineer'),
      ('spare_requests', 'engineer'), ('spare_dispatches', 'engineer'),
      ('spare_consumption', 'engineer'), ('spare_consumption_history', 'engineer'),
      ('handstock_opening', 'engineer'), ('spare_issue_history', 'engineer'),
      ('material_returns', 'engineer'), ('handstock_adjustments', 'engineer'),
      ('stock_transfers', 'from_engineer'), ('stock_transfers', 'to_engineer'),
      ('parties', 'service_engineer'), ('products', 'service_engineer')
    ) v(tbl, col)
  loop
    if to_regclass('public.' || target.tbl) is not null
       and exists (select 1 from information_schema.columns c
                    where c.table_schema = 'public' and c.table_name = target.tbl
                      and c.column_name = target.col) then
      execute format('update public.%I set %I = $1 where lower(btrim(%I)) = $2',
                     target.tbl, target.col, target.col)
        using new_nm, old_key;
    end if;
  end loop;

  delete from public.engineer_rename_ticket where txid = txid_current();
  return null;
end $$;
revoke execute on function public.user_directory_carry_rename_records() from public, anon, authenticated;

-- ------------------------------------------------------------------------
-- 0346_rename_carries_pending_indoor_dc.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0346 — A USER MASTER RENAME CARRIES THE INDOOR DCs WAITING FOR THAT PERSON
--        (second re-review, 2026-10-03: D-144)
--
-- user_directory_carry_rename_records() (0259, 0267) moves every record filed
-- under a person's old name to the new one. indoor_dcs.authorised_by_name was
-- not on its list, and it is how an Indoor DC finds its approver (0327:
-- indoor_dc_may_approve, the read policy and approve_indoor_dc all match it).
-- Measured: after the authoriser was renamed they saw 0 DCs and could not reach
-- the one naming them, which stayed Pending approval with its units held.
--
-- ONLY A PENDING DC MOVES. On an approved, rejected or "issued before
-- approval" DC the name is what the printed document says authorised it, and
-- re-printing it must say the same thing.
--
-- The function below is 0267's VERBATIM with that one statement added, read
-- from a database built from every migration. Same module (user_directory),
-- after 0267, so a replay of user_directory.sql ends on this definition.
-- ===========================================================================

create or replace function public.user_directory_carry_rename_records()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  old_key text := lower(btrim(coalesce(old.name, '')));
  new_nm  text := btrim(coalesce(new.name, ''));
  target  record;
begin
  if old_key = '' or new_nm = '' or old_key = lower(new_nm) then
    return null;
  end if;
  if exists (select 1 from public.user_directory d
              where d.id <> new.id and lower(btrim(d.name)) = old_key) then
    return null;
  end if;

  insert into public.engineer_rename_ticket (txid, old_key, new_name)
  values (txid_current(), old_key, new_nm)
  on conflict (txid) do update set old_key = excluded.old_key,
                                   new_name = excluded.new_name, at = now();

  for target in
    select * from (values
      ('field_calls', 'allocated_to'), ('installation_calls', 'allocated_to'), ('pm_calls', 'allocated_to'),
      ('call_requests', 'engineer'), ('pending_registrations', 'engineer'),
      ('spare_requests', 'engineer'), ('spare_dispatches', 'engineer'),
      ('spare_consumption', 'engineer'), ('spare_consumption_history', 'engineer'),
      ('handstock_opening', 'engineer'), ('spare_issue_history', 'engineer'),
      ('material_returns', 'engineer'), ('handstock_adjustments', 'engineer'),
      ('stock_transfers', 'from_engineer'), ('stock_transfers', 'to_engineer'),
      ('parties', 'service_engineer'), ('products', 'service_engineer')
    ) v(tbl, col)
  loop
    if to_regclass('public.' || target.tbl) is not null
       and exists (select 1 from information_schema.columns c
                    where c.table_schema = 'public' and c.table_name = target.tbl
                      and c.column_name = target.col) then
      execute format('update public.%I set %I = $1 where lower(btrim(%I)) = $2',
                     target.tbl, target.col, target.col)
        using new_nm, old_key;
    end if;
  end loop;

  -- An Indoor DC still WAITING for its authoriser follows the rename (D-144):
  -- the approver finds the DC by this name, so without it the DC stays Pending
  -- approval with its units held and nobody able to reach it. A DC already
  -- approved, rejected or issued before approval keeps the name it was printed
  -- with -- who authorised a document is history, as dispatched_by is (0259).
  if to_regclass('public.indoor_dcs') is not null then
    update public.indoor_dcs set authorised_by_name = new_nm
     where lower(btrim(authorised_by_name)) = old_key
       and approval_status = 'Pending approval';
  end if;

  delete from public.engineer_rename_ticket where txid = txid_current();
  return null;
end $$;
revoke execute on function public.user_directory_carry_rename_records() from public, anon, authenticated;

-- ------------------------------------------------------------------------
-- 0122_user_directory_replay_tail.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- user_directory.sql must leave the directory's policies where the schema
-- leaves them.
--
-- 0004 creates `ud_admin_write` — FOR ALL, using is_admin() — and 0008 DROPS
-- it, because rbac replaced it with the narrower ud_read / ud_write pair plus
-- 0030's address rule for dispatch. Since rbac runs after user_directory, a
-- database built from all.sql has no ud_admin_write, which is the intended
-- state; but replaying user_directory.sql on its own put it back, and policies
-- are OR'd, so the narrowing went away with no error and no warning.
--
-- Dropping it again here is 0008's word, applied last. On a fresh apply the
-- policy has just been created a few statements above and is dropped again
-- immediately, which is exactly what all.sql does anyway.
-- ===========================================================================

drop policy if exists ud_admin_write on public.user_directory;

-- ------------------------------------------------------------------------
-- 0005_rbac.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- RBAC — role → allowed actions, editable by admins. The app reads app_roles
-- and enforces can(action) against the signed-in user's profiles.role.
-- ===========================================================================

create table if not exists public.app_roles (
  role        text primary key,
  label       text default '',
  permissions jsonb not null default '[]',   -- array of action keys
  updated_at  timestamptz not null default now()
);

-- Seed the roles (permissions left empty here; the app fills sensible defaults
-- on first save). Admins edit these in Admin → Roles & Permissions.
insert into public.app_roles (role, label) values
  ('admin', 'Admin / Super Admin'),
  ('rgm', 'Regional Manager'),
  ('rm', 'Reporting Manager'),
  ('engineer', 'Engineer'),
  ('hotline', 'Hotline Engineer'),
  ('spare_coordinator', 'Spare Coordinator'),
  ('tally_coordinator', 'Tally Coordinator')
on conflict (role) do nothing;

alter table public.app_roles enable row level security;
drop policy if exists ar_read on public.app_roles;
create policy ar_read on public.app_roles for select using (auth.role() = 'authenticated');
drop policy if exists ar_admin_write on public.app_roles;
create policy ar_admin_write on public.app_roles for all using (public.is_admin()) with check (public.is_admin());

-- Allow assigning any of the seven roles to a profile (text column, no enum).
-- (profiles.role already text; no change needed.)

-- ------------------------------------------------------------------------
-- 0007_user_access.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Per-user access: a user gets their ROLE's permissions plus any extra actions
-- granted directly to them. (profiles.role already exists.)
-- ===========================================================================

alter table public.profiles
  add column if not exists extra_permissions jsonb not null default '[]';

-- profiles already has:
--   profiles_self_read  (self or admin can read)
--   profiles_admin_write (admins can insert/update/delete)
-- so admins can set role + extra_permissions from the User Access screen.

-- ------------------------------------------------------------------------
-- 0008_rbac_enforcement.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- RBAC — server-side enforcement.
--
-- Until now the role → action matrix (app_roles, edited in Admin → Roles &
-- Permissions) was only honoured by the browser: can(action) hid buttons and
-- blocked routes, but Postgres itself let any authenticated user write any
-- row it could reach. Anyone with the anon key and a login could bypass the UI.
--
-- This migration moves the same matrix into the database:
--   * has_perm('<action>') resolves the signed-in user's role against
--     app_roles.permissions — the very rows the admin UI edits.
--   * app_roles is seeded with the app's DEFAULT_PERMS (src/lib/rbac.ts) so
--     the matrix is never empty (an empty matrix would lock everyone out).
--   * every RLS policy that previously said "authenticated" or "is_admin()"
--     now names the action it needs.
--   * spare_requests approval columns are guarded per stage by a trigger,
--     since RLS cannot express "may change these columns only".
--
-- Keep this file in sync with src/lib/rbac.ts when actions/roles change.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- Super admins — the dev/support logins that always hold every right (mirrors
-- SUPER_ADMINS in src/lib/auth.tsx). A table, so it can be edited in SQL
-- without a code deploy.
-- ---------------------------------------------------------------------------
create table if not exists public.app_super_admins (
  email      text primary key,
  created_at timestamptz not null default now()
);
insert into public.app_super_admins (email) values
  ('service.almsind@gmail.com'),
  ('devika.m@airliquide.com'),
  ('devikamunusamy@gmail.com'),
  ('mmdev74@gmail.com')
on conflict (email) do nothing;

alter table public.app_super_admins enable row level security;
drop policy if exists asa_read on public.app_super_admins;
create policy asa_read on public.app_super_admins for select using (public.is_admin());
-- No write policy: the list is maintained in SQL only (service role / SQL editor).

create or replace function public.is_super_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.app_super_admins s where lower(s.email) = lower(coalesce(auth.email(), ''))
  );
$$;

-- Admin = profiles.role 'admin', or a super admin login.
create or replace function public.is_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'
  ) or public.is_super_admin();
$$;

-- The signed-in user's RBAC role key (profiles.role), defaulting to engineer.
create or replace function public.my_role()
returns text language sql stable security definer set search_path = public as $$
  select coalesce(nullif(lower(trim(p.role)), ''), 'engineer')
    from public.profiles p where p.id = auth.uid();
$$;

-- The extra actions granted to this user directly, on top of their role
-- (profiles.extra_permissions — see 0007_user_access.sql).
create or replace function public.my_extra_perms()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(p.extra_permissions, '[]'::jsonb) from public.profiles p where p.id = auth.uid();
$$;

-- Does the signed-in user hold `action`? Admins and super admins hold every
-- action. Otherwise the action must appear in app_roles.permissions for their
-- role, or in their own extra_permissions; a role with no row (or an empty
-- array) falls back to 'engineer' so a half-configured matrix degrades to
-- least privilege rather than lock-out.
create or replace function public.has_perm(action text)
returns boolean language sql stable security definer set search_path = public as $$
  with role_row as (
    select r.permissions from public.app_roles r
     where r.role = public.my_role() and jsonb_array_length(coalesce(r.permissions, '[]'::jsonb)) > 0
  ),
  fallback as (
    select r.permissions from public.app_roles r where r.role = 'engineer'
  ),
  perms as (
    select permissions from role_row
    union all
    select permissions from fallback where not exists (select 1 from role_row)
  )
  select public.is_admin()
      or exists (select 1 from perms p where p.permissions ? action)
      or public.my_extra_perms() ? action;
$$;

grant execute on function public.is_super_admin()  to authenticated;
grant execute on function public.my_role()         to authenticated;
grant execute on function public.my_extra_perms()  to authenticated;
grant execute on function public.has_perm(text)    to authenticated;

-- ---------------------------------------------------------------------------
-- Seed app_roles with the app's starting matrix (src/lib/rbac.ts DEFAULT_PERMS)
-- so enforcement has something to enforce. Roles that already carry a
-- non-empty permission list are left untouched — admin edits win.
-- ---------------------------------------------------------------------------
do $$
declare
  admin_mods text[] := array['mod:/users','mod:/roles','mod:/admin-config'];
  open_mods  text[] := array[
    'mod:/','mod:/daily-review','mod:/parties','mod:/product-master','mod:/user-master',
    'mod:/parts','mod:/warranties','mod:/contracts','mod:/request-registration',
    'mod:/pending-registrations','mod:/field-calls','mod:/installations','mod:/pm-calls',
    'mod:/reports','mod:/spare-requests','mod:/spare-consumption','mod:/feedback',
    'mod:/failure-report','mod:/kpi','mod:/settings','mod:/version-history'];
  all_actions text[] := array[
    'calls.view','calls.create','calls.edit','calls.report','request.create','pending.register',
    'spare.request','spare.approve_rm','spare.approve_commercial','spare.approve_nsm','spare.dispatch',
    'consumption.view','masters.view','masters.edit','reports.view','dashboard.view','feedback.view',
    'users.manage','config.manage','rbac.manage'];
  defs jsonb := jsonb_build_object(
    'admin',             to_jsonb(all_actions || open_mods || admin_mods),
    'nsm',               to_jsonb(array['calls.view','masters.view','consumption.view','reports.view','dashboard.view','feedback.view','spare.approve_nsm'] || open_mods),
    'rgm',               to_jsonb(array['calls.view','calls.create','calls.edit','calls.report','request.create','spare.request','spare.approve_rm','consumption.view','masters.view','reports.view','dashboard.view','feedback.view'] || open_mods),
    'rm',                to_jsonb(array['calls.view','calls.create','calls.edit','calls.report','request.create','spare.request','spare.approve_rm','consumption.view','masters.view','reports.view','dashboard.view','feedback.view'] || open_mods),
    'engineer',          to_jsonb(array['calls.view','calls.report','request.create','spare.request','consumption.view','reports.view','dashboard.view'] || open_mods),
    'hotline',           to_jsonb(array['calls.view','calls.create','request.create','pending.register','spare.approve_rm','masters.view','dashboard.view'] || open_mods),
    'spare_coordinator', to_jsonb(array['calls.view','spare.request','spare.approve_rm','spare.dispatch','consumption.view','reports.view','dashboard.view'] || open_mods),
    'stores_incharge',   to_jsonb(array['calls.view','spare.dispatch','consumption.view','reports.view','dashboard.view'] || open_mods),
    'tally_coordinator', to_jsonb(array['calls.view','consumption.view','reports.view','feedback.view','dashboard.view'] || open_mods),
    'commercial',        to_jsonb(array['calls.view','consumption.view','reports.view','feedback.view','dashboard.view','masters.view','spare.approve_commercial'] || open_mods)
  );
  labels jsonb := jsonb_build_object(
    'admin','Admin / Super Admin', 'nsm','NSM (National Service Manager)', 'rgm','Regional Manager',
    'rm','Reporting Manager', 'engineer','Engineer', 'hotline','Hotline Engineer',
    'spare_coordinator','Spare Coordinator', 'stores_incharge','Stores Incharge',
    'tally_coordinator','Tally Coordinator', 'commercial','Commercial');
  k text;
begin
  for k in select jsonb_object_keys(defs) loop
    insert into public.app_roles (role, label, permissions)
    values (k, labels ->> k, defs -> k)
    on conflict (role) do update
      set label       = coalesce(nullif(public.app_roles.label, ''), excluded.label),
          permissions = case
                          when jsonb_array_length(coalesce(public.app_roles.permissions, '[]'::jsonb)) = 0
                          then excluded.permissions
                          else public.app_roles.permissions
                        end,
          updated_at  = now();
  end loop;
end $$;

-- ===========================================================================
-- Policies — each one now names the action it requires.
-- ===========================================================================

-- profiles: own row always readable; managing users needs users.manage.
drop policy if exists profiles_self_read on public.profiles;
create policy profiles_self_read on public.profiles for select
  using (id = auth.uid() or public.is_admin() or public.has_perm('users.manage'));
drop policy if exists profiles_admin_write on public.profiles;
create policy profiles_admin_write on public.profiles for all
  using (public.has_perm('users.manage')) with check (public.has_perm('users.manage'));

-- Masters & catalog: reference data every signed-in user needs to fill a call
-- in (parties, products, parts, value lists), so reads stay open to any
-- authenticated user; changing a master needs masters.edit.
do $$
declare t text;
begin
  foreach t in array array['parties','products','parts','masters'] loop
    execute format('drop policy if exists %1$s_read on public.%1$s;', t);
    execute format('create policy %1$s_read on public.%1$s for select using (auth.role() = ''authenticated'');', t);
    execute format('drop policy if exists %1$s_admin_write on public.%1$s;', t);
    execute format('drop policy if exists %1$s_write on public.%1$s;', t);
    execute format('create policy %1$s_write on public.%1$s for all using (public.has_perm(''masters.edit'')) with check (public.has_perm(''masters.edit''));', t);
  end loop;
end $$;

-- user_directory: readable by anyone who may see calls (it drives the
-- reporting tree); maintained by user managers.
drop policy if exists ud_read on public.user_directory;
create policy ud_read on public.user_directory for select using (auth.role() = 'authenticated');
drop policy if exists ud_admin_write on public.user_directory;
drop policy if exists ud_write on public.user_directory;
create policy ud_write on public.user_directory for all
  using (public.has_perm('users.manage')) with check (public.has_perm('users.manage'));

-- app_roles: everyone reads the matrix (the client needs it to gate the UI);
-- only rbac.manage may change it.
drop policy if exists ar_read on public.app_roles;
create policy ar_read on public.app_roles for select using (auth.role() = 'authenticated');
drop policy if exists ar_admin_write on public.app_roles;
drop policy if exists ar_write on public.app_roles;
create policy ar_write on public.app_roles for all
  using (public.has_perm('rbac.manage')) with check (public.has_perm('rbac.manage'));

-- calls: the reporting-tree scope still applies, on top of the action.
do $calls_guard$ begin
-- 0040_call_tables_split.sql replaces public.calls with a VIEW over the three
-- typed call tables. What follows is table-only work, so on a project that has
-- already been split it has to be SKIPPED, not attempted — otherwise replaying
-- this file (which re-running any bundle does) dies with
--   ERROR 42809: cannot create index on relation "calls"
-- or "calls is not a table". On an unsplit project it runs exactly as before.
if (select c.relkind from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relname = 'calls') = 'r' then
execute $calls_sql$
drop policy if exists calls_scoped_read on public.calls;
create policy calls_scoped_read on public.calls for select
  using (public.has_perm('calls.view') and public.can_see_call(allocated_to));
drop policy if exists calls_insert on public.calls;
create policy calls_insert on public.calls for insert
  with check (public.has_perm('calls.create'));
drop policy if exists calls_update on public.calls;
create policy calls_update on public.calls for update
  using ((public.has_perm('calls.edit') or public.has_perm('calls.report')) and public.can_see_call(allocated_to))
  with check ((public.has_perm('calls.edit') or public.has_perm('calls.report')) and public.can_see_call(allocated_to));
$calls_sql$;
end if;
end $calls_guard$;

-- pending registrations: Hotline registers them; scope still applies to reads.
drop policy if exists pend_read on public.pending_registrations;
create policy pend_read on public.pending_registrations for select
  using (public.is_admin() or created_by = auth.uid()
    or (public.has_perm('calls.view')
        and lower(trim(engineer)) in (select lower(trim(n)) from public.visible_engineer_names() as v(n))));
drop policy if exists pend_insert on public.pending_registrations;
create policy pend_insert on public.pending_registrations for insert
  with check (public.has_perm('pending.register') or public.has_perm('request.create'));
drop policy if exists pend_update on public.pending_registrations;
create policy pend_update on public.pending_registrations for update
  using (public.has_perm('pending.register') or public.has_perm('calls.create'))
  with check (public.has_perm('pending.register') or public.has_perm('calls.create'));

-- call requests: raising one needs request.create; acting on one needs
-- calls.create (the Hotline/admin who turns it into a call).
drop policy if exists cr_insert on public.call_requests;
create policy cr_insert on public.call_requests for insert
  with check (public.has_perm('request.create'));
drop policy if exists cr_update on public.call_requests;
create policy cr_update on public.call_requests for update
  using (public.has_perm('calls.create') or public.has_perm('pending.register') or created_by = auth.uid())
  with check (public.has_perm('calls.create') or public.has_perm('pending.register') or created_by = auth.uid());

-- reports: visible with the parent call; writing one is calls.report.
drop policy if exists reports_read on public.reports;
create policy reports_read on public.reports for select
  using (public.is_admin() or (public.has_perm('calls.view') and exists (
    select 1 from public.calls c where c.ucn = reports.ucn and public.can_see_call(c.allocated_to))));
drop policy if exists reports_write on public.reports;
create policy reports_write on public.reports for all
  using (public.has_perm('calls.report')) with check (public.has_perm('calls.report'));

-- consumption / feedback.
drop policy if exists cons_read on public.spare_consumption;
create policy cons_read on public.spare_consumption for select using (public.has_perm('consumption.view'));
drop policy if exists cons_write on public.spare_consumption;
create policy cons_write on public.spare_consumption for insert
  with check (public.has_perm('calls.report') or public.has_perm('spare.dispatch'));

drop policy if exists fb_read on public.feedback;
create policy fb_read on public.feedback for select
  using (public.has_perm('feedback.view') or public.has_perm('calls.report'));
drop policy if exists fb_write on public.feedback;
create policy fb_write on public.feedback for insert
  with check (public.has_perm('calls.report') or public.has_perm('feedback.view'));

-- spare requests: raising needs spare.request; reading follows the reporting
-- tree, plus anyone in the approval chain (they must see what they approve).
create or replace function public.can_approve_spares()
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_perm('spare.approve_rm')
      or public.has_perm('spare.approve_commercial')
      or public.has_perm('spare.approve_nsm')
      or public.has_perm('spare.dispatch');
$$;
grant execute on function public.can_approve_spares() to authenticated;

drop policy if exists sr_read on public.spare_requests;
create policy sr_read on public.spare_requests for select
  using (public.is_admin() or created_by = auth.uid() or lower(engineer_email) = lower(auth.email())
    or public.can_approve_spares()
    or lower(trim(engineer)) in (select lower(trim(n)) from public.visible_engineer_names() as v(n)));
drop policy if exists sr_insert on public.spare_requests;
create policy sr_insert on public.spare_requests for insert
  with check (public.has_perm('spare.request'));
drop policy if exists sr_update on public.spare_requests;
create policy sr_update on public.spare_requests for update
  using (public.can_approve_spares() or created_by = auth.uid())
  with check (public.can_approve_spares() or created_by = auth.uid());

-- Request lines: readable with their request; the requester writes their own
-- lines (the app inserts them right after the request), approvers may update.
drop policy if exists srl_read on public.spare_request_lines;
create policy srl_read on public.spare_request_lines for select
  using (exists (select 1 from public.spare_requests r where r.uid = spare_request_lines.request_uid));
drop policy if exists srl_write on public.spare_request_lines;
drop policy if exists srl_insert on public.spare_request_lines;
create policy srl_insert on public.spare_request_lines for insert
  with check (public.has_perm('spare.request') and exists (
    select 1 from public.spare_requests r where r.uid = request_uid
      and (r.created_by = auth.uid() or public.is_admin())));
drop policy if exists srl_update on public.spare_request_lines;
create policy srl_update on public.spare_request_lines for update
  using (public.can_approve_spares()) with check (public.can_approve_spares());

-- ---------------------------------------------------------------------------
-- Approval-stage guard. RLS grants or denies a whole row, so it cannot say
-- "you may set rm_approval but not nsm_approval". This trigger does: each
-- stage's columns may only change if the user holds that stage's action.
-- ---------------------------------------------------------------------------
create or replace function public.spare_requests_stage_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  changed boolean;
begin
  if public.is_admin() then return new; end if;

  changed := new.rm_approval is distinct from old.rm_approval
          or new.rm_by       is distinct from old.rm_by
          or new.rm_at       is distinct from old.rm_at;
  if changed and not public.has_perm('spare.approve_rm') then
    raise exception 'RBAC: RM approval requires the spare.approve_rm permission';
  end if;

  changed := new.commercial_approval is distinct from old.commercial_approval
          or new.commercial_by       is distinct from old.commercial_by
          or new.commercial_at       is distinct from old.commercial_at;
  if changed and not public.has_perm('spare.approve_commercial') then
    raise exception 'RBAC: Commercial approval requires the spare.approve_commercial permission';
  end if;

  changed := new.nsm_approval is distinct from old.nsm_approval
          or new.nsm_by       is distinct from old.nsm_by
          or new.nsm_at       is distinct from old.nsm_at;
  if changed and not public.has_perm('spare.approve_nsm') then
    raise exception 'RBAC: NSM approval requires the spare.approve_nsm permission';
  end if;

  changed := new.stores_status  is distinct from old.stores_status
          or new.dc_number      is distinct from old.dc_number
          or new.dispatched_by  is distinct from old.dispatched_by
          or new.dispatched_at  is distinct from old.dispatched_at;
  if changed and not public.has_perm('spare.dispatch') then
    raise exception 'RBAC: dispatch / DC requires the spare.dispatch permission';
  end if;

  -- The workflow stage itself only moves as a side effect of an approval.
  if new.stage is distinct from old.stage and not public.can_approve_spares() then
    raise exception 'RBAC: advancing the approval stage requires an approval permission';
  end if;

  return new;
end $$;

drop trigger if exists spare_requests_stage_guard on public.spare_requests;
create trigger spare_requests_stage_guard
  before update on public.spare_requests
  for each row execute function public.spare_requests_stage_guard();

-- ---------------------------------------------------------------------------
-- Nobody edits their own role or extra permissions (privilege escalation) —
-- only users.manage may, and never to grant admin unless already an admin.
-- ---------------------------------------------------------------------------
create or replace function public.profiles_role_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.role is distinct from old.role or new.extra_permissions is distinct from old.extra_permissions then
    if new.id = auth.uid() and not public.is_super_admin() then
      raise exception 'RBAC: you cannot change your own role or permissions';
    end if;
  end if;
  if new.role is distinct from old.role
     and lower(new.role) = 'admin' and not public.is_admin() then
    raise exception 'RBAC: granting admin requires an administrator';
  end if;
  return new;
end $$;

drop trigger if exists profiles_role_guard on public.profiles;
create trigger profiles_role_guard
  before update on public.profiles
  for each row execute function public.profiles_role_guard();

-- ------------------------------------------------------------------------
-- 0013_all_masters_module.sql
-- ------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 0013 — All Masters module access.
--
-- The new /masters screen (every master the app reads, with its source, size
-- and values) is gated like any other module by `mod:/masters`. 0008 seeded the
-- role matrix with the modules that existed then and deliberately leaves an
-- existing role's permissions alone, so the new key is on no role. Append it —
-- additively — to every role that can already open a master register
-- (`mod:/parts`), without disturbing any permission an admin has since edited.
-- ---------------------------------------------------------------------------
update public.app_roles
   set permissions = coalesce(permissions, '[]'::jsonb) || '["mod:/masters"]'::jsonb,
       updated_at  = now()
 where coalesce(permissions, '[]'::jsonb) ? 'mod:/parts'
   and not coalesce(permissions, '[]'::jsonb) ? 'mod:/masters';

-- ------------------------------------------------------------------------
-- 0030_engineer_address_write.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Who may set an engineer's delivery address.
--
-- The columns are the User Master's (0029_engineer_address.sql). This is only
-- the rule about writing them, and it ships with RBAC because its policy calls
-- has_perm(), which RBAC defines and which applies after the User Directory.
--
-- Writing them is deliberately NOT admin-only. The person who finds out an
-- address is wrong is the one packing the parcel, so anyone who can dispatch
-- may correct it — and ONLY it: the guard refuses every other column from a
-- non-admin, so the reporting tree (which drives who can see whose calls)
-- cannot be edited through this door.
-- ===========================================================================

create or replace function public.user_directory_address_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if public.is_admin() then return new; end if;
  -- Everything except the four address fields must be identical.
  if new.id                is distinct from old.id
  or new.name              is distinct from old.name
  or new.email             is distinct from old.email
  or new.gmail             is distinct from old.gmail
  or new.designation       is distinct from old.designation
  or new.reporting_manager is distinct from old.reporting_manager
  or new.regional_manager  is distinct from old.regional_manager
  or new.region            is distinct from old.region
  or new.validity          is distinct from old.validity
  or new.extra             is distinct from old.extra then
    raise exception 'Only an administrator may edit the user directory; dispatch may set the address only';
  end if;
  if not public.has_perm('spare.dispatch') then
    raise exception 'RBAC: setting a delivery address requires the spare.dispatch permission';
  end if;
  return new;
end $$;

drop trigger if exists user_directory_address_guard on public.user_directory;
create trigger user_directory_address_guard
  before update on public.user_directory
  for each row execute function public.user_directory_address_guard();

-- The policy lets a dispatcher through; the guard above decides what they may
-- actually change. (0004's ud_admin_write still covers admins for everything.)
drop policy if exists ud_address_update on public.user_directory;
create policy ud_address_update on public.user_directory for update
  using (public.is_admin() or public.has_perm('spare.dispatch'))
  with check (public.is_admin() or public.has_perm('spare.dispatch'));

-- ------------------------------------------------------------------------
-- 0033_user_directory_role.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- The role a User Master row carries, and the profile it becomes.
--
-- Roles live on `profiles`, which only exists once a person has signed in — so
-- until now a new joiner could not be given a role in advance, and someone who
-- had never signed in could not be seen or edited anywhere in the app. The
-- User Master is where people are actually maintained, so the role belongs
-- there too:
--
--   • `user_directory.role` is the role to grant, set by an administrator on
--     the User Master screen.
--   • `ensure_my_profile()` turns that into a real profile the first time the
--     person signs in — name, designation and role taken from their directory
--     row, so they arrive with the access they were given rather than as a
--     bare engineer.
--
-- Changing the role of someone who has already signed in is a `profiles` edit
-- (User Access, or the same screen) — this only decides where a profile starts.
-- ===========================================================================

alter table public.user_directory add column if not exists role text default '';

comment on column public.user_directory.role is
  'RBAC role key (app_roles.role) granted when this person first signs in.';

-- ---------------------------------------------------------------------------
-- The address guard (0030_engineer_address_write.sql) lets a dispatcher fix an
-- address and nothing else. `role` is new, so it has to join the list of
-- columns they must leave alone — otherwise the door meant for an address
-- would hand out permissions.
-- ---------------------------------------------------------------------------
create or replace function public.user_directory_address_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if public.is_admin() then return new; end if;
  -- Everything except the four address fields must be identical.
  if new.id                is distinct from old.id
  or new.name              is distinct from old.name
  or new.email             is distinct from old.email
  or new.gmail             is distinct from old.gmail
  or new.designation       is distinct from old.designation
  or new.reporting_manager is distinct from old.reporting_manager
  or new.regional_manager  is distinct from old.regional_manager
  or new.region            is distinct from old.region
  or new.validity          is distinct from old.validity
  or new.role              is distinct from old.role
  or new.extra             is distinct from old.extra then
    raise exception 'Only an administrator may edit the user directory; dispatch may set the address only';
  end if;
  if not public.has_perm('spare.dispatch') then
    raise exception 'RBAC: setting a delivery address requires the spare.dispatch permission';
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- First sign-in: build the profile from the User Master row.
--
-- Nothing created a `profiles` row, so a person who signed in without one was
-- shown as a bare engineer and never appeared in User Access — invisible to
-- the very screen that assigns roles. This closes that: it runs for the caller
-- only (auth.uid()), and takes the role from their directory row.
--
-- SECURITY DEFINER, so the caller does not need write access to profiles; the
-- role it grants is whatever an administrator put on the directory row, and
-- only if the role matrix actually knows it — a typo grants nothing rather
-- than something unintended.
-- ---------------------------------------------------------------------------
create or replace function public.ensure_my_profile()
returns public.profiles language plpgsql security definer set search_path = public as $$
declare
  me   uuid := auth.uid();
  mail text := lower(coalesce(auth.email(), ''));
  dir  public.user_directory;
  p    public.profiles;
  want text;
begin
  if me is null then return null; end if;

  select * into p from public.profiles where id = me;
  if found then return p; end if;

  select * into dir from public.user_directory
   where lower(email) = mail or lower(gmail) = mail
   limit 1;

  want := nullif(btrim(coalesce(dir.role, '')), '');
  if want is not null and not exists (select 1 from public.app_roles where role = want) then
    want := null;  -- not a role the matrix knows: fall back rather than guess
  end if;

  insert into public.profiles (id, email, full_name, role, designation, active)
  values (
    me,
    coalesce(auth.email(), ''),
    coalesce(nullif(btrim(coalesce(dir.name, '')), ''), coalesce(auth.email(), '')),
    coalesce(want, 'engineer'),
    coalesce(dir.designation, ''),
    coalesce(dir.validity, true)
  )
  on conflict do nothing;   -- id or email already taken: leave what is there

  select * into p from public.profiles where id = me;
  return p;   -- null if the email belongs to another profile; the caller copes
end $$;

revoke all on function public.ensure_my_profile() from public;
grant execute on function public.ensure_my_profile() to authenticated;

-- ------------------------------------------------------------------------
-- 0034_office_roles_see_all.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Office / coordination roles see every call.
-- Hotline, NSM, Commercial, Spare Coordinator, Stores Incharge and Tally
-- Coordinator are not tied to a call's allocation, so they should see all calls
-- (and, through the policies that reuse can_see_call, all reports / spares).
-- Engineers, RMs and RGMs stay scoped to their own / their sub-tree's calls.
-- ===========================================================================

-- True when the signed-in user's role is an office/coordination role (or admin).
create or replace function public.can_view_all_calls()
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_admin() or exists (
    select 1 from public.profiles p
     where p.id = auth.uid()
       and lower(coalesce(p.role, '')) in
           ('hotline', 'nsm', 'commercial', 'spare_coordinator', 'stores_incharge', 'tally_coordinator')
  );
$$;
grant execute on function public.can_view_all_calls() to authenticated;

-- Fold the new bypass into can_see_call (used by calls / reports / spare policies).
create or replace function public.can_see_call(allottee text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.can_view_all_calls()
      or coalesce(allottee, '') = ''
      or lower(trim(allottee)) in (
           select lower(trim(n)) from public.visible_engineer_names() as v(n)
         );
$$;

-- ------------------------------------------------------------------------
-- 0035_data_view_all.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- data.view_all — a per-user (or per-role) grant for FULL data visibility, used
-- by a "Permissions + Data" clone. Folded into the read paths so the holder
-- sees every call, spare request/line, report and consumption row.
-- ===========================================================================

-- Calls / reports (reports read via can_see_call).
create or replace function public.can_view_all_calls()
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_admin()
      or public.has_perm('data.view_all')
      or exists (
        select 1 from public.profiles p
         where p.id = auth.uid()
           and lower(coalesce(p.role, '')) in
               ('hotline', 'nsm', 'commercial', 'spare_coordinator', 'stores_incharge', 'tally_coordinator')
      );
$$;

-- Spare requests (lines read follows the request).
drop policy if exists sr_read on public.spare_requests;
create policy sr_read on public.spare_requests for select
  using (public.is_admin() or public.has_perm('data.view_all') or created_by = auth.uid()
    or lower(engineer_email) = lower(auth.email())
    or public.can_approve_spares()
    or lower(trim(engineer)) in (select lower(trim(n)) from public.visible_engineer_names() as v(n)));

-- Consumption.
drop policy if exists cons_read on public.spare_consumption;
create policy cons_read on public.spare_consumption for select
  using (public.has_perm('consumption.view') or public.has_perm('data.view_all'));

-- ------------------------------------------------------------------------
-- 0037_call_read_scale.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Calls / reports read at scale — stop re-deriving the reporting tree per row.
--
-- can_see_call(allottee) wraps `allottee in (select ... visible_engineer_names())`
-- in a scalar function that takes the per-row allocation as its argument. Because
-- the argument changes per row, the planner treats the whole function as a black
-- box and evaluates it — including the RECURSIVE tree walk inside
-- visible_engineer_names() — once for EVERY call row. At 15–18k PM calls a year
-- (and their reports) that is "canceling statement due to statement timeout" on
-- Pending Calls and Reports. 0014 removed this cost once; 0034 folding the office
-- bypass back through can_see_call reintroduced it.
--
-- The fix is not new logic, only new SHAPE: inline the visibility test into the
-- policy so the tree set is an uncorrelated sub-select — an InitPlan Postgres
-- builds ONCE per query and hash-probes per row — and wrap the no-arg auth
-- helpers in (select …) so they are evaluated once too (the Supabase RLS
-- performance pattern). Same rows are visible to the same people; only the plan
-- changes. can_see_call() itself is left in place for callers not on the hot path.
-- ===========================================================================

-- ---- calls: read + update --------------------------------------------------
do $calls_guard$ begin
-- 0040_call_tables_split.sql replaces public.calls with a VIEW over the three
-- typed call tables. What follows is table-only work, so on a project that has
-- already been split it has to be SKIPPED, not attempted — otherwise replaying
-- this file (which re-running any bundle does) dies with
--   ERROR 42809: cannot create index on relation "calls"
-- or "calls is not a table". On an unsplit project it runs exactly as before.
if (select c.relkind from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relname = 'calls') = 'r' then
execute $calls_sql$
drop policy if exists calls_scoped_read on public.calls;
create policy calls_scoped_read on public.calls for select
  using (
    (select public.has_perm('calls.view'))
    and (
      (select public.can_view_all_calls())
      or created_by = (select auth.uid())
      or coalesce(allocated_to, '') = ''
      or lower(trim(allocated_to)) in (
           select lower(trim(n)) from public.visible_engineer_names() as v(n)
         )
    )
  );

drop policy if exists calls_update on public.calls;
create policy calls_update on public.calls for update
  using (
    (select (public.has_perm('calls.edit') or public.has_perm('calls.report')))
    and (
      (select public.can_view_all_calls())
      or created_by = (select auth.uid())
      or coalesce(allocated_to, '') = ''
      or lower(trim(allocated_to)) in (
           select lower(trim(n)) from public.visible_engineer_names() as v(n)
         )
    )
  )
  with check (
    (select (public.has_perm('calls.edit') or public.has_perm('calls.report')))
    and (
      (select public.can_view_all_calls())
      or created_by = (select auth.uid())
      or coalesce(allocated_to, '') = ''
      or lower(trim(allocated_to)) in (
           select lower(trim(n)) from public.visible_engineer_names() as v(n)
         )
    )
  );
$calls_sql$;
end if;
end $calls_guard$;-- ---- reports: read (visible with the parent call) --------------------------
-- The recursive set is uncorrelated, so it stays an InitPlan (once); the only
-- per-report work is the indexed lookup of its call by ucn.
drop policy if exists reports_read on public.reports;
create policy reports_read on public.reports for select
  using (
    (select public.is_admin())
    or (
      (select public.has_perm('calls.view'))
      and (
        (select public.can_view_all_calls())
        or exists (
          select 1 from public.calls c
           where c.ucn = reports.ucn
             and (
               coalesce(c.allocated_to, '') = ''
               or lower(trim(c.allocated_to)) in (
                    select lower(trim(n)) from public.visible_engineer_names() as v(n)
                  )
             )
        )
      )
    )
  );

-- ------------------------------------------------------------------------
-- 0051_pending_registrations_view_all.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Hotline (and the office roles) must see the WHOLE pending-registration queue,
-- not just their own requests — that queue is the Hotline's work: map each to a
-- call, register a new one, or cancel it. The pend_read policy (0008) only let a
-- user see their own rows or an engineer in their reporting sub-tree, so a
-- Hotline engineer (who has no sub-tree) saw almost none.
--
-- Fold in can_view_all_calls() (0035) — is_admin, data.view_all, and the roles
-- hotline / nsm / commercial / spare_coordinator / stores_incharge /
-- tally_coordinator — exactly as the call register already does. The whole call
-- register is already visible to those roles (0037 / 0040); this brings the
-- pending queue in line.
-- ===========================================================================

drop policy if exists pend_read on public.pending_registrations;
create policy pend_read on public.pending_registrations for select
  using (
    public.can_view_all_calls()              -- admin, data.view_all, Hotline + office roles: the whole queue
    or created_by = auth.uid()               -- your own requests
    or (public.has_perm('calls.view')        -- a manager: requests for an engineer in their reporting sub-tree
        and lower(trim(engineer)) in (select lower(trim(n)) from public.visible_engineer_names() as v(n)))
  );

-- ------------------------------------------------------------------------
-- 0069_nsm_service_manager.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- NSM is the National SERVICE Manager, not the National Sales Manager.
--
-- 0008 seeded the label, and its upsert deliberately keeps a label an admin has
-- already set (`coalesce(nullif(existing.label,''), excluded.label)`) — so
-- correcting the seed does nothing to a project where the row already exists.
-- This corrects the stored label in place, and ONLY that exact wording, so a
-- name an admin chose themselves is left alone.
-- ===========================================================================

do $$
begin
  if to_regclass('public.app_roles') is null then
    raise notice 'public.app_roles is not present — run the rbac bundle first';
    return;
  end if;

  update public.app_roles
     set label = 'NSM (National Service Manager)', updated_at = now()
   where role = 'nsm'
     and label = 'NSM (National Sales Manager)';
end $$;

-- ------------------------------------------------------------------------
-- 0093_lookup_module.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- The Product & Party Search screen, for whoever already has the Product Master.
--
-- A new module is in the code's defaults, but `has_perm` reads the STORED list
-- on `app_roles` and only falls back to those defaults when the row is empty —
-- so a role that has ever been saved in Roles & Permissions would not see the
-- screen at all. Granted here, by MERGING, so an administrator's other edits
-- are untouched.
--
-- The rule is simple: it reads exactly what Product Master reads — the install
-- base and the party it belongs to — from the other end. Anyone who may open
-- one may open the other. No new data is exposed, and row-level security
-- answers for the rows either way.
-- ===========================================================================

update public.app_roles
   set permissions = coalesce(permissions, '[]'::jsonb) || '["mod:/lookup"]'::jsonb,
       updated_at  = now()
 where (role = 'admin' or coalesce(permissions, '[]'::jsonb) ? 'mod:/product-master')
   and not coalesce(permissions, '[]'::jsonb) ? 'mod:/lookup';

-- ------------------------------------------------------------------------
-- 0110_admin_reset_password.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- AN ADMINISTRATOR CAN RESET A FORGOTTEN PASSWORD.
--
-- The sign-in page now says "ask an administrator" (v0.9.89), and until this
-- there was nothing for the administrator to do — they had to go to the
-- Supabase dashboard. This gives them the action in the app: a random password
-- is generated, set on the account, and shown ONCE so it can be passed to the
-- person, who changes it under Profile → Password whenever they like.
--
-- WHY IT WRITES `auth.users` DIRECTLY, AND WHAT THAT COSTS.
-- Setting somebody ELSE'S password is an admin-API operation, and the admin API
-- needs the service_role key — which must never be in a browser, so the app
-- cannot call it. The two honest options were an Edge Function holding that key
-- or a definer function here. This project delivers everything as a migration
-- the user runs, and an admin action that fails until an Edge Function is
-- deployed is an admin action that does not work. So: here, as SECURITY
-- DEFINER, writing the same bcrypt hash Supabase's own reset writes.
--
-- It is off the supported path, and these are the limits:
--   • it does not run Supabase's own password policy — the length floor below
--     is the only rule, and the generator makes far longer ones;
--   • it does not send anything. The administrator passes the password on;
--   • if Supabase ever changes how it stores passwords this stops working, and
--     it stops LOUDLY (the person cannot sign in), not silently.
--
-- WHAT IT REFUSES:
--   • anyone who is not an administrator;
--   • a super admin's account, unless the caller is a super admin. An admin who
--     could reset a super admin's password could take the project;
--   • a password under 10 characters, so this cannot be used to set a weak one.
--
-- THE PASSWORD IS NEVER STORED. `password_resets` records WHO reset WHOSE
-- account and when — the fact of it, which is what an audit needs — and nothing
-- that could be used to sign in.
--
-- Every session the person had is ended, so a reset actually takes effect
-- everywhere rather than leaving an old phone signed in.
-- ===========================================================================

create extension if not exists pgcrypto;

create table if not exists public.password_resets (
  id             bigint generated always as identity primary key,
  target_email   text not null,
  target_id      uuid,
  reset_by       uuid,
  reset_by_email text not null default '',
  reset_at       timestamptz not null default now()
);
create index if not exists password_resets_at_idx on public.password_resets (reset_at desc);

alter table public.password_resets enable row level security;
-- Readable by administrators, written only by the function below (which is
-- definer, so it is not subject to this).
drop policy if exists pwr_read on public.password_resets;
create policy pwr_read on public.password_resets for select using (public.is_admin());

create or replace function public.admin_reset_password(p_email text, p_password text)
returns text language plpgsql security definer
set search_path = public, extensions, auth as $$
declare v_id uuid; v_email text; v_target_super boolean;
begin
  if not public.is_admin() then
    raise exception 'RBAC: only an administrator can reset a password';
  end if;
  -- The generator makes 14; this floor is here so the function cannot be used
  -- to set something weak by hand.
  if length(coalesce(p_password, '')) < 10 then
    raise exception 'A reset password must be at least 10 characters';
  end if;

  v_email := lower(btrim(coalesce(p_email, '')));
  select u.id into v_id from auth.users u where lower(u.email) = v_email;
  if v_id is null then raise exception 'No login for %', p_email; end if;

  select exists (select 1 from public.app_super_admins s where lower(s.email) = v_email)
    into v_target_super;
  if v_target_super and not public.is_super_admin() then
    raise exception 'Only a super admin can reset a super admin''s password';
  end if;

  update auth.users
     set encrypted_password = crypt(p_password, gen_salt('bf')),
         updated_at         = now()
   where id = v_id;

  -- End what they had open, so the reset takes effect on every device rather
  -- than leaving an old session signed in. Both tables are Supabase's own and
  -- absent from a bare Postgres, so neither is allowed to fail the reset.
  begin
    delete from auth.sessions where user_id = v_id;
  exception when others then null;
  end;
  begin
    delete from auth.refresh_tokens where user_id::text = v_id::text;
  exception when others then null;
  end;

  insert into public.password_resets (target_email, target_id, reset_by, reset_by_email)
  values (v_email, v_id, auth.uid(), coalesce(auth.email(), ''));

  return v_email;
end $$;
revoke all on function public.admin_reset_password(text, text) from public;
grant execute on function public.admin_reset_password(text, text) to authenticated;

-- ------------------------------------------------------------------------
-- 0120_role_table_views.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A TABLE'S LAYOUT, SET FOR A ROLE.
--
-- The user's ask (2026-09-06): "like save for everyone, I need option to set
-- the views to roles."
--
-- What a register looks like — which columns, in what order, how wide, grouped
-- by what, filtered how — is currently each person's own, kept in their
-- browser. There is also a "default for everyone", but it goes through the
-- Apps Script sheet bridge, it is all-or-nothing, and it carries only the
-- columns: not the grouping, not the filters. Nobody can say "this is how the
-- Stores In-charge should see Pending Dispatch".
--
-- So: one row per (register, role), holding the whole layout. A role of '' is
-- EVERYONE — the same table answers both questions rather than one mechanism
-- for roles and a different one for all, which would drift.
--
-- WHOSE LAYOUT WINS. The same rule as the Auto Save default, and for the same
-- reason: both the reader's own arrangement and the administrator's carry a
-- TIME, and the later decision stands. "The admin always wins" would make
-- every reader's column picker a lie; "your own always wins" would make
-- "apply to a role" a lie. `set_at` is what the client compares against.
--
-- ADMIN-ONLY WRITE, everyone reads. A layout is not sensitive — it says which
-- columns to show, not what is in them — and RLS on the underlying registers
-- is what decides the rows either way.
-- ===========================================================================

create table if not exists public.role_table_views (
  storage_key text        not null,
  role        text        not null default '',     -- '' = everyone
  view        jsonb       not null default '{}'::jsonb,
  set_at      bigint      not null default (extract(epoch from now()) * 1000)::bigint,
  updated_at  timestamptz not null default now(),
  updated_by  uuid        references auth.users (id),
  primary key (storage_key, role)
);

comment on table public.role_table_views is
  'How a register looks for a role: columns, order, widths, grouping, filters. role = '''' means everyone. set_at is compared against the reader''s own arrangement — the later decision wins.';

alter table public.role_table_views enable row level security;
grant select on public.role_table_views to authenticated;
revoke insert, update, delete on public.role_table_views from authenticated;

drop policy if exists rtv_read on public.role_table_views;
create policy rtv_read on public.role_table_views for select
  using (auth.role() = 'authenticated');

-- Writes go through the function below, so the rule about WHO can set a
-- layout lives in one place and `set_at` cannot be back-dated by a caller.
drop policy if exists rtv_write on public.role_table_views;
create policy rtv_write on public.role_table_views for all
  using (public.is_admin() or public.has_perm('config.manage'))
  with check (public.is_admin() or public.has_perm('config.manage'));

create or replace function public.set_role_table_view(
  p_storage_key text, p_role text, p_view jsonb
) returns bigint
language plpgsql security definer set search_path = public as $$
declare v_at bigint := (extract(epoch from now()) * 1000)::bigint;
begin
  if not (public.is_admin() or public.has_perm('config.manage')) then
    raise exception 'RBAC: only an administrator can set a layout for a role';
  end if;
  if coalesce(btrim(p_storage_key), '') = '' then
    raise exception 'Which register?';
  end if;

  insert into public.role_table_views (storage_key, role, view, set_at, updated_at, updated_by)
  values (btrim(p_storage_key), coalesce(btrim(p_role), ''), coalesce(p_view, '{}'::jsonb), v_at, now(), auth.uid())
  on conflict (storage_key, role) do update
     set view = excluded.view, set_at = excluded.set_at,
         updated_at = excluded.updated_at, updated_by = excluded.updated_by;

  return v_at;
end $$;
revoke all on function public.set_role_table_view(text, text, jsonb) from public;
grant execute on function public.set_role_table_view(text, text, jsonb) to authenticated;

-- Clearing one is a decision too, and it must be possible without inventing an
-- "empty layout" that would read as "show no columns".
create or replace function public.clear_role_table_view(p_storage_key text, p_role text)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not (public.is_admin() or public.has_perm('config.manage')) then
    raise exception 'RBAC: only an administrator can clear a layout for a role';
  end if;
  delete from public.role_table_views
   where storage_key = btrim(p_storage_key) and role = coalesce(btrim(p_role), '');
  return found;
end $$;
revoke all on function public.clear_role_table_view(text, text) from public;
grant execute on function public.clear_role_table_view(text, text) to authenticated;

-- WHICH LAYOUT APPLIES TO THE CALLER: the one set for their role, and failing
-- that the one set for everyone. Resolved in the database so every register
-- asks the question the same way and a role name is never matched in the
-- browser against a role the browser only thinks it has.
create or replace function public.my_table_view(p_storage_key text)
returns table (view jsonb, set_at bigint, role text)
language sql stable security definer set search_path = public as $$
  select v.view, v.set_at, v.role
    from public.role_table_views v
   where v.storage_key = btrim(p_storage_key)
     and (v.role = '' or v.role = coalesce(public.my_role(), ''))
   order by (v.role <> '') desc      -- the role's own beats the everyone one
   limit 1
$$;
revoke all on function public.my_table_view(text) from public;
grant execute on function public.my_table_view(text) to authenticated;

-- ------------------------------------------------------------------------
-- 0192_product_database_rename.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0192 — "PRODUCT MASTER" BECOMES "PRODUCT DATABASE", and the name is freed.
--
-- The user, 2026-09-14: "Rename Product Master to Product Database -- Deep dive
-- and Rename all instances." and, in the same breath, "Add a Separate Product
-- Master - Which is the Actual List of Product Lines".
--
-- So the two things swap names, and that is the whole difficulty:
--
--   `public.products`   the INSTALL BASE — one row per MACHINE, by model and
--                       serial, with its customer and its cover. Now labelled
--                       PRODUCT DATABASE, route /product-database.
--   (next migration)    the CATALOGUE — one row per PRODUCT LINE, with its
--                       code, type, category and whether it is still sold.
--                       That is the new PRODUCT MASTER.
--
-- THE TABLE IS NOT RENAMED. `products` is referenced by 24 views, a dozen
-- functions and every screen; renaming it would be a day's work with nothing
-- gained, because the NAME the user reads comes from the module label and not
-- from the table. What this file does is move the PERMISSION.
--
-- WHY THE PERMISSION HAS TO MOVE, and why it cannot simply be left alone:
-- the module key IS the route (`mod:/product-master`). If the new catalogue
-- took that route — which is the obvious thing to do, since it is now the
-- Product Master — then every role holding that key would SILENTLY STOP seeing
-- the install base and START seeing the catalogue. Same key, different screen,
-- no error and nothing on screen to explain it.
--
-- So the install base moves to `mod:/product-database` and KEEPS ITS AUDIENCE:
-- every role that could open it before can open it now. The catalogue's key is
-- NEW and is granted deliberately below, to the roles that maintain masters —
-- not inherited by accident from a key that used to mean something else.
--
-- MERGED, NEVER OVERWRITTEN (the standing rule): `has_perm` falls back to the
-- engineer defaults only when a role's permissions are EMPTY, so writing one
-- key into a role would turn that fallback off and leave it holding one thing.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- 1. THE INSTALL BASE KEEPS ITS AUDIENCE under the new key.
-- ---------------------------------------------------------------------------
update public.app_roles ar
   set permissions = (
         select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
           from (
             select jsonb_array_elements_text(ar.permissions) as v
             union
             select 'mod:/product-database' as v
           ) u
       ),
       updated_at = now()
 where ar.permissions ? 'mod:/product-master'
   and not (ar.permissions ? 'mod:/product-database');

-- ---------------------------------------------------------------------------
-- 2. THE OLD KEY IS LEFT IN PLACE, deliberately.
--
-- It now means the CATALOGUE, and section 3 decides who gets that. Removing it
-- here would be the same silent change in the other direction — a role losing
-- something between one deploy and the next with nothing said. An
-- administrator who does not want a role reading the catalogue unticks it on
-- Roles & Permissions, where the change is visible and theirs.
--
-- The ones that keep it are the roles that maintain masters, which is what the
-- catalogue is. Every other role holding it will see a screen it did not have
-- before, and that is the one consequence worth stating out loud rather than
-- burying: the catalogue is a READ-ONLY LIST OF PRODUCT LINES. It carries no
-- customer, no serial and no cover, so nothing confidential moves with it.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 3. AND THE ROLES THAT MAINTAIN MASTERS GET THE CATALOGUE EXPLICITLY, so it
--    is granted rather than merely left over.
-- ---------------------------------------------------------------------------
update public.app_roles ar
   set permissions = (
         select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
           from (
             select jsonb_array_elements_text(ar.permissions) as v
             union
             select 'mod:/product-master' as v
           ) u
       ),
       updated_at = now()
 where ar.permissions ? 'masters.view'
   and not (ar.permissions ? 'mod:/product-master');

do $$
declare n int;
begin
  select count(*) into n from public.app_roles where permissions ? 'mod:/product-database';
  raise notice '0192: % role(s) can open the Product Database (the install base) under its new key', n;
  select count(*) into n from public.app_roles where permissions ? 'mod:/product-master';
  raise notice '0192: % role(s) can open the Product Master (the product lines)', n;
end $$;

-- ------------------------------------------------------------------------
-- 0195_new_module_keys.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0195 — THE MODULE KEYS THAT SHIPPED WITHOUT BEING GRANTED.
--
-- The user, 2026-09-14: "Update the Roles & Permissions - Always when a New UI
-- is introduced or when a UI is re-arranged -- This is often missed."
--
-- It was missed, three times, and this file is the repair. Found by asking the
-- code rather than by reading the backlog:
--
--   mod:/machine-history     0 migrations.  12 roles hold it in DEFAULT_PERMS.
--   mod:/exports/calls       0 migrations.  12 roles hold it in DEFAULT_PERMS.
--   mod:/exports/feedback    0 migrations.  12 roles hold it in DEFAULT_PERMS.
--
-- WHY A CODE DEFAULT IS NOT ENOUGH, and this is the whole point of the file.
-- `permsForRole()` is
--
--     if (stored && stored.length) return stored;      // the app_roles row
--     return DEFAULT_PERMS[role] ?? DEFAULT_PERMS.engineer;
--
-- so the defaults apply ONLY to a role whose stored set is EMPTY. On a project
-- that has been in use every role has a tuned row, so a new module's key
-- reaches nobody until a migration puts it there. The screen ships, the menu
-- entry exists in the code, the permission is ticked in DEFAULT_PERMS — and the
-- page is invisible to all twelve roles. That is the "a role that sees NOTHING"
-- fault in CLAUDE.md arriving through the front door.
--
-- MACHINE HISTORY IS THE SEVERE ONE: it has no parent key, so nothing covered
-- for it. The two reports were partly saved by `parentAction()`, which makes
-- `mod:/exports` stand in for every `mod:/exports/*` — but only for a role
-- holding the parent. 0155 gave `zoho_migration` the report sub-pages ONE BY
-- ONE ('mod:/exports/consumption','mod:/exports/kpi','mod:/exports/unused'),
-- and a list written out in full is a list that goes stale: the two reports
-- added on 2026-09-14 are not in it, so that role's matrix shows them unticked.
--
-- GRANTED TO EXACTLY THE ROLES THAT HOLD THEM IN CODE — all twelve — so this
-- widens nothing: it makes the database say what the application already says.
--
-- MERGED, NEVER OVERWRITTEN (CLAUDE.md): an administrator may have tuned the
-- role, and overwriting would throw that away.
--
-- A ROLE WITH NO PERMISSIONS AT ALL IS LEFT ALONE, and deliberately: an empty
-- array means "not configured" and the code falls back to the defaults, which
-- already contain these keys. Writing one key into it would turn that fallback
-- OFF and leave the role holding three permissions and nothing else. 0176 made
-- the same decision for `ffr.view`, for the same reason.
-- ===========================================================================

do $$
declare n int;
begin
  if to_regclass('public.app_roles') is null then return; end if;

  update public.app_roles ar
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (
               select jsonb_array_elements_text(ar.permissions) as v
               union
               select unnest(array[
                 'mod:/machine-history',
                 'mod:/exports/calls',
                 'mod:/exports/feedback'
               ]) as v
             ) u
         ),
         updated_at = now()
   -- ONLY a role that is actually configured, and only one still missing at
   -- least one of the three — so a re-run changes nothing.
   where jsonb_array_length(ar.permissions) > 0
     and not (ar.permissions ?& array['mod:/machine-history',
                                      'mod:/exports/calls',
                                      'mod:/exports/feedback']);
  get diagnostics n = row_count;
  raise notice '0195: % role(s) given the module keys that shipped without them', n;
end $$;

-- ------------------------------------------------------------------------
-- 0202_workload_module_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- MY WORKLOAD REACHES THE ROLES THAT ALREADY OPEN THE REGISTERS.
--
-- The user, 2026-09-15: "Remove such cards in Main Views. Move those to a
-- Separate KPI Cards Page where ever applicable."
--
-- A NEW SCREEN IS NOT DONE UNTIL ROLES & PERMISSIONS KNOWS (the standing rule,
-- and it had been missed four times before 0195). `permsForRole()` is
--
--     if (stored && stored.length) return stored;      // the app_roles row
--     return DEFAULT_PERMS[role] ?? DEFAULT_PERMS.engineer;
--
-- so a code default reaches ONLY a role whose stored set is empty, and on a
-- project in use every role has a tuned row. Without this file the page ships,
-- the menu entry exists, the permission is ticked in DEFAULT_PERMS — and the
-- screen is invisible to every role, with no error anywhere. `check:ui` caught
-- exactly that on the first build of this screen, which is what it is for.
--
-- IT GRANTS NO REACH. The page holds NO authority of its own: it shows a
-- register's section only where the reader already holds that register's key,
-- and a section they cannot open is never even requested — so a queue they may
-- not read is never counted at them. "Spares waiting 240" would otherwise tell
-- somebody the size of a queue the register itself would refuse to show them.
-- So every role gets the key, and what each of them SEES on it is decided
-- entirely by what they already had.
--
-- MERGED, NEVER OVERWRITTEN: an administrator may have tuned the role.
--
-- A ROLE WITH NO PERMISSIONS AT ALL IS LEFT ALONE. An empty array means "not
-- configured" and the code falls back to the defaults, which already carry this
-- key; writing one key into it would turn that fallback OFF and leave the role
-- holding exactly one permission.
-- ===========================================================================

do $$
declare n int;
begin
  if to_regclass('public.app_roles') is null then return; end if;

  update public.app_roles ar
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (
               select jsonb_array_elements_text(ar.permissions) as v
               union
               select unnest(array['mod:/workload']) as v
             ) u
         ),
         updated_at = now()
   where jsonb_array_length(ar.permissions) > 0
     and not (ar.permissions ? 'mod:/workload');
  get diagnostics n = row_count;
  raise notice '0202: % role(s) given mod:/workload', n;
end $$;

-- ------------------------------------------------------------------------
-- 0204_dccr_insights_module_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- DAILY CALL REVIEW INSIGHTS REACHES THE ROLES THAT ALREADY READ THE REVIEWS.
--
-- The user, 2026-09-15: "In the Overview heading - Add one more analytics page
-- to analyse all the data that is part of the daily call review."
--
-- A NEW SCREEN IS NOT DONE UNTIL ROLES & PERMISSIONS KNOWS. `permsForRole()`
-- returns the STORED set whenever it is non-empty, so a code default reaches
-- only a role whose row is empty — and on a project in use every role has a
-- tuned row. Without this the page ships, the menu entry exists, the permission
-- is ticked in DEFAULT_PERMS, and the screen is invisible to every role with no
-- error anywhere. That happened four times before 0195.
--
-- IT GRANTS NO REACH. The page holds no authority of its own: it reads
-- `field_call_review`, which `call_reviews_read` already opens to any signed-in
-- user, and it writes nothing. What each role SEES is decided by the row-level
-- security on the calls underneath, exactly as on the register.
--
-- MERGED, NEVER OVERWRITTEN, and a role with ZERO permissions is left alone —
-- an empty array means "not configured" and writing one key into it would turn
-- that fallback off.
-- ===========================================================================

do $$
declare n int;
begin
  if to_regclass('public.app_roles') is null then return; end if;

  update public.app_roles ar
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (
               select jsonb_array_elements_text(ar.permissions) as v
               union
               select unnest(array['mod:/dccr-insights']) as v
             ) u
         ),
         updated_at = now()
   where jsonb_array_length(ar.permissions) > 0
     and not (ar.permissions ? 'mod:/dccr-insights');
  get diagnostics n = row_count;
  raise notice '0204: % role(s) given mod:/dccr-insights', n;
end $$;

-- ------------------------------------------------------------------------
-- 0205_product_failure_module_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE SCREEN WAS RENAMED, AND THE MODULE KEY IS THE ROUTE.
--
-- The user, 2026-09-15: "Rename it as Product Failure analysis." It shipped
-- yesterday as Daily Call Review Insights at `/dccr-insights`; it is now
-- Product Failure Analysis at `/product-failure`.
--
-- A RE-ARRANGED UI IS NOT DONE UNTIL ROLES & PERMISSIONS KNOWS — the standing
-- rule, and a RENAME is the case that hides it best, because the screen is
-- already working for everybody. `permsForRole()` returns the stored set
-- whenever it is non-empty, so the moment the route changed, every role's
-- `mod:/dccr-insights` stopped opening anything and the page went invisible to
-- all of them with no error anywhere.
--
-- IT MERGES THE NEW KEY INTO EVERY CONFIGURED ROLE, exactly as 0204 granted the
-- old one, so nobody loses the screen across the rename.
--
-- THE OLD KEY IS LEFT IN PLACE, and that is deliberate rather than untidy.
-- Removing it would be a second write for no gain: it now names a route that
-- does not exist, so it grants nothing, and `check:ui` ignores a key with no
-- module. Stripping it would also make this migration destructive on a project
-- where an administrator had tuned that row — and 0192 is the precedent for
-- MERGING a renamed module's key rather than swapping it.
--
-- A ROLE WITH ZERO PERMISSIONS IS LEFT ALONE: an empty array means "not
-- configured" and the code falls back to the defaults, which carry the new key.
-- ===========================================================================

do $$
declare n int;
begin
  if to_regclass('public.app_roles') is null then return; end if;

  update public.app_roles ar
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (
               select jsonb_array_elements_text(ar.permissions) as v
               union
               select unnest(array['mod:/product-failure']) as v
             ) u
         ),
         updated_at = now()
   where jsonb_array_length(ar.permissions) > 0
     and not (ar.permissions ? 'mod:/product-failure');
  get diagnostics n = row_count;
  raise notice '0205: % role(s) given mod:/product-failure (renamed from mod:/dccr-insights)', n;
end $$;

-- ------------------------------------------------------------------------
-- 0206_saved_charts.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A CHART SOMEBODY BUILDS, AND KEEPS.
--
-- The user, 2026-09-15: "Add a provision to create a chart by myself and save
-- it." Asked earlier in the same session whether it could be saved "for
-- Everyone or for Specific roles" — so scope is part of the feature, not an
-- afterthought.
--
-- MODELLED ON `role_table_views` (0120) DELIBERATELY. That table already
-- answers "this configuration belongs to a role, or to everyone" for register
-- layouts, and a second answer to the same question would be a second set of
-- rules to keep in step. Same columns, same `set_at`, same admin-only rule for
-- anything shared.
--
-- THREE SCOPES, and the difference is who else is affected:
--   • MINE      owner = the person, role is NULL. Anybody may make one; nobody
--               else sees it.
--   • A ROLE    role = the role key. Changes what a group of people see.
--   • EVERYONE  role = ''. Same, for all of them.
-- The last two need `config.manage` or an administrator — the same authority
-- 0120 requires to set a layout for a role, because it is the same act.
--
-- A CHART IS NOT SENSITIVE AND ITS DATA IS NOT IN IT. The row holds a
-- DIMENSION and a chart type: "count the failures by root cause, as a Pareto".
-- The numbers are computed in the reader's own session from rows their own RLS
-- allowed, so a chart shared with somebody who may see less simply shows less.
-- Sharing a chart can never share data.
--
-- THE SPEC IS VALIDATED WHERE IT IS USED, NOT HERE. A jsonb column cannot
-- usefully constrain "dimension must be a column of field_call_review" — the
-- view's shape changes with migrations, and a CHECK that went stale would
-- refuse a chart that is fine. The page ignores a dimension it does not know
-- and says so, which is the failure that can be seen and corrected.
-- ===========================================================================

create table if not exists public.saved_charts (
  id          bigint generated always as identity primary key,
  page        text        not null,                -- which analysis page it belongs to
  name        text        not null,
  role        text,                                -- NULL = private to `owner`; '' = everyone
  owner       uuid        references auth.users (id),
  spec        jsonb       not null default '{}'::jsonb,
  set_at      bigint      not null default (extract(epoch from now()) * 1000)::bigint,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  updated_by  uuid        references auth.users (id)
);

comment on table public.saved_charts is
  'A chart somebody built and kept. role NULL = private to owner; '''' = everyone; otherwise that role key. The spec holds a dimension and a chart type — never data.';

-- A PERSON CANNOT HAVE TWO CHARTS OF THE SAME NAME ON THE SAME PAGE, and a
-- role cannot either. Partial, because `role` is NULL for a private chart and
-- NULL is not equal to itself: one index per shape, or a private chart and a
-- shared one of the same name would collide with each other.
create unique index if not exists saved_charts_mine_uniq
  on public.saved_charts (page, owner, name) where role is null;
create unique index if not exists saved_charts_shared_uniq
  on public.saved_charts (page, role, name) where role is not null;

create index if not exists saved_charts_page_idx on public.saved_charts (page);

alter table public.saved_charts enable row level security;
grant select, insert, update, delete on public.saved_charts to authenticated;
grant usage, select on all sequences in schema public to authenticated;

-- READ: your own, plus anything shared with everyone or with your role.
drop policy if exists sc_read on public.saved_charts;
create policy sc_read on public.saved_charts for select
  using (
    (role is null and owner = auth.uid())
    or role = ''
    or role = public.my_role()
  );

-- WRITE YOUR OWN. `owner = auth.uid()` on both sides, so nobody can create a
-- chart in somebody else's name or move one to them.
drop policy if exists sc_write_mine on public.saved_charts;
create policy sc_write_mine on public.saved_charts for all
  using (role is null and owner = auth.uid())
  with check (role is null and owner = auth.uid());

-- WRITE A SHARED ONE — the same authority 0120 requires to set a register
-- layout for a role, because it is the same act: deciding what a group of
-- people see when they open a screen.
drop policy if exists sc_write_shared on public.saved_charts;
create policy sc_write_shared on public.saved_charts for all
  using (role is not null and (public.is_admin() or public.has_perm('config.manage')))
  with check (role is not null and (public.is_admin() or public.has_perm('config.manage')));

-- WHO SAVED IT IS THE DATABASE'S TO RECORD, not the caller's — 0113's rule for
-- who registered a call, and for the same reason: a caller-supplied author is
-- a name anybody can type. `owner` is stamped on a PRIVATE chart so it cannot
-- be filed against somebody else even by a caller that means well.
create or replace function public.saved_charts_stamp()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.updated_at := now();
  new.updated_by := auth.uid();
  if new.role is null then new.owner := auth.uid(); end if;
  if tg_op = 'UPDATE' then
    new.created_at := old.created_at;
    -- `set_at` moves on every write: it is what the reader compares when the
    -- same chart exists both privately and for their role — the later decision
    -- stands, which is 0120's rule and the Auto Save rule before it.
    new.set_at := (extract(epoch from now()) * 1000)::bigint;
  end if;
  return new;
end $$;

drop trigger if exists saved_charts_stamp on public.saved_charts;
create trigger saved_charts_stamp
  before insert or update on public.saved_charts
  for each row execute function public.saved_charts_stamp();

-- ------------------------------------------------------------------------
-- 0207_analysis_roles_see_the_data.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE TWO ANALYSIS ROLES COULD OPEN THE ANALYTICS PAGES AND SEE NOTHING ON
-- THEM.
--
-- Reported from use (the user, 2026-09-15): "Spare Insights is blank for
-- VPTechnical Role", and then "Product Failure Analysis is also Blank for
-- VpTechnical." Both pages were in the menu, both opened, both showed zeros.
--
-- THE MODULE KEY OPENS A SCREEN; IT DOES NOT SHOW THE ROWS. That is the whole
-- of this bug, and it is the failure mode the standing rule about Roles &
-- Permissions does not cover — the screen was granted correctly and the
-- database still answered with nothing:
--
--   * PRODUCT FAILURE ANALYSIS reads `field_call_review`, and although
--     `call_reviews_read` (0044) opens the review table to any signed-in user,
--     the VIEW is built `from public.field_calls` — so what a reader sees is
--     bounded by the CALL policies, which are
--     `has_perm('calls.view') AND <visibility>`. A role holding neither sees
--     no calls, therefore no reviews, therefore an empty chart.
--   * SPARE INSIGHTS reads `spare_consumption`, whose `cons_read` (0038) is
--     `can_view_all_calls() OR mine OR my team's`. An analysis role raises no
--     consumption and has no reporting team, so every branch is false.
--
-- `can_view_all_calls()` (0035) names the OFFICE roles literally — hotline,
-- nsm, commercial, spare_coordinator, stores_incharge, tally_coordinator — and
-- neither of these is one. The per-role grant built for exactly this case is
-- `data.view_all`, so that is what they are given, together with the
-- `has_perm` gates each read path tests first. A role that sees NOTHING is
-- usually the `has_perm` gate rather than the scope, and here it was BOTH.
--
-- ONLY THESE TWO ROLES ARE TOUCHED (the user, 2026-09-15: "Take the Current
-- [As Set in the App] Roles as the Standard for Regional Managers, Reporting
-- Managers, Engineers .. Never Touch those Roles & Permissions. Modify only
-- the VPTechnical and RnDEngg Role"). The match is on the role's key OR its
-- label with the separators squashed, so `vptechnical`, `vp_technical` and a
-- label of "VP Technical" all land and nothing else can: `rgm`, `rm` and
-- `engineer` cannot match either pattern.
--
-- READ ONLY. Every key below is a READ — the two roles gain no authority to
-- write a call, a review, a failure report or a stock line. Analysing the data
-- is what they were blank for; changing it was not asked for and is not
-- granted here.
--
-- MERGED, NEVER OVERWRITTEN, and a role with ZERO permissions is left alone:
-- an empty array means "not configured" and `permsForRole()` falls back to the
-- code defaults, which writing one key into would silently switch off.
-- ===========================================================================

do $$
declare
  n int;
  keys text[] := array[
    'data.view_all',      -- the scope: every call, report, request and consumption row
    'calls.view',         -- the gate the call policies test BEFORE the scope
    'consumption.view',   -- Spare Insights, and the consumption reports
    'reports.view',       -- the visit reports a failure is read from
    'ffr.view',           -- the Field Failure Register the analysis rolls up
    'masters.view',       -- product, party and part names, so a chart has labels
    'feedback.view',
    'dashboard.view'
  ];
  who text;
begin
  if to_regclass('public.app_roles') is null then return; end if;

  update public.app_roles ar
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (
               select jsonb_array_elements_text(ar.permissions) as v
               union
               select unnest(keys) as v
             ) u
         ),
         updated_at = now()
   -- The LABEL is matched as well as the key: a role created through the UI
   -- takes its key from the name it was given, and "VP Technical" keys as
   -- `vp_technical` while "VPTechnical" keys as `vptechnical`. Squashing the
   -- separators out of both means the migration does not depend on which was
   -- typed. Nothing else squashes to these strings.
   where jsonb_array_length(ar.permissions) > 0
     and ( regexp_replace(lower(coalesce(ar.role,  '')), '[^a-z0-9]', '', 'g')
             in ('vptechnical', 'rndengg', 'rndengineer')
        or regexp_replace(lower(coalesce(ar.label, '')), '[^a-z0-9]', '', 'g')
             in ('vptechnical', 'rndengg', 'rndengineer') );
  get diagnostics n = row_count;

  select string_agg(ar.role, ', ' order by ar.role) into who
    from public.app_roles ar
   where regexp_replace(lower(coalesce(ar.role, '')), '[^a-z0-9]', '', 'g')
           in ('vptechnical', 'rndengg', 'rndengineer')
      or regexp_replace(lower(coalesce(ar.label, '')), '[^a-z0-9]', '', 'g')
           in ('vptechnical', 'rndengg', 'rndengineer');

  raise notice '0207: % analysis role(s) updated; roles present: %', n, coalesce(who, 'none');
  if who is null then
    raise notice '0207: neither VP Technical nor R&D Engineer exists on this project — nothing to do.';
  end if;
end $$;

-- ------------------------------------------------------------------------
-- 0209_how_rithi_functions_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- "HOW RITHI FUNCTIONS" IS RESTRICTED TO FOUR ROLES.
--
-- The user, 2026-09-16: "How RITHI Functions - Limit Exposure to Admin, NSM,
-- Zoho, Technical Support."
--
-- The page shipped this morning as `alwaysOpen` — not a module at all, open to
-- everybody, like the two help pages beside it. It is a module now, with the
-- key `mod:/knowledge-base/how-it-works`, and this file is what makes that key
-- mean anything on a project in use.
--
-- REMOVING A MENU ENTRY DOES NOT RESTRICT A PAGE. The route still answers, and
-- anyone who has been sent the address still reaches it. The permission is the
-- restriction; the menu merely follows it.
--
-- AND A CODE DEFAULT REACHES NOBODY HERE. `permsForRole()` is
-- `if (stored && stored.length) return stored;` — the defaults apply ONLY to a
-- role whose stored set is EMPTY, and on a live project every role has a tuned
-- row. So ticking the box in `DEFAULT_PERMS` grants it to no one until this
-- runs. That is the standing rule this project has been bitten by four times,
-- and the direction is the same whether the change is widening or narrowing.
--
-- IT ONLY GRANTS. There is nothing to take away: the key is new, so no role
-- holds it, and the page's OLD state was "no key at all". A role not named
-- below simply never gains it — which is the restriction.
--
-- A ROLE WITH ZERO PERMISSIONS IS LEFT ALONE. An empty array means "not
-- configured" and the code defaults apply, which for those three of the four
-- already carry this key; writing one key into an empty row would turn that
-- fallback off and take everything else away.
-- ===========================================================================

do $$
declare n int;
begin
  if to_regclass('public.app_roles') is null then return; end if;

  update public.app_roles ar
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (
               select jsonb_array_elements_text(ar.permissions) as v
               union
               select unnest(array['mod:/knowledge-base/how-it-works']) as v
             ) u
         ),
         updated_at = now()
   where jsonb_array_length(ar.permissions) > 0
     and ar.role in ('admin', 'nsm', 'zoho_migration', 'technical_support')
     and not (ar.permissions ? 'mod:/knowledge-base/how-it-works');
  get diagnostics n = row_count;

  raise notice '0209: % of 4 role(s) given mod:/knowledge-base/how-it-works', n;

  -- SAID OUT LOUD, because the opposite of this grant is the point of the
  -- change: anybody else holding it would be a defect, and a migration that
  -- only reports what it added cannot show that.
  if exists (
    select 1 from public.app_roles
     where permissions ? 'mod:/knowledge-base/how-it-works'
       and role not in ('admin', 'nsm', 'zoho_migration', 'technical_support')
  ) then
    raise notice '0209: WARNING — a role outside the four holds this key. '
                 'Check Roles & Permissions; this file never granted it.';
  end if;
end $$;

-- ------------------------------------------------------------------------
-- 0213_stores_and_spare_coordinator_see_all.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- STORES INCHARGE AND SPARE COORDINATOR SEE EVERY ROW.
--
--   The user, 2026-09-18: "data.view_all --- Stores In Charge, Spare
--   Co-ordinator should be able to view all Rows. Fix this."
--
-- EXACTLY TWO ROLES. Commercial was named in the same message as a module the
-- user is working on, NOT as a role to grant, so it is not touched here. Nor is
-- anything else: the standing rule is that Regional Manager, Reporting Manager
-- and Engineer are as the user set them.
--
-- MERGE, NEVER OVERWRITE. The permissions column is rebuilt as the union of
-- what is already there and the one new key, so a role an administrator has
-- tuned keeps every tick. Re-running changes nothing.
--
-- A ROLE WITH ZERO PERMISSIONS IS LEFT ALONE. An empty array means "not
-- configured", and `has_perm()` falls back to the engineer defaults only while
-- it stays empty — writing one key into it would silently switch that fallback
-- off and take away everything else the role could do.
--
-- ---------------------------------------------------------------------------
-- WHAT THIS DOES AND DOES NOT CHANGE — read this before judging it by the
-- screen afterwards.
--
-- Both roles ALREADY pass `can_view_all_calls()`, which names them directly:
--
--     ... or exists (select 1 from profiles p where p.id = auth.uid()
--                     and lower(p.role) in ('hotline','nsm','commercial',
--                         'spare_coordinator','stores_incharge','tally_coordinator'))
--
-- and every policy in this database that consults `data.view_all` consults
-- `can_view_all_calls()` as well — checked, all three of them
-- (handstock_opening, spare_consumption_history, spare_issue_history). There is
-- no policy anywhere where this permission is the only way in.
--
-- SO THE GRANT IS BELT AND BRACES, and it is worth having for exactly that
-- reason: it makes the intent explicit on the Roles & Permissions screen, and
-- it keeps working if somebody is given a role KEY that is not one of the six
-- names hard-coded in that function.
--
-- WHICH MEANS: IF ROWS ARE STILL MISSING AFTER THIS, THE PERMISSION WAS NOT THE
-- CAUSE. Both routes read the person's role from `profiles.role`
-- (`my_role()` lowercases and trims it), so somebody whose profile says
-- `stores` or `Stores Incharge` rather than `stores_incharge` matches NEITHER
-- the hard-coded list NOR this app_roles row. `_who_can_this_person_see.sql`
-- row 2 prints the value their profile actually holds.
-- ===========================================================================
do $$
declare
  n      int;
  who    text;
  missed text;
begin
  if to_regclass('public.app_roles') is null then
    raise notice '0213: app_roles is missing -- run rbac.sql first';
    return;
  end if;

  update public.app_roles ar
     set permissions = (
           select jsonb_agg(distinct p)
             from jsonb_array_elements(ar.permissions || '["data.view_all"]'::jsonb) p)
   where ar.role in ('stores_incharge', 'spare_coordinator')
     -- Not configured: leave it, so the engineer fallback keeps working.
     and jsonb_array_length(coalesce(ar.permissions, '[]'::jsonb)) > 0
     -- Idempotent: a role that already holds it is not rewritten.
     and not (ar.permissions ? 'data.view_all');
  get diagnostics n = row_count;

  select string_agg(ar.role || ' (' || jsonb_array_length(ar.permissions)::text || ' perms)',
                    ', ' order by ar.role)
    into who
    from public.app_roles ar
   where ar.role in ('stores_incharge', 'spare_coordinator')
     and ar.permissions ? 'data.view_all';

  -- SAY WHAT WAS NOT DONE, and why. A role that is absent, or that has zero
  -- permissions, is skipped by design above -- and a migration that skips
  -- silently is one somebody re-runs looking for an effect it never had.
  select string_agg(r.want || ': ' || r.why, '; ' order by r.want) into missed
    from (
      select w.want,
             case when ar.role is null then 'no such role on this project'
                  else 'zero permissions (not configured) -- left alone on purpose' end as why
        from (values ('stores_incharge'), ('spare_coordinator')) w(want)
        left join public.app_roles ar on ar.role = w.want
       where ar.role is null
          or jsonb_array_length(coalesce(ar.permissions, '[]'::jsonb)) = 0
    ) r;

  raise notice '0213: % role(s) granted data.view_all; now holding it: %',
    n, coalesce(who, 'none');
  if missed is not null then
    raise notice '0213: NOT granted -- %', missed;
  end if;
end $$;

-- ------------------------------------------------------------------------
-- 0216_view_all_except_the_three.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- `data.view_all` FOR EVERY ROLE EXCEPT THREE.
--
--   The user, 2026-09-18: "data.view_all - Is applicable for all Roles Except -
--   Regional Manager , REporting Manager , Engineer."
--
-- This supersedes the narrower question left open after 0213 (whether
-- Commercial should have it): the answer is the RULE, not a list. So this
-- migration is written as the rule — grant to everything, subtract the three —
-- rather than as a list of the nine roles that happen to exist today. A list
-- would be right this week and silently wrong the moment a thirteenth role is
-- added, which is exactly how the analysis roles came to see nothing.
--
-- THE THREE ARE THE STANDING RULE, and they are the ones whose visibility is
-- SUPPOSED to be bounded by the reporting tree: a Regional Manager, a Reporting
-- Manager and an Engineer see their own work and their team's, through
-- `visible_engineer_names()`. Granting this to any of them is the bug reported
-- this morning — "Why is a Regional Manager able to see everyone's call and
-- every spare request?" — so the exclusion is the load-bearing half of this
-- file, not the grant.
--
-- WHICH IS WHY THE EXCLUSION IS DELIBERATELY GENEROUS AND THE GRANT IS NOT.
-- The two errors are not symmetrical: excluding a role that should have been
-- granted leaves somebody with fewer rows than intended, which is visible and
-- reversible by a tick on Roles & Permissions. Granting one that should have
-- been excluded hands a manager every region's data, reads as a different
-- region rather than as an error, and nobody reports it. So the exclusion
-- matches on the role key with case and punctuation SQUASHED and covers the
-- spellings each of the three is written in — `rgm`, `regional_manager`,
-- `RegionalManager` are one role here.
--
-- MERGE, NEVER OVERWRITE (0213's rule, and the project's). The permissions
-- column is rebuilt as the union of what is there and the one key, so a role an
-- administrator has tuned keeps every tick. Re-running changes nothing.
--
-- A ROLE WITH ZERO PERMISSIONS IS LEFT ALONE. An empty array means "not
-- configured", and `has_perm()` falls back to the engineer defaults only while
-- it stays empty — writing one key in would switch that fallback off and take
-- away everything else the role could do. It is reported rather than skipped
-- silently.
--
-- WHAT IT ACTUALLY CHANGES. `data.view_all` makes `can_view_all_calls()` true
-- for ANY role, so for the six office roles named inside that function
-- (hotline, nsm, commercial, spare_coordinator, stores_incharge,
-- tally_coordinator) this is belt and braces — they already passed. What it
-- genuinely widens is every OTHER non-excluded role on the project: the ones
-- not hard-coded in that function, including any this repository does not know
-- about. That is the ask, and it is worth saying out loud rather than
-- discovering.
--
-- AND IF A REGIONAL MANAGER ALREADY HOLDS IT, THIS FILE DOES NOT TAKE IT AWAY.
-- That would be editing one of the three roles the user has said twice not to
-- touch, and a permission removed by a migration is not something an
-- administrator can see was removed. It is REPORTED instead, in the notice
-- below, marked so it cannot be missed — removing it is then a decision
-- somebody makes, not one this file makes for them. (That is how a Regional
-- Manager came to see every region: `data.view_all` was ticked by hand on Roles
-- & Permissions; `_who_can_this_person_see.sql` tells that apart from the blank
-- name fault 0212 fixed.)
--
-- NO `_status.sql` ROW, DELIBERATELY. `app_roles` is EDITED by administrators,
-- so a row asserting "every non-excluded role holds this" would read NO the
-- first time somebody legitimately unticks one — and a NO that means nothing is
-- worse than no row, because it sends somebody to re-run a bundle already in.
-- Row 165 was exactly that mistake a week ago. The notices above are the
-- report; they print what is true at the moment it is run.
-- ===========================================================================
do $$
declare
  n        int;
  granted  text;
  skipped  text;
  excluded text;
begin
  if to_regclass('public.app_roles') is null then
    raise notice '0216: app_roles is missing -- run rbac.sql first';
    return;
  end if;

  update public.app_roles ar
     set permissions = (
           select jsonb_agg(distinct p)
             from jsonb_array_elements(ar.permissions || '["data.view_all"]'::jsonb) p)
   where regexp_replace(lower(coalesce(ar.role, '')), '[^a-z0-9]', '', 'g') not in (
           -- REGIONAL MANAGER
           'rgm', 'regionalmanager', 'regionmanager',
           -- REPORTING MANAGER
           'rm', 'reportingmanager', 'reportmanager',
           -- ENGINEER
           'engineer', 'engineers', 'fieldengineer', 'serviceengineer'
         )
     -- Not configured: leave it, so the engineer fallback keeps working.
     and jsonb_array_length(coalesce(ar.permissions, '[]'::jsonb)) > 0
     -- Idempotent: a role that already holds it is not rewritten.
     and not (ar.permissions ? 'data.view_all');
  get diagnostics n = row_count;

  select string_agg(ar.role, ', ' order by ar.role) into granted
    from public.app_roles ar
   where ar.permissions ? 'data.view_all';

  select string_agg(ar.role, ', ' order by ar.role) into skipped
    from public.app_roles ar
   where jsonb_array_length(coalesce(ar.permissions, '[]'::jsonb)) = 0;

  -- NAME THE EXCLUDED ONES EVERY RUN. This is the half somebody needs to be
  -- able to read back off the screen, and a migration that only reports what it
  -- changed cannot show that the three were deliberately left as they are.
  select string_agg(ar.role || case when ar.permissions ? 'data.view_all'
                                    then ' *** HOLDS data.view_all -- ticked by hand,'
                                         || ' this file does not remove it ***'
                                    else '' end,
                    ', ' order by ar.role) into excluded
    from public.app_roles ar
   where regexp_replace(lower(coalesce(ar.role, '')), '[^a-z0-9]', '', 'g') in (
           'rgm', 'regionalmanager', 'regionmanager',
           'rm', 'reportingmanager', 'reportmanager',
           'engineer', 'engineers', 'fieldengineer', 'serviceengineer');

  raise notice '0216: granted data.view_all to % role(s). Now holding it: %',
    n, coalesce(granted, 'none');
  raise notice '0216: EXCLUDED (left exactly as they are): %',
    coalesce(excluded, 'none of the three exist on this project');
  if skipped is not null then
    raise notice '0216: skipped, zero permissions (not configured, on purpose): %', skipped;
  end if;
end $$;

-- ------------------------------------------------------------------------
-- 0219_product_database_2_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- PRODUCT DATABASE 2.0 REACHES THE ROLES THAT ALREADY HAVE THE PRODUCT DATABASE.
--
-- `permsForRole()` is `if (stored && stored.length) return stored;` — the code
-- defaults apply ONLY to a role whose stored set is EMPTY, and on a project in
-- use every role has a tuned row. So a new module's key reaches NOBODY until a
-- migration puts it there: the screen ships, the menu entry exists, the
-- permission is ticked in DEFAULT_PERMS, and the page is invisible to every
-- role with no error anywhere. That is what happened to Machine History, the
-- Call Report and the Customer Feedback Report; 0192/0195 are the pattern.
--
-- THE AUDIENCE IS COPIED, NOT CHOSEN. Whoever can open the Product Database can
-- open 2.0 — it is the same machines seen a second way, so picking a different
-- list would be deciding, in a migration, that somebody should not be able to
-- compare the two. 0192 did exactly this when the Product Master and Product
-- Database swapped names.
--
-- MERGE, NEVER OVERWRITE, and leave a role with ZERO permissions alone: an
-- empty array means "not configured" and writing one key into it switches the
-- engineer fallback off, taking away everything else that role could do.
-- ===========================================================================
do $$
declare n int; who text; skipped text;
begin
  if to_regclass('public.app_roles') is null then
    raise notice '0219: app_roles is missing -- run rbac.sql first';
    return;
  end if;

  update public.app_roles ar
     set permissions = (
           select jsonb_agg(distinct p)
             from jsonb_array_elements(ar.permissions || '["mod:/product-database-2"]'::jsonb) p)
   where ar.permissions ? 'mod:/product-database'
     and jsonb_array_length(coalesce(ar.permissions, '[]'::jsonb)) > 0
     and not (ar.permissions ? 'mod:/product-database-2');
  get diagnostics n = row_count;

  select string_agg(ar.role, ', ' order by ar.role) into who
    from public.app_roles ar where ar.permissions ? 'mod:/product-database-2';

  -- SAY WHAT WAS NOT DONE. A role that holds the old key but has zero
  -- permissions cannot hold it, so this can never fire -- but a role that holds
  -- NEITHER key is a role nobody will be able to open the new screen with, and
  -- that is worth reading rather than discovering.
  select string_agg(ar.role, ', ' order by ar.role) into skipped
    from public.app_roles ar
   where not (ar.permissions ? 'mod:/product-database')
     and jsonb_array_length(coalesce(ar.permissions, '[]'::jsonb)) > 0;

  raise notice '0219: % role(s) gained mod:/product-database-2; now holding it: %',
    n, coalesce(who, 'none');
  if skipped is not null then
    raise notice '0219: NOT granted (they do not hold the Product Database either): %', skipped;
  end if;
end $$;

-- ------------------------------------------------------------------------
-- 0241_handstock_report_permission.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE HAND STOCK REPORT'S KEY REACHES SOMEBODY.
--
--   The user, 2026-09-24: "Add a Hand Stock Report - Default access to
--   Admin/Super Admin, Rest of the Access I will select from Roles &
--   Permissions."
--
-- WITHOUT THIS THE SCREEN IS INVISIBLE TO EVERYBODY AND NOTHING SAYS SO.
-- `permsForRole()` is `if (stored && stored.length) return stored;` -- the code
-- defaults apply ONLY to a role whose stored set is EMPTY, and on a project in
-- use every role has a tuned row. So a new module's key must be MERGED into
-- `app_roles` or the page ships, the menu entry exists, the permission is
-- ticked in the code, and no role can open it. That has happened four times
-- here (Machine History, the Call Report, the Customer Feedback Report, Solved
-- Without a Report); 0195, 0209 and 0224 are the pattern and this is the same
-- shape.
--
-- WHO IT GRANTS, AND WHY IT IS NOT JUST `admin`.
--
--   SUPER ADMIN NEEDS NO GRANT. It is not a role -- it is a row in
--   `app_super_admins` that overrides every check -- so it can already open
--   this screen, and writing a key for it would be writing to a role that does
--   not exist.
--
--   TECHNICAL SUPPORT IS GRANTED, AND THAT IS NOT A LIBERTY TAKEN WITH A ROLE
--   THE USER DID NOT NAME. `_status.sql` row 114 asserts a PROPERTY: Technical
--   Support holds every module key the admin holds. That is what the role IS
--   (the user, 2026-09-08: "Map this Role to All Modules and Mimic Super Admin
--   - But with Read Only For now"), and an admin-only page skipping it breaks
--   the role silently -- which is the fault that row exists to catch. The first
--   version of this migration granted `admin` alone and row 114 went red on the
--   validation run, which is exactly what it is for. 0224 granted the previous
--   administrators-only report the same way.
--
--   IT CONFERS NO WRITE. A module key opens a SCREEN; the read policies decide
--   the rows, and this screen writes nothing at all. Row 117 -- Zoho Migration
--   holds no write action -- is untouched either way.
--
--   ZOHO MIGRATION IS LEFT ALONE. No check requires it, the user named Admin,
--   and the standing rule here is not to touch a role that was not named. It is
--   one tick on Roles & Permissions if it is wanted.
--
-- MERGED, NEVER OVERWRITTEN, and a role with ZERO permissions is left exactly
-- as it is: an empty array means "not configured", and writing one key into it
-- turns off the fallback that is currently giving that role its access.
--
-- IDEMPOTENT: a role that already holds the key is not touched, so `updated_at`
-- does not move on a re-run and the notice reports the truth either way.
-- ===========================================================================

do $$
declare n integer;
begin
  if to_regclass('public.app_roles') is null then return; end if;

  update public.app_roles ar
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (
               select jsonb_array_elements_text(ar.permissions) as v
               union
               select unnest(array['mod:/handstock-report']) as v
             ) u
         ),
         updated_at = now()
   where jsonb_array_length(ar.permissions) > 0
     and ar.role in ('admin', 'technical_support')
     and not (ar.permissions ? 'mod:/handstock-report');
  get diagnostics n = row_count;
  raise notice '0241: % of 2 role(s) given mod:/handstock-report (admin + technical_support -- grant the rest on Roles & Permissions)', n;
end $$;

-- ------------------------------------------------------------------------
-- 0199_user_master_is_the_master.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- USER MASTER IS THE MASTER: a role set there reaches the sign-in by itself.
--
-- The user's rule, 2026-09-15: *"The intent and the fact has to match 100% —
-- the user master is the only place I can map and configure."*
--
-- TWO VALUES ANSWER TO THE NAME "ROLE" AND NOTHING KEPT THEM IN STEP.
--   • `user_directory.role`  — what User Master shows. Set by an administrator.
--   • `profiles.role`        — what the sign-in RUNS ON: the menu-bar chip,
--                              `has_perm()`, every policy.
-- 0033 copies the first into the second exactly once — inside
-- `ensure_my_profile()`, which returns early for a row that already exists
-- (`if found then return p; end if;`). After that, the only thing that copied
-- it was SAVING that person's row on the User Master screen, in the browser,
-- by email match (`UserMasterView.persist`). So a role changed after somebody
-- first signed in stayed in User Master: the screen said one thing and their
-- access was another, with nothing anywhere reporting the difference.
--
-- Reported twice. 2026-09-11: *"Why is it now Engineer"* — which produced the
-- drift banner and its "Apply roles" button, a REPAIR for a problem still
-- being created. 2026-09-15: *"Why is it showing as engineer and not Zoho
-- Migration."*
--
-- A BUTTON THAT REPAIRS DRIFT IS NOT THE SAME AS NOT DRIFTING. Somebody has to
-- open the right screen, notice the banner and press it; in between, the
-- application enforces a role nobody chose. This makes the copy automatic, in
-- the database, so it happens for every path that writes a directory row — the
-- screen, a bulk import, an admin's own SQL — and not only the one the browser
-- knows about.
--
-- WHAT IT DOES NOT DO, deliberately:
--   • It never invents a role. A blank directory role leaves the sign-in alone,
--     and a role the matrix does not know (a typo, a role since deleted) is
--     ignored rather than applied — a typo must grant nothing, not something
--     unintended. Same rule `ensure_my_profile()` already uses.
--   • It does not weaken one guard. `profiles_role_guard` (0008) still fires:
--     nobody moves their own role, and granting `admin` still needs an
--     administrator. If an administrator edits their OWN User Master row and
--     changes the role on it, the save is REFUSED with that guard's message —
--     correct, and the only way the two screens can stay honest.
--   • It does not touch a NAME while two directory rows share one login.
--     `service.almsind@gmail.com` has two (eBizWiz Admin, WRITE OFF), so "the"
--     name for that sign-in is not a question with an answer; whichever row was
--     saved last would win and "WRITE OFF" would become somebody's display
--     name. A name needs ONE unambiguous source. The role is still applied —
--     the duplicates agree about it, and a wrong role is enforced where a wrong
--     name is only shown.
-- ===========================================================================

create or replace function public.sync_profile_from_user_directory()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_role   text := lower(btrim(coalesce(new.role, '')));
  v_name   text := btrim(coalesce(new.name, ''));
  v_desig  text := btrim(coalesce(new.designation, ''));
  v_emails text[];
  v_shared boolean;
begin
  -- The sign-in is found by email OR gmail, the same two the screen matches on
  -- and the same two `ensure_my_profile()` uses. A row with neither reaches no
  -- sign-in at all.
  v_emails := array_remove(array[lower(btrim(coalesce(new.email, ''))),
                                 lower(btrim(coalesce(new.gmail, '')))], '');
  if coalesce(array_length(v_emails, 1), 0) = 0 then return new; end if;

  -- A role the matrix does not know grants nothing rather than something
  -- unintended — so it is dropped here, not written and left to fail later.
  if v_role <> '' and not exists (select 1 from public.app_roles a where a.role = v_role) then
    v_role := '';
  end if;

  -- Is this login claimed by more than one directory row? Then its NAME has no
  -- single source and is left alone (see the header).
  select exists (
    select 1 from public.user_directory d
     where d.id is distinct from new.id
       and (lower(btrim(coalesce(d.email, ''))) = any(v_emails)
         or lower(btrim(coalesce(d.gmail, ''))) = any(v_emails))
  ) into v_shared;

  update public.profiles p
     set role        = case when v_role  <> ''                 then v_role  else p.role end,
         full_name   = case when v_name  <> '' and not v_shared then v_name  else p.full_name end,
         designation = case when v_desig <> '' and not v_shared then v_desig else p.designation end
   where lower(btrim(p.email)) = any(v_emails)
     and ((v_role  <> ''                 and p.role      is distinct from v_role)
       or (v_name  <> '' and not v_shared and p.full_name is distinct from v_name)
       or (v_desig <> '' and not v_shared and coalesce(p.designation, '') is distinct from v_desig));

  return new;
end $$;

comment on function public.sync_profile_from_user_directory() is
  'User Master is the master: a role (and, where the login has one directory row, the name and designation) set there is applied to that person''s sign-in immediately.';

revoke all on function public.sync_profile_from_user_directory() from public;

drop trigger if exists user_directory_profile_sync on public.user_directory;
create trigger user_directory_profile_sync
  after insert or update on public.user_directory
  for each row execute function public.sync_profile_from_user_directory();

-- ---------------------------------------------------------------------------
-- THE BACKFILL, for what drifted before the trigger existed.
--
-- ROLE: applied wherever it differs and the matrix knows it. On the live
-- project as of 2026-09-15 this changes NOTHING — all 58 sign-ins already
-- match, because the drift found this week was applied by hand. That is the
-- point of running it anyway: a database rebuilt from these migrations, or one
-- that fell behind, lands in the same state as the live one.
--
-- NAME: only where the profile's name is BLANK — the "?" avatar, which is also
-- what the audit trail records as the actor. A name that is present and merely
-- DIFFERENT is left alone: three logins have one today and one of them is
-- ambiguous, so correcting them is a decision about people, not a migration.
-- They correct themselves the next time those User Master rows are saved.
-- ---------------------------------------------------------------------------
do $$
declare n_role int; n_name int;
begin
  with src as (
    select p.id, lower(btrim(d.role)) as role
      from public.profiles p
      join public.user_directory d
        on lower(btrim(p.email)) = lower(btrim(coalesce(d.email, '')))
        or lower(btrim(p.email)) = lower(btrim(coalesce(d.gmail, '')))
      join public.app_roles a on a.role = lower(btrim(d.role))
     where coalesce(btrim(d.role), '') <> ''
       and p.role is distinct from lower(btrim(d.role))
  )
  update public.profiles p set role = src.role from src where src.id = p.id;
  get diagnostics n_role = row_count;

  with src as (
    select p.id, btrim(d.name) as name
      from public.profiles p
      join public.user_directory d
        on lower(btrim(p.email)) = lower(btrim(coalesce(d.email, '')))
        or lower(btrim(p.email)) = lower(btrim(coalesce(d.gmail, '')))
     where coalesce(btrim(p.full_name), '') = ''
       and coalesce(btrim(d.name), '') <> ''
  )
  update public.profiles p set full_name = src.name from src where src.id = p.id;
  get diagnostics n_name = row_count;

  raise notice 'User Master sync backfill: % role(s) applied, % blank name(s) filled', n_role, n_name;
end $$;

-- ------------------------------------------------------------------------
-- 0087_spare_line_stub_rls.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- "Your role does not have permission for this action." on the FIRST spare line.
--
-- 0084 lets a line whose request is in neither export create a stub parent from
-- a BEFORE INSERT trigger, so one gap in the source does not cost the file. The
-- foreign key is satisfied by that stub — referential checks run at the end of
-- the statement, with a fresh snapshot — but `srl_insert` is NOT:
--
--   with check (has_perm('spare.request') and exists (
--     select 1 from spare_requests r where r.uid = request_uid
--       and (r.created_by = auth.uid() or is_admin())))
--
-- A row-level security check is evaluated INSIDE the inserting command, and a
-- command cannot see rows written by SQL its own triggers ran: the stub's cmin
-- is higher than the command's. So the EXISTS finds nothing and the row is
-- refused — for an ADMIN too, because `is_admin()` sat inside the EXISTS and an
-- EXISTS with no row is false however permissive its predicate is.
--
-- And PostgREST sends the whole upload as ONE insert, so a single such line
-- fails all 8,571 — which is what happened on row 1 (OR26724, an OR number the
-- 2026 header export does not go back far enough to carry).
--
-- Hoisting `is_admin()` out of the EXISTS is the whole fix. It takes nothing
-- away from anyone else: a non-admin still has to own the request they are
-- attaching lines to, and an admin could already read and write every one of
-- these rows.
-- ===========================================================================

drop policy if exists srl_insert on public.spare_request_lines;
create policy srl_insert on public.spare_request_lines for insert
  with check (
    public.has_perm('spare.request')
    and (
      public.is_admin()
      or exists (
        select 1 from public.spare_requests r
         where r.uid = request_uid and r.created_by = auth.uid())
    ));

-- ------------------------------------------------------------------------
-- 0088_spare_line_parent_visible.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- "Your role does not have permission for this action." on the first spare
-- line — still, after 0087.
--
-- 0087 hoisted `is_admin()` out of the EXISTS, which fixes the upload for an
-- administrator and nobody else. But the real fault is not WHO is uploading, it
-- is that the check cannot SEE what it is checking: 0084's stub parent is
-- written by a BEFORE trigger, and a command cannot see rows the SQL its own
-- triggers ran has inserted. So for anyone who is not an admin — a Spare
-- Coordinator, an RM, whoever actually loads the register — the row is still
-- refused, and one such line still fails all 8,571.
--
-- Ask the question in a place that can see the answer. A VOLATILE plpgsql
-- function takes a FRESH SNAPSHOT for each statement it runs (read committed),
-- so the stub its caller's trigger just wrote is visible to it. Same question,
-- same rule — a line must belong to a request you raised (or you are an
-- admin) — asked where it can be answered truthfully.
--
-- It is SECURITY DEFINER so the lookup is not itself filtered by `sr_read`
-- (a request you own but cannot yet read would otherwise answer "no"), and it
-- returns a BOOLEAN and nothing else, so it discloses nothing.
-- ===========================================================================

create or replace function public.spare_line_parent_ok(p_uid text)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare ok boolean;
begin
  if btrim(coalesce(p_uid, '')) = '' then
    return false;                                 -- no parent named; the FK will say so
  end if;
  select exists (
    select 1 from public.spare_requests r
     where r.uid = p_uid
       and (r.created_by = auth.uid() or public.is_admin())
  ) into ok;
  return coalesce(ok, false);
end $$;

grant execute on function public.spare_line_parent_ok(text) to authenticated;

drop policy if exists srl_insert on public.spare_request_lines;
create policy srl_insert on public.spare_request_lines for insert
  with check (
    public.has_perm('spare.request')
    and public.spare_line_parent_ok(request_uid)
  );

-- ------------------------------------------------------------------------
-- 0145_technical_support_role.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- TECHNICAL SUPPORT — the Super Admin's reach, none of its writes.
--
-- The user, 2026-09-08: "Create a New Role 'Technical Support' - Map this Role
-- to All Modules and Mimic Super Admin - But with Read Only For now."
--
-- So the role holds EVERY module key, including the administration ones, and
-- exactly the actions that only READ. It is not a narrower admin: it is the
-- same field of view with nothing that changes a row.
--
-- WHAT MAKES IT READ-ONLY IS WHAT IT DOES NOT HOLD, not a flag. Every write in
-- this database is gated by an RLS policy naming the action it needs --
-- `calls.edit`, `masters.edit`, `spare.dispatch`, `users.manage`, and the rest.
-- A role holding none of them cannot write, whatever a screen offers it: the
-- refusal is Postgres's, not the browser's. That is also why the list below is
-- written out rather than filtered by a pattern -- `consumption.reconcile` and
-- `ownership.transfer` do not say "edit" either, and a rule that went by the
-- key's spelling would hand over both.
--
-- `data.view_all` is what makes the rest of it useful. Without it the role can
-- open every page and, on the call pages, sees only rows allotted to it --
-- which for a support login is nothing at all. can_view_all_calls() (0035)
-- already honours the permission, so no policy changes here.
--
-- `admin.view` is new: it opens the administration screens read-only. They
-- gated themselves on `users.manage` / `rbac.manage` -- the rights to CHANGE
-- what is on them -- so until now there was no way to let somebody look.
--
-- MERGED, NEVER OVERWRITTEN, like every other grant in this project: an
-- administrator may have tuned the role by the time this is replayed, and the
-- merge cannot widen it past read-only because nothing in the list writes.
-- ===========================================================================

do $ts$
declare
  -- Every module in src/lib/rbac.ts MODULES, admin ones included. Kept as a
  -- literal list because the database has no other record of what the app's
  -- pages are; a page added later is added here too (and the union below means
  -- anything the admin role has gained meanwhile comes along by itself).
  all_mods text[] := array[
    'mod:/','mod:/lookup','mod:/daily-review','mod:/parties','mod:/product-master',
    'mod:/user-master','mod:/parts','mod:/masters','mod:/service-manuals','mod:/qms',
    'mod:/warranties','mod:/contracts','mod:/ownership-transfer','mod:/request-registration',
    'mod:/pending-registrations','mod:/field-calls','mod:/installations','mod:/pm-calls',
    'mod:/pending-calls','mod:/reports','mod:/report-mapping','mod:/bulk-uploads',
    'mod:/spare-requests','mod:/spare-rm-approval','mod:/spare-dispatch','mod:/spare-consumption',
    'mod:/handstock','mod:/mrn','mod:/stock-transfer','mod:/feedback','mod:/failure-report',
    'mod:/kpi','mod:/objective','mod:/exports','mod:/tracker','mod:/users','mod:/roles',
    'mod:/audit','mod:/admin-config','mod:/settings','mod:/version-history'];
  -- READ ONLY. Nothing here changes a row.
  read_only text[] := array[
    'calls.view','masters.view','consumption.view','reports.view','dashboard.view',
    'feedback.view','audit.view','admin.view','export.data','data.view_all'];
  granted jsonb;
begin
  if to_regclass('public.app_roles') is null then
    raise notice 'app_roles is missing -- run rbac.sql first';
    return;
  end if;

  -- The module keys the ADMIN role actually holds, so a page added to the admin
  -- role by a later migration reaches Technical Support without this file being
  -- edited. Union, not replacement: the literal list above is the floor.
  select coalesce(jsonb_agg(distinct v), '[]'::jsonb) into granted
    from (
      select unnest(all_mods) as v
      union
      select unnest(read_only)
      union
      select m.v
        from public.app_roles ar,
             lateral jsonb_array_elements_text(ar.permissions) as m(v)
       where ar.role = 'admin'
         and m.v like 'mod:%'
    ) u;

  if exists (select 1 from public.app_roles r where r.role = 'technical_support') then
    -- MERGE. Whatever an administrator has since ticked stays ticked, and the
    -- merge cannot widen the role past read-only because nothing in `granted`
    -- writes.
    update public.app_roles r
       set permissions = (
             select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
               from (
                 select e.v from jsonb_array_elements_text(r.permissions) as e(v)
                 union
                 select g.v from jsonb_array_elements_text(granted) as g(v)
               ) m
           ),
           label      = coalesce(nullif(r.label, ''), 'Technical Support'),
           updated_at = now()
     where r.role = 'technical_support';
  else
    insert into public.app_roles (role, label, permissions)
    values ('technical_support', 'Technical Support', granted);
  end if;

  raise notice 'Technical Support: % permission(s) -- every module, read-only actions only',
    jsonb_array_length(granted);
end $ts$;

-- ---------------------------------------------------------------------------
-- ADMIN GETS `admin.view` TOO, so the matrix does not show the Super Admin
-- missing a right it obviously holds. is_admin() short-circuits has_perm(), so
-- this changes nothing about what an admin can do -- it keeps the row honest.
-- ---------------------------------------------------------------------------
update public.app_roles ar
   set permissions = (
         select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
           from (
             select jsonb_array_elements_text(ar.permissions) as v
             union
             select 'admin.view' as v
           ) u
       ),
       updated_at = now()
 where ar.role = 'admin'
   and not (ar.permissions ? 'admin.view');

-- ------------------------------------------------------------------------
-- 0151_module_keys_catch_up.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE STORED ROLES CATCH UP WITH THE PAGES.
--
-- The user, 2026-09-09: "Update the Role & Permissions as per the Current List
-- of Pages , Actions."
--
-- A NEW PAGE IS INVISIBLE UNTIL A ROLE HOLDS ITS KEY, and that is the failure
-- this file fixes. `DEFAULT_PERMS` in the app is only a FALLBACK: it applies to
-- a role whose `app_roles` row is empty. Every role here has a populated row,
-- so adding a module to the code grants it to nobody — the nav asks
-- `can('mod:/x')`, the stored list does not have it, and the page simply never
-- appears. No error, no clue.
--
-- Three keys were in exactly that state:
--
--   mod:/spare-insights      shipped yesterday and visible to NOBODY but an
--                            administrator (is_admin short-circuits has_perm).
--                            My omission, not a design.
--   mod:/pm-bulk-upload      a page in the menu that had never had a key at all.
--   mod:/software-validation the same.
--
-- WHO GETS WHAT, and why it is derived rather than listed:
--
--   * Spare Insights goes to every role that already holds `consumption.view`.
--     It is a consumption dashboard; the roles allowed to see consumption are
--     the roles allowed to see it summarised. Deriving it from the permission
--     rather than naming roles means an administrator who has already tuned a
--     role gets the answer their own tuning implies.
--   * The two admin pages go to `admin` -- and to `technical_support`, because
--     that role's whole definition is "every module key the admin role holds,
--     read-only" (0145). A new admin page that skipped it would break that
--     promise silently, which is the same class of bug as the three above.
--
-- MERGED, NEVER OVERWRITTEN. An administrator may have tuned any of these; the
-- merge only ever adds, and adds nothing that writes.
-- ===========================================================================

do $mods$
declare
  n int := 0;
begin
  if to_regclass('public.app_roles') is null then
    raise notice 'app_roles is missing -- run rbac.sql first';
    return;
  end if;

  -- ---- Spare Insights: wherever consumption is already visible -------------
  update public.app_roles ar
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (
               select jsonb_array_elements_text(ar.permissions) as v
               union select 'mod:/spare-insights'
             ) u
         ),
         updated_at = now()
   where ar.permissions ? 'consumption.view'
     and not (ar.permissions ? 'mod:/spare-insights');
  get diagnostics n = row_count;
  raise notice 'Spare Insights granted to % role(s) that already see consumption', n;

  -- ---- the two admin pages: admin, and the role defined as admin's reach ---
  update public.app_roles ar
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (
               select jsonb_array_elements_text(ar.permissions) as v
               union select unnest(array['mod:/pm-bulk-upload', 'mod:/software-validation'])
             ) u
         ),
         updated_at = now()
   where ar.role in ('admin', 'technical_support')
     and not (ar.permissions ?& array['mod:/pm-bulk-upload', 'mod:/software-validation']);
  get diagnostics n = row_count;
  raise notice 'PM Bulk Upload and Software Validation granted to % role(s)', n;

  -- ---- and Technical Support keeps its defining property -------------------
  -- "Every module key the admin role holds" is what that role IS. Rather than
  -- listing modules again here, take whatever the admin row actually carries --
  -- so this stays true for pages added after today as well, whenever this file
  -- is replayed.
  update public.app_roles ts
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (
               select jsonb_array_elements_text(ts.permissions) as v
               union
               select m.v from public.app_roles a,
                    lateral jsonb_array_elements_text(a.permissions) as m(v)
                where a.role = 'admin' and m.v like 'mod:%'
             ) u
         ),
         updated_at = now()
   where ts.role = 'technical_support';
end $mods$;

-- ------------------------------------------------------------------------
-- 0155_zoho_migration_role.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- ZOHO MIGRATION — Technical Support's twin, for as long as the migration runs.
--
-- The user, 2026-09-09: "Add one more Role called ZohoMigration, Use Technical
-- Support as the Cloning Role, Add this to all the Modules, Pages, Sub Pages,
-- Actions."
--
-- CLONED FROM THE STORED ROW, not from a copy of its list. 0145 had to write
-- its module list out by hand because nothing in the database knew what the
-- app's pages were; this one does not, because `technical_support` is already
-- sitting there holding the answer -- INCLUDING whatever an administrator has
-- ticked onto it since, and every page added after 0145 was written. A second
-- literal list would be a second thing to keep in step, and the two would
-- diverge the first time somebody edited one.
--
-- SUB-PAGES ARE GRANTED EXPLICITLY even though they would be INHERITED.
-- `parentAction()` already makes `mod:/exports` cover every report and
-- `mod:/masters` cover every value list, so the role would work without this.
-- But the ask names sub-pages, and Roles & Permissions shows a row per
-- sub-page: a screen where the boxes are empty and access nevertheless works
-- is a screen nobody can use to answer "what can this role open?". The master
-- lists are read from `masters` rather than listed, since they are data.
--
-- WHY A SEPARATE ROLE AT ALL, rather than pointing the migration at Technical
-- Support: this one ends when the migration does. Keeping them apart means
-- revoking it is one tick and leaves the support login untouched -- and the
-- audit trail says which of the two did a thing.
--
-- READ-ONLY, by the same mechanism as Technical Support and for the same
-- reason: every write in this database is gated by an RLS policy naming the
-- action it needs, and this role holds none of them. A migration reads
-- everything and writes nothing HERE -- what it writes goes into Zoho. The
-- refusal, if a screen ever offers it a button, is Postgres's and not the
-- browser's.
--
-- MERGED, NEVER OVERWRITTEN, like every grant in this project.
-- ===========================================================================

do $zm$
declare
  granted jsonb;
  n_mods  integer;
begin
  if to_regclass('public.app_roles') is null then
    raise notice 'app_roles is missing -- run rbac.sql first';
    return;
  end if;

  if not exists (select 1 from public.app_roles where role = 'technical_support') then
    -- The clone source has to exist. Inventing a fallback list here is how the
    -- two roles would end up differing, which is the one thing this file is
    -- built to prevent.
    raise notice 'technical_support is not there yet -- run 0145 (rbac.sql) first, then this';
    return;
  end if;

  select coalesce(jsonb_agg(distinct v), '[]'::jsonb) into granted
    from (
      -- 1. Everything Technical Support holds, as it stands right now.
      select m.v
        from public.app_roles ar, lateral jsonb_array_elements_text(ar.permissions) as m(v)
       where ar.role = 'technical_support'
      union
      -- 2. The report sub-pages, spelled out so the matrix shows them ticked.
      select unnest(array['mod:/exports/consumption','mod:/exports/kpi','mod:/exports/unused'])
      union
      -- 3. Every master value list that exists, same reason. Data, so derived.
      select 'mod:/masters/' || ml.name
        from (select distinct name from public.masters where coalesce(name,'') <> '') ml
    ) u;

  -- ---------------------------------------------------------------------
  -- A CLONE SEEDS A ROLE ONCE. IT IS NOT A STANDING MIRROR.
  -- (The user's rule, 2026-09-13, and it applies to ALL cloning here.)
  --
  -- This used to MERGE Technical Support's row into Zoho Migration on every
  -- run, and that is how `review.edit` reached a role built to change
  -- nothing: an administrator ticked it on Technical Support -- their
  -- decision, and it stands -- and the next run of rbac.sql copied it across.
  -- Zoho Migration silently gained the right to write Daily Call Reviews,
  -- which RAISE FIELD FAILURE REPORTS, and a quality record can never be
  -- deleted (0166). Nobody ticking a box on one role expects a DIFFERENT role
  -- to change, and nothing on the screen said that it had.
  --
  -- Two roles kept identical forever are one role with two names; the point of
  -- a separate role is that it can DIVERGE -- narrowed as the migration
  -- proceeds, and revoked when it ends, without touching the support login.
  -- So once the role exists it is the administrator's, and this file stops
  -- having an opinion about it. Divergence is the expected state, not drift.
  if exists (select 1 from public.app_roles r where r.role = 'zoho_migration') then
    raise notice 'Zoho Migration already exists -- left exactly as it is. A clone seeds a role once; it is not kept in sync.';
  else
    insert into public.app_roles (role, label, permissions)
    values ('zoho_migration', 'Zoho Migration', granted);

    -- Reported from what the role ACTUALLY has, and only on the run that
    -- seeded it. It used to report `granted` every time -- so a run that
    -- deliberately changed nothing still announced a clone, which is the
    -- report saying the opposite of what happened.
    select count(*) into n_mods
      from jsonb_array_elements_text(granted) as e(v) where e.v like 'mod:%';

    raise notice 'Zoho Migration CREATED: % permission(s), % module/page key(s) -- seeded from Technical Support, read-only. It is the administrator''s from here; this file will not touch it again.',
      jsonb_array_length(granted), n_mods;
  end if;
end $zm$;

-- ------------------------------------------------------------------------
-- 0156_remove_super_admin_mmdev74.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- REVOKE A SUPER ADMIN.
--
-- The user, 2026-09-09: "mmdev74@gmail.com - remove him from Admin".
--
-- SUPER ADMIN IS TWO THINGS IN TWO PLACES and both have to go, or the account
-- keeps real access:
--
--   * `public.app_super_admins` -- what is_super_admin() reads, so what
--     POSTGRES allows. Removed here.
--   * `SUPER_ADMINS` in src/lib/auth.tsx -- what the BROWSER offers. Removed in
--     the same change; without it the screens still hand them every button and
--     the database quietly refuses each one, which reads as the app being
--     broken rather than as access having been withdrawn.
--
-- AND `profiles.role` IS A THIRD PLACE. is_admin() is `role = 'admin'` OR the
-- super-admin row -- so dropping only the row can leave an ordinary Admin
-- standing, which is not what "remove him from Admin" means. It is downgraded
-- below, and only if it currently says admin.
--
-- DOWNGRADED TO `engineer`, the system's own default for a login with no role
-- set, chosen because it is the least this codebase can express: there is no
-- "no access" ROLE. If the intent is that this person should not sign in AT
-- ALL, that is a different action -- set their User Master row inactive -- and
-- it is deliberately not assumed here. Revoking rights is safe to do without
-- asking; deciding somebody should be locked out entirely is not.
--
-- 0008 SEEDS THAT ROW, and this migration must stay AFTER it in the `rbac`
-- module. Replaying rbac.sql runs 0008's insert (which puts the address back)
-- and then this delete -- in that order, the account ends revoked. The other
-- order would silently restore a super admin on every bundle replay, which is
-- exactly the class of fault this project has been bitten by.
--
-- Idempotent, and it says what it did.
-- ===========================================================================

do $rm$
declare
  v_email text := 'mmdev74@gmail.com';
  n_super integer := 0;
  n_role  integer := 0;
begin
  delete from public.app_super_admins where lower(email) = lower(v_email);
  get diagnostics n_super = row_count;

  update public.profiles
     set role = 'engineer'
   where lower(email) = lower(v_email)
     and lower(coalesce(role, '')) = 'admin';
  get diagnostics n_role = row_count;

  raise notice 'Super admin revoked for %: % super-admin row(s) removed, % profile(s) downgraded from admin',
    v_email, n_super, n_role;

  if n_super = 0 and n_role = 0 then
    raise notice '  (nothing to do -- already revoked, or that address has no rows here)';
  end if;
end $rm$;

-- ------------------------------------------------------------------------
-- 0343_add_super_admin_dccr_mirror.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- ADD A SUPER ADMIN: the DCCR mirror's own login.
--
-- The user, 2026-10-04: "Add a User to Supabase - DCCR_Mirror@gmail.com, Add
-- it to Admin - Hardcode it like service.almsind@gmail.com".
--
-- The DCCR mirror in CallReg.gs signs in as DCCR_EMAIL to read the review
-- register on its four daily runs; the register is bounded by the call
-- policies, so the login must see every call. A super admin does.
--
-- SUPER ADMIN IS TWO PLACES and both change together (0156): this row is what
-- POSTGRES allows; `SUPER_ADMINS` in src/lib/auth.tsx is what the BROWSER
-- offers, changed in the same commit. `check:ui` compares the two.
--
-- THE LOGIN ITSELF IS NOT MADE HERE. A row in auth.users carries the password
-- hash, and a password written into a migration lives in the repository's
-- history for good. It is created in Supabase (Authentication -> Add user) or
-- from User Master, and this row makes whoever signs in with the address a
-- super admin from that moment. Supabase stores the address in lower case;
-- is_super_admin() compares in lower case too.
--
-- AFTER 0156 in the rbac module, like any later change to this list.
-- Idempotent, and it says what it did.
-- ===========================================================================

do $add$
declare
  v_email text := 'dccr_mirror@gmail.com';
  n integer := 0;
begin
  insert into public.app_super_admins (email) values (v_email)
  on conflict (email) do nothing;
  get diagnostics n = row_count;
  raise notice 'Super admin %: %', v_email,
    case when n = 1 then 'added' else 'already present' end;
  if not exists (select 1 from auth.users where lower(email) = v_email) then
    raise notice '  no login with that address yet -- create it in Supabase (Authentication -> Add user)';
  end if;
end $add$;

-- ------------------------------------------------------------------------
-- 0171_stock_out_module.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0171 — STOCK OUT IS A PAGE, so it needs a permission of its own.
--
-- The user, 2026-09-12: "Add a Separate Page as Stock Out - the same FlatList
-- under Pending Dispatch", and with it "Match the Roles and Permissions as per
-- the Re-arrangement."
--
-- The list was a TAB on Pending Dispatch, so the right to read it was the right
-- to open that queue — one key for two different questions. Splitting them is
-- the point of the move: Commercial chasing a DC and a Reporting Manager
-- checking what an engineer was sent both want the record of what WENT OUT, and
-- neither has any business in the Stores queue.
--
-- NOBODY LOSES ANYTHING TODAY. Every role that can open Pending Dispatch is
-- given the new key, so the tab they were reading yesterday is the page they
-- read tomorrow. From here on the two can be granted apart, which they could
-- not be before.
--
-- MERGED, NEVER OVERWRITTEN (CLAUDE.md, and the reason is in 0126): an
-- administrator may have tuned a role, and a grant that replaces the array
-- silently throws that away. `permissions ? 'x'` is the jsonb "contains this
-- key" test, so this touches only the roles that actually hold the old key.
--
-- A ROLE WITH NO PERMISSIONS AT ALL IS NOT TOUCHED, and that is correct rather
-- than an oversight: an empty array means "not configured", and has_perm()
-- falls back to the code defaults for it (which carry every non-admin module,
-- this one included). Writing one key into that row would turn the fallback OFF
-- and leave the role holding exactly one permission — the "role that sees
-- NOTHING" fault in CLAUDE.md, caused by the fix for it.
-- ===========================================================================

update public.app_roles ar
   set permissions = (
         select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
           from (
             select jsonb_array_elements_text(ar.permissions) as v
             union
             select 'mod:/stock-out' as v
           ) u
       ),
       updated_at = now()
 where ar.permissions ? 'mod:/spare-dispatch'
   and not (ar.permissions ? 'mod:/stock-out');

-- ---------------------------------------------------------------------------
-- THE MENU MOVES NEED NO GRANT, and it is worth saying why rather than leaving
-- a reader to wonder what is missing.
--
-- A page's permission is `mod:<path>` — the PATH, not the heading it sits
-- under. Daily Call Review moving to Quality & Analytics, Call Review and
-- Customer Feedback to Service Calls, and the two bulk uploaders to
-- Administration change which heading they are listed beneath in the menu and
-- in the Roles & Permissions matrix; none of them changes a path, so no role
-- gains or loses access. The headings are how the matrix is READ, and matching
-- them to the menu is what stops an administrator granting the wrong row.
--
-- The two uploaders were `adminOnly` before the move and still are — their keys
-- (mod:/report-mapping, mod:/pm-bulk-upload) are unchanged, and administration
-- is where they now appear rather than a new right they now need.
-- ---------------------------------------------------------------------------

-- ------------------------------------------------------------------------
-- 0172_user_signatures.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0172 — A USER MAY SAVE THEIR SIGNATURE.
--
-- The user's ask (2026-09-12): "Add a Provision for users to Save their
-- signatures." The documents that leave this system all end in a signature
-- block somebody signs by hand after printing — the Delivery Challan's two
-- blocks, the Declaration, the Field Failure Report's "Signature:" line. A
-- saved signature is what lets the document carry it already.
--
-- WHY A TABLE OF ITS OWN RATHER THAN A COLUMN ON `profiles`.
--
-- Two reasons, and the second is the important one.
--
--  1. `profiles` cannot be written by its owner. Its only write policy is
--     `profiles_admin_write` — `has_perm('users.manage')` (0008) — so adding a
--     column there would mean either widening that policy or asking an
--     administrator to paste in everybody's signature. RLS grants by ROW, not
--     by column: a policy letting somebody update their own profile row to save
--     a signature lets them update every other field on it too, and the role
--     guard beside it exists precisely because that row is where privilege
--     lives. A separate table is the only way to say "your signature is yours"
--     without saying "your profile is yours".
--
--  2. A SIGNATURE IS NOT ORDINARY PROFILE DATA. It is the mark that stands for
--     a person's assent on a quality record. What it is worth depends entirely
--     on nobody else being able to obtain it or to set it.
--
-- SO: READ YOUR OWN, WRITE YOUR OWN, AND NOBODY ELSE'S — NOT EVEN AN
-- ADMINISTRATOR'S.
--
--   * No administrator read. An administrator has every other right in this
--     system and this one is deliberately withheld: a signature image that a
--     second person can obtain is one they can put on anything, and there is
--     then no sense in which the mark on a printed report is that person's.
--     Admins can see WHETHER somebody has saved one (the view below), which is
--     the only thing administration actually needs — to chase the ones who
--     have not.
--   * No administrator write, for the same reason stated the other way round:
--     a signature somebody else can SET is a signature nobody signed.
--   * REMOVAL is the one administrative act, and it is a FUNCTION rather than
--     a policy — see the note on usig_delete below for why a policy could not
--     express it. A person who has left should not leave their mark in the
--     database, and they are by then unable to remove it themselves. Removal
--     destroys nothing that was signed: the printed document is the record,
--     not this row.
--
-- WHAT THIS MEANS ON A DOCUMENT, and it is a real limitation rather than an
-- oversight: a document prints a saved signature only when the person printing
-- it is the person the block names. Printing somebody else's block leaves it
-- blank to be signed by hand, exactly as today. That is the correct outcome —
-- the alternative is a system that signs documents on people's behalf.
-- ===========================================================================

create table if not exists public.user_signatures (
  user_id     uuid primary key references auth.users(id) on delete cascade,
  -- A PNG data URI. Held as text rather than in a bucket: it is a few KB of
  -- ink, it is read only by the one person it belongs to, and a storage object
  -- would need its own access rules to say the same thing this table says.
  signature   text        not null default '',
  -- The name and title printed UNDER the mark. Taken from the profile when the
  -- signature is saved rather than read live, because a printed document should
  -- carry the name the person signed as.
  name_line   text        not null default '',
  title_line  text        not null default '',
  updated_at  timestamptz not null default now()
);

alter table public.user_signatures enable row level security;

-- YOUR OWN, AND ONLY YOUR OWN. Four policies rather than one `for all`, because
-- delete is the only command with a different answer and a single policy could
-- not express that.
drop policy if exists usig_read on public.user_signatures;
create policy usig_read on public.user_signatures for select to authenticated
  using (user_id = (select auth.uid()));

drop policy if exists usig_insert on public.user_signatures;
create policy usig_insert on public.user_signatures for insert to authenticated
  with check (user_id = (select auth.uid()));

drop policy if exists usig_update on public.user_signatures;
create policy usig_update on public.user_signatures for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- YOURS, AND ONLY YOURS — no `or is_admin()` here, and that is a correction
-- rather than a simplification. It was written that way first and the test
-- proved it did nothing: PostgreSQL applies the SELECT policy to a
-- `DELETE ... WHERE`, because the statement has to READ the row to find it. An
-- administrator who cannot see the row therefore cannot delete it, and the
-- clause reported `DELETE 0` with no error — a permission that looks granted
-- and is not.
--
-- The two ways out are opposite in kind: give administrators a SELECT policy
-- (which hands them the image, destroying the point of the table), or make
-- removal an explicit administrative ACT with its own function. The function is
-- below.
drop policy if exists usig_delete on public.user_signatures;
create policy usig_delete on public.user_signatures for delete to authenticated
  using (user_id = (select auth.uid()));

grant select, insert, update, delete on public.user_signatures to authenticated;

-- ---------------------------------------------------------------------------
-- REMOVING A LEAVER'S SIGNATURE. A person who has left should not leave their
-- mark in the database, and they are by then unable to remove it themselves.
--
-- Definer, so it does not need a read policy to work; it returns whether there
-- was one to remove, and NEVER the signature itself — an administrator's
-- authority here is to destroy the mark, not to hold it. Nothing that was
-- signed is affected: the printed document is the record, not this row.
-- ---------------------------------------------------------------------------
create or replace function public.remove_user_signature(p_user uuid)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_had boolean;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may remove another person''s signature.';
  end if;
  if p_user = auth.uid() then
    raise exception 'Use your own Profile page to remove your signature.';
  end if;
  select true into v_had from public.user_signatures where user_id = p_user;
  delete from public.user_signatures where user_id = p_user;
  return coalesce(v_had, false);
end $$;

revoke all on function public.remove_user_signature(uuid) from public;
grant execute on function public.remove_user_signature(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- THE STAMP. `updated_at` is the database's to set: a client that can choose
-- when its own signature was last changed can make one look current.
-- ---------------------------------------------------------------------------
create or replace function public.user_signature_stamp()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  -- The owner is the session's, not the caller's to name. The insert policy
  -- already refuses another user's id; this makes the column unable to CARRY
  -- one, so the two cannot disagree.
  new.user_id := coalesce(auth.uid(), new.user_id);
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists zz_user_signature_stamp on public.user_signatures;
create trigger zz_user_signature_stamp before insert or update on public.user_signatures
  for each row execute function public.user_signature_stamp();

-- ---------------------------------------------------------------------------
-- WHO HAS SAVED ONE — the image deliberately absent.
--
-- This is what administration needs and all it needs: chasing the people who
-- have NOT saved a signature does not require seeing the ones who have. So this
-- returns a boolean and a date, and there is no path anywhere that returns
-- somebody else's image.
--
-- A FUNCTION, NOT A VIEW, and the difference is not stylistic. To report across
-- rows the caller cannot read it has to be `security definer`, and a definer
-- VIEW over RLS-protected tables is the exact fault this project shipped three
-- times (0040/0050/0057 — `calls` without security_invoker handed every row to
-- every signed-in user); `check:views` now refuses one, correctly, and writing
-- an exception into that check to admit this would blunt the control that
-- catches the real thing. A definer function is the instrument that says
-- "elevated on purpose" out loud, carries its own authority test, and returns
-- only the two columns it means to.
-- ---------------------------------------------------------------------------
create or replace function public.user_signature_status()
returns table (user_id uuid, full_name text, email text, has_signature boolean, signed_at timestamptz)
language plpgsql security definer set search_path = public as $$
begin
  if not (public.is_admin() or public.has_perm('users.manage')) then
    raise exception 'Only User Access may see who has saved a signature.';
  end if;
  return query
    select p.id, p.full_name, p.email,
           (s.user_id is not null and coalesce(btrim(s.signature), '') <> ''),
           s.updated_at
      from public.profiles p
      left join public.user_signatures s on s.user_id = p.id
     order by p.full_name;
end $$;

revoke all on function public.user_signature_status() from public;
grant execute on function public.user_signature_status() to authenticated;

-- ------------------------------------------------------------------------
-- 0180_zoho_readonly.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0180 — ZOHO MIGRATION GIVES BACK `review.edit`.
--
-- Found by _status.sql on the live project and confirmed with the user
-- (2026-09-13): the Zoho Migration row reported NO, and the clause that fired
-- was not drift -- it was A WRITE ACTION on a role whose whole definition is
-- that it holds none.
--
-- WHAT IT COULD DO, established on a database rather than read off the policy:
-- `review.edit` grants ALL commands on `call_reviews`. A user on the role
-- answered Review 2 with Risk to Patient = Yes, the 0167 trigger fired, and
-- FFR - 001/26 was raised in their name. By 0166 that record can never be
-- deleted. So the role could create permanent quality records -- which is a
-- long way from "read-only", and further still from what a data migration
-- needs.
--
-- HOW IT GOT THERE, and it was nobody's mistake at the tick: an administrator
-- granted `review.edit` to TECHNICAL SUPPORT, deliberately. 0155 then merged
-- Technical Support's whole row into Zoho Migration on every run of rbac.sql,
-- so the tick crossed to a role it was never aimed at, silently. 0155 no
-- longer does that -- a clone seeds a role ONCE and is not a standing mirror
-- (the user's rule, and it applies to all cloning here) -- but the key is
-- already on the live row, and a file that only stops the leak leaves it
-- standing. This removes it.
--
-- TECHNICAL SUPPORT KEEPS IT. That was the user's decision, asked before
-- changing anything: the grant there was intended, and revoking a permission
-- an administrator chose is not a tidy-up. This file names ONE role and ONE
-- key for that reason.
--
-- NOTHING IS UNDONE. Any Field Failure Report or review already recorded under
-- this role stays exactly as it is -- 0049's rule, and the reason the register
-- is worth anything. Withdrawing access is not a way of editing the record.
-- ===========================================================================

do $zr$
begin
  if to_regclass('public.app_roles') is null then
    raise notice 'app_roles is missing -- run rbac.sql first';
    return;
  end if;

  if not exists (select 1 from public.app_roles where role = 'zoho_migration') then
    raise notice 'zoho_migration is not there -- nothing to revoke';
    return;
  end if;

  if not exists (select 1 from public.app_roles
                  where role = 'zoho_migration' and permissions ? 'review.edit') then
    raise notice 'zoho_migration does not hold review.edit -- nothing to do';
    return;
  end if;

  -- `-` on a jsonb ARRAY removes every matching element by value. Only this
  -- key and only this role: an administrator may have tuned the rest, and a
  -- rebuild of the row from a literal list would quietly discard that.
  update public.app_roles
     set permissions = permissions - 'review.edit',
         updated_at  = now()
   where role = 'zoho_migration';

  raise notice 'Zoho Migration: review.edit revoked. It can no longer write a Daily Call Review, so it can no longer raise a Field Failure Report.';
end $zr$;

-- ------------------------------------------------------------------------
-- 0250_master_write_policy_once_per_query.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE MACHINE REGISTER AND THE PARTY MASTER: A PERMISSION ASKED ONCE PER
-- QUERY, NOT ONCE PER ROW.
--
-- Reported 2026-09-29: a device downloading the machine register for a test
-- engineer sat at "0 so far" for good, and even the administrator's download
-- took about seven minutes for 11,000 machines. `_why_wont_the_machines_download.sql`
-- on the live project measured the first 1,000 machines at 322 ms as the SQL
-- editor and 24,687 ms as a signed-in user -- over the API's 20-second limit,
-- so the request was cancelled every time and the device retried for ever.
--
-- THE CAUSE IS THE *WRITE* POLICY, NOT THE READ ONE. 0008 gives products,
-- parties and parts two policies:
--
--     <t>_read   FOR SELECT  using (auth.role() = 'authenticated')
--     <t>_write  FOR ALL     using (public.has_perm('masters.edit'))
--
-- `FOR ALL` INCLUDES SELECT, and Postgres ORs every SELECT policy together --
-- so every read of these tables also asks has_perm('masters.edit'), and asks
-- it FIRST. Written bare, that is a PER-ROW call, each one reading app_roles:
-- 20,002 machines and 5,876 customers, on every page of every download. The
-- plan shows it on the scan of each table:
--
--     Filter: (has_perm('masters.edit') OR ($0 = 'authenticated'))
--
-- WRAPPED IN A SCALAR SUBQUERY -- (select has_perm(...)) -- it becomes an
-- InitPlan: worked out ONCE for the query and the answer reused, which is what
-- `_fix_product_database_timeout.sql` did for the cover tables. Measured on a
-- database loaded to the live sizes (20,002 machines, 5,876 parties, 17,689
-- contract lines), as a signed-in user, first 1,000 machines of the view the
-- device reads:
--
--     as written (bare)       ~920 ms
--     wrapped                 11-17 ms
--
-- and the Party Master page 45 ms -> 1 ms. Wrapping the READ policy instead
-- was tried first and changed nothing (~920 ms either way), which is how the
-- write policy was found; the read policy is left exactly as it is.
--
-- NOBODY GAINS OR LOSES A ROW OR A WRITE. Same function, same argument, same
-- USING and WITH CHECK -- has_perm('masters.edit') does not depend on the row,
-- so asking it once gives the answer asking it 20,000 times gave.
--
-- `masters_write` is NOT here: 0067 dropped it and replaced it with per-list
-- insert/update/delete policies.
--
-- GUARDED on each table and policy, so it is harmless on a project behind on
-- other modules; ALTER POLICY rather than drop-and-create, so there is never a
-- moment with no write policy at all.
-- ===========================================================================

do $$
declare t text;
begin
  foreach t in array array['products', 'parties', 'parts'] loop
    if to_regclass('public.' || t) is not null
       and exists (select 1 from pg_policies
                    where schemaname = 'public' and tablename = t and policyname = t || '_write') then
      execute format(
        'alter policy %I on public.%I using ((select public.has_perm(''masters.edit''))) '
        || 'with check ((select public.has_perm(''masters.edit'')))',
        t || '_write', t);
    end if;
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0286_permission_parents.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0286 — A PERMISSION CAN HAVE A PARENT; RBAC-OWNED RULES MOVE TO THE NEW KEYS
--
-- Findings 57-67 (docs/PERMISSIONS_REVIEW.md), the user's decisions of
-- 2026-09-30: "63, 64: It should show the Individual View's Control Action and
-- its Check Box" -- each screen gets keys of its own, today's grants copied
-- across (0298) so nobody gains or loses anything on the day it ships -- and
-- "67: Break it down", with the old key kept as the PARENT of the new ones, so
-- a role holding it keeps everything until an administrator unticks it.
-- The parent rule itself is in has_perm() (0286, public.perm_parents).
--
-- This file: public.perm_parents and has_perm(); call_perm(), which picks the
-- register a UCN is on; visit reports, feedback, user administration, shared
-- charts and table layouts, and master records -- the rules rbac owns.
-- ===========================================================================

-- ---- 1. A key's PARENTS: holding the parent satisfies the child ----------
-- The client has the same list (PERM_PARENTS in src/lib/rbac.ts); check:ui
-- compares the two word for word. Rewritten whole on every run, so the table
-- is always exactly this list.
create table if not exists public.perm_parents (
  child  text not null,
  parent text not null,
  primary key (child, parent)
);
alter table public.perm_parents enable row level security;
revoke all on public.perm_parents from anon, authenticated;
do $$
begin
  if to_regprocedure('public.sys_columns_attach(regclass)') is not null then
    perform public.sys_columns_attach('public.perm_parents'::regclass);
  end if;
end $$;

delete from public.perm_parents;
insert into public.perm_parents (child, parent) values
  ('calls.edit.complaint', 'calls.edit'),
  ('calls.edit.customer', 'calls.edit'),
  ('calls.edit.vigilance', 'calls.edit'),
  ('calls.edit.contact', 'calls.edit'),
  ('install.edit.complaint', 'install.edit'),
  ('install.edit.customer', 'install.edit'),
  ('install.edit.vigilance', 'install.edit'),
  ('install.edit.contact', 'install.edit'),
  ('pm.edit.complaint', 'pm.edit'),
  ('pm.edit.customer', 'pm.edit'),
  ('pm.edit.vigilance', 'pm.edit'),
  ('pm.edit.contact', 'pm.edit'),
  ('calls.report.visit', 'calls.report'),
  ('install.report.visit', 'install.report'),
  ('pm.report.visit', 'pm.report'),
  ('visit.spares', 'calls.report'),
  ('visit.spares', 'install.report'),
  ('visit.spares', 'pm.report'),
  ('visit.feedback', 'calls.report'),
  ('visit.feedback', 'install.report'),
  ('visit.feedback', 'pm.report'),
  ('cover.edit.entries', 'cover.edit'),
  ('cover.edit.delete', 'cover.edit'),
  ('contract.edit.entries', 'contract.edit'),
  ('contract.edit.delete', 'contract.edit'),
  ('masters.edit.records', 'masters.edit'),
  ('masters.edit.kyc', 'masters.edit'),
  ('masters.edit.rename_part', 'masters.edit'),
  ('masters.edit.swap_serviceman', 'masters.edit'),
  ('users.manage.details', 'users.manage'),
  ('users.manage.create', 'users.manage'),
  ('users.manage.disable', 'users.manage'),
  ('users.manage.access', 'users.manage'),
  ('users.manage.settings', 'users.manage'),
  -- One key to add, one to edit, one to delete per master (0325, 2026-10-03).
  -- 0325 inserts the same rows for a database that ran this file before them.
  ('masters.parties.add', 'masters.edit.records'),
  ('masters.parties.add', 'masters.edit'),
  ('masters.parties.edit', 'masters.edit.records'),
  ('masters.parties.edit', 'masters.edit'),
  ('masters.parties.delete', 'masters.edit'),
  ('masters.parts.add', 'masters.edit.records'),
  ('masters.parts.add', 'masters.edit'),
  ('masters.parts.edit', 'masters.edit.records'),
  ('masters.parts.edit', 'masters.edit'),
  ('masters.parts.delete', 'masters.edit'),
  ('masters.product_master.add', 'masters.edit.records'),
  ('masters.product_master.add', 'masters.edit'),
  ('masters.product_master.edit', 'masters.edit.records'),
  ('masters.product_master.edit', 'masters.edit'),
  ('masters.product_master.delete', 'masters.edit'),
  -- D-129 (0401, 2026-10-05): an editor of the review reads its answers.
  ('review.view', 'review.edit');

-- has_perm() keeps its shape and its NULL: with no signed-in user
-- my_extra_perms() is NULL, and several callers rely on `if not has_perm()`
-- then being skipped for an import or a scheduled run, as it always was.
create or replace function public.has_perm(action text)
returns boolean language sql stable security definer set search_path = public as $$
  with role_row as (
    select r.permissions from public.app_roles r
     where r.role = public.my_role() and jsonb_array_length(coalesce(r.permissions, '[]'::jsonb)) > 0
  ),
  fallback as (
    select r.permissions from public.app_roles r where r.role = 'engineer'
  ),
  perms as (
    select permissions from role_row
    union all
    select permissions from fallback where not exists (select 1 from role_row)
  ),
  keys as (
    select action as k
    union all
    select pp.parent from public.perm_parents pp where pp.child = action
  )
  select public.is_admin()
      or exists (select 1 from perms p, keys where p.permissions ? keys.k)
      or (select bool_or(public.my_extra_perms() ? keys.k) from keys);
$$;
grant execute on function public.has_perm(text) to authenticated;

-- ---- 2. Which register a call is on decides which key governs it ---------
-- plpgsql so its body is not resolved at creation: this module runs before
-- the call tables exist on a fresh apply.
create or replace function public.call_perm(p_ucn text, p_verb text)
returns boolean language plpgsql stable security definer set search_path = public as $$
declare v_reg text := 'calls';
begin
  if exists (select 1 from public.installation_calls where ucn = p_ucn) then v_reg := 'install';
  elsif exists (select 1 from public.pm_calls where ucn = p_ucn) then v_reg := 'pm';
  end if;
  return public.has_perm(v_reg || '.' || p_verb);
end $$;
revoke execute on function public.call_perm(text, text) from public, anon;
grant  execute on function public.call_perm(text, text) to authenticated;

-- ---- 3. Visit reports: the call's own register's "save a visit" ----------
-- Split out of FOR ALL, which is also a read policy and would have run
-- call_perm() once per row on every read of the visit history.
drop policy if exists reports_write  on public.reports;
drop policy if exists reports_insert on public.reports;
drop policy if exists reports_update on public.reports;
drop policy if exists reports_delete on public.reports;
create policy reports_insert on public.reports for insert
  with check (public.call_perm(ucn, 'report.visit'));
create policy reports_update on public.reports for update
  using (public.call_perm(ucn, 'report.visit')) with check (public.call_perm(ucn, 'report.visit'));
create policy reports_delete on public.reports for delete
  using (public.call_perm(ucn, 'report.visit'));

-- ---- 4. Customer feedback taken on a visit -------------------------------
drop policy if exists fb_read  on public.feedback;
drop policy if exists fb_write on public.feedback;
create policy fb_read on public.feedback for select
  using (public.has_perm('feedback.view') or public.has_perm('visit.feedback'));
create policy fb_write on public.feedback for insert
  with check (public.has_perm('visit.feedback') or public.has_perm('feedback.view'));

-- ---- 5. User administration, split five ways ------------------------------
drop policy if exists profiles_admin_write  on public.profiles;
drop policy if exists profiles_admin_insert on public.profiles;
drop policy if exists profiles_admin_update on public.profiles;
drop policy if exists profiles_admin_delete on public.profiles;
drop policy if exists profiles_self_read    on public.profiles;
create policy profiles_admin_insert on public.profiles for insert
  with check ((select public.has_perm('users.manage.create')));
create policy profiles_admin_update on public.profiles for update
  using ((select public.has_perm('users.manage.details') or public.has_perm('users.manage.access') or public.has_perm('users.manage.disable') or public.has_perm('users.manage.create'))) with check ((select public.has_perm('users.manage.details') or public.has_perm('users.manage.access') or public.has_perm('users.manage.disable') or public.has_perm('users.manage.create')));
create policy profiles_admin_delete on public.profiles for delete
  using ((select public.has_perm('users.manage.disable')));
create policy profiles_self_read on public.profiles for select
  using (id = auth.uid() or public.is_admin() or (select public.has_perm('users.manage.details') or public.has_perm('users.manage.access') or public.has_perm('users.manage.disable') or public.has_perm('users.manage.create')));

drop policy if exists ud_write  on public.user_directory;
drop policy if exists ud_insert on public.user_directory;
drop policy if exists ud_update on public.user_directory;
drop policy if exists ud_delete on public.user_directory;
create policy ud_insert on public.user_directory for insert
  with check ((select public.has_perm('users.manage.details') or public.has_perm('users.manage.create')));
create policy ud_update on public.user_directory for update
  using ((select public.has_perm('users.manage.details'))) with check ((select public.has_perm('users.manage.details')));
create policy ud_delete on public.user_directory for delete
  using ((select public.has_perm('users.manage.disable')));

-- ---- 6. Shared charts and table layouts get keys of their own ------------
drop policy if exists sc_write_shared on public.saved_charts;
create policy sc_write_shared on public.saved_charts for all
  using (role is not null and (public.is_admin() or public.has_perm('charts.share')))
  with check (role is not null and (public.is_admin() or public.has_perm('charts.share')));

drop policy if exists rtv_write on public.role_table_views;
create policy rtv_write on public.role_table_views for all
  using (public.is_admin() or public.has_perm('layouts.share'))
  with check (public.is_admin() or public.has_perm('layouts.share'));

-- ---- 7. Master records: the general child of masters.edit ----------------
do $$
declare t text;
begin
  foreach t in array array['parties', 'parts', 'products'] loop
    if to_regclass('public.' || t) is not null then
      execute format('drop policy if exists %1$s_write on public.%1$s', t);
      execute format('create policy %1$s_write on public.%1$s for all '
                     'using ((select public.has_perm(''masters.edit.records''))) '
                     'with check ((select public.has_perm(''masters.edit.records'')))', t);
    end if;
  end loop;
end $$;

CREATE OR REPLACE FUNCTION public.profiles_role_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  -- Only a caller through the API is gated: the SQL editor, an import and a
  -- scheduled job are not a person holding keys (the `role` setting survives
  -- SECURITY DEFINER, current_user does not), and an administrator is
  -- everybody.
  api  boolean := coalesce(current_setting('role', true), 'none') in ('authenticated', 'anon');
  self boolean := new.id = auth.uid();
begin
  if tg_op = 'INSERT' then
    -- A PERSON'S OWN FIRST SIGN-IN (0033) creates their profile with the role
    -- their User Master row carries -- a role somebody holding "Assign roles"
    -- put there (ud_role_guard below). Anybody else creating a login decides
    -- what it may do only if they may assign roles: "Create logins" alone
    -- makes an Engineer with nothing extra (finding 67).
    if api and not self and not public.is_admin()
       and (coalesce(nullif(btrim(new.role), ''), 'engineer') <> 'engineer'
            or jsonb_array_length(coalesce(new.extra_permissions, '[]'::jsonb)) > 0)
       and not coalesce(public.has_perm('users.manage.access'), false) then
      raise exception 'RBAC: creating a login with a role other than Engineer, or with extra permissions, needs "Assign roles & grant permissions"';
    end if;
    if not self and lower(coalesce(new.role, '')) = 'admin' and api and not public.is_admin() then
      raise exception 'RBAC: granting admin requires an administrator';
    end if;
    return new;
  end if;

  -- WHICH KEY MAY MOVE WHICH COLUMN (0286): the role and extra permissions are
  -- "Assign roles & grant permissions"; switching a login on or off is
  -- "Disable or delete logins".
  if api and not public.is_admin() then
    if (new.role is distinct from old.role or new.extra_permissions is distinct from old.extra_permissions)
       and not coalesce(public.has_perm('users.manage.access'), false) then
      raise exception 'RBAC: changing a role or permissions needs "Assign roles & grant permissions"';
    end if;
    if new.active is distinct from old.active
       and not coalesce(public.has_perm('users.manage.disable'), false) then
      raise exception 'RBAC: switching a login on or off needs "Disable or delete logins"';
    end if;
  end if;
  if new.role is distinct from old.role or new.extra_permissions is distinct from old.extra_permissions then
    if self and not public.is_super_admin() then
      raise exception 'RBAC: you cannot change your own role or permissions';
    end if;
  end if;
  if new.role is distinct from old.role
     and lower(new.role) = 'admin' and not public.is_admin() then
    raise exception 'RBAC: granting admin requires an administrator';
  end if;
  return new;
end $function$;

-- ...and it now fires on INSERT as well: a login created with a role was not
-- checked at all, so "Manage users" could create an Admin outright.
drop trigger if exists profiles_role_guard on public.profiles;
create trigger profiles_role_guard before insert or update on public.profiles
  for each row execute function public.profiles_role_guard();

-- THE ROLE A USER MASTER ROW GRANTS AT FIRST SIGN-IN (0033) is assigning a
-- role, so it asks the same key -- or "Edit User Master details" alone could
-- give a new joiner any role before they ever signed in.
create or replace function public.user_directory_role_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if coalesce(current_setting('role', true), 'none') in ('authenticated', 'anon')
     and not public.is_admin()
     and ((tg_op = 'INSERT' and coalesce(btrim(new.role), '') <> '')
          or (tg_op = 'UPDATE' and new.role is distinct from old.role))
     and not coalesce(public.has_perm('users.manage.access'), false) then
    raise exception 'RBAC: setting the role a person signs in with needs "Assign roles & grant permissions"';
  end if;
  return new;
end $$;
revoke execute on function public.user_directory_role_guard() from public, anon, authenticated;
do $$
begin
  if to_regclass('public.user_directory') is not null
     and exists (select 1 from information_schema.columns
                  where table_schema = 'public' and table_name = 'user_directory' and column_name = 'role') then
    drop trigger if exists ud_role_guard on public.user_directory;
    create trigger ud_role_guard before insert or update on public.user_directory
      for each row execute function public.user_directory_role_guard();
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.user_signature_status()
 RETURNS TABLE(user_id uuid, full_name text, email text, has_signature boolean, signed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not (public.is_admin() or public.has_perm('users.manage.details')) then
    raise exception 'Only User Access may see who has saved a signature.';
  end if;
  return query
    select p.id, p.full_name, p.email,
           (s.user_id is not null and coalesce(btrim(s.signature), '') <> ''),
           s.updated_at
      from public.profiles p
      left join public.user_signatures s on s.user_id = p.id
     order by p.full_name;
end $function$;

CREATE OR REPLACE FUNCTION public.set_role_table_view(p_storage_key text, p_role text, p_view jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_at bigint := (extract(epoch from now()) * 1000)::bigint;
begin
  if not (public.is_admin() or public.has_perm('layouts.share')) then
    raise exception 'RBAC: only an administrator can set a layout for a role';
  end if;
  if coalesce(btrim(p_storage_key), '') = '' then
    raise exception 'Which register?';
  end if;

  insert into public.role_table_views (storage_key, role, view, set_at, updated_at, updated_by)
  values (btrim(p_storage_key), coalesce(btrim(p_role), ''), coalesce(p_view, '{}'::jsonb), v_at, now(), auth.uid())
  on conflict (storage_key, role) do update
     set view = excluded.view, set_at = excluded.set_at,
         updated_at = excluded.updated_at, updated_by = excluded.updated_by;

  return v_at;
end $function$;

CREATE OR REPLACE FUNCTION public.clear_role_table_view(p_storage_key text, p_role text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not (public.is_admin() or public.has_perm('layouts.share')) then
    raise exception 'RBAC: only an administrator can clear a layout for a role';
  end if;
  delete from public.role_table_views
   where storage_key = btrim(p_storage_key) and role = coalesce(btrim(p_role), '');
  return found;
end $function$;

-- ------------------------------------------------------------------------
-- 0300_unresolved_login_holds_nothing.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A LOGIN THE ORGANISATION DOES NOT KNOW HOLDS NO PERMISSION (D-074, FRS-210.5).
--
-- has_perm() takes the caller's role row and, when that row is empty or absent,
-- falls back to the ENGINEER permissions. For a person with a profile that is
-- the documented default ("an empty row means not configured"). For a person
-- with NO profile it meant this: anybody who could create a Supabase Auth
-- account -- with no profile and no User Master row -- held an engineer's write
-- authority through the API. my_role() returns NULL for them, no role row
-- matches NULL, and the fallback answered for them.
--
-- The client already signs such a person in only as "unresolved" and now gives
-- them nothing (src/lib/auth.tsx); this is the half that decides.
--
-- WHAT CHANGES: a SIGNED-IN caller with no profile row gets FALSE from every
-- has_perm(), unless they are a super administrator (app_super_admins, matched
-- by e-mail, as is_admin() already does).
--
-- WHAT DOES NOT:
--   * a caller WITH a profile -- same answer as 0286, the engineer fallback for
--     an empty role row included;
--   * no signed-in user at all (an import, a scheduled run, the SQL editor) --
--     the same expression as 0286, NULL included, because callers rely on
--     `if not has_perm()` being skipped there (0286's note).
-- FALSE, NOT NULL, for the unknown login: `if not has_perm(...) then raise` is
-- how the guards refuse, and NOT NULL is NULL, so a NULL here would have
-- WIDENED what an unknown login may do past the guards rather than narrowed it.
-- ===========================================================================

create or replace function public.has_perm(action text)
returns boolean language sql stable security definer set search_path = public as $$
  with role_row as (
    select r.permissions from public.app_roles r
     where r.role = public.my_role() and jsonb_array_length(coalesce(r.permissions, '[]'::jsonb)) > 0
  ),
  fallback as (
    select r.permissions from public.app_roles r where r.role = 'engineer'
  ),
  perms as (
    select permissions from role_row
    union all
    select permissions from fallback where not exists (select 1 from role_row)
  ),
  keys as (
    select action as k
    union all
    select pp.parent from public.perm_parents pp where pp.child = action
  )
  select case
    when auth.uid() is not null
     and not exists (select 1 from public.profiles p where p.id = auth.uid())
      then coalesce(public.is_super_admin(), false)
    else public.is_admin()
      or exists (select 1 from perms p, keys where p.permissions ? keys.k)
      or (select bool_or(public.my_extra_perms() ? keys.k) from keys)
  end;
$$;
grant execute on function public.has_perm(text) to authenticated;

-- ------------------------------------------------------------------------
-- 0305_reset_password_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- RESETTING A PASSWORD IS users.reset_password -- AND NOT A CHILD OF users.manage.
-- WHAT WAS AN ADMINISTRATOR'S ALONE IS A KEY (the user, 2026-09-30: "All
-- Admin Actions that are greyed out now should be editable from the Role &
-- Permissions. Only the Admin Role should be Greyed out not the Actions.")
--
-- is_admin() becomes has_perm(<key>). An administrator still passes -- has_perm()
-- answers true for is_admin() -- so nobody loses anything, and NOBODY ELSE GAINS
-- ANYTHING ON THE DAY: no role holds the new key until an administrator ticks it
-- on Roles & Permissions. coalesce(..., false) so a NULL (no session) refuses.
--
-- Not a child of users.manage on purpose: a reset lets its holder sign in as
-- the person, so ticking Manage users must never hand it over. And a holder
-- who is not an administrator is refused an Admin's password, and the password
-- of anyone who can grant permissions (see the function) -- otherwise the key
-- would be a route to every other key. A super admin's still needs a super
-- admin. The reset log is readable by the same holders.
-- ===========================================================================

CREATE OR REPLACE FUNCTION public.admin_reset_password(p_email text, p_password text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'auth'
AS $function$
declare v_id uuid; v_email text; v_target_super boolean; v_target_keys jsonb; v_target_role text;
begin
  if not coalesce(public.has_perm('users.reset_password'), false) then
    raise exception 'RBAC: resetting a password needs "Reset a person''s password"';
  end if;
  -- The generator makes 14; this floor is here so the function cannot be used
  -- to set something weak by hand.
  if length(coalesce(p_password, '')) < 10 then
    raise exception 'A reset password must be at least 10 characters';
  end if;

  v_email := lower(btrim(coalesce(p_email, '')));
  select u.id into v_id from auth.users u where lower(u.email) = v_email;
  if v_id is null then raise exception 'No login for %', p_email; end if;

  select exists (select 1 from public.app_super_admins s where lower(s.email) = v_email)
    into v_target_super;
  if v_target_super and not public.is_super_admin() then
    raise exception 'Only a super admin can reset a super admin''s password';
  end if;

  -- A RESET IS A WAY TO SIGN IN AS SOMEBODY, so a holder who is not an
  -- administrator may not reset the password of anyone who could hand them
  -- more than they hold: an Admin, or anyone whose role or own grants carry
  -- rbac.manage, users.manage / users.manage.access, or this key itself.
  if not coalesce(public.is_admin(), false) then
    select lower(coalesce(nullif(btrim(p.role), ''), 'engineer')),
           coalesce(r.permissions, '[]'::jsonb) || coalesce(p.extra_permissions, '[]'::jsonb)
      into v_target_role, v_target_keys
      from public.profiles p
      left join public.app_roles r on r.role = lower(coalesce(nullif(btrim(p.role), ''), 'engineer'))
     where p.id = v_id;
    if v_target_role = 'admin'
       or coalesce(v_target_keys, '[]'::jsonb) ?| array['rbac.manage', 'users.manage', 'users.manage.access', 'users.reset_password'] then
      raise exception 'Only an administrator can reset the password of an administrator or of somebody who can grant permissions';
    end if;
  end if;

  update auth.users
     set encrypted_password = crypt(p_password, gen_salt('bf')),
         updated_at         = now()
   where id = v_id;

  -- End what they had open, so the reset takes effect on every device rather
  -- than leaving an old session signed in. Both tables are Supabase's own and
  -- absent from a bare Postgres, so neither is allowed to fail the reset.
  begin
    delete from auth.sessions where user_id = v_id;
  exception when others then null;
  end;
  begin
    delete from auth.refresh_tokens where user_id::text = v_id::text;
  exception when others then null;
  end;

  insert into public.password_resets (target_email, target_id, reset_by, reset_by_email)
  values (v_email, v_id, auth.uid(), coalesce(auth.email(), ''));

  return v_email;
end $function$;

drop policy if exists pwr_read on public.password_resets;
create policy pwr_read on public.password_resets for select
  using ((select public.is_admin()) or (select public.has_perm('users.reset_password')));

-- ------------------------------------------------------------------------
-- 0308_part_search_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0308 — PART SEARCH CAN BE OPENED BY EVERY ROLE.
--
-- The user, 2026-10-01: "Create a Page under Overview - 'Part Search' ... It's
-- a Read only View - No Action Buttons or Edit Access for anyone - Including
-- Admin ... No Download Option as well." Asked who may open it: every role.
--
-- A NEW SCREEN IS NOT DONE UNTIL ROLES & PERMISSIONS KNOWS (0195): the code
-- default reaches only a role whose stored set is EMPTY, so without this the
-- page ships invisible to every configured role.
--
-- ONLY THE PAGE KEY. The screen offers no action, so there is nothing else to
-- grant; reading `parts` was already open to every signed-in user (0008
-- parts_read), and writing it stays masters.edit.records on the Part Master.
--
-- MERGED, NEVER OVERWRITTEN; a role with no permissions at all is left alone
-- (an empty array means "not configured", and the code default already holds
-- the key). An administrator can untick it per role afterwards; a re-run only
-- adds it to a configured role that lacks it.
-- ===========================================================================

do $$
declare n int;
begin
  if to_regclass('public.app_roles') is null then return; end if;
  update public.app_roles ar
     set permissions = ar.permissions || '["mod:/part-search"]'::jsonb,
         updated_at = now()
   where jsonb_array_length(ar.permissions) > 0
     and not (ar.permissions ? 'mod:/part-search');
  get diagnostics n = row_count;
  raise notice '0308: % role(s) given Part Search', n;
end $$;

-- ------------------------------------------------------------------------
-- 0325_party_part_add_edit_delete.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0325 — PARTY AND PART MASTER: ONE KEY TO ADD, ONE TO EDIT, ONE TO DELETE
--
-- The user, 2026-10-03: "Provision to edit all masters. Action button on the
-- table. Ensure it is added in Roles and Permissions" -- and, asked how: "One
-- add, one edit, one delete per master".
--
-- Until now one key, masters.edit.records, wrote parties and parts through a
-- FOR ALL policy (0286), so whoever could add a party could also DELETE one
-- through the API although no screen offered it. This file splits it:
--
--   masters.parties.add / .edit   parents: masters.edit.records, masters.edit
--   masters.parties.delete        parent:  masters.edit
--   masters.parts.add / .edit     parents: masters.edit.records, masters.edit
--   masters.parts.delete          parent:  masters.edit
--
-- NOBODY'S GRANTS ARE TOUCHED. Add and edit are children of the key that
-- already allowed them, so a role holding it keeps exactly what it had. Delete
-- is a child of "Edit masters (all of the below)" only: a role holding just
-- masters.edit.records loses an API delete no screen ever offered it, which is
-- a narrowing, never a widening. An administrator passes has_perm() anyway.
--
-- A DELETE IS REFUSED WHILE ANY RECORD STILL NAMES THE ROW. Parties and parts
-- are referenced by TEXT, not by foreign key -- a call carries the party's
-- name, a consumption line the part's CODE|Description -- so a deleted party
-- would leave every machine, call and contract naming a customer who no longer
-- exists, with nothing to say so. master_delete_guard() counts those records
-- as the OWNER (security definer), never as the caller: under the caller's
-- row-level security an engineer's count would see only his own calls and pass
-- a party that a thousand other calls name.
--
-- In the rbac module, after 0286 (which creates parties_write / parts_write)
-- and before the policy tail, so a replay of rbac.sql ends on these.
-- ===========================================================================

-- ---- 1. the parents (0286's list carries the same rows) -------------------
insert into public.perm_parents (child, parent) values
  ('masters.parties.add', 'masters.edit.records'),
  ('masters.parties.add', 'masters.edit'),
  ('masters.parties.edit', 'masters.edit.records'),
  ('masters.parties.edit', 'masters.edit'),
  ('masters.parties.delete', 'masters.edit'),
  ('masters.parts.add', 'masters.edit.records'),
  ('masters.parts.add', 'masters.edit'),
  ('masters.parts.edit', 'masters.edit.records'),
  ('masters.parts.edit', 'masters.edit'),
  ('masters.parts.delete', 'masters.edit'),
  ('masters.product_master.add', 'masters.edit.records'),
  ('masters.product_master.add', 'masters.edit'),
  ('masters.product_master.edit', 'masters.edit.records'),
  ('masters.product_master.edit', 'masters.edit'),
  ('masters.product_master.delete', 'masters.edit')
on conflict do nothing;

-- ---- 2. parties and parts: insert / update / delete, each its own key -----
-- Split out of FOR ALL, which is also a read policy; each wrapped in a
-- sub-select so it is asked once per query, not once per row (0250).
do $$
declare t text; k text;
begin
  foreach t in array array['parties', 'parts'] loop
    if to_regclass('public.' || t) is null then continue; end if;
    k := 'masters.' || t;
    execute format('drop policy if exists %1$s_write on public.%1$s', t);
    execute format('drop policy if exists %1$s_insert on public.%1$s', t);
    execute format('drop policy if exists %1$s_update on public.%1$s', t);
    execute format('drop policy if exists %1$s_delete on public.%1$s', t);
    execute format('create policy %1$s_insert on public.%1$s for insert '
                   'with check ((select public.has_perm(%2$L)))', t, k || '.add');
    execute format('create policy %1$s_update on public.%1$s for update '
                   'using ((select public.has_perm(%2$L))) with check ((select public.has_perm(%2$L)))', t, k || '.edit');
    execute format('create policy %1$s_delete on public.%1$s for delete '
                   'using ((select public.has_perm(%2$L)))', t, k || '.delete');
  end loop;
end $$;

-- ---- 3. no delete while a record names it --------------------------------
-- plpgsql, so nothing in the body is resolved at creation: most of the tables
-- it reads belong to modules that run after this one, and each is asked only
-- if it exists. The lists are every column that names the row, read off the
-- schema on 2026-10-03; a table added later that names a party or a part
-- belongs here too.
create or replace function public.master_delete_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  refs text[];
  r text; tbl text; col text; n bigint;
  key text;
  found text[] := '{}';
  total bigint := 0;
begin
  if tg_table_name = 'parties' then
    key := lower(btrim(old.party_name));
    refs := array['products.party_name', 'field_calls.party_name', 'installation_calls.party_name',
      'pm_calls.party_name', 'call_requests.party_name', 'pending_registrations.party_name',
      'sale_entries.party_name', 'contract_entries.party_name', 'contract_items.party_name',
      'ownership_transfers.from_party', 'ownership_transfers.to_party',
      'product_additional_entries.party_name', 'feedback.party_name', 'spare_requests.party_name',
      'spare_consumption_history.party_name', 'indoor_jobs.party_name'];
  elsif tg_table_name = 'parts' then
    key := lower(btrim(old.item_detail));
    refs := array['spare_request_lines.part', 'spare_dispatch_lines.part', 'spare_consumption.part',
      'spare_consumption_history.part', 'spare_issue_history.part', 'handstock_opening.part',
      'handstock_adjustments.part', 'stock_transfer_lines.part', 'material_returns.part'];
  elsif tg_table_name = 'product_master' then
    key := lower(btrim(old.product_code));
    refs := array['products.item_code', 'sale_items.product_code', 'contract_items.product_code'];
  else
    return old;
  end if;
  if coalesce(key, '') = '' then return old; end if;

  foreach r in array refs loop
    tbl := split_part(r, '.', 1);
    col := split_part(r, '.', 2);
    if to_regclass('public.' || tbl) is null then continue; end if;
    if not exists (select 1 from information_schema.columns
                    where table_schema = 'public' and table_name = tbl and column_name = col) then
      continue;
    end if;
    execute format('select count(*) from public.%I where lower(btrim(%I)) = $1', tbl, col) into n using key;
    if n > 0 then
      found := found || format('%s %s', n, case tbl when 'products' then 'machines' else replace(tbl, '_', ' ') end);
      total := total + n;
    end if;
  end loop;

  if total > 0 then
    raise exception '% is still named on % record(s) — %. It cannot be deleted while they name it.',
      case tg_table_name when 'parties' then 'This party'
                         when 'parts' then 'This part'
                         else 'This product line' end,
      total, array_to_string(found, ', ')
      using errcode = '23503';
  end if;
  return old;
end $$;
revoke execute on function public.master_delete_guard() from public, anon, authenticated;

do $$
declare t text;
begin
  foreach t in array array['parties', 'parts'] loop
    if to_regclass('public.' || t) is null then continue; end if;
    execute format('drop trigger if exists master_delete_guard on public.%I', t);
    execute format('create trigger master_delete_guard before delete on public.%I '
                   'for each row execute function public.master_delete_guard()', t);
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0347_feedback_read_once_and_no_machine_delete.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0347 — CUSTOMER FEEDBACK ASKS THE PERMISSION ONCE PER QUERY (D-132), AND NO
--        SIGNED-IN USER DELETES A MACHINE THROUGH THE API (D-139)
--        (second re-review, 2026-10-03)
--
-- D-132. fb_read and fb_write (0286) call has_perm() bare, so Postgres asks it
-- once per ROW -- the 0250 fault. Measured over 30,000 feedback rows as an
-- engineer: 12,356 ms; with the checks wrapped, 4.9 ms. Wrapped here in a
-- sub-select, which is asked once per query. WHO may read and write is
-- unchanged, word for word. fb_update is owned by data_integrity (0288) and is
-- wrapped there by 0348, so a replay of either bundle keeps its own.
--
-- D-139. products_write (0286) is FOR ALL under masters.edit.records, so the
-- records key could DELETE machines -- measured: DELETE 1 -- although 0325
-- took the API delete away from that key on parties and parts. Split here
-- into INSERT and UPDATE on the same key, with NO delete policy: no screen
-- deletes a machine (deleteMasterRecord covers parties, parts and product
-- lines only), and the Product Database clean-ups that do
-- (_rebuild_product_database.sql, _dedupe_part_product_keys.sql) run in the
-- SQL editor, where row-level security does not apply. The uploads upsert,
-- which is an INSERT and an UPDATE, and keep working.
--
-- 0250 alters products_write only where it exists, so a replay of this bundle
-- re-creates it at 0286 and this file then splits it again.
-- In the rbac module, after 0325 and before the policy tail.
-- ===========================================================================

drop policy if exists fb_read  on public.feedback;
drop policy if exists fb_write on public.feedback;
create policy fb_read on public.feedback for select
  using ((select public.has_perm('feedback.view')) or (select public.has_perm('visit.feedback')));
create policy fb_write on public.feedback for insert
  with check ((select public.has_perm('visit.feedback')) or (select public.has_perm('feedback.view')));

do $$
begin
  if to_regclass('public.products') is null then return; end if;
  drop policy if exists products_write  on public.products;
  drop policy if exists products_insert on public.products;
  drop policy if exists products_update on public.products;
  create policy products_insert on public.products for insert
    with check ((select public.has_perm('masters.edit.records')));
  create policy products_update on public.products for update
    using ((select public.has_perm('masters.edit.records')))
    with check ((select public.has_perm('masters.edit.records')));
end $$;

-- ------------------------------------------------------------------------
-- 0350_delete_guard_counts_every_name.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0350 — THE MASTER DELETE GUARD COUNTS EVERY PLACE A PARTY OR A PART IS NAMED
--        (second re-review, 2026-10-03: D-137)
--
-- master_delete_guard (0325) refuses deleting a party or part that records
-- still name, but its lists left out:
--   * a party named as SOLD THROUGH -- on products, sale_entries, sale_items
--     and ownership_transfers (made dealer-only from the Party Master by 0328
--     the same day) -- as an Indoor DC's CONSIGNEE, an indoor job's DEMO FOR
--     party, a Field Failure Report's CUSTOMER and a material return's CUSTOMER;
--   * a part named on indoor_job_parts.part_code, which part_rename_impact()
--     and rename_part() both list.
-- Measured: a dealer named only as Sold Through, and a party named only as an
-- Indoor DC consignee, were each deleted (DELETE 1), and the machine went on
-- reading that Sold Through.
--
-- 0325's function VERBATIM with those columns added; a table or column a
-- project lacks is skipped exactly as before. It only ever REFUSES more
-- deletes -- nothing that could be deleted before and is still unnamed is
-- refused. In the rbac module (0325's), after 0347, before the policy tail.
-- ===========================================================================

create or replace function public.master_delete_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  refs text[];
  r text; tbl text; col text; n bigint;
  key text;
  found text[] := '{}';
  total bigint := 0;
begin
  if tg_table_name = 'parties' then
    key := lower(btrim(old.party_name));
    refs := array['products.party_name', 'field_calls.party_name', 'installation_calls.party_name',
      'pm_calls.party_name', 'call_requests.party_name', 'pending_registrations.party_name',
      'sale_entries.party_name', 'contract_entries.party_name', 'contract_items.party_name',
      'ownership_transfers.from_party', 'ownership_transfers.to_party',
      'product_additional_entries.party_name', 'feedback.party_name', 'spare_requests.party_name',
      'spare_consumption_history.party_name', 'indoor_jobs.party_name',
      -- 0350 (D-137): the other places a party is named.
      'products.sold_through', 'sale_entries.sold_through', 'sale_items.sold_through',
      'ownership_transfers.sold_through', 'indoor_dcs.consignee', 'indoor_jobs.demo_for_party',
      'field_failure_reports.customer_name', 'material_returns.customer_name'];
  elsif tg_table_name = 'parts' then
    key := lower(btrim(old.item_detail));
    refs := array['spare_request_lines.part', 'spare_dispatch_lines.part', 'spare_consumption.part',
      'spare_consumption_history.part', 'spare_issue_history.part', 'handstock_opening.part',
      'handstock_adjustments.part', 'stock_transfer_lines.part', 'material_returns.part',
      -- 0350 (D-137): part_rename_impact() lists it, so the guard does too.
      'indoor_job_parts.part_code'];
  elsif tg_table_name = 'product_master' then
    key := lower(btrim(old.product_code));
    refs := array['products.item_code', 'sale_items.product_code', 'contract_items.product_code'];
  else
    return old;
  end if;
  if coalesce(key, '') = '' then return old; end if;

  foreach r in array refs loop
    tbl := split_part(r, '.', 1);
    col := split_part(r, '.', 2);
    if to_regclass('public.' || tbl) is null then continue; end if;
    if not exists (select 1 from information_schema.columns
                    where table_schema = 'public' and table_name = tbl and column_name = col) then
      continue;
    end if;
    execute format('select count(*) from public.%I where lower(btrim(%I)) = $1', tbl, col) into n using key;
    if n > 0 then
      found := found || format('%s %s', n, case tbl when 'products' then 'machines' else replace(tbl, '_', ' ') end);
      total := total + n;
    end if;
  end loop;

  if total > 0 then
    raise exception '% is still named on % record(s) — %. It cannot be deleted while they name it.',
      case tg_table_name when 'parties' then 'This party'
                         when 'parts' then 'This part'
                         else 'This product line' end,
      total, array_to_string(found, ', ')
      using errcode = '23503';
  end if;
  return old;
end $$;
revoke execute on function public.master_delete_guard() from public, anon, authenticated;

-- ------------------------------------------------------------------------
-- 0381_master_reads_once_per_query.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE MASTER READ POLICIES ASKED ONCE PER QUERY, NOT ONCE PER ROW (2026-10-05).
--
-- The user's pg_stat_statements export ("Supabase - RootCause") put two plain
-- reads of the masters among the most expensive statements on the project:
-- `products` paged by id (3,800 calls, ~6.9 s each) and `parties` (2,992
-- calls, ~3.9 s each), both with almost no disk reads -- so the time is CPU,
-- not I/O.
--
-- 0008 wrote the read policy on parties, products, parts and masters as
-- `auth.role() = 'authenticated'`, bare. Postgres evaluates a bare function in
-- a policy once per ROW, and on Supabase auth.role() reads the request's JWT
-- claims and parses them as jsonb each time. Wrapped as a sub-select it is an
-- InitPlan, asked once per statement -- the 0095 / 0250 pattern.
--
-- Measured on a database built from every migration, as `authenticated` with a
-- Supabase-shaped auth.role() and a realistic claims string, 20,000 machines:
--   one 1,000-row page at offset 19,000      147 ms  ->  27 ms
--   the product-name count (product_register_names) 106 ms -> 11 ms
-- The live figures are larger than these; the ratio is what this file claims.
--
-- WHO MAY READ IS UNCHANGED: the predicate is the same comparison, only asked
-- once. In the rbac module after 0008, before the policy tail (which does not
-- touch these), so a replay of rbac.sql ends on this definition.
--
-- PRODUCTS FIRST, AND THE ORDER IS NOT TIDINESS. Dropping a policy takes an
-- ACCESS EXCLUSIVE lock on its table, and the first run of this file on the
-- live project (run 37300728067, 2026-10-05) died with `deadlock detected`:
-- it had locked parties and was waiting for products, while a reader of
-- product_database -- which joins products THEN parties -- held products and
-- was waiting for parties. Locking in the readers' order (products before
-- parties) means a reader that holds parties already holds products, so it
-- cannot be waiting on this file, and this file waits only for readers to
-- finish. A lock timeout (the second run) is the remaining failure, and it is
-- safe: the transaction rolls back whole and the workflow is re-run.
-- ===========================================================================

do $$
declare t text;
begin
  foreach t in array array['products', 'parties', 'parts', 'masters'] loop
    if to_regclass('public.' || t) is null then continue; end if;
    execute format('drop policy if exists %1$s_read on public.%1$s', t);
    execute format('create policy %1$s_read on public.%1$s for select '
                   'using ((select auth.role()) = ''authenticated'')', t);
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0121_rbac_policy_tail.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- rbac.sql must leave every policy it defines at its LATEST definition.
--
-- 0008 creates a policy for most tables in the schema. Six of those were later
-- narrowed by other modules — and because the apply bundles are replayed ONE AT
-- A TIME, running `rbac.sql` on its own put 0008's wider version back. No
-- error, no warning, and the bundle reports success. It has now happened twice
-- (2026-09-05 for `srl_insert`, 2026-09-06 for these six), each time reading as
-- "the migration was never applied" when it had been applied and overwritten.
--
-- 0087/0088 were fixed by MOVING them into this module. These six cannot move:
-- each sits in a migration that also does work belonging to its own module, and
-- each depends on tables that module creates. So this file — the LAST in the
-- rbac module — re-asserts their latest definitions instead:
--
--   spare_requests.sr_read        0040_spare_read_scope
--   spare_requests.sr_update      0009_spare_receipt
--   spare_request_lines.srl_update 0016_spare_line_approvals
--   spare_consumption.cons_read   0038_spare_consumption_scope
--   spare_consumption.cons_write  0059_consumption_reconciliation
--   spare_requests_stage_guard()  0016_spare_line_approvals
--   masters insert/update/delete  0067_master_list_permissions
--
-- Every block is GUARDED on what it names. On a FRESH apply rbac runs before
-- masters, spare_requests and handstock (ALL_ORDER), so those tables do not
-- exist yet: each block skips, and the owning module defines the policy itself
-- a moment later — identically. On a replay against a live database everything
-- is present, so the latest definition is restored. Idempotent either way, and
-- the definitions here are copies: change one in its own migration and change
-- it here too, or rbac.sql goes back to reverting it.
-- ===========================================================================

-- --------------------------------------------------------------------------
-- spare_requests — who may SEE one (0040), and who may UPDATE one (0009).
-- --------------------------------------------------------------------------
do $$
begin
  if to_regclass('public.spare_requests') is null then
    raise notice 'skip sr_read/sr_update — public.spare_requests is not present yet';
    return;
  end if;

  if to_regproc('public.can_view_all_calls') is not null
     and exists (select 1 from information_schema.columns
                  where table_schema = 'public' and table_name = 'spare_requests'
                    and column_name = 'engineer_email') then
    drop policy if exists sr_read on public.spare_requests;
    create policy sr_read on public.spare_requests for select
      using (
        (select public.can_view_all_calls())
        or created_by = (select auth.uid())
        or lower(engineer_email) = lower((select auth.email()))
        or lower(btrim(engineer)) in (
             select lower(btrim(n)) from public.visible_engineer_names() as v(n)
           )
      );
  else
    raise notice 'skip sr_read — can_view_all_calls() or engineer_email is not present yet';
  end if;

  if to_regproc('public.is_spare_requester') is not null then
    drop policy if exists sr_update on public.spare_requests;
    create policy sr_update on public.spare_requests for update
      using      (public.can_approve_spares() or public.is_spare_requester(spare_requests))
      with check (public.can_approve_spares() or public.is_spare_requester(spare_requests));
  else
    raise notice 'skip sr_update — is_spare_requester() is not present yet';
  end if;
end $$;

-- --------------------------------------------------------------------------
-- spare_request_lines — the raiser may touch their own lines, not only an
-- approver (0016). Without this an engineer cannot acknowledge receipt.
-- --------------------------------------------------------------------------
do $$
begin
  if to_regclass('public.spare_request_lines') is null
     or to_regproc('public.is_spare_requester') is null then
    raise notice 'skip srl_update — spare_request_lines or is_spare_requester() is not present yet';
    return;
  end if;

  drop policy if exists srl_update on public.spare_request_lines;
  create policy srl_update on public.spare_request_lines for update
    using (
      public.can_approve_spares()
      or exists (select 1 from public.spare_requests r
                  where r.uid = spare_request_lines.request_uid and public.is_spare_requester(r))
    )
    with check (
      public.can_approve_spares()
      or exists (select 1 from public.spare_requests r
                  where r.uid = spare_request_lines.request_uid and public.is_spare_requester(r))
    );
end $$;

-- --------------------------------------------------------------------------
-- spare_consumption — scoped reads (0038), and a Reconciliation line needing
-- its own permission rather than calls.report (0059).
-- --------------------------------------------------------------------------
do $$
begin
  if to_regclass('public.spare_consumption') is null then
    raise notice 'skip cons_read/cons_write — public.spare_consumption is not present yet';
    return;
  end if;

  if to_regproc('public.can_view_all_calls') is not null
     and exists (select 1 from information_schema.columns
                  where table_schema = 'public' and table_name = 'spare_consumption'
                    and column_name = 'engineer_email') then
    drop policy if exists cons_read on public.spare_consumption;
    create policy cons_read on public.spare_consumption for select
      using (
        (select public.can_view_all_calls())
        or created_by = (select auth.uid())
        or lower(engineer_email) = lower((select auth.email()))
        or lower(trim(engineer)) in (
             select lower(trim(n)) from public.visible_engineer_names() as v(n)
           )
      );
  else
    raise notice 'skip cons_read — can_view_all_calls() or engineer_email is not present yet';
  end if;

  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'spare_consumption'
                and column_name = 'source') then
    drop policy if exists cons_write on public.spare_consumption;
    create policy cons_write on public.spare_consumption for insert
      with check (
        case when coalesce(source, 'Report') = 'Reconciliation'
             then public.has_perm('consumption.reconcile')
             else (public.has_perm('visit.spares') or public.has_perm('spare.dispatch'))
        end
      );
  else
    raise notice 'skip cons_write — spare_consumption.source is not present yet';
  end if;
end $$;

-- --------------------------------------------------------------------------
-- masters — write rights are PER LIST (0067).
--
-- This is the one no static check can see: 0008 creates `masters_write`
-- through `execute format(...)` in a loop, so no `create policy` literal
-- appears in its text. Policies are OR'd, so leaving 0008's version in place
-- lets a holder of `masters.edit` write EVERY list again — exactly what 0067
-- narrowed.
-- --------------------------------------------------------------------------
do $$
begin
  if to_regclass('public.masters') is null then
    raise notice 'skip masters policies — public.masters is not present yet';
    return;
  end if;

  drop policy if exists masters_write on public.masters;
  drop policy if exists masters_admin_write on public.masters;
  drop policy if exists masters_insert on public.masters;
  drop policy if exists masters_update on public.masters;
  drop policy if exists masters_delete on public.masters;

  -- masters_insert is 0325_product_line_and_list_add_edit_delete's (a list's
  -- own add key, 2026-10-03).
  create policy masters_insert on public.masters for insert
    with check (public.has_perm('masters.edit.records')
             or public.has_perm('master.' || coalesce(name, '') || '.add')
             or public.has_perm('master.' || coalesce(name, '') || '.edit'));

  create policy masters_update on public.masters for update
    using      (public.has_perm('masters.edit.records')
             or public.has_perm('master.' || coalesce(name, '') || '.edit'))
    with check (public.has_perm('masters.edit.records')
             or public.has_perm('master.' || coalesce(name, '') || '.edit'));

  -- masters_delete is 0371_master_list_delete_key's (a list's own delete key,
  -- or masters.edit -- not "Add / edit master records", D-086).
  create policy masters_delete on public.masters for delete
    using      (public.has_perm('masters.edit')
             or public.has_perm('master.' || coalesce(name, '') || '.delete'));
end $$;

-- --------------------------------------------------------------------------
-- spare_requests_stage_guard() — the per-stage approval guard.
--
-- 0008 creates it; 0009, 0012 and 0016 each extend it, and 0016 has the last
-- word: the receipt columns, courier / dispatch remarks, reject_reason and the
-- Received transition. Replaying rbac.sql put 0008's back, which refuses an
-- engineer acknowledging receipt and lets a rejection be written without one.
--
-- Unlike the policies above this needs nothing that a later module creates —
-- it is plpgsql, so its body is not resolved until it runs — so it is
-- unguarded and correct on a fresh apply as well.
-- --------------------------------------------------------------------------
create or replace function public.spare_requests_stage_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if public.is_admin() then return new; end if;
  if coalesce(current_setting('app.spare_rollup', true), '') = '1' then return new; end if;

  if new.stage  is distinct from old.stage
  or new.status is distinct from old.status
  or new.rm_approval         is distinct from old.rm_approval
  or new.commercial_approval is distinct from old.commercial_approval
  or new.nsm_approval        is distinct from old.nsm_approval
  or new.stores_status       is distinct from old.stores_status
  or new.received_at         is distinct from old.received_at then
    raise exception 'Spare approvals are recorded per spare — update spare_request_lines, not the request';
  end if;
  return new;
end $$;

-- ------------------------------------------------------------------------
-- 0009_audit_log.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Audit log — records actions, logins, errors, and the time each action took.
-- Clients insert their own events; the identity (user_id/email) is stamped by
-- the DB so it can't be forged. Only admins can read the log.
-- ===========================================================================

create table if not exists public.audit_log (
  id          bigint generated always as identity primary key,
  at          timestamptz not null default now(),
  user_id     uuid,
  email       text default '',
  actor       text default '',      -- display name (client-supplied)
  role        text default '',      -- role key (client-supplied)
  action      text not null,        -- e.g. login, call.create, call.report, spare.approve
  target      text default '',      -- UCN / uid / id the action acted on
  status      text default 'ok',    -- ok | error
  error       text default '',
  duration_ms integer,              -- how long the action took
  meta        jsonb not null default '{}'
);
create index if not exists audit_at_idx     on public.audit_log (at desc);
create index if not exists audit_action_idx on public.audit_log (action);
create index if not exists audit_email_idx  on public.audit_log (lower(email));
create index if not exists audit_status_idx on public.audit_log (status);

-- Stamp identity + time server-side (don't trust the client for who/when).
create or replace function public.audit_before_insert()
returns trigger language plpgsql set search_path = public as $$
begin
  new.user_id := auth.uid();
  new.email   := coalesce(nullif(auth.email(), ''), new.email);  -- keep attempted email for anon login failures
  new.at      := now();
  return new;
end $$;
drop trigger if exists audit_biu on public.audit_log;
create trigger audit_biu before insert on public.audit_log
  for each row execute function public.audit_before_insert();

alter table public.audit_log enable row level security;
-- Authenticated users log their own actions; anon may log only login attempts
-- (so failed logins, which have no session yet, are still recorded).
drop policy if exists audit_insert on public.audit_log;
create policy audit_insert on public.audit_log for insert
  with check (auth.role() = 'authenticated' or action in ('login', 'login_failed'));
-- Only admins read the audit log.
drop policy if exists audit_read on public.audit_log;
create policy audit_read on public.audit_log for select using (public.is_admin());

-- ------------------------------------------------------------------------
-- 0033_audit_retention.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Audit-log retention: keep 7 days, auto-delete anything older.
-- A daily pg_cron job runs purge_audit_log(). Safe to run in the SQL editor
-- as the `postgres` role; it enables pg_cron if it isn't already on.
-- ===========================================================================

-- Delete audit rows older than 7 days. Returns how many were removed.
create or replace function public.purge_audit_log()
returns integer
language plpgsql
security definer
set search_path = public as $$
declare removed integer;
begin
  delete from public.audit_log where at < now() - interval '7 days';
  get diagnostics removed = row_count;
  return removed;
end $$;

-- Clear one week of backlog immediately so the policy takes effect now.
select public.purge_audit_log();

-- Schedule it daily at 00:30 UTC via pg_cron.
do $$
begin
  create extension if not exists pg_cron;
exception when others then
  raise notice 'Could not enable pg_cron automatically (%). Enable it in Dashboard -> Database -> Extensions, then re-run this migration.', sqlerrm;
end $$;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    -- Re-scheduling is idempotent: drop the old job first if present.
    if exists (select 1 from cron.job where jobname = 'purge-audit-log') then
      perform cron.unschedule('purge-audit-log');
    end if;
    perform cron.schedule('purge-audit-log', '30 0 * * *', 'select public.purge_audit_log();');
  else
    raise notice 'pg_cron is not enabled. Audit rows will NOT auto-delete until you enable pg_cron (Dashboard -> Database -> Extensions) and re-run this file. Until then, run: select public.purge_audit_log();';
  end if;
end $$;

-- ------------------------------------------------------------------------
-- 0047_audit_retention_compliance.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Audit-log retention for a regulated QMS. The earlier 7-day auto-delete is not
-- acceptable for medical-device quality records — the audit trail must be kept
-- for the record retention period. Retention is now a CONFIGURABLE setting,
-- defaulting to 3650 days (~10 years). The daily purge uses it. The database
-- audit trail (record_audit, 0048) is NOT purged by this job.
-- ===========================================================================

create table if not exists public.app_settings (
  key        text primary key,
  value      text not null,
  updated_at timestamptz not null default now()
);
insert into public.app_settings (key, value) values ('audit_retention_days', '3650')
  on conflict (key) do nothing;

alter table public.app_settings enable row level security;
grant select, insert, update on public.app_settings to authenticated;
drop policy if exists app_settings_read on public.app_settings;
create policy app_settings_read on public.app_settings for select using (auth.role() = 'authenticated');
drop policy if exists app_settings_write on public.app_settings;
create policy app_settings_write on public.app_settings for all
  using (public.is_admin() or public.has_perm('config.manage'))
  with check (public.is_admin() or public.has_perm('config.manage'));

-- Purge uses the configured retention (fallback 3650 days). Redefinition only —
-- the daily pg_cron job scheduled by 0033 keeps calling this function.
create or replace function public.purge_audit_log()
returns integer language plpgsql security definer set search_path = public as $$
declare removed integer; days integer;
begin
  select coalesce(nullif(value, '')::int, 3650) into days from public.app_settings where key = 'audit_retention_days';
  days := greatest(coalesce(days, 3650), 1);
  delete from public.audit_log where at < now() - make_interval(days => days);
  get diagnostics removed = row_count;
  return removed;
end $$;

-- ------------------------------------------------------------------------
-- 0114_audit_mode.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- AUDIT MODE — a switch only an administrator can throw.
--
-- Asked for by the user on 2026-09-06, WITH THE RULES TO FOLLOW: "come up with
-- an Audit Mode, which can be toggled only by the admins — I will give the list
-- of rules for that later". So this migration builds the switch and nothing
-- else. NOTHING IN THE APPLICATION READS IT YET, and that is not an oversight
-- — attaching behaviour to it before the rules arrive would mean guessing what
-- an audit is supposed to change, and guessing wrong in a regulated system is
-- worse than waiting.
--
-- WHAT IS HERE:
--   * the setting itself, in `app_settings` alongside audit_retention_days,
--     because that is where this project keeps configuration;
--   * `audit_mode()` — a stable read anything may call;
--   * `set_audit_mode()` — the only way to change it, admin-only, and it
--     refuses without a reason;
--   * `audit_mode_changes` — every flip, who and when and why, in its own
--     table.
--
-- WHY ITS OWN LOG TABLE. `audit_log` is written by the CLIENT and purged on a
-- retention window (0047). A switch that changes what the system does during an
-- audit is exactly the thing whose history must outlive both of those, so it is
-- recorded by the function itself, on the server, into a table nothing purges
-- and nobody can UPDATE or DELETE through the API. Whatever the rules turn out
-- to be, the fact that the mode was on — and for how long — will always be
-- answerable.
--
-- CLASSIFICATION. Documented in the Validation Package as a NON-AUDITABLE
-- REQUIREMENT (NAR-001), per the user's instruction. That is a statement about
-- the requirement's provenance — it is not derived from a regulatory clause and
-- is not offered as evidence of one — and NOT a statement that its use goes
-- unrecorded. Its use is recorded here, permanently.
-- ===========================================================================

-- app_settings is created by 0047 (audit module). Guarded so this file can be
-- replayed on a project where that has not run yet without dying.
do $mode$
begin
  if to_regclass('public.app_settings') is null then
    raise notice 'app_settings is missing — run 0047_audit_retention_compliance.sql first';
    return;
  end if;
  insert into public.app_settings (key, value) values ('audit_mode', 'off')
    on conflict (key) do nothing;
end $mode$;

-- ---- the log ---------------------------------------------------------------
create table if not exists public.audit_mode_changes (
  id         bigserial primary key,
  at         timestamptz not null default now(),
  turned_on  boolean     not null,
  reason     text        not null,
  changed_by uuid        references auth.users (id)
);
create index if not exists audit_mode_changes_at_idx on public.audit_mode_changes (at desc);

alter table public.audit_mode_changes enable row level security;
-- SELECT only, and only for an administrator. There is no insert/update/delete
-- policy at all, so the ONLY way a row appears is `set_audit_mode()` — a
-- SECURITY DEFINER function, which RLS does not stand in the way of. A history
-- the API cannot edit is the point of the table.
grant select on public.audit_mode_changes to authenticated;
revoke insert, update, delete on public.audit_mode_changes from authenticated;
drop policy if exists amc_read on public.audit_mode_changes;
create policy amc_read on public.audit_mode_changes for select
  using (public.is_admin() or public.has_perm('audit.view'));

-- ---- read ------------------------------------------------------------------
create or replace function public.audit_mode()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(
    (select lower(btrim(value)) in ('on', 'true', '1', 'yes')
       from public.app_settings where key = 'audit_mode'),
    false)
$$;
revoke all on function public.audit_mode() from public;
grant execute on function public.audit_mode() to authenticated;

-- ---- write -----------------------------------------------------------------
-- Admin only, by the user's instruction. Not `config.manage`, which is what
-- app_settings' own write policy allows: the user said ADMINS, and a switch is
-- not a retention number.
create or replace function public.set_audit_mode(p_on boolean, p_reason text)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_now boolean;
begin
  if not public.is_admin() then
    raise exception 'RBAC: only an administrator can change Audit Mode';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'Changing Audit Mode needs a reason';
  end if;

  v_now := public.audit_mode();
  if v_now is not distinct from p_on then
    -- Not an error, and not a log entry either: recording "changed from off to
    -- off" would pad the history that the history exists to keep readable.
    return v_now;
  end if;

  insert into public.app_settings (key, value, updated_at)
       values ('audit_mode', case when p_on then 'on' else 'off' end, now())
  on conflict (key) do update set value = excluded.value, updated_at = excluded.updated_at;

  insert into public.audit_mode_changes (turned_on, reason, changed_by)
       values (p_on, btrim(p_reason), auth.uid());

  return p_on;
end $$;
revoke all on function public.set_audit_mode(boolean, text) from public;
grant execute on function public.set_audit_mode(boolean, text) to authenticated;

comment on table public.audit_mode_changes is
  'Every change of Audit Mode: on/off, why, who, when. Written only by set_audit_mode(); never purged, never editable through the API.';

-- ------------------------------------------------------------------------
-- 0307_audit_mode_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- SWITCHING AUDIT MODE IS audit.mode.
-- WHAT WAS AN ADMINISTRATOR'S ALONE IS A KEY (the user, 2026-09-30: "All
-- Admin Actions that are greyed out now should be editable from the Role &
-- Permissions. Only the Admin Role should be Greyed out not the Actions.")
--
-- is_admin() becomes has_perm(<key>). An administrator still passes -- has_perm()
-- answers true for is_admin() -- so nobody loses anything, and NOBODY ELSE GAINS
-- ANYTHING ON THE DAY: no role holds the new key until an administrator ticks it
-- on Roles & Permissions. coalesce(..., false) so a NULL (no session) refuses.
--
-- A reason is still demanded and every change is still kept. Its history is
-- readable by a holder of the key as well as by audit.view.
-- ===========================================================================

CREATE OR REPLACE FUNCTION public.set_audit_mode(p_on boolean, p_reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_now boolean;
begin
  if not coalesce(public.has_perm('audit.mode'), false) then
    raise exception 'RBAC: changing Audit Mode needs "Switch Audit Mode on or off"';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'Changing Audit Mode needs a reason';
  end if;

  v_now := public.audit_mode();
  if v_now is not distinct from p_on then
    -- Not an error, and not a log entry either: recording "changed from off to
    -- off" would pad the history that the history exists to keep readable.
    return v_now;
  end if;

  insert into public.app_settings (key, value, updated_at)
       values ('audit_mode', case when p_on then 'on' else 'off' end, now())
  on conflict (key) do update set value = excluded.value, updated_at = excluded.updated_at;

  insert into public.audit_mode_changes (turned_on, reason, changed_by)
       values (p_on, btrim(p_reason), auth.uid());

  return p_on;
end $function$;

drop policy if exists amc_read on public.audit_mode_changes;
create policy amc_read on public.audit_mode_changes for select
  using (public.is_admin() or public.has_perm('audit.view') or public.has_perm('audit.mode'));

-- ------------------------------------------------------------------------
-- 0315_audit_log_read_admits_audit_view.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE AUDIT LOG ADMITS WHOEVER THE AUDIT LOG SCREEN ADMITS (D-066, FRS-204).
--
-- The Audit Log screen opens for a holder of `audit.view`; its trail,
-- audit_log, was readable by administrators only (0009: `using (is_admin())`).
-- So a non-administrator granted audit.view opened a page that was always
-- empty -- which reads as "nothing happened", not as "you may not see". The
-- record-level trail beside it, record_audit, already admits
-- `is_admin() or has_perm('audit.view')` (0048); the two trails disagreed
-- about their own audience.
--
-- Now both say the same thing. Writing to the log is unchanged (audit_insert),
-- and nothing can update or delete it.
-- Each half wrapped in a sub-select so it is asked once per query, not once
-- per row (0250 -- the audit log is the largest table this app reads).
-- ===========================================================================

drop policy if exists audit_read on public.audit_log;
create policy audit_read on public.audit_log for select
  using ((select public.is_admin()) or (select public.has_perm('audit.view')));

-- ------------------------------------------------------------------------
-- 0143_tracker.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE TRACKER — a shared list of what is being worked on.
--
-- The user, 2026-09-08: "add a tracker page under admin to track activities.
-- something very similar to backlog.. shared between me and a few other. all who
-- have access should be able add, edit".
--
-- SO IT IS ONE PERMISSION, NOT TWO. `mod:/tracker` grants the page AND the right
-- to add and edit on it -- "all who have access should be able to add, edit" is
-- the whole access model, and splitting it into a view right and an edit right
-- would invent a distinction the user did not ask for and then require two ticks
-- to undo. Sharing it with somebody is one tick in Roles & Permissions.
--
-- Nothing is granted to any role here except ADMIN. A tracker that arrived
-- already visible to the whole company would be the opposite of "shared between
-- me and a few other" -- the few are chosen, not defaulted.
--
-- NOTHING IS EVER DELETED BY ACCIDENT, and nothing is hidden either. An item is
-- CLOSED (status Done or Dropped) and stays on the list; the page filters it out
-- of the default view. A shared list people delete from is one nobody trusts,
-- because the thing you remember agreeing is simply not there any more and there
-- is no way to tell whether it was done or dropped. Deleting is still possible
-- and is a deliberate act on the row.
--
-- WHO TOUCHED IT LAST IS THE POINT OF A SHARED LIST. `updated_by` and
-- `updated_at` are stamped by a trigger, not by the client -- so they cannot be
-- forgotten, and cannot be set to somebody else. `app_user_names` (0068) turns
-- the id into a name for the screen.
--
-- FREE TEXT WHERE THE BACKLOG HAS PROSE. `status` and `area` are plain text with
-- a CHECK only on status: a tracker whose categories have to be migrated before
-- somebody can file a thought is a tracker people keep in a spreadsheet instead.
-- ===========================================================================

create table if not exists public.tracker_items (
  id          bigint generated always as identity primary key,
  title       text not null,
  detail      text not null default '',
  -- OPEN is the default because an item somebody just typed is open by
  -- definition, and making them choose is a step that adds nothing.
  status      text not null default 'Open'
              check (status in ('Open', 'In progress', 'Blocked', 'Done', 'Dropped')),
  -- WHO IT IS WITH -- free text, because it is as often "a decision" or a
  -- customer as it is a person on this system.
  owner       text not null default '',
  area        text not null default '',      -- Calls, Spares, Objectives, Data …
  due_date    date,
  -- Hand ordering, so the list can be arranged the way the people using it
  -- think about it rather than by whatever they happened to type first.
  sort_order  integer not null default 0,
  created_by  uuid,
  created_at  timestamptz not null default now(),
  updated_by  uuid,
  updated_at  timestamptz not null default now()
);

create index if not exists tracker_items_open_idx
  on public.tracker_items (status, sort_order, id);

alter table public.tracker_items enable row level security;

-- ONE PERMISSION FOR BOTH. `for all` covers select, insert, update and delete;
-- `using` gates the rows a reader sees and `with check` the rows a writer may
-- leave behind, and both ask the same question.
drop policy if exists tracker_rw on public.tracker_items;
create policy tracker_rw on public.tracker_items for all
  using (public.has_perm('mod:/tracker'))
  with check (public.has_perm('mod:/tracker'));

grant select, insert, update, delete on public.tracker_items to authenticated;

-- ---------------------------------------------------------------------------
-- WHO, AND WHEN -- stamped here so a client cannot forget it or fake it.
-- ---------------------------------------------------------------------------
create or replace function public.tracker_items_stamp()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.updated_at := now();
  if auth.uid() is not null then new.updated_by := auth.uid(); end if;
  if tg_op = 'INSERT' then
    new.created_at := now();
    if auth.uid() is not null then new.created_by := auth.uid(); end if;
  else
    -- An edit cannot rewrite who raised it, or when.
    new.created_by := old.created_by;
    new.created_at := old.created_at;
  end if;
  return new;
end $$;
drop trigger if exists zz_tracker_items_stamp on public.tracker_items;
create trigger zz_tracker_items_stamp before insert or update on public.tracker_items
  for each row execute function public.tracker_items_stamp();

-- ---------------------------------------------------------------------------
-- THE LIST, WITH NAMES. A shared tracker showing UUIDs would be unreadable, and
-- every consumer resolving them itself is how two screens end up disagreeing
-- about who did something.
--
-- SECURITY INVOKER, so the policy above is what decides who sees it -- not the
-- view's owner. This project has been bitten three times by a view that read as
-- its owner (0040, 0050, 0057) and a shared list is exactly where that would go
-- unnoticed.
-- ---------------------------------------------------------------------------
drop view if exists public.tracker_list;
create view public.tracker_list as
  select t.*,
         coalesce(cu.name, '') as created_by_name,
         coalesce(uu.name, '') as updated_by_name,
         (t.status in ('Done', 'Dropped')) as is_closed
    from public.tracker_items t
    left join public.app_user_names cu on cu.id = t.created_by
    left join public.app_user_names uu on uu.id = t.updated_by;
alter view public.tracker_list set (security_invoker = on);
grant select on public.tracker_list to authenticated;

comment on table public.tracker_items is
  'A shared list of what is being worked on -- the in-app backlog. One permission (mod:/tracker) grants both the page and the right to add and edit, because "all who have access should be able to add, edit" is the access model. Nothing is auto-deleted: an item is Done or Dropped and stays, because a shared list people delete from is one nobody trusts.';

-- ---------------------------------------------------------------------------
-- ADMINS ONLY, TO BEGIN WITH. Everyone else is added by hand on Roles &
-- Permissions -- "a few other" is a choice somebody makes, not a default.
--
-- MERGED, never overwritten: an administrator may have tuned the role already.
-- ---------------------------------------------------------------------------
update public.app_roles ar
   set permissions = (
         select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
           from (
             select jsonb_array_elements_text(ar.permissions) as v
             union
             select 'mod:/tracker' as v
           ) u
       ),
       updated_at = now()
 where ar.role = 'admin'
   and not (ar.permissions ? 'mod:/tracker');

-- ------------------------------------------------------------------------
-- 0144_tracker_seed_backlog.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE BACKLOG'S OPEN ITEMS, ON THE TRACKER.
--
-- The user, 2026-09-08: "Add all backlog Items to Tracker".
--
-- Every item from `docs/BACKLOG.md`'s OPEN ITEMS index, as at the day the
-- Tracker shipped. Seeding it in SQL rather than by hand is the only way the
-- rows reach the live database at all -- and it means the list arrives the same
-- on every project, rather than depending on who typed it in.
--
-- ONLY WHAT IS OPEN. The backlog is 2,000 lines and most of it is the record of
-- decisions already made -- reasoning, warnings, what was applied when. That
-- belongs where it is. What moves here is the part with something still to do:
-- copying the rest would bury the fifteen live items under two hundred settled
-- ones, and a tracker nobody can scan is a tracker nobody reads.
--
-- SO THE TWO ARE NOT THE SAME LIST AND SHOULD NOT BECOME ONE. The backlog keeps
-- the reasoning; the tracker keeps what is being worked on now. An item finished
-- here does not delete its entry there.
--
-- `owner` IS WHO IT IS WITH, not who will do it -- "Rithi Admin", "Decision",
-- "Claude". That is the question a shared list is actually asked ("what is
-- waiting on me?"), and it is the backlog index's own grouping.
--
-- IT SAYS "RITHI ADMIN", NOT "YOU" (the user, 2026-09-08: "Replace all 'You' to
-- Rithi Admin in the Tracker"). On a list one person keeps, "You" is clear; on a
-- SHARED one it is the one word that means somebody different to every reader --
-- so the rename is what makes the owner column mean anything at all. The block
-- below renames rows that are already out there, because the seed only inserts
-- items it has not seen and would otherwise leave the old wording in place.
--
-- IDEMPOTENT BY TITLE. The bundles are replayed one at a time and re-run freely,
-- so every insert is guarded: running this twice does not give anybody a second
-- copy of the same task, and an item somebody has since EDITED or CLOSED is left
-- exactly as they left it.
-- ===========================================================================

do $seed$
declare
  seeded int := 0;
  r      record;
begin
  if to_regclass('public.tracker_items') is null then
    raise notice 'tracker_items is missing -- run tracker.sql first';
    return;
  end if;

  -- The rename, for rows already on somebody's tracker. Narrow on purpose: only
  -- the exact word, and only in the column it was wrong in.
  update public.tracker_items set owner = 'Rithi Admin', updated_at = now()
   where btrim(owner) = 'You';

  for r in
    select * from (values
      -- ---- waiting on the user ------------------------------------------
      (10, 'The PM count is short',
           '7,029 rows in pm_calls where two years at 10,000/yr should be ~20,000 — about a third. Whatever loaded it stopped early or was filtered. Find out BEFORE nine years of history load through the same path, or the backfill silently loses two thirds of itself.',
           'Rithi Admin', 'Data'),
      (20, 'PM rows measure ~2x field-call rows',
           '2,088 bytes/row against field_calls'' 1,124, for tables with IDENTICAL columns (the 0040 split). Either PM complaint text really is twice as long, or pm_calls is carrying bloat. Across 150,000 calls that is 170 MB vs 310 MB of rows — 140 MB on a 500 MB allowance.',
           'Rithi Admin', 'Storage'),
      (30, 'handstock_period.closed_through — is a period closed?',
           'While it is NULL, handstock_cutoff() is -infinity and EVERY row of spare_issue_history + spare_consumption_history (68 MB) still feeds live hand stock. Nothing there is safe to move until a period is closed. Hand stock is derived, never stored, so removing source rows changes balances with no error and no warning.',
           'Rithi Admin', 'Spares'),
      (40, 'What six AppSheet columns held',
           'CALL DETAILS, VISIT REMARKS, CHANGE PRODUCT?, SEND EMAIL FOR DEFECTIVE SPARE, SL NO(T), Complaint. They are in the DCCR export as blank columns so WRR-2026 keeps its shape. Two sample rows from the old sheet would settle it. Three are near-duplicates of columns that ARE exported, which is where a wrong guess would go unnoticed.',
           'Rithi Admin', 'Reliability'),
      (50, 'Four objectives still typed, and the CPX rule',
           'FFR field failures, PM Calls, Installation call, b.Customer feedback have no formula yet. public.feedback exists but nothing says how a score is derived from it. Also the CPX failure rule, which was deferred.',
           'Rithi Admin', 'Objectives'),
      (60, 'Call Update and Cancelled Calls — the legacy files',
           'Should update status, complaint details and allocated-to on EXISTING calls. Needs an update-only import mode: an upsert on ucn would INSERT a stub call for any UCN not in the register. Calls also live in three tables, so it must route by looking the UCN up rather than trusting the picker; and cancellation should go through cancel_call(), which checks the permission and insists on a reason. Waiting on: the files (or their headers), and whether a blank cell clears a field or leaves it.',
           'Rithi Admin', 'Data'),

      -- ---- waiting on a decision -----------------------------------------
      (70, 'Supabase Pro, or split across projects?',
           'Nine years of history is ~300 MB of rows and ~1.25 GB with this project''s indexing. The free tier cannot hold it even split three ways. Pro is 8 GB for about $25/mo and keeps everything joinable, RLS working, and the apply bundles meaningful. Splitting a validated quality system across databases nobody can join costs more than the subscription.',
           'Decision', 'Storage'),
      (80, 'REINDEX the fat tables',
           'Index bloat is real here: record_audit holds 8 MB of indexes over 792 kB of rows. Likely 30–60 MB back for no behaviour change and no risk. reindex index concurrently does not block writes.',
           'Decision', 'Storage'),

      -- ---- waiting on me -------------------------------------------------
      (90, 'The reliability export itself',
           'reliability_wrr (WRR-2026 columns 1–14) and DCCR_EXPORT_COLUMNS (15–67) are both ready and both verified against the workbook. Nothing yet WRITES the file. src/lib/xlsx.ts already makes multi-sheet workbooks.',
           'Claude', 'Reliability'),
      (100, 'has_perm() returns NULL with no signed-in user',
           'my_extra_perms() returns NULL, so has_perm() does, so `if not has_perm(...)` never fires and execution falls through into the write. Fixed in the two functions 0139 touched; 15 OTHER MIGRATIONS still use the bare pattern. Latent rather than exploitable — execute is granted to `authenticated` only — but that is a second lock, not a reason to leave the first open.',
           'Claude', 'Security'),

      -- ---- long-standing --------------------------------------------------
      (110, 'Audit Mode rules', 'Carried in the backlog since before this round.', '', 'Compliance'),
      (120, 'The security migration (D-2 / D-3 / D-4)', 'Carried in the backlog since before this round.', '', 'Security'),
      (130, 'A CI workflow', 'Nothing runs the check scripts or the SQL suites automatically; every round is verified by hand.', '', 'Ops'),
      (140, 'Two data uploads still outstanding',
            'The 77 missing yearly consumptions (delete + re-upload the four files per _yearly_consumption_check.sql, to 39,801 total with 12,015 in 2024), and the Ownership Transfer upload.',
            'Rithi Admin', 'Data'),
      (150, 'engineer_stock needs security_invoker',
            'Carried in the backlog: a view over RLS-protected tables that does not apply RLS to the reader.', 'Claude', 'Security')
    ) as t(ord, title, detail, owner, area)
  loop
    if not exists (select 1 from public.tracker_items i where i.title = r.title) then
      insert into public.tracker_items (title, detail, owner, area, status, sort_order)
           values (r.title, r.detail, r.owner, r.area, 'Open', r.ord);
      seeded := seeded + 1;
    end if;
  end loop;

  raise notice 'Tracker: % backlog item(s) added (% already there)',
    seeded, 15 - seeded;
end $seed$;

-- ------------------------------------------------------------------------
-- 0146_tracker_air_liquide_id.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- ONE TRACKER ITEM, ADDED BY SQL RATHER THAN BY HAND.
--
-- The user, 2026-09-08: "Add - Collect Engineer's Air Liquide ID , Map it in
-- the User Master and then Inform the Rithi Admin - Assign it to Devika".
--
-- WHY A MIGRATION FOR ONE ROW. The Tracker is a live table nobody can write to
-- from here -- the sandbox has no route to the database, and applying SQL is
-- the user's own step by design. A seeded row travels with the bundle instead,
-- so it arrives the same on every project rather than depending on who typed it
-- in. It is a row somebody could equally add on the page in twenty seconds;
-- this way it is also in the record.
--
-- IDEMPOTENT BY TITLE, like 0144. Running the bundle twice does not give
-- anybody a second copy, and an item somebody has since edited or closed is
-- left exactly as they left it.
-- ===========================================================================

do $seed$
declare
  seeded int := 0;
begin
  if to_regclass('public.tracker_items') is null then
    raise notice 'tracker_items is missing -- run tracker.sql first';
    return;
  end if;

  if not exists (
    select 1 from public.tracker_items i
     where i.title = 'Collect every engineer''s Air Liquide ID'
  ) then
    insert into public.tracker_items (title, detail, owner, area, status, sort_order)
    values (
      'Collect every engineer''s Air Liquide ID',
      'Collect the Air Liquide ID from each engineer, map it against their row in User Master, and tell the Rithi Admin once it is done. The mapping is what lets a person be recognised across both systems; until it exists the two directories can only be matched by name, which is exactly the join that goes wrong quietly.',
      'Devika',
      'Data',
      'Open',
      -- ABOVE the seeded backlog (which starts at 10). It was asked for
      -- directly and has a named owner, which the backlog items mostly do not.
      5
    );
    seeded := 1;
  end if;

  raise notice 'Tracker: % item added (Air Liquide ID)', seeded;
end $seed$;

-- ------------------------------------------------------------------------
-- 0150_tracker_sync_backlog.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE TRACKER CATCHES UP WITH THE BACKLOG.
--
-- The user, 2026-09-08: "Update the Tracker as per backlog."
--
-- 0144 seeded the fifteen items open when the Tracker shipped. A day of work
-- has happened since: the 13485 review raised its own, three decisions were
-- PARKED at the user's direction, and Indoor Service went from an unanswered
-- question to a written plan. This adds what is open now and was not there
-- then.
--
-- ADDITIVE, AND IDEMPOTENT BY TITLE. Nothing is closed, renamed or deleted
-- here. An item somebody has since edited, re-owned or marked Done is left
-- exactly as they left it, and running the bundle twice adds nothing -- the
-- same rule 0144 follows, and the reason a seed can live in a bundle that is
-- replayed freely.
--
-- WHY NOT CLOSE THE ONES THAT ARE DONE. Because "done" is a judgement the
-- people using the list make, not one a migration should make for them: a row
-- closed by SQL is a row somebody has to re-open to argue with. The backlog
-- records what shipped; the Tracker records what those people are working on,
-- and the two are deliberately not the same list.
-- ===========================================================================

do $seed$
declare
  seeded int := 0;
  r      record;
begin
  if to_regclass('public.tracker_items') is null then
    raise notice 'tracker_items is missing -- run tracker.sql first';
    return;
  end if;

  for r in
    select * from (values
      -- ---- parked decisions (the user, 2026-09-08: "Park it in Backlog") ----
      (200, 'DECISION: Frequent Failure — the complaint condition, and old answers',
            'The rule is settled and written down: two or more failures INCLUDING the call under review, within a month, same equipment or the same part in the same machine, window and threshold editable in Admin Config. Two things block the build. (1) Does the same-equipment path still require a matching complaint? The rule of 2026-09-06 said yes; the written procedure does not mention it. (2) Review 2 auto-answers on a schedule (0124), so a new rule re-bases judgements already recorded — leave them as answered, or re-open them? Either way a quality record is being restated.',
            'Decision', 'DCCR'),
      (210, 'DECISION: ANNEXURE A — CMC''s bucket, and two missing call fields',
            'The SLA cannot express the procedure. sla_rules holds ONE target_hours per key; ANNEXURE A is a cover x problem-criticality x spare-availability matrix. Criticality and spare availability do not exist as fields on a call, so capturing them is a change to call registration rather than to a rules table. And CMC is a live cover type (WGP/OGP/CMC/AMC) that ANNEXURE A does not mention. Until then breach highlighting measures against targets the procedure does not set: closure = 5 days where it says 3, closure_spare_noncover = 10 where it says 15, and nothing at all for the four OGP rows.',
            'Decision', 'SLA'),
      (220, 'DECISION: Indoor Service — five questions before Phase 1',
            'The plan is written and phased (docs/INDOOR_SERVICE_PLAN.md). Five things to settle: does Central Service hold its own spare stock; must QC be done by somebody other than the person who did the work; does the SLA clock keep running while a machine is on the bench; the job-number series (IND26-0001?); and who may transfer a call to Indoor — Hotline only, as the procedure says, or managers too. Phase 1 stands alone and is what finally makes the Indoor Service heading appear, since a nav group with no pages renders as nothing.',
            'Decision', 'Indoor Service'),

      -- ---- the 13485 review ------------------------------------------------
      (230, 'Post-service verification against acceptance criteria (SR-006)',
            'The largest gap in the servicing requirements. §7.5.4 asks that it is verified that product requirements are met after servicing; "Solved" is a CALL outcome, not a statement that the device performs to specification. The Indoor procedure §4.5.6 already requires a quality check on completion — so the process exists and the RECORD lives outside this system. A per-product checklist of parameter, expected value and pass/fail, on the visit that closes a call.',
            'Claude', 'Quality'),
      (240, 'A measurement is not tied to a calibrated instrument (SR-020)',
            '§7.6. No instrument register, no calibration due dates, and a service report does not record WHICH instrument produced a reading — so a measurement does not evidence conformity, and an instrument later found out of calibration cannot be traced to the records it touched. Only worth building after SR-006 exists.',
            'Claude', 'Quality'),
      (250, 'The complaint determination is not recorded (SR-027)',
            'Cheapest real gain in the whole review, and now load-bearing: the field call register IS the complaint register by the decision of 2026-09-08, so a field marking WHICH calls are complaints is what makes the population producible. Without it the register says either that every field call is a complaint (untrue, and it inflates the rate) or that none is. One controlled field and a reason, on the Daily Call Review that already runs daily — plus SR-039, the recorded handoff to the system that holds CAPA, since §7.5.4(b) does not end at a system boundary.',
            'Claude', 'Quality'),
      (260, 'A complaint that never becomes a call has nowhere to live (SR-038)',
            'The exposure the boundary decision creates. If the field call register is the complaint register, a complaint arriving by any other route — a customer emailing Commercial about labelling, a distributor report on a device already replaced — is recorded nowhere. Either every complaint enters as a call, or the complaint register is elsewhere and this system feeds it. What cannot stand is the middle.',
            'Decision', 'Quality'),
      (270, 'Is any servicing subcontracted?',
            '§7.5.4 says "the organization OR ITS SUPPLIER". If any servicing is subcontracted, those records sit outside the daily analysis entirely and the gap is invisible from inside RITHI. Worth confirming either way — a no closes SR-035/036 permanently.',
            'Rithi Admin', 'Quality')
    ) as t(ord, title, detail, owner, area)
  loop
    if not exists (select 1 from public.tracker_items i where i.title = r.title) then
      insert into public.tracker_items (title, detail, owner, area, status, sort_order)
           values (r.title, r.detail, r.owner, r.area, 'Open', r.ord);
      seeded := seeded + 1;
    end if;
  end loop;

  raise notice 'Tracker: % item(s) added from the backlog (% already there)',
    seeded, 8 - seeded;
end $seed$;

-- ------------------------------------------------------------------------
-- 0157_tracker_sync_0909.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE TRACKER CATCHES UP — the points open at the end of 2026-09-09.
--
-- The user: "then list the Pending points and update the tracker."
--
-- ADDITIVE AND IDEMPOTENT BY TITLE, like 0144 and 0150. Nothing is closed,
-- renamed or deleted: an item somebody has edited, re-owned or marked Done is
-- left exactly as they left it, and running the bundle twice adds nothing.
--
-- "Done" stays a judgement the people using the list make. A row closed by SQL
-- is a row somebody has to re-open to argue with -- and the two lists are
-- deliberately different: the backlog records what shipped and why, the Tracker
-- records what is being worked on.
--
-- WHAT IS NOT HERE: everything already seeded by 0144 and 0150 (the parked
-- decisions, the 13485 findings). This adds only what became open since, or
-- what was open all along and had never been written down.
--
-- ONE ITEM WAS REMOVED BEFORE THIS FILE EVER RAN (2026-09-09): "Confirm the
-- super-admin revocation actually took". The user pasted the _status.sql output
-- the same evening and row 118 read `yes`, so the question was answered before
-- the seed could ask it. Seeding an answered item as Open would put a job on
-- somebody's list that is already done -- and closing it here in SQL would break
-- this file's own rule that Done is the reader's judgement. So it is simply not
-- seeded. (If an earlier copy of 0157 had already run somewhere, the row exists
-- and is Open; tick it.)
-- ===========================================================================

do $seed$
declare
  seeded int := 0;
  total  int := 0;
  r      record;
begin
  if to_regclass('public.tracker_items') is null then
    raise notice 'tracker_items is missing -- run tracker.sql first';
    return;
  end if;

  for r in
    select * from (values
      -- ---- verification the user can close in a minute ---------------------
      (310, 'Assign the Zoho Migration role to a login',
            'The role exists and is a read-only clone of Technical Support, but nobody holds it. It is in the User Master role dropdown. Kept separate from Technical Support on purpose: it ends when the migration does, so revoking it is one tick and leaves the support login alone.',
            'Rithi Admin', 'Access'),

      -- ---- parked, with the reason it is parked ---------------------------
      (320, 'Un-park the auto-apply pipeline (one character)',
            'CI/CD to apply migrations is BUILT and merged but parked. It failed on an unencoded "@" in the database password -- psql read the tail of the password as part of the hostname, so it never reached the database. Percent-encode it (@ -> %40) in the SUPABASE_DB_URL secret, then Actions -> Apply database migrations -> mode baseline with baseline_through set to the last migration really applied, then mode apply. WARNING: a fragment of the password reached a PUBLIC Actions log before the scrubber was fixed -- reset the database password and delete those runs when picking this up.',
            'Rithi Admin', 'Infrastructure'),

      -- ---- design settled, not built --------------------------------------
      -- PHASE 1 SHIPPED THE SAME DAY THIS FILE WAS WRITTEN (v0.9.182), so the
      -- item is what is LEFT rather than what was asked for. Rewritten rather
      -- than closed: the work did not finish, it moved on a phase.
      (330, 'Indoor Service: Phase 2 (the call loop) and Phase 3 (QC criteria)',
            'Phase 1 shipped on 2026-09-09 (v0.9.182): the register, both axes, all six activities, the page and the permissions -- run indoor.sql. PHASE 2 is the loop with the call: the transfer of 4.5.1 keeping ONE call and ONE UCN, a chip on the call saying it is at Indoor Service, and the completion report of 4.5.7 closing it. This is SR-044, the one requirement in section L still Absent. PHASE 3 is QC that means something: indoor_job_checks already holds parameter / expected / measured / verdict / instrument / calibration due, so it needs the per-product REFERENCE MEASUREMENTS, which do not exist as data. Until then SR-043 is closed in form and not in substance, and that difference is the whole of SR-006.',
            'Claude', 'Indoor Service'),
      (340, 'DECISION: who may condemn a unit, and where a salvaged part goes',
            'From the Indoor activity work, and STILL OPEN after Phase 1 -- which settled only the reversible half of each. Condemning is now its own permission (indoor.condemn), enforced by a trigger and granted to ADMIN ALONE, so nobody can scrap a machine by accident; but WHO SHOULD hold it is the question, and scrapping CUSTOMER property in particular cannot be an engineer''s own decision. A salvaged part is RECORDED with its condition grade and destination and credited to NO stock balance, because a harvested part entering stock under its normal code is indistinguishable from new -- the register already holds a refurbished part under its own code (URS-027), and salvage should do the same or the grade means nothing. No balance moves until this is answered.',
            'Decision', 'Indoor Service'),

      -- ---- open data questions --------------------------------------------
      (350, 'Party spellings: run the tidy-up, or leave it',
            'A party spelled two ways showed no products, because products carried CAPITALS while the party row was Title Case. The register is CORRECT without any SQL -- the lookups match case-insensitively as of v0.9.174. _party_name_normalise.sql is an optional tidy-up (dry run by default) that aligns the stored spellings so exports and groupings agree too, and separately lists products whose party has no row at all.',
            'Rithi Admin', 'Data'),
      (360, 'The spare_bulk_approval suite emits an unlabelled error',
            'Pre-existing, and reproduces identically against main''s own migrations, so it is not from any recent change -- but by this project''s convention every error a suite prints should be one labelled "expect ERROR", and this one is not. "Nothing selected" at line 135, where the fixture''s BA-R2 lines appear not to exist.',
            'Claude', 'Testing')
    ) as t(ord, title, detail, owner, area)
  loop
    total := total + 1;
    if not exists (select 1 from public.tracker_items i where i.title = r.title) then
      insert into public.tracker_items (title, detail, owner, area, status, sort_order)
           values (r.title, r.detail, r.owner, r.area, 'Open', r.ord);
      seeded := seeded + 1;
    end if;
  end loop;

  raise notice 'Tracker: % of % item(s) added (% already there)', seeded, total, total - seeded;
end $seed$;

-- ------------------------------------------------------------------------
-- 0296_tracker_delete_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0296 — DELETING A TRACKER ITEM IS ITS OWN KEY
--
-- Findings 57-67 (docs/PERMISSIONS_REVIEW.md), the user's decisions of
-- 2026-09-30: "63, 64: It should show the Individual View's Control Action and
-- its Check Box" -- each screen gets keys of its own, today's grants copied
-- across (0298) so nobody gains or loses anything on the day it ships -- and
-- "67: Break it down", with the old key kept as the PARENT of the new ones, so
-- a role holding it keeps everything until an administrator unticks it.
-- The parent rule itself is in has_perm() (0286, public.perm_parents).
--
-- This file: everybody who opens the Tracker still adds and edits (the
-- user's design); deleting asks tracker.delete, copied by 0298 to every
-- role that holds the Tracker today.
-- ===========================================================================

drop policy if exists tracker_rw     on public.tracker_items;
drop policy if exists tracker_read   on public.tracker_items;
drop policy if exists tracker_insert on public.tracker_items;
drop policy if exists tracker_update on public.tracker_items;
drop policy if exists tracker_delete on public.tracker_items;
create policy tracker_read on public.tracker_items for select using (public.has_perm('mod:/tracker'));
create policy tracker_insert on public.tracker_items for insert with check (public.has_perm('mod:/tracker'));
create policy tracker_update on public.tracker_items for update
  using (public.has_perm('mod:/tracker')) with check (public.has_perm('mod:/tracker'));
create policy tracker_delete on public.tracker_items for delete
  using (public.has_perm('mod:/tracker') and public.has_perm('tracker.delete'));

-- ------------------------------------------------------------------------
-- 0162_tracker_nl_team.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0162 — the tracker's "With whom" never reads "Claude"; it reads "NL Team".
--
-- The user's instruction (2026-09-11): the assignee on a tracker item is a
-- TEAM, not a tool. Everyone reading the tracker is from the customer's side
-- of the table, and an item parked "with Claude" tells them nothing they can
-- chase — "NL Team" is a party they can ask.
--
-- Three seed migrations wrote 'Claude' into tracker_items.owner (0144, 0150,
-- 0157). Those are applied history and are not edited; this renames what they
-- left behind, and it must stay LAST in the `tracker` module of
-- scripts/build-apply-bundles.mjs — the bundles are replayed one at a time, so
-- if 0144 ran after this, 'Claude' would simply come back.
--
-- Idempotent: re-running it changes nothing once no row says 'Claude'.
-- ===========================================================================

update public.tracker_items
   set owner = 'NL Team',
       updated_at = now()
 where btrim(coalesce(owner, '')) ilike 'claude';

-- ------------------------------------------------------------------------
-- 0158_indoor_service.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- INDOOR SERVICE — the workshop register (procedure §4.5). PHASE 1.
--
-- The plan is docs/INDOOR_SERVICE_PLAN.md and this is its Phase 1: the register
-- itself, standing alone. Phase 2 is the loop with the call (the transfer of
-- 4.5.1, the chip on the call, the completion report of 4.5.7); Phase 3 is QC
-- with acceptance criteria, which is what SR-006 actually asks for.
--
-- TWO AXES, NOT ONE, and this is the decision the whole shape rests on:
--
--   `kind`     -- WHOSE PROPERTY IS THIS. Customer property or a DEMO unit.
--                 It is not a label: it is what turns the custody duties of
--                 §7.5.10 on or off, which is precisely why the procedure gives
--                 DEMO units a different tag (4.5.5).
--   `activity` -- WHAT IS BEING DONE TO IT. Repair, Rework, Salvage,
--                 Pre-delivery inspection, Demo, Other.
--
-- One field cannot carry both. A pre-delivery check and a demo are both on the
-- company's own stock; a rework may be on either. Vignesh supplied four
-- activities and invited the split ("choose or creat ur own"): Repair is added
-- back because it is what §4.5 is actually about, and "recycling or rework" is
-- separated into Rework (§8.3.4, bringing a nonconforming unit back to spec)
-- and Salvage (SR-017, harvesting parts from a condemned one) — because calling
-- both by one word puts a scrapping decision and a repair decision in the same
-- bucket.
--
-- THE REGISTER IS NOT AN ATTRIBUTE OF A CALL. 4.5.5 puts DEMO units in here, and
-- a DEMO unit has no customer, no complaint and no call. So `ucn` is NULLABLE
-- and the register stands on its own; a call is "at Indoor Service" iff it has
-- an open row here, derived in one lookup the way UCN colours already are.
--
-- NO COLUMN IS ADDED TO THE THREE CALL TABLES AND THE `calls` VIEW IS NOT
-- REBUILT. That is not a shortcut, it is the safer road: `create or replace
-- view` drops `security_invoker`, which has silently exposed every call to every
-- user three times in this project (0040 -> 0050 -> 0057). Not rebuilding that
-- view avoids the whole class of fault.
--
-- WHAT THE PERMISSIONS ENFORCE, AND WHERE. The procedure separates the roles, so
-- the rights are separate: indoor.receive, indoor.work, indoor.qc,
-- indoor.dispatch, indoor.condemn. THREE OF THEM ARE ENFORCED BY A TRIGGER
-- BELOW, not by hiding buttons — this project has learned that a right the
-- database does not test is decoration (0126, 0127). `indoor.qc` being its own
-- right is the one that matters: it is what allows the check to be somebody
-- other than the person who did the work.
--
-- WHAT IS DELIBERATELY NOT ENFORCED, and why it is a warning rather than a
-- block: whether QC must be done by SOMEBODY ELSE. The procedure does not say
-- (open question 2 in the plan). Both names are recorded, so the segregation is
-- auditable either way and the screen warns when they match — turning that into
-- a hard block later is one line here, and unblocking a workshop that turns out
-- to have one qualified person is not.
--
-- A SALVAGED PART IS RECORDED, NOT CREDITED TO STOCK. Open question 7 has a real
-- risk attached: a harvested part entering hand stock under its normal code is
-- indistinguishable from a new one, and the condition grade becomes decoration.
-- Phase 1 therefore records the harvest and touches no balance. Recording
-- without crediting is the half that cannot go wrong.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- THE JOB NUMBER — IND<YY>-<NNNN>, restarting each year.
--
-- Its own series, because a DEMO unit has no UCN to be known by. Same shape as
-- the UCN counters (0125): one row per year, seeded PAST whatever that year
-- already carries, so it is safe to apply mid-year and correct after an import
-- that back-fills one. The year is INDIA'S -- `now()` is UTC and would roll the
-- year over at 5:30 am on 1 January, which is the same bug 0125 fixed for the
-- UCN's date.
--
-- RLS on with no policy: nothing but the definer function below may see or
-- touch it.
-- ---------------------------------------------------------------------------
create table if not exists public.indoor_job_counters (
  yr      smallint not null primary key,
  last_no integer  not null default 0
);
alter table public.indoor_job_counters enable row level security;

create or replace function public.next_indoor_job_no()
returns text language plpgsql volatile security definer set search_path = public as $$
declare
  v_yr  smallint := extract(year from (now() at time zone 'Asia/Kolkata'))::smallint;
  v_yy  text     := to_char((now() at time zone 'Asia/Kolkata'), 'YY');
  v_hi  integer;
  v_no  integer;
begin
  -- The highest number ALREADY ISSUED this year. The shape test matters as much
  -- as the prefix: an imported job_no that is not IND<YY>-<NNNN> has no number
  -- to compare, and right(job_no,4)::int on one would raise rather than skip it.
  select coalesce(max(right(job_no, 4)::int), 0) into v_hi
    from public.indoor_jobs
   where job_no like 'IND' || v_yy || '-%'
     and job_no ~ ('^IND' || v_yy || '-[0-9]{4}$');

  insert into public.indoor_job_counters (yr, last_no)
       values (v_yr, v_hi)
  on conflict (yr) do update
          set last_no = greatest(public.indoor_job_counters.last_no, excluded.last_no);

  update public.indoor_job_counters
     set last_no = last_no + 1
   where yr = v_yr
  returning last_no into v_no;

  return 'IND' || v_yy || '-' || lpad(v_no::text, 4, '0');
end $$;
revoke all on function public.next_indoor_job_no() from public;

-- ---------------------------------------------------------------------------
-- THE REGISTER. One row per equipment intake.
--
-- Wide on purpose. Six activities share a core -- everything §4.5 asks of every
-- unit that comes in -- and each adds fields only it needs. The alternative is
-- six tables that cannot be listed together, or a jsonb blob that nothing can
-- constrain; a register whose columns say what each activity owes is the one
-- that can be audited.
--
-- CLEANING APPLIES TO ALL SIX. A unit that has been in a hospital is
-- decontaminated before anyone opens it, whether it is going to be repaired,
-- stripped for parts or sent out on demo. WI/SER/01 does not care why it came in.
-- ---------------------------------------------------------------------------
create table if not exists public.indoor_jobs (
  id            bigint generated always as identity primary key,
  job_no        text not null unique,

  -- NULLABLE, and that is the point: a DEMO unit has no call.
  ucn           text,

  kind          text not null default 'Customer property'
                check (kind in ('Customer property', 'DEMO unit')),
  activity      text not null default 'Repair'
                check (activity in ('Repair', 'Rework', 'Salvage',
                                    'Pre-delivery inspection', 'Demo', 'Other')),

  product_name  text not null default '',
  serial        text not null default '',
  party_name    text,                       -- null for a DEMO unit with no customer

  -- 4.5.2 -- who received it, when.
  received_at   timestamptz not null default now(),
  received_by   uuid,
  condition_on_arrival text not null default '',
  tag_no        text not null default '',   -- 4.5.4 / 4.5.5, the physical tag

  status        text not null default 'Received'
                check (status in ('Received', 'Cleaned', 'Under repair',
                                  'Awaiting spares', 'QC', 'Ready',
                                  'Dispatched', 'Closed', 'Condemned')),

  -- 4.5.3 -- cleaned and disinfected per WI/SER/01, and against WHICH revision.
  cleaned_at    timestamptz,
  cleaned_by    uuid,
  cleaning_wi   text not null default 'WI/SER/01',
  cleaning_wi_rev text not null default '',

  work_done     text not null default '',
  findings      text not null default '',

  -- 4.5.6 -- the quality check is its OWN record, not a line in the work text.
  qc_result     text check (qc_result in ('Pass', 'Fail')),
  qc_by         uuid,
  qc_at         timestamptz,
  qc_notes      text not null default '',

  -- 4.5.7
  dispatched_at timestamptz,
  dispatched_by uuid,
  dispatch_ref  text not null default '',

  -- §7.5.10's reporting duty, which otherwise has nowhere to live: damage to
  -- the customer's property is theirs to be told about.
  damage_note   text not null default '',
  reported_to_customer_at timestamptz,
  reported_to_customer_by uuid,

  -- ---- Rework (§8.3.4) ---------------------------------------------------
  nc_reference           text not null default '',
  rework_instruction     text not null default '',
  rework_instruction_rev text not null default '',
  rework_authorised_by   text not null default '',
  rework_authorised_at   timestamptz,
  -- §8.3.4 ASKS FOR THIS EXPLICITLY and it is the field most likely to be left
  -- out: does reworking this unit harm it in some other way?
  adverse_effect_assessed boolean,
  adverse_effect_note    text not null default '',
  reverified_by          text not null default '',
  reverified_at          timestamptz,
  reverification_result  text check (reverification_result in ('Pass', 'Fail')),
  disposition            text check (disposition in ('Released', 'Scrapped')),

  -- ---- Salvage (SR-017) --------------------------------------------------
  condemned_reason text not null default '',
  condemned_by     uuid,
  condemned_at     timestamptz,
  -- The hard gate. Nobody opens a used medical device before it is cleaned;
  -- enforced on the harvest rows below rather than warned about.
  decontaminated   boolean not null default false,
  disposal_method  text not null default '',
  disposal_ref     text not null default '',
  customer_informed boolean not null default false,

  -- ---- Pre-delivery inspection (SR-003 / SR-006 / SR-020) ----------------
  source_ref       text not null default '',
  checklist_ref    text not null default '',
  checklist_rev    text not null default '',
  firmware_version text not null default '',
  accessories_per_packing_list boolean,
  -- "Pass with observation" is what stops a real finding being rounded up to
  -- Pass. A Fail does not leave the workshop.
  pdi_result       text check (pdi_result in ('Pass', 'Pass with observation', 'Fail')),
  released_by      uuid,
  released_at      timestamptz,
  held_reason      text not null default '',

  -- ---- Demo --------------------------------------------------------------
  demo_for_party   text not null default '',
  requested_by     text not null default '',
  expected_out     date,
  expected_return  date,
  actual_out       date,
  actual_return    date,
  custody_holder   text not null default '',
  condition_out    text not null default '',
  condition_back   text not null default '',
  consumables_used text not null default '',
  demo_outcome     text check (demo_outcome in ('Converted', 'Returned', 'Damaged', 'Lost')),
  sale_ref         text not null default '',

  -- ---- Other -------------------------------------------------------------
  -- "Other" with no description is a hole in the record, so the constraint is
  -- on the table and not on the form.
  activity_note    text not null default '',

  created_by    uuid,
  created_at    timestamptz not null default now(),
  updated_by    uuid,
  updated_at    timestamptz not null default now(),

  constraint indoor_jobs_other_needs_note
    check (activity <> 'Other' or btrim(activity_note) <> ''),
  -- A unit is not condemned without a reason. Scrapping a machine is a decision
  -- with an author, and "Condemned" with an empty reason records only the half
  -- that needs no explaining.
  constraint indoor_jobs_condemned_needs_reason
    check (status <> 'Condemned' or btrim(condemned_reason) <> '')
);

create index if not exists indoor_jobs_status_idx  on public.indoor_jobs (status, id desc);
create index if not exists indoor_jobs_ucn_idx     on public.indoor_jobs (ucn) where ucn is not null;
create index if not exists indoor_jobs_serial_idx  on public.indoor_jobs (lower(btrim(serial)));
-- The number this register exists to produce: DEMO units out past their due
-- date. Nothing else in the system tracks company assets sitting at a customer.
create index if not exists indoor_jobs_demo_due_idx
  on public.indoor_jobs (expected_return)
  where activity = 'Demo' and actual_return is null;

-- ---------------------------------------------------------------------------
-- ACCESSORIES — 4.5.4 says accessories carry the PARENT equipment's details.
--
-- A list, because returning the customer's accessories is part of returning
-- their property, and a list is what makes that checkable at dispatch. Without
-- it "and its accessories" is a sentence in a text box that nobody can tick off.
-- ---------------------------------------------------------------------------
create table if not exists public.indoor_job_accessories (
  id       bigint generated always as identity primary key,
  job_id   bigint not null references public.indoor_jobs (id) on delete cascade,
  name     text not null default '',
  serial   text not null default '',
  tag_no   text not null default '',
  returned boolean not null default false,
  note     text not null default ''
);
create index if not exists indoor_job_accessories_job_idx
  on public.indoor_job_accessories (job_id, id);

-- ---------------------------------------------------------------------------
-- HARVESTED PARTS — SR-017, and the condition grade is the whole point.
--
-- A harvested part is not a new part. `destination` is where it went, in words,
-- because Phase 1 deliberately does NOT credit hand stock: a part entering
-- stock under its normal code is indistinguishable from new, and until that is
-- settled (open question 7) recording it is right and crediting it is not.
-- ---------------------------------------------------------------------------
create table if not exists public.indoor_job_parts (
  id          bigint generated always as identity primary key,
  job_id      bigint not null references public.indoor_jobs (id) on delete cascade,
  part_code   text not null default '',
  description text not null default '',
  qty         numeric not null default 0 check (qty >= 0),
  condition_grade text not null default ''
              check (condition_grade in ('', 'Serviceable', 'Repairable', 'Scrap')),
  destination text not null default '',
  note        text not null default ''
);
create index if not exists indoor_job_parts_job_idx
  on public.indoor_job_parts (job_id, id);

-- ---------------------------------------------------------------------------
-- THE CHECKS — expected against measured, and the instrument that measured it.
--
-- This is SR-003 and SR-006, and the pair SR-020 needs to mean anything: a
-- measurement from an uncalibrated meter is not evidence. It arrives in Phase 1
-- because a pre-delivery inspection without expected-vs-measured is not an
-- inspection, it is a signature -- and the same structure serves QC after a
-- repair when Phase 3 gives it per-product reference values.
-- ---------------------------------------------------------------------------
create table if not exists public.indoor_job_checks (
  id          bigint generated always as identity primary key,
  job_id      bigint not null references public.indoor_jobs (id) on delete cascade,
  seq         integer not null default 0,
  parameter   text not null default '',
  expected    text not null default '',
  measured    text not null default '',
  verdict     text not null default ''
              check (verdict in ('', 'Pass', 'Fail', 'N/A')),
  instrument  text not null default '',
  instrument_serial text not null default '',
  calibration_due   date
);
create index if not exists indoor_job_checks_job_idx
  on public.indoor_job_checks (job_id, seq, id);

-- ---------------------------------------------------------------------------
-- WHO, AND WHEN. Stamped here so a client cannot forget it or fake it, and the
-- job number is assigned here so two intakes at once cannot collide on one.
-- ---------------------------------------------------------------------------
create or replace function public.indoor_jobs_stamp()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.updated_at := now();
  if auth.uid() is not null then new.updated_by := auth.uid(); end if;

  if tg_op = 'INSERT' then
    new.created_at := now();
    if auth.uid() is not null then new.created_by := auth.uid(); end if;
    -- The job number is the DATABASE'S to issue, and a client-supplied one is
    -- DISCARDED rather than trusted -- the same way a call's registrant is
    -- (0113). Not "filled in when blank": a number the client may set when it
    -- feels like it is a number two people can mint, and the first thing that
    -- happens then is two machines answering to one job number. The test suite
    -- sends IND99-9999 and expects it gone.
    new.job_no := public.next_indoor_job_no();
    if new.received_by is null and auth.uid() is not null then
      new.received_by := auth.uid();
    end if;
  else
    -- An edit cannot rewrite who took the machine in, or when it arrived.
    new.created_by := old.created_by;
    new.created_at := old.created_at;
    new.job_no     := old.job_no;
  end if;
  return new;
end $$;
drop trigger if exists zz_indoor_jobs_stamp on public.indoor_jobs;
create trigger zz_indoor_jobs_stamp before insert or update on public.indoor_jobs
  for each row execute function public.indoor_jobs_stamp();

-- ---------------------------------------------------------------------------
-- THE GUARD — the rules that are not the screen's to keep.
--
-- Everything here was learned the hard way on the call tables (0126, 0127): a
-- right the database does not test is a hidden button, and hidden buttons are
-- found. Each rule below is one somebody could otherwise walk around with a
-- direct PostgREST call.
-- ---------------------------------------------------------------------------
create or replace function public.indoor_jobs_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  -- An administrator is not gated by the stage rights; every other rule below
  -- still applies to them, because the ones that follow are about the RECORD
  -- being coherent rather than about who is allowed to act.
  if not public.is_admin() then
    if tg_op = 'UPDATE' then
      if (new.qc_result is distinct from old.qc_result
       or new.qc_by     is distinct from old.qc_by
       or new.qc_at     is distinct from old.qc_at
       or new.qc_notes  is distinct from old.qc_notes)
         and not public.has_perm('indoor.qc') then
        raise exception 'indoor.qc is required to record a quality check'
          using errcode = '42501';
      end if;

      if (new.dispatched_at is distinct from old.dispatched_at
       or new.dispatch_ref  is distinct from old.dispatch_ref
       or new.dispatched_by is distinct from old.dispatched_by)
         and not public.has_perm('indoor.dispatch') then
        raise exception 'indoor.dispatch is required to dispatch a unit'
          using errcode = '42501';
      end if;
    end if;

    -- CONDEMNING IS ITS OWN RIGHT, on insert as well as update. Scrapping
    -- customer property in particular cannot be an engineer's own decision
    -- (open question 8 in the plan, settled here the safe way: a separate
    -- permission granted to nobody by default).
    if (tg_op = 'INSERT' and (btrim(new.condemned_reason) <> '' or new.status = 'Condemned'))
    or (tg_op = 'UPDATE' and (new.condemned_reason is distinct from old.condemned_reason
                           or new.condemned_at     is distinct from old.condemned_at
                           or (new.status = 'Condemned' and old.status <> 'Condemned'))) then
      if not public.has_perm('indoor.condemn') then
        raise exception 'indoor.condemn is required to condemn a unit'
          using errcode = '42501';
      end if;
      if new.condemned_at is null then new.condemned_at := now(); end if;
      if new.condemned_by is null then new.condemned_by := auth.uid(); end if;
    end if;
  end if;

  -- A MACHINE CANNOT LEAVE WITH A FAILED CHECK. 4.5.6 puts the quality check
  -- before the return, so a failed one sends it back to Under repair rather
  -- than being noted and stepped over.
  if new.status in ('Ready', 'Dispatched', 'Closed') and new.qc_result = 'Fail' then
    raise exception 'the quality check failed -- the unit returns to Under repair, it does not leave'
      using errcode = '23514';
  end if;

  -- AND A REPAIR OR REWORK CANNOT LEAVE WITH NO CHECK AT ALL. The other four
  -- activities are exempt on purpose: a demo going out and a unit stripped for
  -- parts have no repair to verify, and a pre-delivery inspection records its
  -- verdict in pdi_result instead.
  if new.status in ('Dispatched', 'Closed')
     and new.activity in ('Repair', 'Rework')
     and new.qc_result is null then
    raise exception 'a % cannot be dispatched before its quality check is recorded (4.5.6)', lower(new.activity)
      using errcode = '23514';
  end if;

  -- A FAILED PRE-DELIVERY INSPECTION DOES NOT SHIP either, and a held one says
  -- why it is being held.
  if new.status in ('Dispatched', 'Closed')
     and new.activity = 'Pre-delivery inspection' and new.pdi_result = 'Fail' then
    raise exception 'a failed pre-delivery inspection does not leave the workshop'
      using errcode = '23514';
  end if;

  -- Timestamps that follow from an action are stamped, not typed: a cleaning
  -- date somebody can type is a cleaning date somebody can back-date.
  if new.status <> 'Received' and old is distinct from null then
    if new.cleaned_by is distinct from coalesce(old.cleaned_by, new.cleaned_by)
       and new.cleaned_at is null then
      new.cleaned_at := now();
    end if;
  end if;
  if new.qc_result is not null and new.qc_at is null then
    new.qc_at := now();
    if new.qc_by is null then new.qc_by := auth.uid(); end if;
  end if;
  if new.dispatch_ref <> '' and new.dispatched_at is null then
    new.dispatched_at := now();
    if new.dispatched_by is null then new.dispatched_by := auth.uid(); end if;
  end if;

  return new;
end $$;
drop trigger if exists zz_indoor_jobs_guard on public.indoor_jobs;
create trigger zz_indoor_jobs_guard before insert or update on public.indoor_jobs
  for each row execute function public.indoor_jobs_guard();

-- ---------------------------------------------------------------------------
-- THE HARD GATE — nothing is harvested from a unit that has not been cleaned.
--
-- The one rule in this file that BLOCKS rather than warns, and the plan says so
-- in as many words. Everything else here is a record; this is a person putting
-- their hands inside a device that has been in a hospital. WI/SER/01 comes
-- first, and the register is where that is provable.
-- ---------------------------------------------------------------------------
create or replace function public.indoor_job_parts_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_ok boolean;
begin
  select decontaminated into v_ok from public.indoor_jobs where id = new.job_id;
  if not coalesce(v_ok, false) then
    raise exception 'the unit has not been decontaminated -- nothing is harvested from it yet (WI/SER/01, 4.5.3)'
      using errcode = '23514';
  end if;
  return new;
end $$;
drop trigger if exists zz_indoor_job_parts_guard on public.indoor_job_parts;
create trigger zz_indoor_job_parts_guard before insert or update on public.indoor_job_parts
  for each row execute function public.indoor_job_parts_guard();

-- ---------------------------------------------------------------------------
-- ROW-LEVEL SECURITY.
--
-- READING is the module right: whoever may open the page sees the register.
-- There is no per-engineer scope here on purpose -- a workshop register that
-- showed each person only their own jobs could not answer "where is that
-- machine?", which is the question it exists for.
--
-- WRITING asks for any ONE of the stage rights, and the guard above decides
-- which fields each of them may actually move. The policy cannot do that job:
-- it sees the row, not which columns changed.
-- ---------------------------------------------------------------------------
alter table public.indoor_jobs            enable row level security;
alter table public.indoor_job_accessories enable row level security;
alter table public.indoor_job_parts       enable row level security;
alter table public.indoor_job_checks      enable row level security;

drop policy if exists indoor_read on public.indoor_jobs;
create policy indoor_read on public.indoor_jobs for select
  using (public.has_perm('mod:/indoor'));

drop policy if exists indoor_insert on public.indoor_jobs;
create policy indoor_insert on public.indoor_jobs for insert
  with check (public.has_perm('indoor.receive'));

drop policy if exists indoor_update on public.indoor_jobs;
create policy indoor_update on public.indoor_jobs for update
  using (public.has_perm('indoor.receive') or public.has_perm('indoor.work')
      or public.has_perm('indoor.qc')      or public.has_perm('indoor.dispatch')
      or public.has_perm('indoor.condemn'))
  with check (public.has_perm('indoor.receive') or public.has_perm('indoor.work')
      or public.has_perm('indoor.qc')      or public.has_perm('indoor.dispatch')
      or public.has_perm('indoor.condemn'));

-- NO DELETE POLICY, and that is the same rule 0049 sets for consumption: a
-- quality record is not deleted. A job raised in error is closed with the
-- reason in its own words, so the register says what happened rather than
-- silently no longer mentioning a customer's machine.

-- The three child tables follow the parent: reading is the module right,
-- writing asks for indoor.work -- with harvested parts additionally gated by the
-- decontamination trigger above.
do $$
declare t text;
begin
  foreach t in array array['indoor_job_accessories', 'indoor_job_parts', 'indoor_job_checks'] loop
    execute format('drop policy if exists %I on public.%I', t || '_read', t);
    execute format(
      'create policy %I on public.%I for select using (public.has_perm(''mod:/indoor''))',
      t || '_read', t);
    execute format('drop policy if exists %I on public.%I', t || '_write', t);
    execute format(
      'create policy %I on public.%I for all using (%s) with check (%s)',
      t || '_write', t,
      'public.has_perm(''indoor.work'') or public.has_perm(''indoor.receive'')',
      'public.has_perm(''indoor.work'') or public.has_perm(''indoor.receive'')');
  end loop;
end $$;

grant select, insert, update on public.indoor_jobs to authenticated;
grant select, insert, update, delete on public.indoor_job_accessories to authenticated;
grant select, insert, update, delete on public.indoor_job_parts       to authenticated;
grant select, insert, update, delete on public.indoor_job_checks      to authenticated;

-- ---------------------------------------------------------------------------
-- THE LIST, WITH NAMES AND THE NUMBER THE REGISTER EXISTS TO PRODUCE.
--
-- SECURITY INVOKER, so the policies above decide who sees it and not the view's
-- owner. Three times in this project a view has read as its owner and handed
-- every signed-in user everything (0040, 0050, 0057).
-- ---------------------------------------------------------------------------
drop view if exists public.indoor_job_list;
create view public.indoor_job_list as
  select j.*,
         coalesce(rb.name, '') as received_by_name,
         coalesce(cb.name, '') as cleaned_by_name,
         coalesce(qb.name, '') as qc_by_name,
         coalesce(db.name, '') as dispatched_by_name,
         coalesce(xb.name, '') as condemned_by_name,
         coalesce(ub.name, '') as updated_by_name,
         (j.status in ('Closed', 'Dispatched', 'Condemned')) as is_closed,
         -- A DEMO unit out past its due date, which is the one figure nothing
         -- else in this system produces. NULL rather than false where there is
         -- no due date: "not overdue" and "nobody said when" are different facts.
         (case when j.activity = 'Demo' and j.actual_return is null
                    and j.expected_return is not null
               then (j.expected_return < (now() at time zone 'Asia/Kolkata')::date)
          end) as demo_overdue,
         (select count(*) from public.indoor_job_accessories a where a.job_id = j.id)
           as accessory_count,
         (select count(*) from public.indoor_job_accessories a
           where a.job_id = j.id and not a.returned) as accessories_outstanding
    from public.indoor_jobs j
    left join public.app_user_names rb on rb.id = j.received_by
    left join public.app_user_names cb on cb.id = j.cleaned_by
    left join public.app_user_names qb on qb.id = j.qc_by
    left join public.app_user_names db on db.id = j.dispatched_by
    left join public.app_user_names xb on xb.id = j.condemned_by
    left join public.app_user_names ub on ub.id = j.updated_by;
alter view public.indoor_job_list set (security_invoker = on);
grant select on public.indoor_job_list to authenticated;

comment on table public.indoor_jobs is
  'The Indoor Service Register (procedure §4.5). TWO AXES: kind says whose property the unit is, which turns the custody duties of §7.5.10 on or off; activity says what is being done to it. The call (ucn) is OPTIONAL, because a DEMO unit has no call -- which is why this is a register in its own right and not a stage a call can be in.';

-- ---------------------------------------------------------------------------
-- WHO GETS IT, in the STORED rows -- because a page nobody holds is invisible.
--
-- This is the trap 0151 exists for and it is worth restating: DEFAULT_PERMS in
-- the app is only a fallback for a role whose app_roles row is EMPTY, and every
-- role here has a populated row. So adding a module in code grants it to
-- NOBODY: the nav asks can('mod:/indoor'), the stored list lacks it, and the
-- page never appears -- with no error anywhere to explain why.
--
-- MERGED, NEVER OVERWRITTEN. An administrator may have tuned any of these roles
-- and a straight assignment would silently undo that.
--
-- WHO, AND WHY:
--   * admin / technical_support / zoho_migration -- every module key, by what
--     those roles ARE. The last two are read-only by what they do not hold:
--     the module key alone opens the page, and every write here is gated by an
--     action they have not got.
--   * nsm and spare_coordinator get the page and the working rights: the
--     workshop is theirs to run.
--   * indoor.condemn IS GRANTED TO NOBODY BUT ADMIN. Scrapping a machine --
--     customer property above all -- is not a default, it is a decision
--     somebody makes deliberately in Roles & Permissions. Open question 8 in
--     the plan asks who may condemn; until it is answered, the safe answer is
--     "whoever an administrator says", not "anyone who can open the page".
-- ---------------------------------------------------------------------------
do $indoor_perms$
declare
  r        record;
  v_add    jsonb;
begin
  if to_regclass('public.app_roles') is null then
    raise notice 'app_roles is missing -- run rbac.sql first';
    return;
  end if;

  for r in select role, permissions from public.app_roles loop
    v_add := '[]'::jsonb;

    if r.role in ('admin', 'technical_support', 'zoho_migration') then
      v_add := v_add || '["mod:/indoor"]'::jsonb;
    end if;
    if r.role = 'admin' then
      v_add := v_add || '["indoor.receive","indoor.work","indoor.qc","indoor.dispatch","indoor.condemn"]'::jsonb;
    end if;
    if r.role in ('nsm', 'spare_coordinator', 'stores_incharge') then
      v_add := v_add || '["mod:/indoor","indoor.receive","indoor.work","indoor.dispatch"]'::jsonb;
    end if;
    -- QC is separate from the work on purpose (4.5.6): giving both to the same
    -- role by default would make the segregation impossible to arrange later
    -- without taking something away from somebody.
    if r.role in ('nsm') then
      v_add := v_add || '["indoor.qc"]'::jsonb;
    end if;

    if jsonb_array_length(v_add) > 0 then
      update public.app_roles a
         set permissions = (
               select jsonb_agg(distinct p)
                 from jsonb_array_elements_text(coalesce(a.permissions, '[]'::jsonb) || v_add) t(p))
       where a.role = r.role;
    end if;
  end loop;
end $indoor_perms$;

-- ------------------------------------------------------------------------
-- 0297_indoor_status_needs_dispatch.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0297 — A UNIT IS NOT DISPATCHED THROUGH THE STATUS PICKER WITHOUT THE DISPATCH RIGHT
--
-- Findings 57-67 (docs/PERMISSIONS_REVIEW.md), the user's decisions of
-- 2026-09-30: "63, 64: It should show the Individual View's Control Action and
-- its Check Box" -- each screen gets keys of its own, today's grants copied
-- across (0298) so nobody gains or loses anything on the day it ships -- and
-- "67: Break it down", with the old key kept as the PARENT of the new ones, so
-- a role holding it keeps everything until an administrator unticks it.
-- The parent rule itself is in has_perm() (0286, public.perm_parents).
--
-- This file: finding 59. The guard asked indoor.dispatch only when the
-- dispatch date, reference or dispatcher changed, so the Status picker could
-- set Dispatched or Closed with indoor.work alone. It now asks it for that
-- status change too.
-- ===========================================================================

CREATE OR REPLACE FUNCTION public.indoor_jobs_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- An administrator is not gated by the stage rights; every other rule below
  -- still applies to them, because the ones that follow are about the RECORD
  -- being coherent rather than about who is allowed to act.
  if not public.is_admin() then
    if tg_op = 'UPDATE' then
      if (new.qc_result is distinct from old.qc_result
       or new.qc_by     is distinct from old.qc_by
       or new.qc_at     is distinct from old.qc_at
       or new.qc_notes  is distinct from old.qc_notes)
         and not public.has_perm('indoor.qc') then
        raise exception 'indoor.qc is required to record a quality check'
          using errcode = '42501';
      end if;

      if (new.dispatched_at is distinct from old.dispatched_at
       or new.dispatch_ref  is distinct from old.dispatch_ref
       or new.dispatched_by is distinct from old.dispatched_by)
         and not public.has_perm('indoor.dispatch') then
        raise exception 'indoor.dispatch is required to dispatch a unit'
          using errcode = '42501';
      end if;

      if new.status in ('Dispatched', 'Closed') and new.status is distinct from old.status
         and not public.has_perm('indoor.dispatch') then
        raise exception 'indoor.dispatch is required to mark a unit %', new.status
          using errcode = '42501';
      end if;
    end if;

    -- CONDEMNING IS ITS OWN RIGHT, on insert as well as update. Scrapping
    -- customer property in particular cannot be an engineer's own decision
    -- (open question 8 in the plan, settled here the safe way: a separate
    -- permission granted to nobody by default).
    if (tg_op = 'INSERT' and (btrim(new.condemned_reason) <> '' or new.status = 'Condemned'))
    or (tg_op = 'UPDATE' and (new.condemned_reason is distinct from old.condemned_reason
                           or new.condemned_at     is distinct from old.condemned_at
                           or (new.status = 'Condemned' and old.status <> 'Condemned'))) then
      if not public.has_perm('indoor.condemn') then
        raise exception 'indoor.condemn is required to condemn a unit'
          using errcode = '42501';
      end if;
      if new.condemned_at is null then new.condemned_at := now(); end if;
      if new.condemned_by is null then new.condemned_by := auth.uid(); end if;
    end if;
  end if;

  -- A MACHINE CANNOT LEAVE WITH A FAILED CHECK. 4.5.6 puts the quality check
  -- before the return, so a failed one sends it back to Under repair rather
  -- than being noted and stepped over.
  if new.status in ('Ready', 'Dispatched', 'Closed') and new.qc_result = 'Fail' then
    raise exception 'the quality check failed -- the unit returns to Under repair, it does not leave'
      using errcode = '23514';
  end if;

  -- AND A REPAIR OR REWORK CANNOT LEAVE WITH NO CHECK AT ALL. The other four
  -- activities are exempt on purpose: a demo going out and a unit stripped for
  -- parts have no repair to verify, and a pre-delivery inspection records its
  -- verdict in pdi_result instead.
  if new.status in ('Dispatched', 'Closed')
     and new.activity in ('Repair', 'Rework')
     and new.qc_result is null then
    raise exception 'a % cannot be dispatched before its quality check is recorded (4.5.6)', lower(new.activity)
      using errcode = '23514';
  end if;

  -- A FAILED PRE-DELIVERY INSPECTION DOES NOT SHIP either, and a held one says
  -- why it is being held.
  if new.status in ('Dispatched', 'Closed')
     and new.activity = 'Pre-delivery inspection' and new.pdi_result = 'Fail' then
    raise exception 'a failed pre-delivery inspection does not leave the workshop'
      using errcode = '23514';
  end if;

  -- Timestamps that follow from an action are stamped, not typed: a cleaning
  -- date somebody can type is a cleaning date somebody can back-date.
  if new.status <> 'Received' and old is distinct from null then
    if new.cleaned_by is distinct from coalesce(old.cleaned_by, new.cleaned_by)
       and new.cleaned_at is null then
      new.cleaned_at := now();
    end if;
  end if;
  if new.qc_result is not null and new.qc_at is null then
    new.qc_at := now();
    if new.qc_by is null then new.qc_by := auth.uid(); end if;
  end if;
  if new.dispatch_ref <> '' and new.dispatched_at is null then
    new.dispatched_at := now();
    if new.dispatched_by is null then new.dispatched_by := auth.uid(); end if;
  end if;

  return new;
end $function$;

-- ------------------------------------------------------------------------
-- 0320_indoor_register_and_pdt.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0320 — THE INDOOR REGISTER CARRIES R/SER/07, AND A DEMO UNIT OF AN IMPORTED
--        PRODUCT CARRIES R/SER/QC/007
--
-- The user, 2026-10-02, with photographs of the two controlled paper records
-- the Indoor Service process keeps: "Compare what is there and tell me the
-- process / conception gap and implement process so that it is in line with
-- these records."
--
-- RECORD 1 -- R/SER/07 INDOOR SERVICE EQUIPMENT FAILURE REGISTER, two sheets
-- ("CUSTOMER - DEVICE's" and "DEMO"). Its columns the register did not hold:
--   Field Service Report No   field_report_no
--   Engineer Name             engineer_name   (DEMO: "Indoor Service")
--   Customer Place            customer_place
--   Problem Reported          problem_reported
--   Status (the COVER)        cover           WGP / OGP / CMC / AMC, read from
--                                             the machine by the screen and
--                                             editable (the user's decision 1)
--   Indoor Service Report No  indoor_report_no
--   DC No./Date               dispatch_ref (exists) + dc_date
--   Remarks                   remarks         free text (decision 2)
--   Verified By               verified_by / verified_at (decision 3)
-- `status` stays the WORKFLOW stage and `condition_on_arrival` stays what it
-- is: the paper's "Status" column is the cover, which is why it is a new
-- column and not a second meaning of an old one.
--
-- VERIFIED BY is a supervisor's verification of the COMPLETED row, so it is
-- its own key, `indoor.verify`, asked by the guard below; it is allowed only
-- once the job is Dispatched, Closed or Condemned; and who and when are
-- STAMPED from the session -- whatever the browser sends is discarded, the
-- rule every other stamp here keeps. The key is GRANTED TO NOBODY by this file
-- (the user's standing rule: Roles & Permissions is the administrator's). An
-- administrator passes has_perm() anyway.
--
-- RECORD 2 -- R/SER/QC/007 PRE DELIVERY TESTING (Quality Control), structured
-- in `indoor_pdt`, one row per job. It is OWED only by a DEMO unit whose
-- product line is IMPORTED (the user: "Pre-delivery check is done only for
-- Imported products, not for in-house manufactured equipment"):
--   * indoor_job_is_imported() answers from the Product Master (0319);
--   * UNKNOWN -- the product matches no line, or the line's `imported` is
--     blank -- does NOT require the test for dispatch (the user's decision),
--     and the screen says the answer is unknown so somebody fills the master;
--   * when it IS owed, the unit cannot move to Dispatched or Closed until the
--     test is COMPLETE (every field filled, inspector signed) and checks 1-5
--     all read OK. A NOT OK refuses -- "a machine cannot leave with a failed
--     check", the rule 0158 already keeps for the quality check.
-- Customer-property jobs keep the existing quality check unchanged.
--
-- The guard is 0297's body WORD FOR WORD with the new rules added after it;
-- every rule it carried is still here.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- 1. THE REGISTER'S COLUMNS
-- ---------------------------------------------------------------------------
alter table public.indoor_jobs
  add column if not exists field_report_no  text not null default '',
  add column if not exists engineer_name    text not null default '',
  add column if not exists customer_place   text not null default '',
  add column if not exists problem_reported text not null default '',
  add column if not exists indoor_report_no text not null default '',
  add column if not exists dc_date          date,
  add column if not exists remarks          text not null default '',
  add column if not exists cover            text not null default '',
  add column if not exists verified_by      uuid,
  add column if not exists verified_at      timestamptz;

comment on column public.indoor_jobs.cover is
  'R/SER/07 "Status": the machine''s COVER (WGP / OGP / CMC / AMC, cover_code()), read from the Product Database when the job is received or its product/serial changes, and editable. Not the workflow stage, which is `status`.';
comment on column public.indoor_jobs.verified_by is
  'R/SER/07 "Verified By": stamped from the session by indoor_jobs_guard() (0320) for a holder of indoor.verify, once the job is Dispatched, Closed or Condemned. A value the browser sends is discarded.';

-- ---------------------------------------------------------------------------
-- 2. IS THIS JOB'S PRODUCT IMPORTED? true / false / NULL (= not known)
--
-- THE MAPPING IS THE ONE THIS PROJECT ALREADY USES, in this order:
--   a. THE MACHINE'S OWN CODE. A job names model and serial; the Product
--      Database holds one machine per model+serial (`machine_key`, unique,
--      0079) and that machine's product code (`item_code`, 0194, whose comment
--      says it "joins this machine to its line on public.product_master").
--      Exact, and the only way to tell CPX CARE's nine codes apart.
--   b. THE NAME, as product_line_sellable() (0193) falls back to it:
--      upper(btrim()) equality on product_master.product_name. A name can have
--      several codes, so it answers only where EVERY code of that name gives
--      the same, non-blank answer; codes that disagree, or one left blank, is
--      UNKNOWN rather than a guess.
-- NULL means unknown, and the dispatch rule treats unknown as not owing the
-- test (the user's decision) while the screen says so.
--
-- PL/pgSQL and checked at RUN time on purpose: this module runs BEFORE the
-- masters module in ALL_ORDER, so `product_master.imported` (0319) does not
-- exist yet when this file is applied to an empty database. A function that
-- named it at creation would stop the bundle; this one answers NULL until the
-- column is there.
--
-- SECURITY DEFINER so the screen (through indoor_job_list) and the guard read
-- the same machine whatever the reader's Product Database visibility is -- an
-- answer that changed with who asked would be a dispatch rule that changed
-- with who asked. It returns one boolean about a product line, and the
-- Product Master is readable by every signed-in user anyway (pm_read).
-- ---------------------------------------------------------------------------
create or replace function public.indoor_job_is_imported(p_product_name text, p_serial text)
returns boolean
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_code text;
  v_ans  boolean;
  v_n    integer;
  v_set  integer;
  v_true integer;
begin
  if not exists (select 1 from information_schema.columns
                  where table_schema = 'public' and table_name = 'product_master'
                    and column_name = 'imported') then
    return null;
  end if;

  -- a. the machine's own code
  if coalesce(btrim(p_product_name), '') <> '' and coalesce(btrim(p_serial), '') <> ''
     and exists (select 1 from information_schema.columns
                  where table_schema = 'public' and table_name = 'products'
                    and column_name = 'item_code') then
    select nullif(btrim(p.item_code), '') into v_code
      from public.products p
     where p.machine_key = lower(btrim(p_product_name)) || '|' || lower(btrim(p_serial))
     limit 1;
    if v_code is not null then
      select count(*) into v_n
        from public.product_master pm
       where upper(btrim(pm.product_code)) = upper(v_code);
      if v_n = 1 then
        select pm.imported into v_ans from public.product_master pm
         where upper(btrim(pm.product_code)) = upper(v_code);
        return v_ans;
      end if;
    end if;
  end if;

  -- b. the name, only where every code of it agrees
  if coalesce(btrim(p_product_name), '') = '' then return null; end if;
  select count(*), count(pm.imported), count(*) filter (where pm.imported)
    into v_n, v_set, v_true
    from public.product_master pm
   where upper(btrim(pm.product_name)) = upper(btrim(p_product_name));
  if v_n = 0 or v_set < v_n then return null; end if;   -- no line, or one left blank
  if v_true = v_n then return true; end if;
  if v_true = 0 then return false; end if;
  return null;                                           -- the codes disagree
end $$;

comment on function public.indoor_job_is_imported(text, text) is
  'Is the product of an indoor job IMPORTED? true / false / NULL = unknown. The machine''s own code (Product Database, model+serial -> item_code -> product_master) first; else the product NAME, answering only where every code of that name agrees and none is blank (0320). Decides whether a DEMO unit owes Pre-Delivery Testing R/SER/QC/007; unknown does not.';

revoke all on function public.indoor_job_is_imported(text, text) from public;
do $$ begin
  execute 'revoke all on function public.indoor_job_is_imported(text, text) from anon';
  execute 'grant execute on function public.indoor_job_is_imported(text, text) to authenticated';
exception when undefined_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 3. R/SER/QC/007 PRE DELIVERY TESTING -- one row per job.
--
-- The form's own fields, in its own words. "HV" and "HT" are kept as the
-- paper prints them and NOT interpreted: text, because nobody has said what
-- they measure or in what unit. The two mode tables are the measured values
-- at FiO2 21 / 60 / 100 %; the SET values (V=500 ml, RR=12 bpm ...) are
-- printed on the form and are not data.
--
-- Check 6 on the paper -- "Only use the Accessories associated with the
-- respective machine." -- is an instruction, not a check, and has no column.
-- ---------------------------------------------------------------------------
create table if not exists public.indoor_pdt (
  id        bigint generated always as identity primary key,
  job_id    bigint not null unique references public.indoor_jobs (id) on delete cascade,

  test_date              date,
  measuring_equipment_id text not null default '',
  software_version       text not null default '',
  hv                     text not null default '',
  ht                     text not null default '',

  check1 text check (check1 in ('OK', 'NOT OK')),
  check2 text check (check2 in ('OK', 'NOT OK')),
  check3 text check (check3 in ('OK', 'NOT OK')),
  check4 text check (check4 in ('OK', 'NOT OK')),
  check5 text check (check5 in ('OK', 'NOT OK')),

  -- 7. Mode CMV/ACMV -- Volume (Vte), Peep, O2% at FiO2 21 / 60 / 100 %
  cmv_vte_21  numeric, cmv_vte_60  numeric, cmv_vte_100  numeric,
  cmv_peep_21 numeric, cmv_peep_60 numeric, cmv_peep_100 numeric,
  cmv_o2_21   numeric, cmv_o2_60   numeric, cmv_o2_100   numeric,
  -- 8. Mode PCMV -- PIP, Peep, O2% at FiO2 21 / 60 / 100 %
  pcmv_pip_21  numeric, pcmv_pip_60  numeric, pcmv_pip_100  numeric,
  pcmv_peep_21 numeric, pcmv_peep_60 numeric, pcmv_peep_100 numeric,
  pcmv_o2_21   numeric, pcmv_o2_60   numeric, pcmv_o2_100   numeric,

  -- Inspected by: stamped from the session at signing, with the name and the
  -- designation the person held THEN (User Master via profiles, 0199).
  inspected_by          uuid,
  inspector_name        text not null default '',
  inspector_designation text not null default '',
  inspected_at          timestamptz,

  created_by uuid,
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now()
);

comment on table public.indoor_pdt is
  'R/SER/QC/007 PRE DELIVERY TESTING, one row per indoor job (0320). Owed by a DEMO unit whose product line is imported (indoor_job_is_imported): such a unit is not Dispatched or Closed until every field here is filled, the inspector has signed, and checks 1-5 all read OK.';

-- WHO SIGNED IS THE SESSION'S, like every stamp in this module. Setting
-- inspected_by (to anything) is the act of signing: the trigger replaces it
-- with auth.uid() and fills the name, designation and time from the profile.
-- Clearing it withdraws the signature. Any other change to the four columns is
-- discarded.
create or replace function public.indoor_pdt_stamp()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_sign boolean;
begin
  new.updated_at := now();
  if auth.uid() is not null then new.updated_by := auth.uid(); end if;

  if tg_op = 'INSERT' then
    new.created_at := now();
    new.created_by := auth.uid();
    v_sign := new.inspected_by is not null;
  else
    new.created_at := old.created_at;
    new.created_by := old.created_by;
    new.job_id     := old.job_id;
    v_sign := new.inspected_by is distinct from old.inspected_by and new.inspected_by is not null;
    if new.inspected_by is null and old.inspected_by is not null then
      new.inspector_name := ''; new.inspector_designation := ''; new.inspected_at := null;
      return new;
    end if;
    if not v_sign then
      new.inspected_by          := old.inspected_by;
      new.inspector_name        := old.inspector_name;
      new.inspector_designation := old.inspector_designation;
      new.inspected_at          := old.inspected_at;
      return new;
    end if;
  end if;

  if v_sign then
    new.inspected_by := auth.uid();
    new.inspected_at := case when auth.uid() is null then null else now() end;
    select coalesce(nullif(btrim(p.full_name), ''), p.email, ''), coalesce(btrim(p.designation), '')
      into new.inspector_name, new.inspector_designation
      from public.profiles p where p.id = auth.uid();
    new.inspector_name        := coalesce(new.inspector_name, '');
    new.inspector_designation := coalesce(new.inspector_designation, '');
  else
    new.inspected_by := null; new.inspected_at := null;
    new.inspector_name := ''; new.inspector_designation := '';
  end if;
  return new;
end $$;
drop trigger if exists zz_indoor_pdt_stamp on public.indoor_pdt;
create trigger zz_indoor_pdt_stamp before insert or update on public.indoor_pdt
  for each row execute function public.indoor_pdt_stamp();

-- The audience of indoor_job_checks (0158): reading is the module key, writing
-- indoor.work or indoor.receive. NO DELETE policy and no DELETE grant: this is
-- a quality record (0049's rule), corrected by a further edit, never removed.
alter table public.indoor_pdt enable row level security;
drop policy if exists indoor_pdt_read on public.indoor_pdt;
create policy indoor_pdt_read on public.indoor_pdt for select
  using ((select public.has_perm('mod:/indoor')));
drop policy if exists indoor_pdt_insert on public.indoor_pdt;
create policy indoor_pdt_insert on public.indoor_pdt for insert
  with check ((select public.has_perm('indoor.work')) or (select public.has_perm('indoor.receive')));
drop policy if exists indoor_pdt_update on public.indoor_pdt;
create policy indoor_pdt_update on public.indoor_pdt for update
  using ((select public.has_perm('indoor.work')) or (select public.has_perm('indoor.receive')))
  with check ((select public.has_perm('indoor.work')) or (select public.has_perm('indoor.receive')));
grant select, insert, update on public.indoor_pdt to authenticated;

-- The five system columns, now where the module that adds them already ran
-- (on a fresh build sys_columns runs later and attaches it itself).
do $$
begin
  if to_regprocedure('public.sys_columns_attach(regclass)') is not null then
    perform public.sys_columns_attach('public.indoor_pdt'::regclass);
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- 4. THE GUARD -- 0297 verbatim, then the three new rules.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.indoor_jobs_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pdt   public.indoor_pdt%rowtype;
  v_blank text[];
  v_bad   text[];
begin
  -- An administrator is not gated by the stage rights; every other rule below
  -- still applies to them, because the ones that follow are about the RECORD
  -- being coherent rather than about who is allowed to act.
  if not public.is_admin() then
    if tg_op = 'UPDATE' then
      if (new.qc_result is distinct from old.qc_result
       or new.qc_by     is distinct from old.qc_by
       or new.qc_at     is distinct from old.qc_at
       or new.qc_notes  is distinct from old.qc_notes)
         and not public.has_perm('indoor.qc') then
        raise exception 'indoor.qc is required to record a quality check'
          using errcode = '42501';
      end if;

      if (new.dispatched_at is distinct from old.dispatched_at
       or new.dispatch_ref  is distinct from old.dispatch_ref
       or new.dispatched_by is distinct from old.dispatched_by)
         and not public.has_perm('indoor.dispatch') then
        raise exception 'indoor.dispatch is required to dispatch a unit'
          using errcode = '42501';
      end if;

      if new.status in ('Dispatched', 'Closed') and new.status is distinct from old.status
         and not public.has_perm('indoor.dispatch') then
        raise exception 'indoor.dispatch is required to mark a unit %', new.status
          using errcode = '42501';
      end if;
    end if;

    -- CONDEMNING IS ITS OWN RIGHT, on insert as well as update. Scrapping
    -- customer property in particular cannot be an engineer's own decision
    -- (open question 8 in the plan, settled here the safe way: a separate
    -- permission granted to nobody by default).
    if (tg_op = 'INSERT' and (btrim(new.condemned_reason) <> '' or new.status = 'Condemned'))
    or (tg_op = 'UPDATE' and (new.condemned_reason is distinct from old.condemned_reason
                           or new.condemned_at     is distinct from old.condemned_at
                           or (new.status = 'Condemned' and old.status <> 'Condemned'))) then
      if not public.has_perm('indoor.condemn') then
        raise exception 'indoor.condemn is required to condemn a unit'
          using errcode = '42501';
      end if;
      if new.condemned_at is null then new.condemned_at := now(); end if;
      if new.condemned_by is null then new.condemned_by := auth.uid(); end if;
    end if;
  end if;

  -- A MACHINE CANNOT LEAVE WITH A FAILED CHECK. 4.5.6 puts the quality check
  -- before the return, so a failed one sends it back to Under repair rather
  -- than being noted and stepped over.
  if new.status in ('Ready', 'Dispatched', 'Closed') and new.qc_result = 'Fail' then
    raise exception 'the quality check failed -- the unit returns to Under repair, it does not leave'
      using errcode = '23514';
  end if;

  -- AND A REPAIR OR REWORK CANNOT LEAVE WITH NO CHECK AT ALL. The other four
  -- activities are exempt on purpose: a demo going out and a unit stripped for
  -- parts have no repair to verify, and a pre-delivery inspection records its
  -- verdict in pdi_result instead.
  if new.status in ('Dispatched', 'Closed')
     and new.activity in ('Repair', 'Rework')
     and new.qc_result is null then
    raise exception 'a % cannot be dispatched before its quality check is recorded (4.5.6)', lower(new.activity)
      using errcode = '23514';
  end if;

  -- A FAILED PRE-DELIVERY INSPECTION DOES NOT SHIP either, and a held one says
  -- why it is being held.
  if new.status in ('Dispatched', 'Closed')
     and new.activity = 'Pre-delivery inspection' and new.pdi_result = 'Fail' then
    raise exception 'a failed pre-delivery inspection does not leave the workshop'
      using errcode = '23514';
  end if;

  -- Timestamps that follow from an action are stamped, not typed: a cleaning
  -- date somebody can type is a cleaning date somebody can back-date.
  if new.status <> 'Received' and old is distinct from null then
    if new.cleaned_by is distinct from coalesce(old.cleaned_by, new.cleaned_by)
       and new.cleaned_at is null then
      new.cleaned_at := now();
    end if;
  end if;
  if new.qc_result is not null and new.qc_at is null then
    new.qc_at := now();
    if new.qc_by is null then new.qc_by := auth.uid(); end if;
  end if;
  if new.dispatch_ref <> '' and new.dispatched_at is null then
    new.dispatched_at := now();
    if new.dispatched_by is null then new.dispatched_by := auth.uid(); end if;
  end if;

  -- ======================== 0320 ========================================

  -- R/SER/QC/007. A DEMO UNIT OF AN IMPORTED PRODUCT DOES NOT LEAVE UNTESTED.
  -- Asked on the MOVE into Dispatched / Closed (or a job filed or re-kinded
  -- straight into one), not on every later edit: a unit already out before
  -- this rule existed can still be verified and remarked. UNKNOWN imported-ness
  -- does not require the test -- the user's decision; the screen says unknown.
  if new.kind = 'DEMO unit' and new.status in ('Dispatched', 'Closed')
     and (tg_op = 'INSERT' or new.status is distinct from old.status
          or new.kind is distinct from old.kind
          or new.product_name is distinct from old.product_name
          or new.serial is distinct from old.serial)
     and coalesce(public.indoor_job_is_imported(new.product_name, new.serial), false) then
    select * into v_pdt from public.indoor_pdt where job_id = new.id;
    if not found then
      raise exception 'a DEMO unit of an imported product does not leave before its Pre-Delivery Testing (R/SER/QC/007) is recorded'
        using errcode = '23514';
    end if;
    v_bad := array_remove(array[
      case when v_pdt.check1 = 'NOT OK' then '1' end,
      case when v_pdt.check2 = 'NOT OK' then '2' end,
      case when v_pdt.check3 = 'NOT OK' then '3' end,
      case when v_pdt.check4 = 'NOT OK' then '4' end,
      case when v_pdt.check5 = 'NOT OK' then '5' end], null);
    if cardinality(v_bad) > 0 then
      raise exception 'Pre-Delivery Testing check % reads NOT OK -- a machine cannot leave with a failed check',
        array_to_string(v_bad, ', ')
        using errcode = '23514';
    end if;
    v_blank := array_remove(array[
      case when v_pdt.test_date is null then 'Date' end,
      case when btrim(v_pdt.measuring_equipment_id) = '' then 'Measuring Equipment ID No' end,
      case when btrim(v_pdt.software_version) = '' then 'Software Version' end,
      case when btrim(v_pdt.hv) = '' then 'HV' end,
      case when btrim(v_pdt.ht) = '' then 'HT' end,
      case when v_pdt.check1 is null or v_pdt.check2 is null or v_pdt.check3 is null
             or v_pdt.check4 is null or v_pdt.check5 is null then 'checks 1-5' end,
      case when v_pdt.cmv_vte_21 is null or v_pdt.cmv_vte_60 is null or v_pdt.cmv_vte_100 is null
             or v_pdt.cmv_peep_21 is null or v_pdt.cmv_peep_60 is null or v_pdt.cmv_peep_100 is null
             or v_pdt.cmv_o2_21 is null or v_pdt.cmv_o2_60 is null or v_pdt.cmv_o2_100 is null
           then 'the CMV/ACMV readings' end,
      case when v_pdt.pcmv_pip_21 is null or v_pdt.pcmv_pip_60 is null or v_pdt.pcmv_pip_100 is null
             or v_pdt.pcmv_peep_21 is null or v_pdt.pcmv_peep_60 is null or v_pdt.pcmv_peep_100 is null
             or v_pdt.pcmv_o2_21 is null or v_pdt.pcmv_o2_60 is null or v_pdt.pcmv_o2_100 is null
           then 'the PCMV readings' end,
      case when v_pdt.inspected_by is null then 'Inspected by (not signed)' end], null);
    if cardinality(v_blank) > 0 then
      raise exception 'Pre-Delivery Testing (R/SER/QC/007) is incomplete -- still blank: %',
        array_to_string(v_blank, ', ')
        using errcode = '23514';
    end if;
  end if;

  -- R/SER/07 "VERIFIED BY". Its own key; only on a completed row; who and when
  -- from the session. On insert there is nothing to verify yet, so whatever
  -- was sent is discarded.
  if tg_op = 'INSERT' then
    new.verified_by := null;
    new.verified_at := null;
  elsif new.verified_by is distinct from old.verified_by
     or new.verified_at is distinct from old.verified_at then
    if not public.has_perm('indoor.verify') then
      raise exception 'indoor.verify is required to verify an Indoor Service register entry'
        using errcode = '42501';
    end if;
    if new.verified_by is null then
      new.verified_at := null;               -- a verification withdrawn
    else
      if new.status not in ('Dispatched', 'Closed', 'Condemned') then
        raise exception 'a register entry is verified once the unit is Dispatched, Closed or Condemned -- this one is %', new.status
          using errcode = '23514';
      end if;
      new.verified_by := auth.uid();
      new.verified_at := now();
    end if;
  end if;

  -- R/SER/07 "Status" is the COVER, in the one vocabulary (0208), where that
  -- rule is installed. Run-time lookup: data_integrity runs after this module.
  if new.cover is distinct from (case when tg_op = 'UPDATE' then old.cover end)
     and to_regprocedure('public.cover_code(text)') is not null then
    execute 'select public.cover_code($1)' into new.cover using new.cover;
    new.cover := coalesce(new.cover, '');
  end if;

  return new;
end $function$;

-- ---------------------------------------------------------------------------
-- 5. THE LIST -- 0158's view, with the verifier's name, the accessories as the
--    register writes them, and whether the product is imported. `j.*` picks up
--    the new columns. MIRRORED WORD FOR WORD in 0245 (check:bundles).
-- ---------------------------------------------------------------------------
drop view if exists public.indoor_job_list;
create view public.indoor_job_list as
  select j.*,
         coalesce(rb.name, '') as received_by_name,
         coalesce(cb.name, '') as cleaned_by_name,
         coalesce(qb.name, '') as qc_by_name,
         coalesce(db.name, '') as dispatched_by_name,
         coalesce(xb.name, '') as condemned_by_name,
         coalesce(ub.name, '') as updated_by_name,
         (j.status in ('Closed', 'Dispatched', 'Condemned')) as is_closed,
         -- A DEMO unit out past its due date, which is the one figure nothing
         -- else in this system produces. NULL rather than false where there is
         -- no due date: "not overdue" and "nobody said when" are different facts.
         (case when j.activity = 'Demo' and j.actual_return is null
                    and j.expected_return is not null
               then (j.expected_return < (now() at time zone 'Asia/Kolkata')::date)
          end) as demo_overdue,
         (select count(*) from public.indoor_job_accessories a where a.job_id = j.id)
           as accessory_count,
         (select count(*) from public.indoor_job_accessories a
           where a.job_id = j.id and not a.returned) as accessories_outstanding,
         coalesce(vb.name, '') as verified_by_name,
         (select string_agg(btrim(a.name), ', ' order by a.id) from public.indoor_job_accessories a
           where a.job_id = j.id and btrim(a.name) <> '') as accessories_received,
         public.indoor_job_is_imported(j.product_name, j.serial) as product_imported
    from public.indoor_jobs j
    left join public.app_user_names rb on rb.id = j.received_by
    left join public.app_user_names cb on cb.id = j.cleaned_by
    left join public.app_user_names qb on qb.id = j.qc_by
    left join public.app_user_names db on db.id = j.dispatched_by
    left join public.app_user_names xb on xb.id = j.condemned_by
    left join public.app_user_names ub on ub.id = j.updated_by
    left join public.app_user_names vb on vb.id = j.verified_by;
alter view public.indoor_job_list set (security_invoker = on);
grant select on public.indoor_job_list to authenticated;

-- ------------------------------------------------------------------------
-- 0321_indoor_dc.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0321 — INDOOR_DC: THE DELIVERY CHALLAN THAT TAKES A UNIT OUT OF THE WORKSHOP
--
-- The user, 2026-10-02, with the paper template: a Delivery Challan for the
-- Indoor Service module ONLY -- "Name it Indoor_DC". It is separate from the
-- spare DC (spare_dispatches, 0027/0028), which this file does not touch.
--
-- THE USER'S DECISIONS, and where each one lives:
--   * Its own number, IDC-YYMM-NNNN, restarting each month by the DC DATE,
--     ISSUED BY THE DATABASE -- a number sent by the caller is discarded, the
--     rule the job number (0158) and the stock-out number (0027) keep.
--   * One DC may carry SEVERAL jobs going to the SAME consignee ("To"). The
--     consignee of a job is its party (customer property) or its "going to"
--     party (a DEMO unit, demo_for_party); jobs whose consignees differ are
--     refused together.
--   * Creating the DC stamps each job: dispatch_ref = the IDC number (R/SER/07
--     "DC No.") and dc_date = the DC date. IT DOES NOT CHANGE THE JOB'S STATUS
--     -- and the existing guard (0158) stamps dispatched_at / dispatched_by when
--     dispatch_ref is first set, exactly as it does when the reference is
--     typed on the job.
--   * The DC is NOT A WAY ROUND A DISPATCH RULE. Setting dispatch_ref alone
--     asks none of indoor_jobs_guard()'s leaving rules (a failed quality check,
--     a repair with no check, a failed PDI, a DEMO unit of an imported product
--     without its Pre-Delivery Testing -- 0158, 0297, 0320): they are asked on
--     the move into Dispatched / Closed. So each job is TRIED -- moved to
--     Dispatched inside a sub-transaction that is always rolled back -- and a
--     job the guard refuses is refused here with the guard's own words. The
--     rule is therefore not copied: whatever the guard says today, and
--     whatever it is changed to say, is what the DC says.
--   * Only a READY unit goes on a DC, and only one carrying no DC No. yet.
--   * Lines: per job, the equipment (PART No. = the product code the machine
--     carries in the Product Database, else the one code its name has on the
--     Product Master, else blank; DESCRIPTION = product + " Sl.No " + serial)
--     and then one line per accessory (name + " Sl.No " + serial). QTY 1.
--     PURPOSE typed once for the DC and editable per line.
--   * The "To" text, MIRN No. / Customer Ref No. and its date, and Mode of
--     Despatch are stored on the DC as typed.
--   * Permission: the existing indoor.dispatch. NO KEY IS ADDED AND NOTHING IS
--     GRANTED: the page is the Indoor Service Register's (mod:/indoor).
--
-- WRITTEN ONLY BY create_indoor_dc(). Both tables are readable with the page
-- and have NO write policy and no write grant: a DC row written straight
-- through the API would be a challan whose jobs were never stamped and never
-- tried against the leaving rules. The function asks indoor.dispatch itself.
-- A DC IS A RECORD OF A UNIT LEAVING: no delete policy, no delete grant, and
-- 0049's no_hard_delete trigger.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- 1. THE NUMBER -- IDC-YYMM-NNNN, one counter row per month.
--    The 0027 pattern (an upsert that locks the row, so two issuers in the
--    same instant get 0007 and 0008), seeded PAST whatever the month already
--    carries as 0158 seeds the job number, so it is safe after an import.
--    RLS on with no policy: nothing but the definer function touches it.
-- ---------------------------------------------------------------------------
create table if not exists public.indoor_dc_counters (
  period  text    not null primary key,   -- YYMM
  last_no integer not null default 0
);
alter table public.indoor_dc_counters enable row level security;
revoke all on public.indoor_dc_counters from public;
do $$ begin
  execute 'revoke all on public.indoor_dc_counters from anon, authenticated';
exception when undefined_object then null; end $$;

create or replace function public.next_indoor_dc_no(p_on date)
returns text language plpgsql volatile security definer set search_path = public as $$
declare
  v_on  date := coalesce(p_on, (now() at time zone 'Asia/Kolkata')::date);
  v_yymm text := to_char(v_on, 'YYMM');
  v_hi  integer := 0;
  v_no  integer;
begin
  if to_regclass('public.indoor_dcs') is not null then
    select coalesce(max(right(dc_no, 4)::int), 0) into v_hi
      from public.indoor_dcs
     where dc_no ~ ('^IDC-' || v_yymm || '-[0-9]{4}$');
  end if;
  insert into public.indoor_dc_counters (period, last_no) values (v_yymm, v_hi + 1)
  on conflict (period) do update
     set last_no = greatest(public.indoor_dc_counters.last_no, v_hi) + 1
  returning last_no into v_no;
  return 'IDC-' || v_yymm || '-' || lpad(v_no::text, 4, '0');
end $$;
comment on function public.next_indoor_dc_no(date) is
  'Issues the next Indoor DC number, IDC-YYMM-NNNN, restarting each month by the DC date (0321). Called only by the indoor_dcs insert trigger.';
-- Only the trigger calls it (it runs as the owner), so the API may not.
revoke all on function public.next_indoor_dc_no(date) from public;
do $$ begin
  execute 'revoke all on function public.next_indoor_dc_no(date) from anon, authenticated';
exception when undefined_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 2. THE DC AND ITS LINES
-- ---------------------------------------------------------------------------
create table if not exists public.indoor_dcs (
  id                bigint generated always as identity primary key,
  dc_no             text not null unique,
  dc_date           date not null default ((now() at time zone 'Asia/Kolkata')::date),
  consignee         text not null default '',   -- "To", as typed (prefilled from the Party Master)
  customer_ref      text not null default '',   -- "MIRN No. / CUSTOMER REF No."
  customer_ref_date date,                       -- its "DATE"
  mode_of_despatch  text not null default '',
  purpose           text not null default '',   -- typed once; each line carries its own copy
  issued_by_name    text not null default '',   -- "ISSUED BY (Stores)": the name RITHI knows for the creator
  created_by        uuid,
  created_at        timestamptz not null default now()
);
comment on table public.indoor_dcs is
  'Indoor_DC -- the Delivery Challan that takes Indoor Service units out of the workshop (0321). One DC, one consignee, one or more jobs. Number IDC-YYMM-NNNN issued by the database. Written only by create_indoor_dc(); never deleted.';
comment on column public.indoor_dcs.issued_by_name is
  'The creator''s name as the profile gave it when the DC was issued -- printed under ISSUED BY (Stores). Stamped from the session; a value sent is discarded.';

create table if not exists public.indoor_dc_lines (
  id           bigint generated always as identity primary key,
  dc_id        bigint not null references public.indoor_dcs (id),
  line_no      integer not null,
  job_id       bigint not null references public.indoor_jobs (id),
  -- NULL for the equipment line. An accessory removed from the job later
  -- leaves the line, and its description, as printed.
  accessory_id bigint references public.indoor_job_accessories (id) on delete set null,
  part_no      text not null default '',
  description  text not null default '',
  qty          numeric not null default 1 check (qty > 0),
  purpose      text not null default '',
  created_at   timestamptz not null default now(),
  unique (dc_id, line_no)
);
create index if not exists indoor_dc_lines_job_idx on public.indoor_dc_lines (job_id);
comment on table public.indoor_dc_lines is
  'The lines of an Indoor DC (0321): per job the equipment, then each accessory, QTY 1, each with its PURPOSE. A snapshot taken when the DC was issued, so a re-print is the same challan.';

-- The number and the issuer are the database's. An edit (only a trusted role
-- can make one: no write grant) cannot rewrite either.
create or replace function public.indoor_dcs_stamp()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if new.dc_date is null then new.dc_date := (now() at time zone 'Asia/Kolkata')::date; end if;
    new.dc_no      := public.next_indoor_dc_no(new.dc_date);
    new.created_at := now();
    new.created_by := auth.uid();
    select coalesce(nullif(btrim(p.full_name), ''), p.email, '') into new.issued_by_name
      from public.profiles p where p.id = auth.uid();
    new.issued_by_name := coalesce(new.issued_by_name, '');
  else
    new.dc_no          := old.dc_no;
    new.created_at     := old.created_at;
    new.created_by     := old.created_by;
    new.issued_by_name := old.issued_by_name;
  end if;
  return new;
end $$;
drop trigger if exists zz_indoor_dcs_stamp on public.indoor_dcs;
create trigger zz_indoor_dcs_stamp before insert or update on public.indoor_dcs
  for each row execute function public.indoor_dcs_stamp();

-- ---------------------------------------------------------------------------
-- 3. THE PRODUCT CODE OF A JOB -- for PART No. on the equipment line.
--    The mapping 0320's indoor_job_is_imported() uses, in its order:
--      a. the machine's own code: products.machine_key (model|serial) ->
--         item_code (0194);
--      b. the NAME on the Product Master, only where it has exactly ONE code.
--    Otherwise NULL, and PART No. prints blank: a guessed code on a challan is
--    worse than none. PL/pgSQL with run-time column tests for 0320's reason:
--    the masters module runs after this one.
-- ---------------------------------------------------------------------------
create or replace function public.indoor_job_product_code(p_product_name text, p_serial text)
returns text
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_code text;
  v_n    integer;
begin
  if coalesce(btrim(p_product_name), '') <> '' and coalesce(btrim(p_serial), '') <> ''
     and exists (select 1 from information_schema.columns
                  where table_schema = 'public' and table_name = 'products'
                    and column_name = 'item_code') then
    select nullif(btrim(p.item_code), '') into v_code
      from public.products p
     where p.machine_key = lower(btrim(p_product_name)) || '|' || lower(btrim(p_serial))
     limit 1;
    if v_code is not null then return v_code; end if;
  end if;

  if coalesce(btrim(p_product_name), '') = ''
     or to_regclass('public.product_master') is null then
    return null;
  end if;
  select count(distinct upper(btrim(pm.product_code))), min(btrim(pm.product_code))
    into v_n, v_code
    from public.product_master pm
   where upper(btrim(pm.product_name)) = upper(btrim(p_product_name))
     and btrim(coalesce(pm.product_code, '')) <> '';
  if v_n = 1 then return v_code; end if;
  return null;
end $$;
comment on function public.indoor_job_product_code(text, text) is
  'The product code of an indoor job''s equipment, for PART No. on an Indoor DC (0321): the machine''s own item_code (Product Database, model+serial), else the single code its name has on the Product Master; NULL otherwise.';
revoke all on function public.indoor_job_product_code(text, text) from public;
do $$ begin
  execute 'revoke all on function public.indoor_job_product_code(text, text) from anon';
  execute 'grant execute on function public.indoor_job_product_code(text, text) to authenticated';
exception when undefined_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 4. ISSUING A DC -- the only writer.
--
--   p_job_ids        the jobs, in the order they are to be printed
--   p_consignee      "To", as typed
--   p_dc_date        DATE (NULL = today in India)
--   p_customer_ref   MIRN No. / CUSTOMER REF No. (optional)
--   p_customer_ref_date  its DATE (optional)
--   p_mode           Mode of Despatch
--   p_purpose        PURPOSE, typed once
--   p_line_purposes  per-line PURPOSE overrides, [{job_id, accessory_id, purpose}]
--                    (accessory_id null = the equipment line)
--
-- SECURITY DEFINER so the tables can stay closed to direct writes; every
-- question about the CALLER is still asked of the caller: has_perm() and
-- is_admin() read the session, and the job updates run indoor_jobs_guard(),
-- which asks the caller's rights too.
-- ---------------------------------------------------------------------------
create or replace function public.create_indoor_dc(
  p_job_ids           bigint[],
  p_consignee         text,
  p_dc_date           date  default null,
  p_customer_ref      text  default '',
  p_customer_ref_date date  default null,
  p_mode              text  default '',
  p_purpose           text  default '',
  p_line_purposes     jsonb default '[]'::jsonb
) returns text
language plpgsql volatile security definer
set search_path = public
as $$
declare
  v_ids   bigint[];
  v_date  date := coalesce(p_dc_date, (now() at time zone 'Asia/Kolkata')::date);
  v_dc    bigint;
  v_no    text;
  v_line  integer := 0;
  v_state text;
  v_msg   text;
  v_keys  text;
  j       record;
  a       record;
  v_ov    jsonb;
begin
  if not public.has_perm('indoor.dispatch') then
    raise exception 'indoor.dispatch is required to issue an Indoor DC'
      using errcode = '42501';
  end if;

  select array_agg(x order by o) into v_ids
    from (select x, min(o) as o from unnest(p_job_ids) with ordinality u(x, o)
           where x is not null group by x) d;
  if coalesce(cardinality(v_ids), 0) = 0 then
    raise exception 'choose at least one Ready unit for the Indoor DC'
      using errcode = '22023';
  end if;
  if coalesce(btrim(p_consignee), '') = '' then
    raise exception 'an Indoor DC needs its consignee (To)'
      using errcode = '23514';
  end if;

  -- Every job must exist, and is locked for the rest of the transaction so two
  -- people cannot put one unit on two challans at once.
  perform 1 from public.indoor_jobs where id = any (v_ids) order by id for update;
  if (select count(*) from public.indoor_jobs where id = any (v_ids)) <> cardinality(v_ids) then
    raise exception 'an Indoor Service job on this DC was not found'
      using errcode = '23503';
  end if;

  -- ONE DC, ONE CONSIGNEE: a customer unit goes to its party, a DEMO unit to
  -- its "going to" party.
  select string_agg(distinct coalesce(nullif(btrim(k), ''), '(none)'), ' / ') into v_keys
    from (select case when kind = 'DEMO unit' then demo_for_party else party_name end as k
            from public.indoor_jobs where id = any (v_ids)) s;
  if (select count(distinct upper(btrim(coalesce(case when kind = 'DEMO unit' then demo_for_party
                                                       else party_name end, ''))))
        from public.indoor_jobs where id = any (v_ids)) > 1 then
    raise exception 'one Indoor DC goes to one consignee -- these units go to %', v_keys
      using errcode = '23514';
  end if;

  for j in
    select ij.*, u.o from public.indoor_jobs ij
      join unnest(v_ids) with ordinality u(x, o) on u.x = ij.id
     order by u.o
  loop
    if j.status <> 'Ready' then
      raise exception '%: only a Ready unit goes on an Indoor DC -- this one is %', j.job_no, j.status
        using errcode = '23514';
    end if;
    if btrim(j.dispatch_ref) <> '' then
      raise exception '%: already carries DC No. % -- one unit, one DC', j.job_no, j.dispatch_ref
        using errcode = '23514';
    end if;

    -- THE TRIAL. Would the guard let this unit leave? Asked by moving it to
    -- Dispatched and always rolling the move back.
    begin
      update public.indoor_jobs set status = 'Dispatched' where id = j.id;
      raise exception using errcode = 'P0001', message = 'indoor_dc_trial_passed';
    exception when others then
      get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text;
      if v_msg <> 'indoor_dc_trial_passed' then
        raise exception '%: %', j.job_no, v_msg using errcode = v_state;
      end if;
    end;
  end loop;

  -- Overrides must name a job on this DC (a purpose for a unit that is not
  -- here is a mistake, said rather than dropped).
  for v_ov in select * from jsonb_array_elements(coalesce(p_line_purposes, '[]'::jsonb)) loop
    if not coalesce((v_ov ->> 'job_id')::bigint = any (v_ids), false) then
      raise exception 'a line purpose names job %, which is not on this DC', v_ov ->> 'job_id'
        using errcode = '22023';
    end if;
  end loop;

  insert into public.indoor_dcs (dc_no, dc_date, consignee, customer_ref, customer_ref_date,
                                 mode_of_despatch, purpose)
  values ('auto', v_date, btrim(p_consignee), btrim(coalesce(p_customer_ref, '')), p_customer_ref_date,
          btrim(coalesce(p_mode, '')), btrim(coalesce(p_purpose, '')))
  returning id, dc_no into v_dc, v_no;

  for j in
    select ij.*, u.o from public.indoor_jobs ij
      join unnest(v_ids) with ordinality u(x, o) on u.x = ij.id
     order by u.o
  loop
    v_line := v_line + 1;
    insert into public.indoor_dc_lines (dc_id, line_no, job_id, accessory_id, part_no, description, qty, purpose)
    values (v_dc, v_line, j.id, null,
            coalesce(public.indoor_job_product_code(j.product_name, j.serial), ''),
            btrim(btrim(j.product_name) || case when btrim(j.serial) <> '' then ' Sl.No ' || btrim(j.serial) else '' end),
            1,
            coalesce((select e ->> 'purpose' from jsonb_array_elements(coalesce(p_line_purposes, '[]'::jsonb)) e
                       where (e ->> 'job_id')::bigint = j.id
                         and nullif(e ->> 'accessory_id', '') is null
                       limit 1), btrim(coalesce(p_purpose, ''))));
    for a in
      select * from public.indoor_job_accessories
       where job_id = j.id and (btrim(name) <> '' or btrim(serial) <> '')
       order by id
    loop
      v_line := v_line + 1;
      insert into public.indoor_dc_lines (dc_id, line_no, job_id, accessory_id, part_no, description, qty, purpose)
      values (v_dc, v_line, j.id, a.id, '',
              btrim(btrim(a.name) || case when btrim(a.serial) <> '' then ' Sl.No ' || btrim(a.serial) else '' end),
              1,
              coalesce((select e ->> 'purpose' from jsonb_array_elements(coalesce(p_line_purposes, '[]'::jsonb)) e
                         where (e ->> 'job_id')::bigint = j.id
                           and (e ->> 'accessory_id')::bigint = a.id
                         limit 1), btrim(coalesce(p_purpose, ''))));
    end loop;
  end loop;

  -- THE STAMP ON EACH JOB. Through the guard, as the caller: it asks
  -- indoor.dispatch for a change of dispatch_ref and stamps dispatched_at /
  -- dispatched_by, exactly as a reference typed on the job does.
  update public.indoor_jobs
     set dispatch_ref = v_no, dc_date = v_date
   where id = any (v_ids);

  return v_no;
end $$;
comment on function public.create_indoor_dc(bigint[], text, date, text, date, text, text, jsonb) is
  'Issues an Indoor DC (0321): asks indoor.dispatch; one consignee; only Ready units with no DC No.; each unit TRIED against indoor_jobs_guard()''s leaving rules and refused with the guard''s words; lines built from the jobs and their accessories; each job stamped dispatch_ref = IDC number, dc_date = DC date. Returns the IDC number.';
revoke all on function public.create_indoor_dc(bigint[], text, date, text, date, text, text, jsonb) from public;
do $$ begin
  execute 'revoke all on function public.create_indoor_dc(bigint[], text, date, text, date, text, text, jsonb) from anon';
  execute 'grant execute on function public.create_indoor_dc(bigint[], text, date, text, date, text, text, jsonb) to authenticated';
exception when undefined_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 5. WHO MAY READ, AND NOBODY MAY WRITE DIRECTLY
-- ---------------------------------------------------------------------------
alter table public.indoor_dcs      enable row level security;
alter table public.indoor_dc_lines enable row level security;

drop policy if exists indoor_dcs_read on public.indoor_dcs;
create policy indoor_dcs_read on public.indoor_dcs for select
  using ((select public.has_perm('mod:/indoor')));
drop policy if exists indoor_dc_lines_read on public.indoor_dc_lines;
create policy indoor_dc_lines_read on public.indoor_dc_lines for select
  using ((select public.has_perm('mod:/indoor')));

revoke all on public.indoor_dcs, public.indoor_dc_lines from public;
do $$ begin
  execute 'revoke all on public.indoor_dcs, public.indoor_dc_lines from anon, authenticated';
  execute 'grant select on public.indoor_dcs, public.indoor_dc_lines to authenticated';
exception when undefined_object then null; end $$;

-- RECORD RETENTION (0049): not deleted by the application, whatever grant a
-- project's defaults hand out. block_hard_delete() belongs to the audit
-- module, which runs before this one; guarded for a bundle replayed alone.
do $$
declare t text;
begin
  if to_regprocedure('public.block_hard_delete()') is not null then
    foreach t in array array['indoor_dcs', 'indoor_dc_lines'] loop
      execute format('drop trigger if exists no_hard_delete on public.%I', t);
      execute format('create trigger no_hard_delete before delete on public.%I for each row execute function public.block_hard_delete()', t);
    end loop;
  end if;
end $$;

-- The five system columns, now where the module that adds them already ran
-- (on a fresh build sys_columns runs later and attaches them itself). The
-- counter is a counter and gets none (0244's list).
do $$
begin
  if to_regprocedure('public.sys_columns_attach(regclass)') is not null then
    perform public.sys_columns_attach('public.indoor_dcs'::regclass);
    perform public.sys_columns_attach('public.indoor_dc_lines'::regclass);
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- 6. THE LIST -- one row per DC with its jobs and line count. Columns NAMED,
--    not d.* (a `*` view is expanded at creation and would need 0245's mirror).
-- ---------------------------------------------------------------------------
drop view if exists public.indoor_dc_list;
create view public.indoor_dc_list as
  select d.id, d.dc_no, d.dc_date, d.consignee, d.customer_ref, d.customer_ref_date,
         d.mode_of_despatch, d.purpose, d.issued_by_name, d.created_by, d.created_at,
         (select count(*) from public.indoor_dc_lines l where l.dc_id = d.id) as line_count,
         (select string_agg(j.job_no, ', ' order by l.line_no)
            from public.indoor_dc_lines l join public.indoor_jobs j on j.id = l.job_id
           where l.dc_id = d.id and l.accessory_id is null) as job_nos
    from public.indoor_dcs d;
alter view public.indoor_dc_list set (security_invoker = on);
grant select on public.indoor_dc_list to authenticated;

-- ------------------------------------------------------------------------
-- 0323_indoor_stages.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0323 — THE INDOOR SERVICE WORKFLOW AS STAGES: INTAKE -> CLEANING -> REPAIR
--        -> SERVICE REPORT (+ the visit, drafted) -> INDOOR_DC (+ the visit,
--        filed)
--
-- The user, 2026-10-02, describing how Ajay G (Indoor Service Engineer) and
-- Vignesh (head of Indoor Service) actually work, and asking for the screen to
-- be rebuilt around the stages. The decisions, and where each one lives:
--
--   INTAKE. A job is received FROM A CALL (product + serial lists its open
--   calls, or the UCN is typed) and fills from the call; or as a DEMO / new
--   device with no call. The call's Standard Complaint is shown beside the
--   Problem Reported, so it is kept: `standard_complaint` (snapshot at intake;
--   the indoor engineer may not be able to read the call later).
--   The RECEIVED ACCESSORIES are an add-item list WITH A QUANTITY: `qty` on
--   indoor_job_accessories, default 1, > 0.
--
--   SERVICE REPORT UPLOAD (stage 4). The report number (indoor_report_no, 0320)
--   and the uploaded file's link: report_file_url / report_file_name, with
--   report_uploaded_by / report_uploaded_at STAMPED from the session (a value
--   sent is discarded). REFUSED UNTIL THE UNIT IS CLEANED and refused without a
--   report number -- the order the user set: cleaning before upload. Uploading
--   is the indoor.work right (the work, not a new key).
--   For a job WITH A UCN the same form captures the VISIT -- every field of the
--   Visit Entry, by the Visit Entry's own form and rules -- as a DRAFT on the
--   job: `visit_draft` (jsonb) and `visit_date`. Nothing is written to the call.
--
--   INDOOR_DC (stage 5). "When the DC is approved add an entry to Visit entry
--   against the UCN" -- the DC is approved when it is issued (Authorised By is
--   recorded then; there is no other approval step). The screen FILES the
--   drafted visit through the Visit Entry's own save path BEFORE asking for the
--   DC, and records it on the job: `visit_uid` (the reports row) and
--   `visit_filed_at` (spares and feedback written too). create_indoor_dc() then
--   REFUSES a job with a UCN whose visit is not filed, and any job whose report
--   is not uploaded. A job with no UCN (a DEMO unit) files no visit.
--   AUTHORISED BY is chosen from the issuer's Reporting Manager, Regional
--   Manager (user_directory) and every active NSM (indoor_dc_authorisers()),
--   stored on the DC as `authorised_by_name` and printed.
--   THE DC DATE IS THE DATE OF ENTRY: create_indoor_dc() no longer takes one.
--   THE LINES CARRY THE ACCESSORIES' QUANTITIES as received.
--   A check-only call (p_check_only) asks every DC rule except "the visit is
--   filed" and writes nothing, so the screen can be refused BEFORE it files
--   visits for a DC that would not be issued.
--
-- The guard is 0320's body WORD FOR WORD with the new rules added after it;
-- create_indoor_dc is 0321's body with the changes above. Every rule either
-- carried is still here.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- 1. COLUMNS
-- ---------------------------------------------------------------------------
alter table public.indoor_job_accessories
  add column if not exists qty numeric not null default 1;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'indoor_job_accessories_qty_positive') then
    alter table public.indoor_job_accessories
      add constraint indoor_job_accessories_qty_positive check (qty > 0);
  end if;
end $$;
comment on column public.indoor_job_accessories.qty is
  'How many of this accessory were RECEIVED with the unit (0323). Printed on the Indoor DC line.';

alter table public.indoor_jobs
  add column if not exists standard_complaint  text not null default '',
  add column if not exists report_file_url     text not null default '',
  add column if not exists report_file_name    text not null default '',
  add column if not exists report_uploaded_by  uuid,
  add column if not exists report_uploaded_at  timestamptz,
  add column if not exists visit_draft         jsonb,
  add column if not exists visit_date          date,
  add column if not exists visit_uid           text,
  add column if not exists visit_filed_at      timestamptz;

comment on column public.indoor_jobs.standard_complaint is
  'The call''s Standard Complaint as it read when the unit was received from that call (0323). Shown read-only beside Problem Reported.';
comment on column public.indoor_jobs.report_file_url is
  'The uploaded Indoor Service Report (stage 4), filed in Drive as "<Indoor Service Report No>_<original file name>". Refused until the unit is cleaned and without a report number; who and when are stamped (0323).';
comment on column public.indoor_jobs.visit_draft is
  'For a job with a UCN: the Visit Entry answers captured with the report upload, a DRAFT. Filed against the UCN by the Visit Entry''s own save path when the Indoor DC is issued (0323).';
comment on column public.indoor_jobs.visit_uid is
  'The reports row (visit) filed against the UCN from this job''s draft (0323). Must name a visit of this job''s UCN.';
comment on column public.indoor_jobs.visit_filed_at is
  'When the drafted visit was filed in full -- the visit, its spares and its feedback (0323). Stamped; create_indoor_dc() requires it for a job with a UCN.';

alter table public.indoor_dcs
  add column if not exists authorised_by_name text not null default '',
  add column if not exists approval_status    text not null default 'Pending approval',
  add column if not exists approved_by        uuid,
  add column if not exists approved_by_name   text not null default '',
  add column if not exists approved_at        timestamptz,
  add column if not exists rejected_by        uuid,
  add column if not exists rejected_at        timestamptz,
  add column if not exists rejection_reason   text not null default '';
-- A DC issued BEFORE approval existed (0321 alone) was never put to anybody:
-- it reads as such rather than as approved by nobody, or as pending for ever.
-- Only rows with no Authorised By and no decision are touched; a DC made since
-- 0323 always names its Authorised By, so a re-run changes nothing.
update public.indoor_dcs
   set approval_status = 'Issued before approval'
 where approval_status = 'Pending approval' and btrim(authorised_by_name) = ''
   and approved_at is null and rejected_at is null;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'indoor_dcs_approval_status_check') then
    alter table public.indoor_dcs add constraint indoor_dcs_approval_status_check
      check (approval_status in ('Pending approval', 'Approved', 'Rejected', 'Issued before approval'));
  end if;
end $$;
comment on column public.indoor_dcs.authorised_by_name is
  'AUTHORISED BY on the Indoor DC: one of indoor_dc_authorisers() for the issuer, named when the DC was created (0323). That person -- by their User Master name -- or an administrator approves or rejects it.';
comment on column public.indoor_dcs.approval_status is
  'Pending approval (on creation) -> Approved (approve_indoor_dc, which needs every UCN job''s visit filed) or Rejected (reject_indoor_dc, which releases the units). Issued before approval = a DC made before 0323 (0323).';

-- THE RELEASE TICKET. A rejected DC clears its units' DC No.; the guard asks
-- indoor.dispatch for that, which the approver (a manager, an NSM) need not
-- hold. The exemption is a row here: RLS on, NO policy, no grant -- written
-- only by reject_indoor_dc() (definer) and read only by the guard (definer),
-- for the job and the transaction it was written in. A transaction-local
-- setting would be forgeable (set_config is anybody's), which is 0196's
-- lesson.
create table if not exists public.indoor_dc_release_tickets (
  job_id bigint not null,
  tx     bigint not null,
  primary key (job_id, tx)
);
alter table public.indoor_dc_release_tickets enable row level security;
revoke all on public.indoor_dc_release_tickets from public;
do $$ begin
  execute 'revoke all on public.indoor_dc_release_tickets from anon, authenticated';
exception when undefined_object then null; end $$;

-- The five system columns, where the module that adds them already ran (on a
-- fresh build sys_columns runs later and attaches them itself). Not a counter,
-- so not on 0244's exclusion list.
do $$
begin
  if to_regprocedure('public.sys_columns_attach(regclass)') is not null then
    perform public.sys_columns_attach('public.indoor_dc_release_tickets'::regclass);
  end if;
end $$;

create or replace function public.indoor_dc_release_ticketed(p_job_id bigint)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.indoor_dc_release_tickets t
                  where t.job_id = p_job_id and t.tx = txid_current());
$$;
revoke all on function public.indoor_dc_release_ticketed(bigint) from public;
do $$ begin
  execute 'revoke all on function public.indoor_dc_release_ticketed(bigint) from anon, authenticated';
exception when undefined_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 2. WHO MAY AUTHORISE THE ISSUER'S DC -- their Reporting Manager and Regional
--    Manager as the User Master names them, and every active NSM.
--    The issuer is the SESSION: matched to the User Master by the login's
--    email, the way my_dir_name() matches (email or gmail). SECURITY DEFINER
--    because profiles is readable row-by-row only to its owner; it returns
--    names and nothing else.
-- ---------------------------------------------------------------------------
create or replace function public.indoor_dc_authorisers()
returns table (name text, basis text)
language sql stable security definer
set search_path = public
as $$
  with me as (
    select lower(btrim(coalesce(p.email, auth.email(), ''))) as em
      from (select 1) x left join public.profiles p on p.id = auth.uid()
  ), dir as (
    select d.reporting_manager, d.regional_manager
      from public.user_directory d, me
     where me.em <> '' and (lower(btrim(coalesce(d.email, ''))) = me.em or lower(btrim(coalesce(d.gmail, ''))) = me.em)
     order by d.validity desc, d.id
     limit 1
  ), cand as (
    select btrim(reporting_manager) as name, 'Reporting Manager'::text as basis, 1 as o from dir
    union all
    select btrim(regional_manager), 'Regional Manager', 2 from dir
    union all
    select coalesce(nullif(btrim(p.full_name), ''), p.email), 'NSM', 3
      from public.profiles p where p.role = 'nsm' and p.active
  )
  select name, string_agg(basis, ' / ' order by o) as basis
    from cand where coalesce(name, '') <> ''
   group by name
   order by min(o), name;
$$;
comment on function public.indoor_dc_authorisers() is
  'AUTHORISED BY choices for an Indoor DC issued by the signed-in user (0323): their Reporting Manager and Regional Manager on the User Master, and every active profile whose role is NSM.';
revoke all on function public.indoor_dc_authorisers() from public;
do $$ begin
  execute 'revoke all on function public.indoor_dc_authorisers() from anon';
  execute 'grant execute on function public.indoor_dc_authorisers() to authenticated';
exception when undefined_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 3. THE GUARD -- 0320 verbatim, then 0323's rules.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.indoor_jobs_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pdt   public.indoor_pdt%rowtype;
  v_blank text[];
  v_bad   text[];
begin
  -- An administrator is not gated by the stage rights; every other rule below
  -- still applies to them, because the ones that follow are about the RECORD
  -- being coherent rather than about who is allowed to act.
  if not public.is_admin() then
    if tg_op = 'UPDATE' then
      if (new.qc_result is distinct from old.qc_result
       or new.qc_by     is distinct from old.qc_by
       or new.qc_at     is distinct from old.qc_at
       or new.qc_notes  is distinct from old.qc_notes)
         and not public.has_perm('indoor.qc') then
        raise exception 'indoor.qc is required to record a quality check'
          using errcode = '42501';
      end if;

      if (new.dispatched_at is distinct from old.dispatched_at
       or new.dispatch_ref  is distinct from old.dispatch_ref
       or new.dispatched_by is distinct from old.dispatched_by)
         and not public.has_perm('indoor.dispatch')
         -- 0323: a REJECTED Indoor DC releases its units through
         -- reject_indoor_dc(), whose approver need not hold indoor.dispatch.
         -- The exemption is a ticket only that definer function can write.
         and not public.indoor_dc_release_ticketed(new.id) then
        raise exception 'indoor.dispatch is required to dispatch a unit'
          using errcode = '42501';
      end if;

      if new.status in ('Dispatched', 'Closed') and new.status is distinct from old.status
         and not public.has_perm('indoor.dispatch') then
        raise exception 'indoor.dispatch is required to mark a unit %', new.status
          using errcode = '42501';
      end if;
    end if;

    -- CONDEMNING IS ITS OWN RIGHT, on insert as well as update. Scrapping
    -- customer property in particular cannot be an engineer's own decision
    -- (open question 8 in the plan, settled here the safe way: a separate
    -- permission granted to nobody by default).
    if (tg_op = 'INSERT' and (btrim(new.condemned_reason) <> '' or new.status = 'Condemned'))
    or (tg_op = 'UPDATE' and (new.condemned_reason is distinct from old.condemned_reason
                           or new.condemned_at     is distinct from old.condemned_at
                           or (new.status = 'Condemned' and old.status <> 'Condemned'))) then
      if not public.has_perm('indoor.condemn') then
        raise exception 'indoor.condemn is required to condemn a unit'
          using errcode = '42501';
      end if;
      if new.condemned_at is null then new.condemned_at := now(); end if;
      if new.condemned_by is null then new.condemned_by := auth.uid(); end if;
    end if;
  end if;

  -- A MACHINE CANNOT LEAVE WITH A FAILED CHECK. 4.5.6 puts the quality check
  -- before the return, so a failed one sends it back to Under repair rather
  -- than being noted and stepped over.
  if new.status in ('Ready', 'Dispatched', 'Closed') and new.qc_result = 'Fail' then
    raise exception 'the quality check failed -- the unit returns to Under repair, it does not leave'
      using errcode = '23514';
  end if;

  -- AND A REPAIR OR REWORK CANNOT LEAVE WITH NO CHECK AT ALL. The other four
  -- activities are exempt on purpose: a demo going out and a unit stripped for
  -- parts have no repair to verify, and a pre-delivery inspection records its
  -- verdict in pdi_result instead.
  if new.status in ('Dispatched', 'Closed')
     and new.activity in ('Repair', 'Rework')
     and new.qc_result is null then
    raise exception 'a % cannot be dispatched before its quality check is recorded (4.5.6)', lower(new.activity)
      using errcode = '23514';
  end if;

  -- A FAILED PRE-DELIVERY INSPECTION DOES NOT SHIP either, and a held one says
  -- why it is being held.
  if new.status in ('Dispatched', 'Closed')
     and new.activity = 'Pre-delivery inspection' and new.pdi_result = 'Fail' then
    raise exception 'a failed pre-delivery inspection does not leave the workshop'
      using errcode = '23514';
  end if;

  -- Timestamps that follow from an action are stamped, not typed: a cleaning
  -- date somebody can type is a cleaning date somebody can back-date.
  if new.status <> 'Received' and old is distinct from null then
    if new.cleaned_by is distinct from coalesce(old.cleaned_by, new.cleaned_by)
       and new.cleaned_at is null then
      new.cleaned_at := now();
    end if;
  end if;
  if new.qc_result is not null and new.qc_at is null then
    new.qc_at := now();
    if new.qc_by is null then new.qc_by := auth.uid(); end if;
  end if;
  if new.dispatch_ref <> '' and new.dispatched_at is null then
    new.dispatched_at := now();
    if new.dispatched_by is null then new.dispatched_by := auth.uid(); end if;
  end if;

  -- ======================== 0320 ========================================

  -- R/SER/QC/007. A DEMO UNIT OF AN IMPORTED PRODUCT DOES NOT LEAVE UNTESTED.
  -- Asked on the MOVE into Dispatched / Closed (or a job filed or re-kinded
  -- straight into one), not on every later edit: a unit already out before
  -- this rule existed can still be verified and remarked. UNKNOWN imported-ness
  -- does not require the test -- the user's decision; the screen says unknown.
  if new.kind = 'DEMO unit' and new.status in ('Dispatched', 'Closed')
     and (tg_op = 'INSERT' or new.status is distinct from old.status
          or new.kind is distinct from old.kind
          or new.product_name is distinct from old.product_name
          or new.serial is distinct from old.serial)
     and coalesce(public.indoor_job_is_imported(new.product_name, new.serial), false) then
    select * into v_pdt from public.indoor_pdt where job_id = new.id;
    if not found then
      raise exception 'a DEMO unit of an imported product does not leave before its Pre-Delivery Testing (R/SER/QC/007) is recorded'
        using errcode = '23514';
    end if;
    v_bad := array_remove(array[
      case when v_pdt.check1 = 'NOT OK' then '1' end,
      case when v_pdt.check2 = 'NOT OK' then '2' end,
      case when v_pdt.check3 = 'NOT OK' then '3' end,
      case when v_pdt.check4 = 'NOT OK' then '4' end,
      case when v_pdt.check5 = 'NOT OK' then '5' end], null);
    if cardinality(v_bad) > 0 then
      raise exception 'Pre-Delivery Testing check % reads NOT OK -- a machine cannot leave with a failed check',
        array_to_string(v_bad, ', ')
        using errcode = '23514';
    end if;
    v_blank := array_remove(array[
      case when v_pdt.test_date is null then 'Date' end,
      case when btrim(v_pdt.measuring_equipment_id) = '' then 'Measuring Equipment ID No' end,
      case when btrim(v_pdt.software_version) = '' then 'Software Version' end,
      case when btrim(v_pdt.hv) = '' then 'HV' end,
      case when btrim(v_pdt.ht) = '' then 'HT' end,
      case when v_pdt.check1 is null or v_pdt.check2 is null or v_pdt.check3 is null
             or v_pdt.check4 is null or v_pdt.check5 is null then 'checks 1-5' end,
      case when v_pdt.cmv_vte_21 is null or v_pdt.cmv_vte_60 is null or v_pdt.cmv_vte_100 is null
             or v_pdt.cmv_peep_21 is null or v_pdt.cmv_peep_60 is null or v_pdt.cmv_peep_100 is null
             or v_pdt.cmv_o2_21 is null or v_pdt.cmv_o2_60 is null or v_pdt.cmv_o2_100 is null
           then 'the CMV/ACMV readings' end,
      case when v_pdt.pcmv_pip_21 is null or v_pdt.pcmv_pip_60 is null or v_pdt.pcmv_pip_100 is null
             or v_pdt.pcmv_peep_21 is null or v_pdt.pcmv_peep_60 is null or v_pdt.pcmv_peep_100 is null
             or v_pdt.pcmv_o2_21 is null or v_pdt.pcmv_o2_60 is null or v_pdt.pcmv_o2_100 is null
           then 'the PCMV readings' end,
      case when v_pdt.inspected_by is null then 'Inspected by (not signed)' end], null);
    if cardinality(v_blank) > 0 then
      raise exception 'Pre-Delivery Testing (R/SER/QC/007) is incomplete -- still blank: %',
        array_to_string(v_blank, ', ')
        using errcode = '23514';
    end if;
  end if;

  -- R/SER/07 "VERIFIED BY". Its own key; only on a completed row; who and when
  -- from the session. On insert there is nothing to verify yet, so whatever
  -- was sent is discarded.
  if tg_op = 'INSERT' then
    new.verified_by := null;
    new.verified_at := null;
  elsif new.verified_by is distinct from old.verified_by
     or new.verified_at is distinct from old.verified_at then
    if not public.has_perm('indoor.verify') then
      raise exception 'indoor.verify is required to verify an Indoor Service register entry'
        using errcode = '42501';
    end if;
    if new.verified_by is null then
      new.verified_at := null;               -- a verification withdrawn
    else
      if new.status not in ('Dispatched', 'Closed', 'Condemned') then
        raise exception 'a register entry is verified once the unit is Dispatched, Closed or Condemned -- this one is %', new.status
          using errcode = '23514';
      end if;
      new.verified_by := auth.uid();
      new.verified_at := now();
    end if;
  end if;

  -- R/SER/07 "Status" is the COVER, in the one vocabulary (0208), where that
  -- rule is installed. Run-time lookup: data_integrity runs after this module.
  if new.cover is distinct from (case when tg_op = 'UPDATE' then old.cover end)
     and to_regprocedure('public.cover_code(text)') is not null then
    execute 'select public.cover_code($1)' into new.cover using new.cover;
    new.cover := coalesce(new.cover, '');
  end if;


  -- ======================== 0323 ========================================

  -- A UNIT ON AN INDOOR DC THAT IS STILL PENDING APPROVAL DOES NOT LEAVE.
  -- Asked on the move into Dispatched / Closed.
  if new.status in ('Dispatched', 'Closed')
     and (tg_op = 'INSERT' or new.status is distinct from old.status)
     and btrim(coalesce(new.dispatch_ref, '')) <> ''
     and exists (select 1 from public.indoor_dcs d
                  where d.dc_no = btrim(new.dispatch_ref) and d.approval_status = 'Pending approval') then
    raise exception 'Indoor DC % is still pending approval -- the unit is dispatched once it is approved', btrim(new.dispatch_ref)
      using errcode = '23514';
  end if;

  -- STAGE 4 -- THE INDOOR SERVICE REPORT. Uploaded after CLEANING, with its
  -- number; the indoor.work right; who and when from the session.
  if new.report_file_url is distinct from (case when tg_op = 'UPDATE' then old.report_file_url end)
     and btrim(coalesce(new.report_file_url, '')) <> '' then
    if not public.is_admin() and not public.has_perm('indoor.work') then
      raise exception 'indoor.work is required to upload the Indoor Service Report'
        using errcode = '42501';
    end if;
    if new.cleaned_at is null then
      raise exception 'the Indoor Service Report is uploaded after cleaning (WI/SER/01) -- this unit has not been cleaned yet'
        using errcode = '23514';
    end if;
    if btrim(coalesce(new.indoor_report_no, '')) = '' then
      raise exception 'an uploaded Indoor Service Report needs its Indoor Service Report No'
        using errcode = '23514';
    end if;
    new.report_uploaded_by := auth.uid();
    new.report_uploaded_at := now();
  elsif btrim(coalesce(new.report_file_url, '')) = '' then
    new.report_file_url    := '';
    new.report_file_name   := '';
    new.report_uploaded_by := null;
    new.report_uploaded_at := null;
  elsif tg_op = 'UPDATE' then
    new.report_uploaded_by := old.report_uploaded_by;   -- unchanged file: the stamps stand
    new.report_uploaded_at := old.report_uploaded_at;
  end if;

  -- STAGE 5 -- THE VISIT FILED FROM THE DRAFT. visit_uid must be a visit of
  -- THIS job's call; visit_filed_at is stamped, and only once a visit is named.
  if new.visit_uid is distinct from (case when tg_op = 'UPDATE' then old.visit_uid end)
     and new.visit_uid is not null then
    if new.ucn is null or not exists (select 1 from public.reports r
                                       where r.uid = new.visit_uid and r.ucn = new.ucn) then
      raise exception 'visit % is not a visit of call % -- a job records only the visit filed against its own call',
        new.visit_uid, coalesce(new.ucn, '(none)')
        using errcode = '23514';
    end if;
    -- THE USER'S RULE FOR THIS VISIT (2026-10-02): the unit goes back to the
    -- field, so the call is Unsolved, pending "Return to Field", with the work
    -- details updated. A visit saying anything else is not the one this stage
    -- files.
    if not exists (select 1 from public.reports r
                    where r.uid = new.visit_uid
                      and r.call_status = 'Unsolved'
                      and r.pending_reason = 'Return to Field'
                      and r.data ->> 'Update Visit Work Details?' = 'Yes') then
      raise exception 'visit % does not read Unsolved / Return to Field / Update Visit Work Details? = Yes -- the visit filed from Indoor Service always does',
        new.visit_uid
        using errcode = '23514';
    end if;
    if btrim(coalesce(new.report_file_url, '')) = '' then
      raise exception 'the visit is filed from the Indoor Service Report stage -- upload the report first'
        using errcode = '23514';
    end if;
  end if;
  if new.visit_uid is null then
    new.visit_filed_at := null;
  elsif new.visit_filed_at is distinct from (case when tg_op = 'UPDATE' then old.visit_filed_at end) then
    new.visit_filed_at := case when new.visit_filed_at is null then null else now() end;
  end if;

  return new;
end $function$;
drop trigger if exists zz_indoor_jobs_guard on public.indoor_jobs;
create trigger zz_indoor_jobs_guard before insert or update on public.indoor_jobs
  for each row execute function public.indoor_jobs_guard();

-- ---------------------------------------------------------------------------
-- 4. ISSUING A DC -- 0321's create_indoor_dc() with 0323's changes:
--      * NO DC DATE PARAMETER: the DC date is the date of entry (today, India);
--      * every job must carry its uploaded Indoor Service Report;
--      * AUTHORISED BY, one of indoor_dc_authorisers(), REQUIRED: the DC is
--        created PENDING APPROVAL and that person approves it (section 5);
--      * an accessory line's QTY is the quantity received.
--    The old signature is DROPPED (a call with p_dc_date would otherwise still
--    reach the 0321 version and skip every new rule).
-- ---------------------------------------------------------------------------
drop function if exists public.create_indoor_dc(bigint[], text, date, text, date, text, text, jsonb);

create or replace function public.create_indoor_dc(
  p_job_ids           bigint[],
  p_consignee         text,
  p_customer_ref      text    default '',
  p_customer_ref_date date    default null,
  p_mode              text    default '',
  p_purpose           text    default '',
  p_line_purposes     jsonb   default '[]'::jsonb,
  p_authorised_by     text    default ''
) returns text
language plpgsql volatile security definer
set search_path = public
as $$
declare
  v_ids   bigint[];
  v_date  date := (now() at time zone 'Asia/Kolkata')::date;
  v_dc    bigint;
  v_no    text;
  v_line  integer := 0;
  v_state text;
  v_msg   text;
  v_keys  text;
  v_auth  text;
  j       record;
  a       record;
  v_ov    jsonb;
begin
  if not public.has_perm('indoor.dispatch') then
    raise exception 'indoor.dispatch is required to issue an Indoor DC'
      using errcode = '42501';
  end if;

  select array_agg(x order by o) into v_ids
    from (select x, min(o) as o from unnest(p_job_ids) with ordinality u(x, o)
           where x is not null group by x) d;
  if coalesce(cardinality(v_ids), 0) = 0 then
    raise exception 'choose at least one Ready unit for the Indoor DC'
      using errcode = '22023';
  end if;
  if coalesce(btrim(p_consignee), '') = '' then
    raise exception 'an Indoor DC needs its consignee (To)'
      using errcode = '23514';
  end if;

  -- AUTHORISED BY: one of the issuer's choices, matched without regard to case
  -- and stored as the list spells it. REQUIRED -- it names who approves.
  if coalesce(btrim(p_authorised_by), '') = '' then
    raise exception 'choose who AUTHORISES this Indoor DC (your Reporting Manager, Regional Manager or an NSM) -- they approve it'
      using errcode = '23514';
  end if;
  select au.name into v_auth from public.indoor_dc_authorisers() au
   where upper(btrim(au.name)) = upper(btrim(p_authorised_by))
   limit 1;
  if v_auth is null then
    raise exception 'AUTHORISED BY must be your Reporting Manager, your Regional Manager or an NSM -- % is none of them', btrim(p_authorised_by)
      using errcode = '23514';
  end if;

  -- Every job must exist, and is locked for the rest of the transaction so two
  -- people cannot put one unit on two challans at once.
  perform 1 from public.indoor_jobs where id = any (v_ids) order by id for update;
  if (select count(*) from public.indoor_jobs where id = any (v_ids)) <> cardinality(v_ids) then
    raise exception 'an Indoor Service job on this DC was not found'
      using errcode = '23503';
  end if;

  -- ONE DC, ONE CONSIGNEE: a customer unit goes to its party, a DEMO unit to
  -- its "going to" party.
  select string_agg(distinct coalesce(nullif(btrim(k), ''), '(none)'), ' / ') into v_keys
    from (select case when kind = 'DEMO unit' then demo_for_party else party_name end as k
            from public.indoor_jobs where id = any (v_ids)) s;
  if (select count(distinct upper(btrim(coalesce(case when kind = 'DEMO unit' then demo_for_party
                                                       else party_name end, ''))))
        from public.indoor_jobs where id = any (v_ids)) > 1 then
    raise exception 'one Indoor DC goes to one consignee -- these units go to %', v_keys
      using errcode = '23514';
  end if;

  for j in
    select ij.*, u.o from public.indoor_jobs ij
      join unnest(v_ids) with ordinality u(x, o) on u.x = ij.id
     order by u.o
  loop
    if j.status <> 'Ready' then
      raise exception '%: only a Ready unit goes on an Indoor DC -- this one is %', j.job_no, j.status
        using errcode = '23514';
    end if;
    if btrim(j.dispatch_ref) <> '' then
      raise exception '%: already carries DC No. % -- one unit, one DC', j.job_no, j.dispatch_ref
        using errcode = '23514';
    end if;
    -- 0323: THE REPORT BEFORE THE DC, AND THE VISIT WITH IT.
    if btrim(coalesce(j.report_file_url, '')) = '' then
      raise exception '%: the Indoor Service Report has not been uploaded -- a unit goes on an Indoor DC after its report', j.job_no
        using errcode = '23514';
    end if;

    -- THE TRIAL. Would the guard let this unit leave? Asked by moving it to
    -- Dispatched and always rolling the move back.
    begin
      update public.indoor_jobs set status = 'Dispatched' where id = j.id;
      raise exception using errcode = 'P0001', message = 'indoor_dc_trial_passed';
    exception when others then
      get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text;
      if v_msg <> 'indoor_dc_trial_passed' then
        raise exception '%: %', j.job_no, v_msg using errcode = v_state;
      end if;
    end;
  end loop;

  -- Overrides must name a job on this DC (a purpose for a unit that is not
  -- here is a mistake, said rather than dropped).
  for v_ov in select * from jsonb_array_elements(coalesce(p_line_purposes, '[]'::jsonb)) loop
    if not coalesce((v_ov ->> 'job_id')::bigint = any (v_ids), false) then
      raise exception 'a line purpose names job %, which is not on this DC', v_ov ->> 'job_id'
        using errcode = '22023';
    end if;
  end loop;

  insert into public.indoor_dcs (dc_no, dc_date, consignee, customer_ref, customer_ref_date,
                                 mode_of_despatch, purpose, authorised_by_name, approval_status)
  values ('auto', v_date, btrim(p_consignee), btrim(coalesce(p_customer_ref, '')), p_customer_ref_date,
          btrim(coalesce(p_mode, '')), btrim(coalesce(p_purpose, '')), v_auth, 'Pending approval')
  returning id, dc_no into v_dc, v_no;

  for j in
    select ij.*, u.o from public.indoor_jobs ij
      join unnest(v_ids) with ordinality u(x, o) on u.x = ij.id
     order by u.o
  loop
    v_line := v_line + 1;
    insert into public.indoor_dc_lines (dc_id, line_no, job_id, accessory_id, part_no, description, qty, purpose)
    values (v_dc, v_line, j.id, null,
            coalesce(public.indoor_job_product_code(j.product_name, j.serial), ''),
            btrim(btrim(j.product_name) || case when btrim(j.serial) <> '' then ' Sl.No ' || btrim(j.serial) else '' end),
            1,
            coalesce((select e ->> 'purpose' from jsonb_array_elements(coalesce(p_line_purposes, '[]'::jsonb)) e
                       where (e ->> 'job_id')::bigint = j.id
                         and nullif(e ->> 'accessory_id', '') is null
                       limit 1), btrim(coalesce(p_purpose, ''))));
    for a in
      select * from public.indoor_job_accessories
       where job_id = j.id and (btrim(name) <> '' or btrim(serial) <> '')
       order by id
    loop
      v_line := v_line + 1;
      insert into public.indoor_dc_lines (dc_id, line_no, job_id, accessory_id, part_no, description, qty, purpose)
      values (v_dc, v_line, j.id, a.id, '',
              btrim(btrim(a.name) || case when btrim(a.serial) <> '' then ' Sl.No ' || btrim(a.serial) else '' end),
              a.qty,
              coalesce((select e ->> 'purpose' from jsonb_array_elements(coalesce(p_line_purposes, '[]'::jsonb)) e
                         where (e ->> 'job_id')::bigint = j.id
                           and (e ->> 'accessory_id')::bigint = a.id
                         limit 1), btrim(coalesce(p_purpose, ''))));
    end loop;
  end loop;

  -- THE STAMP ON EACH JOB. Through the guard, as the caller: it asks
  -- indoor.dispatch for a change of dispatch_ref and stamps dispatched_at /
  -- dispatched_by, exactly as a reference typed on the job does.
  update public.indoor_jobs
     set dispatch_ref = v_no, dc_date = v_date
   where id = any (v_ids);

  return v_no;
end $$;
comment on function public.create_indoor_dc(bigint[], text, text, date, text, text, jsonb, text) is
  'Issues an Indoor DC PENDING APPROVAL (0321, 0323): asks indoor.dispatch; one consignee; only Ready units with no DC No. and an uploaded Indoor Service Report; AUTHORISED BY required, one of indoor_dc_authorisers(); DC date = today (India); each unit TRIED against indoor_jobs_guard()''s leaving rules; lines from the jobs and their accessories with the quantities received; each job stamped dispatch_ref and dc_date (its reservation). Returns the IDC number.';
revoke all on function public.create_indoor_dc(bigint[], text, text, date, text, text, jsonb, text) from public;
do $$ begin
  execute 'revoke all on function public.create_indoor_dc(bigint[], text, text, date, text, text, jsonb, text) from anon';
  execute 'grant execute on function public.create_indoor_dc(bigint[], text, text, date, text, text, jsonb, text) to authenticated';
exception when undefined_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 5. THE APPROVAL -- the Indoor DC's own, and only the Indoor DC's (the user:
--    "Only the INDOOR DC needs an approval"; the spare DC is untouched).
--
--    WHO: the person named as AUTHORISED BY, recognised by the name the User
--    Master gives their login (my_dir_name()) or, failing that, their profile
--    name -- or an administrator. Anybody else is refused.
--
--    APPROVE: every job on the DC that has a UCN must have its drafted visit
--    FILED first (the screen files it, through the Visit Entry's own save
--    path, as the approver, and records it with record_indoor_visit()); then
--    approved_by / approved_at / approved_by_name are stamped from the
--    session. p_check_only asks who and what state, and nothing else, so the
--    screen is refused BEFORE it files any visit.
--
--    REJECT: a reason, then the units are RELEASED -- DC No., DC date and the
--    dispatch stamps cleared through the guard on a release ticket -- so a new
--    DC can be made. The DC is kept, never deleted.
-- ---------------------------------------------------------------------------
create or replace function public.indoor_dc_may_approve(p_authorised_by text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_admin()
      or (coalesce(btrim(p_authorised_by), '') <> ''
          and upper(btrim(p_authorised_by)) in (
                upper(btrim(coalesce(public.my_dir_name(), ''))),
                upper(btrim(coalesce((select p.full_name from public.profiles p where p.id = auth.uid()), '')))));
$$;
comment on function public.indoor_dc_may_approve(text) is
  'May the signed-in user approve or reject an Indoor DC whose AUTHORISED BY reads p_authorised_by? Their User Master name or profile name matches it, or they are an administrator (0323).';
revoke all on function public.indoor_dc_may_approve(text) from public;
do $$ begin
  execute 'revoke all on function public.indoor_dc_may_approve(text) from anon';
  execute 'grant execute on function public.indoor_dc_may_approve(text) to authenticated';
exception when undefined_object then null; end $$;

-- Recording the visit filed for a job at approval. The approver need hold no
-- indoor right, so this is the one writer of visit_uid / visit_filed_at for
-- them; the guard still checks the visit is this call's and reads Unsolved /
-- Return to Field / Yes.
create or replace function public.record_indoor_visit(p_job_id bigint, p_visit_uid text, p_complete boolean default false)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  v_dc public.indoor_dcs%rowtype;
begin
  select d.* into v_dc from public.indoor_dcs d
    join public.indoor_jobs j on btrim(j.dispatch_ref) = d.dc_no
   where j.id = p_job_id and d.approval_status = 'Pending approval'
   limit 1;
  if not found then
    raise exception 'job % is not on an Indoor DC awaiting approval -- its visit is filed when that DC is approved', p_job_id
      using errcode = '23514';
  end if;
  if not public.indoor_dc_may_approve(v_dc.authorised_by_name) then
    raise exception 'only % (AUTHORISED BY on %) or an administrator files the visits of that DC', v_dc.authorised_by_name, v_dc.dc_no
      using errcode = '42501';
  end if;
  update public.indoor_jobs
     set visit_uid = nullif(btrim(coalesce(p_visit_uid, '')), ''),
         visit_filed_at = case when p_complete then now() else null end
   where id = p_job_id;
end $$;
revoke all on function public.record_indoor_visit(bigint, text, boolean) from public;
do $$ begin
  execute 'revoke all on function public.record_indoor_visit(bigint, text, boolean) from anon';
  execute 'grant execute on function public.record_indoor_visit(bigint, text, boolean) to authenticated';
exception when undefined_object then null; end $$;

create or replace function public.approve_indoor_dc(p_dc_no text, p_check_only boolean default false)
returns text language plpgsql volatile security definer set search_path = public as $$
declare
  v_dc   public.indoor_dcs%rowtype;
  v_todo text;
begin
  select * into v_dc from public.indoor_dcs where dc_no = btrim(p_dc_no) for update;
  if not found then
    raise exception 'Indoor DC % was not found', p_dc_no using errcode = '23503';
  end if;
  if not public.indoor_dc_may_approve(v_dc.authorised_by_name) then
    raise exception 'only % (AUTHORISED BY) or an administrator approves Indoor DC %', coalesce(nullif(v_dc.authorised_by_name, ''), '(nobody named)'), v_dc.dc_no
      using errcode = '42501';
  end if;
  if v_dc.approval_status <> 'Pending approval' then
    raise exception 'Indoor DC % is %, not pending approval', v_dc.dc_no, v_dc.approval_status
      using errcode = '23514';
  end if;
  if p_check_only then return 'OK'; end if;

  select string_agg(j.job_no || ' (' || j.ucn || ')', ', ' order by j.id) into v_todo
    from public.indoor_jobs j
   where btrim(j.dispatch_ref) = v_dc.dc_no
     and coalesce(btrim(j.ucn), '') <> '' and j.visit_filed_at is null;
  if v_todo is not null then
    raise exception 'Indoor DC % is not approved: the visit is not yet filed for %', v_dc.dc_no, v_todo
      using errcode = '23514';
  end if;

  update public.indoor_dcs
     set approval_status  = 'Approved',
         approved_by      = auth.uid(),
         approved_at      = now(),
         approved_by_name = coalesce((select coalesce(nullif(btrim(p.full_name), ''), p.email)
                                        from public.profiles p where p.id = auth.uid()), '')
   where id = v_dc.id;
  return v_dc.dc_no;
end $$;
comment on function public.approve_indoor_dc(text, boolean) is
  'Approves an Indoor DC (0323): the AUTHORISED BY person or an administrator; pending only; every job with a UCN must have its visit filed (visit_filed_at); stamps approved_by / approved_at / approved_by_name from the session. p_check_only asks who and state only.';
revoke all on function public.approve_indoor_dc(text, boolean) from public;
do $$ begin
  execute 'revoke all on function public.approve_indoor_dc(text, boolean) from anon';
  execute 'grant execute on function public.approve_indoor_dc(text, boolean) to authenticated';
exception when undefined_object then null; end $$;

create or replace function public.reject_indoor_dc(p_dc_no text, p_reason text)
returns text language plpgsql volatile security definer set search_path = public as $$
declare
  v_dc public.indoor_dcs%rowtype;
begin
  select * into v_dc from public.indoor_dcs where dc_no = btrim(p_dc_no) for update;
  if not found then
    raise exception 'Indoor DC % was not found', p_dc_no using errcode = '23503';
  end if;
  if not public.indoor_dc_may_approve(v_dc.authorised_by_name) then
    raise exception 'only % (AUTHORISED BY) or an administrator rejects Indoor DC %', coalesce(nullif(v_dc.authorised_by_name, ''), '(nobody named)'), v_dc.dc_no
      using errcode = '42501';
  end if;
  if v_dc.approval_status <> 'Pending approval' then
    raise exception 'Indoor DC % is %, not pending approval', v_dc.dc_no, v_dc.approval_status
      using errcode = '23514';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'say why Indoor DC % is rejected', v_dc.dc_no using errcode = '23514';
  end if;

  update public.indoor_dcs
     set approval_status = 'Rejected', rejected_by = auth.uid(), rejected_at = now(),
         rejection_reason = btrim(p_reason)
   where id = v_dc.id;

  -- RELEASE THE UNITS, through the guard, on a ticket for this transaction.
  insert into public.indoor_dc_release_tickets (job_id, tx)
  select j.id, txid_current() from public.indoor_jobs j where btrim(j.dispatch_ref) = v_dc.dc_no
  on conflict do nothing;
  update public.indoor_jobs
     set dispatch_ref = '', dc_date = null, dispatched_at = null, dispatched_by = null
   where btrim(dispatch_ref) = v_dc.dc_no;
  delete from public.indoor_dc_release_tickets where tx = txid_current();
  return v_dc.dc_no;
end $$;
comment on function public.reject_indoor_dc(text, text) is
  'Rejects an Indoor DC (0323): the AUTHORISED BY person or an administrator; pending only; a reason; the DC is kept and its units RELEASED (DC No., DC date and dispatch stamps cleared) so a new DC can be made.';
revoke all on function public.reject_indoor_dc(text, text) from public;
do $$ begin
  execute 'revoke all on function public.reject_indoor_dc(text, text) from anon';
  execute 'grant execute on function public.reject_indoor_dc(text, text) to authenticated';
exception when undefined_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 6. "RETURN TO FIELD" -- the Pending Reason every visit filed from Indoor
--    Service carries (the user, 2026-10-02). Added to the Call Pending Reason
--    master (`pendingreason`, 0021) where it is not there exactly, and made
--    active where it is. Written without the columns later modules add
--    (active: 0066, added_on/by: 0021 -- both in `masters`, which runs AFTER
--    this module on a fresh build), and the active flag set only where it
--    exists.
-- ---------------------------------------------------------------------------
insert into public.masters (name, value)
select 'pendingreason', 'Return to Field'
 where not exists (select 1 from public.masters where name = 'pendingreason' and value = 'Return to Field');
do $$
begin
  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'masters' and column_name = 'active') then
    execute $q$update public.masters set active = true
                where name = 'pendingreason' and value = 'Return to Field' and active is not true$q$;
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- 7. THE LISTS -- indoor_job_list rebuilt so `j.*` carries 0323's columns, and
--    the accessories written with their quantity where it is not 1. MIRRORED
--    WORD FOR WORD in 0245 (check:bundles). indoor_dc_list gains the approval
--    (appended), and whether the reader may decide it.
-- ---------------------------------------------------------------------------
drop view if exists public.indoor_job_list;
create view public.indoor_job_list as
  select j.*,
         coalesce(rb.name, '') as received_by_name,
         coalesce(cb.name, '') as cleaned_by_name,
         coalesce(qb.name, '') as qc_by_name,
         coalesce(db.name, '') as dispatched_by_name,
         coalesce(xb.name, '') as condemned_by_name,
         coalesce(ub.name, '') as updated_by_name,
         (j.status in ('Closed', 'Dispatched', 'Condemned')) as is_closed,
         -- A DEMO unit out past its due date, which is the one figure nothing
         -- else in this system produces. NULL rather than false where there is
         -- no due date: "not overdue" and "nobody said when" are different facts.
         (case when j.activity = 'Demo' and j.actual_return is null
                    and j.expected_return is not null
               then (j.expected_return < (now() at time zone 'Asia/Kolkata')::date)
          end) as demo_overdue,
         (select count(*) from public.indoor_job_accessories a where a.job_id = j.id)
           as accessory_count,
         (select count(*) from public.indoor_job_accessories a
           where a.job_id = j.id and not a.returned) as accessories_outstanding,
         coalesce(vb.name, '') as verified_by_name,
         (select string_agg(btrim(a.name) || case when a.qty <> 1 then ' x' || trim_scale(a.qty)::text else '' end,
                            ', ' order by a.id) from public.indoor_job_accessories a
           where a.job_id = j.id and btrim(a.name) <> '') as accessories_received,
         public.indoor_job_is_imported(j.product_name, j.serial) as product_imported,
         coalesce(rpb.name, '') as report_uploaded_by_name
    from public.indoor_jobs j
    left join public.app_user_names rb on rb.id = j.received_by
    left join public.app_user_names cb on cb.id = j.cleaned_by
    left join public.app_user_names qb on qb.id = j.qc_by
    left join public.app_user_names db on db.id = j.dispatched_by
    left join public.app_user_names xb on xb.id = j.condemned_by
    left join public.app_user_names ub on ub.id = j.updated_by
    left join public.app_user_names vb on vb.id = j.verified_by
    left join public.app_user_names rpb on rpb.id = j.report_uploaded_by;
alter view public.indoor_job_list set (security_invoker = on);
grant select on public.indoor_job_list to authenticated;

create or replace view public.indoor_dc_list as
  select d.id, d.dc_no, d.dc_date, d.consignee, d.customer_ref, d.customer_ref_date,
         d.mode_of_despatch, d.purpose, d.issued_by_name, d.created_by, d.created_at,
         (select count(*) from public.indoor_dc_lines l where l.dc_id = d.id) as line_count,
         (select string_agg(j.job_no, ', ' order by l.line_no)
            from public.indoor_dc_lines l join public.indoor_jobs j on j.id = l.job_id
           where l.dc_id = d.id and l.accessory_id is null) as job_nos,
         d.authorised_by_name, d.approval_status, d.approved_by_name, d.approved_at,
         d.rejected_at, d.rejection_reason,
         public.indoor_dc_may_approve(d.authorised_by_name) as i_may_approve
    from public.indoor_dcs d;
alter view public.indoor_dc_list set (security_invoker = on);
grant select on public.indoor_dc_list to authenticated;

-- ------------------------------------------------------------------------
-- 0324_indoor_delete_job.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0324 — DELETING AN INDOOR SERVICE JOB, PERMANENTLY, BEFORE IT HAS LEFT A
--        TRACE ANYWHERE ELSE
--
-- The user, 2026-10-03: a job received in error (the wrong unit, a duplicate
-- intake, a test entry) should be removable, and they chose PERMANENT deletion
-- over keep-and-hide. "Allow Admin by default, rest I will update from Roles &
-- Permissions": the key is `indoor.delete`, an administrator passes has_perm()
-- anyway, and THIS MIGRATION GRANTS IT TO NO OTHER ROLE.
--
-- WHAT IS NEVER DELETED, whoever asks:
--   * a job that went on an Indoor DC -- it carries a DC No. (dispatch_ref) or
--     a line of any Indoor DC names it, approved, pending or rejected. A DC is
--     a record of a unit leaving and is kept for ever (0321, no_hard_delete);
--     its lines reference the job.
--   * a job whose visit has been FILED against its call (visit_uid): the call's
--     visit history names that work, and deleting the job would leave a visit
--     pointing at nothing.
-- A drafted visit (visit_draft) lives on the job and goes with it.
--
-- HOW: delete_indoor_job() is SECURITY DEFINER and is the ONLY way. indoor_jobs
-- and indoor_pdt have no DELETE policy (0158, 0320), and this migration also
-- revokes the DELETE privilege on both from the API roles, so a direct DELETE
-- is refused outright rather than matching zero rows. The function deletes the
-- children it names (accessories, harvested parts, checks, PDT) and then the
-- job; indoor_job_counters is not touched, so a deleted job's number is never
-- issued again. No record-retention trigger sits on these tables (0049 covers
-- calls, visits and spares), so nothing has to be lifted: there is no ticket
-- and no general hole.
--
-- THE TRAIL: an audit_log row `indoor.job_delete` written by the function
-- itself, naming the job no., product, serial, UCN, kind, status, the reason and
-- what went with it; who and when are stamped by audit_before_insert() from the
-- session.
-- ===========================================================================

create or replace function public.delete_indoor_job(p_job_id bigint, p_reason text)
returns text
language plpgsql volatile security definer
set search_path = public
as $$
declare
  j        public.indoor_jobs%rowtype;
  v_dcs    text;
  v_acc    integer;
  v_parts  integer;
  v_checks integer;
  v_pdt    integer;
  v_actor  text;
  v_role   text;
begin
  if not public.has_perm('indoor.delete') then
    raise exception 'indoor.delete is required to delete an Indoor Service job'
      using errcode = '42501';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'say why the Indoor Service job is being deleted'
      using errcode = '23514';
  end if;

  select * into j from public.indoor_jobs where id = p_job_id for update;
  if not found then
    raise exception 'Indoor Service job % was not found', p_job_id
      using errcode = '23503';
  end if;

  if btrim(coalesce(j.dispatch_ref, '')) <> '' then
    raise exception '% carries DC No. % -- a job that went on a delivery challan is a record of the unit leaving and is not deleted',
      j.job_no, btrim(j.dispatch_ref)
      using errcode = '23514';
  end if;
  select string_agg(distinct d.dc_no || ' (' || d.approval_status || ')', ', ') into v_dcs
    from public.indoor_dc_lines l join public.indoor_dcs d on d.id = l.dc_id
   where l.job_id = j.id;
  if v_dcs is not null then
    raise exception '% is on Indoor DC % -- the challan keeps its lines, so the job is not deleted',
      j.job_no, v_dcs
      using errcode = '23514';
  end if;
  if j.visit_uid is not null then
    raise exception '% has visit % filed against call % -- the call''s visit history names this job, so it is not deleted',
      j.job_no, j.visit_uid, coalesce(j.ucn, '(none)')
      using errcode = '23514';
  end if;

  delete from public.indoor_job_accessories where job_id = j.id;
  get diagnostics v_acc = row_count;
  delete from public.indoor_job_parts where job_id = j.id;
  get diagnostics v_parts = row_count;
  delete from public.indoor_job_checks where job_id = j.id;
  get diagnostics v_checks = row_count;
  delete from public.indoor_pdt where job_id = j.id;
  get diagnostics v_pdt = row_count;
  delete from public.indoor_jobs where id = j.id;

  select coalesce(nullif(btrim(p.full_name), ''), p.email, ''), coalesce(p.role, '')
    into v_actor, v_role
    from public.profiles p where p.id = auth.uid();

  insert into public.audit_log (actor, role, action, target, status, meta)
  values (coalesce(v_actor, ''), coalesce(v_role, ''), 'indoor.job_delete', j.job_no, 'ok',
          jsonb_build_object(
            'job_no', j.job_no, 'product', j.product_name, 'serial', j.serial,
            'ucn', coalesce(j.ucn, ''), 'kind', j.kind, 'activity', j.activity, 'status', j.status,
            'party', coalesce(j.party_name, ''), 'received_at', j.received_at,
            'indoor_report_no', coalesce(j.indoor_report_no, ''),
            'had_visit_draft', j.visit_draft is not null,
            'reason', btrim(p_reason),
            'deleted', jsonb_build_object('accessories', v_acc, 'parts', v_parts, 'checks', v_checks, 'pdt', v_pdt)));

  return j.job_no;
end $$;
comment on function public.delete_indoor_job(bigint, text) is
  'Deletes an Indoor Service job PERMANENTLY with its accessories, harvested parts, checks and PDT (0324): asks indoor.delete (granted to no role by migration; an administrator passes); needs a reason; refused for a job carrying a DC No., named on any Indoor DC line, or whose visit has been filed. Writes audit_log indoor.job_delete. The job counter is untouched, so the number is not reissued.';
revoke all on function public.delete_indoor_job(bigint, text) from public;
do $$ begin
  execute 'revoke all on function public.delete_indoor_job(bigint, text) from anon';
  execute 'grant execute on function public.delete_indoor_job(bigint, text) to authenticated';
exception when undefined_object then null; end $$;

-- A DIRECT DELETE IS REFUSED OUTRIGHT. There is no DELETE policy on either
-- table, so a project's default grants would let a DELETE through to RLS and
-- match zero rows -- "nothing happened" rather than "you may not". Revoked, it
-- says so. The function above runs as the owner and is unaffected.
do $$ begin
  execute 'revoke delete on public.indoor_jobs, public.indoor_pdt from anon, authenticated';
exception when undefined_object then null; end $$;

-- ------------------------------------------------------------------------
-- 0327_indoor_dc_approver_from_user_master.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0327 — THE INDOOR DC IS APPROVED BY WHOEVER THE USER MASTER NAMES, AND THE
-- APPROVAL FILES THE VISIT ITSELF (D-109, D-110, D-108).
--
-- The user, 2026-10-03: "AJAY G (INDOOR) is mapped to VIGNESH and Bagyaraj..
-- but this is not a Hardcodes concept.. it is dynamic based on the user
-- master. So when I say RM / RGM / NSM - it should map as per the user
-- Master". Asked how the NSM is found, as the User Master has no NSM column:
-- "Regional Manager's own manager". Asked whether the person named may see
-- and approve the DC whatever their role holds: "Yes, the mapping decides".
--
-- 1. WHO MAY AUTHORISE (indoor_dc_authorisers). From the ISSUER's User Master
--    row:
--      Reporting Manager  its reporting_manager
--      Regional Manager   its regional_manager
--      NSM                the reporting_manager on the REGIONAL MANAGER's own
--                         User Master row
--    0323 offered every login whose ROLE was nsm, the issuer included, so an
--    NSM could name and approve their own DC (D-110). The issuer is never
--    offered now, whatever the User Master says. A blank name is never a
--    manager (0212's rule): a blank column offers nobody.
--    create_indoor_dc() already refuses an AUTHORISED BY this list does not
--    hold, so the rule reaches the DC without touching that function.
--
-- 2. THE PERSON NAMED SEES WHAT THEY APPROVE. The three read policies asked
--    mod:/indoor alone, which the seeded rm and rgm roles do not hold (D-109):
--    the person the User Master named could not see the DC that named them.
--    Each now also admits the DC's AUTHORISED BY -- the DC, its lines, and the
--    units on it -- and nothing else of Indoor Service.
--
-- 3. APPROVING FILES THE VISIT, IN THE DATABASE. 0323 left the filing to the
--    approver's browser, through the Visit Entry's save path, so it passed
--    only for an approver whose ROLE could file a visit on that call -- an NSM
--    holds no call-report key. approve_indoor_dc() now files, for every unit on
--    the DC with a UCN and no visit filed, exactly what that path files: one
--    visit row (Unsolved / Return to Field / work details Yes, the uploaded
--    Indoor Service Report as the manual report, its number as Manual Report
--    No.) and the drafted spares as consumption, then stamps the unit -- in the
--    SAME transaction as the approval, so a refusal anywhere (the visit-date
--    rule, the hand-stock cap) leaves the DC pending with nothing filed. The
--    visit's own guards still run: this writes as its owner, but every trigger
--    on reports and spare_consumption fires as it does for the screen.
--
-- 4. ONLY THE APPROVAL MARKS A VISIT FILED (D-108). visit_uid and
--    visit_filed_at could be written by the unit's engineer, pointing at an
--    older visit, and the approval then filed nothing. A trigger now refuses a
--    signed-in change to either unless it comes from approve_indoor_dc() or
--    record_indoor_visit() (a transaction-local ticket).
-- ===========================================================================

-- ---- 1. who may authorise ---------------------------------------------------
create or replace function public.indoor_dc_authorisers()
returns table(name text, basis text)
language sql stable security definer set search_path = public as $$
  with me as (
    select lower(btrim(coalesce(p.email, auth.email(), ''))) as em,
           upper(btrim(coalesce(p.full_name, '')))            as full_name
      from (select 1) x left join public.profiles p on p.id = auth.uid()
  ), dir as (
    select d.name, d.reporting_manager, d.regional_manager
      from public.user_directory d, me
     where me.em <> '' and (lower(btrim(coalesce(d.email, ''))) = me.em or lower(btrim(coalesce(d.gmail, ''))) = me.em)
     order by d.validity desc, d.id
     limit 1
  ), rgm_row as (
    -- The REGIONAL MANAGER's own User Master row, by name; its Reporting
    -- Manager is the NSM. A blank Regional Manager finds no row.
    select r.reporting_manager
      from public.user_directory r, dir
     where btrim(coalesce(dir.regional_manager, '')) <> ''
       and upper(btrim(coalesce(r.name, ''))) = upper(btrim(dir.regional_manager))
     order by r.validity desc, r.id
     limit 1
  ), cand as (
    select btrim(coalesce(reporting_manager, '')) as name, 'Reporting Manager'::text as basis, 1 as o from dir
    union all
    select btrim(coalesce(regional_manager, '')), 'Regional Manager', 2 from dir
    union all
    select btrim(coalesce(reporting_manager, '')), 'NSM', 3 from rgm_row
  )
  select c.name, string_agg(c.basis, ' / ' order by c.o) as basis
    from cand c, me
   where c.name <> ''
     -- NEVER THE ISSUER (D-110), by their User Master name or their login's.
     and upper(c.name) <> upper(btrim(coalesce((select d.name from dir d), '')))
     and upper(c.name) <> me.full_name
   group by c.name
   order by min(c.o), c.name;
$$;

-- ---- 2. the person named sees what they approve ----------------------------
-- Asked inside a policy, so they run as the caller and must be executable by
-- a signed-in user; they answer only "is this DC / this unit's DC mine to
-- approve", through indoor_dc_may_approve() (0323).
create or replace function public.indoor_dc_names_me(p_dc_id bigint)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.indoor_dcs d
                  where d.id = p_dc_id and public.indoor_dc_may_approve(d.authorised_by_name));
$$;
create or replace function public.indoor_job_on_my_dc(p_dispatch_ref text)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(btrim(p_dispatch_ref), '') <> ''
     and exists (select 1 from public.indoor_dcs d
                  where d.dc_no = btrim(p_dispatch_ref) and public.indoor_dc_may_approve(d.authorised_by_name));
$$;
revoke execute on function public.indoor_dc_names_me(bigint) from public, anon;
revoke execute on function public.indoor_job_on_my_dc(text) from public, anon;
grant execute on function public.indoor_dc_names_me(bigint) to authenticated;
grant execute on function public.indoor_job_on_my_dc(text) to authenticated;

drop policy if exists indoor_dcs_read on public.indoor_dcs;
create policy indoor_dcs_read on public.indoor_dcs for select
  using ((select public.has_perm('mod:/indoor')) or public.indoor_dc_may_approve(authorised_by_name));

drop policy if exists indoor_dc_lines_read on public.indoor_dc_lines;
create policy indoor_dc_lines_read on public.indoor_dc_lines for select
  using ((select public.has_perm('mod:/indoor')) or public.indoor_dc_names_me(dc_id));

drop policy if exists indoor_read on public.indoor_jobs;
create policy indoor_read on public.indoor_jobs for select
  using ((select public.has_perm('mod:/indoor')) or public.indoor_job_on_my_dc(dispatch_ref));

-- ---- 4. only the approval marks a visit filed (D-108) ----------------------
create or replace function public.indoor_job_visit_by_approval()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if (new.visit_uid is distinct from old.visit_uid or new.visit_filed_at is distinct from old.visit_filed_at)
     and auth.uid() is not null
     and coalesce(current_setting('rithi.indoor_visit', true), '') <> 'on' then
    raise exception 'the visit on job % is recorded by the Indoor DC''s approval, not by an edit', old.job_no
      using errcode = '42501';
  end if;
  return new;
end $$;
revoke execute on function public.indoor_job_visit_by_approval() from public, anon, authenticated;
drop trigger if exists indoor_job_visit_by_approval on public.indoor_jobs;
create trigger indoor_job_visit_by_approval
  before update on public.indoor_jobs
  for each row execute function public.indoor_job_visit_by_approval();

-- record_indoor_visit (0323), unchanged but for the ticket.
create or replace function public.record_indoor_visit(p_job_id bigint, p_visit_uid text, p_complete boolean default false)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_dc public.indoor_dcs%rowtype;
begin
  select d.* into v_dc from public.indoor_dcs d
    join public.indoor_jobs j on btrim(j.dispatch_ref) = d.dc_no
   where j.id = p_job_id and d.approval_status = 'Pending approval'
   limit 1;
  if not found then
    raise exception 'job % is not on an Indoor DC awaiting approval -- its visit is filed when that DC is approved', p_job_id
      using errcode = '23514';
  end if;
  if not public.indoor_dc_may_approve(v_dc.authorised_by_name) then
    raise exception 'only % (AUTHORISED BY on %) or an administrator files the visits of that DC', v_dc.authorised_by_name, v_dc.dc_no
      using errcode = '42501';
  end if;
  perform set_config('rithi.indoor_visit', 'on', true);
  update public.indoor_jobs
     set visit_uid = nullif(btrim(coalesce(p_visit_uid, '')), ''),
         visit_filed_at = case when p_complete then now() else null end
   where id = p_job_id;
end $$;

-- ---- 3. approving files the visit, in the database -------------------------
-- 0323's approve_indoor_dc, read from the database, with the filing added
-- between the checks and the approval, and the issuer refused (D-110) for a
-- DC raised before this migration that named its own issuer.
create or replace function public.approve_indoor_dc(p_dc_no text, p_check_only boolean default false)
returns text language plpgsql security definer set search_path = public as $$
declare
  v_dc    public.indoor_dcs%rowtype;
  j       record;
  v_call  record;
  v_draft jsonb;
  v_uid   text;
  v_me    text;
  v_sp    jsonb;
begin
  select * into v_dc from public.indoor_dcs where dc_no = btrim(p_dc_no) for update;
  if not found then
    raise exception 'Indoor DC % was not found', p_dc_no using errcode = '23503';
  end if;
  if not public.indoor_dc_may_approve(v_dc.authorised_by_name) then
    raise exception 'only % (AUTHORISED BY) or an administrator approves Indoor DC %', coalesce(nullif(v_dc.authorised_by_name, ''), '(nobody named)'), v_dc.dc_no
      using errcode = '42501';
  end if;
  if v_dc.created_by = auth.uid() and not public.is_admin() then
    raise exception 'Indoor DC % was issued by you -- the Reporting Manager, Regional Manager or NSM the User Master names approves it', v_dc.dc_no
      using errcode = '42501';
  end if;
  if v_dc.approval_status <> 'Pending approval' then
    raise exception 'Indoor DC % is %, not pending approval', v_dc.dc_no, v_dc.approval_status
      using errcode = '23514';
  end if;

  -- Every unit with a call must have its visit drafted before anything is
  -- written -- including on a check-only call, so the screen says so first.
  for j in select * from public.indoor_jobs
            where btrim(dispatch_ref) = v_dc.dc_no
              and coalesce(btrim(ucn), '') <> '' and visit_filed_at is null
            order by id loop
    if j.visit_draft is null or jsonb_typeof(j.visit_draft) <> 'object' then
      raise exception '%: no visit was drafted with its Indoor Service Report -- the Indoor engineer completes it (Report stage) before Indoor DC % can be approved', j.job_no, v_dc.dc_no
        using errcode = '23514';
    end if;
    if not exists (select 1 from public.calls c where c.ucn = btrim(j.ucn)) then
      raise exception '%: call % was not found -- its visit cannot be filed', j.job_no, btrim(j.ucn)
        using errcode = '23503';
    end if;
  end loop;
  if p_check_only then return 'OK'; end if;

  v_me := coalesce((select nullif(btrim(p.email), '') from public.profiles p where p.id = auth.uid()), auth.email(), '');
  perform set_config('rithi.indoor_visit', 'on', true);

  for j in select * from public.indoor_jobs
            where btrim(dispatch_ref) = v_dc.dc_no
              and coalesce(btrim(ucn), '') <> '' and visit_filed_at is null
            order by id loop
    select c.ucn, c.call_number, c.call_type into v_call from public.calls c where c.ucn = btrim(j.ucn) limit 1;
    v_draft := j.visit_draft;
    -- WHAT THE VISIT ENTRY'S SAVE PATH FILES (fileVisit, CallReporting.tsx),
    -- with the user's fixed Indoor values whatever the draft says: Unsolved /
    -- Return to Field / work details Yes; the report is the uploaded Indoor
    -- Service Report and its number travels as Manual Report No.
    -- A VISIT ALREADY FILED by an earlier attempt through the screen (0323's
    -- path recorded its uid before finishing) is reused, never filed twice;
    -- that path's retry then filed the spares, and so does this.
    if j.visit_uid is not null and exists (select 1 from public.reports r where r.uid = j.visit_uid) then
      v_uid := j.visit_uid;
    else
    v_uid := 'WEB-' || upper(to_hex((extract(epoch from clock_timestamp()) * 1000)::bigint))
             || '-' || upper(substr(md5(random()::text || j.id::text), 1, 5));
    insert into public.reports (uid, ucn, call_number, manual_report, call_status, pending_reason,
                                engineer, engineer_email, visit_at, data, updated_at)
    values (v_uid, btrim(j.ucn), coalesce(v_call.call_number, ''), coalesce(j.report_file_url, ''),
            'Unsolved', 'Return to Field',
            coalesce(v_draft->>'engineer', ''), coalesce(v_draft->>'engineerEmail', ''),
            case when coalesce(v_draft->>'visitDate', '') <> '' then ((v_draft->>'visitDate') || 'T00:00:00Z')::timestamptz end,
            jsonb_build_object(
              'Email-ID', v_me,
              'Call Type', coalesce(v_call.call_type, ''),
              'Visit Entry Date', to_char(now() at time zone 'Asia/Kolkata', 'DD-Mon-YYYY HH24:MI:SS'),
              'Visit Date & Time', coalesce(v_draft->>'visitDate', ''))
            || case when jsonb_typeof(v_draft->'work') = 'object' then v_draft->'work' else '{}'::jsonb end
            -- the fixed values LAST, so nothing in the draft can override them
            || jsonb_build_object('Update Visit Work Details?', 'Yes',
                                  'Manual Report', coalesce(j.report_file_url, ''),
                                  'Manual Report No.', coalesce(j.indoor_report_no, '')),
            now());
    end if;

    -- The drafted spares, every part in ONE statement, as the screen did.
    if jsonb_typeof(v_draft->'spares') = 'array' and jsonb_array_length(v_draft->'spares') > 0 then
      insert into public.spare_consumption (ucn, call_number, part, qty, grir, engineer, engineer_email, data)
      select btrim(j.ucn), coalesce(v_call.call_number, ''), coalesce(sp->>'part', ''),
             coalesce(nullif(sp->>'qty', '')::numeric, 1), coalesce(sp->>'grir', ''),
             coalesce(v_draft->>'engineer', ''), coalesce(v_draft->>'engineerEmail', ''), '{}'::jsonb
        from jsonb_array_elements(v_draft->'spares') sp;
    end if;

    update public.indoor_jobs set visit_uid = v_uid, visit_filed_at = now() where id = j.id;
  end loop;

  update public.indoor_dcs
     set approval_status  = 'Approved',
         approved_by      = auth.uid(),
         approved_at      = now(),
         approved_by_name = coalesce((select coalesce(nullif(btrim(p.full_name), ''), p.email)
                                        from public.profiles p where p.id = auth.uid()), '')
   where id = v_dc.id;
  return v_dc.dc_no;
end $$;

-- ------------------------------------------------------------------------
-- 0334_indoor_testing_data_emptied.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0334 — THE INDOOR SERVICE TEST DATA, EMPTIED ONCE
--
-- The user, 2026-10-04: "Empty all data in Indoor" -- "Indoor is in Testing
-- Phase, so deleting is not a problem." Asked: no backup; the numbering
-- restarts; and the visits and spares an Indoor DC approval filed on calls go
-- too, each call's status falling back to its previous visit.
--
-- What goes, in this order, ONCE (one_time_fixes_done '0334_indoor_emptied'):
--   1. spare_consumption lines an Indoor DC approval booked. They carry no
--      Indoor marker, but approve_indoor_dc() writes them in the SAME
--      transaction that stamps the job's visit_filed_at, so their created_at
--      is that exact instant -- matched on the job's UCN AND that instant, so
--      no other spare on the call is touched. Their hand stock returns.
--   2. the visits those approvals filed (reports.uid = indoor_jobs.visit_uid);
--      sync_call_last_visit() puts each call back on its previous visit.
--   3. every Indoor DC line, DC and release ticket; every pre-delivery test,
--      check, harvested part, accessory and job.
--   4. the job and IDC number counters, so the next of each is the first.
-- no_hard_delete is lifted BY NAME on the four tables that carry it, for these
-- statements only, and put back before the block ends. Files in Drive stay.
-- ===========================================================================

do $$
declare n_sp integer := 0; n_vis integer := 0; n_jobs integer := 0; n_dcs integer := 0;
begin
  if to_regclass('public.indoor_jobs') is null then
    raise notice '0334: no Indoor tables here -- nothing to empty';
    return;
  end if;
  -- Created here when absent: on a fresh build this module runs before the one
  -- that first makes it, and a bare reference would not even plan.
  create table if not exists public.one_time_fixes_done (
    name text primary key, applied_at timestamptz not null default now(), detail text);
  alter table public.one_time_fixes_done enable row level security;
  revoke all on public.one_time_fixes_done from anon, authenticated;
  if exists (select 1 from public.one_time_fixes_done where name = '0334_indoor_emptied') then
    raise notice '0334: the Indoor test data was emptied before -- not touched again';
    return;
  end if;
  -- Nothing to empty (a fresh build): record it and stop, so the guards on
  -- tables later modules create are not reached for nothing.
  if not exists (select 1 from public.indoor_jobs) and not exists (select 1 from public.indoor_dcs) then
    delete from public.indoor_job_counters;
    delete from public.indoor_dc_counters;
    insert into public.one_time_fixes_done (name, detail) values ('0334_indoor_emptied', 'nothing to empty');
    raise notice '0334: no Indoor data -- nothing to empty';
    return;
  end if;

  if exists (select 1 from pg_trigger where tgname = 'no_hard_delete' and tgrelid = 'public.spare_consumption'::regclass) then
    alter table public.spare_consumption disable trigger no_hard_delete;
  end if;
  delete from public.spare_consumption c
   using public.indoor_jobs j
   where j.visit_filed_at is not null
     and btrim(c.ucn) = btrim(j.ucn)
     and c.created_at = j.visit_filed_at;
  get diagnostics n_sp = row_count;
  if exists (select 1 from pg_trigger where tgname = 'no_hard_delete' and tgrelid = 'public.spare_consumption'::regclass) then
    alter table public.spare_consumption enable trigger no_hard_delete;
  end if;

  if exists (select 1 from pg_trigger where tgname = 'no_hard_delete' and tgrelid = 'public.reports'::regclass) then
    alter table public.reports disable trigger no_hard_delete;
  end if;
  delete from public.reports r
   using public.indoor_jobs j
   where j.visit_uid is not null and r.uid = j.visit_uid;
  get diagnostics n_vis = row_count;
  if exists (select 1 from pg_trigger where tgname = 'no_hard_delete' and tgrelid = 'public.reports'::regclass) then
    alter table public.reports enable trigger no_hard_delete;
  end if;

  select count(*) into n_dcs from public.indoor_dcs;
  if exists (select 1 from pg_trigger where tgname = 'no_hard_delete' and tgrelid = 'public.indoor_dc_lines'::regclass) then
    alter table public.indoor_dc_lines disable trigger no_hard_delete;
  end if;
  if exists (select 1 from pg_trigger where tgname = 'no_hard_delete' and tgrelid = 'public.indoor_dcs'::regclass) then
    alter table public.indoor_dcs disable trigger no_hard_delete;
  end if;
  delete from public.indoor_dc_lines;
  delete from public.indoor_dcs;
  if exists (select 1 from pg_trigger where tgname = 'no_hard_delete' and tgrelid = 'public.indoor_dc_lines'::regclass) then
    alter table public.indoor_dc_lines enable trigger no_hard_delete;
  end if;
  if exists (select 1 from pg_trigger where tgname = 'no_hard_delete' and tgrelid = 'public.indoor_dcs'::regclass) then
    alter table public.indoor_dcs enable trigger no_hard_delete;
  end if;
  if to_regclass('public.indoor_dc_release_tickets') is not null then
    delete from public.indoor_dc_release_tickets;
  end if;

  select count(*) into n_jobs from public.indoor_jobs;
  delete from public.indoor_pdt;
  delete from public.indoor_job_checks;
  delete from public.indoor_job_parts;
  delete from public.indoor_job_accessories;
  delete from public.indoor_jobs;

  delete from public.indoor_job_counters;
  delete from public.indoor_dc_counters;

  insert into public.one_time_fixes_done (name, detail)
  values ('0334_indoor_emptied',
          format('%s job(s), %s DC(s), %s visit(s) and %s spare line(s) removed; numbering restarted', n_jobs, n_dcs, n_vis, n_sp));
  raise notice '0334: % Indoor job(s), % Indoor DC(s), % visit(s) and % spare line(s) filed by DC approvals removed; job and IDC numbering restarted',
    n_jobs, n_dcs, n_vis, n_sp;
end $$;

-- ------------------------------------------------------------------------
-- 0336_indoor_job_worked_on_is_kept.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0336 — AN INDOOR JOB THAT HAS BEEN WORKED ON IS NOT DELETED
--        (second re-review, 2026-10-03: D-142)
--
-- 0324 lets an Indoor Service job be deleted PERMANENTLY -- the user's choice,
-- for a job "received in error (the wrong unit, a duplicate intake, a test
-- entry)" -- and refuses it once the job has left a trace: a DC, or a filed
-- visit. Measured: a job that was CONDEMNED (decontaminated, disposal
-- reference, a harvested part, a check verdict) and one that was VERIFIED and
-- PDT-SIGNED were both deleted, and only the status and the counts survived in
-- the audit entry. Neither was received in error; both are quality records.
--
-- THE FIX keeps 0324's rule and its purpose, and counts the job's own SIGNED
-- or OUTWARD records as traces too: verified or re-verified, Pre-Delivery
-- Testing signed, reported to the customer, condemned or disposal recorded,
-- service report uploaded. The refusal says which trace stopped it.
--
-- WHAT IS DELIBERATELY NOT A TRACE: a QC result, checks, harvested parts,
-- accessories, decontamination and an UNSIGNED PDT. 0324's own suite deletes a
-- job carrying all of those ("Duplicate intake", indoor_delete_job_test
-- section 7), so that is the deletion the user decided on, and it still works
-- exactly as before.
--
-- The function is 0324's definition, read from the file that is its only
-- definition, with that one block (and its variable) added.
-- ===========================================================================

create or replace function public.delete_indoor_job(p_job_id bigint, p_reason text)
returns text
language plpgsql volatile security definer
set search_path = public
as $$
declare
  j        public.indoor_jobs%rowtype;
  v_dcs    text;
  v_acc    integer;
  v_parts  integer;
  v_checks integer;
  v_pdt    integer;
  v_actor  text;
  v_role   text;
  v_trace  text;
begin
  if not public.has_perm('indoor.delete') then
    raise exception 'indoor.delete is required to delete an Indoor Service job'
      using errcode = '42501';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'say why the Indoor Service job is being deleted'
      using errcode = '23514';
  end if;

  select * into j from public.indoor_jobs where id = p_job_id for update;
  if not found then
    raise exception 'Indoor Service job % was not found', p_job_id
      using errcode = '23503';
  end if;

  if btrim(coalesce(j.dispatch_ref, '')) <> '' then
    raise exception '% carries DC No. % -- a job that went on a delivery challan is a record of the unit leaving and is not deleted',
      j.job_no, btrim(j.dispatch_ref)
      using errcode = '23514';
  end if;
  select string_agg(distinct d.dc_no || ' (' || d.approval_status || ')', ', ') into v_dcs
    from public.indoor_dc_lines l join public.indoor_dcs d on d.id = l.dc_id
   where l.job_id = j.id;
  if v_dcs is not null then
    raise exception '% is on Indoor DC % -- the challan keeps its lines, so the job is not deleted',
      j.job_no, v_dcs
      using errcode = '23514';
  end if;
  if j.visit_uid is not null then
    raise exception '% has visit % filed against call % -- the call''s visit history names this job, so it is not deleted',
      j.job_no, j.visit_uid, coalesce(j.ucn, '(none)')
      using errcode = '23514';
  end if;

  -- 0336 (D-142): a job that has been worked on is a quality record, not a job
  -- "received in error" (URS-175). Any one of these is a trace of its own.
  v_trace := concat_ws(', ',
    case when j.status = 'Condemned' or j.condemned_at is not null
              or btrim(coalesce(j.disposal_ref, '')) <> '' or btrim(coalesce(j.disposal_method, '')) <> ''
         then 'condemned / disposal recorded' end,
    case when j.verified_by is not null or j.verified_at is not null then 'verified' end,
    case when btrim(coalesce(j.reverified_by, '')) <> '' or j.reverified_at is not null then 're-verified' end,
    case when exists (select 1 from public.indoor_pdt p
                       where p.job_id = j.id and (p.inspected_by is not null or p.inspected_at is not null))
         then 'Pre-Delivery Testing signed' end,
    case when btrim(coalesce(j.report_file_url, '')) <> '' then 'service report uploaded' end,
    case when j.reported_to_customer_at is not null then 'reported to the customer' end);
  if v_trace <> '' then
    raise exception '% has been worked on (%) -- it is a quality record, not a job received in error, and is not deleted',
      j.job_no, v_trace
      using errcode = '23514';
  end if;

  delete from public.indoor_job_accessories where job_id = j.id;
  get diagnostics v_acc = row_count;
  delete from public.indoor_job_parts where job_id = j.id;
  get diagnostics v_parts = row_count;
  delete from public.indoor_job_checks where job_id = j.id;
  get diagnostics v_checks = row_count;
  delete from public.indoor_pdt where job_id = j.id;
  get diagnostics v_pdt = row_count;
  delete from public.indoor_jobs where id = j.id;

  select coalesce(nullif(btrim(p.full_name), ''), p.email, ''), coalesce(p.role, '')
    into v_actor, v_role
    from public.profiles p where p.id = auth.uid();

  insert into public.audit_log (actor, role, action, target, status, meta)
  values (coalesce(v_actor, ''), coalesce(v_role, ''), 'indoor.job_delete', j.job_no, 'ok',
          jsonb_build_object(
            'job_no', j.job_no, 'product', j.product_name, 'serial', j.serial,
            'ucn', coalesce(j.ucn, ''), 'kind', j.kind, 'activity', j.activity, 'status', j.status,
            'party', coalesce(j.party_name, ''), 'received_at', j.received_at,
            'indoor_report_no', coalesce(j.indoor_report_no, ''),
            'had_visit_draft', j.visit_draft is not null,
            'reason', btrim(p_reason),
            'deleted', jsonb_build_object('accessories', v_acc, 'parts', v_parts, 'checks', v_checks, 'pdt', v_pdt)));

  return j.job_no;
end $$;
comment on function public.delete_indoor_job(bigint, text) is
  'Deletes an Indoor Service job PERMANENTLY with its accessories, harvested parts, checks and PDT (0324): asks indoor.delete (granted to no role by migration; an administrator passes); needs a reason; refused for a job carrying a DC No., named on any Indoor DC line, or whose visit has been filed, and (0336) for one verified, re-verified, PDT-signed, reported to the customer, condemned or disposed of, or with its report uploaded. Writes audit_log indoor.job_delete. The job counter is untouched, so the number is not reissued.';
revoke all on function public.delete_indoor_job(bigint, text) from public;
do $$ begin
  execute 'revoke all on function public.delete_indoor_job(bigint, text) from anon';
  execute 'grant execute on function public.delete_indoor_job(bigint, text) to authenticated';
exception when undefined_object then null; end $$;

-- A DIRECT DELETE IS REFUSED OUTRIGHT. There is no DELETE policy on either
-- table, so a project's default grants would let a DELETE through to RLS and
-- match zero rows -- "nothing happened" rather than "you may not". Revoked, it
-- says so. The function above runs as the owner and is unaffected.
do $$ begin
  execute 'revoke delete on public.indoor_jobs, public.indoor_pdt from anon, authenticated';
exception when undefined_object then null; end $$;

-- ------------------------------------------------------------------------
-- 0352_indoor_report_keeps_its_number.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0352 — AN UPLOADED INDOOR SERVICE REPORT KEEPS ITS NUMBER
--        (second re-review, 2026-10-03: D-115)
--
-- The stage guard (0323) refuses UPLOADING the report without its Indoor
-- Service Report No, but nothing refused BLANKING the number afterwards.
-- Measured: setting indoor_report_no to empty on a job with a report file
-- succeeded, and the register then shows a report with no number.
--
-- A TRIGGER OF ITS OWN, not another rule in indoor_jobs_guard: that function
-- has been rebuilt more than once, and a rebuild from an old revision is how
-- this project has lost rules before (0210 / 0217). This one says one thing:
-- while the job carries a report file, its number is not blank.
--
-- What keeps working: re-uploading a report sets the number and the file in
-- the same update (saveIndoorReport); correcting the number to another
-- non-blank value is still allowed; a connection with no session (a repair
-- in the SQL editor) is not stopped.
-- In the indoor module, after 0336.
-- ===========================================================================

create or replace function public.indoor_report_keeps_its_number()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return new; end if;          -- a migration, a repair
  if btrim(coalesce(new.report_file_url, '')) <> ''
     and btrim(coalesce(new.indoor_report_no, '')) = '' then
    raise exception 'This job has an uploaded Indoor Service Report, so its Indoor Service Report No cannot be blank'
      using errcode = '23514';
  end if;
  return new;
end $$;
revoke execute on function public.indoor_report_keeps_its_number() from public, anon, authenticated;

drop trigger if exists indoor_report_keeps_its_number on public.indoor_jobs;
create trigger indoor_report_keeps_its_number
  before update on public.indoor_jobs
  for each row execute function public.indoor_report_keeps_its_number();

-- ------------------------------------------------------------------------
-- 0370_indoor_troubleshooting.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0370 — INDOOR SERVICE: A FIELD RETURN IS A TROUBLESHOOTING JOB.
--
-- The user, 2026-10-04 (the Receive equipment intake): "Fix it to
-- Troubleshooting - when it is Field Return", and Troubleshooting follows the
-- Repair rules ("Same as Repair"): it cannot be dispatched or closed before
-- its quality check is recorded (4.5.6).
--
-- The activity CHECK gains 'Troubleshooting'; indoor_jobs_guard() is re-stated
-- from the DATABASE's current definition (0352's, read with
-- pg_get_functiondef, never from an older migration file) with the one line
-- that names Repair and Rework now naming Troubleshooting too.
-- ===========================================================================

alter table public.indoor_jobs drop constraint if exists indoor_jobs_activity_check;
alter table public.indoor_jobs add constraint indoor_jobs_activity_check
  check (activity in ('Repair', 'Rework', 'Troubleshooting', 'Salvage', 'Pre-delivery inspection', 'Demo', 'Other'));

CREATE OR REPLACE FUNCTION public.indoor_jobs_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pdt   public.indoor_pdt%rowtype;
  v_blank text[];
  v_bad   text[];
begin
  -- An administrator is not gated by the stage rights; every other rule below
  -- still applies to them, because the ones that follow are about the RECORD
  -- being coherent rather than about who is allowed to act.
  if not public.is_admin() then
    if tg_op = 'UPDATE' then
      if (new.qc_result is distinct from old.qc_result
       or new.qc_by     is distinct from old.qc_by
       or new.qc_at     is distinct from old.qc_at
       or new.qc_notes  is distinct from old.qc_notes)
         and not public.has_perm('indoor.qc') then
        raise exception 'indoor.qc is required to record a quality check'
          using errcode = '42501';
      end if;

      if (new.dispatched_at is distinct from old.dispatched_at
       or new.dispatch_ref  is distinct from old.dispatch_ref
       or new.dispatched_by is distinct from old.dispatched_by)
         and not public.has_perm('indoor.dispatch')
         -- 0323: a REJECTED Indoor DC releases its units through
         -- reject_indoor_dc(), whose approver need not hold indoor.dispatch.
         -- The exemption is a ticket only that definer function can write.
         and not public.indoor_dc_release_ticketed(new.id) then
        raise exception 'indoor.dispatch is required to dispatch a unit'
          using errcode = '42501';
      end if;

      if new.status in ('Dispatched', 'Closed') and new.status is distinct from old.status
         and not public.has_perm('indoor.dispatch') then
        raise exception 'indoor.dispatch is required to mark a unit %', new.status
          using errcode = '42501';
      end if;
    end if;

    -- CONDEMNING IS ITS OWN RIGHT, on insert as well as update. Scrapping
    -- customer property in particular cannot be an engineer's own decision
    -- (open question 8 in the plan, settled here the safe way: a separate
    -- permission granted to nobody by default).
    if (tg_op = 'INSERT' and (btrim(new.condemned_reason) <> '' or new.status = 'Condemned'))
    or (tg_op = 'UPDATE' and (new.condemned_reason is distinct from old.condemned_reason
                           or new.condemned_at     is distinct from old.condemned_at
                           or (new.status = 'Condemned' and old.status <> 'Condemned'))) then
      if not public.has_perm('indoor.condemn') then
        raise exception 'indoor.condemn is required to condemn a unit'
          using errcode = '42501';
      end if;
      if new.condemned_at is null then new.condemned_at := now(); end if;
      if new.condemned_by is null then new.condemned_by := auth.uid(); end if;
    end if;
  end if;

  -- A MACHINE CANNOT LEAVE WITH A FAILED CHECK. 4.5.6 puts the quality check
  -- before the return, so a failed one sends it back to Under repair rather
  -- than being noted and stepped over.
  if new.status in ('Ready', 'Dispatched', 'Closed') and new.qc_result = 'Fail' then
    raise exception 'the quality check failed -- the unit returns to Under repair, it does not leave'
      using errcode = '23514';
  end if;

  -- AND A REPAIR OR REWORK CANNOT LEAVE WITH NO CHECK AT ALL. The other four
  -- activities are exempt on purpose: a demo going out and a unit stripped for
  -- parts have no repair to verify, and a pre-delivery inspection records its
  -- verdict in pdi_result instead.
  if new.status in ('Dispatched', 'Closed')
     and new.activity in ('Repair', 'Rework', 'Troubleshooting')
     and new.qc_result is null then
    raise exception 'a % cannot be dispatched before its quality check is recorded (4.5.6)', lower(new.activity)
      using errcode = '23514';
  end if;

  -- A FAILED PRE-DELIVERY INSPECTION DOES NOT SHIP either, and a held one says
  -- why it is being held.
  if new.status in ('Dispatched', 'Closed')
     and new.activity = 'Pre-delivery inspection' and new.pdi_result = 'Fail' then
    raise exception 'a failed pre-delivery inspection does not leave the workshop'
      using errcode = '23514';
  end if;

  -- Timestamps that follow from an action are stamped, not typed: a cleaning
  -- date somebody can type is a cleaning date somebody can back-date.
  if new.status <> 'Received' and old is distinct from null then
    if new.cleaned_by is distinct from coalesce(old.cleaned_by, new.cleaned_by)
       and new.cleaned_at is null then
      new.cleaned_at := now();
    end if;
  end if;
  if new.qc_result is not null and new.qc_at is null then
    new.qc_at := now();
    if new.qc_by is null then new.qc_by := auth.uid(); end if;
  end if;
  if new.dispatch_ref <> '' and new.dispatched_at is null then
    new.dispatched_at := now();
    if new.dispatched_by is null then new.dispatched_by := auth.uid(); end if;
  end if;

  -- ======================== 0320 ========================================

  -- R/SER/QC/007. A DEMO UNIT OF AN IMPORTED PRODUCT DOES NOT LEAVE UNTESTED.
  -- Asked on the MOVE into Dispatched / Closed (or a job filed or re-kinded
  -- straight into one), not on every later edit: a unit already out before
  -- this rule existed can still be verified and remarked. UNKNOWN imported-ness
  -- does not require the test -- the user's decision; the screen says unknown.
  if new.kind = 'DEMO unit' and new.status in ('Dispatched', 'Closed')
     and (tg_op = 'INSERT' or new.status is distinct from old.status
          or new.kind is distinct from old.kind
          or new.product_name is distinct from old.product_name
          or new.serial is distinct from old.serial)
     and coalesce(public.indoor_job_is_imported(new.product_name, new.serial), false) then
    select * into v_pdt from public.indoor_pdt where job_id = new.id;
    if not found then
      raise exception 'a DEMO unit of an imported product does not leave before its Pre-Delivery Testing (R/SER/QC/007) is recorded'
        using errcode = '23514';
    end if;
    v_bad := array_remove(array[
      case when v_pdt.check1 = 'NOT OK' then '1' end,
      case when v_pdt.check2 = 'NOT OK' then '2' end,
      case when v_pdt.check3 = 'NOT OK' then '3' end,
      case when v_pdt.check4 = 'NOT OK' then '4' end,
      case when v_pdt.check5 = 'NOT OK' then '5' end], null);
    if cardinality(v_bad) > 0 then
      raise exception 'Pre-Delivery Testing check % reads NOT OK -- a machine cannot leave with a failed check',
        array_to_string(v_bad, ', ')
        using errcode = '23514';
    end if;
    v_blank := array_remove(array[
      case when v_pdt.test_date is null then 'Date' end,
      case when btrim(v_pdt.measuring_equipment_id) = '' then 'Measuring Equipment ID No' end,
      case when btrim(v_pdt.software_version) = '' then 'Software Version' end,
      case when btrim(v_pdt.hv) = '' then 'HV' end,
      case when btrim(v_pdt.ht) = '' then 'HT' end,
      case when v_pdt.check1 is null or v_pdt.check2 is null or v_pdt.check3 is null
             or v_pdt.check4 is null or v_pdt.check5 is null then 'checks 1-5' end,
      case when v_pdt.cmv_vte_21 is null or v_pdt.cmv_vte_60 is null or v_pdt.cmv_vte_100 is null
             or v_pdt.cmv_peep_21 is null or v_pdt.cmv_peep_60 is null or v_pdt.cmv_peep_100 is null
             or v_pdt.cmv_o2_21 is null or v_pdt.cmv_o2_60 is null or v_pdt.cmv_o2_100 is null
           then 'the CMV/ACMV readings' end,
      case when v_pdt.pcmv_pip_21 is null or v_pdt.pcmv_pip_60 is null or v_pdt.pcmv_pip_100 is null
             or v_pdt.pcmv_peep_21 is null or v_pdt.pcmv_peep_60 is null or v_pdt.pcmv_peep_100 is null
             or v_pdt.pcmv_o2_21 is null or v_pdt.pcmv_o2_60 is null or v_pdt.pcmv_o2_100 is null
           then 'the PCMV readings' end,
      case when v_pdt.inspected_by is null then 'Inspected by (not signed)' end], null);
    if cardinality(v_blank) > 0 then
      raise exception 'Pre-Delivery Testing (R/SER/QC/007) is incomplete -- still blank: %',
        array_to_string(v_blank, ', ')
        using errcode = '23514';
    end if;
  end if;

  -- R/SER/07 "VERIFIED BY". Its own key; only on a completed row; who and when
  -- from the session. On insert there is nothing to verify yet, so whatever
  -- was sent is discarded.
  if tg_op = 'INSERT' then
    new.verified_by := null;
    new.verified_at := null;
  elsif new.verified_by is distinct from old.verified_by
     or new.verified_at is distinct from old.verified_at then
    if not public.has_perm('indoor.verify') then
      raise exception 'indoor.verify is required to verify an Indoor Service register entry'
        using errcode = '42501';
    end if;
    if new.verified_by is null then
      new.verified_at := null;               -- a verification withdrawn
    else
      if new.status not in ('Dispatched', 'Closed', 'Condemned') then
        raise exception 'a register entry is verified once the unit is Dispatched, Closed or Condemned -- this one is %', new.status
          using errcode = '23514';
      end if;
      new.verified_by := auth.uid();
      new.verified_at := now();
    end if;
  end if;

  -- R/SER/07 "Status" is the COVER, in the one vocabulary (0208), where that
  -- rule is installed. Run-time lookup: data_integrity runs after this module.
  if new.cover is distinct from (case when tg_op = 'UPDATE' then old.cover end)
     and to_regprocedure('public.cover_code(text)') is not null then
    execute 'select public.cover_code($1)' into new.cover using new.cover;
    new.cover := coalesce(new.cover, '');
  end if;


  -- ======================== 0323 ========================================

  -- A UNIT ON AN INDOOR DC THAT IS STILL PENDING APPROVAL DOES NOT LEAVE.
  -- Asked on the move into Dispatched / Closed.
  if new.status in ('Dispatched', 'Closed')
     and (tg_op = 'INSERT' or new.status is distinct from old.status)
     and btrim(coalesce(new.dispatch_ref, '')) <> ''
     and exists (select 1 from public.indoor_dcs d
                  where d.dc_no = btrim(new.dispatch_ref) and d.approval_status = 'Pending approval') then
    raise exception 'Indoor DC % is still pending approval -- the unit is dispatched once it is approved', btrim(new.dispatch_ref)
      using errcode = '23514';
  end if;

  -- STAGE 4 -- THE INDOOR SERVICE REPORT. Uploaded after CLEANING, with its
  -- number; the indoor.work right; who and when from the session.
  if new.report_file_url is distinct from (case when tg_op = 'UPDATE' then old.report_file_url end)
     and btrim(coalesce(new.report_file_url, '')) <> '' then
    if not public.is_admin() and not public.has_perm('indoor.work') then
      raise exception 'indoor.work is required to upload the Indoor Service Report'
        using errcode = '42501';
    end if;
    if new.cleaned_at is null then
      raise exception 'the Indoor Service Report is uploaded after cleaning (WI/SER/01) -- this unit has not been cleaned yet'
        using errcode = '23514';
    end if;
    if btrim(coalesce(new.indoor_report_no, '')) = '' then
      raise exception 'an uploaded Indoor Service Report needs its Indoor Service Report No'
        using errcode = '23514';
    end if;
    new.report_uploaded_by := auth.uid();
    new.report_uploaded_at := now();
  elsif btrim(coalesce(new.report_file_url, '')) = '' then
    new.report_file_url    := '';
    new.report_file_name   := '';
    new.report_uploaded_by := null;
    new.report_uploaded_at := null;
  elsif tg_op = 'UPDATE' then
    new.report_uploaded_by := old.report_uploaded_by;   -- unchanged file: the stamps stand
    new.report_uploaded_at := old.report_uploaded_at;
  end if;

  -- STAGE 5 -- THE VISIT FILED FROM THE DRAFT. visit_uid must be a visit of
  -- THIS job's call; visit_filed_at is stamped, and only once a visit is named.
  if new.visit_uid is distinct from (case when tg_op = 'UPDATE' then old.visit_uid end)
     and new.visit_uid is not null then
    if new.ucn is null or not exists (select 1 from public.reports r
                                       where r.uid = new.visit_uid and r.ucn = new.ucn) then
      raise exception 'visit % is not a visit of call % -- a job records only the visit filed against its own call',
        new.visit_uid, coalesce(new.ucn, '(none)')
        using errcode = '23514';
    end if;
    -- THE USER'S RULE FOR THIS VISIT (2026-10-02): the unit goes back to the
    -- field, so the call is Unsolved, pending "Return to Field", with the work
    -- details updated. A visit saying anything else is not the one this stage
    -- files.
    if not exists (select 1 from public.reports r
                    where r.uid = new.visit_uid
                      and r.call_status = 'Unsolved'
                      and r.pending_reason = 'Return to Field'
                      and r.data ->> 'Update Visit Work Details?' = 'Yes') then
      raise exception 'visit % does not read Unsolved / Return to Field / Update Visit Work Details? = Yes -- the visit filed from Indoor Service always does',
        new.visit_uid
        using errcode = '23514';
    end if;
    if btrim(coalesce(new.report_file_url, '')) = '' then
      raise exception 'the visit is filed from the Indoor Service Report stage -- upload the report first'
        using errcode = '23514';
    end if;
  end if;
  if new.visit_uid is null then
    new.visit_filed_at := null;
  elsif new.visit_filed_at is distinct from (case when tg_op = 'UPDATE' then old.visit_filed_at end) then
    new.visit_filed_at := case when new.visit_filed_at is null then null else now() end;
  end if;

  return new;
end $function$

;

-- ------------------------------------------------------------------------
-- 0372_indoor_call_status.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0372 — INDOOR SERVICE: THE JOB'S CALL STATUS AND CALL PENDING REASON.
--
-- The user, 2026-10-04 (the Repair page's Workshop record): "Move this to Top
-- of this Page, Remove Status and Add - Call Status, Call Pending Reason.
-- Follow the Exact same rule as to Visit Work Details - All Fields should be
-- Mimicked as we are basically calling the same module here." And:
--   * ONE VALUE: what is chosen on the job IS the visit's Call Status and
--     Pending Reason (until now fixed at Unsolved / Return to Field);
--   * the job's own status is DERIVED from it, not chosen:
--       Solved - ...                 -> Ready (a Repair / Rework /
--                                       Troubleshooting first needs its QC
--                                       Pass: until then QC)
--       Unsolved, spare not available -> Awaiting spares
--       Unsolved, any other reason    -> Under repair
--     never once the unit is Dispatched, Closed or Condemned, and not before
--     it is cleaned;
--   * a DEMO / new device (no call) keeps its Status chosen by hand.
-- The visit form's rules, mirrored: the three statuses of that form; a Pending
-- Reason for Unsolved (asked of the DC approval, which files the visit); a
-- report pending reads "Report Pending"; a completed report has none.
-- ===========================================================================

alter table public.indoor_jobs add column if not exists call_status         text not null default '';
alter table public.indoor_jobs add column if not exists call_pending_reason text not null default '';

alter table public.indoor_jobs drop constraint if exists indoor_jobs_call_status_check;
alter table public.indoor_jobs add constraint indoor_jobs_call_status_check
  check (call_status in ('', 'Solved - Report Completed', 'Unsolved', 'Solved - Report Pending'));

-- What the filed visit reads: the job's choice, or -- for a job from before
-- 0372 with none -- the old fixed Unsolved / Return to Field.
create or replace function public.indoor_visit_status(p_status text, p_reason text)
returns table (call_status text, pending_reason text)
language sql immutable set search_path = public as $$
  select case when btrim(coalesce(p_status, '')) = '' then 'Unsolved' else btrim(p_status) end,
         case when btrim(coalesce(p_status, '')) = '' then 'Return to Field'
              when btrim(p_status) = 'Solved - Report Pending' then 'Report Pending'
              when btrim(p_status) = 'Solved - Report Completed' then ''
              else btrim(coalesce(p_reason, '')) end;
$$;

-- THE DERIVATION, BEFORE the guard (zy < zz) so the guard judges the status it
-- produced. Also keeps a saved visit draft in step, so the two never disagree.
create or replace function public.indoor_jobs_call_status()
returns trigger language plpgsql set search_path = public as $$
declare
  st     text := btrim(coalesce(new.call_status, ''));
  rsn    text := upper(btrim(coalesce(new.call_pending_reason, '')));
begin
  -- The visit form's own normalising: a pending report reads Report Pending,
  -- a completed one carries no reason.
  if st = 'Solved - Report Pending' then new.call_pending_reason := 'Report Pending';
  elsif st = 'Solved - Report Completed' then new.call_pending_reason := '';
  end if;

  if coalesce(btrim(new.ucn), '') <> '' and st <> ''
     and new.cleaned_at is not null
     and coalesce(new.status, '') not in ('Dispatched', 'Closed', 'Condemned') then
    if st like 'Solved%' then
      new.status := case when new.activity in ('Repair', 'Rework', 'Troubleshooting')
                              and new.qc_result is distinct from 'Pass' then 'QC' else 'Ready' end;
    elsif rsn like '%SPARE%' and (rsn like '%NOT AVAILABLE%' or rsn like '%UNAVAILABLE%') then
      new.status := 'Awaiting spares';
    else
      new.status := 'Under repair';
    end if;
  end if;

  if st <> '' and new.visit_draft is not null and jsonb_typeof(new.visit_draft) = 'object' then
    new.visit_draft := new.visit_draft || jsonb_build_object(
      'status', st, 'pendingReason', coalesce(new.call_pending_reason, ''), 'updateWork', 'Yes');
  end if;
  return new;
end $$;
revoke execute on function public.indoor_jobs_call_status() from public, anon, authenticated;

drop trigger if exists zy_indoor_jobs_call_status on public.indoor_jobs;
create trigger zy_indoor_jobs_call_status before insert or update on public.indoor_jobs
  for each row execute function public.indoor_jobs_call_status();

-- The guard, re-stated from the database's current definition (0370's) with
-- its visit check reading the job's choice.
CREATE OR REPLACE FUNCTION public.indoor_jobs_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pdt   public.indoor_pdt%rowtype;
  v_blank text[];
  v_bad   text[];
begin
  -- An administrator is not gated by the stage rights; every other rule below
  -- still applies to them, because the ones that follow are about the RECORD
  -- being coherent rather than about who is allowed to act.
  if not public.is_admin() then
    if tg_op = 'UPDATE' then
      if (new.qc_result is distinct from old.qc_result
       or new.qc_by     is distinct from old.qc_by
       or new.qc_at     is distinct from old.qc_at
       or new.qc_notes  is distinct from old.qc_notes)
         and not public.has_perm('indoor.qc') then
        raise exception 'indoor.qc is required to record a quality check'
          using errcode = '42501';
      end if;

      if (new.dispatched_at is distinct from old.dispatched_at
       or new.dispatch_ref  is distinct from old.dispatch_ref
       or new.dispatched_by is distinct from old.dispatched_by)
         and not public.has_perm('indoor.dispatch')
         -- 0323: a REJECTED Indoor DC releases its units through
         -- reject_indoor_dc(), whose approver need not hold indoor.dispatch.
         -- The exemption is a ticket only that definer function can write.
         and not public.indoor_dc_release_ticketed(new.id) then
        raise exception 'indoor.dispatch is required to dispatch a unit'
          using errcode = '42501';
      end if;

      if new.status in ('Dispatched', 'Closed') and new.status is distinct from old.status
         and not public.has_perm('indoor.dispatch') then
        raise exception 'indoor.dispatch is required to mark a unit %', new.status
          using errcode = '42501';
      end if;
    end if;

    -- CONDEMNING IS ITS OWN RIGHT, on insert as well as update. Scrapping
    -- customer property in particular cannot be an engineer's own decision
    -- (open question 8 in the plan, settled here the safe way: a separate
    -- permission granted to nobody by default).
    if (tg_op = 'INSERT' and (btrim(new.condemned_reason) <> '' or new.status = 'Condemned'))
    or (tg_op = 'UPDATE' and (new.condemned_reason is distinct from old.condemned_reason
                           or new.condemned_at     is distinct from old.condemned_at
                           or (new.status = 'Condemned' and old.status <> 'Condemned'))) then
      if not public.has_perm('indoor.condemn') then
        raise exception 'indoor.condemn is required to condemn a unit'
          using errcode = '42501';
      end if;
      if new.condemned_at is null then new.condemned_at := now(); end if;
      if new.condemned_by is null then new.condemned_by := auth.uid(); end if;
    end if;
  end if;

  -- A MACHINE CANNOT LEAVE WITH A FAILED CHECK. 4.5.6 puts the quality check
  -- before the return, so a failed one sends it back to Under repair rather
  -- than being noted and stepped over.
  if new.status in ('Ready', 'Dispatched', 'Closed') and new.qc_result = 'Fail' then
    raise exception 'the quality check failed -- the unit returns to Under repair, it does not leave'
      using errcode = '23514';
  end if;

  -- AND A REPAIR OR REWORK CANNOT LEAVE WITH NO CHECK AT ALL. The other four
  -- activities are exempt on purpose: a demo going out and a unit stripped for
  -- parts have no repair to verify, and a pre-delivery inspection records its
  -- verdict in pdi_result instead.
  if new.status in ('Dispatched', 'Closed')
     and new.activity in ('Repair', 'Rework', 'Troubleshooting')
     and new.qc_result is null then
    raise exception 'a % cannot be dispatched before its quality check is recorded (4.5.6)', lower(new.activity)
      using errcode = '23514';
  end if;

  -- A FAILED PRE-DELIVERY INSPECTION DOES NOT SHIP either, and a held one says
  -- why it is being held.
  if new.status in ('Dispatched', 'Closed')
     and new.activity = 'Pre-delivery inspection' and new.pdi_result = 'Fail' then
    raise exception 'a failed pre-delivery inspection does not leave the workshop'
      using errcode = '23514';
  end if;

  -- Timestamps that follow from an action are stamped, not typed: a cleaning
  -- date somebody can type is a cleaning date somebody can back-date.
  if new.status <> 'Received' and old is distinct from null then
    if new.cleaned_by is distinct from coalesce(old.cleaned_by, new.cleaned_by)
       and new.cleaned_at is null then
      new.cleaned_at := now();
    end if;
  end if;
  if new.qc_result is not null and new.qc_at is null then
    new.qc_at := now();
    if new.qc_by is null then new.qc_by := auth.uid(); end if;
  end if;
  if new.dispatch_ref <> '' and new.dispatched_at is null then
    new.dispatched_at := now();
    if new.dispatched_by is null then new.dispatched_by := auth.uid(); end if;
  end if;

  -- ======================== 0320 ========================================

  -- R/SER/QC/007. A DEMO UNIT OF AN IMPORTED PRODUCT DOES NOT LEAVE UNTESTED.
  -- Asked on the MOVE into Dispatched / Closed (or a job filed or re-kinded
  -- straight into one), not on every later edit: a unit already out before
  -- this rule existed can still be verified and remarked. UNKNOWN imported-ness
  -- does not require the test -- the user's decision; the screen says unknown.
  if new.kind = 'DEMO unit' and new.status in ('Dispatched', 'Closed')
     and (tg_op = 'INSERT' or new.status is distinct from old.status
          or new.kind is distinct from old.kind
          or new.product_name is distinct from old.product_name
          or new.serial is distinct from old.serial)
     and coalesce(public.indoor_job_is_imported(new.product_name, new.serial), false) then
    select * into v_pdt from public.indoor_pdt where job_id = new.id;
    if not found then
      raise exception 'a DEMO unit of an imported product does not leave before its Pre-Delivery Testing (R/SER/QC/007) is recorded'
        using errcode = '23514';
    end if;
    v_bad := array_remove(array[
      case when v_pdt.check1 = 'NOT OK' then '1' end,
      case when v_pdt.check2 = 'NOT OK' then '2' end,
      case when v_pdt.check3 = 'NOT OK' then '3' end,
      case when v_pdt.check4 = 'NOT OK' then '4' end,
      case when v_pdt.check5 = 'NOT OK' then '5' end], null);
    if cardinality(v_bad) > 0 then
      raise exception 'Pre-Delivery Testing check % reads NOT OK -- a machine cannot leave with a failed check',
        array_to_string(v_bad, ', ')
        using errcode = '23514';
    end if;
    v_blank := array_remove(array[
      case when v_pdt.test_date is null then 'Date' end,
      case when btrim(v_pdt.measuring_equipment_id) = '' then 'Measuring Equipment ID No' end,
      case when btrim(v_pdt.software_version) = '' then 'Software Version' end,
      case when btrim(v_pdt.hv) = '' then 'HV' end,
      case when btrim(v_pdt.ht) = '' then 'HT' end,
      case when v_pdt.check1 is null or v_pdt.check2 is null or v_pdt.check3 is null
             or v_pdt.check4 is null or v_pdt.check5 is null then 'checks 1-5' end,
      case when v_pdt.cmv_vte_21 is null or v_pdt.cmv_vte_60 is null or v_pdt.cmv_vte_100 is null
             or v_pdt.cmv_peep_21 is null or v_pdt.cmv_peep_60 is null or v_pdt.cmv_peep_100 is null
             or v_pdt.cmv_o2_21 is null or v_pdt.cmv_o2_60 is null or v_pdt.cmv_o2_100 is null
           then 'the CMV/ACMV readings' end,
      case when v_pdt.pcmv_pip_21 is null or v_pdt.pcmv_pip_60 is null or v_pdt.pcmv_pip_100 is null
             or v_pdt.pcmv_peep_21 is null or v_pdt.pcmv_peep_60 is null or v_pdt.pcmv_peep_100 is null
             or v_pdt.pcmv_o2_21 is null or v_pdt.pcmv_o2_60 is null or v_pdt.pcmv_o2_100 is null
           then 'the PCMV readings' end,
      case when v_pdt.inspected_by is null then 'Inspected by (not signed)' end], null);
    if cardinality(v_blank) > 0 then
      raise exception 'Pre-Delivery Testing (R/SER/QC/007) is incomplete -- still blank: %',
        array_to_string(v_blank, ', ')
        using errcode = '23514';
    end if;
  end if;

  -- R/SER/07 "VERIFIED BY". Its own key; only on a completed row; who and when
  -- from the session. On insert there is nothing to verify yet, so whatever
  -- was sent is discarded.
  if tg_op = 'INSERT' then
    new.verified_by := null;
    new.verified_at := null;
  elsif new.verified_by is distinct from old.verified_by
     or new.verified_at is distinct from old.verified_at then
    if not public.has_perm('indoor.verify') then
      raise exception 'indoor.verify is required to verify an Indoor Service register entry'
        using errcode = '42501';
    end if;
    if new.verified_by is null then
      new.verified_at := null;               -- a verification withdrawn
    else
      if new.status not in ('Dispatched', 'Closed', 'Condemned') then
        raise exception 'a register entry is verified once the unit is Dispatched, Closed or Condemned -- this one is %', new.status
          using errcode = '23514';
      end if;
      new.verified_by := auth.uid();
      new.verified_at := now();
    end if;
  end if;

  -- R/SER/07 "Status" is the COVER, in the one vocabulary (0208), where that
  -- rule is installed. Run-time lookup: data_integrity runs after this module.
  if new.cover is distinct from (case when tg_op = 'UPDATE' then old.cover end)
     and to_regprocedure('public.cover_code(text)') is not null then
    execute 'select public.cover_code($1)' into new.cover using new.cover;
    new.cover := coalesce(new.cover, '');
  end if;


  -- ======================== 0323 ========================================

  -- A UNIT ON AN INDOOR DC THAT IS STILL PENDING APPROVAL DOES NOT LEAVE.
  -- Asked on the move into Dispatched / Closed.
  if new.status in ('Dispatched', 'Closed')
     and (tg_op = 'INSERT' or new.status is distinct from old.status)
     and btrim(coalesce(new.dispatch_ref, '')) <> ''
     and exists (select 1 from public.indoor_dcs d
                  where d.dc_no = btrim(new.dispatch_ref) and d.approval_status = 'Pending approval') then
    raise exception 'Indoor DC % is still pending approval -- the unit is dispatched once it is approved', btrim(new.dispatch_ref)
      using errcode = '23514';
  end if;

  -- STAGE 4 -- THE INDOOR SERVICE REPORT. Uploaded after CLEANING, with its
  -- number; the indoor.work right; who and when from the session.
  if new.report_file_url is distinct from (case when tg_op = 'UPDATE' then old.report_file_url end)
     and btrim(coalesce(new.report_file_url, '')) <> '' then
    if not public.is_admin() and not public.has_perm('indoor.work') then
      raise exception 'indoor.work is required to upload the Indoor Service Report'
        using errcode = '42501';
    end if;
    if new.cleaned_at is null then
      raise exception 'the Indoor Service Report is uploaded after cleaning (WI/SER/01) -- this unit has not been cleaned yet'
        using errcode = '23514';
    end if;
    if btrim(coalesce(new.indoor_report_no, '')) = '' then
      raise exception 'an uploaded Indoor Service Report needs its Indoor Service Report No'
        using errcode = '23514';
    end if;
    new.report_uploaded_by := auth.uid();
    new.report_uploaded_at := now();
  elsif btrim(coalesce(new.report_file_url, '')) = '' then
    new.report_file_url    := '';
    new.report_file_name   := '';
    new.report_uploaded_by := null;
    new.report_uploaded_at := null;
  elsif tg_op = 'UPDATE' then
    new.report_uploaded_by := old.report_uploaded_by;   -- unchanged file: the stamps stand
    new.report_uploaded_at := old.report_uploaded_at;
  end if;

  -- STAGE 5 -- THE VISIT FILED FROM THE DRAFT. visit_uid must be a visit of
  -- THIS job's call; visit_filed_at is stamped, and only once a visit is named.
  if new.visit_uid is distinct from (case when tg_op = 'UPDATE' then old.visit_uid end)
     and new.visit_uid is not null then
    if new.ucn is null or not exists (select 1 from public.reports r
                                       where r.uid = new.visit_uid and r.ucn = new.ucn) then
      raise exception 'visit % is not a visit of call % -- a job records only the visit filed against its own call',
        new.visit_uid, coalesce(new.ucn, '(none)')
        using errcode = '23514';
    end if;
    -- THE USER'S RULE FOR THIS VISIT (2026-10-02): the unit goes back to the
    -- field, so the call is Unsolved, pending "Return to Field", with the work
    -- details updated. A visit saying anything else is not the one this stage
    -- files.
    -- 0372: the visit reads the Call Status and Pending Reason chosen on the
    -- job's Workshop record (a job from before 0372 with none chosen keeps the
    -- old fixed Unsolved / Return to Field).
    if not exists (select 1 from public.reports r, public.indoor_visit_status(new.call_status, new.call_pending_reason) v
                    where r.uid = new.visit_uid
                      and r.call_status = v.call_status
                      and coalesce(r.pending_reason, '') = coalesce(v.pending_reason, '')
                      and r.data ->> 'Update Visit Work Details?' = 'Yes') then
      raise exception 'visit % does not read the Call Status / Pending Reason chosen on the job, with Update Visit Work Details? = Yes',
        new.visit_uid
        using errcode = '23514';
    end if;
    if btrim(coalesce(new.report_file_url, '')) = '' then
      raise exception 'the visit is filed from the Indoor Service Report stage -- upload the report first'
        using errcode = '23514';
    end if;
  end if;
  if new.visit_uid is null then
    new.visit_filed_at := null;
  elsif new.visit_filed_at is distinct from (case when tg_op = 'UPDATE' then old.visit_filed_at end) then
    new.visit_filed_at := case when new.visit_filed_at is null then null else now() end;
  end if;

  return new;
end $function$;

-- approve_indoor_dc(), re-stated from the database's current definition
-- (0327's), filing the visit with the job's choice and refusing an Unsolved
-- job with no Pending Reason.
CREATE OR REPLACE FUNCTION public.approve_indoor_dc(p_dc_no text, p_check_only boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_vs     record;
  v_dc    public.indoor_dcs%rowtype;
  j       record;
  v_call  record;
  v_draft jsonb;
  v_uid   text;
  v_me    text;
  v_sp    jsonb;
begin
  select * into v_dc from public.indoor_dcs where dc_no = btrim(p_dc_no) for update;
  if not found then
    raise exception 'Indoor DC % was not found', p_dc_no using errcode = '23503';
  end if;
  if not public.indoor_dc_may_approve(v_dc.authorised_by_name) then
    raise exception 'only % (AUTHORISED BY) or an administrator approves Indoor DC %', coalesce(nullif(v_dc.authorised_by_name, ''), '(nobody named)'), v_dc.dc_no
      using errcode = '42501';
  end if;
  if v_dc.created_by = auth.uid() and not public.is_admin() then
    raise exception 'Indoor DC % was issued by you -- the Reporting Manager, Regional Manager or NSM the User Master names approves it', v_dc.dc_no
      using errcode = '42501';
  end if;
  if v_dc.approval_status <> 'Pending approval' then
    raise exception 'Indoor DC % is %, not pending approval', v_dc.dc_no, v_dc.approval_status
      using errcode = '23514';
  end if;

  -- Every unit with a call must have its visit drafted before anything is
  -- written -- including on a check-only call, so the screen says so first.
  for j in select * from public.indoor_jobs
            where btrim(dispatch_ref) = v_dc.dc_no
              and coalesce(btrim(ucn), '') <> '' and visit_filed_at is null
            order by id loop
    if j.visit_draft is null or jsonb_typeof(j.visit_draft) <> 'object' then
      raise exception '%: no visit was drafted with its Indoor Service Report -- the Indoor engineer completes it (Report stage) before Indoor DC % can be approved', j.job_no, v_dc.dc_no
        using errcode = '23514';
    end if;
    if btrim(coalesce(j.call_status, '')) = 'Unsolved' and btrim(coalesce(j.call_pending_reason, '')) = '' then
      raise exception '%: the Call Status is Unsolved with no Call Pending Reason -- choose one in the Workshop record before Indoor DC % can be approved', j.job_no, v_dc.dc_no
        using errcode = '23514';
    end if;
    if not exists (select 1 from public.calls c where c.ucn = btrim(j.ucn)) then
      raise exception '%: call % was not found -- its visit cannot be filed', j.job_no, btrim(j.ucn)
        using errcode = '23503';
    end if;
  end loop;
  if p_check_only then return 'OK'; end if;

  v_me := coalesce((select nullif(btrim(p.email), '') from public.profiles p where p.id = auth.uid()), auth.email(), '');
  perform set_config('rithi.indoor_visit', 'on', true);

  for j in select * from public.indoor_jobs
            where btrim(dispatch_ref) = v_dc.dc_no
              and coalesce(btrim(ucn), '') <> '' and visit_filed_at is null
            order by id loop
    select c.ucn, c.call_number, c.call_type into v_call from public.calls c where c.ucn = btrim(j.ucn) limit 1;
    v_draft := j.visit_draft;
    -- 0372: the Call Status / Pending Reason chosen on the job's Workshop record.
    select * into v_vs from public.indoor_visit_status(j.call_status, j.call_pending_reason);
    -- WHAT THE VISIT ENTRY'S SAVE PATH FILES (fileVisit, CallReporting.tsx),
    -- with the user's fixed Indoor values whatever the draft says: Unsolved /
    -- Return to Field / work details Yes; the report is the uploaded Indoor
    -- Service Report and its number travels as Manual Report No.
    -- A VISIT ALREADY FILED by an earlier attempt through the screen (0323's
    -- path recorded its uid before finishing) is reused, never filed twice;
    -- that path's retry then filed the spares, and so does this.
    if j.visit_uid is not null and exists (select 1 from public.reports r where r.uid = j.visit_uid) then
      v_uid := j.visit_uid;
    else
    v_uid := 'WEB-' || upper(to_hex((extract(epoch from clock_timestamp()) * 1000)::bigint))
             || '-' || upper(substr(md5(random()::text || j.id::text), 1, 5));
    insert into public.reports (uid, ucn, call_number, manual_report, call_status, pending_reason,
                                engineer, engineer_email, visit_at, data, updated_at)
    values (v_uid, btrim(j.ucn), coalesce(v_call.call_number, ''), coalesce(j.report_file_url, ''),
            v_vs.call_status, v_vs.pending_reason,
            coalesce(v_draft->>'engineer', ''), coalesce(v_draft->>'engineerEmail', ''),
            case when coalesce(v_draft->>'visitDate', '') <> '' then ((v_draft->>'visitDate') || 'T00:00:00Z')::timestamptz end,
            jsonb_build_object(
              'Email-ID', v_me,
              'Call Type', coalesce(v_call.call_type, ''),
              'Visit Entry Date', to_char(now() at time zone 'Asia/Kolkata', 'DD-Mon-YYYY HH24:MI:SS'),
              'Visit Date & Time', coalesce(v_draft->>'visitDate', ''))
            || case when jsonb_typeof(v_draft->'work') = 'object' then v_draft->'work' else '{}'::jsonb end
            -- the fixed values LAST, so nothing in the draft can override them
            || jsonb_build_object('Update Visit Work Details?', 'Yes',
                                  'Manual Report', coalesce(j.report_file_url, ''),
                                  'Manual Report No.', coalesce(j.indoor_report_no, '')),
            now());
    end if;

    -- The drafted spares, every part in ONE statement, as the screen did.
    if jsonb_typeof(v_draft->'spares') = 'array' and jsonb_array_length(v_draft->'spares') > 0 then
      insert into public.spare_consumption (ucn, call_number, part, qty, grir, engineer, engineer_email, data)
      select btrim(j.ucn), coalesce(v_call.call_number, ''), coalesce(sp->>'part', ''),
             coalesce(nullif(sp->>'qty', '')::numeric, 1), coalesce(sp->>'grir', ''),
             coalesce(v_draft->>'engineer', ''), coalesce(v_draft->>'engineerEmail', ''), '{}'::jsonb
        from jsonb_array_elements(v_draft->'spares') sp;
    end if;

    update public.indoor_jobs set visit_uid = v_uid, visit_filed_at = now() where id = j.id;
  end loop;

  update public.indoor_dcs
     set approval_status  = 'Approved',
         approved_by      = auth.uid(),
         approved_at      = now(),
         approved_by_name = coalesce((select coalesce(nullif(btrim(p.full_name), ''), p.email)
                                        from public.profiles p where p.id = auth.uid()), '')
   where id = v_dc.id;
  return v_dc.dc_no;
end $function$;

-- ------------------------------------------------------------------------
-- 0374_indoor_new_device_kind.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0374 — INDOOR SERVICE: "NEW DEVICE" IS ITS OWN KIND.
--
-- The user, 2026-10-04: "Split Demo / New Device -> Demo, New Device as
-- Separate Options", a New Device recorded as "its own kind: New device", its
-- activity fixed to Troubleshooting (as a Field Return), a Demo's to Demo.
--
-- A New device has no customer behind it, so wherever that matters it is
-- treated as a DEMO unit is: create_indoor_dc() sends it to the party it is
-- going to (demo_for_party), never to a party_name it does not have. The
-- Pre-Delivery Testing rule stays the DEMO unit's (the user's rule of
-- 2026-10-02: a DEMO unit of an imported product).
-- ===========================================================================

alter table public.indoor_jobs drop constraint if exists indoor_jobs_kind_check;
alter table public.indoor_jobs add constraint indoor_jobs_kind_check
  check (kind in ('Customer property', 'DEMO unit', 'New device'));

-- create_indoor_dc(), re-stated from the database's current definition
-- (0327's) with its two consignee lines counting a New device as a DEMO unit.
CREATE OR REPLACE FUNCTION public.create_indoor_dc(p_job_ids bigint[], p_consignee text, p_customer_ref text DEFAULT ''::text, p_customer_ref_date date DEFAULT NULL::date, p_mode text DEFAULT ''::text, p_purpose text DEFAULT ''::text, p_line_purposes jsonb DEFAULT '[]'::jsonb, p_authorised_by text DEFAULT ''::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ids   bigint[];
  v_date  date := (now() at time zone 'Asia/Kolkata')::date;
  v_dc    bigint;
  v_no    text;
  v_line  integer := 0;
  v_state text;
  v_msg   text;
  v_keys  text;
  v_auth  text;
  j       record;
  a       record;
  v_ov    jsonb;
begin
  if not public.has_perm('indoor.dispatch') then
    raise exception 'indoor.dispatch is required to issue an Indoor DC'
      using errcode = '42501';
  end if;

  select array_agg(x order by o) into v_ids
    from (select x, min(o) as o from unnest(p_job_ids) with ordinality u(x, o)
           where x is not null group by x) d;
  if coalesce(cardinality(v_ids), 0) = 0 then
    raise exception 'choose at least one Ready unit for the Indoor DC'
      using errcode = '22023';
  end if;
  if coalesce(btrim(p_consignee), '') = '' then
    raise exception 'an Indoor DC needs its consignee (To)'
      using errcode = '23514';
  end if;

  -- AUTHORISED BY: one of the issuer's choices, matched without regard to case
  -- and stored as the list spells it. REQUIRED -- it names who approves.
  if coalesce(btrim(p_authorised_by), '') = '' then
    raise exception 'choose who AUTHORISES this Indoor DC (your Reporting Manager, Regional Manager or an NSM) -- they approve it'
      using errcode = '23514';
  end if;
  select au.name into v_auth from public.indoor_dc_authorisers() au
   where upper(btrim(au.name)) = upper(btrim(p_authorised_by))
   limit 1;
  if v_auth is null then
    raise exception 'AUTHORISED BY must be your Reporting Manager, your Regional Manager or an NSM -- % is none of them', btrim(p_authorised_by)
      using errcode = '23514';
  end if;

  -- Every job must exist, and is locked for the rest of the transaction so two
  -- people cannot put one unit on two challans at once.
  perform 1 from public.indoor_jobs where id = any (v_ids) order by id for update;
  if (select count(*) from public.indoor_jobs where id = any (v_ids)) <> cardinality(v_ids) then
    raise exception 'an Indoor Service job on this DC was not found'
      using errcode = '23503';
  end if;

  -- ONE DC, ONE CONSIGNEE: a customer unit goes to its party, a DEMO unit to
  -- its "going to" party.
  select string_agg(distinct coalesce(nullif(btrim(k), ''), '(none)'), ' / ') into v_keys
    from (select case when kind in ('DEMO unit', 'New device') then demo_for_party else party_name end as k
            from public.indoor_jobs where id = any (v_ids)) s;
  if (select count(distinct upper(btrim(coalesce(case when kind in ('DEMO unit', 'New device') then demo_for_party
                                                       else party_name end, ''))))
        from public.indoor_jobs where id = any (v_ids)) > 1 then
    raise exception 'one Indoor DC goes to one consignee -- these units go to %', v_keys
      using errcode = '23514';
  end if;

  for j in
    select ij.*, u.o from public.indoor_jobs ij
      join unnest(v_ids) with ordinality u(x, o) on u.x = ij.id
     order by u.o
  loop
    if j.status <> 'Ready' then
      raise exception '%: only a Ready unit goes on an Indoor DC -- this one is %', j.job_no, j.status
        using errcode = '23514';
    end if;
    if btrim(j.dispatch_ref) <> '' then
      raise exception '%: already carries DC No. % -- one unit, one DC', j.job_no, j.dispatch_ref
        using errcode = '23514';
    end if;
    -- 0323: THE REPORT BEFORE THE DC, AND THE VISIT WITH IT.
    if btrim(coalesce(j.report_file_url, '')) = '' then
      raise exception '%: the Indoor Service Report has not been uploaded -- a unit goes on an Indoor DC after its report', j.job_no
        using errcode = '23514';
    end if;

    -- THE TRIAL. Would the guard let this unit leave? Asked by moving it to
    -- Dispatched and always rolling the move back.
    begin
      update public.indoor_jobs set status = 'Dispatched' where id = j.id;
      raise exception using errcode = 'P0001', message = 'indoor_dc_trial_passed';
    exception when others then
      get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text;
      if v_msg <> 'indoor_dc_trial_passed' then
        raise exception '%: %', j.job_no, v_msg using errcode = v_state;
      end if;
    end;
  end loop;

  -- Overrides must name a job on this DC (a purpose for a unit that is not
  -- here is a mistake, said rather than dropped).
  for v_ov in select * from jsonb_array_elements(coalesce(p_line_purposes, '[]'::jsonb)) loop
    if not coalesce((v_ov ->> 'job_id')::bigint = any (v_ids), false) then
      raise exception 'a line purpose names job %, which is not on this DC', v_ov ->> 'job_id'
        using errcode = '22023';
    end if;
  end loop;

  insert into public.indoor_dcs (dc_no, dc_date, consignee, customer_ref, customer_ref_date,
                                 mode_of_despatch, purpose, authorised_by_name, approval_status)
  values ('auto', v_date, btrim(p_consignee), btrim(coalesce(p_customer_ref, '')), p_customer_ref_date,
          btrim(coalesce(p_mode, '')), btrim(coalesce(p_purpose, '')), v_auth, 'Pending approval')
  returning id, dc_no into v_dc, v_no;

  for j in
    select ij.*, u.o from public.indoor_jobs ij
      join unnest(v_ids) with ordinality u(x, o) on u.x = ij.id
     order by u.o
  loop
    v_line := v_line + 1;
    insert into public.indoor_dc_lines (dc_id, line_no, job_id, accessory_id, part_no, description, qty, purpose)
    values (v_dc, v_line, j.id, null,
            coalesce(public.indoor_job_product_code(j.product_name, j.serial), ''),
            btrim(btrim(j.product_name) || case when btrim(j.serial) <> '' then ' Sl.No ' || btrim(j.serial) else '' end),
            1,
            coalesce((select e ->> 'purpose' from jsonb_array_elements(coalesce(p_line_purposes, '[]'::jsonb)) e
                       where (e ->> 'job_id')::bigint = j.id
                         and nullif(e ->> 'accessory_id', '') is null
                       limit 1), btrim(coalesce(p_purpose, ''))));
    for a in
      select * from public.indoor_job_accessories
       where job_id = j.id and (btrim(name) <> '' or btrim(serial) <> '')
       order by id
    loop
      v_line := v_line + 1;
      insert into public.indoor_dc_lines (dc_id, line_no, job_id, accessory_id, part_no, description, qty, purpose)
      values (v_dc, v_line, j.id, a.id, '',
              btrim(btrim(a.name) || case when btrim(a.serial) <> '' then ' Sl.No ' || btrim(a.serial) else '' end),
              a.qty,
              coalesce((select e ->> 'purpose' from jsonb_array_elements(coalesce(p_line_purposes, '[]'::jsonb)) e
                         where (e ->> 'job_id')::bigint = j.id
                           and (e ->> 'accessory_id')::bigint = a.id
                         limit 1), btrim(coalesce(p_purpose, ''))));
    end loop;
  end loop;

  -- THE STAMP ON EACH JOB. Through the guard, as the caller: it asks
  -- indoor.dispatch for a change of dispatch_ref and stamps dispatched_at /
  -- dispatched_by, exactly as a reference typed on the job does.
  update public.indoor_jobs
     set dispatch_ref = v_no, dc_date = v_date
   where id = any (v_ids);

  return v_no;
end $function$

;

-- ------------------------------------------------------------------------
-- 0377_pre_delivery_qc.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0377  PRE-DELIVERY QUALITY CHECK -- a register of its own (2026-10-05).
--
-- The user: "Pre-Delivery Quality Check [Under Indoor] 1. Imported Machines
-- are received in Godown. 2. It is done before Billing 3. It is done as per
-- the Record. 4. There are certain Checks. 5. Use the Image for Fields, Ensure
-- all the Fields are Mandatory". Their answers: its OWN register (no Indoor
-- job behind it), ANY product, RECORD ONLY (billing is not blocked), and the
-- SAME checks and tables as R/SER/QC/007 -- so the columns are indoor_pdt's
-- (0320), word for word, with the product and serial on the row itself.
--
-- EVERY FIELD IS MANDATORY, and the database says so: NOT NULL and non-blank
-- on every column of the form, so a half-filled check cannot be saved by any
-- path. A record is therefore written whole, in one save.
--
-- INSPECTED BY is the SESSION'S, stamped by the trigger with the name and the
-- designation held then -- whoever saves the record is the person vouching
-- for it, so an edit re-signs it as the editor. A value the browser sends is
-- discarded.
--
-- A QUALITY RECORD: no DELETE policy and no DELETE grant (0049's rule).
--
-- KEYS: mod:/indoor/pdqc opens the page (admin + technical_support only, the
-- 0241 pattern); pdqc.record writes, granted to NO role -- an administrator
-- passes has_perm() anyway; every other grant is made on Roles & Permissions.
-- ===========================================================================

create table if not exists public.pdqc_records (
  id        bigint generated always as identity primary key,

  product_name text not null check (btrim(product_name) <> ''),
  serial       text not null check (btrim(serial) <> ''),
  test_date    date not null,
  measuring_equipment_id text not null check (btrim(measuring_equipment_id) <> ''),
  software_version       text not null check (btrim(software_version) <> ''),
  hv                     text not null check (btrim(hv) <> ''),
  ht                     text not null check (btrim(ht) <> ''),

  check1 text not null check (check1 in ('OK', 'NOT OK')),
  check2 text not null check (check2 in ('OK', 'NOT OK')),
  check3 text not null check (check3 in ('OK', 'NOT OK')),
  check4 text not null check (check4 in ('OK', 'NOT OK')),
  check5 text not null check (check5 in ('OK', 'NOT OK')),

  -- 7. Mode CMV/ACMV -- Volume (Vte), Peep, O2% at FiO2 21 / 60 / 100 %
  cmv_vte_21  numeric not null, cmv_vte_60  numeric not null, cmv_vte_100  numeric not null,
  cmv_peep_21 numeric not null, cmv_peep_60 numeric not null, cmv_peep_100 numeric not null,
  cmv_o2_21   numeric not null, cmv_o2_60   numeric not null, cmv_o2_100   numeric not null,
  -- 8. Mode PCMV -- PIP, Peep, O2% at FiO2 21 / 60 / 100 %
  pcmv_pip_21  numeric not null, pcmv_pip_60  numeric not null, pcmv_pip_100  numeric not null,
  pcmv_peep_21 numeric not null, pcmv_peep_60 numeric not null, pcmv_peep_100 numeric not null,
  pcmv_o2_21   numeric not null, pcmv_o2_60   numeric not null, pcmv_o2_100   numeric not null,

  inspected_by          uuid,
  inspector_name        text not null default '',
  inspector_designation text not null default '',
  inspected_at          timestamptz,

  created_by uuid,
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now()
);

comment on table public.pdqc_records is
  'Pre-Delivery Quality Check (R/SER/QC/007) of an imported machine in the godown before billing, one row per check (0377). Every field is mandatory; Inspected by is stamped from the session at every save. Record only: nothing else reads it. A quality record: never deleted.';

create index if not exists pdqc_records_serial on public.pdqc_records (serial);
create index if not exists pdqc_records_test_date on public.pdqc_records (test_date desc, id desc);

create or replace function public.pdqc_stamp()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.product_name := btrim(new.product_name);
  new.serial       := btrim(new.serial);
  new.updated_at   := now();
  new.updated_by   := auth.uid();
  if tg_op = 'INSERT' then
    new.created_at := now();
    new.created_by := auth.uid();
  else
    new.created_at := old.created_at;
    new.created_by := old.created_by;
  end if;
  -- WHOEVER SAVES IS THE INSPECTOR -- never what the browser sent.
  new.inspected_by := auth.uid();
  new.inspected_at := case when auth.uid() is null then null else now() end;
  new.inspector_name := ''; new.inspector_designation := '';
  select coalesce(nullif(btrim(p.full_name), ''), p.email, ''), coalesce(btrim(p.designation), '')
    into new.inspector_name, new.inspector_designation
    from public.profiles p where p.id = auth.uid();
  new.inspector_name        := coalesce(new.inspector_name, '');
  new.inspector_designation := coalesce(new.inspector_designation, '');
  return new;
end $$;
revoke execute on function public.pdqc_stamp() from public, anon, authenticated;

drop trigger if exists zz_pdqc_stamp on public.pdqc_records;
create trigger zz_pdqc_stamp before insert or update on public.pdqc_records
  for each row execute function public.pdqc_stamp();

alter table public.pdqc_records enable row level security;
drop policy if exists pdqc_read on public.pdqc_records;
create policy pdqc_read on public.pdqc_records for select
  using ((select public.has_perm('mod:/indoor/pdqc')) or (select public.has_perm('pdqc.record')));
drop policy if exists pdqc_insert on public.pdqc_records;
create policy pdqc_insert on public.pdqc_records for insert
  with check ((select public.has_perm('pdqc.record')));
drop policy if exists pdqc_update on public.pdqc_records;
create policy pdqc_update on public.pdqc_records for update
  using ((select public.has_perm('pdqc.record')))
  with check ((select public.has_perm('pdqc.record')));
revoke all on public.pdqc_records from anon;
revoke delete, truncate on public.pdqc_records from authenticated;
grant select, insert, update on public.pdqc_records to authenticated;

do $$
begin
  if to_regprocedure('public.sys_columns_attach(regclass)') is not null then
    perform public.sys_columns_attach('public.pdqc_records'::regclass);
  end if;
end $$;

-- THE SCREEN'S KEY, IN THE ADMIN AND TECHNICAL SUPPORT ROLES ONLY (0241, 0355).
do $$
declare n integer;
begin
  if to_regclass('public.app_roles') is null then return; end if;
  update public.app_roles ar
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (select jsonb_array_elements_text(ar.permissions) as v
                   union select unnest(array['mod:/indoor/pdqc']) as v) u),
         updated_at = now()
   where jsonb_array_length(ar.permissions) > 0
     and ar.role in ('admin', 'technical_support')
     and not (ar.permissions ? 'mod:/indoor/pdqc');
  get diagnostics n = row_count;
  raise notice '0377: Pre-Delivery Quality Check screen key given to admin + technical_support (% of 2 rows) -- grant the rest on Roles & Permissions', n;
end $$;

-- ------------------------------------------------------------------------
-- 0378_pdqc_number.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0378  PRE-DELIVERY QUALITY CHECK NUMBER -- PDQC/YY/NNNN (2026-10-05).
--
-- The user, asked whether a check should carry a number such as
-- PDQC/26/0001: "Yes". Numbered like RCY/YY/NNNN (0355): the two-digit year
-- of when the check is recorded (India time), restarting at 0001 each year,
-- stamped by the database on insert and never changed after. Checks already
-- recorded are numbered once, in the order they were recorded.
-- ===========================================================================

alter table public.pdqc_records add column if not exists pdqc_no text;

create or replace function public.pdqc_next_no(p_at timestamptz)
returns text language plpgsql security definer set search_path = public as $$
declare
  yy text := to_char(p_at at time zone 'Asia/Kolkata', 'YY');
  n  integer;
begin
  perform pg_advisory_xact_lock(hashtext('pdqc_no:' || yy));
  select coalesce(max(nullif(split_part(pdqc_no, '/', 3), '')::int), 0) into n
    from public.pdqc_records where pdqc_no like 'PDQC/' || yy || '/%';
  return 'PDQC/' || yy || '/' || lpad((n + 1)::text, 4, '0');
end $$;
revoke execute on function public.pdqc_next_no(timestamptz) from public, anon, authenticated;

-- Number what is already there, oldest first (a no-op once every row has one).
do $$
declare r record;
begin
  for r in select id, created_at from public.pdqc_records where pdqc_no is null order by created_at, id loop
    update public.pdqc_records set pdqc_no = public.pdqc_next_no(r.created_at) where id = r.id;
  end loop;
end $$;

create unique index if not exists pdqc_records_pdqc_no on public.pdqc_records (pdqc_no);

-- The number is the database's: given on insert, kept on every update.
create or replace function public.pdqc_number()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    new.pdqc_no := public.pdqc_next_no(now());
  else
    new.pdqc_no := coalesce(old.pdqc_no, new.pdqc_no);
  end if;
  return new;
end $$;
revoke execute on function public.pdqc_number() from public, anon, authenticated;

drop trigger if exists zy_pdqc_number on public.pdqc_records;
create trigger zy_pdqc_number before insert or update on public.pdqc_records
  for each row execute function public.pdqc_number();

alter table public.pdqc_records alter column pdqc_no set not null;

-- ------------------------------------------------------------------------
-- 0403_indoor_approval_skips_a_solved_call.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0403 — APPROVING AN INDOOR DC DOES NOT PUT A SOLVED CALL BACK TO UNSOLVED
--        (second re-review D-145; the user's decision, 2026-10-04)
--
-- approve_indoor_dc files each unit's drafted visit as Unsolved / Return to
-- Field without asking the call's state. Measured: a call solved by a field
-- visit after the draft received the approval's Unsolved visit as its latest
-- entry, so it read Unsolved, reopen_count 0, nothing saying why.
--
-- THE USER'S DECISION: "Approve, skip that visit" -- the DC is approved and
-- its other units' visits are filed; for a unit whose call is already Solved
-- the drafted visit (and its spares) is NOT filed, the skip is written to the
-- audit log (indoor.visit_skipped) and the approver is told which calls: the
-- function returns "<DC No> | visit not filed, call already Solved: <UCNs>",
-- and the screen shows it. "Solved" is the call's last status beginning with
-- Solved (Solved, Solved - Report Pending ...) -- NOT open_state's "Report
-- pending", which also covers a visit with a blank status.
--
-- Built on 0372's definition (the workshop's Call Status / Pending Reason
-- decide the visit's), VERBATIM, with those lines added -- so the skip applies
-- only where the call is already Solved AND the visit this job would file is
-- not: a visit the workshop records as Solved is still filed.
-- (Written as 0360 against 0327; renumbered after main's 0372 re-stated the
-- function without it, which would otherwise have dropped the skip.)
-- In the indoor module, after 0372.
-- ===========================================================================

CREATE OR REPLACE FUNCTION public.approve_indoor_dc(p_dc_no text, p_check_only boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_vs     record;
  v_skipped text[] := '{}';
  v_dc    public.indoor_dcs%rowtype;
  j       record;
  v_call  record;
  v_draft jsonb;
  v_uid   text;
  v_me    text;
  v_sp    jsonb;
begin
  select * into v_dc from public.indoor_dcs where dc_no = btrim(p_dc_no) for update;
  if not found then
    raise exception 'Indoor DC % was not found', p_dc_no using errcode = '23503';
  end if;
  if not public.indoor_dc_may_approve(v_dc.authorised_by_name) then
    raise exception 'only % (AUTHORISED BY) or an administrator approves Indoor DC %', coalesce(nullif(v_dc.authorised_by_name, ''), '(nobody named)'), v_dc.dc_no
      using errcode = '42501';
  end if;
  if v_dc.created_by = auth.uid() and not public.is_admin() then
    raise exception 'Indoor DC % was issued by you -- the Reporting Manager, Regional Manager or NSM the User Master names approves it', v_dc.dc_no
      using errcode = '42501';
  end if;
  if v_dc.approval_status <> 'Pending approval' then
    raise exception 'Indoor DC % is %, not pending approval', v_dc.dc_no, v_dc.approval_status
      using errcode = '23514';
  end if;

  -- Every unit with a call must have its visit drafted before anything is
  -- written -- including on a check-only call, so the screen says so first.
  for j in select * from public.indoor_jobs
            where btrim(dispatch_ref) = v_dc.dc_no
              and coalesce(btrim(ucn), '') <> '' and visit_filed_at is null
            order by id loop
    if j.visit_draft is null or jsonb_typeof(j.visit_draft) <> 'object' then
      raise exception '%: no visit was drafted with its Indoor Service Report -- the Indoor engineer completes it (Report stage) before Indoor DC % can be approved', j.job_no, v_dc.dc_no
        using errcode = '23514';
    end if;
    if btrim(coalesce(j.call_status, '')) = 'Unsolved' and btrim(coalesce(j.call_pending_reason, '')) = '' then
      raise exception '%: the Call Status is Unsolved with no Call Pending Reason -- choose one in the Workshop record before Indoor DC % can be approved', j.job_no, v_dc.dc_no
        using errcode = '23514';
    end if;
    if not exists (select 1 from public.calls c where c.ucn = btrim(j.ucn)) then
      raise exception '%: call % was not found -- its visit cannot be filed', j.job_no, btrim(j.ucn)
        using errcode = '23503';
    end if;
  end loop;
  if p_check_only then return 'OK'; end if;

  v_me := coalesce((select nullif(btrim(p.email), '') from public.profiles p where p.id = auth.uid()), auth.email(), '');
  perform set_config('rithi.indoor_visit', 'on', true);

  for j in select * from public.indoor_jobs
            where btrim(dispatch_ref) = v_dc.dc_no
              and coalesce(btrim(ucn), '') <> '' and visit_filed_at is null
            order by id loop
    select c.ucn, c.call_number, c.call_type, c.last_status into v_call from public.calls c where c.ucn = btrim(j.ucn) limit 1;
    v_draft := j.visit_draft;
    -- 0372: the Call Status / Pending Reason chosen on the job's Workshop record.
    select * into v_vs from public.indoor_visit_status(j.call_status, j.call_pending_reason);
    -- D-145 (the user's decision, 2026-10-04: "Approve, skip that visit"): a
    -- call SOLVED since the visit was drafted is not put back to an open
    -- status. When the call's last status is Solved and the visit this job
    -- would file is not, the visit and its spares are not filed, the job keeps
    -- no visit, the skip goes to the audit log, and the approver is told which
    -- calls. A visit the workshop records as Solved (0372) is still filed, and
    -- a visit an earlier attempt already filed is still reused.
    if lower(btrim(coalesce(v_call.last_status, ''))) like 'solved%'
       and lower(btrim(coalesce(v_vs.call_status, ''))) not like 'solved%'
       and not (j.visit_uid is not null and exists (select 1 from public.reports r where r.uid = j.visit_uid)) then
      v_skipped := v_skipped || btrim(j.ucn);
      insert into public.audit_log (actor, role, action, target, status, meta)
      values (v_me, '', 'indoor.visit_skipped', j.job_no, 'ok',
              jsonb_build_object('dc_no', v_dc.dc_no, 'job_no', j.job_no, 'ucn', btrim(j.ucn),
                                 'call_status', coalesce(v_call.last_status, ''),
                                 'reason', 'the call was Solved after the visit was drafted, so the visit was not filed'));
      continue;
    end if;
    -- WHAT THE VISIT ENTRY'S SAVE PATH FILES (fileVisit, CallReporting.tsx),
    -- with the user's fixed Indoor values whatever the draft says: Unsolved /
    -- Return to Field / work details Yes; the report is the uploaded Indoor
    -- Service Report and its number travels as Manual Report No.
    -- A VISIT ALREADY FILED by an earlier attempt through the screen (0323's
    -- path recorded its uid before finishing) is reused, never filed twice;
    -- that path's retry then filed the spares, and so does this.
    if j.visit_uid is not null and exists (select 1 from public.reports r where r.uid = j.visit_uid) then
      v_uid := j.visit_uid;
    else
    v_uid := 'WEB-' || upper(to_hex((extract(epoch from clock_timestamp()) * 1000)::bigint))
             || '-' || upper(substr(md5(random()::text || j.id::text), 1, 5));
    insert into public.reports (uid, ucn, call_number, manual_report, call_status, pending_reason,
                                engineer, engineer_email, visit_at, data, updated_at)
    values (v_uid, btrim(j.ucn), coalesce(v_call.call_number, ''), coalesce(j.report_file_url, ''),
            v_vs.call_status, v_vs.pending_reason,
            coalesce(v_draft->>'engineer', ''), coalesce(v_draft->>'engineerEmail', ''),
            case when coalesce(v_draft->>'visitDate', '') <> '' then ((v_draft->>'visitDate') || 'T00:00:00Z')::timestamptz end,
            jsonb_build_object(
              'Email-ID', v_me,
              'Call Type', coalesce(v_call.call_type, ''),
              'Visit Entry Date', to_char(now() at time zone 'Asia/Kolkata', 'DD-Mon-YYYY HH24:MI:SS'),
              'Visit Date & Time', coalesce(v_draft->>'visitDate', ''))
            || case when jsonb_typeof(v_draft->'work') = 'object' then v_draft->'work' else '{}'::jsonb end
            -- the fixed values LAST, so nothing in the draft can override them
            || jsonb_build_object('Update Visit Work Details?', 'Yes',
                                  'Manual Report', coalesce(j.report_file_url, ''),
                                  'Manual Report No.', coalesce(j.indoor_report_no, '')),
            now());
    end if;

    -- The drafted spares, every part in ONE statement, as the screen did.
    if jsonb_typeof(v_draft->'spares') = 'array' and jsonb_array_length(v_draft->'spares') > 0 then
      insert into public.spare_consumption (ucn, call_number, part, qty, grir, engineer, engineer_email, data)
      select btrim(j.ucn), coalesce(v_call.call_number, ''), coalesce(sp->>'part', ''),
             coalesce(nullif(sp->>'qty', '')::numeric, 1), coalesce(sp->>'grir', ''),
             coalesce(v_draft->>'engineer', ''), coalesce(v_draft->>'engineerEmail', ''), '{}'::jsonb
        from jsonb_array_elements(v_draft->'spares') sp;
    end if;

    update public.indoor_jobs set visit_uid = v_uid, visit_filed_at = now() where id = j.id;
  end loop;

  update public.indoor_dcs
     set approval_status  = 'Approved',
         approved_by      = auth.uid(),
         approved_at      = now(),
         approved_by_name = coalesce((select coalesce(nullif(btrim(p.full_name), ''), p.email)
                                        from public.profiles p where p.id = auth.uid()), '')
   where id = v_dc.id;
  if array_length(v_skipped, 1) > 0 then
    return v_dc.dc_no || ' | visit not filed, call already Solved: ' || array_to_string(v_skipped, ', ');
  end if;
  return v_dc.dc_no;
end $function$;

-- ------------------------------------------------------------------------
-- 0363_indoor_pdt_lock_dispatch_and_cleaning.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0363 — A SIGNED PDT IS LOCKED; THE DISPATCH DATE IS WHEN THE UNIT LEAVES;
--        A CLEANING TIME MAY BE EARLIER BUT NEVER LATER, AND NAMES WHO
--        (second re-review D-111, D-112, D-114; the user's decisions, 2026-10-04)
--
-- D-111 -- indoor_pdt_stamp() stamps the inspector on signing and nothing
-- refused a later change: measured, a second engineer changed the HV reading
-- and a check from OK to NOT OK after the first had signed, and the row still
-- named the first as the inspector -- after dispatch too.
-- THE USER'S DECISION: "Lock once signed" -- a signed PDT cannot be changed;
-- a correction needs it un-signed first, by "a new key, ticked per person":
-- indoor.pdt_unsign (an administrator holds every key; nobody else is given
-- it here). Un-signing is unsign_indoor_pdt(job, reason): the reason and who
-- go to the audit log (indoor.pdt_unsign), and only that function's ticket
-- lets a signature be withdrawn. Signing over somebody else's signature is
-- refused too: that is a change of who vouched for the test.
--
-- D-112 -- the 0323 guard stamps dispatched_at / dispatched_by when the DC
-- number is set, i.e. when the DC is ISSUED; moving the unit to Dispatched
-- later did not re-stamp, so a unit still Ready showed a dispatch date.
-- THE USER'S DECISION: the Dispatch Date is the date it is marked Dispatched.
-- They are stamped on the move into Dispatched (or straight into Closed with
-- none yet) from the session, and a unit not Dispatched or Closed carries
-- none. ONCE, the stamps the DC issue left on units still not dispatched are
-- cleared -- that one statement lifts zz_indoor_jobs_guard by name (the
-- migration has no session, and the guard would read the clearing as an
-- unauthorised dispatch) and puts it straight back.
--
-- D-114 -- the report may be uploaded only after cleaning, judged on
-- cleaned_at, which the browser sent; measured, cleaned_at = 2020-01-01 with
-- no cleaned_by was accepted. THE USER'S DECISION: "allow an earlier time"
-- (cleaning is sometimes recorded after it happened), never a future one, and
-- the database records WHO marked it -- cleaned_by is the session whatever was
-- sent. Clearing the cleaning time clears who.
--
-- ONE TRIGGER OF ITS OWN for D-112 / D-114, not another edit of
-- indoor_jobs_guard: that function is 269 lines and has been rebuilt before.
-- It is named to run AFTER zz_indoor_jobs_guard and zz_indoor_jobs_stamp
-- (zzy_ sorts between them and zzz_sys_stamp), so its stamps are the last word.
-- A connection with no session (a repair, an import) is not stopped.
-- In the indoor module, after 0403.
-- ===========================================================================

-- ---- D-111 ------------------------------------------------------------------
create or replace function public.indoor_pdt_locked_once_signed()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_stamps text[] := array['id', 'job_id', 'inspected_by', 'inspector_name', 'inspector_designation',
                           'inspected_at', 'created_by', 'created_at', 'updated_by', 'updated_at',
                           'sys_id', 'sys_created_by', 'sys_created_on', 'sys_updated_by', 'sys_updated_on'];
begin
  if auth.uid() is null then return new; end if;                -- a repair
  if old.inspected_by is null then return new; end if;           -- not signed: editable

  if new.inspected_by is null then                               -- withdrawing the signature
    if coalesce(current_setting('rithi.pdt_unsign', true), '') = 'on'
       and public.has_perm('indoor.pdt_unsign') then
      return new;
    end if;
    raise exception 'A signed Pre-Delivery Testing record is un-signed with "Un-sign", by somebody given indoor.pdt_unsign, with a reason'
      using errcode = '42501';
  end if;

  if new.inspected_by is distinct from old.inspected_by then
    raise exception 'This Pre-Delivery Testing record is already signed by % -- it is un-signed first, then signed again',
      coalesce(nullif(old.inspector_name, ''), 'the inspector') using errcode = '42501';
  end if;

  if (to_jsonb(new) - v_stamps) is distinct from (to_jsonb(old) - v_stamps) then
    raise exception 'This Pre-Delivery Testing record is signed by % and locked -- it is un-signed first (needs indoor.pdt_unsign and a reason) before anything on it changes',
      coalesce(nullif(old.inspector_name, ''), 'the inspector') using errcode = '42501';
  end if;
  return new;
end $$;
revoke execute on function public.indoor_pdt_locked_once_signed() from public, anon, authenticated;
drop trigger if exists indoor_pdt_locked_once_signed on public.indoor_pdt;
create trigger indoor_pdt_locked_once_signed
  before update on public.indoor_pdt
  for each row execute function public.indoor_pdt_locked_once_signed();

create or replace function public.unsign_indoor_pdt(p_job_id bigint, p_reason text)
returns void language plpgsql security definer set search_path = public as $$
declare v_pdt public.indoor_pdt%rowtype; v_job text; v_actor text;
begin
  if not public.has_perm('indoor.pdt_unsign') then
    raise exception 'indoor.pdt_unsign is required to un-sign a Pre-Delivery Testing record' using errcode = '42501';
  end if;
  if btrim(coalesce(p_reason, '')) = '' then
    raise exception 'Say why the Pre-Delivery Testing record is un-signed' using errcode = '23514';
  end if;
  select * into v_pdt from public.indoor_pdt where job_id = p_job_id for update;
  if not found or v_pdt.inspected_by is null then
    raise exception 'That Pre-Delivery Testing record is not signed' using errcode = '23514';
  end if;
  select job_no into v_job from public.indoor_jobs where id = p_job_id;
  select coalesce(nullif(btrim(p.full_name), ''), p.email, '') into v_actor from public.profiles p where p.id = auth.uid();

  perform set_config('rithi.pdt_unsign', 'on', true);
  update public.indoor_pdt set inspected_by = null where job_id = p_job_id;
  perform set_config('rithi.pdt_unsign', 'off', true);

  insert into public.audit_log (actor, role, action, target, status, meta)
  values (coalesce(v_actor, ''), '', 'indoor.pdt_unsign', coalesce(v_job, p_job_id::text), 'ok',
          jsonb_build_object('job_id', p_job_id, 'reason', btrim(p_reason),
                             'was_signed_by', v_pdt.inspector_name, 'was_signed_at', v_pdt.inspected_at));
end $$;
revoke execute on function public.unsign_indoor_pdt(bigint, text) from public, anon;
grant execute on function public.unsign_indoor_pdt(bigint, text) to authenticated;

-- ---- D-112 / D-114 ----------------------------------------------------------
create or replace function public.indoor_dispatch_and_cleaning_stamps()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return new; end if;                -- a repair, an import

  -- D-112: dispatched when it is marked Dispatched, not when its DC was issued.
  if new.status in ('Dispatched', 'Closed') then
    if new.status = 'Dispatched'
       and (tg_op = 'INSERT' or old.status is distinct from 'Dispatched')
       and (tg_op = 'INSERT' or old.status is distinct from 'Closed') then
      new.dispatched_at := now();
      new.dispatched_by := auth.uid();
    elsif new.status = 'Closed' and new.dispatched_at is null then
      new.dispatched_at := now();
      new.dispatched_by := auth.uid();
    end if;
  else
    new.dispatched_at := null;
    new.dispatched_by := null;
  end if;

  -- D-114: an earlier cleaning time is allowed, a later one is not; who is the session.
  if new.cleaned_at is distinct from (case when tg_op = 'UPDATE' then old.cleaned_at end)
     or new.cleaned_by is distinct from (case when tg_op = 'UPDATE' then old.cleaned_by end) then
    if new.cleaned_at is null then
      new.cleaned_by := null;
    else
      if new.cleaned_at > now() + interval '5 minutes' then
        raise exception 'A cleaning cannot be recorded in the future (%) -- give the time it was done',
          to_char(new.cleaned_at at time zone 'Asia/Kolkata', 'DD-Mon-YYYY HH24:MI') using errcode = '23514';
      end if;
      new.cleaned_by := auth.uid();
    end if;
  end if;
  return new;
end $$;
revoke execute on function public.indoor_dispatch_and_cleaning_stamps() from public, anon, authenticated;
drop trigger if exists zzy_indoor_dispatch_and_cleaning on public.indoor_jobs;
create trigger zzy_indoor_dispatch_and_cleaning
  before insert or update on public.indoor_jobs
  for each row execute function public.indoor_dispatch_and_cleaning_stamps();

-- ---- once: the dispatch stamps the DC issue left on units not yet dispatched --
create table if not exists public.one_time_fixes_done (
  name       text primary key,
  applied_at timestamptz not null default now(),
  detail     text
);
alter table public.one_time_fixes_done enable row level security;
revoke all on public.one_time_fixes_done from anon, authenticated;

do $$
declare n bigint;
begin
  if exists (select 1 from public.one_time_fixes_done where name = '0363_premature_dispatch_stamps_cleared') then return; end if;
  -- Lifted for this ONE statement and put straight back (the 0210 rule).
  alter table public.indoor_jobs disable trigger zz_indoor_jobs_guard;
  update public.indoor_jobs
     set dispatched_at = null, dispatched_by = null
   where status not in ('Dispatched', 'Closed')
     and (dispatched_at is not null or dispatched_by is not null);
  get diagnostics n = row_count;
  alter table public.indoor_jobs enable trigger zz_indoor_jobs_guard;
  insert into public.one_time_fixes_done (name, detail)
  values ('0363_premature_dispatch_stamps_cleared', n || ' unit(s) not yet dispatched had the DC issue''s dispatch stamp cleared');
  raise notice '0363: % unit(s) not yet dispatched had the DC issue''s dispatch stamp cleared', n;
end $$;

-- ------------------------------------------------------------------------
-- 0367_indoor_dc_approver_is_the_login.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0367 — AN INDOOR DC IS APPROVED BY THE LOGIN THE USER MASTER NAMES, NOT BY
--        ANYBODY WHOSE PROFILE CARRIES THE SAME NAME
--        (second re-review D-143)
--
-- indoor_dc_may_approve() (0323) compared authorised_by_name with
-- my_dir_name() (limit 1, no order) OR the caller's profile full_name.
-- Measured: a second login whose profile name equals the approver's, holding
-- calls.view only and with no User Master row, saw both DCs (indoor_read reads
-- it through indoor_job_on_my_dc()) and approved one; the DC then read
-- approved_by_name as the right person.
--
-- The authoriser is chosen from the User Master (0327), so the person named is
-- a User Master row, and that row says which login is theirs: its Mail ID or
-- its Gmail. The caller is now the person named when a User Master row of that
-- name carries the caller's sign-in address -- any such row, not the first.
-- The profile's own name is still accepted ONLY where no User Master row of
-- that name carries any address at all: then the directory cannot say who the
-- person is, and refusing would leave the DC with no approver but an
-- administrator. Where it does carry one, a different login with the same
-- name is refused.
-- Signature and every caller unchanged (approve, reject, record_indoor_visit,
-- the DC list, indoor_job_on_my_dc). In the indoor module, after 0363.
-- ===========================================================================

create or replace function public.indoor_dc_may_approve(p_authorised_by text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_admin()
      or (coalesce(btrim(p_authorised_by), '') <> ''
          and (exists (select 1 from public.user_directory d
                        where upper(btrim(d.name)) = upper(btrim(p_authorised_by))
                          and coalesce(auth.email(), '') <> ''
                          and (lower(btrim(coalesce(d.email, ''))) = lower(auth.email())
                               or lower(btrim(coalesce(d.gmail, ''))) = lower(auth.email())))
               or (not exists (select 1 from public.user_directory d
                                where upper(btrim(d.name)) = upper(btrim(p_authorised_by))
                                  and (btrim(coalesce(d.email, '')) <> '' or btrim(coalesce(d.gmail, '')) <> ''))
                   and upper(btrim(p_authorised_by))
                       = upper(btrim(coalesce((select p.full_name from public.profiles p where p.id = auth.uid()), ''))))));
$$;
comment on function public.indoor_dc_may_approve(text) is
  'True for an administrator, or for the login a User Master row of that name carries (Mail ID or Gmail); by profile name only where no row of that name carries an address (0367, D-143).';
revoke all on function public.indoor_dc_may_approve(text) from public;
revoke execute on function public.indoor_dc_may_approve(text) from anon;
grant execute on function public.indoor_dc_may_approve(text) to authenticated;

-- ------------------------------------------------------------------------
-- 0404_indoor_record_visit_closed_and_comments.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0404 — record_indoor_visit() IS NOT A SIGNED-IN USER'S, AND THE INDOOR VISIT
--        COLUMNS SAY WHEN THE VISIT IS ACTUALLY FILED
--        (second re-review D-108, D-116)
--
-- D-108 -- 0327 stopped the engineer marking a unit's visit filed, but
-- record_indoor_visit() stayed executable by authenticated, and no screen calls
-- it (read: src/ -- only an unused wrapper names it). Measured: the DC's named
-- approver pointed a repair at a 200-day-old visit with it and approved; the DC
-- read Approved and nothing of this repair was filed. The approval files the
-- visit itself (approve_indoor_dc(), 0327), running as its owner, so it does
-- not need the grant. The function is KEPT for a repair in the SQL editor,
-- where its own checks still apply.
--
-- D-116 -- the column comments 0323 wrote say the visit is filed when the DC is
-- ISSUED and that create_indoor_dc() requires it; since 0327 the visit is filed
-- at APPROVAL and create_indoor_dc() asks neither. DATABASE_SCHEMA.md carries
-- the comments, so it said the same.
-- In the indoor module, after 0367.
-- ===========================================================================

revoke execute on function public.record_indoor_visit(bigint, text, boolean) from public, anon, authenticated;

comment on column public.indoor_jobs.visit_draft is
  'For a job with a UCN: the Visit Entry answers captured with the report upload, a DRAFT. Filed against the UCN when the Indoor DC is APPROVED -- by approve_indoor_dc(), as the approver (0327) -- not when it is issued.';
comment on column public.indoor_jobs.visit_uid is
  'The reports row (visit) filed against the UCN from this job''s draft, written by the DC''s approval (0327). Must name a visit of this job''s UCN; no signed-in write may change it.';
comment on column public.indoor_jobs.visit_filed_at is
  'When the drafted visit was filed in full -- the visit, its spares and its feedback -- by the DC''s approval (0327). create_indoor_dc() does not ask for it; approve_indoor_dc() files it.';

-- ------------------------------------------------------------------------
-- 0412_indoor_reported_to_customer_stamp.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0412 — WHO REPORTED THE DAMAGE TO THE CUSTOMER IS THE SESSION
--        (second re-review D-039, FRS-143.9)
--
-- indoor_jobs.reported_to_customer_at / _by exist (FRS-057) and were on no
-- screen. The screen now records when damage was reported to the owner; the
-- person is the database's to write, the 0363 rule for the cleaning:
--   * setting or changing the time stamps reported_to_customer_by from the
--     session, discarding whatever was sent;
--   * a time in the future is refused (five minutes' grace for a clock);
--   * clearing the time clears the person.
-- A connection with no session (a repair, an import) is left alone.
-- In the indoor module, after 0404.
-- ===========================================================================

create or replace function public.indoor_reported_to_customer_stamp()
returns trigger language plpgsql security invoker set search_path = public as $$
begin
  if auth.uid() is null then return new; end if;
  if new.reported_to_customer_at is distinct from (case when tg_op = 'UPDATE' then old.reported_to_customer_at end)
     or new.reported_to_customer_by is distinct from (case when tg_op = 'UPDATE' then old.reported_to_customer_by end) then
    if new.reported_to_customer_at is null then
      new.reported_to_customer_by := null;
    else
      if new.reported_to_customer_at > now() + interval '5 minutes' then
        raise exception 'A damage report to the customer cannot be recorded in the future (%)',
          to_char(new.reported_to_customer_at at time zone 'Asia/Kolkata', 'DD-Mon-YYYY HH24:MI') using errcode = '23514';
      end if;
      new.reported_to_customer_by := auth.uid();
    end if;
  end if;
  return new;
end $$;
revoke execute on function public.indoor_reported_to_customer_stamp() from public, anon, authenticated;
drop trigger if exists zzy_indoor_reported_to_customer on public.indoor_jobs;
create trigger zzy_indoor_reported_to_customer
  before insert or update on public.indoor_jobs
  for each row execute function public.indoor_reported_to_customer_stamp();

-- ------------------------------------------------------------------------
-- 0355_spare_recycling.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0355 — SPARE RECYCLING: A PARALLEL TRACK UNDER INDOOR SERVICE.
--
-- The user, 2026-10-04: "Create a Complete Work Flow for Spare Recycling,
-- Like Registration, spare request, job done details, consumption, handstock
-- -- This is a Parallel Track and should not collide with Regular Calls or
-- Spare or Handstock. Even the Stock should be maintained Separately. This is
-- Non Auditable Requirement and when i enable the Audit mode, it should not
-- show. Keep all this under Indoor Service. In Spare Request, there is no need
-- for approval. But during Stock out, Give a Provision to add Cost. I want to
-- be able to track how much i am spending for Recycling the Said spare."
--
-- And the answers that shaped it:
--   * a request is a DEFECTIVE SPARE, with an OPTIONAL call reference kept as
--     TEXT -- so nothing here ever reads or writes a call;
--   * the spares used come from the regular stores through an MRS (Material
--     Request Slip), raised WITHOUT approval; STORES books the stock out IN
--     THIS MODULE, with a unit cost, and the quantity lands in the requester's
--     RECYCLING hand stock -- a ledger of its own, never the regular one;
--   * closing the request consumes from that hand stock and records the job
--     done; it closes RETURNED (to the Service Store as R<PartNo>, recorded
--     only -- Part Master and the regular stock are untouched) or NOT
--     RECYCLABLE (with a reason);
--   * cost per request = the parts consumed, valued at their stock-out cost,
--     plus any other costs (labour, courier, vendor, other);
--   * numbering RCY/26/0001 and RMRS/26/0001, restarting each year.
--
-- NOTHING HERE TOUCHES calls, spare_requests, spare_dispatches,
-- spare_consumption, stock_transfers or any hand-stock function: separate
-- tables, separate ledger, separate keys.
--
-- HIDDEN IN AUDIT MODE, BY THE DATABASE. Every policy below adds
-- `not audit_mode()`: while Audit Mode is on, the screen is hidden AND every
-- read returns nothing and every write is refused -- the NAR pattern (a
-- non-auditable requirement).
--
-- THE KEYS ARE GRANTED TO NOBODY (the user's standing rule: Roles &
-- Permissions are theirs). An administrator passes has_perm() anyway; anyone
-- else is given them on Roles & Permissions -> Indoor Service.
--   recycle.view      see the recycling track
--   recycle.register  register a defective spare, record job done
--   recycle.request   raise an MRS
--   recycle.issue     book the stock out of an MRS, with cost (Stores)
--   recycle.close     consume, add other costs, close a request
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- 1. THE TABLES
-- ---------------------------------------------------------------------------
create table if not exists public.recycle_requests (
  id                    bigint generated always as identity primary key,
  rcy_no                text unique,
  received_on           date not null default ((now() at time zone 'Asia/Kolkata')::date),
  part_code             text not null,
  part_description      text not null default '',
  serial                text not null default '',
  qty                   numeric not null default 1 check (qty > 0),
  received_from         text not null default '',
  call_ref              text not null default '',
  remarks               text not null default '',
  job_done              text not null default '',
  status                text not null default 'Open'
                          check (status in ('Open', 'Returned', 'Not recyclable')),
  returned_part_code    text not null default '',
  returned_qty          numeric check (returned_qty is null or returned_qty > 0),
  returned_on           date,
  not_recyclable_reason text not null default '',
  closed_at             timestamptz,
  closed_by             uuid,
  closed_by_name        text not null default '',
  created_at            timestamptz not null default now(),
  created_by            uuid,
  created_by_name       text not null default '',
  updated_at            timestamptz not null default now()
);

create table if not exists public.recycle_mrs (
  id                  bigint generated always as identity primary key,
  mrs_no              text unique,
  request_id          bigint references public.recycle_requests (id),
  requested_for       uuid,
  requested_for_name  text not null default '',
  remarks             text not null default '',
  created_at          timestamptz not null default now(),
  created_by          uuid
);

create table if not exists public.recycle_mrs_lines (
  id                bigint generated always as identity primary key,
  mrs_id            bigint not null references public.recycle_mrs (id) on delete cascade,
  part_code         text not null,
  part_description  text not null default '',
  qty               numeric not null check (qty > 0),
  created_at        timestamptz not null default now()
);

-- THE STOCK OUT, one row per booking, so a line can be issued in parts.
create table if not exists public.recycle_issues (
  id              bigint generated always as identity primary key,
  mrs_line_id     bigint not null references public.recycle_mrs_lines (id),
  qty             numeric not null check (qty > 0),
  unit_cost       numeric not null check (unit_cost >= 0),
  issued_at       timestamptz not null default now(),
  issued_by       uuid,
  issued_by_name  text not null default ''
);

create table if not exists public.recycle_consumption (
  id           bigint generated always as identity primary key,
  request_id   bigint not null references public.recycle_requests (id),
  holder       uuid,
  holder_name  text not null default '',
  part_code    text not null,
  qty          numeric not null check (qty > 0),
  consumed_at  timestamptz not null default now()
);

create table if not exists public.recycle_other_costs (
  id           bigint generated always as identity primary key,
  request_id   bigint not null references public.recycle_requests (id),
  cost_type    text not null default 'Other' check (cost_type in ('Labour', 'Courier', 'Vendor', 'Other')),
  description  text not null default '',
  amount       numeric not null check (amount >= 0),
  created_at   timestamptz not null default now(),
  created_by   uuid,
  created_by_name text not null default ''
);

create index if not exists recycle_mrs_lines_mrs_idx on public.recycle_mrs_lines (mrs_id);
create index if not exists recycle_issues_line_idx on public.recycle_issues (mrs_line_id);
create index if not exists recycle_consumption_req_idx on public.recycle_consumption (request_id);
create index if not exists recycle_consumption_holder_idx on public.recycle_consumption (holder, part_code);
create index if not exists recycle_other_costs_req_idx on public.recycle_other_costs (request_id);

-- THE FIVE SYSTEM COLUMNS (0244) on each new table now, rather than waiting
-- for sys_columns.sql to be re-run -- the pattern 0332 uses.
do $$
declare t text;
begin
  if to_regprocedure('public.sys_columns_attach(regclass)') is not null then
    foreach t in array array['recycle_requests', 'recycle_mrs', 'recycle_mrs_lines', 'recycle_issues',
                             'recycle_consumption', 'recycle_other_costs'] loop
      perform public.sys_columns_attach(('public.' || t)::regclass);
    end loop;
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- 2. WHO IS SIGNED IN, BY NAME -- the profile's name, else its email.
-- ---------------------------------------------------------------------------
create or replace function public.recycle_me_name()
returns text language sql stable security definer set search_path = public as $$
  select coalesce((select coalesce(nullif(btrim(p.full_name), ''), nullif(btrim(p.email), ''))
                     from public.profiles p where p.id = auth.uid()), coalesce(auth.email(), ''));
$$;
revoke execute on function public.recycle_me_name() from public, anon, authenticated;

-- The next number of a series for this year: PREFIX/YY/0001, restarting each
-- year. Under an advisory lock so two at once cannot take the same number --
-- and no counter table, so nothing here needs the counters' exceptions.
create or replace function public.recycle_next_no(p_prefix text, p_table regclass, p_col text)
returns text language plpgsql security definer set search_path = public as $$
declare
  yy  text := to_char(now() at time zone 'Asia/Kolkata', 'YY');
  n   integer;
begin
  perform pg_advisory_xact_lock(hashtext('recycle_no:' || p_prefix || ':' || yy));
  execute format(
    'select coalesce(max(nullif(split_part(%I, ''/'', 3), '''')::int), 0) from %s where %I like $1',
    p_col, p_table, p_col)
    into n using p_prefix || '/' || yy || '/%';
  return p_prefix || '/' || yy || '/' || lpad((n + 1)::text, 4, '0');
end $$;
revoke execute on function public.recycle_next_no(text, regclass, text) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 3. THE GUARDS -- stamped columns are the database's, and the rules a
--    screen could skip are refused here.
-- ---------------------------------------------------------------------------
create or replace function public.recycle_requests_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    new.rcy_no := public.recycle_next_no('RCY', 'public.recycle_requests', 'rcy_no');
    new.created_by := auth.uid();
    new.created_by_name := public.recycle_me_name();
    new.status := 'Open';
    new.returned_part_code := ''; new.returned_qty := null; new.returned_on := null;
    new.closed_at := null; new.closed_by := null; new.closed_by_name := '';
    new.part_code := btrim(new.part_code);
    if new.part_code = '' then raise exception 'Part code is required.'; end if;
    return new;
  end if;

  -- UPDATE
  new.rcy_no := old.rcy_no; new.created_by := old.created_by;
  new.created_by_name := old.created_by_name; new.created_at := old.created_at;
  new.updated_at := now();
  if old.status <> 'Open' then
    raise exception 'Recycling request % is closed (%) and cannot be changed.', old.rcy_no, old.status;
  end if;
  if new.status = 'Open' then
    new.returned_part_code := ''; new.returned_qty := null; new.returned_on := null;
    new.closed_at := null; new.closed_by := null; new.closed_by_name := '';
    return new;
  end if;

  -- CLOSING
  if not coalesce(public.has_perm('recycle.close'), false) then
    raise exception 'RBAC: closing a recycling request needs "Consume, add costs and close a recycling request"';
  end if;
  if btrim(coalesce(new.job_done, '')) = '' then
    raise exception 'Record the job done before closing %.', old.rcy_no;
  end if;
  new.closed_at := now();
  new.closed_by := auth.uid();
  new.closed_by_name := public.recycle_me_name();
  if new.status = 'Returned' then
    -- RETURNED TO THE SERVICE STORE AS R<PartNo>, recorded here only.
    new.returned_part_code := 'R' || old.part_code;
    new.returned_qty := coalesce(new.returned_qty, old.qty);
    new.returned_on := coalesce(new.returned_on, (now() at time zone 'Asia/Kolkata')::date);
    new.not_recyclable_reason := '';
  else
    if btrim(coalesce(new.not_recyclable_reason, '')) = '' then
      raise exception 'Say why % is not recyclable.', old.rcy_no;
    end if;
    new.returned_part_code := ''; new.returned_qty := null; new.returned_on := null;
  end if;
  return new;
end $$;
revoke execute on function public.recycle_requests_guard() from public, anon, authenticated;
drop trigger if exists recycle_requests_guard on public.recycle_requests;
create trigger recycle_requests_guard before insert or update on public.recycle_requests
  for each row execute function public.recycle_requests_guard();

create or replace function public.recycle_mrs_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    new.mrs_no := public.recycle_next_no('RMRS', 'public.recycle_mrs', 'mrs_no');
    -- THE SPARES GO TO THE HAND STOCK OF WHOEVER RAISED IT.
    new.requested_for := auth.uid();
    new.requested_for_name := public.recycle_me_name();
    new.created_by := auth.uid();
  else
    new.mrs_no := old.mrs_no; new.requested_for := old.requested_for;
    new.requested_for_name := old.requested_for_name; new.created_by := old.created_by;
    new.created_at := old.created_at;
  end if;
  if new.request_id is not null
     and exists (select 1 from public.recycle_requests r where r.id = new.request_id and r.status <> 'Open') then
    raise exception 'That recycling request is closed; raise the MRS against an open one, or none.';
  end if;
  return new;
end $$;
revoke execute on function public.recycle_mrs_guard() from public, anon, authenticated;
drop trigger if exists recycle_mrs_guard on public.recycle_mrs;
create trigger recycle_mrs_guard before insert or update on public.recycle_mrs
  for each row execute function public.recycle_mrs_guard();

-- A LINE CANNOT BE ISSUED BEYOND WHAT IT ASKED FOR, and a line already issued
-- from cannot have its part or quantity changed under the issue.
create or replace function public.recycle_mrs_lines_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.part_code := btrim(new.part_code);
  if new.part_code = '' then raise exception 'Part code is required.'; end if;
  if tg_op = 'UPDATE' and exists (select 1 from public.recycle_issues i where i.mrs_line_id = old.id) then
    if new.part_code <> old.part_code then
      raise exception 'Stock has been issued against this line; its part cannot change.';
    end if;
    if new.qty < (select sum(i.qty) from public.recycle_issues i where i.mrs_line_id = old.id) then
      raise exception 'Stock has been issued against this line; its quantity cannot go below what was issued.';
    end if;
  end if;
  return new;
end $$;
revoke execute on function public.recycle_mrs_lines_guard() from public, anon, authenticated;
drop trigger if exists recycle_mrs_lines_guard on public.recycle_mrs_lines;
create trigger recycle_mrs_lines_guard before insert or update on public.recycle_mrs_lines
  for each row execute function public.recycle_mrs_lines_guard();

create or replace function public.recycle_issues_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  asked   numeric;
  given   numeric;
begin
  if tg_op = 'UPDATE' then
    raise exception 'A stock out is not edited. Book another for the remainder.';
  end if;
  select l.qty into asked from public.recycle_mrs_lines l where l.id = new.mrs_line_id for update;
  if asked is null then raise exception 'No such MRS line.'; end if;
  select coalesce(sum(i.qty), 0) into given from public.recycle_issues i where i.mrs_line_id = new.mrs_line_id;
  if given + new.qty > asked then
    raise exception 'Only % more can be issued against this line (asked %, issued %).', asked - given, asked, given;
  end if;
  new.issued_at := now();
  new.issued_by := auth.uid();
  new.issued_by_name := public.recycle_me_name();
  return new;
end $$;
revoke execute on function public.recycle_issues_guard() from public, anon, authenticated;
drop trigger if exists recycle_issues_guard on public.recycle_issues;
create trigger recycle_issues_guard before insert or update on public.recycle_issues
  for each row execute function public.recycle_issues_guard();

-- ---------------------------------------------------------------------------
-- 4. THE RECYCLING HAND STOCK -- issued to a holder, less what the holder
--    consumed. Derived, never stored, like the regular one; and kept apart
--    from it entirely.
-- ---------------------------------------------------------------------------
create or replace function public.recycle_balance(p_holder uuid, p_part text)
returns numeric language sql stable security definer set search_path = public as $$
  select coalesce((select sum(i.qty)
                     from public.recycle_issues i
                     join public.recycle_mrs_lines l on l.id = i.mrs_line_id
                     join public.recycle_mrs m on m.id = l.mrs_id
                    where m.requested_for = p_holder and l.part_code = p_part), 0)
       - coalesce((select sum(c.qty) from public.recycle_consumption c
                    where c.holder = p_holder and c.part_code = p_part), 0);
$$;
revoke execute on function public.recycle_balance(uuid, text) from public, anon, authenticated;

create or replace function public.recycle_consumption_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  st   text;
  bal  numeric;
begin
  if tg_op = 'UPDATE' then
    raise exception 'A consumption line is not edited. Remove it and enter it again.';
  end if;
  if tg_op = 'DELETE' then
    select r.status into st from public.recycle_requests r where r.id = old.request_id;
    if st <> 'Open' then raise exception 'The request is closed; its consumption stays.'; end if;
    return old;
  end if;
  select r.status into st from public.recycle_requests r where r.id = new.request_id;
  if st is null then raise exception 'No such recycling request.'; end if;
  if st <> 'Open' then raise exception 'The request is closed; nothing more can be consumed on it.'; end if;
  -- FROM THE CONSUMER'S OWN RECYCLING HAND STOCK, and never more than it holds.
  new.holder := auth.uid();
  new.holder_name := public.recycle_me_name();
  new.part_code := btrim(new.part_code);
  perform pg_advisory_xact_lock(hashtext('recycle_bal:' || coalesce(new.holder::text, '') || ':' || new.part_code));
  bal := public.recycle_balance(new.holder, new.part_code);
  if new.qty > bal then
    raise exception 'Your recycling hand stock of % is %; % cannot be consumed.', new.part_code, bal, new.qty;
  end if;
  new.consumed_at := now();
  return new;
end $$;
revoke execute on function public.recycle_consumption_guard() from public, anon, authenticated;
drop trigger if exists recycle_consumption_guard on public.recycle_consumption;
create trigger recycle_consumption_guard before insert or update or delete on public.recycle_consumption
  for each row execute function public.recycle_consumption_guard();

create or replace function public.recycle_other_costs_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  st text;
begin
  select r.status into st from public.recycle_requests r
   where r.id = case when tg_op = 'DELETE' then old.request_id else new.request_id end;
  if st is distinct from 'Open' then raise exception 'The request is closed; its costs stay as they are.'; end if;
  if tg_op = 'DELETE' then return old; end if;
  if tg_op = 'INSERT' then
    new.created_by := auth.uid();
    new.created_by_name := public.recycle_me_name();
    new.created_at := now();
  else
    new.request_id := old.request_id; new.created_by := old.created_by;
    new.created_by_name := old.created_by_name; new.created_at := old.created_at;
  end if;
  return new;
end $$;
revoke execute on function public.recycle_other_costs_guard() from public, anon, authenticated;
drop trigger if exists recycle_other_costs_guard on public.recycle_other_costs;
create trigger recycle_other_costs_guard before insert or update or delete on public.recycle_other_costs
  for each row execute function public.recycle_other_costs_guard();

-- ---------------------------------------------------------------------------
-- 5. ROW-LEVEL SECURITY -- the keys, and NOT IN AUDIT MODE.
-- ---------------------------------------------------------------------------
create or replace function public.recycle_may_see()
returns boolean language sql stable security definer set search_path = public as $$
  select not coalesce(public.audit_mode(), false)
     and (coalesce(public.has_perm('recycle.view'), false)
       or coalesce(public.has_perm('recycle.register'), false)
       or coalesce(public.has_perm('recycle.request'), false)
       or coalesce(public.has_perm('recycle.issue'), false)
       or coalesce(public.has_perm('recycle.close'), false));
$$;
revoke execute on function public.recycle_may_see() from public, anon;
grant execute on function public.recycle_may_see() to authenticated;

create or replace function public.recycle_may(p_key text)
returns boolean language sql stable security definer set search_path = public as $$
  select not coalesce(public.audit_mode(), false) and coalesce(public.has_perm(p_key), false);
$$;
revoke execute on function public.recycle_may(text) from public, anon;
grant execute on function public.recycle_may(text) to authenticated;

alter table public.recycle_requests    enable row level security;
alter table public.recycle_mrs         enable row level security;
alter table public.recycle_mrs_lines   enable row level security;
alter table public.recycle_issues      enable row level security;
alter table public.recycle_consumption enable row level security;
alter table public.recycle_other_costs enable row level security;

drop policy if exists rr_read on public.recycle_requests;
create policy rr_read on public.recycle_requests for select using ((select public.recycle_may_see()));
drop policy if exists rr_insert on public.recycle_requests;
create policy rr_insert on public.recycle_requests for insert with check ((select public.recycle_may('recycle.register')));
drop policy if exists rr_update on public.recycle_requests;
create policy rr_update on public.recycle_requests for update
  using ((select public.recycle_may('recycle.register')) or (select public.recycle_may('recycle.close')))
  with check ((select public.recycle_may('recycle.register')) or (select public.recycle_may('recycle.close')));

drop policy if exists rm_read on public.recycle_mrs;
create policy rm_read on public.recycle_mrs for select using ((select public.recycle_may_see()));
drop policy if exists rm_insert on public.recycle_mrs;
create policy rm_insert on public.recycle_mrs for insert with check ((select public.recycle_may('recycle.request')));

drop policy if exists rml_read on public.recycle_mrs_lines;
create policy rml_read on public.recycle_mrs_lines for select using ((select public.recycle_may_see()));
drop policy if exists rml_insert on public.recycle_mrs_lines;
create policy rml_insert on public.recycle_mrs_lines for insert with check ((select public.recycle_may('recycle.request')));

drop policy if exists ri_read on public.recycle_issues;
create policy ri_read on public.recycle_issues for select using ((select public.recycle_may_see()));
drop policy if exists ri_insert on public.recycle_issues;
create policy ri_insert on public.recycle_issues for insert with check ((select public.recycle_may('recycle.issue')));

drop policy if exists rc_read on public.recycle_consumption;
create policy rc_read on public.recycle_consumption for select using ((select public.recycle_may_see()));
drop policy if exists rc_insert on public.recycle_consumption;
create policy rc_insert on public.recycle_consumption for insert with check ((select public.recycle_may('recycle.close')));
drop policy if exists rc_delete on public.recycle_consumption;
create policy rc_delete on public.recycle_consumption for delete using ((select public.recycle_may('recycle.close')));

drop policy if exists roc_read on public.recycle_other_costs;
create policy roc_read on public.recycle_other_costs for select using ((select public.recycle_may_see()));
drop policy if exists roc_insert on public.recycle_other_costs;
create policy roc_insert on public.recycle_other_costs for insert with check ((select public.recycle_may('recycle.close')));
drop policy if exists roc_delete on public.recycle_other_costs;
create policy roc_delete on public.recycle_other_costs for delete using ((select public.recycle_may('recycle.close')));

grant select, insert, update on public.recycle_requests to authenticated;
grant select, insert on public.recycle_mrs, public.recycle_mrs_lines, public.recycle_issues to authenticated;
grant select, insert, delete on public.recycle_consumption, public.recycle_other_costs to authenticated;
revoke all on public.recycle_requests, public.recycle_mrs, public.recycle_mrs_lines, public.recycle_issues,
              public.recycle_consumption, public.recycle_other_costs from anon;

-- ---------------------------------------------------------------------------
-- 6. THE VIEWS THE SCREEN READS (security_invoker: the policies above apply).
-- ---------------------------------------------------------------------------

-- An MRS line with what has been issued against it, and at what cost.
create or replace view public.recycle_mrs_list as
select l.id as line_id, m.id as mrs_id, m.mrs_no, m.request_id, r.rcy_no,
       m.requested_for, m.requested_for_name, m.remarks, m.created_at,
       l.part_code, l.part_description, l.qty as qty_requested,
       coalesce(i.qty_issued, 0) as qty_issued,
       l.qty - coalesce(i.qty_issued, 0) as qty_pending,
       coalesce(i.cost_issued, 0) as cost_issued,
       i.last_issued_at,
       case when coalesce(i.qty_issued, 0) = 0 then 'Pending'
            when i.qty_issued < l.qty then 'Partly issued'
            else 'Issued' end as status
  from public.recycle_mrs_lines l
  join public.recycle_mrs m on m.id = l.mrs_id
  left join public.recycle_requests r on r.id = m.request_id
  left join lateral (
    select sum(x.qty) as qty_issued, sum(x.qty * x.unit_cost) as cost_issued, max(x.issued_at) as last_issued_at
      from public.recycle_issues x where x.mrs_line_id = l.id
  ) i on true;
alter view public.recycle_mrs_list set (security_invoker = on);
grant select on public.recycle_mrs_list to authenticated;

-- THE RECYCLING HAND STOCK, per holder and part, with the average stock-out
-- cost -- what a consumed unit is valued at.
create or replace view public.recycle_hand_stock as
with iss as (
  select m.requested_for as holder, max(m.requested_for_name) as holder_name, l.part_code,
         max(l.part_description) as part_description,
         sum(i.qty) as issued, sum(i.qty * i.unit_cost) as issued_cost
    from public.recycle_issues i
    join public.recycle_mrs_lines l on l.id = i.mrs_line_id
    join public.recycle_mrs m on m.id = l.mrs_id
   group by m.requested_for, l.part_code
), con as (
  select c.holder, c.part_code, sum(c.qty) as consumed
    from public.recycle_consumption c group by c.holder, c.part_code
)
select iss.holder, iss.holder_name, iss.part_code, iss.part_description,
       iss.issued, coalesce(con.consumed, 0) as consumed,
       iss.issued - coalesce(con.consumed, 0) as balance,
       case when iss.issued > 0 then round(iss.issued_cost / iss.issued, 4) end as avg_unit_cost
  from iss left join con on con.holder = iss.holder and con.part_code = iss.part_code;
alter view public.recycle_hand_stock set (security_invoker = on);
grant select on public.recycle_hand_stock to authenticated;

-- A consumption line with its value: the holder's average stock-out cost for
-- that part.
create or replace view public.recycle_consumption_list as
select c.id, c.request_id, r.rcy_no, c.holder, c.holder_name, c.part_code, c.qty, c.consumed_at,
       h.avg_unit_cost, round(c.qty * coalesce(h.avg_unit_cost, 0), 2) as value
  from public.recycle_consumption c
  join public.recycle_requests r on r.id = c.request_id
  left join public.recycle_hand_stock h on h.holder = c.holder and h.part_code = c.part_code;
alter view public.recycle_consumption_list set (security_invoker = on);
grant select on public.recycle_consumption_list to authenticated;

-- THE REQUEST WITH WHAT IT COST: parts consumed + other costs. The cost of
-- stock ISSUED on its MRSs is shown beside it, because issued is not used.
-- Columns NAMED, never r.*: `*` is expanded at creation, and the system
-- columns 0244 adds later would make a replay of this bundle a different view.
-- DROPPED FIRST: 0365 appends columns to this view, so a replay of this
-- bundle would otherwise try to remove them ("cannot drop columns from
-- view"). Nothing is built on it.
drop view if exists public.recycle_request_list;
create view public.recycle_request_list as
select r.id, r.rcy_no, r.received_on, r.part_code, r.part_description, r.serial, r.qty,
       r.received_from, r.call_ref, r.remarks, r.job_done, r.status,
       r.returned_part_code, r.returned_qty, r.returned_on, r.not_recyclable_reason,
       r.closed_at, r.closed_by, r.closed_by_name, r.created_at, r.created_by, r.created_by_name,
       r.updated_at,
       coalesce(pc.parts_cost, 0) as parts_cost,
       coalesce(oc.other_cost, 0) as other_cost,
       coalesce(pc.parts_cost, 0) + coalesce(oc.other_cost, 0) as total_cost,
       coalesce(ic.issued_cost, 0) as issued_cost
  from public.recycle_requests r
  left join lateral (select sum(v.value) as parts_cost from public.recycle_consumption_list v where v.request_id = r.id) pc on true
  left join lateral (select sum(o.amount) as other_cost from public.recycle_other_costs o where o.request_id = r.id) oc on true
  left join lateral (select sum(x.cost_issued) as issued_cost from public.recycle_mrs_list x where x.request_id = r.id) ic on true;
alter view public.recycle_request_list set (security_invoker = on);
grant select on public.recycle_request_list to authenticated;

-- ---------------------------------------------------------------------------
-- 7. THE SCREEN'S KEY, IN THE ADMIN AND TECHNICAL SUPPORT ROLES ONLY (the
--    0241 pattern). An administrator passes every check anyway; Technical
--    Support holds every screen key the admin does (0145, _status.sql row
--    114) -- and the key only OPENS the page: every row needs a recycle.* key,
--    which no role is given, so it sees an empty page. Every other role is
--    given access -- or not -- on Roles & Permissions (the user's rule).
-- ---------------------------------------------------------------------------
do $$
declare n integer;
begin
  if to_regclass('public.app_roles') is null then return; end if;
  update public.app_roles ar
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (select jsonb_array_elements_text(ar.permissions) as v
                   union select unnest(array['mod:/indoor/recycling']) as v) u),
         updated_at = now()
   where jsonb_array_length(ar.permissions) > 0
     and ar.role in ('admin', 'technical_support')
     and not (ar.permissions ? 'mod:/indoor/recycling');
  get diagnostics n = row_count;
  raise notice '0355: Spare Recycling screen key given to admin + technical_support (% of 2 rows) -- grant the rest on Roles & Permissions', n;
end $$;

-- ------------------------------------------------------------------------
-- 0365_spare_recycling_start_sla_mrn.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0365 — SPARE RECYCLING: START WORK AND ITS SLA, ONE REQUEST PER SPARE, AND
--        IMPORT FROM MRN.
--
-- The user, 2026-10-04:
--   * "I should be able to Track my Work in Spare Recycling, I need Provision
--     to Mark - Start Work - With Date & Time. SLA starts only when i click on
--     Start Work. SLA is 3 Working Days. Saturday, Sunday Holiday, But make it
--     configurable through SLA Page."
--   * "If Qty is more than 1, it should get created as Separate requests."
--   * "I should have the Provision to Import spares from MRN as well." --
--     both the good and the defective quantity, and a line may be imported
--     any number of times (no link is kept; the MRN No is recorded as text).
--
-- STILL A PARALLEL TRACK, STILL NON-AUDITABLE: everything below refuses while
-- Audit Mode is on, and the MRN read is READ-ONLY on material_returns.
-- ===========================================================================

alter table public.recycle_requests add column if not exists work_started_at      timestamptz;
alter table public.recycle_requests add column if not exists work_started_by      uuid;
alter table public.recycle_requests add column if not exists work_started_by_name text not null default '';
alter table public.recycle_requests add column if not exists mrn_ref              text not null default '';

-- ---------------------------------------------------------------------------
-- 1. THE SLA SETTINGS -- the recycling track's OWN, kept apart from the call
--    SLA rules so they can never change how a call is judged. In app_settings,
--    changed only through set_recycle_sla() and read through
--    recycle_sla_settings().
--      recycle_sla_working_days  how many working days from Start Work (3)
--      recycle_sla_weekend_days  the days that are not working days, as
--                                day-of-week numbers, 0 = Sunday .. 6 = Saturday
--                                ('0,6' = Saturday and Sunday)
-- ---------------------------------------------------------------------------
do $$
begin
  if to_regclass('public.app_settings') is not null then
    insert into public.app_settings (key, value) values
      ('recycle_sla_working_days', '3'),
      ('recycle_sla_weekend_days', '0,6')
    on conflict (key) do nothing;
  end if;
end $$;

create or replace function public.recycle_sla_settings()
returns table (working_days integer, weekend_days integer[])
language sql stable security definer set search_path = public as $$
  select coalesce((select nullif(btrim(value), '')::int from public.app_settings where key = 'recycle_sla_working_days'), 3),
         coalesce((select array(select nullif(btrim(x), '')::int
                                  from unnest(string_to_array(value, ',')) x where btrim(x) <> '')
                     from public.app_settings where key = 'recycle_sla_weekend_days'), array[0, 6]);
$$;
revoke execute on function public.recycle_sla_settings() from public, anon;
grant execute on function public.recycle_sla_settings() to authenticated;

create or replace function public.set_recycle_sla(p_working_days integer, p_weekend_days integer[])
returns void language plpgsql security definer set search_path = public as $$
begin
  if coalesce(public.audit_mode(), false) then
    raise exception 'Spare Recycling is not available while Audit Mode is on.';
  end if;
  if not (coalesce(public.is_admin(), false) or coalesce(public.has_perm('config.manage'), false)) then
    raise exception 'RBAC: changing the SLA needs "Admin config"';
  end if;
  if p_working_days is null or p_working_days < 1 or p_working_days > 60 then
    raise exception 'The SLA must be between 1 and 60 working days.';
  end if;
  if exists (select 1 from unnest(coalesce(p_weekend_days, '{}')) d where d < 0 or d > 6) then
    raise exception 'Holidays are days of the week, 0 (Sunday) to 6 (Saturday).';
  end if;
  if coalesce(array_length(p_weekend_days, 1), 0) >= 7 then
    raise exception 'At least one day of the week must be a working day.';
  end if;
  insert into public.app_settings (key, value) values
    ('recycle_sla_working_days', p_working_days::text),
    ('recycle_sla_weekend_days', coalesce(array_to_string(
       array(select distinct d from unnest(p_weekend_days) d order by d), ','), ''))
  on conflict (key) do update set value = excluded.value, updated_at = now();
end $$;
revoke execute on function public.set_recycle_sla(integer, integer[]) from public, anon;
grant execute on function public.set_recycle_sla(integer, integer[]) to authenticated;

-- WHEN THE SLA FALLS DUE: the start plus N working days, the clock time kept,
-- skipping every day of the week marked as a holiday -- counted in India time,
-- because "a working day" is a day in Chennai, not in UTC.
create or replace function public.recycle_sla_due(p_start timestamptz)
returns timestamptz language plpgsql stable security definer set search_path = public as $$
declare
  s     record;
  d     timestamp;
  n     integer := 0;
  guard integer := 0;
begin
  if p_start is null then return null; end if;
  select * into s from public.recycle_sla_settings();
  d := p_start at time zone 'Asia/Kolkata';
  while n < s.working_days and guard < 400 loop
    d := d + interval '1 day';
    guard := guard + 1;
    if not (extract(dow from d)::int = any (coalesce(s.weekend_days, '{}'))) then
      n := n + 1;
    end if;
  end loop;
  return d at time zone 'Asia/Kolkata';
end $$;
revoke execute on function public.recycle_sla_due(timestamptz) from public, anon;
grant execute on function public.recycle_sla_due(timestamptz) to authenticated;

-- ---------------------------------------------------------------------------
-- 2. START WORK -- once, on an open request, at a time not in the future.
--    The only way the work_started_* columns are written: the guard keeps the
--    old values on every other update.
-- ---------------------------------------------------------------------------
-- SECURITY DEFINER, because it stamps the starter's name (recycle_me_name(),
-- closed to the API); the key and Audit Mode are asked first, below.
create or replace function public.start_recycle_work(p_id bigint, p_at timestamptz)
returns timestamptz language plpgsql security definer set search_path = public as $$
declare
  r public.recycle_requests;
  t timestamptz := coalesce(p_at, now());
begin
  if not coalesce(public.recycle_may('recycle.close'), false)
     and not coalesce(public.recycle_may('recycle.register'), false) then
    raise exception 'RBAC: starting work on a recycling request needs "Consume, add costs and close" or "Register"';
  end if;
  select * into r from public.recycle_requests where id = p_id;
  if not found then raise exception 'No such recycling request.'; end if;
  if r.status <> 'Open' then raise exception '% is closed.', r.rcy_no; end if;
  if r.work_started_at is not null then
    raise exception 'Work on % was already started on %.', r.rcy_no,
      to_char(r.work_started_at at time zone 'Asia/Kolkata', 'DD-Mon-YYYY HH24:MI');
  end if;
  if t > now() + interval '5 minutes' then raise exception 'Start Work cannot be in the future.'; end if;
  if t < r.created_at - interval '1 minute' then
    raise exception 'Start Work cannot be before % was registered.', r.rcy_no;
  end if;
  perform set_config('rithi.recycle_start', 'on', true);
  update public.recycle_requests
     set work_started_at = t, work_started_by = auth.uid(), work_started_by_name = public.recycle_me_name()
   where id = p_id;
  perform set_config('rithi.recycle_start', '', true);
  return t;
end $$;
revoke execute on function public.start_recycle_work(bigint, timestamptz) from public, anon;
grant execute on function public.start_recycle_work(bigint, timestamptz) to authenticated;

-- The guard, re-stated whole from 0355 with three additions: the Start Work
-- columns are written only by start_recycle_work(); a NEW request is ONE
-- spare (qty 1); and mrn_ref is kept as typed.
create or replace function public.recycle_requests_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    new.rcy_no := public.recycle_next_no('RCY', 'public.recycle_requests', 'rcy_no');
    new.created_by := auth.uid();
    new.created_by_name := public.recycle_me_name();
    new.status := 'Open';
    new.returned_part_code := ''; new.returned_qty := null; new.returned_on := null;
    new.closed_at := null; new.closed_by := null; new.closed_by_name := '';
    new.work_started_at := null; new.work_started_by := null; new.work_started_by_name := '';
    new.part_code := btrim(new.part_code);
    if new.part_code = '' then raise exception 'Part code is required.'; end if;
    -- ONE REQUEST PER SPARE (the user, 2026-10-04): register_recycle_requests()
    -- makes N requests for a quantity of N.
    if new.qty <> 1 then
      raise exception 'A recycling request is one spare. Register a quantity of % as % requests.', new.qty, new.qty;
    end if;
    return new;
  end if;

  -- UPDATE
  new.rcy_no := old.rcy_no; new.created_by := old.created_by;
  new.created_by_name := old.created_by_name; new.created_at := old.created_at;
  new.updated_at := now();
  if coalesce(current_setting('rithi.recycle_start', true), '') <> 'on' then
    new.work_started_at := old.work_started_at; new.work_started_by := old.work_started_by;
    new.work_started_by_name := old.work_started_by_name;
  end if;
  if old.status <> 'Open' then
    raise exception 'Recycling request % is closed (%) and cannot be changed.', old.rcy_no, old.status;
  end if;
  if new.status = 'Open' then
    new.returned_part_code := ''; new.returned_qty := null; new.returned_on := null;
    new.closed_at := null; new.closed_by := null; new.closed_by_name := '';
    return new;
  end if;

  -- CLOSING
  if not coalesce(public.has_perm('recycle.close'), false) then
    raise exception 'RBAC: closing a recycling request needs "Consume, add costs and close a recycling request"';
  end if;
  if btrim(coalesce(new.job_done, '')) = '' then
    raise exception 'Record the job done before closing %.', old.rcy_no;
  end if;
  new.closed_at := now();
  new.closed_by := auth.uid();
  new.closed_by_name := public.recycle_me_name();
  if new.status = 'Returned' then
    new.returned_part_code := 'R' || old.part_code;
    new.returned_qty := coalesce(new.returned_qty, old.qty);
    new.returned_on := coalesce(new.returned_on, (now() at time zone 'Asia/Kolkata')::date);
    new.not_recyclable_reason := '';
  else
    if btrim(coalesce(new.not_recyclable_reason, '')) = '' then
      raise exception 'Say why % is not recyclable.', old.rcy_no;
    end if;
    new.returned_part_code := ''; new.returned_qty := null; new.returned_on := null;
  end if;
  return new;
end $$;
revoke execute on function public.recycle_requests_guard() from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 3. REGISTER N SPARES AS N REQUESTS, in one transaction: all numbered, or
--    none. Runs as the CALLER, so the insert policy (recycle.register, not in
--    Audit Mode) decides.
-- ---------------------------------------------------------------------------
create or replace function public.register_recycle_requests(
  p_part_code text, p_part_description text, p_serial text, p_qty integer,
  p_received_on date, p_received_from text, p_call_ref text, p_remarks text, p_mrn_ref text default '')
returns text[] language plpgsql security invoker set search_path = public as $$
declare
  nos text[] := '{}';
  no  text;
  i   integer;
begin
  if p_qty is null or p_qty < 1 then raise exception 'Quantity must be at least 1.'; end if;
  if p_qty > 200 then raise exception 'Register at most 200 spares at a time.'; end if;
  -- A serial belongs to ONE spare: with more than one, each request gets its
  -- own serial afterwards.
  if p_qty > 1 and btrim(coalesce(p_serial, '')) <> '' then
    raise exception 'A serial belongs to one spare. Leave it blank for a quantity of %, and enter each serial on its own request.', p_qty;
  end if;
  for i in 1..p_qty loop
    insert into public.recycle_requests
      (part_code, part_description, serial, qty, received_on, received_from, call_ref, remarks, mrn_ref)
    values (p_part_code, coalesce(p_part_description, ''), coalesce(p_serial, ''), 1,
            coalesce(p_received_on, (now() at time zone 'Asia/Kolkata')::date),
            coalesce(p_received_from, ''), coalesce(p_call_ref, ''), coalesce(p_remarks, ''), coalesce(p_mrn_ref, ''))
    returning rcy_no into no;
    nos := nos || no;
  end loop;
  return nos;
end $$;
revoke execute on function public.register_recycle_requests(text, text, text, integer, date, text, text, text, text) from public, anon;
grant execute on function public.register_recycle_requests(text, text, text, integer, date, text, text, text, text) to authenticated;

-- ---------------------------------------------------------------------------
-- 4. THE MRN LINES TO IMPORT FROM -- READ-ONLY on the regular material_returns,
--    every line with a good or defective quantity, for a holder of
--    recycle.register while Audit Mode is off. A definer function, because
--    material_returns' own read policy narrows a non-office reader to their
--    own and their team's returns, and the recycling user imports from all of
--    them. Nothing here writes to material_returns.
-- ---------------------------------------------------------------------------
create or replace function public.recycle_mrn_lines(p_search text default '', p_limit integer default 300)
returns table (id bigint, mrn_no text, mrn_date date, engineer text, item_code text, item_name text,
               part text, good_qty numeric, defective_qty numeric, customer_name text, report_no text,
               removed_from_equipment text, remarks text)
language plpgsql stable security definer set search_path = public as $$
declare
  q text := lower(btrim(coalesce(p_search, '')));
begin
  if not coalesce(public.recycle_may('recycle.register'), false) then
    raise exception 'RBAC: importing from MRN needs "Register a defective spare for recycling" (and Audit Mode off)';
  end if;
  return query
    select m.id, m.mrn_no, m.mrn_date, m.engineer, m.item_code, m.item_name, m.part,
           coalesce(m.good_qty, 0), coalesce(m.defective_qty, 0), m.customer_name, m.report_no,
           m.removed_from_equipment, m.remarks
      from public.material_returns m
     where (coalesce(m.good_qty, 0) > 0 or coalesce(m.defective_qty, 0) > 0)
       and (q = '' or lower(concat_ws(' ', m.mrn_no, m.engineer, m.item_code, m.item_name, m.part, m.customer_name)) like '%' || q || '%')
     order by m.mrn_date desc nulls last, m.id desc
     limit greatest(1, least(coalesce(p_limit, 300), 1000));
end $$;
revoke execute on function public.recycle_mrn_lines(text, integer) from public, anon;
grant execute on function public.recycle_mrn_lines(text, integer) to authenticated;

-- ---------------------------------------------------------------------------
-- 5. THE REQUEST LIST, WITH THE SLA. Re-created with its columns NAMED; the
--    new ones at the END (create or replace can only append).
-- ---------------------------------------------------------------------------
create or replace view public.recycle_request_list as
select r.id, r.rcy_no, r.received_on, r.part_code, r.part_description, r.serial, r.qty,
       r.received_from, r.call_ref, r.remarks, r.job_done, r.status,
       r.returned_part_code, r.returned_qty, r.returned_on, r.not_recyclable_reason,
       r.closed_at, r.closed_by, r.closed_by_name, r.created_at, r.created_by, r.created_by_name,
       r.updated_at,
       coalesce(pc.parts_cost, 0) as parts_cost,
       coalesce(oc.other_cost, 0) as other_cost,
       coalesce(pc.parts_cost, 0) + coalesce(oc.other_cost, 0) as total_cost,
       coalesce(ic.issued_cost, 0) as issued_cost,
       -- ---- 0365 ------------------------------------------------------------
       r.work_started_at, r.work_started_by_name, r.mrn_ref,
       sla.due_at as sla_due_at,
       case
         when r.work_started_at is null then 'Not started'
         when r.status <> 'Open' then case when r.closed_at <= sla.due_at then 'Met' else 'Breached' end
         when now() > sla.due_at then 'Breached'
         when (now() at time zone 'Asia/Kolkata')::date = (sla.due_at at time zone 'Asia/Kolkata')::date then 'Due today'
         else 'On track'
       end as sla_status
  from public.recycle_requests r
  left join lateral (select sum(v.value) as parts_cost from public.recycle_consumption_list v where v.request_id = r.id) pc on true
  left join lateral (select sum(o.amount) as other_cost from public.recycle_other_costs o where o.request_id = r.id) oc on true
  left join lateral (select sum(x.cost_issued) as issued_cost from public.recycle_mrs_list x where x.request_id = r.id) ic on true
  left join lateral (select public.recycle_sla_due(r.work_started_at) as due_at) sla on true;
alter view public.recycle_request_list set (security_invoker = on);
grant select on public.recycle_request_list to authenticated;

-- ------------------------------------------------------------------------
-- 0376_spare_recycling_delete.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0376 — SPARE RECYCLING: DELETE A REQUEST.
--
-- The user, 2026-10-04: "Add Delete Option" (on the Spare Recycling list).
-- delete_recycle_requests() removes one or many requests, open or closed,
-- with the consumption booked on them (those parts go back to the recycling
-- hand stock, which is derived) and their other costs; an MRS raised for one
-- stays, unlinked. Its own key, recycle.delete, granted to NO role (an
-- administrator passes); refused, like the whole track, in Audit Mode.
-- Non-auditable (NAR-008), so a deletion is a deletion -- it is logged to the
-- audit log by the screen, not kept as a voided row.
-- ===========================================================================

-- The two guards, re-stated from the database's definitions (0355's), each
-- stepping aside for the delete function only.
CREATE OR REPLACE FUNCTION public.recycle_consumption_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  st   text;
  bal  numeric;
begin
  if tg_op = 'UPDATE' then
    raise exception 'A consumption line is not edited. Remove it and enter it again.';
  end if;
  if tg_op = 'DELETE' then
    -- 0376: delete_recycle_requests() removes a request's consumption with it.
    if coalesce(current_setting('rithi.recycle_delete', true), '') = 'on' then return old; end if;
    select r.status into st from public.recycle_requests r where r.id = old.request_id;
    if st <> 'Open' then raise exception 'The request is closed; its consumption stays.'; end if;
    return old;
  end if;
  select r.status into st from public.recycle_requests r where r.id = new.request_id;
  if st is null then raise exception 'No such recycling request.'; end if;
  if st <> 'Open' then raise exception 'The request is closed; nothing more can be consumed on it.'; end if;
  -- FROM THE CONSUMER'S OWN RECYCLING HAND STOCK, and never more than it holds.
  new.holder := auth.uid();
  new.holder_name := public.recycle_me_name();
  new.part_code := btrim(new.part_code);
  perform pg_advisory_xact_lock(hashtext('recycle_bal:' || coalesce(new.holder::text, '') || ':' || new.part_code));
  bal := public.recycle_balance(new.holder, new.part_code);
  if new.qty > bal then
    raise exception 'Your recycling hand stock of % is %; % cannot be consumed.', new.part_code, bal, new.qty;
  end if;
  new.consumed_at := now();
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.recycle_other_costs_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  st text;
begin
  select r.status into st from public.recycle_requests r
   where r.id = case when tg_op = 'DELETE' then old.request_id else new.request_id end;
  -- 0376: delete_recycle_requests() removes a request's costs with it.
  if tg_op = 'DELETE' and coalesce(current_setting('rithi.recycle_delete', true), '') = 'on' then return old; end if;
  if st is distinct from 'Open' then raise exception 'The request is closed; its costs stay as they are.'; end if;
  if tg_op = 'DELETE' then return old; end if;
  if tg_op = 'INSERT' then
    new.created_by := auth.uid();
    new.created_by_name := public.recycle_me_name();
    new.created_at := now();
  else
    new.request_id := old.request_id; new.created_by := old.created_by;
    new.created_by_name := old.created_by_name; new.created_at := old.created_at;
  end if;
  return new;
end $function$;

create or replace function public.delete_recycle_requests(p_ids bigint[])
returns integer language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  if not coalesce(public.recycle_may('recycle.delete'), false) then
    raise exception 'RBAC: deleting a recycling request needs "Delete a recycling request" (and Audit Mode off)';
  end if;
  if p_ids is null or array_length(p_ids, 1) is null then return 0; end if;
  perform set_config('rithi.recycle_delete', 'on', true);
  delete from public.recycle_consumption where request_id = any (p_ids);
  delete from public.recycle_other_costs where request_id = any (p_ids);
  update public.recycle_mrs set request_id = null where request_id = any (p_ids);
  delete from public.recycle_requests where id = any (p_ids);
  get diagnostics n = row_count;
  perform set_config('rithi.recycle_delete', '', true);
  return n;
end $$;
revoke execute on function public.delete_recycle_requests(bigint[]) from public, anon;
grant execute on function public.delete_recycle_requests(bigint[]) to authenticated;

-- ------------------------------------------------------------------------
-- 0379_recycle_mrn_source.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0379  A SPARE IMPORTED FROM AN MRN HAS THE SOURCE "Defective Spare"
--       (2026-10-05).
--
-- 0376's screen made Source a pick of Service Return / Defective Spare, while
-- an MRN import went on writing "MRN <no> · <engineer>". The user, asked which
-- it should be: "DEFECTIVE SPARE". The screen now sends it; this puts the
-- requests already imported in step. The MRN No stays on each in mrn_ref, so
-- nothing is lost.
--
-- A CLOSED request is otherwise unchangeable, so the ONE guard that refuses it
-- is lifted by name for this statement and put straight back.
-- ===========================================================================
do $$
declare n integer;
begin
  if to_regclass('public.recycle_requests') is null then return; end if;
  alter table public.recycle_requests disable trigger recycle_requests_guard;
  update public.recycle_requests
     set received_from = 'Defective Spare'
   where coalesce(mrn_ref, '') <> ''
     and received_from is distinct from 'Defective Spare';
  get diagnostics n = row_count;
  alter table public.recycle_requests enable trigger recycle_requests_guard;
  raise notice '0379: % request(s) imported from an MRN now read Source "Defective Spare"', n;
end $$;

-- ------------------------------------------------------------------------
-- 0021_master_lists.sql
-- ------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 0021 — Master value lists as their own maintained tables.
--
-- Each master ("200 All Masters" in the workbook: Call Type, Standard
-- Complaint, Call Pending Reason, Call Cancel Reason, Feedback, Spare Approval
-- Reason) becomes a list that admins add to and remove from in the app. The
-- rows still live in `masters` — one store the dropdown reader already knows —
-- and `master_lists` is the registry that gives each list its own table: its
-- label, what one row is called, and any extra columns that list carries
-- (Spare Approval Reason has Stage + Status, kept in `masters.extra`).
--
-- Writes are already gated by masters.edit (0008_rbac_enforcement.sql).
-- ---------------------------------------------------------------------------

-- Provenance columns, as the workbook carries them.
alter table public.masters add column if not exists added_on date;
alter table public.masters add column if not exists added_by text default '';

-- Standard Complaint arrived under two names; settle on `complaint`
-- (listMaster() already reads them as one) so the list has a single table.
update public.masters set name = 'complaint' where name = 'standardComplaint';

-- One row per value per list — a re-seed or a double-tap on Add is a no-op.
-- The Stage discriminator keeps the same reason on two approval stages.
delete from public.masters a
 using public.masters b
 where a.name = b.name
   and a.value = b.value
   and coalesce(a.extra->>'stage','') = coalesce(b.extra->>'stage','')
   and a.id > b.id;
create unique index if not exists masters_name_value_idx
  on public.masters (name, value, (coalesce(extra->>'stage','')));

-- The registry: which lists exist, and what a row of each looks like.
create table if not exists public.master_lists (
  key         text primary key,
  label       text not null,
  value_label text not null default 'Value',
  -- [{ "key": "stage", "label": "Stage" }, ...] — extra columns in masters.extra
  columns     jsonb not null default '[]',
  sort_order  int  not null default 100,
  active      boolean not null default true,
  updated_at  timestamptz not null default now()
);
alter table public.master_lists enable row level security;
drop policy if exists master_lists_read on public.master_lists;
create policy master_lists_read on public.master_lists for select
  using (auth.role() = 'authenticated');
drop policy if exists master_lists_write on public.master_lists;
create policy master_lists_write on public.master_lists for all
  using (public.has_perm('masters.edit')) with check (public.has_perm('masters.edit'));

insert into public.master_lists (key, label, value_label, columns, sort_order) values
  ('calltype', 'Call Type', 'Call Type', '[]'::jsonb, 10),
  ('complaint', 'Standard Complaint', 'Complaint Name', '[]'::jsonb, 20),
  ('pendingreason', 'Call Pending Reason', 'Reason', '[]'::jsonb, 30),
  ('cancelreason', 'Call Cancel Reason', 'Reason', '[]'::jsonb, 40),
  ('feedbackrating', 'Feedback Rating', 'Rating', '[]'::jsonb, 50),
  ('orapproval', 'Spare Approval Reason', 'Reason', '[{"key": "stage", "label": "Stage"}, {"key": "status", "label": "Status"}]'::jsonb, 60)
on conflict (key) do update set
  label = excluded.label, value_label = excluded.value_label,
  columns = excluded.columns, sort_order = excluded.sort_order, updated_at = now();

