-- ------------------------------------------------------------------------
-- 0066_master_values_active.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Master value lists gain an ACTIVE flag, as the part catalogue already has.
--
-- A value that is no longer used cannot simply be deleted: it is already on
-- calls, reports and spare requests, and removing it would leave those records
-- referring to something that no longer exists. Deactivating keeps the history
-- and takes the value out of the pickers — the same rule the parts catalogue
-- follows, and the same rule the rest of this system follows for records that
-- matter.
-- ===========================================================================

alter table public.masters
  add column if not exists active boolean not null default true;

create index if not exists masters_active_idx on public.masters (name, active);

-- ------------------------------------------------------------------------
-- 0067_master_list_permissions.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Master value lists — permission per list, not one switch for all of them.
--
-- 0008 put every master write behind a single global `masters.edit`: whoever
-- could maintain Call Type could also maintain Cancel Reason, Feedback and
-- every list added since. Roles & Permissions now lists each master as its own
-- page, so the database has to honour the same granularity:
--
--   master.<list>.edit     add / change values in that one list
--   master.<list>.delete   remove a value from that one list
--
-- `masters.edit` still grants both on every list, so no existing role loses
-- anything — it is the parent the per-list keys inherit from (mirrors can() in
-- src/lib/auth.tsx, where mod:/masters covers every mod:/masters/<key>).
--
-- Only `public.masters` is split this way. parties / products / parts are their
-- own registers with their own screens and keep the global `masters.edit`.
-- ===========================================================================

do $$
begin
  if to_regclass('public.masters') is null then
    raise notice 'public.masters is not present — run the masters bundle first';
    return;
  end if;

  -- 0008 created one FOR ALL policy; replace it with per-command policies so
  -- delete can be granted separately from add / edit.
  drop policy if exists masters_write on public.masters;
  drop policy if exists masters_admin_write on public.masters;
  drop policy if exists masters_insert on public.masters;
  drop policy if exists masters_update on public.masters;
  drop policy if exists masters_delete on public.masters;

  create policy masters_insert on public.masters for insert
    with check (public.has_perm('masters.edit')
             or public.has_perm('master.' || coalesce(name, '') || '.edit'));

  create policy masters_update on public.masters for update
    using      (public.has_perm('masters.edit')
             or public.has_perm('master.' || coalesce(name, '') || '.edit'))
    with check (public.has_perm('masters.edit')
             or public.has_perm('master.' || coalesce(name, '') || '.edit'));

  create policy masters_delete on public.masters for delete
    using      (public.has_perm('masters.edit')
             or public.has_perm('master.' || coalesce(name, '') || '.delete'));
end $$;

-- ------------------------------------------------------------------------
-- 0076_party_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- PARTY KEY — a readable identifier for each customer: Party-1, Party-2, …
--
-- Two things at once, and the second matters more than it looks:
--
--   1. Every party gets a short, stable handle to refer to. Assigned ONCE on
--      insert and never reassigned — a key that moves is not a key.
--
--   2. `parties` had NO unique constraint at all, so re-running an upload
--      ADDED another copy of every row. On a 5,874-row master that is a
--      catastrophe you only notice later, when the pickers show everything
--      twice. `name_key` makes the party name the natural key, so a re-load
--      CORRECTS rather than duplicates.
--
-- `name_key` is a STORED generated column rather than an expression index,
-- because `on conflict` cannot infer an expression index — the upload's upsert
-- would be refused outright. (The same trap 0071 and 0074 sprang.)
-- ===========================================================================

alter table public.parties add column if not exists party_key text;
alter table public.parties
  add column if not exists name_key text generated always as (lower(btrim(party_name))) stored;

-- ---------------------------------------------------------------------------
-- The series. A table rather than a sequence, so the go-live reset can empty it
-- with the other counters and production starts again at Party-1 — a sequence
-- would have to be reset separately and would be forgotten.
-- ---------------------------------------------------------------------------
create table if not exists public.party_key_seq (
  singleton boolean primary key default true check (singleton),
  last_no   bigint not null default 0
);

create or replace function public.next_party_key()
returns text language plpgsql security definer set search_path = public as $$
declare v_no bigint;
begin
  insert into public.party_key_seq (singleton, last_no)
  values (true, coalesce((select max(nullif(regexp_replace(party_key, '^Party-', ''), '')::bigint)
                            from public.parties where party_key ~ '^Party-[0-9]+$'), 0))
  on conflict (singleton) do nothing;

  update public.party_key_seq set last_no = last_no + 1 returning last_no into v_no;
  return 'Party-' || v_no;
end $$;
grant execute on function public.next_party_key() to authenticated;

create or replace function public.parties_before_write()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'UPDATE' then
    -- A key that moves is not a key: keep whatever the row was given.
    new.party_key := coalesce(nullif(btrim(old.party_key), ''), new.party_key);
  end if;
  new.party_name := btrim(coalesce(new.party_name, ''));
  return new;
end $$;

drop trigger if exists parties_biu on public.parties;
create trigger parties_biu before insert or update on public.parties
  for each row execute function public.parties_before_write();

-- ---------------------------------------------------------------------------
-- The key is assigned AFTER the insert, not before it — and that is the whole
-- point of putting it here.
--
-- A BEFORE INSERT trigger fires on every attempted insert, INCLUDING the ones
-- that `on conflict do update` then turns into updates. Re-uploading the
-- 5,874-row Party Master would burn 5,874 numbers each time and the next real
-- party would come out as Party-11749 — a series with holes the size of the
-- file. AFTER INSERT fires only for rows that were genuinely inserted, so the
-- numbering follows the parties, not the upload attempts.
-- ---------------------------------------------------------------------------
create or replace function public.parties_after_insert()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if btrim(coalesce(new.party_key, '')) = '' then
    update public.parties set party_key = public.next_party_key() where id = new.id;
  end if;
  return null;
end $$;

drop trigger if exists parties_aii on public.parties;
create trigger parties_aii after insert on public.parties
  for each row execute function public.parties_after_insert();

-- Backfill anything already loaded, oldest first so the numbering follows the
-- order the parties were actually created.
do $$
declare r record;
begin
  for r in select id from public.parties
            where coalesce(btrim(party_key), '') = '' order by id loop
    update public.parties set party_key = public.next_party_key() where id = r.id;
  end loop;
end $$;

create unique index if not exists parties_party_key_uniq on public.parties (party_key)
  where party_key is not null;
-- THE point of the exercise: a second upload of the same file corrects its rows
-- instead of adding 5,874 more.
create unique index if not exists parties_name_key_uniq on public.parties (name_key);
create index if not exists parties_party_key_idx on public.parties (party_key);

-- ------------------------------------------------------------------------
-- 0086_party_key_safe_update.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- "UPDATE requires a WHERE clause" — the Party Master upload, stopped at row 1.
--
-- Supabase runs PostgREST with pg_safeupdate loaded, so ANY update or delete
-- without a WHERE clause is refused for the API roles — including one inside a
-- SECURITY DEFINER function, because the guard is a session setting and not a
-- privilege. `next_party_key()` bumped its counter with
--
--     update public.party_key_seq set last_no = last_no + 1 returning ...
--
-- which is unambiguous (the table holds exactly one row, by primary key) but
-- has no WHERE — so the first inserted party raised, and 5,873 rows landed
-- nowhere. It never showed in psql, where the guard is not loaded.
--
-- The counter row is `singleton`. Name it.
-- ===========================================================================

create or replace function public.next_party_key()
returns text language plpgsql security definer set search_path = public as $$
declare v_no bigint;
begin
  insert into public.party_key_seq (singleton, last_no)
  values (true, coalesce((select max(nullif(regexp_replace(party_key, '^Party-', ''), '')::bigint)
                            from public.parties where party_key ~ '^Party-[0-9]+$'), 0))
  on conflict (singleton) do nothing;

  update public.party_key_seq set last_no = last_no + 1
   where singleton
  returning last_no into v_no;
  return 'Party-' || v_no;
end $$;
grant execute on function public.next_party_key() to authenticated;

-- ------------------------------------------------------------------------
-- 0079_part_product_keys.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Natural keys for Part Master and Product Master.
--
-- Neither had one, so re-running an upload ADDED every row again — 1,324 parts
-- and 19,259 machines, silently, with the damage only visible later when every
-- picker shows everything twice. Parties got this in 0076; these are the other
-- two registers a cutover loads more than once.
--
--   parts     — the part CODE. One duplicate in the real 1,324-row export
--               ("YR134500"), which the upload collapses to the last of them.
--   products  — a machine is its MODEL plus its SERIAL, not the serial alone:
--               in the real 20,999-row export 3,794 serials repeat (there are
--               eleven machines called "219"), but model + serial is distinct
--               on 19,253 of 19,259.
--
-- Both are STORED generated columns rather than expression indexes, because
-- `on conflict` cannot infer an expression index (0071, 0074, 0076, 0077 — this
-- is the fifth time, hence the check in `npm run check:uploads`).
--
-- GUARDED: a project that already holds duplicates from an earlier load cannot
-- build the index, and this says so rather than failing the whole bundle.
-- ===========================================================================

alter table public.parts
  add column if not exists code_key text generated always as (lower(btrim(code))) stored;

do $$
begin
  if exists (select 1 from public.parts where btrim(coalesce(code, '')) <> ''
              group by lower(btrim(code)) having count(*) > 1) then
    raise notice 'parts already holds duplicate codes — de-duplicate, then re-run this file to build parts_code_key_uniq.';
  else
    create unique index if not exists parts_code_key_uniq on public.parts (code_key) where code_key <> '';
  end if;
end $$;

alter table public.products
  add column if not exists machine_key text generated always as
    (lower(btrim(coalesce(item_name, ''))) || '|' || lower(btrim(coalesce(serial_number, '')))) stored;

do $$
begin
  if exists (select 1 from public.products where btrim(coalesce(serial_number, '')) <> ''
              group by lower(btrim(coalesce(item_name, ''))) || '|' || lower(btrim(coalesce(serial_number, '')))
              having count(*) > 1) then
    raise notice 'products already holds duplicate model+serial — de-duplicate, then re-run this file to build products_machine_key_uniq.';
  else
    create unique index if not exists products_machine_key_uniq
      on public.products (machine_key) where machine_key <> '|';
  end if;
end $$;

create index if not exists parts_code_key_idx    on public.parts (code_key);
-- products_machine_idx (machine_key) was here; the same column as products_machine_key_uniq (0081).
-- Removed 2026-10-05; 0382 drops it where it exists.

-- ------------------------------------------------------------------------
-- 0129_product_serial_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- LOOKING UP ONE MACHINE BY ITS SERIAL IS AN EQUALITY, AND IT WAS A SUBSTRING.
--
-- Reported 2026-09-07: "Could not prepare registration: canceling statement due
-- to statement timeout", on Pending Registrations, again.
--
-- Registering a call from a request validates the machine against Product
-- Master by serial. It asked for `serial_number ILIKE '%5054%'` — a
-- leading-wildcard substring scan over every machine — and then picked the
-- EXACT row out of the answer in the browser. Two things follow, and the
-- timeout is the less serious one:
--
--   * A 4-character pattern has almost no trigrams to go on, so the trigram
--     index (0052) returns most of the table as candidates and the planner
--     gives up and scans. At ~21k machines that crosses `authenticated`'s
--     statement timeout, and Supabase cancels it. The register grows, so this
--     gets worse, which is why it keeps coming back.
--   * It asked for the first 25 matches and then looked for the exact serial
--     among them. A serial that 25 OTHER serials contain as a substring was
--     never found at all — reported as "not in Product Master", warranty and
--     contract silently not filled in, on a call that had them.
--
-- WHY THE EARLIER FIXES DID NOT REACH IT. 0037 indexed
-- `lower(trim(serial_number))` for the cover import; 0052 added trigram
-- indexes for SEARCH; 0079/0082 added btree keys so the UPSERTS could infer a
-- target. Every one of them was about a query that says `=`. This call site
-- says `ILIKE '%…%'`, so no index built for equality was ever consulted. The
-- gotcha in CLAUDE.md — "substring search needs pg_trgm; `=`/`IN` needs a
-- btree" — inverted: the code asked for a substring when it meant equality.
--
-- THE FIX IS A COLUMN, NOT AN INDEX. `products_serial_key_idx` (0037) is an
-- EXPRESSION index, and PostgREST cannot express `lower(trim(serial_number))`
-- in a filter — so a client can never use it. A stored generated column can be
-- filtered on directly and is indexed like any other, which is exactly what
-- 0077 did for `product_additional_entries` and for the same reason.
--
-- The expression index stays: `sync_product_cover` still joins on
-- `lower(trim(serial_number))`, and that is its index.
-- ===========================================================================

alter table public.products
  add column if not exists serial_key text
    generated always as (lower(btrim(coalesce(serial_number, '')))) stored;

create index if not exists products_serial_key_col_idx
  on public.products (serial_key) where serial_key <> '';

comment on column public.products.serial_key is
  'lower(btrim(serial_number)), stored, so a client can look one machine up by serial as an EQUALITY on an indexed column. The expression index products_serial_key_idx (0037) cannot be reached through PostgREST; this can.';

-- ------------------------------------------------------------------------
-- 0193_product_master_lines.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0193 — THE PRODUCT MASTER: the catalogue of product LINES.
--
-- The user, 2026-09-14: "Add a Separate Product Master - Which is the Actual
-- List of Product Lines along with all Details -- With Active and Inactive
-- [All Inactive Products can never have a new Sale Entry, But can still have
-- Contract or Calls or Basically everything other than New Sale Entry]".
--
-- THE TWO ARE NOT THE SAME REGISTER AND NEVER WERE:
--
--   public.products         the INSTALL BASE — one row per MACHINE, model and
--                           serial, its customer and its cover. Labelled
--                           PRODUCT DATABASE since 0192.
--   public.product_master   THIS — one row per PRODUCT LINE. 53 of them today.
--                           No customer, no serial, no cover.
--
-- THE KEY IS THE PRODUCT CODE, measured against the user's own ProductList
-- export rather than assumed: 53 rows, 53 distinct Product Codes, but only 43
-- distinct Product NAMES. CPX CARE alone has NINE codes, EXTEND-XT two, HORUS
-- two — and within CPX CARE some codes are Active and some Inactive. So a rule
-- written on the NAME would be wrong nine times over on that product alone.
--
-- `active` IS THE WHOLE POINT OF THE TABLE. 23 of the 53 are Active and 30
-- Inactive, and the rule the user gave is precise: an inactive line takes NO
-- NEW SALE ENTRY, and everything else — contracts, calls, visits, spares,
-- feedback — carries on exactly as before. A machine sold in 2014 is still
-- supported; the line is simply no longer sold.
--
-- WHERE THAT RULE IS ENFORCED, and why not here: see the note at the foot of
-- this file. It is not a trigger, and that is a decision rather than an
-- omission.
-- ===========================================================================

create table if not exists public.product_master (
  product_code   text primary key,
  product_name   text not null default '',
  -- "CODE|NAME", the export's own `Item Code | Item Name`. Carried as given so
  -- a file can be matched back to what it said.
  item_detail    text not null default '',
  item_type      text not null default '',   -- PRODUCT / PRODUCT-ALLIED
  item_category  text not null default '',   -- VENTILATOR-ICU / ACCESSORY / …
  short_form     text not null default '',
  -- ACTIVE? in the export. TRUE means the line can still be SOLD; it says
  -- nothing about whether the machines already out there are supported.
  active         boolean not null default true,
  added_on       date,
  added_by       text not null default '',
  -- Anything the export carries that has no column here, under its own
  -- heading — the same bargain every other importer makes.
  extra          jsonb not null default '{}'::jsonb,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  created_by     uuid references auth.users (id) default auth.uid()
);

comment on table public.product_master is
  'The catalogue of PRODUCT LINES — one row per code, 53 today. Not the install base: that is public.products, labelled Product Database. `active` false means the line takes no NEW SALE ENTRY; contracts, calls and everything else are unaffected.';
comment on column public.product_master.active is
  'Can this line still be SOLD? False stops a NEW sale entry only. Machines already sold stay supported — they take contracts, calls, visits, spares and feedback exactly as before.';

create index if not exists product_master_name_idx   on public.product_master (product_name);
create index if not exists product_master_active_idx on public.product_master (active);
-- NO TRIGRAM INDEX, and the reason is the size rather than the search. The
-- first draft added one by habit — the party cascade needed pg_trgm alongside
-- its btree, and that note in CLAUDE.md is about a table with thousands of
-- rows. THIS TABLE HAS FIFTY-THREE. Postgres will scan it whatever is on it,
-- and the index only bought a dependency: `check:replay` refused the bundle
-- outright with `operator class "gin_trgm_ops" does not exist`, because
-- all.sql builds its database before any migration has created the extension.
-- A habit applied without the measurement behind it.

create or replace function public.product_master_touch()
returns trigger language plpgsql as $$
begin new.updated_at := now(); return new; end $$;
drop trigger if exists product_master_touch on public.product_master;
create trigger product_master_touch before update on public.product_master
  for each row execute function public.product_master_touch();

-- ---------------------------------------------------------------------------
-- RLS. Reading the catalogue is reading a price-list without prices: it names
-- the product lines and says which are still sold, and carries no customer, no
-- serial and no cover. Any signed-in user reads it, because every picker that
-- offers a product needs it. Writing needs `masters.edit`, the same right the
-- other masters take.
-- ---------------------------------------------------------------------------
alter table public.product_master enable row level security;
grant select, insert, update, delete on public.product_master to authenticated;

drop policy if exists pm_read on public.product_master;
create policy pm_read on public.product_master for select
  using (auth.role() = 'authenticated');

drop policy if exists pm_write on public.product_master;
create policy pm_write on public.product_master for all
  using (public.has_perm('masters.edit')) with check (public.has_perm('masters.edit'));

-- ---------------------------------------------------------------------------
-- IS THIS LINE STILL SELLABLE? One answer, for the form and for anything else
-- that needs it.
--
-- UNKNOWN IS SELLABLE. A code the catalogue has never heard of returns TRUE,
-- not FALSE: the catalogue is maintained by hand and an incomplete one must not
-- silently refuse a real sale. Refusing what you do not recognise is how a
-- master list stops a business rather than describing it.
--
-- THE NAME IS THE FALLBACK, and only where there is no code — a name is
-- sellable if ANY of its codes is. CPX CARE is the case: nine codes, some
-- active, some not, and treating the name as dead because one code is would be
-- wrong eight times.
-- ---------------------------------------------------------------------------
create or replace function public.product_line_sellable(p_code text, p_name text default null)
returns boolean language sql stable as $$
  select case
    when coalesce(btrim(p_code), '') <> '' then
      coalesce((select pm.active from public.product_master pm
                 where upper(btrim(pm.product_code)) = upper(btrim(p_code))), true)
    when coalesce(btrim(p_name), '') <> '' then
      coalesce((select bool_or(pm.active) from public.product_master pm
                 where upper(btrim(pm.product_name)) = upper(btrim(p_name))), true)
    else true
  end;
$$;

comment on function public.product_line_sellable(text, text) is
  'Can a NEW sale entry name this product line? Keyed on the CODE; the NAME is the fallback and is sellable if ANY of its codes is. An UNKNOWN code or name is sellable — an incomplete catalogue must not refuse a real sale.';

-- ===========================================================================
-- WHY THERE IS NO TRIGGER ON sale_items, and it is a decision not an omission.
--
-- A trigger refusing an inactive line would also refuse THE HISTORICAL SALES
-- IMPORT. The Warranty Sale Details export is full of machines sold when their
-- line was current and long since retired — ORION, HORUS, MONNAL T20, the whole
-- PRD-OLD-* family, 30 of the 53 lines. Those sales HAPPENED. A database that
-- refused to record them would make the register unloadable, and the first
-- symptom would be a load stopping part-way with a message about a product
-- nobody is trying to sell.
--
-- So the rule lives where the ACT of selling happens: the Sale Entry form
-- offers active lines only, and says why when a line is missing. A bulk load of
-- history is not somebody making a new sale.
--
-- If that is ever not enough, the guard belongs on the FORM'S path rather than
-- the table's — an `is_new_sale` flag the importer does not set — and this note
-- is here so whoever adds it knows which way round the problem is.
-- ===========================================================================

-- ------------------------------------------------------------------------
-- 0194_product_database_all_columns.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0194 — THE PRODUCT DATABASE KEEPS EVERY COLUMN OF ITS EXPORT.
--
-- The user, 2026-09-14: "Product Database has to retain all Columns - Attached
-- a Sample. [v2_ProdMaster (1).csv]".
--
-- Measured against that sample rather than guessed: the export has 32 columns
-- and eleven of them had a column here. THE OTHER TWENTY-ONE WERE NOT LOST —
-- the importer is `extraInto: 'extra'` and has been keeping every unnamed
-- heading under its own spelling — but a value in a jsonb blob cannot be
-- sorted, filtered, grouped or shown as a column. It is present and unusable,
-- which is the same fault 0148 fixed for the Part Master:
--
--     "a value in a jsonb blob cannot be grouped, filtered or shown as a
--      column, so 'Spare / Consumable' was in the database and unusable"
--
-- SO THE BACKFILL MATTERS AS MUCH AS THE COLUMNS. Every machine already loaded
-- carries these values in `extra` right now, so this reads them back out — the
-- same move 0190 made for the feedback dates, and for the same reason: nobody
-- should have to re-upload to get at what the importer already kept.
--
-- `extra` IS NOT EMPTIED. A column that now exists is still left in `extra`
-- as it arrived, because the two answer different questions: the column is what
-- this system holds, `extra` is what the FILE SAID. When they disagree — a bad
-- date, a value the parser could not read — the file's own words are the
-- evidence, and deleting them would destroy the only record of what was
-- actually supplied.
--
-- THREE THAT ARE NOT SIMPLY TEXT, and each is a decision:
--
--   `item_code`       the Product Database had NO product code at all. It is
--                     what joins a machine to its line on the new Product
--                     Master (0193), so it is the one that unlocks the other
--                     register rather than merely displaying.
--   `warranty_status_keyed` / `contract_status_keyed`
--                     the export's OWN "ACTIVE"/"INACTIVE" text. NOT the same
--                     as the state this system computes from the dates, and
--                     named `_keyed` so the two can never be mistaken for one
--                     another — the cover registers make exactly this
--                     distinction already.
--   `pm_visits`       an integer, because it is counted. A blank stays NULL
--                     rather than becoming 0: "nobody said" and "none" are
--                     different answers about a service schedule.
-- ===========================================================================

alter table public.products
  add column if not exists item_code              text not null default '',
  add column if not exists item_details_long      text not null default '',
  add column if not exists item_details           text not null default '',
  add column if not exists sold_through           text not null default '',
  add column if not exists state                  text not null default '',
  add column if not exists city                   text not null default '',
  add column if not exists address                text not null default '',
  add column if not exists po_no                  text not null default '',
  add column if not exists po_date                date,
  add column if not exists warranty_status_keyed  text not null default '',
  add column if not exists contract_status_keyed  text not null default '',
  add column if not exists pm_visits              integer,
  add column if not exists other_details          text not null default '',
  add column if not exists service_engineer       text not null default '',
  add column if not exists prod_final             text not null default '',
  add column if not exists installation_completed text not null default '',
  add column if not exists inst_call              text not null default '',
  add column if not exists inst_date              date,
  add column if not exists inst_call_status       text not null default '',
  add column if not exists report                 text not null default '',
  add column if not exists associated_accessory   text not null default '';

comment on column public.products.item_code is
  'The product CODE. Joins this machine to its line on public.product_master (0193) — the Product Database had none until 0194.';
comment on column public.products.warranty_status_keyed is
  'The export''s own ACTIVE/INACTIVE text. NOT the state this system computes from the dates; the two can disagree and the disagreement is worth seeing.';
comment on column public.products.contract_status_keyed is
  'As warranty_status_keyed, for the contract.';
comment on column public.products.pm_visits is
  'How many PM visits the cover carries. NULL means nobody said, which is not the same as none.';

-- The code is how a machine reaches its product line, so it is worth an index.
create index if not exists products_item_code_idx on public.products (item_code);

-- ---------------------------------------------------------------------------
-- THE BACKFILL, out of `extra` and into the columns.
--
-- Idempotent: it only fills a column that is still EMPTY, so running it again
-- changes nothing and it can never overwrite a value somebody has since
-- corrected on screen. `extra` is read, never written.
--
-- THE DATES ARE GUARDED ON THEIR SHAPE. `to_date('rubbish','DD Mon YY')` does
-- not return null, it RAISES — so one unreadable cell in twenty thousand would
-- fail the whole migration. The sample writes them `02 Sep 23`, which is
-- `DD Mon YY`; anything not matching that shape is left for somebody to look
-- at, and is still in `extra` verbatim.
-- ---------------------------------------------------------------------------
do $$
declare n int;
begin
  if to_regclass('public.products') is null then return; end if;

  update public.products p set
    item_code              = coalesce(nullif(p.item_code, ''),              btrim(coalesce(p.extra->>'Item Code', ''))),
    item_details_long      = coalesce(nullif(p.item_details_long, ''),      btrim(coalesce(p.extra->>'Item Details Long', ''))),
    item_details           = coalesce(nullif(p.item_details, ''),           btrim(coalesce(p.extra->>'Item Details', ''))),
    sold_through           = coalesce(nullif(p.sold_through, ''),           btrim(coalesce(p.extra->>'Sold Through', ''))),
    state                  = coalesce(nullif(p.state, ''),                  btrim(coalesce(p.extra->>'State', ''))),
    city                   = coalesce(nullif(p.city, ''),                   btrim(coalesce(p.extra->>'City', ''))),
    address                = coalesce(nullif(p.address, ''),                btrim(coalesce(p.extra->>'Address', ''))),
    po_no                  = coalesce(nullif(p.po_no, ''),                  btrim(coalesce(p.extra->>'PO No.', p.extra->>'PO No', ''))),
    warranty_status_keyed  = coalesce(nullif(p.warranty_status_keyed, ''),  btrim(coalesce(p.extra->>'Warranty Status', ''))),
    contract_status_keyed  = coalesce(nullif(p.contract_status_keyed, ''),  btrim(coalesce(p.extra->>'Contract Status', ''))),
    other_details          = coalesce(nullif(p.other_details, ''),          btrim(coalesce(p.extra->>'Other Details', ''))),
    service_engineer       = coalesce(nullif(p.service_engineer, ''),       btrim(coalesce(p.extra->>'Service Engineer', ''))),
    prod_final             = coalesce(nullif(p.prod_final, ''),             btrim(coalesce(p.extra->>'ProdFinal', ''))),
    installation_completed = coalesce(nullif(p.installation_completed, ''), btrim(coalesce(p.extra->>'Installation Completed?', ''))),
    inst_call              = coalesce(nullif(p.inst_call, ''),              btrim(coalesce(p.extra->>'INST Call', ''))),
    inst_call_status       = coalesce(nullif(p.inst_call_status, ''),       btrim(coalesce(p.extra->>'INST Call Status', ''))),
    report                 = coalesce(nullif(p.report, ''),                 btrim(coalesce(p.extra->>'Report', ''))),
    associated_accessory   = coalesce(nullif(p.associated_accessory, ''),   btrim(coalesce(p.extra->>'Associated Accessory', '')))
   where p.extra <> '{}'::jsonb;
  get diagnostics n = row_count;
  raise notice '0194: % machine(s) had their kept columns read back out of `extra`', n;

  -- A COUNT, so a blank stays NULL. "Nobody said" and "none" are different
  -- answers about a service schedule.
  update public.products p
     set pm_visits = (btrim(p.extra->>'PM Visits'))::int
   where p.pm_visits is null
     and btrim(coalesce(p.extra->>'PM Visits', '')) ~ '^\d{1,4}$';

  -- The two dates, guarded on the sample's own shape (`02 Sep 23`).
  update public.products p
     set po_date = to_date(btrim(p.extra->>'PO Date'), 'DD Mon YY')
   where p.po_date is null
     and btrim(coalesce(p.extra->>'PO Date', '')) ~ '^\d{1,2} [A-Za-z]{3} \d{2}$';
  update public.products p
     set inst_date = to_date(btrim(p.extra->>'INST Date'), 'DD Mon YY')
   where p.inst_date is null
     and btrim(coalesce(p.extra->>'INST Date', '')) ~ '^\d{1,2} [A-Za-z]{3} \d{2}$';
end $$;

-- ------------------------------------------------------------------------
-- 0200_party_service_engineer.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE PARTY MASTER CARRIES ITS SERVICE ENGINEER.
--
-- The user, 2026-09-15: *"In Party Master, my old source has service engineer
-- details. So during any new field call or Installation calls or PM Call, it
-- has to map the engineer as per the party master. In case of creating a call
-- from a request, then it has to map it to the requestor. All the fields to be
-- retained as is."*
--
-- The supplied export (Product Master - PartyMaster.csv, 4,752 parties) has a
-- `Serviceman` column, filled on 4,677 of them — 49 distinct names. That is who
-- looks after the customer, and it is the answer for a call on a machine this
-- system has never seen: an INSTALLATION reaches a customer who has no machine
-- yet, so the machine's own Service Engineer cannot answer for it.
--
-- A REAL COLUMN, NOT A KEY IN `extra`. The importer is `extraInto: 'extra'`, so
-- the value would arrive either way — and a value in a jsonb blob cannot be
-- joined, indexed or picked from. It is the fault 0148 fixed for the Part
-- Master and 0194 for the Product Database, and the call form has to LOOK THIS
-- UP on every registration, which is the one thing a blob is worst at.
--
-- PRECEDENCE, settled with the user before any of this was built: the MACHINE'S
-- own Service Engineer still wins, and the party's Serviceman answers only
-- where the machine has none. So this widens where an engineer can be found and
-- changes no call that already found one.
--
-- IT IS A PREFILL AND NOTHING MORE. `allocated_to` keeps no default and gains
-- no trigger: the form offers a name and whoever registers the call may change
-- it. An assignment the database made would be a rule nobody could see and,
-- once the party master went stale, one nobody could correct at the keyboard.
-- ===========================================================================

alter table public.parties add column if not exists service_engineer text default '';

comment on column public.parties.service_engineer is
  'The Serviceman on the Party Master — who looks after this customer. Prefills "Call Allocated To" where the machine has no Service Engineer of its own.';

-- ---------------------------------------------------------------------------
-- THE BACKFILL, out of `extra`.
--
-- The parties already loaded came in through `extraInto: 'extra'`, so any
-- Serviceman they carried is on the row under its ORIGINAL SPREADSHEET HEADING
-- — the same reason 0190 could recover the feedback dates without asking for
-- the file again. Several spellings are tried because the exports disagree, and
-- the first non-blank wins.
--
-- It never overwrites a value already in the column, so re-running it cannot
-- undo a correction somebody made on the screen.
-- ---------------------------------------------------------------------------
-- WRITTEN OUT TWICE rather than through a LATERAL, and that is not a style
-- choice: `update ... from lateral (...)` CANNOT SEE the update's own target
-- table, so the tidier version raises `invalid reference to FROM-clause entry
-- for table "p"` and the whole migration stops before the function below is
-- created. Caught by running it; it reads perfectly well.
do $$
declare n int;
begin
  update public.parties p
     set service_engineer = coalesce(
           nullif(btrim(p.extra ->> 'Serviceman'), ''),
           nullif(btrim(p.extra ->> 'Service Engineer'), ''),
           nullif(btrim(p.extra ->> 'SERVICEMAN'), ''),
           nullif(btrim(p.extra ->> 'Service Man'), ''))
   where coalesce(btrim(p.service_engineer), '') = ''
     and coalesce(
           nullif(btrim(p.extra ->> 'Serviceman'), ''),
           nullif(btrim(p.extra ->> 'Service Engineer'), ''),
           nullif(btrim(p.extra ->> 'SERVICEMAN'), ''),
           nullif(btrim(p.extra ->> 'Service Man'), '')) is not null;
  get diagnostics n = row_count;
  raise notice 'Party Master: service engineer recovered from `extra` on % part(y/ies).', n;
end $$;

-- ---------------------------------------------------------------------------
-- The lookup the call form makes, and the only reason this is a column.
--
-- Answered from `name_key`, which is GENERATED and already carries the unique
-- index (0076) — so the party is found by the same key the importer matches on
-- and the two cannot disagree about which party this is.
--
-- SECURITY INVOKER by being plain SQL over a table the reader's own policy
-- covers: `parties_read` admits any signed-in user, which is what the existing
-- party pickers already rely on. It returns the empty string rather than NULL
-- for a party nobody has recorded, so the caller has one thing to test.
-- ---------------------------------------------------------------------------
-- THE COALESCE IS OUTSIDE THE SUBQUERY, and the first version had it inside.
-- A `select ... from parties where ...` that matches NO ROW returns no rows at
-- all, so the function returned NULL for exactly the case it exists to answer
-- — a party nobody has recorded — whatever the coalesce around the column said.
-- It passed every test written against a party that DOES exist. Caught by
-- asking it about one that does not.
create or replace function public.party_service_engineer(p_party text)
returns text language sql stable security invoker set search_path = public as $$
  select coalesce((
    select nullif(btrim(p.service_engineer), '')
      from public.parties p
     where p.name_key = lower(btrim(coalesce(p_party, '')))
     limit 1
  ), '')
$$;

comment on function public.party_service_engineer(text) is
  'The Party Master Serviceman for a party name, or the empty string. Prefills "Call Allocated To" where the machine has none.';

grant execute on function public.party_service_engineer(text) to authenticated;

-- ------------------------------------------------------------------------
-- 0201_party_columns_and_kyc.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE PARTY MASTER'S OWN COLUMNS, AND SOMEWHERE TO PUT KYC.
--
-- The user, 2026-09-15: *"Additionally add provision to capture the KYC details
-- of the customer. Clean up the columns, de-dupe the column headers."*
--
-- WHAT THE SUPPLIED EXPORT ACTUALLY HOLDS, counted rather than assumed
-- (4,752 parties):
--
--   Profile          4752  PRIVATE / GOVERNMENT — 3 values. A real
--                          classification, and it was being THROWN AWAY: the
--                          importer aliased `party_type` to ['type','profile']
--                          and Type wins, so Profile only ever reached `extra`.
--   Route            4714  2,922 values — the territory.
--   Inst. Pincode    2469
--   Tel 1            4752  but only 922 distinct: the same switchboard number
--                          repeats over thousands of rows.
--   Tel 2             232   Fax 17   Email ID 73
--   Billing Address    26   Pincode 5   Tel 1 [2] 14   Tel 2 [2] 2   Fax [2] 1
--   Email ID [2]        0
--   Office Name      4752  ...and it is OUR OWN COMPANY on every row, not the
--                          customer. It gets no column: a column that says the
--                          same thing 4,752 times answers no question.
--   Under               0  Salesman 0  Tax 3 0 — EMPTY. No columns either.
--
-- DE-DUPED BY NAMING, not by numbering. The file carries `Tel 1`, `Tel 2`,
-- `Fax` and `Email ID` TWICE — once against the installation address and once
-- against the billing address — so the second set becomes billing_* here and
-- stops being a mystery second column. Until 0200 it was being dropped outright.
--
-- ---------------------------------------------------------------------------
-- KYC: THE FRAME, NOT THE FIELDS.
--
-- Asked which fields to capture, the user said: *"I don't know.. there is some
-- format for KYC, I will update."* So the fields are NOT invented here. What is
-- built is the part that was decided and the part the evidence settles:
--
--   • THE STATUS, and every party starts Pending (the user's answer). 4,752 of
--     them, because NOBODY HAS VERIFIED ANYTHING — a number on file is not a
--     verification, and marking five rows Verified because a spreadsheet had a
--     string in a Tax column would be inventing an audit record. Who verified
--     it and when are stamped by the database, not by the caller.
--   • GSTIN AND PAN, which are certain: they are statutory, they have a shape,
--     and the export already carries six of them.
--
-- The rest arrives as real columns when the format does. A jsonb bag "for the
-- fields we don't know yet" is what 0148 and 0194 both had to undo.
-- ===========================================================================

alter table public.parties
  add column if not exists profile          text default '',
  add column if not exists route            text default '',
  add column if not exists pincode          text default '',
  add column if not exists phone            text default '',
  add column if not exists phone_2          text default '',
  add column if not exists fax              text default '',
  add column if not exists email            text default '',
  add column if not exists billing_address  text default '',
  add column if not exists billing_pincode  text default '',
  add column if not exists billing_phone    text default '',
  add column if not exists billing_phone_2  text default '',
  add column if not exists billing_fax      text default '',
  add column if not exists billing_email    text default '',
  add column if not exists gstin            text default '',
  add column if not exists pan              text default '',
  add column if not exists kyc_status       text default 'Pending',
  add column if not exists kyc_notes        text default '',
  add column if not exists kyc_verified_by  uuid,
  add column if not exists kyc_verified_at  timestamptz;

comment on column public.parties.profile   is 'PRIVATE / GOVERNMENT — the export''s own Profile column, which Type used to swallow.';
comment on column public.parties.gstin     is 'GSTIN, 15 characters. Parsed out of the export''s free-text Tax columns.';
comment on column public.parties.pan       is 'PAN, 10 characters. A GSTIN contains one at characters 3-12, so it is derived where only a GSTIN is known.';
comment on column public.parties.kyc_status is 'Pending / Verified / Rejected. Every party starts Pending: nobody has verified anything yet.';

-- A STATUS WITH THREE VALUES, and the constraint says so. Not free text: this
-- one is COUNTED ("how many customers still need KYC?"), and a fourth spelling
-- makes every count wrong rather than merely untidy.
--
-- Added by NAME-independent inspection, because `add constraint if not exists`
-- does not exist and a bare add fails on a second run. `IF NOT EXISTS GUARDS A
-- NAME, NEVER A DEFINITION` (0186) — so it is dropped by name and recreated,
-- which is also what makes a changed list of values actually take.
alter table public.parties drop constraint if exists parties_kyc_status_check;
alter table public.parties
  add constraint parties_kyc_status_check
  check (coalesce(kyc_status, '') in ('', 'Pending', 'Verified', 'Rejected'));

-- ---------------------------------------------------------------------------
-- FINDING A STATUTORY NUMBER IN FREE TEXT.
--
-- The five values on record are `PAN NO:AAACI7716A`, `GST NO:33AADCK3295K2ZB`,
-- `GSTIN:33AAACL7222Q1ZB` and `GSTIN: 09AAACI7716A1ZV` — a label, a separator
-- that is sometimes a colon and sometimes a space, then the number. There is no
-- format to parse, so the number is found by its SHAPE, which is the only thing
-- all of them agree about.
--
--   GSTIN  a 2-digit state code, a 10-character PAN, an entity digit, `Z` and a
--          checksum — 15 characters. It cannot match a label, because it must
--          begin with two DIGITS.
--   PAN    five letters, four digits, a letter. SEARCHED, not anchored, because
--          the label is still attached: `PANNOAAACI7716A` must yield
--          `AAACI7716A`.
--
-- SPACES SURVIVE THE STRIP while punctuation does not, and that is deliberate:
-- the space is what separates `Tax 1` from `Tax 2` once they are concatenated,
-- so a number cannot be assembled across two fields that never held one.
--
-- ONE DEFINITION, called by the backfill below AND by the trigger, so an upload
-- next year is read exactly as the migration read the file today. The regex
-- was written out four times in the first draft, which is three chances for
-- them to drift apart.
-- ---------------------------------------------------------------------------
create or replace function public.kyc_gstin(p_text text)
returns text language sql immutable as $$
  select substring(upper(regexp_replace(coalesce(p_text, ''), '[^A-Za-z0-9 ]', '', 'g'))
                   from '[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][0-9A-Z]Z[0-9A-Z]')
$$;

create or replace function public.kyc_pan(p_text text)
returns text language sql immutable as $$
  select substring(upper(regexp_replace(coalesce(p_text, ''), '[^A-Za-z0-9 ]', '', 'g'))
                   from '[A-Z]{5}[0-9]{4}[A-Z]')
$$;

grant execute on function public.kyc_gstin(text) to authenticated;
grant execute on function public.kyc_pan(text)   to authenticated;

-- WHO SAYS IT IS VERIFIED IS THE DATABASE'S TO RECORD, not the caller's — the
-- same rule 0113 applies to who registered a call and 0173 to who reviewed one.
-- A verification naming somebody who did not do it is worse than one naming
-- nobody, and on a KYC record that is the whole value of the field.
create or replace function public.parties_kyc_stamp()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if coalesce(btrim(new.kyc_status), '') = '' then new.kyc_status := 'Pending'; end if;
  end if;

  -- A LONE `Pincode` BESIDE AN `Inst. Pincode` IS THE BILLING ONE. The export
  -- names the installation pincode and leaves the billing one bare, so the
  -- importer cannot alias it without racing the installation column for the
  -- same heading. The pair is only ambiguous in isolation: where BOTH headings
  -- are on the row, which is which is not in doubt.
  if coalesce(btrim(new.billing_pincode), '') = ''
     and new.extra ? 'Inst. Pincode' and coalesce(btrim(new.extra ->> 'Pincode'), '') <> '' then
    new.billing_pincode := btrim(new.extra ->> 'Pincode');
  end if;

  -- THE NUMBERS ARE DERIVED HERE TOO, not only in the backfill below. An upload
  -- puts the Tax columns in `extra` and nothing else would ever read them, so a
  -- file loaded next year would land exactly as the file loaded today did
  -- BEFORE this migration — with its GSTIN sitting in a blob. Only ever fills a
  -- BLANK: a number typed on the screen is never overwritten by a spreadsheet.
  if coalesce(btrim(new.gstin), '') = '' then
    new.gstin := coalesce(public.kyc_gstin(concat_ws(' ',
      new.extra ->> 'Tax 1', new.extra ->> 'Tax 2', new.extra ->> 'Tax 3',
      new.extra ->> 'GSTIN', new.extra ->> 'GST No')), '');
  end if;
  -- AFTER the GSTIN, and reading it: a GSTIN contains a PAN at characters 3-12,
  -- so a customer who gave only a GSTIN is not asked for a PAN as well.
  if coalesce(btrim(new.pan), '') = '' then
    new.pan := coalesce(public.kyc_pan(concat_ws(' ', new.gstin,
      new.extra ->> 'Tax 1', new.extra ->> 'Tax 2', new.extra ->> 'Tax 3',
      new.extra ->> 'PAN', new.extra ->> 'PAN No')), '');
  end if;
  if new.kyc_status is distinct from (case when tg_op = 'UPDATE' then old.kyc_status else null end) then
    if new.kyc_status = 'Verified' then
      new.kyc_verified_by := auth.uid();
      new.kyc_verified_at := now();
    else
      -- Moving OFF Verified clears the stamp: a party sent back to Pending has
      -- not been verified by anybody, and leaving the old name on it would say
      -- it had.
      new.kyc_verified_by := null;
      new.kyc_verified_at := null;
    end if;
  end if;
  return new;
end $$;

drop trigger if exists parties_kyc_stamp on public.parties;
create trigger parties_kyc_stamp
  before insert or update on public.parties
  for each row execute function public.parties_kyc_stamp();

-- ---------------------------------------------------------------------------
-- THE BACKFILL, out of `extra` — nobody is asked to upload the file again.
--
-- Every party already loaded came in through extraInto:'extra', so each of
-- these values is on the row under its ORIGINAL SPREADSHEET HEADING. The `[2]`
-- spellings are what the de-duped parse now produces for the billing block;
-- the bare ones are what earlier exports called the same thing.
--
-- A value already in the column is never overwritten, so this cannot undo a
-- correction somebody made on the screen.
-- ---------------------------------------------------------------------------
-- WRITTEN OUT, one column at a time. A loop building these with `format` was
-- the first draft and it is exactly the trap 0200 already hit: `update ... from
-- lateral (...)` CANNOT see the update's own target table. Thirteen plain
-- statements are longer and they are the ones that run.
update public.parties p set profile = coalesce(nullif(btrim(p.extra ->> 'Profile'), ''), p.profile)
 where coalesce(btrim(p.profile), '') = '' and coalesce(btrim(p.extra ->> 'Profile'), '') <> '';
update public.parties p set route = coalesce(nullif(btrim(p.extra ->> 'Route'), ''), p.route)
 where coalesce(btrim(p.route), '') = '' and coalesce(btrim(p.extra ->> 'Route'), '') <> '';
update public.parties p set pincode = coalesce(nullif(btrim(p.extra ->> 'Inst. Pincode'), ''), nullif(btrim(p.extra ->> 'Inst Pincode'), ''), nullif(btrim(p.extra ->> 'Pincode'), ''), p.pincode)
 where coalesce(btrim(p.pincode), '') = '';
update public.parties p set phone = coalesce(nullif(btrim(p.extra ->> 'Tel 1'), ''), nullif(btrim(p.extra ->> 'Phone'), ''), nullif(btrim(p.extra ->> 'Telephone'), ''), p.phone)
 where coalesce(btrim(p.phone), '') = '';
update public.parties p set phone_2 = coalesce(nullif(btrim(p.extra ->> 'Tel 2'), ''), p.phone_2)
 where coalesce(btrim(p.phone_2), '') = '';
update public.parties p set fax = coalesce(nullif(btrim(p.extra ->> 'Fax'), ''), p.fax)
 where coalesce(btrim(p.fax), '') = '';
update public.parties p set email = coalesce(nullif(btrim(p.extra ->> 'Email ID'), ''), nullif(btrim(p.extra ->> 'Email'), ''), p.email)
 where coalesce(btrim(p.email), '') = '';
update public.parties p set billing_address = coalesce(nullif(btrim(p.extra ->> 'Billing Address'), ''), p.billing_address)
 where coalesce(btrim(p.billing_address), '') = '';
update public.parties p set billing_pincode = coalesce(nullif(btrim(p.extra ->> 'Pincode [2]'), ''), nullif(btrim(p.extra ->> 'Billing Pincode'), ''), p.billing_pincode)
 where coalesce(btrim(p.billing_pincode), '') = '';
-- ...and the bare `Pincode` where an `Inst. Pincode` sits beside it to say
-- which is which. Same rule as the trigger, so a row already loaded and a row
-- loaded tomorrow are read the same way.
update public.parties p set billing_pincode = btrim(p.extra ->> 'Pincode')
 where coalesce(btrim(p.billing_pincode), '') = ''
   and p.extra ? 'Inst. Pincode' and coalesce(btrim(p.extra ->> 'Pincode'), '') <> '';
update public.parties p set billing_phone = coalesce(nullif(btrim(p.extra ->> 'Tel 1 [2]'), ''), nullif(btrim(p.extra ->> 'Billing Tel 1'), ''), p.billing_phone)
 where coalesce(btrim(p.billing_phone), '') = '';
update public.parties p set billing_phone_2 = coalesce(nullif(btrim(p.extra ->> 'Tel 2 [2]'), ''), nullif(btrim(p.extra ->> 'Billing Tel 2'), ''), p.billing_phone_2)
 where coalesce(btrim(p.billing_phone_2), '') = '';
update public.parties p set billing_fax = coalesce(nullif(btrim(p.extra ->> 'Fax [2]'), ''), nullif(btrim(p.extra ->> 'Billing Fax'), ''), p.billing_fax)
 where coalesce(btrim(p.billing_fax), '') = '';
update public.parties p set billing_email = coalesce(nullif(btrim(p.extra ->> 'Email ID [2]'), ''), nullif(btrim(p.extra ->> 'Billing Email'), ''), p.billing_email)
 where coalesce(btrim(p.billing_email), '') = '';

-- ---------------------------------------------------------------------------
-- GSTIN AND PAN, out of the export's free-text Tax columns.
--
-- The five values on record are `PAN NO:AAACI7716A`, `GST NO:33AADCK3295K2ZB`,
-- `GSTIN:33AAACL7222Q1ZB`, `GSTIN: 09AAACI7716A1ZV` and one more — a label, a
-- separator that is sometimes a colon and sometimes a space, then the number.
-- So the punctuation is STRIPPED and the number is FOUND BY ITS SHAPE, which is
-- the only thing all five agree about.
--
--   GSTIN  2-digit state code, a 10-character PAN, an entity digit, `Z`, a
--          checksum — 15 characters.
--   PAN    five letters, four digits, a letter.
--
-- Searched, not anchored, because the label is still attached: `PANNOAAACI7716A`
-- has to yield `AAACI7716A`. The GSTIN pattern cannot match a label, since it
-- must start with two DIGITS.
--
-- AND A GSTIN CONTAINS A PAN at characters 3-12, so a party that gave only a
-- GSTIN gets its PAN for nothing rather than being asked for it again.
-- ---------------------------------------------------------------------------
-- The same two derivations for the rows ALREADY loaded. It calls the helpers,
-- so the migration and the trigger cannot read a file differently.
update public.parties p
   set gstin = public.kyc_gstin(concat_ws(' ', p.extra ->> 'Tax 1', p.extra ->> 'Tax 2',
                 p.extra ->> 'Tax 3', p.extra ->> 'GSTIN', p.extra ->> 'GST No'))
 where coalesce(btrim(p.gstin), '') = ''
   and public.kyc_gstin(concat_ws(' ', p.extra ->> 'Tax 1', p.extra ->> 'Tax 2',
                 p.extra ->> 'Tax 3', p.extra ->> 'GSTIN', p.extra ->> 'GST No')) is not null;

update public.parties p
   set pan = public.kyc_pan(concat_ws(' ', p.gstin, p.extra ->> 'Tax 1', p.extra ->> 'Tax 2',
                 p.extra ->> 'Tax 3', p.extra ->> 'PAN', p.extra ->> 'PAN No'))
 where coalesce(btrim(p.pan), '') = ''
   and public.kyc_pan(concat_ws(' ', p.gstin, p.extra ->> 'Tax 1', p.extra ->> 'Tax 2',
                 p.extra ->> 'Tax 3', p.extra ->> 'PAN', p.extra ->> 'PAN No')) is not null;

-- EVERY PARTY STARTS PENDING (the user's answer). Including the handful whose
-- GSTIN came out of the spreadsheet: a number on file is not a verification,
-- and marking those Verified would be inventing an audit record nobody made.
update public.parties set kyc_status = 'Pending'
 where coalesce(btrim(kyc_status), '') = '';

do $$
declare n_gst int; n_pan int; n_pend int;
begin
  select count(*) filter (where coalesce(btrim(gstin), '') <> ''),
         count(*) filter (where coalesce(btrim(pan), '') <> ''),
         count(*) filter (where kyc_status = 'Pending')
    into n_gst, n_pan, n_pend from public.parties;
  raise notice 'Party Master KYC: % GSTIN, % PAN recovered; % part(y/ies) Pending.', n_gst, n_pan, n_pend;
end $$;

-- ------------------------------------------------------------------------
-- 0231_party_kyc_documents.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE KYC RECORDS THEMSELVES, ATTACHED TO THE PARTY.
--
--   The user, 2026-09-22: "In Party Master, add a provision to attach the KYC
--   records. If the customer is already KYC Verified, then display as KYC
--   Verified so that commercial department can proceed with Sale Entry and
--   Installation call."
--
-- 0201 gave a party a KYC STATUS, a note and a stamp of who verified it and
-- when. What it did not give it is the EVIDENCE: the GST certificate, the PAN
-- card, the registration that somebody looked at before writing "Verified".
-- A verification with no record behind it is an assertion, and the person who
-- has to rely on it downstream -- Commercial, before a sale entry and an
-- installation call -- cannot check it.
--
-- A JSONB LIST ON THE PARTY, NOT A TABLE, and the reason is what an attachment
-- IS here: the file lives in Drive, so this column holds a link and a name, not
-- a document. A table of two text columns keyed to the party, with its own
-- policies and its own cascade, buys nothing over a list that is read and
-- written exactly when the party is.
--
-- EACH ENTRY RECORDS WHO ATTACHED IT AND WHEN, because a KYC record whose
-- provenance is unknown is the same problem one step along. The shape is
-- { name, url, at, by } and the CHECK below refuses anything that is not a
-- list -- a single object written here by a mistaken client would make every
-- reader's `jsonb_array_elements` fail rather than show nothing.
-- ===========================================================================
alter table public.parties
  add column if not exists kyc_docs jsonb not null default '[]'::jsonb;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'parties_kyc_docs_is_list') then
    alter table public.parties add constraint parties_kyc_docs_is_list
      check (jsonb_typeof(kyc_docs) = 'array');
  end if;
end $$;

comment on column public.parties.kyc_docs is
  'The KYC records attached to this party: a list of { name, url, at, by }. The files live in Drive; this holds the link, the file name and who attached it when. Evidence for kyc_status — a verification with no record behind it is an assertion.';

-- ---------------------------------------------------------------------------
-- IS THIS PARTY CLEARED TO BUY? One expression, so the screen that offers a
-- Sale Entry and the screen that lists what Commercial is waiting on cannot
-- come to different answers about the same customer.
--
-- VERIFIED IS VERIFIED WHETHER OR NOT A FILE IS ATTACHED. The status is the
-- decision and a person made it; refusing to honour it because the evidence was
-- filed elsewhere would make this function stricter than the people it serves,
-- and the screens say separately whether a record is attached. What it will not
-- do is infer the other way: a party with documents and no verification is NOT
-- verified, because attaching a file is not a decision.
-- ---------------------------------------------------------------------------
create or replace function public.party_kyc_verified(p_status text)
returns boolean language sql immutable as $$
  select lower(btrim(coalesce(p_status, ''))) = 'verified';
$$;

grant execute on function public.party_kyc_verified(text) to authenticated;

comment on function public.party_kyc_verified(text) is
  'Is this party KYC verified? The status alone decides it — attaching a document is not a decision, and a verification recorded without one is still a decision somebody made.';

-- ------------------------------------------------------------------------
-- 0255_product_accessories.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- MAIN PRODUCT -> ITS ACCESSORIES AND ALLIED PRODUCTS.
--
--   The user, 2026-09-30: "Phase 2 - List Accessories + Main Product for the
--   Spare Request. So should also be able to map the Main Product and
--   Accessories / Allied products that might have been sold together -- so
--   ensure we have a place holder for that also in the table." Asked where it
--   should live: ON THE PRODUCT LINE -- one list per product, the same for
--   every machine of that product.
--
-- ONE ROW PER MAIN PRODUCT, keyed on its Product Database name (ORION-G,
-- VEGA...) -- the names a machine, a call and a spare request carry, and the
-- names the Part Master and the Standard Complaints are mapped to -- so Phase 2
-- can go from a call's product to its accessories and on to the parts of both
-- with no translation between vocabularies.
--
-- A PLACEHOLDER TODAY: nothing reads it yet. Phase 2 (the spare request
-- offering the parts of the main product AND its accessories) is the reader.
--
-- Readable by anyone signed in (a list of product names discloses nothing the
-- product list does not); written by whoever may edit masters -- the permission
-- asked ONCE per query (0250's lesson: a bare has_perm in a FOR ALL policy is
-- paid per row, on every read).
-- ===========================================================================

create table if not exists public.product_accessories (
  id           bigint generated always as identity primary key,
  main_product text not null,
  accessories  text[] not null default '{}',
  note         text not null default '',
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

-- ONE LIST PER MAIN PRODUCT, however it was typed -- a plain unique index on a
-- stored key, so a re-save updates rather than adds a second list.
alter table public.product_accessories
  add column if not exists main_product_key text generated always as (lower(btrim(main_product))) stored;
create unique index if not exists product_accessories_main_key on public.product_accessories (main_product_key);

create or replace function public.product_accessories_touch()
returns trigger language plpgsql set search_path = public as $$
begin
  new.updated_at := now();
  if tg_op = 'UPDATE' then new.created_at := old.created_at; end if;
  return new;
end $$;
drop trigger if exists product_accessories_touch on public.product_accessories;
create trigger product_accessories_touch before insert or update on public.product_accessories
  for each row execute function public.product_accessories_touch();

alter table public.product_accessories enable row level security;

drop policy if exists pa_read on public.product_accessories;
create policy pa_read on public.product_accessories for select to authenticated using (true);

drop policy if exists pa_insert on public.product_accessories;
create policy pa_insert on public.product_accessories for insert to authenticated
  with check ((select public.has_perm('masters.edit')));
drop policy if exists pa_update on public.product_accessories;
create policy pa_update on public.product_accessories for update to authenticated
  using ((select public.has_perm('masters.edit'))) with check ((select public.has_perm('masters.edit')));
drop policy if exists pa_delete on public.product_accessories;
create policy pa_delete on public.product_accessories for delete to authenticated
  using ((select public.has_perm('masters.edit')));

grant select, insert, update, delete on public.product_accessories to authenticated;
revoke all on public.product_accessories from anon;

-- The five system columns (0244), which a table created after 0244 does not
-- get from it -- guarded, since on a fresh apply sys_columns runs later.
do $$
begin
  if to_regprocedure('public.sys_columns_attach(regclass)') is not null then
    perform public.sys_columns_attach('public.product_accessories'::regclass);
  end if;
end $$;

-- ------------------------------------------------------------------------
-- 0263_user_department.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- DEPARTMENT ON THE USER MASTER.
--
--   The user, 2026-09-30: "Also add Department field in User Master, since the
--   scope has increased and will have to extend this app to other Department."
--
-- A column on `user_directory` (read by everyone signed in, like designation
-- and region -- a department is not private), and a MASTER LIST of the
-- departments so every screen offers the same spellings: a department typed
-- two ways splits every count and every training audience in two.
-- The list starts EMPTY -- nothing is invented; an administrator adds the
-- company's departments under Masters -> Department.
-- ===========================================================================

alter table public.user_directory add column if not exists department text not null default '';
create index if not exists user_directory_department_idx on public.user_directory (lower(department));

do $$
begin
  if to_regclass('public.master_lists') is not null then
    insert into public.master_lists (key, label, value_label, columns, sort_order)
    values ('department', 'Department', 'Department', '[]'::jsonb, 90)
    on conflict (key) do update set label = excluded.label, value_label = excluded.value_label, updated_at = now();
  end if;
end $$;

-- ------------------------------------------------------------------------
-- 0290_master_keys_split.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0290 — EDITING MASTERS, VERIFYING KYC AND THE SERVICEMAN SWAP ARE SEPARATE
--
-- Findings 57-67 (docs/PERMISSIONS_REVIEW.md), the user's decisions of
-- 2026-09-30: "63, 64: It should show the Individual View's Control Action and
-- its Check Box" -- each screen gets keys of its own, today's grants copied
-- across (0298) so nobody gains or loses anything on the day it ships -- and
-- "67: Break it down", with the old key kept as the PARENT of the new ones, so
-- a role holding it keeps everything until an administrator unticks it.
-- The parent rule itself is in has_perm() (0286, public.perm_parents).
--
-- This file: every master write rule the masters module owns asks
-- masters.edit.records; a KYC status change asks masters.edit.kyc; the bulk
-- Serviceman swap becomes swap_service_engineer() with masters.edit.swap_serviceman.
-- ===========================================================================

drop policy if exists pm_write on public.product_master;
create policy pm_write on public.product_master for all
  using ((select public.has_perm('masters.edit.records'))) with check ((select public.has_perm('masters.edit.records')));

drop policy if exists master_lists_write on public.master_lists;
create policy master_lists_write on public.master_lists for all
  using ((select public.has_perm('masters.edit.records'))) with check ((select public.has_perm('masters.edit.records')));

do $$
begin
  if to_regclass('public.product_accessories') is null then return; end if;
  drop policy if exists pa_insert on public.product_accessories;
  drop policy if exists pa_update on public.product_accessories;
  drop policy if exists pa_delete on public.product_accessories;
  create policy pa_insert on public.product_accessories for insert
    with check ((select public.has_perm('masters.edit.records')));
  create policy pa_update on public.product_accessories for update
    using ((select public.has_perm('masters.edit.records'))) with check ((select public.has_perm('masters.edit.records')));
  create policy pa_delete on public.product_accessories for delete
    using ((select public.has_perm('masters.edit.records')));
end $$;

drop policy if exists masters_insert on public.masters;
drop policy if exists masters_update on public.masters;
drop policy if exists masters_delete on public.masters;
create policy masters_insert on public.masters for insert
    with check (public.has_perm('masters.edit.records')
             or public.has_perm('master.' || coalesce(name, '') || '.edit'));

  create policy masters_update on public.masters for update
    using      (public.has_perm('masters.edit.records')
             or public.has_perm('master.' || coalesce(name, '') || '.edit'))
    with check (public.has_perm('masters.edit.records')
             or public.has_perm('master.' || coalesce(name, '') || '.edit'));

  create policy masters_delete on public.masters for delete
    using      (public.has_perm('masters.edit.records')
             or public.has_perm('master.' || coalesce(name, '') || '.delete'));

-- ---- the Serviceman swap, as one statement with its own key ---------------
-- It was a bulk UPDATE from the browser under masters.edit. Exact match on
-- the stored string, as the screen always did, so it renames nobody by
-- accident.
create or replace function public.swap_service_engineer(p_from text, p_to text)
returns integer language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  if not coalesce(public.has_perm('masters.edit.swap_serviceman'), false) then
    raise exception 'RBAC: changing the Serviceman on every party needs "Swap the Serviceman in bulk"';
  end if;
  if coalesce(p_from, '') = '' then raise exception 'Pick the name to change'; end if;
  if p_from = coalesce(p_to, '') then raise exception 'That is the same name'; end if;
  update public.parties set service_engineer = coalesce(p_to, '') where service_engineer = p_from;
  get diagnostics n = row_count;
  return n;
end $$;
revoke execute on function public.swap_service_engineer(text, text) from public, anon;
grant  execute on function public.swap_service_engineer(text, text) to authenticated;

CREATE OR REPLACE FUNCTION public.parties_kyc_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    if coalesce(btrim(new.kyc_status), '') = '' then new.kyc_status := 'Pending'; end if;
  end if;

  -- A LONE `Pincode` BESIDE AN `Inst. Pincode` IS THE BILLING ONE. The export
  -- names the installation pincode and leaves the billing one bare, so the
  -- importer cannot alias it without racing the installation column for the
  -- same heading. The pair is only ambiguous in isolation: where BOTH headings
  -- are on the row, which is which is not in doubt.
  if coalesce(btrim(new.billing_pincode), '') = ''
     and new.extra ? 'Inst. Pincode' and coalesce(btrim(new.extra ->> 'Pincode'), '') <> '' then
    new.billing_pincode := btrim(new.extra ->> 'Pincode');
  end if;

  -- THE NUMBERS ARE DERIVED HERE TOO, not only in the backfill below. An upload
  -- puts the Tax columns in `extra` and nothing else would ever read them, so a
  -- file loaded next year would land exactly as the file loaded today did
  -- BEFORE this migration — with its GSTIN sitting in a blob. Only ever fills a
  -- BLANK: a number typed on the screen is never overwritten by a spreadsheet.
  if coalesce(btrim(new.gstin), '') = '' then
    new.gstin := coalesce(public.kyc_gstin(concat_ws(' ',
      new.extra ->> 'Tax 1', new.extra ->> 'Tax 2', new.extra ->> 'Tax 3',
      new.extra ->> 'GSTIN', new.extra ->> 'GST No')), '');
  end if;
  -- AFTER the GSTIN, and reading it: a GSTIN contains a PAN at characters 3-12,
  -- so a customer who gave only a GSTIN is not asked for a PAN as well.
  if coalesce(btrim(new.pan), '') = '' then
    new.pan := coalesce(public.kyc_pan(concat_ws(' ', new.gstin,
      new.extra ->> 'Tax 1', new.extra ->> 'Tax 2', new.extra ->> 'Tax 3',
      new.extra ->> 'PAN', new.extra ->> 'PAN No')), '');
  end if;
  if new.kyc_status is distinct from (case when tg_op = 'UPDATE' then old.kyc_status else null end) then
    -- VERIFYING KYC IS ITS OWN KEY (0290). A new party starting at Pending is
    -- not a verification; the SQL editor or an import is not a caller through
    -- the API (the `role` setting survives SECURITY DEFINER).
    if tg_op = 'UPDATE' and coalesce(current_setting('role', true), 'none') in ('authenticated', 'anon') and not public.is_admin()
       and not coalesce(public.has_perm('masters.edit.kyc'), false) then
      raise exception 'RBAC: changing a party''s KYC status needs "Verify KYC"';
    end if;
    if new.kyc_status = 'Verified' then
      new.kyc_verified_by := auth.uid();
      new.kyc_verified_at := now();
    else
      -- Moving OFF Verified clears the stamp: a party sent back to Pending has
      -- not been verified by anybody, and leaving the old name on it would say
      -- it had.
      new.kyc_verified_by := null;
      new.kyc_verified_at := null;
    end if;
  end if;
  return new;
end $function$;

-- ------------------------------------------------------------------------
-- 0319_product_master_imported.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0319 — THE PRODUCT MASTER SAYS WHETHER A LINE IS IMPORTED
--
-- The user, 2026-10-02: "Pre-delivery check is done only for Imported
-- products, not for in-house manufactured equipment." Pre-Delivery Testing
-- (R/SER/QC/007) is owed by a DEMO unit in the workshop whose product line is
-- imported (0320, the indoor module), so the catalogue has to say which lines
-- are.
--
-- NULLABLE, AND BLANK UNTIL SOMEBODY FILLS IT. Nobody has said which of the 53
-- lines are imported, and a default either way would be a guess written into
-- the catalogue: TRUE would demand a test of in-house equipment, FALSE would
-- wave an imported unit out untested. NULL reads as "not known", the indoor
-- screen SAYS so on the job, and the dispatch rule treats it as not requiring
-- the test until the Product Master is filled (the user's decision).
--
-- WHO MAY SET IT: whoever may write a product line today -- pm_write, which
-- asks masters.edit.records (0290). No new key and no grant.
-- ===========================================================================

alter table public.product_master
  add column if not exists imported boolean;

comment on column public.product_master.imported is
  'Is this product line IMPORTED (true) or made in-house (false)? NULL = not recorded yet. Decides whether a DEMO unit of the line owes Pre-Delivery Testing R/SER/QC/007 before it leaves the workshop (0320); NULL is treated as not owing it, and the indoor screen says the answer is unknown.';

-- ------------------------------------------------------------------------
-- 0325_product_line_and_list_add_edit_delete.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0325 — PRODUCT MASTER AND THE VALUE LISTS: ADD, EDIT AND DELETE KEYS
--
-- The user, 2026-10-03: "One add, one edit, one delete per master" -- the
-- masters-module half of 0325_party_part_add_edit_delete.sql (rbac), which
-- holds the parents and master_delete_guard().
--
--   Product Master   masters.product_master.add / .edit / .delete, split out
--                    of pm_write (FOR ALL under masters.edit.records, 0290).
--                    A line is refused deletion while a machine, a sale or a
--                    contract names its code -- the same guard as a party.
--   A value list     master.<list>.add joins master.<list>.edit and
--                    master.<list>.delete. Adding asks the add key OR the
--                    list's edit key (its parent, as everywhere else: a role
--                    that could add values yesterday still can) OR
--                    masters.edit.records, exactly as before. Edit -- which
--                    now includes RENAMING a value, the user's choice -- and
--                    delete are unchanged.
--
-- No grant is changed.
-- ===========================================================================

drop policy if exists pm_write on public.product_master;
drop policy if exists pm_insert on public.product_master;
drop policy if exists pm_update on public.product_master;
drop policy if exists pm_delete on public.product_master;
create policy pm_insert on public.product_master for insert
  with check ((select public.has_perm('masters.product_master.add')));
create policy pm_update on public.product_master for update
  using ((select public.has_perm('masters.product_master.edit')))
  with check ((select public.has_perm('masters.product_master.edit')));
create policy pm_delete on public.product_master for delete
  using ((select public.has_perm('masters.product_master.delete')));

drop trigger if exists master_delete_guard on public.product_master;
create trigger master_delete_guard before delete on public.product_master
  for each row execute function public.master_delete_guard();

drop policy if exists masters_insert on public.masters;
create policy masters_insert on public.masters for insert
    with check (public.has_perm('masters.edit.records')
             or public.has_perm('master.' || coalesce(name, '') || '.add')
             or public.has_perm('master.' || coalesce(name, '') || '.edit'));

-- ------------------------------------------------------------------------
-- 0326_party_country.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0326 — A PARTY HAS A COUNTRY
--
-- The user, 2026-10-03: "In Party Master, City, State, Country can be in 1
-- row" -- and, asked whether to add the field the Party Master did not have:
-- "Add Country". Plain text, blank by default, so every existing party reads
-- exactly as it did; the Party Master upload fills it from a Country column,
-- and the Add / Edit forms set it.
-- ===========================================================================

alter table public.parties add column if not exists country text not null default '';

-- THE VALUE MAY ALREADY BE HERE. The Party Master export has a COUNTRY
-- heading, and with no column for it the upload kept it on the row (`extra`,
-- as it keeps every heading it cannot place). Copied across, whatever its
-- spelling of the heading; only a BLANK is filled, so a re-run, or a country
-- typed on the screen, is never overwritten. `extra` itself is left as it is.
update public.parties p
   set country = (select btrim(e.value) from jsonb_each_text(coalesce(p.extra, '{}'::jsonb)) e
                   where lower(btrim(e.key)) = 'country' and coalesce(btrim(e.value), '') <> ''
                   limit 1)
 where coalesce(btrim(p.country), '') = ''
   and exists (select 1 from jsonb_each_text(coalesce(p.extra, '{}'::jsonb)) e
                where lower(btrim(e.key)) = 'country' and coalesce(btrim(e.value), '') <> '');

-- ------------------------------------------------------------------------
-- 0366_masters_required_kyc_and_line_names.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0366 — THE MASTERS' OWN RULES IN THE DATABASE: required fields, a code that
--        differs only in case, the KYC verifier, and a product line's NAME
--        (second re-review D-058, D-138, D-140)
--
-- D-140 -- the masters' required fields and unique codes were the forms' alone.
-- Measured as a signed-in user, each accepted: a party with no city or state,
-- a party named only spaces, a part with blank code and description, a
-- product line with blank code and name, a product line 'c-named' beside
-- 'C-NAMED' (product_line_sellable('C-NAMED') then fails with "more than one
-- row returned by a subquery") and a part 'cp-r' beside 'CP-R'.
-- Now, for a signed-in caller who is not an importer:
--   * a NEW party needs a name, a city and a state (the Add form's three --
--     the user, 2026-10-03); an edit may not blank one that has a value, and
--     leaves a row that never had one alone, so an old incomplete party can
--     still be edited;
--   * a part needs a code and a description; a product line a code and a
--     name -- on insert, and an edit may not blank them;
--   * a part code or a product code that matches an EXISTING one ignoring case
--     and outer spaces, but is spelled differently, is refused: the exact
--     spelling is already unique (parts_item_detail_key_uniq, the product
--     master's primary key), so the case variant is the only duplicate left.
--     Not a unique index: one would fail this migration on a project that
--     already holds a pair, and a pair already there is not this file's to
--     choose between.
-- Imports load history as it was and are not stopped. The rule is
-- stock_import_allowed()'s (0339), written out: that function is created by a
-- LATER module, and this trigger may fire before it exists on a fresh apply.
--
-- D-058 -- parties_kyc_stamp() (0201) stamps kyc_verified_by / _at only when
-- the KYC status changes, so an UPDATE writing the verifier without changing
-- the status kept the caller's value (measured). A signed-in UPDATE that leaves
-- the status alone now keeps the verifier and time as they were. (The other
-- half of D-058, renaming a party, is refused since 0325's
-- master_key_changes_only_by_rename.)
--
-- D-138 -- a product line is matched by NAME as well as code:
-- indoor_job_product_code() (0321) and indoor_job_is_imported() (0320) read
-- product_master.product_name, and the delete guard counted only the code.
-- Measured: a line whose name indoor jobs carry, and whose code no machine
-- carries, was deleted, and the jobs lost their code. Now:
--   * product_line_name_uses(name) counts the indoor jobs naming a line by
--     that name -- 0 where another line keeps the name, since the match then
--     still resolves -- for the Product Master's rename warning;
--   * deleting a line those jobs still name is refused, in the delete guard's
--     words, by a trigger of its own (master_delete_guard is 0350's and is
--     left as it is).
-- In the masters module, after 0326.
-- ===========================================================================

-- ---- D-140 -------------------------------------------------------------------
create or replace function public.master_required_fields()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_missing text[] := '{}';
  v_other   text;
begin
  -- On INSERT a blank is refused; on UPDATE only a value being BLANKED is.
  if auth.uid() is null or public.has_perm('bulk.upload') or public.has_perm('import.panel') then return new; end if;     -- no session, or an importer

  if tg_table_name = 'parties' then
    if btrim(coalesce(new.party_name, '')) = ''
       and (tg_op = 'INSERT' or btrim(coalesce(old.party_name, '')) <> '') then
      v_missing := v_missing || 'Party Name'::text;
    end if;
    if btrim(coalesce(new.city, '')) = ''
       and (tg_op = 'INSERT' or btrim(coalesce(old.city, '')) <> '') then
      v_missing := v_missing || 'City'::text;
    end if;
    if btrim(coalesce(new.state, '')) = ''
       and (tg_op = 'INSERT' or btrim(coalesce(old.state, '')) <> '') then
      v_missing := v_missing || 'State'::text;
    end if;

  elsif tg_table_name = 'parts' then
    if btrim(coalesce(new.code, '')) = ''
       and (tg_op = 'INSERT' or btrim(coalesce(old.code, '')) <> '') then
      v_missing := v_missing || 'Part Code'::text;
    end if;
    if btrim(coalesce(new.description, '')) = ''
       and (tg_op = 'INSERT' or btrim(coalesce(old.description, '')) <> '') then
      v_missing := v_missing || 'Description'::text;
    end if;
    if btrim(coalesce(new.code, '')) <> ''
       and (tg_op = 'INSERT' or new.code is distinct from old.code) then
      select p.code into v_other from public.parts p
       where p.id is distinct from new.id
         and lower(btrim(p.code)) = lower(btrim(new.code))
         and p.code is distinct from new.code
       limit 1;
      if found then
        raise exception 'Part code % is already on the Part Master as % -- the same code spelled differently would be counted as two parts',
          btrim(new.code), v_other using errcode = '23505';
      end if;
    end if;

  elsif tg_table_name = 'product_master' then
    if btrim(coalesce(new.product_code, '')) = ''
       and (tg_op = 'INSERT' or btrim(coalesce(old.product_code, '')) <> '') then
      v_missing := v_missing || 'Product Code'::text;
    end if;
    if btrim(coalesce(new.product_name, '')) = ''
       and (tg_op = 'INSERT' or btrim(coalesce(old.product_name, '')) <> '') then
      v_missing := v_missing || 'Product Name'::text;
    end if;
    if btrim(coalesce(new.product_code, '')) <> ''
       and (tg_op = 'INSERT' or new.product_code is distinct from old.product_code) then
      select m.product_code into v_other from public.product_master m
       where m.product_code is distinct from new.product_code
         and lower(btrim(m.product_code)) = lower(btrim(new.product_code))
       limit 1;
      if found then
        raise exception 'Product code % is already on the Product Master as % -- the same code spelled differently would be two product lines',
          btrim(new.product_code), v_other using errcode = '23505';
      end if;
    end if;
  end if;

  if array_length(v_missing, 1) > 0 then
    raise exception '% cannot be blank', array_to_string(v_missing, ', ') using errcode = '23502';
  end if;
  return new;
end $$;
revoke execute on function public.master_required_fields() from public, anon, authenticated;

do $$
declare t text;
begin
  foreach t in array array['parties', 'parts', 'product_master'] loop
    execute format('drop trigger if exists master_required_fields on public.%I', t);
    execute format('create trigger master_required_fields before insert or update on public.%I '
                   'for each row execute function public.master_required_fields()', t);
  end loop;
end $$;

-- ---- D-058: the KYC verifier is the database's -------------------------------
-- Runs after parties_kyc_stamp (the name sorts after it), so a status change
-- has already been stamped and is left alone.
create or replace function public.parties_kyc_stamp_kept()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return new; end if;                 -- the SQL editor, a restore
  if new.kyc_status is not distinct from old.kyc_status then
    new.kyc_verified_by := old.kyc_verified_by;
    new.kyc_verified_at := old.kyc_verified_at;
  end if;
  return new;
end $$;
revoke execute on function public.parties_kyc_stamp_kept() from public, anon, authenticated;
drop trigger if exists parties_kyc_stamp_kept on public.parties;
create trigger parties_kyc_stamp_kept
  before update on public.parties
  for each row execute function public.parties_kyc_stamp_kept();

-- ---- D-138: a product line named by indoor jobs -------------------------------
-- How many indoor jobs would lose their match if no line carried this name any
-- more. 0 when another line (other than p_except_code) still has the name.
create or replace function public.product_line_name_uses(p_name text, p_except_code text default null)
returns bigint language plpgsql stable security definer set search_path = public as $$
declare n bigint := 0;
begin
  if btrim(coalesce(p_name, '')) = '' then return 0; end if;
  if exists (select 1 from public.product_master m
              where lower(btrim(m.product_name)) = lower(btrim(p_name))
                and (p_except_code is null or m.product_code is distinct from p_except_code)) then
    return 0;
  end if;
  if to_regclass('public.indoor_jobs') is not null then
    execute 'select count(*) from public.indoor_jobs where lower(btrim(product_name)) = lower(btrim($1))'
      into n using p_name;
  end if;
  return n;
end $$;
revoke execute on function public.product_line_name_uses(text, text) from public, anon;
grant execute on function public.product_line_name_uses(text, text) to authenticated;

create or replace function public.product_line_delete_by_name_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare n bigint;
begin
  n := public.product_line_name_uses(old.product_name, old.product_code);
  if n > 0 then
    raise exception 'This product line is still named on % record(s) — % indoor jobs (by product name). It cannot be deleted while they name it.',
      n, n using errcode = '23503';
  end if;
  return old;
end $$;
revoke execute on function public.product_line_delete_by_name_guard() from public, anon, authenticated;
drop trigger if exists product_line_delete_by_name_guard on public.product_master;
create trigger product_line_delete_by_name_guard
  before delete on public.product_master
  for each row execute function public.product_line_delete_by_name_guard();

-- ------------------------------------------------------------------------
-- 0371_master_list_delete_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0371 — DELETING A VALUE FROM A MASTER LIST NEEDS THAT LIST'S DELETE KEY,
--        NOT "ADD / EDIT MASTER RECORDS"
--        (second re-review D-086)
--
-- masters_delete (0290, re-asserted by 0121's tail) admitted
-- masters.edit.records -- labelled "Add / edit master records (parties, parts,
-- products, lists)" -- while the list screen offers Delete only to
-- master.<list>.delete, whose parent is masters.edit. Measured: a role holding
-- masters.edit.records alone deleted a value (DELETE 1) through the API that no
-- screen offered it. A key named add / edit does not delete: the policy now
-- asks the list's own delete key or masters.edit, exactly whom the screen
-- offers it to. Add and Edit are unchanged in the database; the screen now also
-- offers Edit to masters.edit.records, as masters_update already admits.
-- 0121's guarded tail carries the same text (it is checked word for word).
-- In the masters module, after 0366.
-- ===========================================================================

drop policy if exists masters_delete on public.masters;
create policy masters_delete on public.masters for delete
    using      (public.has_perm('masters.edit')
             or public.has_perm('master.' || coalesce(name, '') || '.delete'));

-- ------------------------------------------------------------------------
-- 0409_master_value_in_use_kept.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0409 — A VALUE THAT RECORDS CARRY IS DEACTIVATED, NOT DELETED
--        (second re-review D-056, FRS-015, FRS-180.6)
--
-- Master Lists offered Delete to a holder of master.<list>.delete, and
-- masters_delete checked only the permission: a Standard Complaint carried by
-- thousands of calls could be erased, and every record kept a word no list
-- holds -- every count, filter and frequent-failure match downstream runs on
-- that word. FRS-015: a value in use SHALL be deactivated rather than deleted,
-- and the database SHALL refuse the deletion of a value any record carries.
-- Deactivate already exists on the screen (masters.active): the value stays on
-- every record and stops being offered.
--
-- WHICH RECORDS CARRY WHICH LIST -- read from the columns that hold each one's
-- values, compared trimmed and case-insensitive:
--   calltype       call_requests, field/installation/pm calls, feedback,
--                  field_failure_reports, pending_registrations  .call_type
--   complaint      call_requests, field/installation/pm calls, indoor_jobs
--                  .standard_complaint
--   pendingreason  reports.pending_reason, indoor_jobs.call_pending_reason
--   cancelreason   call_requests, field/installation/pm calls .cancel_reason
--   dccrgrouping   call_reviews.complaint_grouping
--   rootcause      call_reviews.root_cause_keyword
--   department     user_directory.department
--   feedbackrating the answers of feedback (a rating is an answer's value)
--   orapproval     nothing reads it today, so nothing carries it
-- A value is "carried" only where no OTHER row of the same list holds the same
-- word: deleting one of two duplicates (a complaint listed for two products)
-- leaves the word on the list, so nothing is orphaned and it is allowed.
-- master_value_uses() COUNTS AS ITS OWNER: run as the caller, row-level
-- security would hide the records the person deleting cannot see, the count
-- would read low and a value in use elsewhere would be deleted. It returns a
-- number and nothing else.
-- Not stopped: a connection with no session and a function running as its
-- owner. In the masters module, last.
-- ===========================================================================

-- One list under two names: Standard Complaint rows are named `complaint`
-- since 0021 and may still be named `standardComplaint` (0233 can write it),
-- and the screen reads both as one list -- so does this.
create or replace function public.master_list_family(p_name text)
returns text language sql immutable set search_path = public as $$
  select case lower(btrim(coalesce(p_name, '')))
           when 'standardcomplaint' then 'complaint'
           else lower(btrim(coalesce(p_name, ''))) end
$$;
revoke execute on function public.master_list_family(text) from public, anon;
grant execute on function public.master_list_family(text) to authenticated;

create or replace function public.master_value_uses(p_name text, p_value text)
returns bigint language plpgsql stable security definer set search_path = public as $$
declare
  v    text := lower(btrim(coalesce(p_value, '')));
  n    bigint := 0;
  c    bigint;
  pair text[];
  cols text[][];
begin
  if v = '' then return 0; end if;
  cols := case public.master_list_family(p_name)
    when 'calltype' then array[['call_requests','call_type'], ['field_calls','call_type'], ['installation_calls','call_type'],
                               ['pm_calls','call_type'], ['feedback','call_type'], ['field_failure_reports','call_type'],
                               ['pending_registrations','call_type']]
    when 'complaint' then array[['call_requests','standard_complaint'], ['field_calls','standard_complaint'],
                                ['installation_calls','standard_complaint'], ['pm_calls','standard_complaint'],
                                ['indoor_jobs','standard_complaint']]
    when 'pendingreason' then array[['reports','pending_reason'], ['indoor_jobs','call_pending_reason']]
    when 'cancelreason' then array[['call_requests','cancel_reason'], ['field_calls','cancel_reason'],
                                   ['installation_calls','cancel_reason'], ['pm_calls','cancel_reason']]
    when 'dccrgrouping' then array[['call_reviews','complaint_grouping']]
    when 'rootcause' then array[['call_reviews','root_cause_keyword']]
    when 'department' then array[['user_directory','department']]
    else null end;
  if cols is not null then
    foreach pair slice 1 in array cols loop
      if to_regclass('public.' || pair[1]) is not null
         and exists (select 1 from information_schema.columns
                      where table_schema = 'public' and table_name = pair[1] and column_name = pair[2]) then
        execute format('select count(*) from public.%I where lower(btrim(%I)) = $1', pair[1], pair[2]) into c using v;
        n := n + c;
      end if;
    end loop;
  end if;
  if public.master_list_family(p_name) = 'feedbackrating' and to_regclass('public.feedback') is not null then
    select count(*) into c
      from public.feedback f
     where jsonb_typeof(f.answers) = 'object'
       and exists (select 1 from jsonb_each_text(f.answers) a where lower(btrim(a.value)) = v);
    n := n + c;
  end if;
  return n;
end $$;
revoke execute on function public.master_value_uses(text, text) from public, anon;
grant execute on function public.master_value_uses(text, text) to authenticated;

create or replace function public.master_value_in_use_kept()
returns trigger language plpgsql security invoker set search_path = public as $$
declare n bigint;
begin
  if auth.uid() is null then return old; end if;
  if current_user <> 'authenticated' then return old; end if;
  -- Another row of the same list still holds the word: nothing is orphaned.
  if exists (select 1 from public.masters m
              where public.master_list_family(m.name) = public.master_list_family(old.name) and m.id <> old.id
                and lower(btrim(m.value)) = lower(btrim(coalesce(old.value, '')))) then
    return old;
  end if;
  n := public.master_value_uses(old.name, old.value);
  if n > 0 then
    raise exception '"%" is on % record(s) and cannot be deleted -- deactivate it instead, so it stays on those records and is no longer offered',
      old.value, n using errcode = '23514';
  end if;
  return old;
end $$;
revoke execute on function public.master_value_in_use_kept() from public, anon, authenticated;
drop trigger if exists master_value_in_use_kept on public.masters;
create trigger master_value_in_use_kept
  before delete on public.masters
  for each row execute function public.master_value_in_use_kept();

-- ------------------------------------------------------------------------
-- 0070_documents.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- DOCUMENT LIBRARY — service manuals and QMS documents.
--
-- The FILES live in Google Drive (uploaded through the CallReg bridge, the same
-- path a manual report already takes); what lives here is the CATALOGUE that
-- makes one findable: which product a manual covers, its revision, and the link.
-- That is the whole point of the table — an engineer on a call must be handed
-- THE RIGHT manual for the machine in front of them, and a Drive folder cannot
-- answer that question.
--
-- One table, two kinds:
--   'service_manual' — keyed by PRODUCT; surfaced on the call as a supporting
--                      document for the machine the call is against.
--   'qms'            — the controlled quality documents (SOPs, work
--                      instructions, forms), carrying a document number,
--                      revision and effective date.
-- They differ only in which fields matter and who may maintain them, so they
-- share the table and split on `kind`.
--
-- Maintaining them is two separate rights, because they are two separate jobs:
--   docs.manage — service manuals and general documents
--   qms.manage  — the QMS shelf (quality's own)
-- Everyone signed in READS both: a manual nobody can open is no use in the
-- field, and a QMS document the team cannot find is not controlled, it is lost.
-- ===========================================================================

create table if not exists public.documents (
  id             bigint generated always as identity primary key,
  kind           text not null default 'service_manual',
  title          text not null,
  -- The product/model a manual covers. BLANK deliberately means "every
  -- product" — a general manual still has to reach every call.
  product        text not null default '',
  doc_no         text not null default '',   -- QMS document number
  revision       text not null default '',
  effective_date date,
  tags           text not null default '',   -- comma-separated, matched against a call
  url            text not null,              -- the Drive link
  file_name      text not null default '',
  notes          text not null default '',
  active         boolean not null default true,
  uploaded_by      uuid references auth.users (id),
  uploaded_by_name text not null default '',
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

alter table public.documents add column if not exists effective_date date;
alter table public.documents add column if not exists notes text not null default '';

-- A call looks a manual up BY PRODUCT, every time a call is opened, so that
-- lookup gets its own index rather than a scan of the shelf.
-- documents_kind_idx (kind) was here; a prefix of documents_dated_idx (kind, dated desc).
-- Removed 2026-10-05; 0382 drops it where it exists.
create index if not exists documents_product_idx  on public.documents (lower(product));
create index if not exists documents_active_idx   on public.documents (active);

-- Stamp who uploaded it (cannot be spoofed) and keep updated_at honest.
create or replace function public.documents_before_write()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    new.uploaded_by := coalesce(new.uploaded_by, auth.uid());
  else
    new.uploaded_by := old.uploaded_by;   -- authorship is not editable
    new.created_at  := old.created_at;
  end if;
  new.kind := lower(trim(coalesce(new.kind, 'service_manual')));
  if new.kind = '' then new.kind := 'service_manual'; end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists documents_biu on public.documents;
create trigger documents_biu before insert or update on public.documents
  for each row execute function public.documents_before_write();

alter table public.documents enable row level security;
grant select, insert, update, delete on public.documents to authenticated;

-- Read: everyone signed in, both kinds.
drop policy if exists documents_read on public.documents;
create policy documents_read on public.documents for select
  using (auth.role() = 'authenticated');

-- Write: the right that matches the kind. Admins hold both via has_perm().
drop policy if exists documents_insert on public.documents;
create policy documents_insert on public.documents for insert
  with check (case when kind = 'qms' then public.has_perm('qms.manage')
                   else public.has_perm('docs.manage') end);

-- Both sides tested, so a document cannot be moved between shelves by someone
-- who may only maintain one of them.
drop policy if exists documents_update on public.documents;
create policy documents_update on public.documents for update
  using      (case when kind = 'qms' then public.has_perm('qms.manage')
                   else public.has_perm('docs.manage') end)
  with check (case when kind = 'qms' then public.has_perm('qms.manage')
                   else public.has_perm('docs.manage') end);

drop policy if exists documents_delete on public.documents;
create policy documents_delete on public.documents for delete
  using (case when kind = 'qms' then public.has_perm('qms.manage')
              else public.has_perm('docs.manage') end);

-- ---------------------------------------------------------------------------
-- Grant the new rights to the roles that already do this work, by MERGING into
-- app_roles — never by overwriting, since an admin may have tuned the role.
-- Service manuals: the roles that maintain masters. QMS: admin only, until
-- quality says who else keeps it.
-- ---------------------------------------------------------------------------
do $$
declare r record;
begin
  if to_regclass('public.app_roles') is null then
    raise notice 'public.app_roles is not present — run the rbac bundle first';
    return;
  end if;

  for r in select role, coalesce(permissions, '[]'::jsonb) as perms from public.app_roles loop
    if r.role in ('admin', 'hotline', 'nsm', 'spare_coordinator')
       and not (r.perms ? 'docs.manage') then
      update public.app_roles
         set permissions = r.perms || '["docs.manage"]'::jsonb, updated_at = now()
       where role = r.role;
    end if;
    if r.role = 'admin' and not (r.perms ? 'qms.manage') then
      update public.app_roles
         set permissions = coalesce(permissions, '[]'::jsonb) || '["qms.manage"]'::jsonb, updated_at = now()
       where role = r.role;
    end if;
  end loop;

  -- And the modules themselves, so the two screens are reachable at all.
  update public.app_roles
     set permissions = coalesce(permissions, '[]'::jsonb) || '["mod:/service-manuals"]'::jsonb, updated_at = now()
   where not (coalesce(permissions, '[]'::jsonb) ? 'mod:/service-manuals');
  update public.app_roles
     set permissions = coalesce(permissions, '[]'::jsonb) || '["mod:/qms"]'::jsonb, updated_at = now()
   where role in ('admin', 'nsm', 'hotline')
     and not (coalesce(permissions, '[]'::jsonb) ? 'mod:/qms');
end $$;

-- ------------------------------------------------------------------------
-- 0265_qms_document_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- QMS DOCUMENTS BY BULK UPLOAD -- the Master List.
--
--   The user, 2026-09-30: "I want to be able to do a bulk upload on QMS
--   Documents. 99% it will be a One Time Activity, the QMS Department has a
--   Specific format to maintain the MasterList." What goes up: the Master List
--   with each document's Drive URL (the files are already on Drive).
--
-- TWO THINGS THE UPLOAD NEEDS:
--
--   * A KEY, so a re-load CORRECTS a row instead of adding a second copy of
--     the document: the document number + revision, on the QMS shelf only.
--     NULL for anything without a number (every service manual, and a QMS row
--     typed without one), and NULLs never collide -- so the index constrains
--     exactly the rows the Master List can name, and is a plain unique index
--     PostgREST can infer (check:upserts), not a partial one.
--   * SOMEWHERE FOR THE MASTER LIST'S OWN COLUMNS. Its format is the QMS
--     department's; every heading with no column here is kept in `extra`
--     under its own spelling rather than dropped.
--
-- IF TWO QMS ROWS ALREADY SHARE A NUMBER AND REVISION, the index cannot be
-- built, and this says so instead of failing: nothing is deleted or merged
-- (quality records are never deleted) -- retire or correct one of them on the
-- QMS Documents screen and run this again. _status.sql row 205 checks it.
-- ===========================================================================

alter table public.documents add column if not exists extra jsonb not null default '{}'::jsonb;
alter table public.documents add column if not exists doc_key text generated always as (
  case when kind = 'qms' and btrim(doc_no) <> ''
       then lower(btrim(doc_no)) || '|' || lower(btrim(revision)) end) stored;

do $$
declare dup text;
begin
  if exists (select 1 from pg_indexes where schemaname = 'public' and indexname = 'documents_doc_key_uniq') then
    return;
  end if;
  select string_agg(doc_key, ', ') into dup
    from (select doc_key from public.documents where doc_key is not null
           group by doc_key having count(*) > 1 limit 20) x;
  if dup is not null then
    raise notice '0265: QMS documents share a number + revision (%); the upload key was NOT created. Correct them and run again.', dup;
    return;
  end if;
  create unique index documents_doc_key_uniq on public.documents (doc_key);
end $$;

-- ------------------------------------------------------------------------
-- 0272_service_note_upload_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- TECHNICAL / SERVICE NOTES BY BULK UPLOAD -- a key for re-loading the list.
--
--   The user, 2026-09-30, pasting the Drive listing of the Technical Note
--   folder: "Normalise this for bulk upload". The shelf itself exists since
--   v0.10.6 (documents kind 'service_note', no migration); what a bulk load
--   needs is a KEY, so loading the list a second time CORRECTS those rows
--   instead of adding a second copy of every note.
--
-- THE KEY IS THE DRIVE LINK. A note has no controlled number and revision the
-- way a QMS document does (0265): the listing's file names carry a number
-- sometimes and a revision rarely, and two different notes are filed under the
-- same number in two product folders (NT606 is under Extend-XT AND Monnal
-- T75). What names ONE file unambiguously is its Drive link. So url_key is the
-- link, lower-cased and trimmed, for SERVICE NOTES ONLY -- NULL for every other
-- kind, and NULLs never collide, so the index constrains exactly the rows this
-- upload writes and is a plain unique index PostgREST can infer.
--
-- IF TWO NOTES ALREADY SHARE A LINK the index cannot be built; this says so
-- instead of failing, and nothing is deleted. _status.sql row 212 checks it.
-- ===========================================================================

alter table public.documents add column if not exists url_key text generated always as (
  case when kind = 'service_note' and btrim(url) <> '' then lower(btrim(url)) end) stored;

do $$
declare dup text;
begin
  if exists (select 1 from pg_indexes where schemaname = 'public' and indexname = 'documents_url_key_uniq') then
    return;
  end if;
  select string_agg(url_key, ', ') into dup
    from (select url_key from public.documents where url_key is not null
           group by url_key having count(*) > 1 limit 20) x;
  if dup is not null then
    raise notice '0272: service notes share a Drive link (%); the upload key was NOT created. Retire one of each and run again.', dup;
    return;
  end if;
  create unique index documents_url_key_uniq on public.documents (url_key);
end $$;

-- ------------------------------------------------------------------------
-- 0299_document_drive_details.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A TECHNICAL / SERVICE NOTE CARRIES ITS DRIVE DETAILS.
--
--   The user, 2026-09-30, after loading the Technical Note list: "I didn't
--   want this '30-Sep-2026 10:27:25' in the updated date and time -- it has to
--   reflect the Meta data from Drive. Added also has to be mapped per the Drive
--   Details." Their answers: the shelf shows Added = Drive's Created,
--   Added By = Drive's Last Modified By, Updated = Drive's Last Modified; and
--   RITHI's own record of who loaded it and when is KEPT, shown in the record
--   details rather than the table.
--
-- SO THESE ARE THREE NEW COLUMNS, NOT created_at / updated_at REWRITTEN.
-- created_at, updated_at and uploaded_by answer "when and by whom was this
-- entered HERE" -- documents_before_write() (0070) stamps them and that is the
-- audit trail. What Drive says about the FILE is a different fact about a
-- different thing, and putting it in those columns would lose the first to
-- record the second. Blank for anything not loaded from a Drive listing.
-- ===========================================================================

alter table public.documents add column if not exists source_created_at  timestamptz;
alter table public.documents add column if not exists source_modified_at timestamptz;
alter table public.documents add column if not exists source_modified_by text not null default '';

comment on column public.documents.source_created_at  is 'Drive''s Created date-time of the file, from the listing it was loaded from (0299). Not when it was entered here -- that is created_at.';
comment on column public.documents.source_modified_at is 'Drive''s Last Modified date-time of the file (0299). Not when the row was last changed here -- that is updated_at.';
comment on column public.documents.source_modified_by is 'Drive''s Last Modified By, as the listing wrote it (0299). Not who entered it here -- that is uploaded_by.';

-- ------------------------------------------------------------------------
-- 0354_service_note_dated_latest.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- TECHNICAL / SERVICE NOTES: A DATE OF THEIR OWN, AND THE LATEST ONE PER
-- PRODUCT MARKED.
--
-- The user, 2026-10-04: "Group it as Per Product. Add a Column [Dated], which
-- I will update manually. Sort it by Dated, Newest to Oldest. Automatically add
-- a Tag as Latest. When I add a new Technical Note for the Product, these Auto
-- Tags should reset and update according to the Latest. I should have a Button
-- to Trigger this correction."  Settled with the user the same day:
--   * a note covering several products is listed under EACH of them, and may
--     be the latest for one and not another -- so the mark is PER PRODUCT;
--   * a note with no product is the "Every product" group (token '');
--   * only a LIVE note with a Dated can be the latest -- a note not yet dated,
--     or retired, is never marked; two live notes on the same newest date are
--     both marked;
--   * the mark is STORED, recalculated automatically, and on demand by a button.
--
-- documents.dated       the date the user gives the note, by hand. Not
--                       effective_date (the QMS field) and not created_at (when
--                       it was entered here) -- a note entered today may be
--                       dated years ago.
-- documents.latest_for  the products this note is currently the latest for,
--                       spelled as on the note; '' stands for "Every product".
--                       Written ONLY by refresh_service_note_latest_all().
--
-- WHEN IT RECALCULATES: a statement-level trigger after any insert or delete of
-- a document, and after an update of kind / product / dated / active -- so a
-- bulk upload of 300 notes recalculates once, and the recalculation's own write
-- (latest_for only) does not fire it again. The Refresh button calls
-- refresh_service_note_latest(), which asks for docs.manage and does the same.
-- Only rows whose mark actually changes are written.
-- ===========================================================================

alter table public.documents add column if not exists dated date;
alter table public.documents add column if not exists latest_for text[] not null default '{}';

comment on column public.documents.dated is
  'Technical / Service Notes: the note''s own date, entered by hand. Orders the shelf (newest first) and decides which note is the latest per product (0354).';
comment on column public.documents.latest_for is
  'Technical / Service Notes: the products this note is the latest for ('''' = every product). Written only by refresh_service_note_latest_all() (0354).';

create index if not exists documents_dated_idx on public.documents (kind, dated desc);

-- THE RECALCULATION. Products are split exactly as the screen splits them
-- (comma, semicolon, bar, newline; trimmed; blanks dropped) and compared
-- case-insensitively, so "MONNAL T60" and "Monnal T60" are one product.
create or replace function public.refresh_service_note_latest_all()
returns integer language plpgsql security definer set search_path = public as $$
declare v_changed integer;
begin
  with note_products as (
    select d.id, d.dated,
           coalesce(nullif(btrim(p.prod), ''), '') as prod
      from public.documents d
      left join lateral regexp_split_to_table(coalesce(d.product, ''), '[,;|\n]') as p(prod) on true
     where d.kind = 'service_note' and d.active and d.dated is not null
  ),
  -- A note with products listed has '' rows only from blank pieces; drop
  -- those unless the note names no product at all.
  cleaned as (
    select np.* from note_products np
     where np.prod <> ''
        or not exists (select 1 from note_products o where o.id = np.id and o.prod <> '')
  ),
  newest as (
    select lower(prod) as k, max(dated) as top from cleaned group by lower(prod)
  ),
  marks as (
    select c.id, array_agg(distinct c.prod order by c.prod) as latest
      from cleaned c join newest n on n.k = lower(c.prod) and n.top = c.dated
     group by c.id
  ),
  target as (
    select d.id, coalesce(m.latest, '{}'::text[]) as latest
      from public.documents d left join marks m on m.id = d.id
     where d.kind = 'service_note'
  )
  update public.documents d set latest_for = t.latest
    from target t
   where t.id = d.id and d.latest_for is distinct from t.latest;
  get diagnostics v_changed = row_count;
  return v_changed;
end $$;

revoke execute on function public.refresh_service_note_latest_all() from public, anon, authenticated;

-- THE BUTTON. The same work, for whoever may maintain the shelf.
create or replace function public.refresh_service_note_latest()
returns integer language plpgsql security definer set search_path = public as $$
begin
  if not public.has_perm('docs.manage') then
    raise exception 'Your role does not have permission for this action' using errcode = '42501';
  end if;
  return public.refresh_service_note_latest_all();
end $$;

revoke execute on function public.refresh_service_note_latest() from public, anon;
grant execute on function public.refresh_service_note_latest() to authenticated;

create or replace function public.documents_refresh_latest()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.refresh_service_note_latest_all();
  return null;
end $$;

revoke execute on function public.documents_refresh_latest() from public, anon, authenticated;

drop trigger if exists zz_service_note_latest_ins on public.documents;
create trigger zz_service_note_latest_ins after insert or delete on public.documents
  for each statement execute function public.documents_refresh_latest();
drop trigger if exists zz_service_note_latest_upd on public.documents;
create trigger zz_service_note_latest_upd after update of kind, product, dated, active on public.documents
  for each statement execute function public.documents_refresh_latest();

-- The notes already on the shelf: none has a Dated yet, so this marks nothing
