select public.refresh_service_note_latest_all();

-- ------------------------------------------------------------------------
-- 0356_service_notes_batch_save.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- TECHNICAL / SERVICE NOTES: MANY EDITS, ONE SAVE.
--
-- The user, 2026-10-04: "Give me a Beta Edit -- like one click at the top,
-- make all changes and 1 Save saves all the changes done."
--
-- save_service_notes(p_rows jsonb) takes an array of {id, <field>: <value>...}
-- and writes every one in ONE transaction: all of it, or -- on the first
-- refusal -- none of it, so a half-applied batch cannot happen.
--
-- SECURITY INVOKER, deliberately: the documents_update policy (0070) decides
-- exactly as it does for one edit -- docs.manage for a note. A row the policy
-- refuses matches nothing and Postgres raises no error (finding 48), so each
-- UPDATE is counted and a miss STOPS the batch with the note's id, instead of
-- the batch reporting a refused edit as saved.
--
-- Only the fields a note carries are written, and only those present in the
-- element: title, product, doc_no, revision, effective_date, dated, tags,
-- notes, url, file_name, extra. A date sent blank is cleared. Title and link
-- may not be blanked -- the same rule as the form. kind, active and the Drive
-- facts are not writable here. Changing dated or product fires 0354's trigger
-- and the Latest marks follow.
-- ===========================================================================

create or replace function public.save_service_notes(p_rows jsonb)
returns integer language plpgsql security invoker set search_path = public as $$
declare
  r     jsonb;
  v_id  bigint;
  v_n   integer := 0;
  v_hit integer;
begin
  if jsonb_typeof(p_rows) is distinct from 'array' then
    raise exception 'save_service_notes expects an array of notes' using errcode = '22023';
  end if;

  for r in select * from jsonb_array_elements(p_rows) loop
    v_id := nullif(r->>'id', '')::bigint;
    if v_id is null then
      raise exception 'A note in the batch has no id' using errcode = '22023';
    end if;
    if (r ? 'title' and btrim(coalesce(r->>'title', '')) = '')
       or (r ? 'url' and btrim(coalesce(r->>'url', '')) = '') then
      raise exception 'Note % needs a title and a link -- nothing was saved', v_id using errcode = '23514';
    end if;
    if r ? 'extra' and jsonb_typeof(r->'extra') is distinct from 'object' then
      raise exception 'Note %: extra must be an object', v_id using errcode = '22023';
    end if;

    update public.documents d set
      title          = case when r ? 'title'          then btrim(r->>'title')                          else d.title end,
      product        = case when r ? 'product'        then coalesce(r->>'product', '')                 else d.product end,
      doc_no         = case when r ? 'doc_no'         then coalesce(btrim(r->>'doc_no'), '')           else d.doc_no end,
      revision       = case when r ? 'revision'       then coalesce(btrim(r->>'revision'), '')         else d.revision end,
      effective_date = case when r ? 'effective_date' then nullif(r->>'effective_date', '')::date      else d.effective_date end,
      dated          = case when r ? 'dated'          then nullif(r->>'dated', '')::date               else d.dated end,
      tags           = case when r ? 'tags'           then coalesce(btrim(r->>'tags'), '')             else d.tags end,
      notes          = case when r ? 'notes'          then coalesce(btrim(r->>'notes'), '')            else d.notes end,
      url            = case when r ? 'url'            then btrim(r->>'url')                            else d.url end,
      file_name      = case when r ? 'file_name'      then coalesce(btrim(r->>'file_name'), '')        else d.file_name end,
      extra          = case when r ? 'extra'          then r->'extra'                                  else d.extra end,
      updated_at     = now()
     where d.id = v_id and d.kind = 'service_note';
    get diagnostics v_hit = row_count;
    if v_hit = 0 then
      raise exception 'Note % was not saved -- it no longer exists, or your role may not edit it. Nothing in this batch was saved.', v_id
        using errcode = '42501';
    end if;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

revoke execute on function public.save_service_notes(jsonb) from public, anon;
grant execute on function public.save_service_notes(jsonb) to authenticated;

comment on function public.save_service_notes(jsonb) is
  'Technical / Service Notes Beta Edit: writes every edited note in one transaction under the caller''s own rights (documents_update), all or nothing (0356).';

-- ------------------------------------------------------------------------
-- 0368_qms_revision_is_a_new_entry.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0368 — A QMS DOCUMENT'S REVISION IS A NEW ENTRY, NOT AN EDIT, AND A QMS
--        DOCUMENT IS RETIRED, NEVER DELETED
--        (second re-review D-061)
--
-- documents_update (0070) let any holder of qms.manage save number, revision,
-- effective date and link over an existing QMS row, and documents_delete let
-- them delete it. Measured: revision 01 changed to 02 in place, effective
-- date cleared, link replaced -- UPDATE 1. What was in force on a date was
-- replaced rather than retired; the screen's own guidance says to publish a
-- new revision as a new entry, and nothing held it.
--
-- For a QMS document (kind = 'qms'), signed in and not an importer:
--   * a NEW one needs its document number, revision and effective date;
--   * on an existing one, Document No, Revision, Effective date and the file
--     (url) may be FILLED where blank and are otherwise fixed -- a new revision
--     is added as a new entry and the old one retired (Retire sets active);
--     title, tags, notes, Live / Retired stay editable;
--   * it is not deleted: a quality record is retired (the 0049 rule);
--   * a document cannot be moved into or out of the QMS shelf.
-- Service manuals and technical notes are untouched. Imports (bulk.upload /
-- import.panel) and a connection with no session load history as it was --
-- stock_import_allowed()'s rule (0339), written out because that function is
-- created by a later module.
-- In the documents module, after 0356.
-- ===========================================================================

create or replace function public.qms_document_controlled()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_changed text[] := '{}';
begin
  if auth.uid() is null or public.has_perm('bulk.upload') or public.has_perm('import.panel') then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if tg_op = 'DELETE' then
    if old.kind = 'qms' then
      raise exception 'A QMS document is a quality record: it is retired (Retire), not deleted'
        using errcode = '42501';
    end if;
    return old;
  end if;

  if tg_op = 'UPDATE' and (old.kind = 'qms') is distinct from (new.kind = 'qms') then
    raise exception 'A document is not moved into or out of the QMS shelf -- add it there as a new entry'
      using errcode = '42501';
  end if;
  if new.kind is distinct from 'qms' then return new; end if;

  if tg_op = 'INSERT' then
    if btrim(coalesce(new.doc_no, '')) = '' or btrim(coalesce(new.revision, '')) = '' or new.effective_date is null then
      raise exception 'A QMS document needs its Document No, Revision and Effective date'
        using errcode = '23502';
    end if;
    return new;
  end if;

  -- UPDATE: a controlled field may be filled where blank, never changed.
  if btrim(coalesce(old.doc_no, '')) <> '' and btrim(coalesce(new.doc_no, '')) is distinct from btrim(old.doc_no) then
    v_changed := v_changed || 'Document No'::text;
  end if;
  if btrim(coalesce(old.revision, '')) <> '' and btrim(coalesce(new.revision, '')) is distinct from btrim(old.revision) then
    v_changed := v_changed || 'Revision'::text;
  end if;
  if old.effective_date is not null and new.effective_date is distinct from old.effective_date then
    v_changed := v_changed || 'Effective date'::text;
  end if;
  if btrim(coalesce(old.url, '')) <> '' and btrim(coalesce(new.url, '')) is distinct from btrim(old.url) then
    v_changed := v_changed || 'the file'::text;
  end if;
  if array_length(v_changed, 1) > 0 then
    raise exception 'A QMS document''s % is fixed once recorded -- add the new revision as a new entry and retire this one',
      array_to_string(v_changed, ', ') using errcode = '42501';
  end if;
  return new;
end $$;
revoke execute on function public.qms_document_controlled() from public, anon, authenticated;
drop trigger if exists qms_document_controlled on public.documents;
create trigger qms_document_controlled
  before insert or update or delete on public.documents
  for each row execute function public.qms_document_controlled();

-- ------------------------------------------------------------------------
-- 0264_people_and_training.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A PERSON'S PROFILE, THEIR ROLES & RESPONSIBILITIES, AND THEIR TRAINING.
--
--   The user, 2026-09-30:
--   Feature 1 -- "Add a Provision to Add Roles and Responsibilities attachments
--   in User Master. Attachment Option [With Effective Date]; if I update a new
--   Roles and Responsibilities then I should be able to update the Period
--   [From, To]. Give me a Provision to See the User's Details -- Joining Date,
--   Reporting Manager, Employee Code, Mail ID, Roles & Responsibilities."
--   Feature 2 -- "Add a Training Module; it should Trigger Training if a New
--   QMS document is Uploaded; Bulk Training. ... If a User is given Training on
--   a Specific topic then it should list all Past Training details."
--
-- THE USER'S ANSWERS, which this file implements and nothing more:
--   * A new R&R AUTO-CLOSES the previous one: its To becomes the day before the
--     new one's From. Every period stays editable; nothing is deleted.
--   * Who is trained on a QMS document is CHOSEN AT UPLOAD (roles,
--     designations, departments, regions or named people).
--   * Completion is recorded FOUR ways: a trainer's session (bulk attendance),
--     the trainee's own "read & understood", an attendance sheet / certificate
--     attached to the session, and an assessment (Pass / Fail, score).
--   * An assignment is COMPLETE when the person ATTENDED a session on it, or
--     ACKNOWLEDGED reading it -- and a recorded FAIL keeps it open until a
--     later session is attended without one.
--   * Profile details are seen by THE PERSON, THEIR MANAGERS (the reporting
--     tree), USER MASTER ADMINS (users.manage) and whoever holds the new
--     `training.manage`.
--   * `training.manage` and the screen key go to admin (by has_perm) and to
--     the VP Technical and R&D Engineer roles -- the ONLY roles the user has
--     allowed to be changed. No other role is touched.
--
-- WHY THE PROFILE IS ITS OWN TABLE: `user_directory` is readable by everyone
-- signed in (it drives the reporting tree). Joining date and employee code are
-- not for everyone, so they live in `user_profile`, readable by the audience
-- above only. Department stays on the directory (0263): it is not private and
-- the training audience picker needs it.
--
-- QUALITY RECORDS ARE NEVER DELETED: no delete policy on any table here. A
-- wrong assignment is CANCELLED with a reason, a wrong R&R period is corrected.
-- ===========================================================================

-- ---- who may see a person's profile, R&R and training ----------------------
-- ONE RULE, used by every policy below. DEFINER because it reads the directory
-- and the reporting tree; the permission test is inside it.
create or replace function public.may_see_person(p_dir_id bigint)
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_perm('users.manage')
      or public.has_perm('training.manage')
      or exists (
           select 1 from public.user_directory d
            where d.id = p_dir_id
              and ( (btrim(coalesce(d.email, '')) <> '' and lower(d.email) = lower(auth.email()))
                 or (btrim(coalesce(d.gmail, '')) <> '' and lower(d.gmail) = lower(auth.email()))
                 or d.name in (select public.visible_engineer_names()) ));
$$;
revoke execute on function public.may_see_person(bigint) from public, anon;
grant execute on function public.may_see_person(bigint) to authenticated;

-- ---- the private profile ---------------------------------------------------
create table if not exists public.user_profile (
  dir_id        bigint primary key references public.user_directory (id) on delete cascade,
  employee_code text not null default '',
  joining_date  date,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create unique index if not exists user_profile_employee_code_uniq
  on public.user_profile (lower(btrim(employee_code))) where btrim(employee_code) <> '';

alter table public.user_profile enable row level security;
drop policy if exists up_read on public.user_profile;
create policy up_read on public.user_profile for select to authenticated
  using (public.may_see_person(dir_id));
drop policy if exists up_insert on public.user_profile;
create policy up_insert on public.user_profile for insert to authenticated
  with check ((select public.has_perm('users.manage')));
drop policy if exists up_update on public.user_profile;
create policy up_update on public.user_profile for update to authenticated
  using ((select public.has_perm('users.manage'))) with check ((select public.has_perm('users.manage')));
grant select, insert, update on public.user_profile to authenticated;
revoke all on public.user_profile from anon;

-- ---- roles & responsibilities, one row per period ---------------------------
create table if not exists public.user_rr (
  id               bigint generated always as identity primary key,
  dir_id           bigint not null references public.user_directory (id) on delete cascade,
  title            text not null default 'Roles & Responsibilities',
  url              text not null,                -- the Drive link
  file_name        text not null default '',
  effective_from   date not null,
  effective_to     date,                          -- open = current
  notes            text not null default '',
  uploaded_by      uuid default auth.uid(),
  uploaded_by_name text not null default '',
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  constraint user_rr_period check (effective_to is null or effective_to >= effective_from)
);
create index if not exists user_rr_dir_idx on public.user_rr (dir_id, effective_from desc);

-- A NEW R&R CLOSES THE ONE BEFORE IT (the user's choice): every earlier period
-- of the same person still open on or after the new From ends the day before.
-- An earlier-dated entry added later closes nothing that starts after it.
create or replace function public.user_rr_close_previous()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.user_rr
     set effective_to = new.effective_from - 1, updated_at = now()
   where dir_id = new.dir_id and id <> new.id
     and effective_from < new.effective_from
     and (effective_to is null or effective_to >= new.effective_from);
  return null;
end $$;
revoke execute on function public.user_rr_close_previous() from public, anon, authenticated;
drop trigger if exists user_rr_close_previous on public.user_rr;
create trigger user_rr_close_previous after insert on public.user_rr
  for each row execute function public.user_rr_close_previous();

create or replace function public.user_rr_touch()
returns trigger language plpgsql as $$
begin
  if tg_op = 'UPDATE' then new.created_at := old.created_at; new.uploaded_by := old.uploaded_by; end if;
  if tg_op = 'INSERT' then new.uploaded_by := auth.uid(); end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists user_rr_touch on public.user_rr;
create trigger user_rr_touch before insert or update on public.user_rr
  for each row execute function public.user_rr_touch();

alter table public.user_rr enable row level security;
drop policy if exists rr_read on public.user_rr;
create policy rr_read on public.user_rr for select to authenticated using (public.may_see_person(dir_id));
drop policy if exists rr_insert on public.user_rr;
create policy rr_insert on public.user_rr for insert to authenticated
  with check ((select public.has_perm('users.manage')) or (select public.has_perm('training.manage')));
drop policy if exists rr_update on public.user_rr;
create policy rr_update on public.user_rr for update to authenticated
  using ((select public.has_perm('users.manage')) or (select public.has_perm('training.manage')))
  with check ((select public.has_perm('users.manage')) or (select public.has_perm('training.manage')));
grant select, insert, update on public.user_rr to authenticated;
revoke all on public.user_rr from anon;

-- ---- training: sessions (bulk), attendance, assignments ---------------------
create table if not exists public.training_sessions (
  id             bigint generated always as identity primary key,
  topic          text not null,
  document_id    bigint references public.documents (id),   -- the QMS document, when it is one
  session_date   date not null,
  trainer        text not null default '',
  method         text not null default '',   -- Classroom / Online / Read & Understand / On the job
  duration_hours numeric,
  notes          text not null default '',
  -- The attendance sheet / certificates: [{ name, url, at, by }] (the 0231 pattern).
  attachments    jsonb not null default '[]'::jsonb,
  created_by     uuid default auth.uid(),
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  constraint training_sessions_attachments_array check (jsonb_typeof(attachments) = 'array')
);
create index if not exists training_sessions_doc_idx on public.training_sessions (document_id);
create index if not exists training_sessions_topic_idx on public.training_sessions (lower(topic));

create table if not exists public.training_attendance (
  id          bigint generated always as identity primary key,
  session_id  bigint not null references public.training_sessions (id),
  dir_id      bigint not null references public.user_directory (id),
  attended    boolean not null default true,
  assessment  text not null default '',       -- '' (not assessed) / Pass / Fail
  score       numeric,
  remarks     text not null default '',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint training_attendance_assessment check (assessment in ('', 'Pass', 'Fail'))
);
create unique index if not exists training_attendance_session_person
  on public.training_attendance (session_id, dir_id);
create index if not exists training_attendance_person_idx on public.training_attendance (dir_id);

create table if not exists public.training_assignments (
  id               bigint generated always as identity primary key,
  dir_id           bigint not null references public.user_directory (id),
  document_id      bigint references public.documents (id),
  topic            text not null,
  -- ONE ASSIGNMENT PER PERSON PER DOCUMENT (or per topic, without one), so
  -- assigning the same document twice cannot make two open items.
  topic_key        text generated always as (coalesce(document_id::text, 'topic:' || lower(btrim(topic)))) stored,
  due_date         date,
  assigned_by      uuid default auth.uid(),
  assigned_by_name text not null default '',
  assigned_at      timestamptz not null default now(),
  acknowledged_at  timestamptz,               -- the trainee's "read & understood"
  cancelled        boolean not null default false,
  cancel_reason    text not null default '',
  updated_at       timestamptz not null default now()
);
create unique index if not exists training_assignments_person_topic
  on public.training_assignments (dir_id, topic_key);
create index if not exists training_assignments_doc_idx on public.training_assignments (document_id);

create or replace function public.training_touch()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  if tg_op = 'UPDATE' and tg_table_name = 'training_assignments' then
    new.assigned_at := old.assigned_at; new.assigned_by := old.assigned_by;
  end if;
  if tg_op = 'INSERT' and tg_table_name = 'training_assignments' then new.assigned_by := auth.uid(); end if;
  if tg_op = 'UPDATE' and tg_table_name = 'training_sessions' then
    new.created_at := old.created_at; new.created_by := old.created_by;
  end if;
  if tg_op = 'INSERT' and tg_table_name = 'training_sessions' then new.created_by := auth.uid(); end if;
  return new;
end $$;
drop trigger if exists training_sessions_touch on public.training_sessions;
create trigger training_sessions_touch before insert or update on public.training_sessions
  for each row execute function public.training_touch();
drop trigger if exists training_attendance_touch on public.training_attendance;
create trigger training_attendance_touch before insert or update on public.training_attendance
  for each row execute function public.training_touch();
drop trigger if exists training_assignments_touch on public.training_assignments;
create trigger training_assignments_touch before insert or update on public.training_assignments
  for each row execute function public.training_touch();

alter table public.training_sessions   enable row level security;
alter table public.training_attendance enable row level security;
alter table public.training_assignments enable row level security;

-- Sessions: what was taught, when and by whom -- no personal data, so everyone
-- signed in reads them (a trainee's history names the session). Written by
-- training.manage.
drop policy if exists ts_read on public.training_sessions;
create policy ts_read on public.training_sessions for select to authenticated using (true);
drop policy if exists ts_insert on public.training_sessions;
create policy ts_insert on public.training_sessions for insert to authenticated
  with check ((select public.has_perm('training.manage')));
drop policy if exists ts_update on public.training_sessions;
create policy ts_update on public.training_sessions for update to authenticated
  using ((select public.has_perm('training.manage'))) with check ((select public.has_perm('training.manage')));

-- Attendance: per person, so read by who may see that person.
drop policy if exists ta_read on public.training_attendance;
create policy ta_read on public.training_attendance for select to authenticated using (public.may_see_person(dir_id));
drop policy if exists ta_insert on public.training_attendance;
create policy ta_insert on public.training_attendance for insert to authenticated
  with check ((select public.has_perm('training.manage')));
drop policy if exists ta_update on public.training_attendance;
create policy ta_update on public.training_attendance for update to authenticated
  using ((select public.has_perm('training.manage'))) with check ((select public.has_perm('training.manage')));

-- Assignments: read as attendance. CREATED by training.manage OR by whoever
-- uploads the QMS document (qms.manage) -- the audience is chosen AT UPLOAD.
-- Changed (cancel, due date) by training.manage; the trainee's acknowledgement
-- goes through acknowledge_training(), never a plain update.
drop policy if exists tg_read on public.training_assignments;
create policy tg_read on public.training_assignments for select to authenticated using (public.may_see_person(dir_id));
drop policy if exists tg_insert on public.training_assignments;
create policy tg_insert on public.training_assignments for insert to authenticated
  with check ((select public.has_perm('training.manage')) or (select public.has_perm('qms.manage')));
drop policy if exists tg_update on public.training_assignments;
create policy tg_update on public.training_assignments for update to authenticated
  using ((select public.has_perm('training.manage'))) with check ((select public.has_perm('training.manage')));

grant select, insert, update on public.training_sessions, public.training_attendance, public.training_assignments to authenticated;
revoke all on public.training_sessions, public.training_attendance, public.training_assignments from anon;

-- ---- "I have read and understood" --------------------------------------------
-- The trainee's OWN assignment only, found by their sign-in address. DEFINER
-- with the ownership test inside: a plain UPDATE policy for trainees would let
-- them change the due date or cancel their own training too.
create or replace function public.acknowledge_training(p_id bigint)
returns timestamptz language plpgsql security definer set search_path = public as $$
declare t timestamptz;
begin
  update public.training_assignments a
     set acknowledged_at = coalesce(a.acknowledged_at, now())
   where a.id = p_id and not a.cancelled
     and exists (select 1 from public.user_directory d
                  where d.id = a.dir_id
                    and ( (btrim(coalesce(d.email, '')) <> '' and lower(d.email) = lower(auth.email()))
                       or (btrim(coalesce(d.gmail, '')) <> '' and lower(d.gmail) = lower(auth.email())) ))
  returning a.acknowledged_at into t;
  if t is null then
    raise exception 'This training is not assigned to you, or it was cancelled.' using errcode = '42501';
  end if;
  return t;
end $$;
revoke execute on function public.acknowledge_training(bigint) from public, anon;
grant execute on function public.acknowledge_training(bigint) to authenticated;

-- ---- the state of every assignment -------------------------------------------
-- COMPLETE = attended a session on the same document (or the same topic, where
-- there is no document) without a Fail, OR acknowledged reading it with no
-- Fail recorded. A Fail keeps it open ("Failed - retrain") until a session is
-- attended without one. security_invoker: the caller's own policies bound it.
create or replace view public.training_status with (security_invoker = on) as
select a.id, a.dir_id, d.name as person, d.designation, d.department, d.region,
       a.document_id, doc.doc_no, doc.revision, a.topic, a.due_date, a.assigned_at,
       a.assigned_by_name, a.acknowledged_at, a.cancelled, a.cancel_reason,
       ok.session_date as attended_on,
       case
         when a.cancelled then 'Cancelled'
         when ok.session_date is not null then 'Completed'
         when a.acknowledged_at is not null and not coalesce(bad.failed, false) then 'Completed'
         when coalesce(bad.failed, false) then 'Failed - retrain'
         when a.due_date is not null and a.due_date < current_date then 'Overdue'
         else 'Pending'
       end as status,
       case
         when a.cancelled then null
         when ok.session_date is not null then ok.session_date::timestamptz
         when a.acknowledged_at is not null and not coalesce(bad.failed, false) then a.acknowledged_at
       end as completed_at
  from public.training_assignments a
  join public.user_directory d on d.id = a.dir_id
  left join public.documents doc on doc.id = a.document_id
  left join lateral (
    select min(s.session_date) as session_date
      from public.training_attendance t
      join public.training_sessions s on s.id = t.session_id
     where t.dir_id = a.dir_id and t.attended and t.assessment <> 'Fail'
       and ( (a.document_id is not null and s.document_id = a.document_id)
          or (a.document_id is null and lower(btrim(s.topic)) = lower(btrim(a.topic))) )
  ) ok on true
  left join lateral (
    select true as failed
      from public.training_attendance t
      join public.training_sessions s on s.id = t.session_id
     where t.dir_id = a.dir_id and t.assessment = 'Fail'
       and ( (a.document_id is not null and s.document_id = a.document_id)
          or (a.document_id is null and lower(btrim(s.topic)) = lower(btrim(a.topic))) )
     limit 1
  ) bad on true;
grant select on public.training_status to authenticated;

-- ---- a person's PAST TRAINING, every source in one list ----------------------
-- "If a User is given Training on a Specific topic then it should list all Past
-- Training details": every session attended and every read acknowledgement.
create or replace view public.training_history with (security_invoker = on) as
select t.dir_id, 'Session'::text as source, s.session_date::timestamptz as trained_on,
       s.topic, s.document_id, doc.doc_no, doc.revision, s.trainer, s.method,
       t.attended, t.assessment, t.score, t.remarks, s.id as session_id, s.attachments
  from public.training_attendance t
  join public.training_sessions s on s.id = t.session_id
  left join public.documents doc on doc.id = s.document_id
union all
select a.dir_id, 'Read & understood', a.acknowledged_at,
       a.topic, a.document_id, doc.doc_no, doc.revision, '', 'Read & Understand',
       true, '', null, '', null, '[]'::jsonb
  from public.training_assignments a
  left join public.documents doc on doc.id = a.document_id
 where a.acknowledged_at is not null;
grant select on public.training_history to authenticated;

-- ---- the screen key and the permission -----------------------------------------
-- MERGED, never overwritten, into the VP Technical and R&D Engineer roles only
-- (matched by key OR label with separators squashed -- the 0207 rule), and a
-- role with ZERO permissions is left alone. Admin holds both through has_perm.
do $$
declare n integer;
begin
  if to_regclass('public.app_roles') is null then
    raise notice '0264: app_roles is missing -- run rbac.sql first. Nothing granted.';
    return;
  end if;
  update public.app_roles ar
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (select jsonb_array_elements_text(ar.permissions) as v
                   union select unnest(array['mod:/training', 'training.manage'])) u),
         updated_at = now()
   where jsonb_array_length(ar.permissions) > 0
     and ( regexp_replace(lower(coalesce(ar.role,  '')), '[^a-z0-9]', '', 'g') in ('vptechnical', 'rndengg', 'rndengineer')
        or regexp_replace(lower(coalesce(ar.label, '')), '[^a-z0-9]', '', 'g') in ('vptechnical', 'rndengg', 'rndengineer') )
     and not (ar.permissions ?& array['mod:/training', 'training.manage']);
  get diagnostics n = row_count;
  raise notice '0264: % role(s) given the Training screen and training.manage (VP Technical / R&D Engineer only)', n;
end $$;

-- ---- the five system columns (0244), attached as 0249 does -------------------
do $$
declare t text;
begin
  if to_regprocedure('public.sys_columns_attach(regclass)') is null then return; end if;
  foreach t in array array['user_profile', 'user_rr', 'training_sessions', 'training_attendance', 'training_assignments'] loop
    perform public.sys_columns_attach(('public.' || t)::regclass);
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0295_user_profile_details_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0295 — A PERSON'S PROFILE AND R&R ARE "EDIT USER MASTER DETAILS"
--
-- Findings 57-67 (docs/PERMISSIONS_REVIEW.md), the user's decisions of
-- 2026-09-30: "63, 64: It should show the Individual View's Control Action and
-- its Check Box" -- each screen gets keys of its own, today's grants copied
-- across (0298) so nobody gains or loses anything on the day it ships -- and
-- "67: Break it down", with the old key kept as the PARENT of the new ones, so
-- a role holding it keeps everything until an administrator unticks it.
-- The parent rule itself is in has_perm() (0286, public.perm_parents).
--
-- This file: the training module's rules that asked users.manage now ask
-- its child users.manage.details.
-- ===========================================================================

do $$
begin
  if to_regclass('public.user_profile') is null then return; end if;
  drop policy if exists up_insert on public.user_profile;
  drop policy if exists up_update on public.user_profile;
  create policy up_insert on public.user_profile for insert
    with check ((select public.has_perm('users.manage.details')));
  create policy up_update on public.user_profile for update
    using ((select public.has_perm('users.manage.details'))) with check ((select public.has_perm('users.manage.details')));
  drop policy if exists rr_insert on public.user_rr;
  drop policy if exists rr_update on public.user_rr;
  create policy rr_insert on public.user_rr for insert
    with check ((select public.has_perm('users.manage.details')) or (select public.has_perm('training.manage')));
  create policy rr_update on public.user_rr for update
    using ((select public.has_perm('users.manage.details')) or (select public.has_perm('training.manage')))
    with check ((select public.has_perm('users.manage.details')) or (select public.has_perm('training.manage')));
end $$;

CREATE OR REPLACE FUNCTION public.may_see_person(p_dir_id bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.has_perm('users.manage.details')
      or public.has_perm('training.manage')
      or exists (
           select 1 from public.user_directory d
            where d.id = p_dir_id
              and ( (btrim(coalesce(d.email, '')) <> '' and lower(d.email) = lower(auth.email()))
                 or (btrim(coalesce(d.gmail, '')) <> '' and lower(d.gmail) = lower(auth.email()))
                 or d.name in (select public.visible_engineer_names()) ));
$function$;

-- ------------------------------------------------------------------------
-- 0405_user_master_keeps_history.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0405 — A USER MASTER ENTRY WITH A PROFILE OR R&R HISTORY IS NOT DELETED
--        (second re-review D-059)
--
-- 0264 declares user_profile.dir_id and user_rr.dir_id ON DELETE CASCADE, so
-- deleting a User Master row took the person's profile and every Roles &
-- Responsibilities period with it -- measured: the row, its R&R periods and
-- its profile all went -- while the screen's confirmation says "all history
-- are kept", FRS-093 says nothing in the person's record is deletable and
-- URS-079 says a new R&R period ends the previous one without deleting it.
-- (Training attendance and assignments already refuse the delete: their keys
-- do not cascade.)
-- A signed-in delete of a row that has a profile or an R&R period is now
-- refused, saying to mark the person inactive (Active = No) instead; a row with
-- neither -- an entry made by mistake -- can still be deleted. A connection
-- with no session (a repair) is not stopped.
-- In the training module, after 0295.
-- ===========================================================================

create or replace function public.user_directory_keeps_history()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_what text[] := '{}';
begin
  if auth.uid() is null then return old; end if;
  if to_regclass('public.user_profile') is not null
     and exists (select 1 from public.user_profile p where p.dir_id = old.id) then
    v_what := v_what || 'a profile'::text;
  end if;
  if to_regclass('public.user_rr') is not null
     and exists (select 1 from public.user_rr r where r.dir_id = old.id) then
    v_what := v_what || 'Roles & Responsibilities history'::text;
  end if;
  if array_length(v_what, 1) > 0 then
    raise exception '% has % on the User Master, which is kept: set Active to No instead of deleting the entry',
      coalesce(nullif(btrim(old.name), ''), 'This person'), array_to_string(v_what, ' and ')
      using errcode = '23503';
  end if;
  return old;
end $$;
revoke execute on function public.user_directory_keeps_history() from public, anon, authenticated;
drop trigger if exists user_directory_keeps_history on public.user_directory;
create trigger user_directory_keeps_history
  before delete on public.user_directory
  for each row execute function public.user_directory_keeps_history();

-- ------------------------------------------------------------------------
-- 0008_calls_creator_read.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Let a creator read back the call they just inserted (so insert...returning
-- works for everyone, not only admins). Fixes "new call saved locally / pending"
-- when the register is on Supabase.
-- ===========================================================================

do $calls_guard$ begin
-- 0040_call_tables_split.sql replaces public.calls with a VIEW over the three
-- typed call tables. What follows is table-only work, so on a project that has
-- already been split it has to be SKIPPED, not attempted — otherwise replaying
-- this file (which re-running any bundle does) dies with
--   ERROR 42809: cannot create index on relation "calls"
-- or "calls is not a table". On an unsplit project it runs exactly as before.
if (select c.relkind from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relname = 'calls') = 'r' then
execute $calls_sql$
drop policy if exists calls_scoped_read on public.calls;
create policy calls_scoped_read on public.calls for select
  using (public.can_see_call(allocated_to) or created_by = auth.uid());

drop policy if exists calls_update on public.calls;
create policy calls_update on public.calls for update
  using (public.can_see_call(allocated_to) or created_by = auth.uid())
  with check (public.can_see_call(allocated_to) or created_by = auth.uid());
$calls_sql$;
end if;
end $calls_guard$;

-- ------------------------------------------------------------------------
-- 0010_call_request_items.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Multi-item call requests. A request is up to 5 calls (Product + Serial No +
-- Standard Complaint + Reported Problem) that SHARE one REQID, so REQID cannot
-- be unique — the per-row identity is UniqueID (REQID-Product-SerialNo).
--
-- Before this, inserting the 2nd..5th item failed with
--   duplicate key value violates unique constraint "call_requests_reqid_key"
-- leaving the request half-saved (item 1 only).
-- ===========================================================================

alter table public.call_requests drop constraint if exists call_requests_reqid_key;
create index if not exists call_requests_reqid_idx on public.call_requests (reqid);

-- The real identity: one row per product/serial within a request.
create unique index if not exists call_requests_unique_key_uidx
  on public.call_requests (unique_key);

-- Mint a REQID up front so the whole request goes in as ONE insert and can
-- never be half-saved. The trigger still assigns one when this isn't used.
create or replace function public.next_call_reqid()
returns text language sql security definer set search_path = public as $$
  select 'R' || nextval('public.call_req_seq')::text;
$$;
grant execute on function public.next_call_reqid() to authenticated;

-- ------------------------------------------------------------------------
-- 0011_call_request_actions.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Call request actions (Hotline): a pending request is closed out in one of
-- three ways —
--   • Registered — a new call was created from it (UCN written back)
--   • Mapped     — it belongs to an existing call (that call's UCN written back)
--   • Cancelled  — not a call; reason recorded
-- A request leaves the pending list once it has a UCN or is cancelled.
-- ===========================================================================

alter table public.call_requests
  add column if not exists cancel_reason text default '',
  add column if not exists cancelled_at  timestamptz,
  add column if not exists actioned_by   text default '',
  add column if not exists actioned_at   timestamptz;

create index if not exists call_requests_status_idx on public.call_requests (status);

-- 0003 ships permissive insert/update policies; 0008 (RBAC enforcement)
-- replaces them with permission checks. Re-applying 0003 — which the
-- call_requests apply bundle does — would silently hand them back, so put the
-- RBAC versions back whenever has_perm() is present.
do $$
begin
  if to_regprocedure('public.has_perm(text)') is null then return; end if;

  execute 'drop policy if exists cr_insert on public.call_requests';
  execute $p$create policy cr_insert on public.call_requests for insert
    with check (public.has_perm('request.create'))$p$;

  execute 'drop policy if exists cr_update on public.call_requests';
  execute $p$create policy cr_update on public.call_requests for update
    using (public.has_perm('calls.create') or public.has_perm('pending.register') or created_by = auth.uid())
    with check (public.has_perm('calls.create') or public.has_perm('pending.register') or created_by = auth.uid())$p$;
end $$;

-- ------------------------------------------------------------------------
-- 0012_call_state.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Call state = whether a call is still open, derived from its LATEST visit:
--   Unattended     — no visit reported yet
--   Unsolved       — last visit came back unsolved
--   Report pending — visit made, report not completed
--   Solved         — last visit closed it
-- `pending_calls` is every call that is not Solved (the Pending Calls module).
-- Both views run with the caller's rights, so calls/reports RLS still applies.
-- ===========================================================================

-- Guarded for the same reason the pending_calls block below is: once
-- 0014_call_state_denorm.sql has run, IT owns this view and has since grown
-- columns (reopened_at / reopen_count, 0057). `create or replace view` cannot
-- drop columns, so re-running this file over a fully-migrated project failed
-- with "cannot drop columns from view" and took the rest of all.sql down with
-- it. 0014's definition supersedes this one, so skipping is a no-op.
do $cs$
begin
  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'calls'
                and column_name = 'open_state') then
    return;
  end if;

  execute $view$
    create or replace view public.call_state as
    select
      c.ucn,
      coalesce(r.call_status, '')                        as last_status,
      r.visit_at                                         as last_visit_at,
      case
        when r.ucn is null                    then 'Unattended'
        when r.call_status ilike 'solved%'     then 'Solved'
        when r.call_status ilike '%unsolved%'  then 'Unsolved'
        else 'Report pending'
      end                                                as state
    from public.calls c
    left join lateral (
      select rr.ucn, rr.call_status, rr.visit_at
      from public.reports rr
      where rr.ucn = c.ucn
      order by rr.visit_at desc nulls last, rr.id desc
      limit 1
    ) r on true
  $view$;
end $cs$;

-- NB: `calls` already has a `state` column (the geographic one), so the call's
-- open state is exposed here as `open_state`.
--
-- Skipped once 0014_call_state_denorm.sql has run: that migration denormalises
-- open_state onto `calls` itself and rebuilds this view against it. After that,
-- `c.*` here already carries open_state and aliasing s.state to the same name
-- collides ("column open_state ... already exists"), which broke re-running
-- this file. 0014's definition supersedes this one, so skipping is a no-op.
do $$
begin
  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'calls'
                and column_name = 'open_state') then
    return;
  end if;

  create or replace view public.pending_calls as
  select c.*, s.state as open_state, s.last_status, s.last_visit_at
  from public.calls c
  join public.call_state s on s.ucn = c.ucn
  where s.state <> 'Solved';

  execute 'alter view public.pending_calls set (security_invoker = on)';
  execute 'grant select on public.pending_calls to authenticated';
end $$;

-- Both views exist by now either way (this file's, or 0014's), so these are
-- safe; guarded only against a partial state where pending_calls is absent.
alter view public.call_state set (security_invoker = on);

grant select on public.call_state    to authenticated;
do $g$ begin
  if to_regclass('public.pending_calls') is not null then
    grant select on public.pending_calls to authenticated;
  end if;
end $g$;

-- ------------------------------------------------------------------------
-- 0014_call_state_denorm.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Call state, without re-deriving it on every read.
--
-- 0012 computed a call's state from its latest visit in a view. Correct, but
-- reading it meant scanning `reports` through that table's RLS — a correlated
-- subquery plus can_see_call() per report row. At 11k calls / 17k reports that
-- is ~37ms without RLS and >5s with it: "canceling statement due to statement
-- timeout".
--
-- The latest visit is now kept ON the call, maintained by a trigger on
-- `reports`. Reads touch `calls` only — the register already loads it, so the
-- state comes along for free, and Pending Calls is an indexed filter.
-- ===========================================================================

-- The 0012 views read the columns below, and one of them is recreated with a
-- different shape, so they go first.
drop view if exists public.pending_calls;
drop view if exists public.call_state;

do $calls_guard$ begin
-- 0040_call_tables_split.sql replaces public.calls with a VIEW over the three
-- typed call tables. What follows is table-only work, so on a project that has
-- already been split it has to be SKIPPED, not attempted — otherwise replaying
-- this file (which re-running any bundle does) dies with
--   ERROR 42809: cannot create index on relation "calls"
-- or "calls is not a table". On an unsplit project it runs exactly as before.
if (select c.relkind from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relname = 'calls') = 'r' then
execute $calls_sql$
alter table public.calls
  add column if not exists last_status   text default '',
  add column if not exists last_visit_at timestamptz;

-- Derived, so it can never drift from the two columns above.
alter table public.calls drop column if exists open_state;
alter table public.calls add column open_state text
  generated always as (
    case
      when last_visit_at is null and coalesce(last_status, '') = '' then 'Unattended'
      when lower(coalesce(last_status, '')) like 'solved%'          then 'Solved'
      when lower(coalesce(last_status, '')) like '%unsolved%'       then 'Unsolved'
      else 'Report pending'
    end
  ) stored;

create index if not exists calls_open_idx on public.calls (open_state) where open_state <> 'Solved';
$calls_sql$;
end if;
end $calls_guard$;

-- ---- keep it current -------------------------------------------------------
-- security definer: a visit by one engineer updates the call regardless of who
-- may write `calls`.
create or replace function public.sync_call_last_visit(p_ucn text)
returns void language plpgsql security definer set search_path = public as $$
begin
  update public.calls c
     set last_status   = coalesce(r.call_status, ''),
         last_visit_at = r.visit_at
    from (
      select call_status, visit_at
        from public.reports
       where ucn = p_ucn
       order by visit_at desc nulls last, id desc
       limit 1
    ) r
   where c.ucn = p_ucn;

  if not found then  -- no visits left (or none matched): back to Unattended
    update public.calls set last_status = '', last_visit_at = null where ucn = p_ucn;
  end if;
end $$;

create or replace function public.reports_touch_call()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.sync_call_last_visit(coalesce(new.ucn, old.ucn));
  if tg_op = 'UPDATE' and new.ucn is distinct from old.ucn then
    perform public.sync_call_last_visit(old.ucn);
  end if;
  return null;
end $$;

drop trigger if exists reports_touch_call on public.reports;
create trigger reports_touch_call after insert or update or delete on public.reports
  for each row execute function public.reports_touch_call();

-- ---- backfill --------------------------------------------------------------
update public.calls c
   set last_status   = coalesce(r.call_status, ''),
       last_visit_at = r.visit_at
  from (
    select distinct on (ucn) ucn, call_status, visit_at
      from public.reports
     order by ucn, visit_at desc nulls last, id desc
  ) r
 where r.ucn = c.ucn
   and (c.last_status is distinct from coalesce(r.call_status, '')
     or c.last_visit_at is distinct from r.visit_at);

-- ---- views, now trivial ----------------------------------------------------
-- `calls` already carries `state` (the geographic one), so the call's open
-- state stays `open_state` here too.
create view public.call_state as
  select ucn, last_status, last_visit_at, open_state as state from public.calls;

create view public.pending_calls as
  select * from public.calls where open_state <> 'Solved';

alter view public.call_state    set (security_invoker = on);
alter view public.pending_calls set (security_invoker = on);

grant select on public.call_state    to authenticated;
grant select on public.pending_calls to authenticated;

-- ------------------------------------------------------------------------
-- 0015_call_number.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Call Number.
--
--   • From a call registration request → the request's UniqueID
--     (REQID-Product-SerialNo), carried over when the Hotline registers it.
--   • Direct customer call (no request) → CLYY + a 5-digit running number,
--     e.g. CL2600001, continuing the existing series for that year
--     (the register already holds CL2300081, CL2300079, …).
--
-- It was a free-text field nobody filled, so a hand-created call could be
-- saved with a blank Call Number — and reports, spare requests, consumption
-- and feedback are all keyed by it.
-- ===========================================================================

create table if not exists public.call_number_seq (
  yy      text primary key,          -- two-digit year
  last_no integer not null default 0
);
alter table public.call_number_seq enable row level security;  -- only the definer function touches it

-- Next CL number for a year. The counter is seeded once, from the numbers
-- already in `calls` — so import historical CL numbers BEFORE this runs (or
-- delete that year's `call_number_seq` row afterwards to re-seed).
-- Next CL number for this year. The year's counter is seeded from the highest
-- CLYY##### already in `calls`, so it continues the series instead of
-- colliding with imported history.
create or replace function public.next_direct_call_number(p_yy text default null)
returns text language plpgsql security definer set search_path = public as $$
declare
  v_yy text := coalesce(nullif(p_yy, ''), to_char(current_date, 'YY'));
  v_no int;
begin
  insert into public.call_number_seq (yy, last_no)
  values (v_yy, coalesce((
    select max(substring(call_number from 5 for 5)::int)
      from public.calls
     where call_number ~ ('^CL' || v_yy || '[0-9]{5}')), 0))
  on conflict (yy) do nothing;

  update public.call_number_seq set last_no = last_no + 1
   where yy = v_yy
   returning last_no into v_no;

  return 'CL' || v_yy || lpad(v_no::text, 5, '0');
end $$;

-- Assign one when the call arrives without a Call Number. A call registered
-- from a request carries the request's UniqueID, so this only fires for direct
-- calls (and for any import row that has none).
create or replace function public.calls_before_insert()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.ucn is null or new.ucn = '' then
    new.ucn := public.next_ucn(new.call_type);
  end if;
  if coalesce(new.call_number, '') = '' then
    new.call_number := public.next_direct_call_number(to_char(coalesce(new.reg_date, current_date), 'YY'));
  end if;
  if new.reg_date is null then new.reg_date := current_date; end if;
  if new.created_by is null then new.created_by := auth.uid(); end if;
  return new;
end $$;

do $calls_guard$ begin
-- 0040_call_tables_split.sql replaces public.calls with a VIEW over the three
-- typed call tables. What follows is table-only work, so on a project that has
-- already been split it has to be SKIPPED, not attempted — otherwise replaying
-- this file (which re-running any bundle does) dies with
--   ERROR 42809: cannot create index on relation "calls"
-- or "calls is not a table". On an unsplit project it runs exactly as before.
if (select c.relkind from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relname = 'calls') = 'r' then
execute $calls_sql$
drop trigger if exists calls_biu on public.calls;
create trigger calls_biu before insert on public.calls
  for each row execute function public.calls_before_insert();
$calls_sql$;
end if;
end $calls_guard$;

-- Back-fill calls saved before this with no Call Number, each in its own year's
-- series (a call registered in 2025 gets a CL25 number, not a CL26 one).
do $$
declare r record;
begin
  for r in select id, reg_date from public.calls where coalesce(call_number, '') = '' order by id loop
    update public.calls
       set call_number = public.next_direct_call_number(to_char(coalesce(r.reg_date, current_date), 'YY'))
     where id = r.id;
  end loop;
end $$;

grant execute on function public.next_direct_call_number(text) to authenticated;

-- ------------------------------------------------------------------------
-- 0024_call_request_extra.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- `extra` on call_requests, so the historical CRN Registration export can be
-- imported without losing the columns the table has no home for — "Any Open
-- Call?" (the Hotline's answer at the time, either No or the open call's UCN),
-- Regional Manager, and Comments / Remarks.
-- ===========================================================================

alter table public.call_requests
  add column if not exists extra jsonb not null default '{}'::jsonb;

-- ------------------------------------------------------------------------
-- 0032_call_state_by_entry.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Call status: Unattended until a visit is entered, then the status of the
-- LATEST VISIT ENTRY — latest by when the visit was ENTERED, not by the visit
-- date the engineer typed.
--
-- Two fixes:
--
-- 1) `sync_call_last_visit` picked the latest visit by `visit_at` (the Visit
--    Date field). A visit entered today for a call visited last week then lost
--    to an older entry with a later visit date. The entry timestamp is
--    `reports.updated_at` (set when the row is written), so order by that and
--    fall back to `id` — which also orders the sheet-era rows, whose
--    updated_at is their import time. `last_visit_at` still carries the visit
--    DATE; only the choice of row changes.
--
-- 2) `open_state` tested `like 'solved%'` first, so the "Solved - Report
--    Pending" status introduced with the report field spec read as Solved and
--    dropped the call off Pending Calls. Unsolved and report-pending are now
--    tested before solved.
-- ===========================================================================

-- The views read open_state, and it is recreated below.
drop view if exists public.pending_calls;
drop view if exists public.call_state;

do $calls_guard$ begin
-- 0040_call_tables_split.sql replaces public.calls with a VIEW over the three
-- typed call tables. What follows is table-only work, so on a project that has
-- already been split it has to be SKIPPED, not attempted — otherwise replaying
-- this file (which re-running any bundle does) dies with
--   ERROR 42809: cannot create index on relation "calls"
-- or "calls is not a table". On an unsplit project it runs exactly as before.
if (select c.relkind from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relname = 'calls') = 'r' then
execute $calls_sql$
alter table public.calls drop column if exists open_state;
alter table public.calls add column open_state text
  generated always as (
    case
      when last_visit_at is null and coalesce(last_status, '') = ''   then 'Unattended'
      when lower(coalesce(last_status, '')) like '%unsolved%'         then 'Unsolved'
      when lower(coalesce(last_status, '')) like '%report pending%'   then 'Report pending'
      when lower(coalesce(last_status, '')) like 'solved%'            then 'Solved'
      else 'Report pending'
    end
  ) stored;

create index if not exists calls_open_idx on public.calls (open_state) where open_state <> 'Solved';
$calls_sql$;
end if;
end $calls_guard$;

-- ---- latest = latest ENTRY -------------------------------------------------
create or replace function public.sync_call_last_visit(p_ucn text)
returns void language plpgsql security definer set search_path = public as $$
begin
  update public.calls c
     set last_status   = coalesce(r.call_status, ''),
         last_visit_at = r.visit_at
    from (
      select call_status, visit_at
        from public.reports
       where ucn = p_ucn
       order by updated_at desc nulls last, id desc
       limit 1
    ) r
   where c.ucn = p_ucn;

  if not found then  -- no visits left (or none matched): back to Unattended
    update public.calls set last_status = '', last_visit_at = null where ucn = p_ucn;
  end if;
end $$;

-- ---- re-backfill on the new rule ------------------------------------------
update public.calls c
   set last_status   = coalesce(r.call_status, ''),
       last_visit_at = r.visit_at
  from (
    select distinct on (ucn) ucn, call_status, visit_at
      from public.reports
     order by ucn, updated_at desc nulls last, id desc
  ) r
 where r.ucn = c.ucn
   and (c.last_status is distinct from coalesce(r.call_status, '')
     or c.last_visit_at is distinct from r.visit_at);

-- A call whose reports have all gone is Unattended again.
--
-- ONCE, AND NEVER AGAIN ON A RE-APPLY. This is a BARE statement, so every run
-- of `call_requests.sql` used to execute it against LIVE DATA -- and 0109
-- (close_call, four months later) made its premise false: from then on a call
-- could be Solved with no visit ON PURPOSE, and this statement silently
-- un-solved every one of them.
--
-- IT HAPPENED, 2026-09-20. The user ran this bundle to pick up 0164's engineer
-- timeout and 0125's UCN counter, and 4,222 calls went from Solved to
-- Unattended in one statement nobody asked for. Reproduced exactly on a copy
-- before writing this: 4,222 in, 4,222 Unattended out.
--
-- A BACKFILL IS A ONE-TIME DATA CORRECTION, NOT PART OF THE SCHEMA, and the
-- difference only shows when a bundle is re-run -- which is the normal way this
-- project applies anything. The sentinel makes that explicit rather than
-- relying on the statement happening to be idempotent, which this one is not:
-- it is idempotent against the state 0032 shipped into and destructive against
-- the state 0109 created. Same class as `parts_category_check` (0148/0152) --
-- dead code that still executes, and only bites against real data.
--
-- The re-backfill ABOVE is deliberately left unguarded: it recomputes
-- `last_status` from `reports`, which is the source of truth, so re-running it
-- is a no-op on a correct database and a repair on a drifted one.
-- `app_settings` is created by 0047, in a LATER module -- so on a fresh apply
-- it does not exist yet and there is nothing to have run before, which is
-- exactly when the backfill SHOULD run. Absent table means first time.
--
-- READ THROUGH `execute`, NOT A PLAIN `if ... and exists(...)`. plpgsql
-- prepares the whole condition as ONE query and Postgres PARSES it before any
-- short-circuit can help, so `to_regclass(...) is not null and exists (select
-- ... from public.app_settings ...)` still fails with "relation does not
-- exist" on a fresh database. Found by running it, not by reading it.
do $$
declare v_done boolean := false;
begin
  if to_regclass('public.app_settings') is not null then
    execute 'select exists (select 1 from public.app_settings where key = $1)'
       into v_done using 'calls_unattended_backfill_0032';
  end if;

  if v_done then
    raise notice '0032: the Unattended backfill has already run; skipping (it would un-solve calls closed without a visit)';
    return;
  end if;

  update public.calls c
     set last_status = '', last_visit_at = null
   where (coalesce(c.last_status, '') <> '' or c.last_visit_at is not null)
     and not exists (select 1 from public.reports r where r.ucn = c.ucn);

  if to_regclass('public.app_settings') is not null then
    execute 'insert into public.app_settings (key, value) values ($1, to_jsonb(now()::text)) on conflict (key) do nothing'
      using 'calls_unattended_backfill_0032';
  end if;
end $$;

-- ---- views -----------------------------------------------------------------
create view public.call_state as
  select ucn, last_status, last_visit_at, open_state as state from public.calls;

create view public.pending_calls as
  select * from public.calls where open_state <> 'Solved';

alter view public.call_state    set (security_invoker = on);
alter view public.pending_calls set (security_invoker = on);

grant select on public.call_state    to authenticated;
grant select on public.pending_calls to authenticated;

-- ------------------------------------------------------------------------
-- 0040_call_tables_split.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Split `calls` into three physical tables: field_calls, installation_calls,
-- pm_calls — so PM's bulk (15–18k/yr) lives in its own table and never bloats
-- the others. Non-breaking: `calls` becomes a UNION-ALL VIEW over the three,
-- with INSTEAD OF triggers routing every write to the right table, so all
-- existing code (addCall / updateCall / bulkInsert('calls') / the reports
-- last-visit sync / the pending_calls & call_state views) keeps working
-- unchanged. Stage 2 will point the registers at the typed tables directly.
--
-- There are NO foreign keys into calls (associations link by ucn/call_number
-- value only), so replacing the table with a view breaks no constraint.
--
-- Idempotent: the one-time structural split is guarded on field_calls not yet
-- existing; the views / triggers / policies are create-or-replace and re-run
-- safely.
-- ===========================================================================

-- Which physical table a call_type belongs to. Robust to 'P M VISIT' (spaces)
-- and 'INSTALLATION CALL'. Immutable so it can drive routing and checks.
create or replace function public.call_table_for(p_type text)
returns text language sql immutable set search_path = public as $$
  select case
    when upper(coalesce(p_type, '')) like 'INSTALL%'                     then 'installation'
    when upper(replace(coalesce(p_type, ''), ' ', '')) like 'PM%'        then 'pm'
    else 'field'
  end;
$$;

-- Fix next_ucn's PM detection to match (a 'P M VISIT' UCN should start with P).
create or replace function public.next_ucn(p_call_type text)
returns text language plpgsql volatile security definer set search_path = public as $$
declare
  yy      text := to_char(now(), 'YY');
  mon     text := substr('ABCDEFGHIJKL', extract(month from now())::int, 1);
  dd      text := to_char(now(), 'DD');
  tletter text := case public.call_table_for(p_call_type)
                    when 'installation' then 'I'
                    when 'pm'           then 'P'
                    else 'F'
                  end;
  seq     int  := nextval('public.ucn_seq');
begin
  return yy || mon || dd || tletter || lpad(seq::text, 4, '0');
end;
$$;

-- ---- one-time structural split --------------------------------------------
do $$
declare cols text;
begin
  if to_regclass('public.field_calls') is not null then return; end if;      -- already split

  -- A single id space shared across the three tables, so the union view's id
  -- stays unique. Continue past the highest existing id.
  create sequence if not exists public.call_split_id_seq;
  perform setval('public.call_split_id_seq', coalesce((select max(id) from public.calls), 0) + 1, false);

  -- Three tables cloned from the current calls shape (columns, the generated
  -- open_state, defaults, the ucn-unique and allocated/serial/open indexes).
  create table public.field_calls        (like public.calls including all);
  create table public.installation_calls (like public.calls including all);
  create table public.pm_calls           (like public.calls including all);

  -- id: drop the per-table identity LIKE copied, use the shared sequence.
  alter table public.field_calls        alter column id drop identity if exists, alter column id set default nextval('public.call_split_id_seq');
  alter table public.installation_calls alter column id drop identity if exists, alter column id set default nextval('public.call_split_id_seq');
  alter table public.pm_calls           alter column id drop identity if exists, alter column id set default nextval('public.call_split_id_seq');

  -- created_by FK parity (LIKE never copies foreign keys).
  alter table public.field_calls        add constraint field_calls_created_by_fkey        foreign key (created_by) references auth.users(id);
  alter table public.installation_calls add constraint installation_calls_created_by_fkey foreign key (created_by) references auth.users(id);
  alter table public.pm_calls           add constraint pm_calls_created_by_fkey           foreign key (created_by) references auth.users(id);

  -- Copy existing rows into their table by type. All non-generated columns
  -- (this list excludes the generated open_state, which recomputes itself).
  select string_agg(quote_ident(column_name), ', ' order by ordinal_position)
    into cols
    from information_schema.columns
   where table_schema = 'public' and table_name = 'calls' and is_generated = 'NEVER';

  execute format('insert into public.field_calls (%1$s)        select %1$s from public.calls where public.call_table_for(call_type) = %2$L', cols, 'field');
  execute format('insert into public.installation_calls (%1$s) select %1$s from public.calls where public.call_table_for(call_type) = %2$L', cols, 'installation');
  execute format('insert into public.pm_calls (%1$s)           select %1$s from public.calls where public.call_table_for(call_type) = %2$L', cols, 'pm');

  -- Drop the views and the reports policy that depend on the table, then the
  -- table itself (this also drops its calls_biu trigger and its RLS policies).
  drop view if exists public.pending_calls;
  drop view if exists public.call_state;
  drop policy if exists reports_read on public.reports;   -- references public.calls; recreated below over the view
  drop table public.calls;
end $$;

-- ---- per-table write trigger (ucn / call_number / reg_date / created_by) ---
-- calls_before_insert() already exists (0015); attach it to each base table.
drop trigger if exists calls_biu on public.field_calls;
create trigger calls_biu before insert on public.field_calls        for each row execute function public.calls_before_insert();
drop trigger if exists calls_biu on public.installation_calls;
create trigger calls_biu before insert on public.installation_calls for each row execute function public.calls_before_insert();
drop trigger if exists calls_biu on public.pm_calls;
create trigger calls_biu before insert on public.pm_calls           for each row execute function public.calls_before_insert();

-- ---- the compatibility view ------------------------------------------------
create or replace view public.calls as
  select * from public.field_calls
  union all select * from public.installation_calls
  union all select * from public.pm_calls;
alter view public.calls set (security_invoker = on);
grant select, insert, update, delete on public.calls to authenticated;
grant select, insert, update, delete on public.field_calls, public.installation_calls, public.pm_calls to authenticated;
grant usage on sequence public.call_split_id_seq to authenticated;   -- id default is nextval(); insert needs it

-- INSTEAD OF triggers route writes and (on insert) write the trigger-assigned
-- ucn / call_number / id / open_state back onto NEW so `insert … returning *`
-- gives the caller the real UCN.
do $$
declare ins_cols text; ins_vals text; set_list text;
begin
  -- INSERT omits id (shared-sequence default). For every other column, fall
  -- back to the base-table default when the caller didn't supply it, so an
  -- omitted column (NEW is null on a view insert) still gets '' / '{}' / now()
  -- / 'Registered' rather than a null that breaks NOT NULL or loses the default.
  select string_agg(quote_ident(column_name), ', ' order by ordinal_position),
         string_agg(
           case when column_default is not null
                then format('coalesce(new.%I, %s)', column_name, column_default)
                else 'new.' || quote_ident(column_name) end,
           ', ' order by ordinal_position),
         string_agg(quote_ident(column_name) || ' = new.' || quote_ident(column_name), ', ' order by ordinal_position)
    into ins_cols, ins_vals, set_list
    from information_schema.columns
   where table_schema = 'public' and table_name = 'field_calls'
     -- open_state EXCLUDED BY NAME, not only by being generated. 0226 turns
     -- it into an ordinary column kept by a trigger, so `is_generated`
     -- stops excluding it and this list would silently start writing a
     -- DERIVED value through the view. A no-op before 0226; the thing
     -- that holds after it. check:replay found exactly this.
     and is_generated = 'NEVER' and column_name not in ('id', 'open_state');

  execute format($f$
    create or replace function public.calls_view_insert() returns trigger language plpgsql as $b$
    begin
      case public.call_table_for(new.call_type)
        when 'installation' then
          insert into public.installation_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, open_state
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.open_state;
        when 'pm' then
          insert into public.pm_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, open_state
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.open_state;
        else
          insert into public.field_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, open_state
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.open_state;
      end case;
      return new;
    end $b$;
  $f$, ins_cols, ins_vals);

  execute format($f$
    create or replace function public.calls_view_update() returns trigger language plpgsql as $b$
    begin
      case public.call_table_for(old.call_type)
        when 'installation' then update public.installation_calls set %1$s where ucn = old.ucn;
        when 'pm'           then update public.pm_calls           set %1$s where ucn = old.ucn;
        else                     update public.field_calls        set %1$s where ucn = old.ucn;
      end case;
      return new;
    end $b$;
  $f$, set_list);
end $$;

create or replace function public.calls_view_delete() returns trigger language plpgsql as $$
begin
  case public.call_table_for(old.call_type)
    when 'installation' then delete from public.installation_calls where ucn = old.ucn;
    when 'pm'           then delete from public.pm_calls           where ucn = old.ucn;
    else                     delete from public.field_calls        where ucn = old.ucn;
  end case;
  return old;
end $$;

drop trigger if exists calls_view_ins on public.calls;
create trigger calls_view_ins instead of insert on public.calls for each row execute function public.calls_view_insert();
drop trigger if exists calls_view_upd on public.calls;
create trigger calls_view_upd instead of update on public.calls for each row execute function public.calls_view_update();
drop trigger if exists calls_view_del on public.calls;
create trigger calls_view_del instead of delete on public.calls for each row execute function public.calls_view_delete();

-- ---- the last-visit sync now targets the base tables -----------------------
create or replace function public.sync_call_last_visit(p_ucn text)
returns void language plpgsql security definer set search_path = public as $$
declare v_status text; v_at timestamptz;
begin
  select call_status, visit_at into v_status, v_at
    from public.reports where ucn = p_ucn
   order by updated_at desc nulls last, id desc limit 1;   -- null when no visits → Unattended
  update public.field_calls        set last_status = coalesce(v_status, ''), last_visit_at = v_at where ucn = p_ucn;
  update public.installation_calls set last_status = coalesce(v_status, ''), last_visit_at = v_at where ucn = p_ucn;
  update public.pm_calls           set last_status = coalesce(v_status, ''), last_visit_at = v_at where ucn = p_ucn;
end $$;

-- ---- rebuild the derived views over the union ------------------------------
create or replace view public.call_state as
  select ucn, last_status, last_visit_at, open_state as state from public.calls;
create or replace view public.pending_calls as
  select * from public.calls where open_state <> 'Solved';
alter view public.call_state    set (security_invoker = on);
alter view public.pending_calls set (security_invoker = on);
grant select on public.call_state, public.pending_calls to authenticated;

-- reports_read reads calls (now the view) to scope a visit by its parent call.
drop policy if exists reports_read on public.reports;
create policy reports_read on public.reports for select
  using (
    (select public.is_admin())
    or (
      (select public.has_perm('calls.view'))
      and (
        (select public.can_view_all_calls())
        or exists (
          select 1 from public.calls c
           where c.ucn = reports.ucn
             and (
               coalesce(c.allocated_to, '') = ''
               or lower(trim(c.allocated_to)) in (
                    select lower(trim(n)) from public.visible_engineer_names() as v(n))
             )
        )
      )
    )
  );

-- ---- RLS: the same three policies (0037 read/update, rbac insert) per table -
do $$
declare t text; vis text;
begin
  -- The shared "may I see this call" test, inlined so the reporting-tree set is
  -- an InitPlan built once (the 0037 shape).
  vis := $v$ (select public.can_view_all_calls())
             or created_by = (select auth.uid())
             or coalesce(allocated_to, '') = ''
             or lower(trim(allocated_to)) in (select lower(trim(n)) from public.visible_engineer_names() as v(n)) $v$;
  foreach t in array array['field_calls', 'installation_calls', 'pm_calls'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists calls_scoped_read on public.%I', t);
    execute format('create policy calls_scoped_read on public.%I for select using ((select public.has_perm(''calls.view'')) and (%s))', t, vis);
    execute format('drop policy if exists calls_insert on public.%I', t);
    execute format('create policy calls_insert on public.%I for insert with check (public.has_perm(''calls.create''))', t);
    execute format('drop policy if exists calls_update on public.%I', t);
    execute format('create policy calls_update on public.%1$I for update using ((select (public.has_perm(''calls.edit'') or public.has_perm(''calls.report''))) and (%2$s)) with check ((select (public.has_perm(''calls.edit'') or public.has_perm(''calls.report''))) and (%2$s))', t, vis);
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0041_call_split_hardening.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Stage 3 — harden the calls split. The `calls` view stays (cheap, keeps the
-- cross-type screens simple, and after Stage 2 the registers already read the
-- typed tables directly); this makes keeping it robust:
--
--   1. A CHECK per table pins each row to the right table (call_table_for()),
--      so the INSTEAD OF routing can never misfile a row, and an accidental
--      in-place call_type change is rejected rather than silently orphaned.
--   2. Drop the per-table call_type index LIKE copied from calls — every row in
--      a table now shares one call_type, so the index only costs writes.
--
-- (No constraint-exclusion pruning is attempted: the check is on
-- call_table_for(call_type) while callers filter on call_type, different
-- expressions, and the registers no longer filter the view by type anyway.)
--
-- Idempotent.
-- ===========================================================================

do $$
declare t text; want text; idx text;
begin
  if to_regclass('public.field_calls') is null then
    raise notice 'calls not split yet (0040) — nothing to harden'; return;
  end if;

  foreach t in array array['field_calls', 'installation_calls', 'pm_calls'] loop
    want := case t when 'field_calls' then 'field'
                   when 'installation_calls' then 'installation'
                   else 'pm' end;

    -- 1 + 2. type-pinning CHECK (drop/recreate so it's idempotent).
    execute format('alter table public.%I drop constraint if exists %I', t, t || '_type_ck');
    execute format($c$alter table public.%1$I add constraint %1$s_type_ck check (public.call_table_for(call_type) = %2$L)$c$, t, want);

    -- 3. drop any index on just (call_type) — redundant now the table is one type.
    for idx in
      select indexrelid::regclass::text
        from pg_index i
        join pg_class c on c.oid = i.indrelid
       where c.relname = t and c.relnamespace = 'public'::regnamespace
         and not i.indisprimary and not i.indisunique
         and pg_get_indexdef(i.indexrelid) ilike '%(call_type)%'
    loop
      execute format('drop index if exists %s', idx);
    end loop;
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0043_installation_create_gate.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Creating an INSTALLATION call is Commercial's job (they're notified first),
-- with the Hotline desk that registers calls, and admins. Everyone else may
-- still see and report installations, but not create one.
--
-- Enforced on installation_calls only: field_calls / pm_calls keep calls.create.
-- The calls view routes an installation insert into installation_calls, so this
-- governs the view too.
-- ===========================================================================

do $$ begin
  if to_regclass('public.installation_calls') is null then
    raise notice 'calls not split yet (0040) — run split_call_tables.sql first';
    return;
  end if;
  drop policy if exists calls_insert on public.installation_calls;
  create policy calls_insert on public.installation_calls for insert
    with check (public.has_perm('install.create'));
end $$;

-- Grant install.create to the roles that create installations (idempotent).
do $$
declare r text;
begin
  foreach r in array array['admin', 'commercial', 'hotline'] loop
    update public.app_roles
       set permissions = (
             select jsonb_agg(distinct p)
               from (
                 select jsonb_array_elements_text(coalesce(permissions, '[]'::jsonb)) as p
                 union select 'install.create'
               ) u
           ),
           updated_at = now()
     where role = r;
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0050_pm_schedule_fields.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- PM schedule fields. PM calls are raised for a due MONTH: the registration
-- DATE is the 1st of that month (so a January batch is dated 1 Jan, whether
-- uploaded in January or backfilled later), and the actual upload date is kept
-- separately as "added_on".
--
-- The call NUMBERING is unchanged (UCN + Call Number as before). What gives a
-- monthly batch a stable order is the registration DATE-AND-TIME: a new
-- `reg_at timestamptz` alongside `reg_date`. The uploader sequences a batch a
-- few seconds apart (see pmImport.ts) — for a fresh month from 00:30 on the
-- 1st, or continuing after the latest existing call when adding to a month that
-- already has some — and the datetime is editable before import.
--
-- reg_date stays a plain `date` (every existing view/index/interval that reads
-- it keeps working); reg_at is the finer-grained companion. Two columns are
-- added to the split call tables, so the calls view and the INSTEAD OF routing
-- triggers are rebuilt to carry them.
-- ===========================================================================

-- An earlier revision of this file trialled a per-month serial (PM-YYYY-MM-####);
-- that idea was dropped (numbering must not change). Remove its objects if a
-- previous bundle created them — harmless if they were never there.
drop trigger  if exists pm_serial_biu on public.pm_calls;
drop function if exists public.pm_serial_assign();
drop function if exists public.next_pm_serial(date);
drop table    if exists public.pm_serial_seq;

do $outer$
begin
  if to_regclass('public.field_calls') is null then
    raise notice 'calls not split yet (0040) — run split_call_tables.sql first';
    return;
  end if;

  -- 1. new columns on each base table (identical shape for the UNION view).
  --    added_on: the day the batch was uploaded. reg_at: the registration
  --    date-and-time (reg_date is its date part).
  alter table public.field_calls        add column if not exists added_on date, add column if not exists reg_at timestamptz;
  alter table public.installation_calls add column if not exists added_on date, add column if not exists reg_at timestamptz;
  alter table public.pm_calls           add column if not exists added_on date, add column if not exists reg_at timestamptz;
  -- The uploader reads the latest reg_at for a due-month to continue after it.
  create index if not exists pm_calls_reg_idx on public.pm_calls (reg_date, reg_at desc);

  -- 2. back-fill reg_at for existing rows so the column is never null where a
  --    date is known (midnight of the registration date).
  update public.field_calls        set reg_at = reg_date::timestamptz where reg_at is null and reg_date is not null;
  update public.installation_calls set reg_at = reg_date::timestamptz where reg_at is null and reg_date is not null;
  update public.pm_calls           set reg_at = reg_date::timestamptz where reg_at is null and reg_date is not null;

  -- 3. the calls view and pending_calls gain the columns (CREATE OR REPLACE
  --    appends the new select-* columns; call_state is unchanged).
  create or replace view public.calls as
    select * from public.field_calls
    union all select * from public.installation_calls
    union all select * from public.pm_calls;
  alter view public.calls set (security_invoker = on);
  create or replace view public.pending_calls as
    select * from public.calls where open_state <> 'Solved';
end $outer$;

-- Keep reg_date and reg_at consistent when only one is supplied: derive the
-- date from the datetime, and default the datetime to midnight of the date.
-- (calls_before_insert() from 0015 also assigns the UCN / Call Number.)
-- Only rebuilt on a SPLIT project — on the pre-split `calls` table there is no
-- reg_at column, so referencing it would break inserts; there we leave the
-- 0015/0040 version in place and this whole migration is a no-op until the
-- split (0040) has run.
do $cbi$
begin
  if to_regclass('public.field_calls') is null then return; end if;
  execute $fn$
    create or replace function public.calls_before_insert()
    returns trigger language plpgsql security definer set search_path = public as $body$
    begin
      if new.ucn is null or new.ucn = '' then
        new.ucn := public.next_ucn(new.call_type);
      end if;
      if new.reg_date is null and new.reg_at is not null then
        new.reg_date := new.reg_at::date;
      end if;
      if coalesce(new.call_number, '') = '' then
        new.call_number := public.next_direct_call_number(to_char(coalesce(new.reg_date, current_date), 'YY'));
      end if;
      if new.reg_date is null then new.reg_date := current_date; end if;
      if new.reg_at is null then new.reg_at := new.reg_date::timestamptz; end if;
      if new.created_by is null then new.created_by := auth.uid(); end if;
      return new;
    end $body$;
  $fn$;
end $cbi$;

-- 4. Rebuild the INSTEAD OF insert/update trigger functions so the two new
--    columns are routed, and returned (both supplied by the caller) on
--    `insert … returning *`.
do $regen$
declare ins_cols text; ins_vals text; set_list text;
begin
  if to_regclass('public.field_calls') is null then return; end if;
  select string_agg(quote_ident(column_name), ', ' order by ordinal_position),
         string_agg(
           case when column_default is not null
                then format('coalesce(new.%I, %s)', column_name, column_default)
                else 'new.' || quote_ident(column_name) end,
           ', ' order by ordinal_position),
         string_agg(quote_ident(column_name) || ' = new.' || quote_ident(column_name), ', ' order by ordinal_position)
    into ins_cols, ins_vals, set_list
    from information_schema.columns
   where table_schema = 'public' and table_name = 'field_calls'
     -- open_state EXCLUDED BY NAME, not only by being generated. 0226 turns
     -- it into an ordinary column kept by a trigger, so `is_generated`
     -- stops excluding it and this list would silently start writing a
     -- DERIVED value through the view. A no-op before 0226; the thing
     -- that holds after it. check:replay found exactly this.
     and is_generated = 'NEVER' and column_name not in ('id', 'open_state');

  execute format($f$
    create or replace function public.calls_view_insert() returns trigger language plpgsql as $b$
    begin
      case public.call_table_for(new.call_type)
        when 'installation' then
          insert into public.installation_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, open_state, added_on, reg_at
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.open_state, new.added_on, new.reg_at;
        when 'pm' then
          insert into public.pm_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, open_state, added_on, reg_at
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.open_state, new.added_on, new.reg_at;
        else
          insert into public.field_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, open_state, added_on, reg_at
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.open_state, new.added_on, new.reg_at;
      end case;
      return new;
    end $b$;
  $f$, ins_cols, ins_vals);

  execute format($f$
    create or replace function public.calls_view_update() returns trigger language plpgsql as $b$
    begin
      case public.call_table_for(old.call_type)
        when 'installation' then update public.installation_calls set %1$s where ucn = old.ucn;
        when 'pm'           then update public.pm_calls           set %1$s where ucn = old.ucn;
        else                     update public.field_calls        set %1$s where ucn = old.ucn;
      end case;
      return new;
    end $b$;
  $f$, set_list);
end $regen$;

-- ------------------------------------------------------------------------
-- 0389_pm_calls_newest_registration_first.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- PM CALLS: NEWEST REGISTRATION FIRST.
--
-- The user, 2026-10-06: "Sort the PM Calls in Newest to Oldest based on Call
-- Registration Date. -- Table, Database". The register used to be read by
-- `id` -- the order the rows were INSERTED -- and a PM month is bulk-loaded
-- and back-dated, so that is the order of the uploads, not of the calls.
--
-- A table has no stored order; a query does. The PM register is now READ
-- newest registration first: reg_at desc, then reg_date desc, then id desc
-- (src/lib/supabase.ts orderCalls), and this index serves exactly that order,
-- so each page of 1,000 is an index scan rather than a sort of the whole
-- table. reg_at is the registration date-time (0050 fills it from reg_date
-- where absent); NULLS LAST so a call missing it sits at the end, not the top.
--
-- 0050's pm_calls_reg_idx (reg_date, reg_at desc) is LEFT: it serves the bulk
-- uploader's "latest registration in a month" lookup, a different question.
-- ===========================================================================

create index if not exists pm_calls_reg_at_desc_idx
  on public.pm_calls (reg_at desc nulls last, reg_date desc nulls last, id desc);

-- ------------------------------------------------------------------------
-- 0053_call_requests_view_all.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Hotline (and the office roles) must see the whole Pending Registrations
-- queue. That screen reads call_requests (rows with no UCN yet), gated by
-- cr_read (0003) — which only showed a user their own requests or an engineer
-- in their reporting sub-tree, with no office-role bypass. So a Hotline engineer
-- saw only the request they raised themselves.
--
-- Fold can_view_all_calls() (admin / data.view_all / hotline / nsm / commercial
-- / spare_coordinator / stores_incharge / tally_coordinator) into cr_read, in
-- line with the call registers and pending_registrations.
-- ===========================================================================

drop policy if exists cr_read on public.call_requests;
create policy cr_read on public.call_requests for select using (
  public.can_view_all_calls()
  or created_by = auth.uid()
  or lower(email) = lower(auth.email())
  or lower(trim(engineer)) in (select lower(trim(n)) from public.visible_engineer_names() as v(n))
);

-- ------------------------------------------------------------------------
-- 0057_call_reopen.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Re-opening a closed call.
--
-- A call whose latest visit says Solved is finished: no more visit entries,
-- spare requests or edits. Sometimes it isn't really finished — the fault
-- returns, or the visit was entered against the wrong call — so the Hotline
-- can RE-OPEN it. A re-opened call counts as open again and carries a flag
-- (`reopen_count`) that makes "how many calls were re-opened?" a filter rather
-- than an archaeology exercise.
--
-- `open_state` itself is left alone: it is a generated column with views
-- hanging off it (field_call_review …), and re-opening is a fact ABOUT the
-- call, not another visit outcome. The effective state — open_state, or
-- 'Reopened' while a re-open is outstanding — is exposed by `call_state` and
-- `pending_calls`, which is what the registers read.
--
-- A re-open is spent by the next visit entry: once visited again the call's
-- state comes from that visit, as usual.
-- ===========================================================================

do $reopen$
declare
  t      text;
  tables text[] := case when to_regclass('public.field_calls') is not null
                        then array['field_calls', 'installation_calls', 'pm_calls']
                        else array['calls'] end;
begin
  if to_regclass('public.field_calls') is null
     and (select c.relkind from pg_class c join pg_namespace n on n.oid = c.relnamespace
           where n.nspname = 'public' and c.relname = 'calls') <> 'r' then
    raise notice 'calls is neither a table nor split — nothing to alter';
    return;
  end if;

  foreach t in array tables loop
    execute format('alter table public.%I add column if not exists reopened_at timestamptz', t);
    execute format('alter table public.%I add column if not exists reopen_count integer not null default 0', t);
    execute format('create index if not exists %I on public.%I (reopen_count) where reopen_count > 0',
                   t || '_reopen_idx', t);
  end loop;

  -- A view built with select * fixed its column list when it was created, so
  -- it has to be replaced to carry the two new columns. Replacing (rather than
  -- dropping) keeps the INSTEAD OF triggers attached.
  if to_regclass('public.field_calls') is not null then
    create or replace view public.calls as
      select * from public.field_calls
      union all select * from public.installation_calls
      union all select * from public.pm_calls;
  end if;
end $reopen$;

-- The view's INSTEAD OF functions were generated from the column list as it
-- was; regenerate so a write through `calls` carries the new columns too.
do $regen$
declare ins_cols text; ins_vals text; set_list text;
begin
  if to_regclass('public.field_calls') is null then return; end if;
  select string_agg(quote_ident(column_name), ', ' order by ordinal_position),
         string_agg(
           case when column_default is not null
                then format('coalesce(new.%I, %s)', column_name, column_default)
                else 'new.' || quote_ident(column_name) end,
           ', ' order by ordinal_position),
         string_agg(quote_ident(column_name) || ' = new.' || quote_ident(column_name), ', ' order by ordinal_position)
    into ins_cols, ins_vals, set_list
    from information_schema.columns
   where table_schema = 'public' and table_name = 'field_calls'
     -- open_state EXCLUDED BY NAME, not only by being generated. 0226 turns
     -- it into an ordinary column kept by a trigger, so `is_generated`
     -- stops excluding it and this list would silently start writing a
     -- DERIVED value through the view. A no-op before 0226; the thing
     -- that holds after it. check:replay found exactly this.
     and is_generated = 'NEVER' and column_name not in ('id', 'open_state');

  execute format($f$
    create or replace function public.calls_view_insert() returns trigger language plpgsql as $b$
    begin
      case public.call_table_for(new.call_type)
        when 'installation' then
          insert into public.installation_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, open_state, added_on, reg_at
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.open_state, new.added_on, new.reg_at;
        when 'pm' then
          insert into public.pm_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, open_state, added_on, reg_at
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.open_state, new.added_on, new.reg_at;
        else
          insert into public.field_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, open_state, added_on, reg_at
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.open_state, new.added_on, new.reg_at;
      end case;
      return new;
    end $b$;
  $f$, ins_cols, ins_vals);

  execute format($f$
    create or replace function public.calls_view_update() returns trigger language plpgsql as $b$
    begin
      case public.call_table_for(old.call_type)
        when 'installation' then update public.installation_calls set %1$s where ucn = old.ucn;
        when 'pm'           then update public.pm_calls           set %1$s where ucn = old.ucn;
        else                     update public.field_calls        set %1$s where ucn = old.ucn;
      end case;
      return new;
    end $b$;
  $f$, set_list);
end $regen$;

-- ---- a visit entry spends the re-open --------------------------------------
create or replace function public.sync_call_last_visit(p_ucn text)
returns void language plpgsql security definer set search_path = public as $$
begin
  update public.calls c
     set last_status   = coalesce(r.call_status, ''),
         last_visit_at = r.visit_at,
         reopened_at   = null
    from (
      select call_status, visit_at
        from public.reports
       where ucn = p_ucn
       order by updated_at desc nulls last, id desc
       limit 1
    ) r
   where c.ucn = p_ucn;

  if not found then  -- no visits left (or none matched): back to Unattended
    update public.calls set last_status = '', last_visit_at = null where ucn = p_ucn;
  end if;
end $$;

-- ---- re-open ---------------------------------------------------------------
-- The Hotline (pending.register) or anyone who may create calls. Security
-- definer so the re-open lands even where the caller may not write the row.
create or replace function public.reopen_call(p_ucn text, p_reason text default '')
returns text language plpgsql security definer set search_path = public as $$
declare v_solved boolean; v_reopened timestamptz;
begin
  if not (public.has_perm('pending.register') or public.has_perm('calls.create')) then
    raise exception 'RBAC: your role cannot re-open a call';
  end if;

  select open_state = 'Solved', reopened_at into v_solved, v_reopened
    from public.calls where ucn = p_ucn;
  if v_solved is null then raise exception 'No call with UCN %', p_ucn; end if;
  if v_reopened is not null then raise exception 'Call % is already re-opened', p_ucn; end if;
  if not v_solved then raise exception 'Call % is not closed, so there is nothing to re-open', p_ucn; end if;

  update public.calls
     set reopened_at = now(), reopen_count = coalesce(reopen_count, 0) + 1
   where ucn = p_ucn;

  return p_ucn;
end $$;
grant execute on function public.reopen_call(text, text) to authenticated;

-- ---- views: effective state, re-open included ------------------------------
drop view if exists public.pending_calls;
drop view if exists public.call_state;

create view public.call_state as
  select ucn, last_status, last_visit_at, reopened_at, reopen_count,
         case when reopened_at is not null then 'Reopened' else open_state end as state
    from public.calls;

create view public.pending_calls as
  select * from public.calls where open_state <> 'Solved' or reopened_at is not null;

alter view public.call_state    set (security_invoker = on);
alter view public.pending_calls set (security_invoker = on);

grant select on public.call_state    to authenticated;
grant select on public.pending_calls to authenticated;

-- ------------------------------------------------------------------------
-- 0058_close_reopened_call.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Closing a re-opened call again, without inventing a visit.
--
-- A call is often re-opened only to correct it — the complaint was typed
-- wrong, the wrong machine was picked. Once corrected there was no way back:
-- the state comes from the latest visit, so the only route to Closed was to
-- enter a visit that never happened.
--
-- `close_reopened_call` withdraws the re-open instead: `reopened_at` is
-- cleared, so the call falls back to what its last visit said (Solved), and
-- nothing is added to its visit history.
--
-- The re-open count is given back. `reopened_at` is only set while NO visit
-- has followed the re-open — once one is entered, sync_call_last_visit clears
-- it and the count stands. So a re-open that is withdrawn never led to a
-- visit: it was an edit, and "how many calls were re-opened" should not count
-- it.
-- ===========================================================================

create or replace function public.close_reopened_call(p_ucn text, p_reason text default '')
returns text language plpgsql security definer set search_path = public as $$
declare v_reopened timestamptz; v_found boolean;
begin
  if not (public.has_perm('pending.register') or public.has_perm('calls.create')) then
    raise exception 'RBAC: your role cannot close a re-opened call';
  end if;

  select true, reopened_at into v_found, v_reopened
    from public.calls where ucn = p_ucn;
  if v_found is null then raise exception 'No call with UCN %', p_ucn; end if;
  if v_reopened is null then
    raise exception 'Call % is not re-opened — close it by entering the visit that solved it', p_ucn;
  end if;

  update public.calls
     set reopened_at  = null,
         reopen_count = greatest(coalesce(reopen_count, 0) - 1, 0)
   where ucn = p_ucn;

  return p_ucn;
end $$;
grant execute on function public.close_reopened_call(text, text) to authenticated;

-- ------------------------------------------------------------------------
-- 0083_request_status_from_ucn.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A request that HAS a UCN is Registered.
--
-- The Hotline sets a request's status explicitly when it registers or maps one
-- (setCallRequestUcn). A bulk load does not — the export carries the UCN in
-- column A and no status at all — so 4,010 registered requests came in reading
-- "Pending" on the register while each pointed at its call. The UCN is the
-- fact; the status is a reading of it, and a reading that can lag the fact is
-- a wrong reading.
--
-- So the database keeps the two in step, on every write from anywhere: a row
-- that carries a UCN and whose status is blank or Pending becomes Registered.
-- Nothing else is touched — Mapped and Registered are already true, Cancelled
-- and Dropped after registration are legitimate states and stay as set.
--
-- The trigger now fires on UPDATE too. It only ever set reqid / unique_key /
-- created_by on insert, which is unchanged; the status rule is the part that
-- has to hold when a UCN is written onto an existing row.
-- ===========================================================================

create or replace function public.call_requests_biu()
returns trigger language plpgsql set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if new.reqid is null or new.reqid = '' then
      new.reqid := 'R' || nextval('public.call_req_seq')::text;
    end if;
    if new.created_by is null then new.created_by := auth.uid(); end if;
    if coalesce(new.email,'') = '' then new.email := auth.email(); end if;
  end if;
  new.unique_key := new.reqid || '-' || coalesce(nullif(new.product,''),'NA') || '-' || coalesce(nullif(new.serial_no,''),'NA');

  -- A UCN means the request became a call. Only a blank / Pending status is
  -- corrected; every deliberate state is left exactly as it was set.
  if btrim(coalesce(new.ucn, '')) <> ''
     and coalesce(btrim(new.status), '') in ('', 'Pending') then
    new.status := 'Registered';
  end if;
  return new;
end $$;

drop trigger if exists call_requests_biu on public.call_requests;
create trigger call_requests_biu before insert or update on public.call_requests
  for each row execute function public.call_requests_biu();

-- What is already loaded: the same rule, once.
update public.call_requests
   set status = 'Registered'
 where btrim(coalesce(ucn, '')) <> ''
   and coalesce(btrim(status), '') in ('', 'Pending');

-- ------------------------------------------------------------------------
-- 0097_call_reqid_continues.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- REQID PICKS UP WHERE THE HISTORY LEFT OFF.
--
-- The register showed R18576, R18575, R18574 … and then the two requests
-- raised today came out as R1 and R2. Nothing was corrupted; the counter had
-- simply been sent back to the start and never told about the history.
--
-- What happened, in order:
--   1. `_reset_for_production.sql` emptied the demo data and reset the counter
--      (`setval('call_req_seq', 1, false)`). Right at that moment — the table
--      was empty, so R1 was the honest next number.
--   2. The sheet-era requests were then bulk-loaded, EACH CARRYING ITS OWN
--      REQID. An explicit reqid never calls `nextval`, so the counter stayed at
--      1 while 18,576 numbered requests landed above it.
--   3. The next request raised in the app took the counter's word for it.
--
-- Two fixes, because the one-off alone would let it happen again the next time
-- a batch is loaded:
--
--   * `resync_call_req_seq()` lifts the counter to the highest REQID on record,
--     and is run once here for what is already loaded.
--   * The insert trigger now does it CONTINUOUSLY: a row that arrives with its
--     own REQID pushes the counter ahead of itself. Load a hundred thousand old
--     requests and the next one raised in the app still follows the last of
--     them. The counter can no longer fall behind the data it numbers.
--
-- The two that were already issued out of order are re-lettered RC1, RC2. They
-- are real requests people have seen, so the number they were given is kept —
-- but `R1` is a number the sheet era may well have used too, and two different
-- requests reading `R1` is worse than either. `RC` says plainly which series a
-- request belongs to, and the same rule re-letters any other that slipped
-- through: numbered BELOW the register's high-water mark, yet raised AFTER it.
-- ===========================================================================

-- The highest number any REQID carries. `R18576` → 18576; anything not shaped
-- like that is ignored rather than guessed at.
create or replace function public.resync_call_req_seq()
returns bigint language plpgsql security definer set search_path = public as $$
declare
  v_max bigint;
  v_now bigint;
begin
  -- The regex has to be applied BEFORE the cast, and only a CASE guarantees
  -- that: `where <shape> and <cast>` is two quals on one scan and the planner
  -- may order them as it likes, so the first `RC1` in the table would make this
  -- die with "invalid input syntax for type bigint: "C1"" — which it did, the
  -- second time the script was run.
  select max(case when reqid ~ '^R[0-9]{1,15}$' then substring(reqid from 2)::bigint end)
    into v_max from public.call_requests;
  v_now := coalesce(pg_sequence_last_value('public.call_req_seq'::regclass), 0);
  if coalesce(v_max, 0) > v_now then
    perform setval('public.call_req_seq', v_max);
    return v_max;
  end if;
  return v_now;
end $$;
revoke all on function public.resync_call_req_seq() from public;
grant execute on function public.resync_call_req_seq() to authenticated;

-- 0083's trigger, with the one branch it was missing: what to do when the row
-- brings its OWN number.
create or replace function public.call_requests_biu()
returns trigger language plpgsql set search_path = public as $$
declare v_n bigint;
begin
  if tg_op = 'INSERT' then
    if new.reqid is null or new.reqid = '' then
      new.reqid := 'R' || nextval('public.call_req_seq')::text;
    elsif new.reqid ~ '^R[0-9]{1,15}$' then
      -- An imported request carries a number the counter has never issued.
      -- Keep the counter ahead of it, or the next request raised in the app
      -- starts again at R1 alongside an R18576.
      v_n := substring(new.reqid from 2)::bigint;
      if v_n > coalesce(pg_sequence_last_value('public.call_req_seq'::regclass), 0) then
        perform setval('public.call_req_seq', v_n);
      end if;
    end if;
    if new.created_by is null then new.created_by := auth.uid(); end if;
    if coalesce(new.email,'') = '' then new.email := auth.email(); end if;
  end if;
  new.unique_key := new.reqid || '-' || coalesce(nullif(new.product,''),'NA') || '-' || coalesce(nullif(new.serial_no,''),'NA');

  -- A UCN means the request became a call. Only a blank / Pending status is
  -- corrected; every deliberate state is left exactly as it was set. (0083)
  if btrim(coalesce(new.ucn, '')) <> ''
     and coalesce(btrim(new.status), '') in ('', 'Pending') then
    new.status := 'Registered';
  end if;
  return new;
end $$;

drop trigger if exists call_requests_biu on public.call_requests;
create trigger call_requests_biu before insert or update on public.call_requests
  for each row execute function public.call_requests_biu();

-- What is already loaded: once, now.
select public.resync_call_req_seq();

-- ---------------------------------------------------------------------------
-- The ones already issued out of order: numbered below the highest REQID on
-- record, but raised after it. Nothing else can match that — a genuine old
-- request is numbered below the high-water mark AND older than it.
-- ---------------------------------------------------------------------------
do $$
declare
  v_max  bigint;
  v_when timestamptz;
  v_ids  text;
begin
  select max(case when reqid ~ '^R[0-9]{1,15}$' then substring(reqid from 2)::bigint end)
    into v_max from public.call_requests;
  if v_max is null then return; end if;

  -- When the top of the series was raised. Anything numbered below it but not
  -- OLDER than it was numbered by a counter that had lost its place.
  select max(submitted_at) into v_when
    from public.call_requests
   where case when reqid ~ '^R[0-9]{1,15}$' then substring(reqid from 2)::bigint end = v_max;

  select string_agg(distinct reqid, ', ' order by reqid) into v_ids
    from public.call_requests
   where case when reqid ~ '^R[0-9]{1,15}$' then substring(reqid from 2)::bigint end < v_max
     and submitted_at >= v_when;
  if v_ids is null then
    raise notice 'REQID: nothing to re-letter — the series is in order.';
    return;
  end if;

  update public.call_requests
     set reqid = 'RC' || substring(reqid from 2)
   where case when reqid ~ '^R[0-9]{1,15}$' then substring(reqid from 2)::bigint end < v_max
     and submitted_at >= v_when;

  raise notice 'REQID: re-lettered % to RC — numbered below R%, raised after it.', v_ids, v_max;
end $$;

-- ------------------------------------------------------------------------
-- 0104_complaint_suggestions.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- SUGGESTING THE STANDARD COMPLAINT — from the register's own evidence.
--
-- The desk types what the customer said ("Oxygen sensor defective") into
-- Reported Problem, and must then find the right one of FIVE HUNDRED AND SEVEN
-- Standard Complaints. That is the field this suggests.
--
-- The evidence is already here: eighteen thousand past calls, each pairing a
-- reported problem with the standard complaint somebody chose for it. So the
-- first and best answer to "what is this?" is "here is what was chosen the last
-- twelve times somebody described it that way, on this product".
--
-- TWO SOURCES, IN THAT ORDER OF TRUST:
--   1. What was CHOSEN on past calls whose reported problem reads like this one
--      — a decision a person actually made, not a guess about words.
--   2. The wording of the complaint value itself, where no past call is close
--      enough. Weaker, and ranked below.
--
-- Both use the trigram indexes 0052 already built on complaint_reported and
-- standard_complaint, so `%` is an index lookup rather than a scan.
--
-- WHY SECURITY DEFINER. Read as the caller, an engineer would draw suggestions
-- only from their OWN calls, and the newest engineer would get the worst
-- suggestions — the opposite of what is wanted. It returns AGGREGATES ONLY:
-- a master-list value, a count and a score. No call, party, engineer or serial
-- crosses the boundary, so a reader learns nothing about a call they may not
-- see. That is the whole reason it is safe to define it this way.
--
-- WHERE THIS RUNS OUT. It is good at wording that recurs, which on a service
-- desk is most of it — the same fault gets typed the same way. It is weak on a
-- genuine paraphrase: "battery not holding charge" against "Internal battery
-- inoperant" shares one word and scores under any threshold worth using, and
-- pushing the threshold down far enough to catch it drags in everything else.
-- That gap is what the AI layer is for, and it is why the AI layer is worth
-- having rather than an ornament. This layer answers first, always, and the
-- screen works whether or not the other one is switched on.
--
-- IT SUGGESTS. IT DOES NOT DECIDE. The value is written by the person choosing
-- it, on their own authority, and `complaint_suggestions` records what was
-- offered and what was taken so the accept rate can be read rather than
-- assumed.
-- ===========================================================================

-- pg_trgm, which `similarity` / `word_similarity` / `%` below all need. It is
-- installed by 0052 — but 0052 is in the `performance` module, which runs LAST,
-- and this one is in `call_requests`, which runs seventh. So a FRESH apply of
-- `all.sql` (or of `call_requests.sql` on a database that has not had 0052 yet)
-- stopped dead here: a `language sql` body is parsed when the function is
-- created, so the missing operator is an error at apply time, not at run time.
-- Idempotent, and a no-op on the live project, which has had it since 0052.
create extension if not exists pg_trgm;

create or replace function public.suggest_standard_complaint(
  p_text text, p_product text default '', p_limit int default 5
)
returns table (value text, chosen int, score real, why text)
language sql stable security definer set search_path = public as $$
  with asked as (
    select btrim(coalesce(p_text, '')) as t, btrim(coalesce(p_product, '')) as p
  ),
  -- 1. What a person chose, on a call whose reported problem reads like this.
  --    Narrowed to the product when one is given, because the same words mean
  --    different things on different machines.
  from_calls as (
    select c.standard_complaint as v,
           count(*)::int as n,
           max(greatest(similarity(c.complaint_reported, a.t),
                        word_similarity(a.t, c.complaint_reported))) as sim
      from public.calls c, asked a
     where a.t <> ''
       and coalesce(c.standard_complaint, '') <> ''
       and coalesce(c.complaint_reported, '') <> ''
       and (a.p = '' or c.product_name = a.p)
       -- TWO WAYS OF BEING ALIKE, because whole-string similarity alone misses
       -- the way people actually retype a fault. "O2 sensor faulty" against
       -- "Oxygen sensor defective" scores 0.24 on similarity() — under the 0.3
       -- threshold, so the twelve calls that settled exactly this question were
       -- invisible — and 0.41 on word_similarity(), which asks whether the words
       -- asked for appear in what was written rather than whether the two
       -- strings look alike end to end.
       --
       -- The `%` arm is index-backed (0052's trigram indexes). The word arm is
       -- not, which is why it is worth scoping to the product: a scan of one
       -- product's calls is small, a scan of every call is not.
       and (c.complaint_reported % a.t or word_similarity(a.t, c.complaint_reported) >= 0.35)
     group by c.standard_complaint
  ),
  -- 2. The complaint's own wording, for a description nothing has been called
  --    before. Only live values: a deactivated one must not be offered again.
  from_master as (
    select m.value as v, greatest(similarity(m.value, a.t), word_similarity(a.t, m.value)) as sim
      from public.masters m, asked a
     where a.t <> ''
       and m.name = 'complaint'
       and coalesce(m.active, true)
       and (m.value % a.t or word_similarity(a.t, m.value) >= 0.35)
  ),
  merged as (
    select coalesce(fc.v, fm.v) as v,
           coalesce(fc.n, 0) as n,
           greatest(coalesce(fc.sim, 0), coalesce(fm.sim, 0)) as sim,
           (fc.v is not null) as seen
      from from_calls fc
      full join from_master fm on fm.v = fc.v
  )
  select v,
         n,
         -- A decision somebody made outranks a resemblance between two strings,
         -- so evidence carries the weight and the wording breaks ties. The log
         -- is there to be argued with: if the ranking is wrong, the accept rate
         -- will say so.
         (sim + least(n, 20) * 0.05)::real as score,
         case
           when n >= 2 then 'chosen on ' || n || ' similar call' || case when n = 1 then '' else 's' end
           when n = 1 then 'chosen once on a similar call'
           else 'wording match'
         end as why
    from merged
   where v is not null and v <> ''
   order by score desc, n desc, v
   limit greatest(coalesce(p_limit, 5), 1);
$$;
revoke all on function public.suggest_standard_complaint(text, text, int) from public;
grant execute on function public.suggest_standard_complaint(text, text, int) to authenticated;

-- ---------------------------------------------------------------------------
-- WHAT WAS OFFERED, AND WHAT WAS TAKEN.
--
-- Without this the only honest thing that could be said about the feature is
-- "it seems to help". One row per registration where a suggestion was shown:
-- the list offered in order, and the value the person actually chose. The
-- accept rate falls out of it, and so does the answer to "is the AI adding
-- anything the register's own evidence did not already give us".
--
-- It records a SUGGESTION, not a quality record, so it is not in the
-- record_audit set and carries no before/after image.
-- ---------------------------------------------------------------------------
create table if not exists public.complaint_suggestions (
  id            bigint generated always as identity primary key,
  asked_at      timestamptz not null default now(),
  asked_by      uuid,
  asked_by_name text not null default '',
  product       text not null default '',
  reported      text not null default '',
  -- [{ value, why, rank, source }] — source is 'register' or 'ai'.
  suggested     jsonb not null default '[]'::jsonb,
  -- What the person chose. '' means they took none of them, which is the most
  -- interesting row in the table.
  accepted      text not null default '',
  accepted_rank int,
  ucn           text not null default ''
);
create index if not exists complaint_suggestions_at_idx on public.complaint_suggestions (asked_at desc);

alter table public.complaint_suggestions enable row level security;
grant select, insert on public.complaint_suggestions to authenticated;

drop policy if exists cs_insert on public.complaint_suggestions;
create policy cs_insert on public.complaint_suggestions for insert
  with check (auth.role() = 'authenticated');
drop policy if exists cs_read on public.complaint_suggestions;
create policy cs_read on public.complaint_suggestions for select
  using ((select public.is_admin()) or (select public.has_perm('audit.view')));

-- Stamp the author in the database rather than trusting the client with it.
create or replace function public.complaint_suggestions_bi()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.asked_by := auth.uid();
  new.asked_by_name := coalesce((select full_name from public.profiles where id = auth.uid()), '');
  return new;
end $$;
drop trigger if exists complaint_suggestions_bi on public.complaint_suggestions;
create trigger complaint_suggestions_bi before insert on public.complaint_suggestions
  for each row execute function public.complaint_suggestions_bi();

-- ------------------------------------------------------------------------
-- 0105_calls_view_security_invoker.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE `calls` VIEW WAS READING AS ITS OWNER — SO EVERY USER SAW EVERY CALL.
--
-- 0040 created the view over the three typed tables and set `security_invoker`
-- on it, which is what makes row-level security apply to the person reading
-- rather than to the view's owner. 0050 re-created the view and correctly set
-- it again. 0057 re-created the view and DID NOT.
--
-- `create or replace view` does not carry the setting over. There is no error
-- and no warning; the view simply starts running as its owner, and RLS stops
-- applying to everything read through it.
--
-- Measured on a database with every migration applied, as an engineer holding
-- twelve calls that belong to somebody else:
--
--     field_calls (the table)   0 rows      <- RLS working
--     calls (the view)         12 rows      <- RLS bypassed
--     pending_calls            12 rows      <- reads `calls`, so it leaks too
--     call_state               12 rows      <- same
--     failure_modes_by_product  visible     <- same
--
-- pending_calls and call_state carry `security_invoker` themselves and were
-- still wide open, because a view marked invoker that reads a view running as
-- its owner inherits the owner's reach. Marking the outer view is no protection
-- if an inner one is unmarked.
--
-- That defeats URS-002 (role-based visibility), FRS-003/004, R-01 and OQ-02 —
-- an engineer could read every call in the register, and the KPI screens
-- counted the whole fleet for everybody.
--
-- WHAT CHANGES WHEN THIS IS APPLIED: engineers and managers will see FEWER
-- calls on Pending Calls, the registers and the KPIs — the ones their role
-- actually permits. That is the intended behaviour and what the validation
-- package has always claimed; it will nonetheless look like something broke to
-- anyone who had grown used to seeing everything.
--
-- A SECURITY DEFINER function reading the view is unaffected: inside one, the
-- invoker IS the function's owner, so `suggest_standard_complaint()` still
-- draws on every call, which is the whole point of defining it that way.
--
-- THIS LIVES IN THE `call_requests` BUNDLE, after 0057, because that is the
-- bundle that defines the view. Anywhere else and replaying call_requests.sql
-- would put the leak straight back.
-- ===========================================================================

do $$
begin
  if to_regclass('public.calls') is not null
     and (select relkind from pg_class where oid = 'public.calls'::regclass) = 'v' then
    execute 'alter view public.calls set (security_invoker = on)';
    raise notice 'calls: row-level security now applies to the reader, not the view owner.';
  end if;
end $$;

-- The views built ON it, re-asserted for the same reason: cheap, and it removes
-- any doubt about the order these were last written in.
do $$
declare v text;
begin
  foreach v in array array['pending_calls', 'call_state'] loop
    if to_regclass('public.' || v) is not null then
      execute format('alter view public.%I set (security_invoker = on)', v);
    end if;
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0107_complaint_text_help.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE COMPLAINT IS ALREADY WRITTEN IN A HOUSE STYLE. HELP PEOPLE KEEP IT.
--
-- Reported Problem is free text, but the register's is not freely written: the
-- alarm number is used wherever the machine gives one, the terms are the
-- manufacturer's, and the same fault comes back in the same words. That style
-- is worth something — it is why searching this register works at all, and why
-- the Standard Complaint suggestions in 0104 have anything to go on. It
-- survives on habit, and habit is what a new joiner does not have.
--
-- So the same treatment the Standard Complaint got, one field earlier, on the
-- text itself. TWO KINDS OF HELP, both drawn from things that already exist:
--
--   1. THE ALARM NUMBER, IN THE PRODUCT'S OWN FORM. The alarm list is already
--      curated, per product, in the `dccrgrouping` master — "ALARM 012" for
--      COMM, "Alarm 012" for MONNAL T75, and 54 more for T60. Somebody typing
--      "al 12" or "alarm12" gets offered the canonical spelling for THIS
--      product. It is the same alarm; the register just wants it written once.
--
--   2. HOW THIS FAULT HAS BEEN WRITTEN BEFORE, on this product, counted. Not a
--      style guide anyone has to maintain — the register's own most-used
--      wording for what is being described, so phrasing converges instead of
--      drifting a little further with each new joiner.
--
-- AND ONE CHECK, which is the part that catches a mistake rather than saving
-- keystrokes: an alarm number this product does not have. "Alarm 099" on a
-- MONNAL T60 is a typo, or the wrong machine, and today nothing says so until
-- somebody reads it months later in a review.
--
-- WHY SECURITY DEFINER — the same reason as 0104, and the same limit. Read as
-- the caller, an engineer would only ever be shown their own wording, so the
-- newest person gets the least help. It returns AGGREGATES ONLY: a phrase, a
-- count, a reason. No call, party, serial or engineer crosses the boundary.
--
-- IT SUGGESTS. IT DOES NOT REWRITE. Nothing here edits what somebody typed;
-- every value is offered, and taken or ignored by the person writing it.
-- ===========================================================================

-- pg_trgm, which `similarity` / `word_similarity` / `%` below all need. It is
-- installed by 0052 — but 0052 is in the `performance` module, which runs LAST,
-- and this one is in `call_requests`, which runs seventh. So a FRESH apply of
-- `all.sql` (or of `call_requests.sql` on a database that has not had 0052 yet)
-- stopped dead here: a `language sql` body is parsed when the function is
-- created, so the missing operator is an error at apply time, not at run time.
-- Idempotent, and a no-op on the live project, which has had it since 0052.
create extension if not exists pg_trgm;

-- ---------------------------------------------------------------------------
-- The alarm number as this product writes it.
--
-- Returns the canonical master value for an alarm number, preferring the
-- product's own list over COMM, so "al 12" on a MONNAL T75 comes back as
-- "Alarm 012" and on anything else as "ALARM 012". Empty when the product has
-- no such alarm — which is the whole point of the check above.
-- ---------------------------------------------------------------------------
create or replace function public.alarm_value_for(p_product text, p_number int)
returns text
language sql stable security definer set search_path = public as $$
  select m.value
    from public.masters m
   where m.name = 'dccrgrouping'
     and coalesce(m.active, true)
     -- The number, however the master spells it: ALARM 012 / Alarm 12 / AL 012.
     and (regexp_replace(upper(m.value), '^AL(ARM)?[^0-9]*([0-9]+).*$', '\2') ~ '^[0-9]+$')
     and upper(m.value) ~ '^AL(ARM)?[^0-9]*[0-9]+'
     and regexp_replace(upper(m.value), '^AL(ARM)?[^0-9]*([0-9]+).*$', '\2')::int = p_number
     and coalesce(m.extra->>'product', '') in (btrim(coalesce(p_product, '')), 'COMM')
   -- The product's own spelling wins over the common list.
   order by (coalesce(m.extra->>'product', '') = btrim(coalesce(p_product, ''))) desc, m.value
   limit 1;
$$;
revoke all on function public.alarm_value_for(text, int) from public;
grant execute on function public.alarm_value_for(text, int) to authenticated;

-- ---------------------------------------------------------------------------
-- What to offer under Reported Problem.
--
-- `kind` says which of the two it is, because they are not the same claim and
-- the screen must not present them as if they were:
--   'alarm'   — the canonical spelling of an alarm number already typed
--   'phrase'  — how this fault has been written on past calls
--   'unknown' — an alarm number this product does not have (a warning, and the
--               only row that is not something to click)
-- ---------------------------------------------------------------------------
create or replace function public.suggest_complaint_text(
  p_text text, p_product text default '', p_limit int default 4
)
returns table (value text, used int, kind text, why text)
language sql stable security definer set search_path = public as $$
  with asked as (
    select btrim(coalesce(p_text, '')) as t, btrim(coalesce(p_product, '')) as p
  ),
  -- The alarm number as typed, in any of the forms people use for it. Only the
  -- FIRST is considered: a complaint naming two alarms is describing two
  -- things, and picking one of them to canonicalise would be a guess.
  typed as (
    select a.p,
           (regexp_match(upper(a.t), '\mAL(?:ARM)?[[:space:]._-]*0*([0-9]{1,3})\M'))[1]::int as num
      from asked a
     where a.t <> ''
  ),
  -- 1. The canonical spelling — offered only when it differs from what is
  --    already written, since offering somebody the text they just typed is
  --    noise.
  alarm as (
    select public.alarm_value_for(t.p, t.num) as v, t.num
      from typed t
     where t.num is not null
  ),
  alarm_rows as (
    select al.v as value,
           (select count(*)::int from public.calls c, asked a
             where (a.p = '' or c.product_name = a.p)
               and c.complaint_reported ilike '%' || al.v || '%') as used,
           'alarm'::text as kind,
           'how ' || coalesce(nullif(btrim(a.p), ''), 'the register') || ' writes alarm ' || al.num as why
      from alarm al, asked a
     where al.v is not null
       and position(lower(al.v) in lower(a.t)) = 0
    union all
    -- The check. A number the product's alarm list does not carry.
    select 'Alarm ' || lpad(al.num::text, 3, '0'),
           0,
           'unknown'::text,
           coalesce(nullif(btrim(a.p), ''), 'This product') || ' has no alarm ' || al.num || ' — check the number'
      from alarm al, asked a
     where al.v is null
       and a.p <> ''
       -- Only worth saying when this product HAS a curated alarm list; silence
       -- is right where there is nothing to check against.
       and exists (select 1 from public.masters m
                    where m.name = 'dccrgrouping' and coalesce(m.active, true)
                      and upper(m.value) ~ '^AL(ARM)?[^0-9]*[0-9]+'
                      and coalesce(m.extra->>'product', '') = a.p)
  ),
  -- 2. How this fault has been written before, on this product. Grouped on the
  --    text itself, so the count is "written this way N times" — the phrasing
  --    that has already won.
  phrases as (
    select btrim(c.complaint_reported) as v, count(*)::int as n,
           max(greatest(similarity(c.complaint_reported, a.t),
                        word_similarity(a.t, c.complaint_reported))) as sim
      from public.calls c, asked a
     where a.t <> ''
       and coalesce(c.complaint_reported, '') <> ''
       and (a.p = '' or c.product_name = a.p)
       -- Index-backed arm first (0052's trigram index on complaint_reported),
       -- then the word arm for a retyping that does not look alike end to end.
       and (c.complaint_reported % a.t or word_similarity(a.t, c.complaint_reported) >= 0.4)
       -- Not the text already written, and not a one-off: a phrasing used once
       -- is not a house style, it is somebody's sentence.
       and lower(btrim(c.complaint_reported)) <> lower(a.t)
     group by btrim(c.complaint_reported)
    having count(*) >= 2
  )
  select value, used, kind, why from alarm_rows
  union all
  select v,
         n,
         'phrase'::text,
         'written this way on ' || n || ' calls'
    from (select v, n, sim from phrases order by (sim + least(n, 20) * 0.03) desc, n desc limit 6) p
  limit greatest(coalesce(p_limit, 4), 1);
$$;
revoke all on function public.suggest_complaint_text(text, text, int) from public;
grant execute on function public.suggest_complaint_text(text, text, int) to authenticated;

-- ------------------------------------------------------------------------
-- 0108_call_cancel.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- CANCELLING A CALL.
--
-- A registered call sometimes should not exist: the same fault was raised
-- twice, the customer rang back, it went onto the wrong machine. Until now the
-- only way out was to leave it open for ever or to close it as though somebody
-- had solved something — which puts a fiction into the register and into every
-- count taken from it.
--
-- WHO. Admin, NSM and the Hotline Engineer, by the user's decision
-- (2026-09-05). It is one permission, `calls.cancel`, so an administrator can
-- give it to somebody else or take it away without a migration. It covers Field,
-- PM and Installation calls alike: they are three tables and one register, and
-- a call raised in error is the same mistake whichever it is.
--
-- NOT A DELETE. The row stays, with who cancelled it, when, and why. The call
-- keeps its UCN, its visits and its quality records — 0049 forbids deleting
-- those and this must not smuggle a delete in through the side door. It leaves
-- the OPEN list and reads as Cancelled everywhere else.
--
-- REVERSIBLE. `restore_call` puts it back, because a one-way action with no
-- undo and a whole register to aim it at is a bad thing to hand anybody. The
-- restore is the same permission and leaves the reason behind it in place.
--
-- WHY NOT `open_state`. That is a STORED GENERATED column on all three tables,
-- and changing its expression means rebuilding the column and everything built
-- on it. Cancellation is not a state the visits derive; it is something a
-- person did to the call. So it is its own columns, and only the VIEWS decide
-- what to show — which is cheap and reversible.
-- ===========================================================================

do $cancel$
declare
  t      text;
  tables text[] := case when to_regclass('public.field_calls') is not null
                        then array['field_calls', 'installation_calls', 'pm_calls']
                        else array['calls'] end;
begin
  if to_regclass('public.field_calls') is null
     and (select c.relkind from pg_class c join pg_namespace n on n.oid = c.relnamespace
           where n.nspname = 'public' and c.relname = 'calls') <> 'r' then
    raise notice 'calls is neither a table nor split — nothing to alter';
    return;
  end if;

  foreach t in array tables loop
    execute format('alter table public.%I add column if not exists cancelled_at timestamptz', t);
    execute format('alter table public.%I add column if not exists cancel_reason text not null default %L', t, '');
    execute format('alter table public.%I add column if not exists cancelled_by uuid', t);
    -- Partial: cancelled calls are the rare ones, and every list that cares
    -- asks for "not cancelled" or "cancelled only".
    execute format('create index if not exists %I on public.%I (cancelled_at) where cancelled_at is not null',
                   t || '_cancelled_idx', t);
  end loop;

  -- `select *` fixed the column list when the view was created, so it has to be
  -- replaced to carry the three new ones. REPLACED, not dropped: the INSTEAD OF
  -- triggers and the KPI views built on it stay attached.
  if to_regclass('public.field_calls') is not null then
    create or replace view public.calls as
      select * from public.field_calls
      union all select * from public.installation_calls
      union all select * from public.pm_calls;
  end if;
end $cancel$;

-- `create or replace view` DROPS security_invoker, and a view without it reads
-- as its OWNER — every signed-in user seeing every call, with no error. 0057
-- rebuilt this view and left it off; 0105 is what put it back. Re-asserted here
-- because this migration rebuilds it again.
alter view public.calls set (security_invoker = on);

-- The INSTEAD OF functions were generated from the column list as it was;
-- regenerate so a write through `calls` carries the new columns too.
do $regen$
declare ins_cols text; ins_vals text; set_list text;
begin
  if to_regclass('public.field_calls') is null then return; end if;
  select string_agg(quote_ident(column_name), ', ' order by ordinal_position),
         string_agg(
           case when column_default is not null
                then format('coalesce(new.%I, %s)', column_name, column_default)
                else 'new.' || quote_ident(column_name) end,
           ', ' order by ordinal_position),
         string_agg(quote_ident(column_name) || ' = new.' || quote_ident(column_name), ', ' order by ordinal_position)
    into ins_cols, ins_vals, set_list
    from information_schema.columns
   where table_schema = 'public' and table_name = 'field_calls'
     -- open_state EXCLUDED BY NAME, not only by being generated. 0226 turns
     -- it into an ordinary column kept by a trigger, so `is_generated`
     -- stops excluding it and this list would silently start writing a
     -- DERIVED value through the view. A no-op before 0226; the thing
     -- that holds after it. check:replay found exactly this.
     and is_generated = 'NEVER' and column_name not in ('id', 'open_state');

  execute format($f$
    create or replace function public.calls_view_insert() returns trigger language plpgsql as $b$
    begin
      case public.call_table_for(new.call_type)
        when 'installation' then
          insert into public.installation_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, open_state, added_on, reg_at
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.open_state, new.added_on, new.reg_at;
        when 'pm' then
          insert into public.pm_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, open_state, added_on, reg_at
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.open_state, new.added_on, new.reg_at;
        else
          insert into public.field_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, open_state, added_on, reg_at
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.open_state, new.added_on, new.reg_at;
      end case;
      return new;
    end $b$;
  $f$, ins_cols, ins_vals);

  execute format($f$
    create or replace function public.calls_view_update() returns trigger language plpgsql as $b$
    begin
      case public.call_table_for(old.call_type)
        when 'installation' then update public.installation_calls set %1$s where ucn = old.ucn;
        when 'pm'           then update public.pm_calls           set %1$s where ucn = old.ucn;
        else                     update public.field_calls        set %1$s where ucn = old.ucn;
      end case;
      return new;
    end $b$;
  $f$, set_list);
end $regen$;

-- ---- the state a reader sees ----------------------------------------------
-- Cancelled is tested FIRST: a call cancelled while it was re-opened is
-- cancelled, not re-opened, and a cancelled call is not "Unattended" waiting
-- for somebody to go.
create or replace view public.call_state as
  select ucn, last_status, last_visit_at, reopened_at, reopen_count,
         case when cancelled_at is not null then 'Cancelled'
              when reopened_at is not null  then 'Reopened'
              else open_state end as state
    from public.calls;

-- A cancelled call is not pending: nobody is expected to go to it.
create or replace view public.pending_calls as
  select * from public.calls
   where cancelled_at is null
     and (open_state <> 'Solved' or reopened_at is not null);

alter view public.call_state    set (security_invoker = on);
alter view public.pending_calls set (security_invoker = on);

-- ---- cancel / restore ------------------------------------------------------
-- SECURITY DEFINER so the change lands on the physical table even where the
-- caller's update policy would not reach it — the permission is the gate, and
-- it is checked first and explicitly.
create or replace function public.cancel_call(p_ucn text, p_reason text)
returns text language plpgsql security definer set search_path = public as $$
declare v_cancelled timestamptz; v_exists boolean;
begin
  if not public.has_perm('calls.cancel') then
    raise exception 'RBAC: your role cannot cancel a call';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'A cancellation needs a reason';
  end if;

  select true, cancelled_at into v_exists, v_cancelled
    from public.calls where ucn = p_ucn;
  if v_exists is null then raise exception 'No call with UCN %', p_ucn; end if;
  if v_cancelled is not null then raise exception 'Call % is already cancelled', p_ucn; end if;

  update public.calls
     set cancelled_at  = now(),
         cancel_reason = btrim(p_reason),
         cancelled_by  = auth.uid()
   where ucn = p_ucn;

  return p_ucn;
end $$;
revoke all on function public.cancel_call(text, text) from public;
grant execute on function public.cancel_call(text, text) to authenticated;

-- The undo. The reason stays on the row: what was done and then undone is part
-- of the record, and clearing it would hide that this happened at all.
create or replace function public.restore_call(p_ucn text)
returns text language plpgsql security definer set search_path = public as $$
declare v_cancelled timestamptz; v_exists boolean;
begin
  if not public.has_perm('calls.cancel') then
    raise exception 'RBAC: your role cannot restore a call';
  end if;

  select true, cancelled_at into v_exists, v_cancelled
    from public.calls where ucn = p_ucn;
  if v_exists is null then raise exception 'No call with UCN %', p_ucn; end if;
  if v_cancelled is null then raise exception 'Call % is not cancelled', p_ucn; end if;

  update public.calls set cancelled_at = null, cancelled_by = null where ucn = p_ucn;
  return p_ucn;
end $$;
revoke all on function public.restore_call(text) from public;
grant execute on function public.restore_call(text) to authenticated;

-- ---- who may do it ---------------------------------------------------------
-- MERGED into whatever these roles already carry: an administrator may have
-- tuned them, and overwriting would silently take something away.
do $grant$
declare r text;
begin
  foreach r in array array['admin', 'nsm', 'hotline'] loop
    insert into public.app_roles as ar (role, label, permissions)
    values (r, initcap(replace(r, '_', ' ')), '["calls.cancel"]'::jsonb)
    on conflict (role) do update set
      permissions = (
        select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
        from (
          select jsonb_array_elements_text(ar.permissions) as v
          union
          select 'calls.cancel' as v
        ) u
      ),
      updated_at = now();
  end loop;
end $grant$;

-- ------------------------------------------------------------------------
-- 0109_close_call.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- CLOSING A CALL WITHOUT A VISIT ENTRY.
--
-- A call is normally closed by the visit that solved it: `open_state` reads
-- Solved because the latest report said so. But calls also end for operational
-- reasons — the customer sorted it themselves, the machine was moved, the job
-- was done on another call — and until now the only ways out were to leave it
-- open for ever or to file a visit nobody made.
--
-- IT IS NOT RECORDED DIFFERENTLY (the user's decision, 2026-09-05). A call
-- closed this way is Solved, like any other closed call. It is not a separate
-- category, it does not get its own badge, and nothing downstream has to learn
-- a new state. What it does NOT do is invent a visit: `last_visit_at` is left
-- alone, so the visit history stays empty and honest.
--
-- `last_status` is set to plain 'Solved'. That reads as Solved everywhere
-- (`open_state` tests `like 'solved%'`), and it is the one thing here that must
-- not be overstated: writing "Solved - Report Completed" would claim a report
-- that was never written.
--
-- AND A VISIT ENTERED LATER SIMPLY TAKES OVER. `sync_call_last_visit` recomputes
-- `last_status` from the newest report whenever `reports` changes (0014's
-- trigger), so the moment a real visit is entered the call goes back to the
-- regular route — including back to OPEN if that visit says Unsolved. Nothing
-- here has to be undone first.
--
-- The pair on screen stays unambiguous, because the two never both apply:
--   • an OPEN call            → "Close call"        (this)
--   • a RE-OPENED call        → "Close again"       (0058) — withdraws the
--                                re-open and gives the count back
-- ===========================================================================

create or replace function public.close_call(p_ucn text)
returns text language plpgsql security definer set search_path = public as $$
declare v_found boolean; v_state text; v_reopened timestamptz; v_cancelled timestamptz;
begin
  -- The same gate as re-opening: whoever may put a call back on the open list
  -- may take one off it.
  if not (public.has_perm('pending.register') or public.has_perm('calls.create')) then
    raise exception 'RBAC: your role cannot close a call';
  end if;

  select true, open_state, reopened_at, cancelled_at
    into v_found, v_state, v_reopened, v_cancelled
    from public.calls where ucn = p_ucn;
  if v_found is null then raise exception 'No call with UCN %', p_ucn; end if;
  if v_cancelled is not null then
    raise exception 'Call % is cancelled — restore it before closing it', p_ucn;
  end if;
  if v_reopened is not null then
    raise exception 'Call % is re-opened — use Close again, which gives the re-open back', p_ucn;
  end if;
  if v_state = 'Solved' then raise exception 'Call % is already closed', p_ucn; end if;

  -- No visit is invented: last_visit_at is untouched, so the visit history
  -- still says what actually happened, which is nothing.
  update public.calls set last_status = 'Solved' where ucn = p_ucn;

  return p_ucn;
end $$;
revoke all on function public.close_call(text) from public;
grant execute on function public.close_call(text) to authenticated;

-- ------------------------------------------------------------------------
-- 0113_call_creator_authoritative.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- WHO REGISTERED A CALL IS THE DATABASE'S TO SAY, NOT THE CALLER'S.
--
-- Only the Hotline engineer is trained on the vigilance questions — Public
-- Health Threat / Death / Serious Incident, answered at Review 1 on the
-- registration form itself. A call registered by anyone else has those three
-- answered by somebody untrained, which is a compliance matter, so the register
-- has to be able to show who actually registered each call (the user's reason,
-- 2026-09-05).
--
-- `calls_before_insert` already stamps it — but only as a FALLBACK:
--
--     if new.created_by is null then new.created_by := auth.uid(); end if;
--
-- so a caller who SENDS a `created_by` keeps it. Nothing in the app sends one
-- (neither the call forms nor Bulk Uploads map that column), but "nothing sends
-- it today" is not a control: the REST API takes whatever a signed-in client
-- posts, and a record that can be attributed to somebody else on request is not
-- evidence of anything.
--
-- So: WHEN THERE IS A SIGNED-IN USER, THAT USER IS RECORDED, and what the
-- caller supplied is discarded.
--
-- WHEN THERE IS NOT — a migration, a restore, an administrative load running as
-- `postgres` — `auth.uid()` is null, and whatever was supplied is kept. Forcing
-- null there would erase the provenance of a restored row, which is the
-- opposite of the point.
--
-- A SECOND TRIGGER rather than a rewrite of `calls_before_insert`: that function
-- is defined in 0001 and redefined in 0050 (it is one of the twelve objects
-- `check:bundles` lists as split across modules), and reproducing it here to
-- change one line would put a stale copy of everything else back. BEFORE
-- triggers fire in NAME order, so `zz_` guarantees this one runs last and has
-- the final say on the column.
-- ===========================================================================

create or replace function public.calls_stamp_creator()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  -- auth.uid() is null for an administrative connection; only an authenticated
  -- caller is overridden, and only ever with their own identity.
  if auth.uid() is not null then
    new.created_by := auth.uid();
  end if;
  return new;
end $$;

do $stamp$
declare
  t      text;
  tables text[] := case when to_regclass('public.field_calls') is not null
                        then array['field_calls', 'installation_calls', 'pm_calls']
                        else array['calls'] end;
begin
  if to_regclass('public.field_calls') is null
     and (select c.relkind from pg_class c join pg_namespace n on n.oid = c.relnamespace
           where n.nspname = 'public' and c.relname = 'calls') <> 'r' then
    raise notice 'calls is neither a table nor split — nothing to stamp';
    return;
  end if;

  foreach t in array tables loop
    execute format('drop trigger if exists zz_calls_stamp_creator on public.%I', t);
    execute format(
      'create trigger zz_calls_stamp_creator before insert on public.%I
         for each row execute function public.calls_stamp_creator()', t);
  end loop;
end $stamp$;

-- ------------------------------------------------------------------------
-- 0114_call_registrant_split.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- TWO FACTS, NOT ONE: THE DESK OF RECORD, AND THE PERSON AT THE KEYBOARD.
--
-- 0113 made `created_by` unforgeable — whoever is signed in is who is recorded.
-- That is right for the compliance question but it collapses two different
-- facts into one column, and the user's instruction (2026-09-06) separates
-- them:
--
--   created_by         THE DESK OF RECORD. Defaults to the Hotline engineer,
--                      who at present is SIVARANI and is the only person
--                      trained on the three vigilance questions (Public Health
--                      Threat / Death / Serious Incident) asked at Review 1 of
--                      a registration. A call belongs to that desk whoever
--                      happened to type it in.
--
--   actual_created_by  THE PERSON AT THE KEYBOARD. Today that is one of
--                      service.almsind@gmail.com, devika.m@airliquide.com or
--                      karthiksundar.b@airliquide.com when the Hotline
--                      engineer is on leave or otherwise unavailable.
--
-- The two agreeing is the ordinary case. The two DISAGREEING is the finding: an
-- untrained person answered the vigilance questions, and the register can now
-- produce that list instead of somebody reconstructing it from memory.
--
-- WHICH ONE IS UNFORGEABLE. `actual_created_by`, always. It is set from
-- auth.uid() and whatever the caller sent is discarded, exactly as 0113 did for
-- created_by — because it is the column an enquiry rests on. `created_by` is a
-- CHOICE (which hotline engineer's desk), so it is accepted from the caller,
-- but only when it names a hotline-role profile; anything else falls back to
-- the default. A choice that cannot be abused is still a choice.
--
-- ADMINISTRATIVE CONNECTIONS (auth.uid() null — a migration, a restore, a bulk
-- load) keep what they supply, and 0113's reasoning holds: forcing null there
-- would erase a restored row's provenance.
--
-- THE HISTORY. Every row that already carries a `created_by` got it from
-- auth.uid(), i.e. it recorded the person at the keyboard — so the backfill is
-- `actual_created_by := created_by`, and it is exact rather than a guess. Rows
-- bulk-loaded from the sheet era carry neither, and still say so;
-- `supabase/apply/_registered_by_check.sql` reports where that line falls.
-- ===========================================================================

-- ---- 1. the column -------------------------------------------------------
do $split$
declare
  t      text;
  tables text[] := case when to_regclass('public.field_calls') is not null
                        then array['field_calls', 'installation_calls', 'pm_calls']
                        else array['calls'] end;
begin
  if to_regclass('public.field_calls') is null
     and (select c.relkind from pg_class c join pg_namespace n on n.oid = c.relnamespace
           where n.nspname = 'public' and c.relname = 'calls') <> 'r' then
    raise notice 'calls is neither a table nor split — nothing to alter';
    return;
  end if;

  foreach t in array tables loop
    -- Appended, never inserted: `public.calls` is `select *` over the three
    -- tables, and `create or replace view` can only ADD columns at the end.
    -- All three gain it in the same statement order, so the union stays aligned.
    execute format('alter table public.%I add column if not exists actual_created_by uuid references auth.users (id)', t);
    -- The read policy gains an `actual_created_by = auth.uid()` arm below, and
    -- that arm is only cheap with an index behind it.
    execute format('create index if not exists %I on public.%I (actual_created_by)',
                   t || '_actual_created_by_idx', t);
    -- Exact, not approximate: until now `created_by` WAS the person at the
    -- keyboard, so copying it across loses nothing and invents nothing.
    execute format('update public.%I set actual_created_by = created_by
                     where actual_created_by is null and created_by is not null', t);
  end loop;
end $split$;

-- ---- 2. whose desk a call belongs to by default ---------------------------
-- Resolution order, most specific first:
--   1. app_settings['calls.default_registrant_email'] — an administrator has
--      named the desk explicitly. An EMAIL rather than a UUID, because the
--      person setting it reads email addresses, not UUIDs.
--   2. the single profile whose role is 'hotline' — true today (SIVARANI) and
--      the reason this needs no configuration to work.
--   3. null, when there are none or several and nobody has said which. The
--      caller then falls back to the signed-in user, which is what 0113 did:
--      an unknown desk must not become an EMPTY one.
create or replace function public.default_registrant()
returns uuid language sql stable security definer set search_path = public as $$
  select coalesce(
    (select p.id from public.profiles p
      join public.app_settings s on s.key = 'calls.default_registrant_email'
      where lower(p.email) = lower(btrim(s.value)) and btrim(s.value) <> ''
      limit 1),
    -- Only when there is exactly ONE. Two hotline engineers and no setting is
    -- an ambiguity, and picking one arbitrarily would put a name on calls that
    -- nobody chose.
    (select p.id from public.profiles p
      where lower(coalesce(p.role, '')) = 'hotline'
        and (select count(*) from public.profiles q
              where lower(coalesce(q.role, '')) = 'hotline') = 1
      limit 1)
  )
$$;
revoke all on function public.default_registrant() from public;
grant execute on function public.default_registrant() to authenticated;

-- Is this user allowed to be named as the desk of record? Only a hotline-role
-- profile, or the configured default itself (which an administrator chose and
-- may have given a different role).
create or replace function public.is_registrant_desk(p_user uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select p_user is not null
     and (p_user = public.default_registrant()
          or exists (select 1 from public.profiles p
                      where p.id = p_user and lower(coalesce(p.role, '')) = 'hotline'))
$$;
revoke all on function public.is_registrant_desk(uuid) from public;
grant execute on function public.is_registrant_desk(uuid) to authenticated;

-- The list a form can offer. `profiles` only lets most people read themselves,
-- so this reaches past that — deliberately, and as a FUNCTION rather than a
-- view: a SECURITY DEFINER view over an RLS-protected table is the exact shape
-- `npm run check:views` exists to reject, and a function makes the boundary
-- explicit instead of hiding it in a view option. It returns three columns of
-- the hotline desks and nothing else about those people.
create or replace function public.registrant_desks()
returns table (id uuid, name text, email text, is_default boolean)
language sql stable security definer set search_path = public as $$
  select p.id,
         coalesce(nullif(btrim(p.full_name), ''), p.email) as name,
         p.email,
         (p.id = public.default_registrant()) as is_default
    from public.profiles p
   where lower(coalesce(p.role, '')) = 'hotline'
      or p.id = public.default_registrant()
   order by (p.id = public.default_registrant()) desc, 2
$$;
revoke all on function public.registrant_desks() from public;
grant execute on function public.registrant_desks() to authenticated;

-- ---- 3. the stamp ---------------------------------------------------------
-- Replaces 0113's version. Still `zz_`-prefixed and still the last BEFORE
-- trigger to run (they fire in name order), so it has the final say.
create or replace function public.calls_stamp_creator()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is not null then
    -- Not negotiable. Whatever the caller sent is discarded.
    new.actual_created_by := auth.uid();

    -- The desk. A caller may name one, but only a real one.
    if new.created_by is null or not public.is_registrant_desk(new.created_by) then
      new.created_by := coalesce(public.default_registrant(), auth.uid());
    end if;
  else
    -- Administrative: a migration, a restore, a bulk load. Keep what was
    -- supplied; only fill a gap, and only from the other column.
    if new.actual_created_by is null then new.actual_created_by := new.created_by; end if;
    if new.created_by is null then new.created_by := new.actual_created_by; end if;
  end if;
  return new;
end $$;

do $stamp$
declare
  t      text;
  tables text[] := case when to_regclass('public.field_calls') is not null
                        then array['field_calls', 'installation_calls', 'pm_calls']
                        else array['calls'] end;
begin
  if to_regclass('public.field_calls') is null
     and (select c.relkind from pg_class c join pg_namespace n on n.oid = c.relnamespace
           where n.nspname = 'public' and c.relname = 'calls') <> 'r' then
    return;
  end if;
  foreach t in array tables loop
    execute format('drop trigger if exists zz_calls_stamp_creator on public.%I', t);
    execute format(
      'create trigger zz_calls_stamp_creator before insert on public.%I
         for each row execute function public.calls_stamp_creator()', t);
  end loop;
end $stamp$;

-- ---- 4. the views carry the new column ------------------------------------
-- `select *` fixed the column list when the view was created, so it has to be
-- REPLACED (not dropped) to pick the new one up — dropping would take the
-- INSTEAD OF triggers and the KPI views built on it with it.
do $views$
begin
  if to_regclass('public.field_calls') is null then return; end if;
  create or replace view public.calls as
    select * from public.field_calls
    union all select * from public.installation_calls
    union all select * from public.pm_calls;
end $views$;

-- `create or replace view` DROPS security_invoker, and a view without it reads
-- as its OWNER — every signed-in user seeing every call, with no error and no
-- warning. It has happened three times in this project (0040/0050/0057), so it
-- is re-asserted on EVERY rebuild, here included.
alter view public.calls set (security_invoker = on);

-- pending_calls is `select * from calls`, so it needs the same treatment to
-- gain the column — and marking it invoker is not optional either: a view
-- marked invoker that reads a view running as its owner inherits the owner's
-- reach.
create or replace view public.pending_calls as
  select * from public.calls
   where cancelled_at is null
     and (open_state <> 'Solved' or reopened_at is not null);
alter view public.pending_calls set (security_invoker = on);
alter view public.call_state    set (security_invoker = on);

-- ---- 5. writes through the view carry it too ------------------------------
-- The INSTEAD OF functions were generated from the column list as it was.
-- Regenerated here, and the RETURNING clause gains `actual_created_by` so the
-- client sees the stamp it did not send.
do $regen$
declare ins_cols text; ins_vals text; set_list text;
begin
  if to_regclass('public.field_calls') is null then return; end if;
  select string_agg(quote_ident(column_name), ', ' order by ordinal_position),
         string_agg(
           case when column_default is not null
                then format('coalesce(new.%I, %s)', column_name, column_default)
                else 'new.' || quote_ident(column_name) end,
           ', ' order by ordinal_position),
         string_agg(quote_ident(column_name) || ' = new.' || quote_ident(column_name), ', ' order by ordinal_position)
    into ins_cols, ins_vals, set_list
    from information_schema.columns
   where table_schema = 'public' and table_name = 'field_calls'
     -- open_state EXCLUDED BY NAME, not only by being generated. 0226 turns
     -- it into an ordinary column kept by a trigger, so `is_generated`
     -- stops excluding it and this list would silently start writing a
     -- DERIVED value through the view. A no-op before 0226; the thing
     -- that holds after it. check:replay found exactly this.
     and is_generated = 'NEVER' and column_name not in ('id', 'open_state');

  execute format($f$
    create or replace function public.calls_view_insert() returns trigger language plpgsql as $b$
    begin
      case public.call_table_for(new.call_type)
        when 'installation' then
          insert into public.installation_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, actual_created_by, open_state, added_on, reg_at
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.actual_created_by, new.open_state, new.added_on, new.reg_at;
        when 'pm' then
          insert into public.pm_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, actual_created_by, open_state, added_on, reg_at
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.actual_created_by, new.open_state, new.added_on, new.reg_at;
        else
          insert into public.field_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, actual_created_by, open_state, added_on, reg_at
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.actual_created_by, new.open_state, new.added_on, new.reg_at;
      end case;
      return new;
    end $b$;
  $f$, ins_cols, ins_vals);

  execute format($f$
    create or replace function public.calls_view_update() returns trigger language plpgsql as $b$
    begin
      case public.call_table_for(old.call_type)
        when 'installation' then update public.installation_calls set %1$s where ucn = old.ucn;
        when 'pm'           then update public.pm_calls           set %1$s where ucn = old.ucn;
        else                     update public.field_calls        set %1$s where ucn = old.ucn;
      end case;
      -- NOTHING WRITTEN IS NOTHING REPORTED (finding 48). When row-level
      -- security lets the caller see a call but not change it, the UPDATE above
      -- matches no row -- and returning NEW regardless told the client
      -- "UPDATE 1" over a call left exactly as it was. NULL makes the view
      -- report the row as not updated, which is the truth.
      if not found then return null; end if;
      return new;
    end $b$;
  $f$, set_list);
end $regen$;

-- ---- 6. the person who registered it can still see it ---------------------
-- The visibility test has an arm for "a call you created". With `created_by`
-- now naming the DESK, that arm stops matching for the very people this change
-- is about: Devika registers a call, it is filed to the Hotline desk, and she
-- can no longer open the thing she just typed in. So the arm is widened to
-- either column.
--
-- This re-creates the 0040 policies verbatim apart from that one line. It is
-- the same shape deliberately: the InitPlan wrappers `(select ...)` are what
-- 0095 added to stop the reporting-tree set being rebuilt per row.
do $rls$
declare t text; vis text;
begin
  if to_regclass('public.field_calls') is null then return; end if;
  vis := $v$ (select public.can_view_all_calls())
             or created_by = (select auth.uid())
             or actual_created_by = (select auth.uid())
             or coalesce(allocated_to, '') = ''
             or lower(trim(allocated_to)) in (select lower(trim(n)) from public.visible_engineer_names() as v(n)) $v$;
  foreach t in array array['field_calls', 'installation_calls', 'pm_calls'] loop
    execute format('drop policy if exists calls_scoped_read on public.%I', t);
    execute format('create policy calls_scoped_read on public.%I for select using ((select public.has_perm(''calls.view'')) and (%s))', t, vis);
    execute format('drop policy if exists calls_update on public.%I', t);
    execute format('create policy calls_update on public.%1$I for update using ((select (public.has_perm(''calls.edit'') or public.has_perm(''calls.report''))) and (%2$s)) with check ((select (public.has_perm(''calls.edit'') or public.has_perm(''calls.report''))) and (%2$s))', t, vis);
  end loop;
end $rls$;

comment on column public.field_calls.actual_created_by is
  'The signed-in user who registered the call. Stamped by the database, never accepted from the caller. created_by is the DESK of record (the Hotline engineer); the two disagreeing is the vigilance finding.';

-- ------------------------------------------------------------------------
-- 0125_ucn_daily_reset.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE UCN COUNTER RESTARTS EVERY DAY, PER CALL TYPE.
--
-- `next_ucn()` built <YY><MonthLetter><DD><TypeLetter><nnnn> where nnnn came
-- from `ucn_seq` — ONE sequence for the whole database, created in 0001 and
-- never reset by anything. So the date in front changed every day and the
-- number behind it just kept climbing, across all three call types together.
--
-- It was never a regression: 0001 says "Seq is a global monotonic count. NOTE:
-- confirm this matches the legacy format before go-live", and
-- docs/SUPABASE_MIGRATION.md has carried "whether the sequence should reset
-- per day/month" as an unresolved open item ever since. This settles it.
--
-- The register itself is the evidence it should reset: it holds 26H28F0009 and
-- then 26H29F0003 — the number goes DOWN from one day to the next, which a
-- global counter can never do. The sheet was counting per day; the database
-- was not. (2024 has the same shape: 24I01P0053, 24I01P0099.)
--
-- PER TYPE, restarting at 0001 each day (user's choice, 2026-09-06): Field,
-- Installation and PM each count their own day. The type letter is already in
-- the UCN, so nothing collides either way; this is the one that reads properly
-- on a printed register, where the Field list counts 1, 2, 3.
--
-- NUMBERS ALREADY ISSUED ARE NOT REWRITTEN (user's choice) — a UCN is printed
-- on delivery challans, quoted on spare requests and written into visit
-- reports, so it can never move under somebody. The counter for a day is
-- SEEDED past whatever that day already carries, so today continues from where
-- it got to and tomorrow opens at 0001. That also makes the change safe to
-- apply mid-day, and correct after an import that back-fills a day.
--
-- AND THE DAY IS INDIA'S. `next_ucn` read `now()`, which is UTC, so the DD in
-- the UCN rolled over at 5:30 am India time: a call registered between midnight
-- and 5:30 already carried YESTERDAY's date. A daily reset keyed off the same
-- clock would have reset at 5:30 too, so both are fixed here. Everything below
-- reads `now() at time zone 'Asia/Kolkata'`.
-- ===========================================================================

-- One counter per day per type. Written only by next_ucn(); RLS on with no
-- policy, so nothing but a definer function can see or touch it.
create table if not exists public.ucn_counters (
  day         date    not null,
  type_letter char(1) not null,          -- F | I | P
  last_no     integer not null default 0,
  primary key (day, type_letter)
);
alter table public.ucn_counters enable row level security;

-- The highest number ALREADY ISSUED under one YYMMDD<T> prefix.
--
-- Reads the three base tables, NOT the `calls` view: `calls` is
-- security_invoker, so inside a definer function it would apply the CALLER's
-- row policies and could hide a call — and a UCN this cannot see is a UCN it
-- would hand out twice. The base tables are read by the definer's owner, which
-- sees all of them.
--
-- The shape test matters as much as the prefix: an imported UCN that does not
-- match YYMMDD<T>nnnn has no number to compare, and `right(ucn,4)::int` on one
-- would raise rather than skip it.
create or replace function public.ucn_highest_issued(p_prefix text)
returns integer language sql stable security definer set search_path = public as $$
  select coalesce(max(right(ucn, 4)::int), 0)
    from (
      select ucn from public.field_calls        where ucn like p_prefix || '%'
      union all
      select ucn from public.installation_calls where ucn like p_prefix || '%'
      union all
      select ucn from public.pm_calls           where ucn like p_prefix || '%'
    ) u
   where ucn ~ '^[0-9]{2}[A-L][0-9]{2}[FIP][0-9]{4}$';
$$;
revoke all on function public.ucn_highest_issued(text) from public;

create or replace function public.next_ucn(p_call_type text)
returns text language plpgsql volatile security definer set search_path = public as $$
declare
  v_local timestamp := now() at time zone 'Asia/Kolkata';
  v_day   date      := v_local::date;
  tletter text := case public.call_table_for(p_call_type)
                    when 'installation' then 'I'
                    when 'pm'           then 'P'
                    else 'F'
                  end;
  v_prefix text := to_char(v_local, 'YY')
                || substr('ABCDEFGHIJKL', extract(month from v_local)::int, 1)
                || to_char(v_local, 'DD')
                || tletter;
  n integer;
begin
  -- Three statements rather than one upsert, so the SEED SCAN runs once a day
  -- per type instead of on every call: the second statement's WHERE matches
  -- only while the counter is still 0, and Postgres does not evaluate a SET
  -- expression for rows it does not match. That matters — `ucn like 'prefix%'`
  -- cannot use the ucn index under a non-C collation, so the seed reads the
  -- three tables. Once a day per type it is nothing; on every registration it
  -- would not be.
  insert into public.ucn_counters (day, type_letter, last_no)
  values (v_day, tletter, 0)
  on conflict (day, type_letter) do nothing;

  update public.ucn_counters c
     set last_no = public.ucn_highest_issued(v_prefix)
   where c.day = v_day and c.type_letter = tletter and c.last_no = 0;

  -- The row lock this takes is what stops two calls registered in the same
  -- instant taking the same number.
  update public.ucn_counters c
     set last_no = c.last_no + 1
   where c.day = v_day and c.type_letter = tletter
  returning c.last_no into n;

  return v_prefix || lpad(n::text, 4, '0');
end $$;

comment on function public.next_ucn(text) is
  'YYMMDD<T>nnnn, where nnnn restarts at 0001 each day PER CALL TYPE and the day is Asia/Kolkata. Seeded past whatever that day already carries, so numbers already issued are never re-used.';

-- The single running series is no longer used by anything. Dropped rather than
-- left lying about: a dead sequence that the production-reset script still
-- resets is a lie in the code, and this project has been caught by stale
-- artefacts before. (0017 retired spare_or_no_seq the same way.)
drop sequence if exists public.ucn_seq;

-- ------------------------------------------------------------------------
-- 0126_call_allot_permission.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- MOVING A CALL TO ANOTHER ENGINEER IS ITS OWN RIGHT.
--
-- Reported 2026-09-06: "call re-allocation option not visible for RM / RGM and
-- I couldn't find it in the roles and permissions as well."
--
-- The second half is the real fault. Re-allocation had no permission of its
-- own: it was a corner of `calls.edit`, so the Roles & Permissions screen had
-- nothing to show, and there was no way to give a manager the right to move a
-- call to one of their engineers WITHOUT also letting them rewrite the rest of
-- the call — or to take it away and leave the rest.
--
-- `calls.allot` is that right. Every role that holds `calls.edit` today is
-- given it, by MERGING into app_roles rather than overwriting: an administrator
-- may have tuned a role, and this must not be the change that quietly undoes
-- that. So nobody loses anything the day this lands, and from here on the two
-- can be granted apart.
--
-- ENFORCED IN THE DATABASE, not only on the screen. The register hides the
-- tick-boxes and locks the "Call Allocated To" box without the permission, but
-- a hidden control is a courtesy: `allocated_to` is reachable through PostgREST
-- by anyone whose row policy lets them update the call at all, and the call
-- policy asks for `calls.edit OR calls.report`. Without the trigger below the
-- new permission would be decoration.
--
-- WHAT THE TRIGGER DOES NOT STOP:
--   * allotting AT REGISTRATION — that is `calls.create`, and this only fires
--     on UPDATE;
--   * a change made with no signed-in user (an import, a definer function, a
--     scheduled job), which has no permissions to test and is not a person;
--   * an administrator.
--
-- Filling a BLANK allocated_to for the first time IS covered, and deliberately:
-- "allot this unallotted call" is the same act as moving it, and it is what the
-- bulk bar on the register actually does most of the time.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- Every role that can edit a call can re-allocate one, as it could yesterday.
-- MERGE, never overwrite (CLAUDE.md): a role with tuned permissions keeps them.
-- ---------------------------------------------------------------------------
update public.app_roles ar
   set permissions = (
         select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
           from (
             select jsonb_array_elements_text(ar.permissions) as v
             union
             select 'calls.allot' as v
           ) u
       ),
       updated_at = now()
 where ar.permissions ? 'calls.edit'
   and not (ar.permissions ? 'calls.allot');

-- ---------------------------------------------------------------------------
-- The guard. Named `zz_` so it runs after the other BEFORE triggers on these
-- tables (they fire in NAME order), which is where the creator stamp lives —
-- nothing here depends on that, but the convention keeps the order readable.
-- ---------------------------------------------------------------------------
create or replace function public.calls_allot_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.allocated_to is not distinct from old.allocated_to then
    return new;                                   -- not a re-allocation
  end if;
  if auth.uid() is null then
    return new;                                   -- import / definer / scheduled
  end if;
  if public.is_admin() then
    return new;
  end if;
  if not public.has_perm('calls.allot') then
    raise exception
      'RBAC: moving a call to another engineer needs the "Re-allocate a call to another engineer" permission';
  end if;
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['field_calls', 'installation_calls', 'pm_calls'] loop
    if to_regclass('public.' || t) is null then
      raise notice 'skip %: not present yet', t;
      continue;
    end if;
    execute format('drop trigger if exists zz_calls_allot_guard on public.%I', t);
    execute format(
      'create trigger zz_calls_allot_guard before update of allocated_to on public.%I
         for each row execute function public.calls_allot_guard()', t);
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0127_call_edit_sections.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- "EDIT A CALL" IS NOT ONE RIGHT. IT IS FOUR.
--
-- Reported 2026-09-06: "edit gives access to edit the whole call.. which is not
-- required for the managers. at the same time the Hotline engineer can edit the
-- complete call.. so 1 single edit permission will not suffice."
--
-- `calls.edit` let anyone who could correct a customer's phone number also
-- rewrite the machine, the complaint and the vigilance answers. The Hotline
-- desk genuinely needs all of that. A manager needs almost none of it, and
-- until now the only choice was to give them everything or nothing.
--
--   calls.edit.complaint   standard_complaint, complaint_reported, breakdown_date
--   calls.edit.customer    party_name, city, state, product_name, serial, item_status
--   calls.edit.vigilance   public_health_threat, death, serious_incident
--   calls.edit.contact     customer_name, customer_number, customer_designation
--
-- `calls.edit` REMAINS, and is the PARENT of all four — the same shape as
-- `masters.edit` over the per-list keys (0067). A role holding it keeps
-- everything it had, so this migration changes nobody's access on the day it
-- runs. To narrow a manager, an administrator unticks "Edit calls" and ticks
-- the sections they should have; that is the whole point of the split.
--
-- Registration and Warranty & Contract get no section of their own on purpose.
-- Those fields are assigned by the database or locked from Product Master, so a
-- right to edit them would be a right over almost nothing; `calls.edit` still
-- covers them, and it is Hotline's.
--
-- ENFORCED HERE, not on the form. The form locks a section it may not change,
-- but the call policy asks only for `calls.edit OR calls.report`, so PostgREST
-- would take any of these columns from anyone who can update the call at all.
--
-- ---------------------------------------------------------------------------
-- AND EVERY CHANGE TO THE VIGILANCE ANSWERS IS KEPT (user's choice).
--
-- Public Health Threat / Death / Serious Incident are Review 1 — the vigilance
-- record the DCCR reads and an auditor asks about. Whoever may change them can
-- change a quality answer after the fact, so each change is written with who,
-- when, and what it moved from and to, in the same statement that makes it:
-- a change cannot exist without its record, or a record without its change.
-- Registration is not a change, so it writes nothing.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- FIRST, THE POLICY HAS TO LET THEM IN AT ALL.
--
-- `calls_update` asks for `calls.edit OR calls.report`, so a role holding only
-- a section right — or only `calls.allot` (0126) — cannot update the call at
-- all: the row simply does not match and the statement reports 0 rows with no
-- error. Every finer right would have been decoration. Found by giving a test
-- role `calls.edit.contact` and watching its perfectly legitimate change do
-- nothing at all.
--
-- So the policy admits the new rights and the TRIGGER below decides which
-- columns each one may actually move. Same division 0067 made for masters: the
-- policy opens the table, the finer rule says what may change.
--
-- This re-creates 0114's policy verbatim apart from that one list, including
-- the InitPlan wrappers `(select ...)` that 0095 added to stop the reporting
-- tree being rebuilt for every row.
-- ---------------------------------------------------------------------------
do $rls$
declare t text; vis text; may text;
begin
  if to_regclass('public.field_calls') is null then
    raise notice 'skip calls_update: the split call tables are not present yet';
    return;
  end if;
  vis := $v$ (select public.can_view_all_calls())
             or created_by = (select auth.uid())
             or actual_created_by = (select auth.uid())
             or coalesce(allocated_to, '') = ''
             or lower(trim(allocated_to)) in (select lower(trim(n)) from public.visible_engineer_names() as v(n)) $v$;
  may := $m$ (select (public.has_perm('calls.edit')
                   or public.has_perm('calls.report')
                   or public.has_perm('calls.allot')
                   or public.has_perm('calls.edit.complaint')
                   or public.has_perm('calls.edit.customer')
                   or public.has_perm('calls.edit.vigilance')
                   or public.has_perm('calls.edit.contact'))) $m$;
  foreach t in array array['field_calls', 'installation_calls', 'pm_calls'] loop
    execute format('drop policy if exists calls_update on public.%I', t);
    execute format('create policy calls_update on public.%1$I for update using (%2$s and (%3$s)) with check (%2$s and (%3$s))', t, may, vis);
  end loop;
end $rls$;

create table if not exists public.call_vigilance_changes (
  id         bigint generated always as identity primary key,
  ucn        text not null,
  field      text not null,                       -- public_health_threat | death | serious_incident
  was        text not null default '',
  now_is     text not null default '',
  changed_by uuid,
  changed_at timestamptz not null default now()
);
create index if not exists call_vigilance_changes_ucn_idx on public.call_vigilance_changes (ucn, changed_at desc);
alter table public.call_vigilance_changes enable row level security;

-- Readable by anyone who may see the daily review or the call register; written
-- ONLY by the trigger below, which is why there is no insert policy.
drop policy if exists cvc_read on public.call_vigilance_changes;
create policy cvc_read on public.call_vigilance_changes for select
  using (public.has_perm('calls.view') or public.has_perm('review.edit'));
grant select on public.call_vigilance_changes to authenticated;

create or replace function public.calls_edit_section_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  me      uuid := auth.uid();
  free    boolean;
  changed boolean;
begin
  -- No signed-in user (import, definer, scheduled) is not a person, and an
  -- administrator is every person. `calls.edit` is the parent of all four.
  free := me is null or public.is_admin() or public.has_perm('calls.edit');

  if not free then
    changed := new.standard_complaint is distinct from old.standard_complaint
            or new.complaint_reported is distinct from old.complaint_reported
            or new.breakdown_date     is distinct from old.breakdown_date;
    if changed and not public.has_perm('calls.edit.complaint') then
      raise exception 'RBAC: changing the complaint needs the "Edit the complaint" permission';
    end if;

    changed := new.party_name   is distinct from old.party_name
            or new.city         is distinct from old.city
            or new.state        is distinct from old.state
            or new.product_name is distinct from old.product_name
            or new.serial       is distinct from old.serial
            or new.item_status  is distinct from old.item_status;
    if changed and not public.has_perm('calls.edit.customer') then
      raise exception 'RBAC: changing the customer or the machine needs the "Edit customer & product" permission';
    end if;

    changed := new.customer_name        is distinct from old.customer_name
            or new.customer_number      is distinct from old.customer_number
            or new.customer_designation is distinct from old.customer_designation;
    if changed and not public.has_perm('calls.edit.contact') then
      raise exception 'RBAC: changing the customer contact needs the "Edit customer contact details" permission';
    end if;

    changed := new.public_health_threat is distinct from old.public_health_threat
            or new.death                is distinct from old.death
            or new.serious_incident     is distinct from old.serious_incident;
    if changed and not public.has_perm('calls.edit.vigilance') then
      raise exception 'RBAC: changing the vigilance answers needs the "Edit the vigilance answers" permission';
    end if;
  end if;

  -- The record, in the same statement as the change — including an
  -- administrator's, and including one made with no signed-in user, because
  -- "who changed the vigilance answer" is a question about the answer and not
  -- about permissions.
  insert into public.call_vigilance_changes (ucn, field, was, now_is, changed_by)
  select new.ucn, f.name, coalesce(f.was, ''), coalesce(f.now_is, ''), me
    from (values
      ('public_health_threat', old.public_health_threat, new.public_health_threat),
      ('death',                old.death,                new.death),
      ('serious_incident',     old.serious_incident,     new.serious_incident)
    ) as f(name, was, now_is)
   where f.now_is is distinct from f.was;

  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['field_calls', 'installation_calls', 'pm_calls'] loop
    if to_regclass('public.' || t) is null then
      raise notice 'skip %: not present yet', t;
      continue;
    end if;
    execute format('drop trigger if exists zz_calls_edit_section_guard on public.%I', t);
    execute format(
      'create trigger zz_calls_edit_section_guard before update on public.%I
         for each row execute function public.calls_edit_section_guard()', t);
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0226_cancelled_is_not_report_pending.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A CANCELLED CALL IS NOT "REPORT PENDING".
--
-- The user, 2026-09-21, looking at a reporting upload: "How did it become
-- Report Pending?" Measured on the file: 11,957 rows, every one carrying a
-- status, producing 36 Report-pending calls out of 7,006 -- and NINETEEN of
-- those 36 have `last_status = 'Canceled'`.
--
-- `open_state` (0032) tests unattended, unsolved, report-pending, then
-- `solved%`, and everything it does not recognise falls into a final ELSE
-- returning 'Report pending'. A cancelled call is not report-pending; it is
-- cancelled, and it was being put in a queue of work somebody is chasing.
--
-- THE CLIENT ALREADY KNEW. `stateBucket()` in src/lib/callstate.tsx has
-- `if (/cancel/i.test(t)) return 'Cancelled'`, with its own slate chip and
-- label. Five screens read `open_state` STRAIGHT FROM THE DATABASE, so those
-- showed "Report pending" for a call the register would otherwise colour
-- Cancelled. The two disagreed; this settles it in the database.
--
-- ---------------------------------------------------------------------------
-- WHY A TRIGGER RATHER THAN A NEW GENERATED EXPRESSION.
--
-- PostgreSQL before 17 cannot CHANGE a generation expression: it has to be
-- dropped and re-added, and dropping the column takes every view that reads it
-- with it. Measured on a database built from every migration: `open_state` on
-- the three call tables is read by `calls`, `field_call_review` and
-- `field_call_review_summary`, and the `calls` view is in turn read by
-- call_report, call_state, consumption_report, failure_rate_by_product,
-- field_failure_register, pending_calls, solved_without_report and
-- unused_spare_report. ELEVEN VIEWS to drop and rebuild, each needing
-- `security_invoker` re-asserted -- the exact rebuild this project has got
-- wrong three times (0040/0050/0057, where `calls` lost the setting and every
-- signed-in user could read every call).
--
-- `ALTER COLUMN ... DROP EXPRESSION` (PG13+) turns the generated column into an
-- ordinary one IN PLACE. Proved on a built database inside a transaction: all
-- eight views still there afterwards, both indexes still there, the column
-- still there and no longer generated. A BEFORE trigger then keeps it, which
-- is what this project does everywhere else a derived value must be right.
--
-- THE VALUE IS STAMPED, NEVER ACCEPTED. The column is writable now, so the
-- trigger overwrites whatever a caller sends -- the 0113/0114 rule: a
-- caller-supplied value is DISCARDED, not refused, because refusing makes an
-- honest client fail and discarding makes a buggy one harmless.
--
-- SCOPE. Only the cancelled branch is added. `stateBucket()` also knows
-- 'Reopened', and it tests report-pending BEFORE unsolved where this tests
-- unsolved first (0032's own comment says that order was deliberate). Neither
-- is changed here: they are separate decisions and this one was asked for.
-- ===========================================================================

-- ---- the rule, in one place ------------------------------------------------
create or replace function public.call_open_state(p_status text, p_visit timestamptz)
returns text language sql immutable set search_path = public as $$
  select case
    -- A call with no visit and nothing said about it has not been attended.
    when p_visit is null and coalesce(p_status, '') = ''        then 'Unattended'
    -- CANCELLED FIRST of the status tests: a cancelled call is cancelled
    -- whatever else the text says. `%cancel%` matches both spellings, which
    -- the register carries -- the AppSheet export writes 'Canceled'.
    when lower(coalesce(p_status, '')) like '%cancel%'          then 'Cancelled'
    when lower(coalesce(p_status, '')) like '%unsolved%'        then 'Unsolved'
    when lower(coalesce(p_status, '')) like '%report pending%'  then 'Report pending'
    when lower(coalesce(p_status, '')) like 'solved%'           then 'Solved'
    else 'Report pending'
  end;
$$;
grant execute on function public.call_open_state(text, timestamptz) to authenticated;

comment on function public.call_open_state(text, timestamptz) is
  'The bucket a call''s status falls into. Mirrors stateBucket() in src/lib/callstate.tsx for the cancelled branch; check:ui compares the two.';

-- ---- convert the column and keep it with a trigger -------------------------
create or replace function public.call_open_state_stamp()
returns trigger language plpgsql set search_path = public as $$
begin
  -- Whatever the caller sent is discarded. This is a derived value.
  new.open_state := public.call_open_state(new.last_status, new.last_visit_at);
  return new;
end $$;

do $conv$
declare t text; n int := 0;
begin
  foreach t in array array['calls', 'field_calls', 'installation_calls', 'pm_calls'] loop
    -- `calls` is a TABLE before 0040 and a VIEW after it. Skip the view.
    continue when to_regclass('public.' || t) is null
              or (select relkind from pg_class where oid = ('public.' || t)::regclass) <> 'r';
    continue when not exists (select 1 from information_schema.columns
                               where table_schema = 'public' and table_name = t
                                 and column_name = 'open_state');

    -- Only if it is still generated; re-running this migration must not fail.
    if exists (select 1 from information_schema.columns
                where table_schema = 'public' and table_name = t
                  and column_name = 'open_state' and is_generated = 'ALWAYS') then
      execute format('alter table public.%I alter column open_state drop expression', t);
    end if;

    execute format('drop trigger if exists call_open_state_t on public.%I', t);
    execute format('create trigger call_open_state_t before insert or update on public.%I '
                   'for each row execute function public.call_open_state_stamp()', t);

    -- Recompute every existing row. This is what makes a re-upload
    -- unnecessary: the statuses on the rows were always right, the expression
    -- reading them was not.
    execute format('update public.%I set open_state = public.call_open_state(last_status, last_visit_at) '
                   'where open_state is distinct from public.call_open_state(last_status, last_visit_at)', t);
    n := n + 1;
  end loop;
  raise notice '0226: open_state is now stamped on % call table(s).', n;
end $conv$;

-- ------------------------------------------------------------------------
-- 0242_cancel_calls_in_one_go.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- CANCELLING A BATCH OF CALLS IN ONE GO.
--
--   The user, 2026-09-24: "Cancel all these calls in 1 Go with Reason as
--   'Duplicate Call'".
--
-- The everyday case this serves is exactly the one the reason names: a handful
-- of calls that are the SAME call, raised twice by different people or landed
-- twice from an import. Cancelling them one at a time is not merely slow — it
-- is a prompt answered a dozen times, which is how one of them gets a
-- different reason typed into it and the set stops reading as one decision.
--
-- IT ADDS NO NEW POWER, AND THAT IS THE WHOLE DESIGN. This function is
-- SECURITY INVOKER and does nothing itself: it LOOPS OVER `public.cancel_call`
-- (0108), which is the definer function that checks `calls.cancel`, refuses an
-- empty reason, refuses an unknown UCN and refuses one already cancelled. So a
-- role that cannot cancel one call cannot cancel fifty through here, and no
-- rule is written down twice — a second copy of a permission check is a second
-- copy to forget when the first one changes.
--
-- PARTIAL SUCCESS IS THE NORMAL OUTCOME AND IS REPORTED PER CALL. A selection
-- of twenty will routinely contain one that somebody already cancelled, and an
-- all-or-nothing batch would throw that whole decision away over it. Each
-- cancellation therefore runs in its OWN subtransaction (`begin ... exception`)
-- and the function returns one row per UCN saying whether it went through and,
-- if not, exactly what Postgres said. A batch that reports "18 done, 2 already
-- cancelled" is an answer; "ERROR" over the same twenty is not.
--
-- THE CAP IS 500 AND IT IS DELIBERATE. Cancelling is reversible (`restore_call`)
-- but it is still aimed at a whole register, and an accidental select-all
-- should not be able to take out ten thousand calls in one request. 500 is well
-- above any real duplicate set and below the PostgREST row cap, so the caller
-- always sees the whole report rather than a silently truncated one.
--
-- NOT A DELETE, the same as 0108: every row keeps its UCN, its visits and its
-- quality records, and reads as Cancelled.
-- ===========================================================================

create or replace function public.cancel_calls(p_ucns text[], p_reason text)
returns table (ucn text, ok boolean, error text)
language plpgsql
as $$
declare
  v_list text[];
  v_one  text;
  v_n    int;
begin
  -- Asked once, for the batch, rather than being discovered on call 1 of 50.
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'A cancellation needs a reason';
  end if;

  -- DE-DUPLICATED AND EMPTIES DROPPED. The same UCN twice in one selection is
  -- a client-side accident, and left alone it produces a row reading
  -- "already cancelled" against a call THIS batch had just cancelled — which
  -- reads as a fault and is not one.
  select coalesce(array_agg(distinct btrim(u)), '{}'::text[])
    into v_list
    from unnest(coalesce(p_ucns, '{}'::text[])) as u
   where coalesce(btrim(u), '') <> '';

  v_n := coalesce(array_length(v_list, 1), 0);
  if v_n = 0 then return; end if;
  if v_n > 500 then
    raise exception 'Too many calls in one go: % (the limit is 500)', v_n;
  end if;

  foreach v_one in array v_list loop
    begin
      perform public.cancel_call(v_one, p_reason);
      ucn := v_one; ok := true; error := null;
    exception when others then
      -- The message is passed through WORD FOR WORD. 0108 already says the
      -- useful thing ("Call X is already cancelled", "No call with UCN X",
      -- "RBAC: your role cannot cancel a call"), and a summary written here
      -- would be a second, worse copy of it.
      ucn := v_one; ok := false; error := sqlerrm;
    end;
    return next;
  end loop;
end $$;

revoke all on function public.cancel_calls(text[], text) from public;
grant execute on function public.cancel_calls(text[], text) to authenticated;

comment on function public.cancel_calls(text[], text) is
  'Cancel many calls with one reason. Loops cancel_call() per UCN in its own '
  'subtransaction and returns one row per UCN (ucn, ok, error). SECURITY '
  'INVOKER by design: the permission check lives in cancel_call().';

-- ------------------------------------------------------------------------
-- 0232_call_request_edit.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A CALL REQUEST CAN BE CORRECTED — UNTIL IT HAS BECOME A CALL.
--
--   The user, 2026-09-22: "Add a Provision in Call Request for me to edit it."
--
-- A request is typed in the field, often from a phone, and the serial, the
-- model or the customer is the thing most often wrong. Until now the only way
-- to fix one was to cancel it and raise another, which loses the original
-- timestamp and leaves two rows for one request.
--
-- THE PERMISSION ALREADY EXISTED and is not widened here: `cr_update` (0003)
-- lets `calls.create`, `pending.register` or the person who RAISED it write the
-- row. What was missing was a form, and one control.
--
-- THE CONTROL: ONCE A REQUEST HAS BECOME A CALL, ITS CONTENT IS FROZEN. The
-- call carries the customer, the machine and the complaint from that moment on;
-- editing the request afterwards leaves two records disagreeing about one
-- machine, and the call is the one everything downstream reads. The correction
-- belongs on the CALL, where it is audited.
--
-- IT FREEZES THE CONTENT AND NOT THE DISPOSITION, which is why this is a
-- trigger rather than a policy. Registering a request writes `ucn`, `status`,
-- `actioned_by` and `actioned_at`; cancelling writes `status`, `cancel_reason`
-- and `cancelled_at`. A rule that froze the whole row would stop the very
-- flows that move a request out of Pending. Those four (plus the cancel three)
-- stay writable in every state; the sixteen columns that describe WHAT was
-- asked for stop moving once the answer exists.
--
-- A trigger rather than a client rule because `cr_update` lets the raiser write
-- their own row: a control that lives only in the form is one that a direct API
-- call walks past.
--
-- THE `::text` CASTS ON THE APPENDS ARE NOT NOISE. `text[] || 'Serial No'`
-- leaves Postgres to choose between array||element and array||array, and it
-- picks the second: the guard fired with `malformed array literal: "Serial No"`
-- instead of the sentence below. It refused the write either way, which is
-- exactly why it would have shipped -- the test that caught it asserted the
-- MESSAGE, not the refusal.
-- ===========================================================================

create or replace function public.call_request_content_frozen()
returns trigger language plpgsql as $$
declare
  was text := lower(btrim(coalesce(old.status, '')));
  changed text[] := '{}';
begin
  -- Pending is the editable state. Anything else means the request has been
  -- answered -- registered as a call, mapped to one, or cancelled.
  if was in ('', 'pending') then return new; end if;

  if new.party_name              is distinct from old.party_name              then changed := changed || 'Party'::text; end if;
  if new.state                   is distinct from old.state                   then changed := changed || 'State'::text; end if;
  if new.city                    is distinct from old.city                    then changed := changed || 'City'::text; end if;
  if new.address                 is distinct from old.address                 then changed := changed || 'Address'::text; end if;
  if new.product                 is distinct from old.product                 then changed := changed || 'Product'::text; end if;
  if new.serial_no               is distinct from old.serial_no               then changed := changed || 'Serial No'::text; end if;
  if new.standard_complaint      is distinct from old.standard_complaint      then changed := changed || 'Standard Complaint'::text; end if;
  if new.reported_problem        is distinct from old.reported_problem        then changed := changed || 'Reported Problem'::text; end if;
  if new.call_type               is distinct from old.call_type               then changed := changed || 'Call Type'::text; end if;
  if new.engineer                is distinct from old.engineer                then changed := changed || 'Engineer'::text; end if;
  if new.email                   is distinct from old.email                   then changed := changed || 'Email'::text; end if;
  if new.customer_contact_details is distinct from old.customer_contact_details then changed := changed || 'Customer Contact'::text; end if;
  if new.customer_contact_number is distinct from old.customer_contact_number then changed := changed || 'Customer Number'::text; end if;
  if new.plan_date               is distinct from old.plan_date               then changed := changed || 'Plan Date'::text; end if;
  if new.additional_comments     is distinct from old.additional_comments     then changed := changed || 'Additional Comments'::text; end if;
  if new.call_attended           is distinct from old.call_attended           then changed := changed || 'Call Attended'::text; end if;

  if array_length(changed, 1) is not null then
    raise exception
      'This request is already % — % cannot be changed here. The call carries these details now, so correct them on the call itself; changing the request would leave the two disagreeing about one machine.',
      coalesce(old.status, 'answered'), array_to_string(changed, ', ');
  end if;
  return new;
end $$;

drop trigger if exists zz_call_request_content_frozen on public.call_requests;
create trigger zz_call_request_content_frozen
  before update on public.call_requests
  for each row execute function public.call_request_content_frozen();

comment on function public.call_request_content_frozen() is
  'A call request may be corrected while it is Pending. Once it has become a call — Registered, Mapped or Cancelled — the sixteen columns describing WHAT was asked for stop moving, because the call carries them from that moment and the call is what everything downstream reads. The disposition columns (ucn, status, actioned_by/at, cancel_reason, cancelled_at) stay writable in every state, or registering and cancelling would themselves be refused.';

-- ------------------------------------------------------------------------
-- 0260_rename_passes_the_request_freeze.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- AN ANSWERED CALL REQUEST FOLLOWS A RENAME OF ITS ENGINEER (0259, finding 23).
--
-- `call_request_content_frozen` (0232) refuses any change to an answered
-- request, the engineer included, because the call now carries those details
-- and the two must not disagree. A User Master rename is the one change that
-- keeps them agreeing: 0259 renames the call's allottee in the same statement.
-- So the Engineer line alone admits exactly that rename, recognised by the
-- ticket 0259 files for its own transaction. Every other field stays frozen,
-- and so does the engineer for anybody else. Body taken from the database.
-- ===========================================================================

create or replace function public.call_request_content_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $$
declare
  was text := lower(btrim(coalesce(old.status, '')));
  changed text[] := '{}';
begin
  -- Pending is the editable state. Anything else means the request has been
  -- answered -- registered as a call, mapped to one, or cancelled.
  if was in ('', 'pending') then return new; end if;

  if new.party_name              is distinct from old.party_name              then changed := changed || 'Party'::text; end if;
  if new.state                   is distinct from old.state                   then changed := changed || 'State'::text; end if;
  if new.city                    is distinct from old.city                    then changed := changed || 'City'::text; end if;
  if new.address                 is distinct from old.address                 then changed := changed || 'Address'::text; end if;
  if new.product                 is distinct from old.product                 then changed := changed || 'Product'::text; end if;
  if new.serial_no               is distinct from old.serial_no               then changed := changed || 'Serial No'::text; end if;
  if new.standard_complaint      is distinct from old.standard_complaint      then changed := changed || 'Standard Complaint'::text; end if;
  if new.reported_problem        is distinct from old.reported_problem        then changed := changed || 'Reported Problem'::text; end if;
  if new.call_type               is distinct from old.call_type               then changed := changed || 'Call Type'::text; end if;
  -- A USER MASTER RENAME (0259) moves the engineer's NAME and nothing else, so
  -- the request and the call it became still agree about who it is.
  if new.engineer                is distinct from old.engineer
     and not public.engineer_rename_in_progress(old.engineer, new.engineer)
                                                                               then changed := changed || 'Engineer'::text; end if;
  if new.email                   is distinct from old.email                   then changed := changed || 'Email'::text; end if;
  if new.customer_contact_details is distinct from old.customer_contact_details then changed := changed || 'Customer Contact'::text; end if;
  if new.customer_contact_number is distinct from old.customer_contact_number then changed := changed || 'Customer Number'::text; end if;
  if new.plan_date               is distinct from old.plan_date               then changed := changed || 'Plan Date'::text; end if;
  if new.additional_comments     is distinct from old.additional_comments     then changed := changed || 'Additional Comments'::text; end if;
  if new.call_attended           is distinct from old.call_attended           then changed := changed || 'Call Attended'::text; end if;

  if array_length(changed, 1) is not null then
    raise exception
      'This request is already % — % cannot be changed here. The call carries these details now, so correct them on the call itself; changing the request would leave the two disagreeing about one machine.',
      coalesce(old.status, 'answered'), array_to_string(changed, ', ');
  end if;
  return new;
end $$;

-- ------------------------------------------------------------------------
-- 0287_call_keys_per_register.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0287 — EACH CALL REGISTER IS GOVERNED BY ITS OWN KEYS
--
-- Findings 57-67 (docs/PERMISSIONS_REVIEW.md), the user's decisions of
-- 2026-09-30: "63, 64: It should show the Individual View's Control Action and
-- its Check Box" -- each screen gets keys of its own, today's grants copied
-- across (0298) so nobody gains or loses anything on the day it ships -- and
-- "67: Break it down", with the old key kept as the PARENT of the new ones, so
-- a role holding it keeps everything until an administrator unticks it.
-- The parent rule itself is in has_perm() (0286, public.perm_parents).
--
-- This file: Installation and PM calls are edited, re-allocated, reported,
-- cancelled and re-opened with install.* and pm.* keys, and Field calls with
-- calls.* -- the section guard and the allot guard read the table they fire
-- on, and the functions that take a UCN ask call_perm() (0286).
-- ===========================================================================

-- ---- the write policies, per register ------------------------------------
-- 0127's policy with the register's own keys. The children name every way in:
-- a section of the call, a visit, or a re-allocation; the parents (edit,
-- report) satisfy their children through has_perm().
do $rls$
declare t text; reg text; vis text; may text;
begin
  if to_regclass('public.field_calls') is null then
    raise notice 'skip calls_update: the split call tables are not present yet';
    return;
  end if;
  vis := $v$ (select public.can_view_all_calls())
             or created_by = (select auth.uid())
             or actual_created_by = (select auth.uid())
             or coalesce(allocated_to, '') = ''
             or lower(trim(allocated_to)) in (select lower(trim(n)) from public.visible_engineer_names() as v(n)) $v$;
  foreach t in array array['field_calls', 'installation_calls', 'pm_calls'] loop
    reg := case t when 'installation_calls' then 'install' when 'pm_calls' then 'pm' else 'calls' end;
    may := format($m$ (select (public.has_perm('%1$s.edit.complaint')
                   or public.has_perm('%1$s.edit.customer')
                   or public.has_perm('%1$s.edit.vigilance')
                   or public.has_perm('%1$s.edit.contact')
                   or public.has_perm('%1$s.report.visit')
                   or public.has_perm('%1$s.allot'))) $m$, reg);
    execute format('drop policy if exists calls_update on public.%I', t);
    execute format('create policy calls_update on public.%1$I for update using (%2$s and (%3$s)) with check (%2$s and (%3$s))', t, may, vis);
  end loop;

  -- A PM call is created with the PM register's own key.
  drop policy if exists calls_insert on public.pm_calls;
  create policy calls_insert on public.pm_calls for insert with check (public.has_perm('pm.create'));
end $rls$;

CREATE OR REPLACE FUNCTION public.calls_edit_section_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  reg     text := case tg_table_name when 'installation_calls' then 'install' when 'pm_calls' then 'pm' else 'calls' end;
  me      uuid := auth.uid();
  free    boolean;
  changed boolean;
begin
  -- No signed-in user (import, definer, scheduled) is not a person, and an
  -- administrator is every person. `calls.edit` is the parent of all four.
  free := me is null or public.is_admin() or public.has_perm(reg || '.edit');

  if not free then
    changed := new.standard_complaint is distinct from old.standard_complaint
            or new.complaint_reported is distinct from old.complaint_reported
            or new.breakdown_date     is distinct from old.breakdown_date;
    if changed and not public.has_perm(reg || '.edit.complaint') then
      raise exception 'RBAC: changing the complaint needs the "Edit the complaint" permission';
    end if;

    changed := new.party_name   is distinct from old.party_name
            or new.city         is distinct from old.city
            or new.state        is distinct from old.state
            or new.product_name is distinct from old.product_name
            or new.serial       is distinct from old.serial
            or new.item_status  is distinct from old.item_status;
    if changed and not public.has_perm(reg || '.edit.customer') then
      raise exception 'RBAC: changing the customer or the machine needs the "Edit customer & product" permission';
    end if;

    changed := new.customer_name        is distinct from old.customer_name
            or new.customer_number      is distinct from old.customer_number
            or new.customer_designation is distinct from old.customer_designation;
    if changed and not public.has_perm(reg || '.edit.contact') then
      raise exception 'RBAC: changing the customer contact needs the "Edit customer contact details" permission';
    end if;

    changed := new.public_health_threat is distinct from old.public_health_threat
            or new.death                is distinct from old.death
            or new.serious_incident     is distinct from old.serious_incident;
    if changed and not public.has_perm(reg || '.edit.vigilance') then
      raise exception 'RBAC: changing the vigilance answers needs the "Edit the vigilance answers" permission';
    end if;
  end if;

  -- The record, in the same statement as the change — including an
  -- administrator's, and including one made with no signed-in user, because
  -- "who changed the vigilance answer" is a question about the answer and not
  -- about permissions.
  insert into public.call_vigilance_changes (ucn, field, was, now_is, changed_by)
  select new.ucn, f.name, coalesce(f.was, ''), coalesce(f.now_is, ''), me
    from (values
      ('public_health_threat', old.public_health_threat, new.public_health_threat),
      ('death',                old.death,                new.death),
      ('serious_incident',     old.serious_incident,     new.serious_incident)
    ) as f(name, was, now_is)
   where f.now_is is distinct from f.was;

  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.calls_allot_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.allocated_to is not distinct from old.allocated_to then
    return new;                                   -- not a re-allocation
  end if;
  if auth.uid() is null then
    return new;                                   -- import / definer / scheduled
  end if;
  if public.is_admin() then
    return new;
  end if;
  if not public.has_perm(case tg_table_name when 'installation_calls' then 'install' when 'pm_calls' then 'pm' else 'calls' end || '.allot') then
    raise exception
      'RBAC: moving a call to another engineer needs the "Re-allocate a call to another engineer" permission';
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.cancel_call(p_ucn text, p_reason text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_cancelled timestamptz; v_exists boolean;
begin
  if not public.call_perm(p_ucn, 'cancel') then
    raise exception 'RBAC: your role cannot cancel a call';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'A cancellation needs a reason';
  end if;

  select true, cancelled_at into v_exists, v_cancelled
    from public.calls where ucn = p_ucn;
  if v_exists is null then raise exception 'No call with UCN %', p_ucn; end if;
  if v_cancelled is not null then raise exception 'Call % is already cancelled', p_ucn; end if;

  update public.calls
     set cancelled_at  = now(),
         cancel_reason = btrim(p_reason),
         cancelled_by  = auth.uid()
   where ucn = p_ucn;

  return p_ucn;
end $function$;

CREATE OR REPLACE FUNCTION public.restore_call(p_ucn text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_cancelled timestamptz; v_exists boolean;
begin
  if not public.call_perm(p_ucn, 'cancel') then
    raise exception 'RBAC: your role cannot restore a call';
  end if;

  select true, cancelled_at into v_exists, v_cancelled
    from public.calls where ucn = p_ucn;
  if v_exists is null then raise exception 'No call with UCN %', p_ucn; end if;
  if v_cancelled is null then raise exception 'Call % is not cancelled', p_ucn; end if;

  update public.calls set cancelled_at = null, cancelled_by = null where ucn = p_ucn;
  return p_ucn;
end $function$;

CREATE OR REPLACE FUNCTION public.reopen_call(p_ucn text, p_reason text DEFAULT ''::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_solved boolean; v_reopened timestamptz;
begin
  if not public.call_perm(p_ucn, 'reopen') then
    raise exception 'RBAC: your role cannot re-open a call';
  end if;

  select open_state = 'Solved', reopened_at into v_solved, v_reopened
    from public.calls where ucn = p_ucn;
  if v_solved is null then raise exception 'No call with UCN %', p_ucn; end if;
  if v_reopened is not null then raise exception 'Call % is already re-opened', p_ucn; end if;
  if not v_solved then raise exception 'Call % is not closed, so there is nothing to re-open', p_ucn; end if;

  update public.calls
     set reopened_at = now(), reopen_count = coalesce(reopen_count, 0) + 1
   where ucn = p_ucn;

  return p_ucn;
end $function$;

CREATE OR REPLACE FUNCTION public.close_call(p_ucn text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_found boolean; v_state text; v_reopened timestamptz; v_cancelled timestamptz;
begin
  -- The same gate as re-opening: whoever may put a call back on the open list
  -- may take one off it.
  if not public.call_perm(p_ucn, 'reopen') then
    raise exception 'RBAC: your role cannot close a call';
  end if;

  select true, open_state, reopened_at, cancelled_at
    into v_found, v_state, v_reopened, v_cancelled
    from public.calls where ucn = p_ucn;
  if v_found is null then raise exception 'No call with UCN %', p_ucn; end if;
  if v_cancelled is not null then
    raise exception 'Call % is cancelled — restore it before closing it', p_ucn;
  end if;
  if v_reopened is not null then
    raise exception 'Call % is re-opened — use Close again, which gives the re-open back', p_ucn;
  end if;
  if v_state = 'Solved' then raise exception 'Call % is already closed', p_ucn; end if;

  -- No visit is invented: last_visit_at is untouched, so the visit history
  -- still says what actually happened, which is nothing.
  update public.calls set last_status = 'Solved' where ucn = p_ucn;

  return p_ucn;
end $function$;

CREATE OR REPLACE FUNCTION public.close_reopened_call(p_ucn text, p_reason text DEFAULT ''::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_reopened timestamptz; v_found boolean;
begin
  if not public.call_perm(p_ucn, 'reopen') then
    raise exception 'RBAC: your role cannot close a re-opened call';
  end if;

  select true, reopened_at into v_found, v_reopened
    from public.calls where ucn = p_ucn;
  if v_found is null then raise exception 'No call with UCN %', p_ucn; end if;
  if v_reopened is null then
    raise exception 'Call % is not re-opened — close it by entering the visit that solved it', p_ucn;
  end if;

  update public.calls
     set reopened_at  = null,
         reopen_count = greatest(coalesce(reopen_count, 0) - 1, 0)
   where ucn = p_ucn;

  return p_ucn;
end $function$;

-- ------------------------------------------------------------------------
-- 0311_cancel_needs_an_open_call.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A CALL IS CANCELLED ONLY WHILE IT IS STILL OPEN (D-036, FRS-133).
--
-- The user's rule: a call may be cancelled only while it is Unattended or
-- Unsolved, because cancelling a call that was visited and closed takes what
-- was done out of every count. The rule lived in ONE place -- `canCancelRow`
-- in FieldCalls.tsx, which offers 🚫 only while the state is blank,
-- Unattended or Unsolved and the call is not re-opened. `cancel_call()` (0108)
-- tested the right, the reason, existence and whether it was already
-- cancelled, and nothing about state; `cancel_calls()` (0242) loops it. So a
-- holder of calls.cancel could cancel a Solved or Re-opened call through the
-- data interface.
--
-- WHAT CHANGES: cancel_call() refuses a call whose state is anything but
-- blank, Unattended or Unsolved, or that is re-opened -- the screen's test,
-- word for word. cancel_calls() inherits it, because it calls this function.
-- WHAT DOES NOT: the right (call_perm(.., 'cancel')), the reason, the
-- already-cancelled refusal, and what is written. Restoring a cancelled call
-- is untouched.
-- ===========================================================================

create or replace function public.cancel_call(p_ucn text, p_reason text)
returns text language plpgsql security definer set search_path = public as $$
declare v_cancelled timestamptz; v_exists boolean; v_state text; v_reopened timestamptz;
begin
  if not public.call_perm(p_ucn, 'cancel') then
    raise exception 'RBAC: your role cannot cancel a call';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'A cancellation needs a reason';
  end if;

  select true, cancelled_at, open_state, reopened_at
    into v_exists, v_cancelled, v_state, v_reopened
    from public.calls where ucn = p_ucn;
  if v_exists is null then raise exception 'No call with UCN %', p_ucn; end if;
  if v_cancelled is not null then raise exception 'Call % is already cancelled', p_ucn; end if;
  -- THE SCREEN'S RULE (FieldCalls.tsx, canCancelRow), now the database's too.
  if v_reopened is not null or coalesce(v_state, '') not in ('', 'Unattended', 'Unsolved') then
    raise exception 'Call % is %: only an Unattended or Unsolved call can be cancelled',
      p_ucn, case when v_reopened is not null then 'Reopened' else v_state end;
  end if;

  update public.calls
     set cancelled_at  = now(),
         cancel_reason = btrim(p_reason),
         cancelled_by  = auth.uid()
   where ucn = p_ucn;

  return p_ucn;
end $$;

-- ------------------------------------------------------------------------
-- 0341_call_actions_need_sight_of_the_call.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0341 — A CALL IS RE-OPENED, CLOSED, CANCELLED OR RESTORED ONLY BY SOMEBODY
--        WHO CAN SEE IT  (second re-review, 2026-10-03: D-128)
--
-- reopen_call, close_call, close_reopened_call, cancel_call and restore_call are
-- SECURITY DEFINER and asked only the permission (call_perm), never whether the
-- caller can see the call. rm and rgm hold calls.reopen without data.view_all,
-- so, measured, an RM who could see neither call re-opened another team's
-- solved call and closed another team's Unattended call as Solved.
--
-- THE TEST IS THE READ RULE: call_visible_to_me() asks what calls_scoped_read
-- asks of a call -- an office role (can_view_all_calls), the creator or the
-- person who typed it in, an unallotted call, or one allotted to somebody in the
-- caller's team -- WITHOUT the has_perm('calls.view') half, so it is never
-- narrower than what a screen can show. Every call a screen lists therefore
-- still passes; only a call the caller cannot see is refused. cancel_calls()
-- loops cancel_call() and inherits it. It answers NULL ONLY for a UCN that is
-- no call (no row), so each function's own "No call with UCN" message still
-- comes first; for a real call it answers true or false, never NULL.
--
-- Each function below is its live definition (read from a database built from
-- every migration, 0287 / 0311) with ONE block added after the permission check.
-- ===========================================================================

create or replace function public.call_visible_to_me(p_ucn text)
returns boolean language sql stable security definer set search_path = public as $$
  -- coalesce(…, false): a call with no creator recorded must read "not mine",
  -- never NULL -- false OR NULL is NULL, and a NULL here would wave it through.
  select coalesce(public.can_see_call(c.allocated_to), false)
      or coalesce(c.created_by = auth.uid(), false)
      or coalesce(c.actual_created_by = auth.uid(), false)
    from public.calls c
   where c.ucn = p_ucn
   limit 1;
$$;
revoke execute on function public.call_visible_to_me(text) from public, anon, authenticated;

create or replace function public.reopen_call(p_ucn text, p_reason text DEFAULT ''::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_solved boolean; v_reopened timestamptz;
begin
  if not public.call_perm(p_ucn, 'reopen') then
    raise exception 'RBAC: your role cannot re-open a call';
  end if;
  -- 0333 (D-128): and only on a call the caller can see -- the read rule, so
  -- every call a screen shows passes and a call outside it is refused.
  if public.call_visible_to_me(p_ucn) is false then
    raise exception 'Call % is not one of yours to change', p_ucn using errcode = '42501';
  end if;

  select open_state = 'Solved', reopened_at into v_solved, v_reopened
    from public.calls where ucn = p_ucn;
  if v_solved is null then raise exception 'No call with UCN %', p_ucn; end if;
  if v_reopened is not null then raise exception 'Call % is already re-opened', p_ucn; end if;
  if not v_solved then raise exception 'Call % is not closed, so there is nothing to re-open', p_ucn; end if;

  update public.calls
     set reopened_at = now(), reopen_count = coalesce(reopen_count, 0) + 1
   where ucn = p_ucn;

  return p_ucn;
end $function$;

create or replace function public.close_call(p_ucn text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_found boolean; v_state text; v_reopened timestamptz; v_cancelled timestamptz;
begin
  -- The same gate as re-opening: whoever may put a call back on the open list
  -- may take one off it.
  if not public.call_perm(p_ucn, 'reopen') then
    raise exception 'RBAC: your role cannot close a call';
  end if;
  -- 0333 (D-128): and only on a call the caller can see -- the read rule, so
  -- every call a screen shows passes and a call outside it is refused.
  if public.call_visible_to_me(p_ucn) is false then
    raise exception 'Call % is not one of yours to change', p_ucn using errcode = '42501';
  end if;

  select true, open_state, reopened_at, cancelled_at
    into v_found, v_state, v_reopened, v_cancelled
    from public.calls where ucn = p_ucn;
  if v_found is null then raise exception 'No call with UCN %', p_ucn; end if;
  if v_cancelled is not null then
    raise exception 'Call % is cancelled — restore it before closing it', p_ucn;
  end if;
  if v_reopened is not null then
    raise exception 'Call % is re-opened — use Close again, which gives the re-open back', p_ucn;
  end if;
  if v_state = 'Solved' then raise exception 'Call % is already closed', p_ucn; end if;

  -- No visit is invented: last_visit_at is untouched, so the visit history
  -- still says what actually happened, which is nothing.
  update public.calls set last_status = 'Solved' where ucn = p_ucn;

  return p_ucn;
end $function$;

create or replace function public.close_reopened_call(p_ucn text, p_reason text DEFAULT ''::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_reopened timestamptz; v_found boolean;
begin
  if not public.call_perm(p_ucn, 'reopen') then
    raise exception 'RBAC: your role cannot close a re-opened call';
  end if;
  -- 0333 (D-128): and only on a call the caller can see -- the read rule, so
  -- every call a screen shows passes and a call outside it is refused.
  if public.call_visible_to_me(p_ucn) is false then
    raise exception 'Call % is not one of yours to change', p_ucn using errcode = '42501';
  end if;

  select true, reopened_at into v_found, v_reopened
    from public.calls where ucn = p_ucn;
  if v_found is null then raise exception 'No call with UCN %', p_ucn; end if;
  if v_reopened is null then
    raise exception 'Call % is not re-opened — close it by entering the visit that solved it', p_ucn;
  end if;

  update public.calls
     set reopened_at  = null,
         reopen_count = greatest(coalesce(reopen_count, 0) - 1, 0)
   where ucn = p_ucn;

  return p_ucn;
end $function$;

create or replace function public.cancel_call(p_ucn text, p_reason text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_cancelled timestamptz; v_exists boolean; v_state text; v_reopened timestamptz;
begin
  if not public.call_perm(p_ucn, 'cancel') then
    raise exception 'RBAC: your role cannot cancel a call';
  end if;
  -- 0333 (D-128): and only on a call the caller can see -- the read rule, so
  -- every call a screen shows passes and a call outside it is refused.
  if public.call_visible_to_me(p_ucn) is false then
    raise exception 'Call % is not one of yours to change', p_ucn using errcode = '42501';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'A cancellation needs a reason';
  end if;

  select true, cancelled_at, open_state, reopened_at
    into v_exists, v_cancelled, v_state, v_reopened
    from public.calls where ucn = p_ucn;
  if v_exists is null then raise exception 'No call with UCN %', p_ucn; end if;
  if v_cancelled is not null then raise exception 'Call % is already cancelled', p_ucn; end if;
  -- THE SCREEN'S RULE (FieldCalls.tsx, canCancelRow), now the database's too.
  if v_reopened is not null or coalesce(v_state, '') not in ('', 'Unattended', 'Unsolved') then
    raise exception 'Call % is %: only an Unattended or Unsolved call can be cancelled',
      p_ucn, case when v_reopened is not null then 'Reopened' else v_state end;
  end if;

  update public.calls
     set cancelled_at  = now(),
         cancel_reason = btrim(p_reason),
         cancelled_by  = auth.uid()
   where ucn = p_ucn;

  return p_ucn;
end $function$;

create or replace function public.restore_call(p_ucn text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_cancelled timestamptz; v_exists boolean;
begin
  if not public.call_perm(p_ucn, 'cancel') then
    raise exception 'RBAC: your role cannot restore a call';
  end if;
  -- 0333 (D-128): and only on a call the caller can see -- the read rule, so
  -- every call a screen shows passes and a call outside it is refused.
  if public.call_visible_to_me(p_ucn) is false then
    raise exception 'Call % is not one of yours to change', p_ucn using errcode = '42501';
  end if;

  select true, cancelled_at into v_exists, v_cancelled
    from public.calls where ucn = p_ucn;
  if v_exists is null then raise exception 'No call with UCN %', p_ucn; end if;
  if v_cancelled is null then raise exception 'Call % is not cancelled', p_ucn; end if;

  update public.calls set cancelled_at = null, cancelled_by = null where ucn = p_ucn;
  return p_ucn;
end $function$;

-- Two of the five were still executable by the public key (0057's grant to
-- PUBLIC); without a sign-in call_perm() refuses them anyway, so this takes
-- nothing from anybody and closes the door the lockdown (0248) closes elsewhere.
revoke execute on function public.reopen_call(text, text) from public, anon;
revoke execute on function public.close_reopened_call(text, text) from public, anon;
grant execute on function public.reopen_call(text, text) to authenticated;
grant execute on function public.close_reopened_call(text, text) to authenticated;

-- ------------------------------------------------------------------------
-- 0386_pm_dates_are_registration.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0386  PM CALLS: COMPLAINT DATE AND BREAKDOWN DATE ARE THE REGISTRATION DATE
--       (2026-10-05) -- a one-time correction of the batch already uploaded.
--
-- The user: "Map, Complaint Date, Break Down Date to the Same Date as Call
-- Registration" -- "I have already uploaded it -- this is only for PM" -- "Not
-- any other Call Types". PM Bulk Upload now writes both from the
-- registration date (pmImport.ts); this brings the PM calls uploaded before
-- that change into line.
--
-- SCOPE, deliberately narrow: PM calls only (pm_calls, call type P M VISIT),
-- and only those registered from 01-Oct-2026 -- the batch that was uploaded.
-- Older PM calls are left as they are; nothing else is touched.
--
-- THE SAME BATCH WENT IN WITHOUT ITS SERIALS (the sheet's "Product Serial
-- Number" was not a recognised heading until v0.10.117) -- the value was kept
-- in `extra`, so the serial is filled from there where the call has none.
-- Nothing is invented: a call whose extra carries no serial stays blank. The
-- engineer ("Call Allocated To") is NOT filled here: setting allocated_to
-- notifies the engineer, and 1,333 notifications are not a data fix.
--
-- Runs as the migration owner (no signed-in user), which the call guards
-- treat as an import. Idempotent: a re-run finds nothing to change.
-- ===========================================================================
do $$
declare n_dates integer := 0; n_serial integer := 0;
begin
  if to_regclass('public.pm_calls') is null then return; end if;

  update public.pm_calls
     set complaint_date = reg_date,
         breakdown_date = reg_date
   where call_type = 'P M VISIT'
     and reg_date >= date '2026-10-01'
     and (complaint_date is distinct from reg_date or breakdown_date is distinct from reg_date);
  get diagnostics n_dates = row_count;

  update public.pm_calls
     set serial = btrim(extra->>'Product Serial Number')
   where call_type = 'P M VISIT'
     and reg_date >= date '2026-10-01'
     and coalesce(btrim(serial), '') = ''
     and coalesce(btrim(extra->>'Product Serial Number'), '') <> '';
  get diagnostics n_serial = row_count;

  raise notice '0386: % PM call(s) now dated by their registration; % given the serial their upload carried', n_dates, n_serial;
end $$;

-- ------------------------------------------------------------------------
-- 0413_field_call_vigilance_answered.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0413 — A FIELD CALL IS REGISTERED WITH ITS THREE VIGILANCE QUESTIONS ANSWERED
--        (second re-review D-033; the user's decision, 2026-10-05)
--
-- Public Health Threat?, Death? and Serious Incident? carried defaultValue 'NO'
-- on the call form, so a call saved without anybody reading that section
-- recorded three answers nobody gave -- and Review 1 of the Daily Complaint
-- Review reads as done the moment the three are filled (review1Done, dccr.ts).
-- THE USER'S DECISION: "Blank, must be answered" -- the form has no default
-- and will not save until all three are YES or NO, and the database refuses a
-- signed-in registration of a FIELD call without them, however it is sent.
--
-- Scope, read from every writer: the Field Call register and Pending
-- Registrations both insert through the `calls` view, whose INSTEAD OF trigger
-- (calls_view_insert) runs as the caller and routes a field call into
-- field_calls -- so this trigger on field_calls sees them as `authenticated`.
-- Installation and PM calls are other tables and keep their default; calls
-- raised from a Sale Entry or a transfer are installation calls and record NO
-- by design (FRS-085.5). Not stopped: an import (bulk.upload / import.panel),
-- a connection with no session, a function running as its owner, and an
-- UPDATE (a call registered before this keeps what it has).
-- In the call_requests module, after 0341.
-- ===========================================================================

create or replace function public.field_call_vigilance_answered()
returns trigger language plpgsql security invoker set search_path = public as $$
declare v_missing text[] := '{}';
begin
  if auth.uid() is null then return new; end if;
  if current_user <> 'authenticated' then return new; end if;
  if public.has_perm('bulk.upload') or public.has_perm('import.panel') then return new; end if;
  if upper(btrim(coalesce(new.public_health_threat, ''))) not in ('YES', 'NO') then
    v_missing := v_missing || 'Public Health Threat?'::text;
  end if;
  if upper(btrim(coalesce(new.death, ''))) not in ('YES', 'NO') then
    v_missing := v_missing || 'Death?'::text;
  end if;
  if upper(btrim(coalesce(new.serious_incident, ''))) not in ('YES', 'NO') then
    v_missing := v_missing || 'Serious Incident?'::text;
  end if;
  if array_length(v_missing, 1) > 0 then
    raise exception 'Answer the vigilance questions before registering the call: %', array_to_string(v_missing, ', ')
      using errcode = '23514';
  end if;
  return new;
end $$;
revoke execute on function public.field_call_vigilance_answered() from public, anon, authenticated;
drop trigger if exists field_call_vigilance_answered on public.field_calls;
create trigger field_call_vigilance_answered
  before insert on public.field_calls
  for each row execute function public.field_call_vigilance_answered();

-- ------------------------------------------------------------------------
-- 0408_call_request_attended_not_future.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0408 — A CALL REQUEST'S ATTENDED DATE IS NOT IN THE FUTURE
--        (second re-review D-030, part 3)
--
-- The Attended Date on Request Registration had no upper bound, and it becomes
-- the complaint date of the call registered from the request -- so a call
-- could be dated days ahead, and every age and SLA measured from it starts in
-- the future. The form now stops at today; the database refuses the same for a
-- signed-in write, measured in India time (the day the engineer is living in,
-- not UTC's, which is still yesterday until 05:30).
-- On UPDATE only when attended_date itself changes, so a request recorded
-- before this is never refused for an unrelated edit.
-- Not stopped: an import (bulk.upload / import.panel), a connection with no
-- session, and a function running as its owner.
-- In the call_requests module, before the cr_read tail (0164).
-- ===========================================================================

create or replace function public.call_request_attended_not_future()
returns trigger language plpgsql security invoker set search_path = public as $$
begin
  if auth.uid() is null then return new; end if;
  if current_user <> 'authenticated' then return new; end if;
  if public.has_perm('bulk.upload') or public.has_perm('import.panel') then return new; end if;
  if new.attended_date is null then return new; end if;
  if tg_op = 'UPDATE' and new.attended_date is not distinct from old.attended_date then return new; end if;
  if new.attended_date > (now() at time zone 'Asia/Kolkata')::date then
    raise exception 'The Attended Date cannot be in the future (%)', to_char(new.attended_date, 'DD-Mon-YYYY')
      using errcode = '23514';
  end if;
  return new;
end $$;
revoke execute on function public.call_request_attended_not_future() from public, anon, authenticated;
drop trigger if exists call_request_attended_not_future on public.call_requests;
create trigger call_request_attended_not_future
  before insert or update of attended_date on public.call_requests
  for each row execute function public.call_request_attended_not_future();

-- ------------------------------------------------------------------------
-- 0411_call_reopen_reason_recorded.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0411 — A RE-OPEN RECORDS ITS REASON, ITS PERSON AND ITS TIME
--        (second re-review D-035, FRS-133.4, FRS-120.9)
--
-- reopen_call(p_ucn, p_reason) accepted a reason and wrote only reopened_at and
-- reopen_count: the reason was stored nowhere and no person was recorded,
-- while the Call Review tells the reviewer "the reason goes on the call"
-- (FRS-064). And it accepted an empty reason, which FRS-120.9 refuses.
--
-- public.call_reopens keeps one row per re-open -- the UCN, when, who (the
-- session, by id and name) and why -- so a call re-opened twice keeps both.
-- A history table rather than columns on the three call tables: a second
-- re-open would overwrite the first reason in a column, and the calls view is
-- a `t.*` view mirrored in 0245 that new columns would not reach.
-- It is written only by reopen_call() (no insert, update or delete policy),
-- and read by whoever may see the call.
--
-- reopen_call() is 0341's body unchanged, plus: an empty reason is refused,
-- and the row above is written. In the call_requests module, after 0341 and
-- before the cr_read tail.
-- ===========================================================================

create table if not exists public.call_reopens (
  id               bigint generated always as identity primary key,
  ucn              text not null,
  reopened_at      timestamptz not null default now(),
  reopened_by      uuid,
  reopened_by_name text not null default '',
  reason           text not null,
  created_at       timestamptz not null default now(),
  created_by       uuid
);
create index if not exists call_reopens_ucn_idx on public.call_reopens (ucn, reopened_at desc);
alter table public.call_reopens enable row level security;
revoke all on public.call_reopens from anon;
grant select on public.call_reopens to authenticated;
drop policy if exists call_reopens_read on public.call_reopens;
-- "May this person see the call" is asked of the calls view itself: it is
-- security_invoker, so the caller's own call policies decide, exactly as on
-- every register (call_visible_to_me() is not executable by a signed-in user).
create policy call_reopens_read on public.call_reopens for select
  using (exists (select 1 from public.calls c where c.ucn = call_reopens.ucn));

do $$
begin
  if to_regprocedure('public.sys_columns_attach(regclass)') is not null then
    perform public.sys_columns_attach('public.call_reopens'::regclass);
  end if;
end $$;

create or replace function public.reopen_call(p_ucn text, p_reason text default '')
returns text language plpgsql security definer set search_path = public as $$
declare v_solved boolean; v_reopened timestamptz;
begin
  if not public.call_perm(p_ucn, 'reopen') then
    raise exception 'RBAC: your role cannot re-open a call';
  end if;
  -- 0333 (D-128): and only on a call the caller can see -- the read rule, so
  -- every call a screen shows passes and a call outside it is refused.
  if public.call_visible_to_me(p_ucn) is false then
    raise exception 'Call % is not one of yours to change', p_ucn using errcode = '42501';
  end if;
  -- 0411 (D-035, FRS-120.9): a re-open says why.
  if btrim(coalesce(p_reason, '')) = '' then
    raise exception 'Give the reason for re-opening call %', p_ucn using errcode = '23514';
  end if;

  select open_state = 'Solved', reopened_at into v_solved, v_reopened
    from public.calls where ucn = p_ucn;
  if v_solved is null then raise exception 'No call with UCN %', p_ucn; end if;
  if v_reopened is not null then raise exception 'Call % is already re-opened', p_ucn; end if;
  if not v_solved then raise exception 'Call % is not closed, so there is nothing to re-open', p_ucn; end if;

  update public.calls
     set reopened_at = now(), reopen_count = coalesce(reopen_count, 0) + 1
   where ucn = p_ucn;

  -- 0411 (D-035, FRS-133.4): the reason, the person and the time, kept.
  insert into public.call_reopens (ucn, reopened_at, reopened_by, reopened_by_name, reason, created_by)
  values (p_ucn, now(), auth.uid(), coalesce(public.my_display_name(), auth.email(), ''), btrim(p_reason), auth.uid());

  return p_ucn;
end $$;

-- ------------------------------------------------------------------------
-- 0164_cr_read_initplan.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0164 — cr_read asks its questions ONCE per query, not once per row.
--
-- Reported 2026-09-11: "the Party drop-down keeps failing for the engineers ...
-- it works perfectly fine for me". The browser showed `canceling statement due
-- to statement timeout`.
--
-- WHAT IT IS. `cr_read` called its helpers BARE:
--
--   can_view_all_calls() or created_by = auth.uid() or lower(email) = ...
--
-- so Postgres evaluated them FOR EVERY ROW of call_requests. The sister policy
-- on the call tables (`calls_scoped_read`, 0127) wraps each one as
-- `(select f())`, which makes it an InitPlan evaluated ONCE — the same
-- treatment hso_write was given in 0095. cr_read never got it.
--
-- WHY IT HITS ENGINEERS AND NOT THE ADMINISTRATOR. The OR short-circuits. For
-- an administrator `can_view_all_calls()` is true at its first test
-- (`is_admin()`), so the row is admitted after one lookup. For an engineer it
-- is false, and only after all three of its branches have run; then
-- `auth.uid()` runs, then `auth.email()`. Every row, every time.
--
-- AND THE COST IS THE WHOLE TABLE, NOT WHAT THEY SEE. An engineer who can see
-- 112 requests still makes the database test all of them to find those 112.
--
-- MEASURED, on 3,000 requests with genuinely partial visibility (the engineer
-- sees 1,220 of 3,000):
--
--     engineer   1,840 ms  ->  7.4 ms
--     admin        189 ms  ->  5.5 ms
--
-- The 10x gap between the two IS the reported symptom, and it grows linearly
-- with the register: at the volume this database is heading for, an engineer's
-- read of the Call Request page approaches the 20-second statement timeout —
-- and a saturated instance is what takes the party search down with it.
--
-- VISIBILITY IS UNCHANGED, and that was proved rather than assumed: the rows
-- returned to an engineer and to an administrator were captured under the old
-- policy and the new one and diffed — byte-identical both times, on data where
-- each branch of the OR actually admits a different set (300 by registrant, 30
-- by e-mail, 1,000 by team).
--
-- MUST STAY LAST in the `call_requests` module of build-apply-bundles.mjs:
-- 0003 and 0053 both define cr_read, and a bundle replayed alone would put the
-- per-row version back.
-- ===========================================================================

drop policy if exists cr_read on public.call_requests;
create policy cr_read on public.call_requests for select to authenticated
  using (
    -- Each of these is now an InitPlan: one evaluation for the whole query.
        (select public.can_view_all_calls())
     or created_by = (select auth.uid())
     or lower(email) = lower((select auth.email()))
    -- Already a hashed SubPlan (one execution, then a hash probe per row), so
    -- it is left as it is.
     or lower(btrim(engineer)) in (
          select lower(btrim(v.n)) from public.visible_engineer_names() v(n))
  );

-- ------------------------------------------------------------------------
-- 0044_daily_call_review.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0044 — Daily Call Review (DCCR: Daily Customer Complaint Review Register).
--
-- Every FIELD call is reviewed, every day, in three stages:
--
--   Review 1  — asked at Call Registration itself: Public Health Threat?,
--               Death?, Serious Incident?. Already columns on the call, so
--               nothing new is stored; its DATE is the call registration date.
--   Review 2  — Risk to Patient / Any Clinical Impact, Warranty Failure (1yr),
--               Frequent Failure.
--   Review 3  — Complaint Grouping, Root Cause Key Word,
--               Spare / Consumable / Correction / Calibration.
--
-- Stages 2 and 3 live here, in `call_reviews`, one row per call keyed by UCN.
-- Keeping them off the call tables leaves the `calls` union view (0040) and its
-- INSTEAD OF routing untouched.
--
-- Derived, so the sheet's formulas cannot drift from the data:
--   • ANY POTENTIAL EFFECT — blank until all three Review 2 answers are in,
--     then YES if any of them is YES, else NO. (The register's ARRAYFORMULA.)
--   • ACTION TAKEN — defaults to 'FFR Generation' the moment Any Potential
--     Effect turns YES; whoever raises the report overwrites it with the FFR
--     number (e.g. FFR-001/26).
--   • REVIEW STATUS — which stage is outstanding: Review 1/2/3 Pending, or
--     Review Completed. Served by the `field_call_review` view below.
--
-- Also adds the two masters the review reads, both tagged PER PRODUCT:
--   • dccrgrouping — "DCCR Complaint Grouping"
--   • rootcause    — "Root Cause Key Word"
-- A value tagged COMM is common to every product. Their values ship in
-- 0046_dccr_master_values.sql.
--
-- Idempotent.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- 1. Review 2 + Review 3, one row per call.
-- ---------------------------------------------------------------------------
create table if not exists public.call_reviews (
  ucn                  text primary key,
  call_number          text not null default '',

  -- Review 2
  risk_to_patient      text not null default '',   -- YES | NO
  warranty_failure     text not null default '',   -- YES | NO  (failure within 1 yr)
  frequent_failure     text not null default '',   -- YES | NO
  review2_at           date,
  review2_by           text not null default '',

  -- Review 3
  complaint_grouping   text not null default '',   -- master: dccrgrouping
  root_cause_keyword   text not null default '',   -- master: rootcause
  spare_category       text not null default '',   -- SPARE | CONSUMABLE | CORRECTION | CALIBRATION | …
  service_observation  text not null default '',
  action_taken         text not null default '',   -- FFR Generation / the FFR number
  review3_at           date,
  review3_by           text not null default '',

  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  updated_by           uuid references auth.users (id)
);

-- A stage is COMPLETE when every answer it asks for has been given.
alter table public.call_reviews
  add column if not exists review2_done boolean
  generated always as (
    btrim(risk_to_patient) <> '' and btrim(warranty_failure) <> '' and btrim(frequent_failure) <> ''
  ) stored;

alter table public.call_reviews
  add column if not exists review3_done boolean
  generated always as (
    btrim(complaint_grouping) <> '' and btrim(root_cause_keyword) <> '' and btrim(spare_category) <> ''
  ) stored;

-- ANY POTENTIAL EFFECT — the register's ARRAYFORMULA, as a column:
--   blank while any of the three is blank, else YES if any is YES, else NO.
alter table public.call_reviews
  add column if not exists any_potential_effect text
  generated always as (
    case
      when btrim(risk_to_patient) = '' or btrim(warranty_failure) = '' or btrim(frequent_failure) = '' then ''
      when upper(btrim(risk_to_patient))  = 'YES' then 'YES'
      when upper(btrim(warranty_failure)) = 'YES' then 'YES'
      when upper(btrim(frequent_failure)) = 'YES' then 'YES'
      else 'NO'
    end
  ) stored;

create index if not exists call_reviews_call_number_idx on public.call_reviews (call_number);
create index if not exists call_reviews_review2_idx      on public.call_reviews (review2_done);
create index if not exists call_reviews_review3_idx      on public.call_reviews (review3_done);

-- ---------------------------------------------------------------------------
-- 2. Stamps: the review dates, and the action a YES calls for.
--
-- A stage's DATE is written when that stage is answered, and is not moved by a
-- later edit of the other stage. `action_taken` is seeded with 'FFR Generation'
-- when Any Potential Effect turns YES and nothing has been entered yet; it is
-- cleared again if the answers change back to NO and nobody has typed over it.
-- ---------------------------------------------------------------------------
create or replace function public.call_review_stamp()
returns trigger language plpgsql set search_path = public as $$
declare
  was2 boolean := case when tg_op = 'UPDATE' then old.review2_done else false end;
  was3 boolean := case when tg_op = 'UPDATE' then old.review3_done else false end;
  new_effect text := case
      when btrim(new.risk_to_patient) = '' or btrim(new.warranty_failure) = '' or btrim(new.frequent_failure) = '' then ''
      when upper(btrim(new.risk_to_patient))  = 'YES' then 'YES'
      when upper(btrim(new.warranty_failure)) = 'YES' then 'YES'
      when upper(btrim(new.frequent_failure)) = 'YES' then 'YES'
      else 'NO'
    end;
  done2 boolean := btrim(new.risk_to_patient) <> '' and btrim(new.warranty_failure) <> '' and btrim(new.frequent_failure) <> '';
  done3 boolean := btrim(new.complaint_grouping) <> '' and btrim(new.root_cause_keyword) <> '' and btrim(new.spare_category) <> '';
begin
  if done2 and new.review2_at is null then new.review2_at := current_date; end if;
  if not done2 and not was2 then new.review2_at := null; end if;
  if done3 and new.review3_at is null then new.review3_at := current_date; end if;
  if not done3 and not was3 then new.review3_at := null; end if;

  -- The action a potential effect calls for: raise a Field Failure Report.
  if new_effect = 'YES' and btrim(new.action_taken) = '' then
    new.action_taken := 'FFR Generation';
  elsif new_effect <> 'YES' and new.action_taken = 'FFR Generation' then
    new.action_taken := '';
  end if;

  new.updated_at := now();
  if new.updated_by is null then new.updated_by := auth.uid(); end if;
  return new;
end;
$$;

drop trigger if exists call_reviews_stamp on public.call_reviews;
create trigger call_reviews_stamp before insert or update on public.call_reviews
  for each row execute function public.call_review_stamp();

-- ---------------------------------------------------------------------------
-- 3. RLS — anyone who may see calls reads the reviews; changing one needs the
--    `review.edit` action (granted below to the roles that run the review).
-- ---------------------------------------------------------------------------
alter table public.call_reviews enable row level security;
grant select, insert, update, delete on public.call_reviews to authenticated;

drop policy if exists call_reviews_read on public.call_reviews;
create policy call_reviews_read on public.call_reviews for select
  using (auth.role() = 'authenticated');

drop policy if exists call_reviews_write on public.call_reviews;
create policy call_reviews_write on public.call_reviews for all
  using (public.has_perm('review.edit')) with check (public.has_perm('review.edit'));

-- `review.edit` on the roles that run the daily review. Admin already holds
-- every action; the rest gain it only if they do not have it already, so an
-- admin who has since removed it is not overruled on a re-run.
do $$
declare r text;
begin
  if to_regclass('public.app_roles') is null then return; end if;
  foreach r in array array['admin', 'hotline', 'nsm', 'rgm', 'rm', 'commercial'] loop
    update public.app_roles
       set permissions = coalesce(permissions, '[]'::jsonb) || '["review.edit"]'::jsonb
     where role = r and not coalesce(permissions, '[]'::jsonb) ? 'review.edit';
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- 4. The register the module reads: one row per FIELD call, with its three
--    review stages and which one is outstanding.
--
--    Review 1 is the registration's own three answers, so it is complete as
--    soon as all three have been given (they default to NO on the form) and
--    its date is the call registration date.
-- ---------------------------------------------------------------------------
-- Dropped and recreated rather than replaced: 0047 adds columns to this view,
-- so a re-run of THIS file would otherwise fail with "cannot drop columns from
-- view". 0047 runs after it and rebuilds the full shape either way.
drop view if exists public.field_call_review;
create view public.field_call_review as
select
  c.id,
  c.ucn,
  c.call_number,
  c.reg_date,
  c.complaint_date,
  c.party_name,
  c.city,
  c.state,
  c.product_name,
  c.serial,
  c.item_status,
  c.call_type,
  c.standard_complaint,
  c.complaint_reported,
  c.allocated_to,
  c.allocated_to_email,
  c.warranty_number,
  c.warranty_start,
  c.status,
  c.open_state,
  c.last_status,
  c.last_visit_at,
  -- Review 1 — from the call itself.
  c.public_health_threat,
  c.death,
  c.serious_incident,
  c.reg_date as review1_at,
  (btrim(coalesce(c.public_health_threat, '')) <> ''
   and btrim(coalesce(c.death, '')) <> ''
   and btrim(coalesce(c.serious_incident, '')) <> '') as review1_done,
  -- Review 2
  coalesce(r.risk_to_patient, '')     as risk_to_patient,
  coalesce(r.warranty_failure, '')    as warranty_failure,
  coalesce(r.frequent_failure, '')    as frequent_failure,
  r.review2_at,
  coalesce(r.review2_by, '')          as review2_by,
  coalesce(r.review2_done, false)     as review2_done,
  -- Review 3
  coalesce(r.complaint_grouping, '')  as complaint_grouping,
  coalesce(r.root_cause_keyword, '')  as root_cause_keyword,
  coalesce(r.spare_category, '')      as spare_category,
  coalesce(r.service_observation, '') as service_observation,
  r.review3_at,
  coalesce(r.review3_by, '')          as review3_by,
  coalesce(r.review3_done, false)     as review3_done,
  -- Derived
  coalesce(r.any_potential_effect, '') as any_potential_effect,
  coalesce(r.action_taken, '')         as action_taken,
  case
    when not (btrim(coalesce(c.public_health_threat, '')) <> ''
              and btrim(coalesce(c.death, '')) <> ''
              and btrim(coalesce(c.serious_incident, '')) <> '') then 'Review 1 Pending'
    when not coalesce(r.review2_done, false) then 'Review 2 Pending'
    when not coalesce(r.review3_done, false) then 'Review 3 Pending'
    else 'Review Completed'
  end as review_status
from public.field_calls c
left join public.call_reviews r on r.ucn = c.ucn;

alter view public.field_call_review set (security_invoker = on);
grant select on public.field_call_review to authenticated;

-- ---------------------------------------------------------------------------
-- 5. The two masters, tagged per product.
--
--    The same value legitimately exists for more than one product ("Calibration"
--    for MONNAL T60 and for MONNAL T75), so the uniqueness that 0021 put on
--    (name, value, stage) has to take the product in too. Widening it is a
--    relaxation — every existing list carries no product, so nothing that was
--    unique before stops being unique.
-- ---------------------------------------------------------------------------
drop index if exists public.masters_name_value_idx;
create unique index if not exists masters_name_value_product_idx
  on public.masters (name, value, (coalesce(extra->>'stage', '')), (coalesce(extra->>'product', '')));

insert into public.master_lists (key, label, value_label, columns, sort_order) values
  ('dccrgrouping', 'DCCR Complaint Grouping', 'Complaint Grouping',
   '[{"key": "product", "label": "Product"}]'::jsonb, 70),
  ('rootcause', 'Root Cause Key Word', 'Root Cause Key Word',
   '[{"key": "product", "label": "Product"}]'::jsonb, 80)
on conflict (key) do update set
  label = excluded.label, value_label = excluded.value_label,
  columns = excluded.columns, sort_order = excluded.sort_order, updated_at = now();

