CREATE OR REPLACE FUNCTION public.link_install_call(p_item_id bigint, p_ucn text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  it  public.sale_items%rowtype;
  v_ucn text := btrim(coalesce(p_ucn, ''));
begin
  if not (public.is_admin() or public.has_perm('cover.edit.entries') or public.has_perm('install.create')) then
    raise exception 'RBAC: mapping an installation call needs install.create or cover.edit.entries';
  end if;

  select * into it from public.sale_items where id = p_item_id for update;
  if not found then
    raise exception 'Machine line % is not on the warranty register', p_item_id;
  end if;

  if btrim(coalesce(it.inst_call, '')) = v_ucn then
    return;
  end if;
  if public.is_call_number(it.inst_call) then
    raise exception '% · % already has installation call %, which is not replaced here',
      it.product_name, it.serial_number, btrim(it.inst_call);
  end if;

  if not exists (
    select 1 from public.installation_calls c
     where c.ucn = v_ucn
       and lower(btrim(coalesce(c.serial, '')))       = lower(btrim(coalesce(it.serial_number, '')))
       and lower(btrim(coalesce(c.product_name, ''))) = lower(btrim(coalesce(it.product_name, '')))
  ) then
    raise exception 'Call % is not an installation call for % · %', v_ucn, it.product_name, it.serial_number;
  end if;

  update public.sale_items set inst_call = v_ucn where id = p_item_id;
end $function$;

-- ------------------------------------------------------------------------
-- 0318_warranty_party_refresh_once.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0318 — ONE TIME: every Warranty Sale Entry re-read from the Party Master, and
-- every machine on it put back on its entry.
--
-- The user, 2026-10-02: "As a 1 time activity - Update all Records in Warranty
-- Sale Entry with '↺ Update from Party Master' in one go. Include 'Force Update
-- Child Records' in Warranty Register as well. Enforce Update as a 1 time
-- activity." And, asked how: blanks are copied exactly as the button copies
-- them, and the machines of EVERY sale go back to following their sale.
--
-- STEP 1 IS THE BUTTON, FOR EVERY SALE AT ONCE. ↺ Update from Party Master
-- (partyFillForSale + partyInfoFrom in the client) sets ELEVEN fields from the
-- Party Master entry whose name matches the sale's Party Name -- the same
-- trimmed, case-insensitive match (`parties.name_key`) -- BLANKS INCLUDED:
--   state, city, address (falling back to extra->>'Address' only where the
--   column is NULL), pincode, tel1 <- phone, tel2 <- phone_2, pan, gst <- gstin,
--   party_type (CUSTOMER / DEALER, anything else blank), profile (PRIVATE /
--   GOVERNMENT / DEALER / GENERAL, anything else blank), engineer <-
--   service_engineer.
-- A sale whose party the master does not hold is left exactly as it is, as the
-- button leaves it ("nothing to update from"). Only a sale where at least one
-- of the eleven actually changes is written.
--
-- STEP 2 IS ↺ FORCE UPDATE CHILD RECORDS, FOR EVERY SALE. The thirteen columns
-- a sale line inherits (inheritAllPatch over SALE.itemFields) are set to NULL,
-- so each machine follows its entry -- including the values step 1 just
-- refreshed. Only a line holding at least one pinned value is written.
--
-- EVERY VALUE IT CHANGES IS KEPT. Before and after, per row, in two backup
-- tables nobody signed in can read or write -- so "what did this machine say
-- before 2 October?" has an answer, and a value somebody needs back can be
-- restored from it by hand.
--
-- ONCE, AND ENFORCED. The migration ledger runs this file once on the live
-- project; but a bundle is also REPLAYED to rebuild or repair a project, and a
-- second run would overwrite whatever has been typed since. So the work is
-- guarded by a row in `one_time_fixes_done`: present, and nothing is touched.
-- ===========================================================================

create table if not exists public.one_time_fixes_done (
  name       text primary key,
  applied_at timestamptz not null default now(),
  detail     text
);
alter table public.one_time_fixes_done enable row level security;
revoke all on public.one_time_fixes_done from anon, authenticated;

create table if not exists public.sale_party_refresh_backup (
  id         bigserial primary key,
  sa_number  text not null,
  party_name text,
  before     jsonb not null,
  after      jsonb not null,
  saved_at   timestamptz not null default now()
);
alter table public.sale_party_refresh_backup enable row level security;
revoke all on public.sale_party_refresh_backup from anon, authenticated;

create table if not exists public.sale_items_inherit_backup (
  id            bigserial primary key,
  item_id       bigint not null,
  sa_number     text,
  serial_number text,
  before        jsonb not null,
  saved_at      timestamptz not null default now()
);
alter table public.sale_items_inherit_backup enable row level security;
revoke all on public.sale_items_inherit_backup from anon, authenticated;

do $$
begin
  if to_regprocedure('public.sys_columns_attach(regclass)') is not null then
    perform public.sys_columns_attach('public.one_time_fixes_done'::regclass);
    perform public.sys_columns_attach('public.sale_party_refresh_backup'::regclass);
    perform public.sys_columns_attach('public.sale_items_inherit_backup'::regclass);
  end if;
end $$;

do $$
declare
  n_sales int := 0;
  n_items int := 0;
begin
  if exists (select 1 from public.one_time_fixes_done where name = '0318_warranty_party_refresh') then
    raise notice '0318: done before -- the warranty sales were not touched again';
    return;
  end if;
  if to_regclass('public.sale_entries') is null or to_regclass('public.sale_items') is null
     or to_regclass('public.parties') is null then
    raise notice '0318: sale_entries, sale_items or parties missing -- nothing to do (and not marked done)';
    return;
  end if;
  -- THE PARTY COLUMNS THE BUTTON READS come from the `masters` bundle (0200,
  -- 0201). This bundle can be replayed on its own, so they are asked for
  -- rather than assumed; missing, nothing is done and nothing is marked.
  if (select count(*) from information_schema.columns
       where table_schema = 'public' and table_name = 'parties'
         and column_name in ('state', 'city', 'address', 'extra', 'pincode', 'phone', 'phone_2',
                             'pan', 'gstin', 'party_type', 'profile', 'service_engineer', 'name_key')) < 13 then
    raise notice '0318: the Party Master lacks columns the update reads -- run masters.sql first (not marked done)';
    return;
  end if;

  -- ---- step 1: the Party Master onto every sale ----------------------------
  create temporary table _fill on commit drop as
  select s.id, s.sa_number, s.party_name,
         jsonb_build_object('state', s.state, 'city', s.city, 'address', s.address, 'pincode', s.pincode,
                            'tel1', s.tel1, 'tel2', s.tel2, 'pan', s.pan, 'gst', s.gst,
                            'party_type', s.party_type, 'profile', s.profile, 'engineer', s.engineer) as before,
         btrim(coalesce(p.state, ''))                                as state,
         btrim(coalesce(p.city, ''))                                 as city,
         btrim(coalesce(p.address, p.extra->>'Address', ''))         as address,
         btrim(coalesce(p.pincode, ''))                              as pincode,
         btrim(coalesce(p.phone, ''))                                as tel1,
         btrim(coalesce(p.phone_2, ''))                              as tel2,
         btrim(coalesce(p.pan, ''))                                  as pan,
         btrim(coalesce(p.gstin, ''))                                as gst,
         case when upper(btrim(coalesce(p.party_type, ''))) in ('CUSTOMER', 'DEALER')
              then upper(btrim(p.party_type)) else '' end            as party_type,
         case when upper(btrim(coalesce(p.profile, ''))) in ('PRIVATE', 'GOVERNMENT', 'DEALER', 'GENERAL')
              then upper(btrim(p.profile)) else '' end               as profile,
         btrim(coalesce(p.service_engineer, ''))                     as engineer
    from public.sale_entries s
    join public.parties p on p.name_key = lower(btrim(s.party_name))
   where btrim(coalesce(s.party_name, '')) <> '';

  delete from _fill f
   where (f.state, f.city, f.address, f.pincode, f.tel1, f.tel2, f.pan, f.gst, f.party_type, f.profile, f.engineer)
         is not distinct from
         (f.before->>'state', f.before->>'city', f.before->>'address', f.before->>'pincode',
          f.before->>'tel1', f.before->>'tel2', f.before->>'pan', f.before->>'gst',
          f.before->>'party_type', f.before->>'profile', f.before->>'engineer');

  insert into public.sale_party_refresh_backup (sa_number, party_name, before, after)
  select f.sa_number, f.party_name, f.before,
         jsonb_build_object('state', f.state, 'city', f.city, 'address', f.address, 'pincode', f.pincode,
                            'tel1', f.tel1, 'tel2', f.tel2, 'pan', f.pan, 'gst', f.gst,
                            'party_type', f.party_type, 'profile', f.profile, 'engineer', f.engineer)
    from _fill f;

  update public.sale_entries s
     set state = f.state, city = f.city, address = f.address, pincode = f.pincode,
         tel1 = f.tel1, tel2 = f.tel2, pan = f.pan, gst = f.gst,
         party_type = f.party_type, profile = f.profile, engineer = f.engineer
    from _fill f
   where s.id = f.id;
  get diagnostics n_sales = row_count;

  -- ---- step 2: every machine back on its sale ------------------------------
  insert into public.sale_items_inherit_backup (item_id, sa_number, serial_number, before)
  select i.id, i.sa_number, i.serial_number,
         jsonb_strip_nulls(jsonb_build_object(
           'warranty_start', i.warranty_start, 'warranty_end', i.warranty_end,
           'warranty_years', i.warranty_years, 'warranty_months', i.warranty_months,
           'pm_visits', i.pm_visits, 'warranty_status', i.warranty_status,
           'invoice_no', i.invoice_no, 'invoice_date', i.invoice_date,
           'sold_through', i.sold_through, 'other_details', i.other_details,
           'state', i.state, 'city', i.city, 'engineer', i.engineer))
    from public.sale_items i
   where coalesce(i.warranty_start::text, i.warranty_end::text, i.warranty_years::text, i.warranty_months::text,
                  i.pm_visits::text, i.warranty_status, i.invoice_no, i.invoice_date::text, i.sold_through,
                  i.other_details, i.state, i.city, i.engineer) is not null;

  update public.sale_items i
     set warranty_start = null, warranty_end = null, warranty_years = null, warranty_months = null,
         pm_visits = null, warranty_status = null, invoice_no = null, invoice_date = null,
         sold_through = null, other_details = null, state = null, city = null, engineer = null
   where coalesce(i.warranty_start::text, i.warranty_end::text, i.warranty_years::text, i.warranty_months::text,
                  i.pm_visits::text, i.warranty_status, i.invoice_no, i.invoice_date::text, i.sold_through,
                  i.other_details, i.state, i.city, i.engineer) is not null;
  get diagnostics n_items = row_count;

  insert into public.one_time_fixes_done (name, detail)
  values ('0318_warranty_party_refresh',
          format('%s sale(s) updated from the Party Master; %s machine line(s) put back on their sale', n_sales, n_items));
  raise notice '0318: % sale(s) updated from the Party Master; % machine line(s) put back on their sale', n_sales, n_items;
end $$;

-- ------------------------------------------------------------------------
-- 0319_install_call_mapping_once.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0319 — ONE TIME: every warranty machine mapped to its installation call,
-- and an administrators' list of the machines that still have none.
--
-- The user, 2026-10-02: "As a 1 time activity - look for all installation
-- calls using this - Product, Serial No, Party Name or WI-<Product>-<SerialNo>.
-- And map it. If it does not have an installation call give it as a separate
-- list in reports - view only for Admins."
--
-- 0234 already mapped a machine where EXACTLY ONE installation call named its
-- product and serial. This pass widens the search in the order the evidence is
-- strongest, and still maps only where the answer is ONE call:
--
--   1. WI-<Product>-<Serial>. The call number this application gives an
--      installation call it raises from a sale (installCallNumber), compared
--      trimmed and case-insensitive.
--
-- ONLY INSTALLATION CALLS, under every rule (the user, 2026-10-02: "Map only
-- installation call"). A field or PM call carrying a WI- number is not this
-- machine's installation and is never mapped or offered.
--   2. Product + Serial + Party Name, on an installation call. Settles a
--      machine two installation calls name, where only one was for this
--      customer.
--   3. Product + Serial alone, on an installation call -- 0234's rule, re-run
--      for calls raised or imported since.
--
-- WHAT IS NEVER DONE:
--   * a machine whose INST Call already holds a call number is not touched;
--   * a call already mapped to a machine is not mapped to a second one;
--   * where two machine lines would take the same call, neither does --
--     a duplicate line is a question, not an answer;
--   * where a rule finds several calls, nothing is written: picking one would
--     be a guess recorded as a fact. Those machines are on the list below,
--     with the candidate calls named.
-- Every change is logged in inst_call_repair_log (0234), old value beside new,
-- with the rule that made it.
--
-- ONCE, AND ENFORCED, as 0318: a row in one_time_fixes_done stops any re-run,
-- so replaying sales_contracts.sql never maps anything a second time.
--
-- THE LIST is install_calls_unmapped(): every warranty machine line without a
-- mapped installation call, why, and the candidates. A definer function with
-- the check inside, gated on the page's own key `mod:/install-calls-unmapped`,
-- which 0319 grants to admin (the user: "view only for Admins") and to
-- technical_support, because that role carries every page key the admin role
-- holds (0145; _status.sql row 114 holds the property) -- the Hand Stock
-- Report (0241) and Device Cache Status (0249) do the same. An administrator
-- can untick it, or tick it for another role, on Roles & Permissions. LIVE, so
-- it shrinks as calls are raised.
-- ===========================================================================

create table if not exists public.one_time_fixes_done (
  name       text primary key,
  applied_at timestamptz not null default now(),
  detail     text
);
alter table public.one_time_fixes_done enable row level security;
revoke all on public.one_time_fixes_done from anon, authenticated;

do $$
declare
  n1 int := 0; n2 int := 0; n3 int := 0;
begin
  if exists (select 1 from public.one_time_fixes_done where name = '0319_install_call_mapping') then
    raise notice '0319: done before -- no machine was mapped again';
    return;
  end if;
  if to_regclass('public.sale_items') is null or to_regclass('public.sale_entries') is null
     or to_regclass('public.calls') is null or to_regclass('public.inst_call_repair_log') is null
     or to_regprocedure('public.is_call_number(text)') is null then
    raise notice '0319: sale_items, sale_entries, calls, inst_call_repair_log or is_call_number() missing -- nothing mapped (and not marked done)';
    return;
  end if;

  -- The machines still waiting, with what identifies them.
  create temporary table _m on commit drop as
  select si.id, si.sa_number, si.product_name, si.serial_number, coalesce(si.inst_call, '') as old_value,
         upper(btrim(si.product_name)) as p, upper(btrim(si.serial_number)) as s,
         upper(btrim(coalesce(h.party_name, ''))) as party,
         upper('WI-' || btrim(si.product_name) || '-' || btrim(si.serial_number)) as wi
    from public.sale_items si
    left join public.sale_entries h on h.sa_number = si.sa_number
   where btrim(coalesce(si.product_name, '')) <> '' and btrim(coalesce(si.serial_number, '')) <> ''
     and not public.is_call_number(si.inst_call);

  -- Calls, once, in the comparable shape. A call already on a machine is out.
  create temporary table _c on commit drop as
  select c.ucn, upper(btrim(coalesce(c.call_number, ''))) as cn,
         upper(btrim(coalesce(c.product_name, ''))) as p, upper(btrim(coalesce(c.serial, ''))) as s,
         upper(btrim(coalesce(c.party_name, ''))) as party
    from public.calls c
   where public.is_call_number(c.ucn)
     and upper(coalesce(c.call_type, '')) like 'INSTALL%'
     and not exists (select 1 from public.sale_items x where upper(btrim(x.inst_call)) = upper(btrim(c.ucn)));

  create temporary table _pick (id bigint, ucn text, why text) on commit drop;

  -- One rule: the machines it gives exactly one call, where that call is
  -- wanted by exactly one machine. Applied in turn, each rule seeing what the
  -- previous one left.
  for i in 1..3 loop
    delete from _pick;
    insert into _pick (id, ucn, why)
    select m.id, min(c.ucn),
           case i when 1 then 'mapped by call number WI-<Product>-<Serial> on an installation call (0319)'
                  when 2 then 'mapped by product + serial + party on an installation call (0319)'
                  else        'mapped by product + serial on the only installation call for it (0319)' end
      from _m m
      join _c c on case i
                     when 1 then c.cn = m.wi
                     when 2 then c.p = m.p and c.s = m.s and c.party = m.party and m.party <> ''
                     else        c.p = m.p and c.s = m.s end
     group by m.id
    having count(distinct c.ucn) = 1;
    -- A call two machine lines both want goes to neither.
    delete from _pick where ucn in (select ucn from _pick group by ucn having count(*) > 1);

    insert into public.inst_call_repair_log (sale_item_id, sa_number, product_name, serial_number, old_value, new_value, why)
    select m.id, coalesce(m.sa_number, ''), coalesce(m.product_name, ''), coalesce(m.serial_number, ''),
           m.old_value, k.ucn, k.why
      from _pick k join _m m on m.id = k.id;
    update public.sale_items si set inst_call = k.ucn from _pick k where si.id = k.id;
    if i = 1 then get diagnostics n1 = row_count;
    elsif i = 2 then get diagnostics n2 = row_count;
    else get diagnostics n3 = row_count; end if;

    delete from _c where ucn in (select ucn from _pick);
    delete from _m where id in (select id from _pick);
  end loop;

  insert into public.one_time_fixes_done (name, detail)
  values ('0319_install_call_mapping',
          format('%s mapped by WI- number, %s by product + serial + party, %s by product + serial; %s machine line(s) still without one',
                 n1, n2, n3, (select count(*) from _m)));
  raise notice '0319: % mapped by WI- number, % by product + serial + party, % by product + serial; % machine line(s) still without one',
               n1, n2, n3, (select count(*) from _m);
end $$;

-- ---- the list: machines without an installation call -----------------------
create or replace function public.install_calls_unmapped()
returns table (
  sale_item_id   bigint,
  sa_number      text,
  party_name     text,
  product_code   text,
  product_name   text,
  serial_number  text,
  warranty_start date,
  warranty_end   date,
  inst_call      text,
  reason         text,
  candidates     text
)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.has_perm('mod:/install-calls-unmapped') then
    raise exception 'RBAC: Machines Without an Installation Call needs the mod:/install-calls-unmapped permission.'
      using errcode = '42501';
  end if;
  return query
  -- EQUALITY JOINS ONLY. The first version matched calls with an OR across
  -- two keys and tested "already mapped" with NOT IN per row: 2 min 47 s at
  -- 20,000 machine lines. Both keys are now joined by equality and unioned,
  -- and "mapped" is a set joined once.
  with m as (
    select si.id, si.sa_number, h.party_name, si.product_code, si.product_name, si.serial_number,
           coalesce(si.warranty_start, h.warranty_start) as ws,
           coalesce(si.warranty_end, h.warranty_end) as we,
           coalesce(si.inst_call, '') as ic,
           upper(btrim(coalesce(si.product_name, ''))) as p, upper(btrim(coalesce(si.serial_number, ''))) as s
      from public.sale_items si
      left join public.sale_entries h on h.sa_number = si.sa_number
     where not public.is_call_number(si.inst_call)
  ),
  ic as materialized (
    -- INSTALLATION CALLS ONLY (the user: "Map only installation call").
    select c.ucn, upper(btrim(c.ucn)) as u, btrim(c.party_name) as party,
           upper(btrim(coalesce(c.call_number, ''))) as cn,
           upper(btrim(coalesce(c.product_name, ''))) as p, upper(btrim(coalesce(c.serial, ''))) as s
      from public.calls c
     where public.is_call_number(c.ucn) and upper(coalesce(c.call_type, '')) like 'INSTALL%'
  ),
  mapped as materialized (
    select distinct upper(btrim(x.inst_call)) as u from public.sale_items x where public.is_call_number(x.inst_call)
  ),
  hit as (
    select m.id, ic.ucn, ic.u, ic.party from m join ic on ic.p = m.p and ic.s = m.s where m.p <> '' and m.s <> ''
    union
    select m.id, ic.ucn, ic.u, ic.party from m join ic on ic.cn = 'WI-' || m.p || '-' || m.s where m.p <> '' and m.s <> ''
  ),
  cand as (
    select h.id,
           string_agg(distinct h.ucn || coalesce(' (' || nullif(h.party, '') || ')', ''), ', ') as list,
           count(distinct h.ucn) as n,
           count(distinct h.ucn) filter (where mp.u is null) as n_free
      from hit h left join mapped mp on mp.u = h.u
     group by h.id
  )
  select m.id, m.sa_number, m.party_name, m.product_code, m.product_name, m.serial_number, m.ws, m.we,
         m.ic,
         case when m.p = '' or m.s = '' then 'The line has no product or no serial, so no call can be matched to it'
              when coalesce(cand.n, 0) = 0 then 'No installation call found for this product and serial'
              when cand.n_free = 0 then 'The installation call for this product and serial is already mapped to another machine line'
              when cand.n_free = 1 then 'One installation call matches but was not mapped automatically (another line claims it, or it arrived later) -- put its UCN in INST Call'
              else 'Several installation calls name this machine -- choose one and put its UCN in INST Call' end,
         coalesce(cand.list, '')
    from m left join cand on cand.id = m.id;
end $$;
revoke execute on function public.install_calls_unmapped() from public, anon;
grant execute on function public.install_calls_unmapped() to authenticated;

-- ---- the key: administrators to begin with ---------------------------------
-- MERGED, never overwritten, and a role with an empty set is left alone (its
-- empty array means "not configured"). Other roles are ticked on Roles &
-- Permissions.
do $$
declare n integer;
begin
  if to_regclass('public.app_roles') is null then return; end if;
  update public.app_roles ar
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (select jsonb_array_elements_text(ar.permissions) as v
                   union select 'mod:/install-calls-unmapped') u),
         updated_at = now()
   where jsonb_array_length(ar.permissions) > 0
     and ar.role in ('admin', 'technical_support')
     and not (ar.permissions ? 'mod:/install-calls-unmapped');
  get diagnostics n = row_count;
  raise notice '0319: % of 2 role(s) given mod:/install-calls-unmapped (admin + technical_support -- grant the rest on Roles & Permissions)', n;
end $$;

-- ------------------------------------------------------------------------
-- 0328_sold_through_dealer_workflow.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0328 — SOLD THROUGH IS THE DEALER, AND A DEALER GETS NO INSTALLATION CALL.
--
-- The user, 2026-10-03: "Sold through -- it is to monitor the equipments sold
-- through Dealer. Only party identified as dealer should be listed as part of
-- the drop down. We can have a sale entry done to a dealer, but we can not have
-- an installation call for a dealer. And eventually the dealer sells the
-- product / products to customer at that point in time we do a Ownership
-- transfer and then generate an installation call from the ownership transfer
-- entry ... OT-PRODUCT-SERIAL NO ... In Product Database and ownership
-- transfer, Warranty Sale Entry we need to have the field to monitor Sold
-- through Details." Asked: on a transfer, Sold Through is THE FROM PARTY when
-- that party is a dealer; the transfer's call is dated the transfer date; the
-- dealer rule is kept by the database as well as the screen; and the Sold
-- Through values 0318 cleared are put back.
--
-- A DEALER is a Party Master entry whose Type (parties.party_type) is DEALER,
-- matched by name the way every cover screen matches a party (name_key).
--
-- 1. ownership_transfers.sold_through, STAMPED: the From party when the Party
--    Master types it DEALER, otherwise blank. What a caller sends is discarded
--    -- the dealer is a fact about the From party, not something typed.
-- 2. THE PRODUCT DATABASE'S Sold Through follows the machine: the dealer on
--    its latest transfer that names one, else the sale line's, else the sale
--    entry's (machine_sold_through). upsert_product_from_sale (0238) and
--    transfer_to_product (0238) are redefined from the database's own
--    definitions with that one change, so a re-saved sale cannot wipe the
--    dealer a transfer recorded.
-- 3. AN INSTALLATION CALL IS REFUSED FOR A DEALER, by a trigger on
--    installation_calls, for any signed-in insert or a change of party --
--    however it is raised (the warranty page, the Field Call form, an upload).
--    The call is raised from the Ownership Transfer when the dealer sells the
--    machine, named OT-PRODUCT-SERIAL. Calls already raised are left as they
--    are; a migration (no session) is not refused.
-- 4. ONCE: the Sold Through 0318 took off machine lines is put back from
--    sale_items_inherit_backup -- for every line still following its entry
--    whose own value was blank on the entry (lost) or different (replaced).
--    Guarded by one_time_fixes_done, so a replayed bundle never repeats it.
-- ===========================================================================

-- ---- the dealer test, one place -------------------------------------------
create or replace function public.party_is_dealer(p_name text)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(btrim(p_name), '') <> ''
     and exists (select 1 from public.parties p
                  where p.name_key = lower(btrim(p_name))
                    and upper(btrim(coalesce(p.party_type, ''))) = 'DEALER');
$$;
revoke execute on function public.party_is_dealer(text) from public, anon;
grant execute on function public.party_is_dealer(text) to authenticated;

-- ---- 1. Sold Through on a transfer ------------------------------------------
alter table public.ownership_transfers add column if not exists sold_through text not null default '';

create or replace function public.ownership_transfer_sold_through()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.sold_through := case when public.party_is_dealer(new.from_party) then btrim(new.from_party) else '' end;
  return new;
end $$;
revoke execute on function public.ownership_transfer_sold_through() from public, anon, authenticated;
-- Named to fire AFTER ownership_transfer_biu, which fills a blank From party
-- from whoever holds the machine.
drop trigger if exists ownership_transfer_sold_through on public.ownership_transfers;
create trigger ownership_transfer_sold_through
  before insert or update on public.ownership_transfers
  for each row execute function public.ownership_transfer_sold_through();

-- Transfers already recorded get theirs.
update public.ownership_transfers
   set sold_through = case when public.party_is_dealer(from_party) then btrim(from_party) else '' end
 where sold_through is distinct from (case when public.party_is_dealer(from_party) then btrim(from_party) else '' end);

-- ---- 2. the Product Database follows the machine ---------------------------
create or replace function public.machine_sold_through(p_item_name text, p_serial text)
returns text language sql stable set search_path = public as $$
  select t.sold_through
    from public.ownership_transfers t
   where lower(btrim(coalesce(t.item_name, '')))     = lower(btrim(coalesce(p_item_name, '')))
     and lower(btrim(coalesce(t.serial_number, ''))) = lower(btrim(coalesce(p_serial, '')))
     and btrim(coalesce(t.sold_through, '')) <> ''
   order by coalesce(t.transferred_at, t.created_at, t.transfer_date::timestamptz) desc nulls last, t.id desc
   limit 1;
$$;

-- 0238's upsert_product_from_sale, read from the database, with Sold Through
-- taken from the machine's latest dealer transfer first.
create or replace function public.upsert_product_from_sale(p_item_id bigint)
returns void language plpgsql security definer set search_path = public as $$
declare i record; h record; v_party text;
begin
  select * into i from public.sale_items where id = p_item_id;
  if not found then return; end if;

  if btrim(coalesce(i.product_name, '')) = '' or btrim(coalesce(i.serial_number, '')) = '' then
    return;
  end if;

  select * into h from public.sale_entries where sa_number = i.sa_number;

  -- NOT h.party_name. A machine sold and later transferred belongs to whoever
  -- holds it now, and re-saving the sale must not hand it back to the buyer.
  v_party := public.machine_current_party(i.product_name, i.serial_number);

  insert into public.products as p (
    item_name, serial_number, party_name,
    item_code, warranty_number,
    warranty_start, warranty_end, warranty_status_keyed, pm_visits,
    sold_through, state, city, address, other_details, service_engineer)
  values (
    btrim(i.product_name), btrim(i.serial_number), coalesce(v_party, ''),
    coalesce(i.product_code, ''), coalesce(i.sa_number, ''),
    coalesce(i.warranty_start, h.warranty_start),
    coalesce(i.warranty_end,   h.warranty_end),
    coalesce(nullif(btrim(coalesce(i.warranty_status, '')), ''), h.warranty_status, ''),
    coalesce(i.pm_visits, h.pm_visits),
    -- THE DEALER A TRANSFER RECORDED wins (0328): re-saving the sale must not
    -- wipe it.
    coalesce(public.machine_sold_through(i.product_name, i.serial_number),
             nullif(btrim(coalesce(i.sold_through, '')), ''), h.sold_through, ''),
    coalesce(nullif(btrim(coalesce(i.state, '')), ''), h.state, ''),
    coalesce(nullif(btrim(coalesce(i.city,  '')), ''), h.city,  ''),
    coalesce(h.address, ''),
    coalesce(nullif(btrim(coalesce(i.other_details, '')), ''), h.other_details, ''),
    coalesce(nullif(btrim(coalesce(i.engineer, '')), ''), h.engineer, ''))
  on conflict (machine_key) do update set
    party_name            = excluded.party_name,
    item_code             = excluded.item_code,
    warranty_number       = excluded.warranty_number,
    warranty_start        = excluded.warranty_start,
    warranty_end          = excluded.warranty_end,
    warranty_status_keyed = excluded.warranty_status_keyed,
    pm_visits             = excluded.pm_visits,
    sold_through          = excluded.sold_through,
    state                 = excluded.state,
    city                  = excluded.city,
    address               = excluded.address,
    other_details         = excluded.other_details,
    service_engineer      = excluded.service_engineer;
  -- `inst_call` IS NO LONGER WRITTEN HERE AT ALL, and that reverses yesterday's
  -- rule at the user's instruction: the installation call now BELONGS to the
  -- machine only while it names the current owner, which is decided on read.
  -- The stored column keeps whatever the import put there, as the keyed value.
end $$;

-- 0238's transfer_to_product, read from the database, with the dealer carried
-- onto a machine that has no sale entry.
create or replace function public.transfer_to_product()
returns trigger language plpgsql security definer set search_path = public as $$
declare r record; m record;
begin
  m := case when tg_op = 'DELETE' then old else new end;
  for r in select i.id from public.sale_items i
            where lower(btrim(coalesce(i.product_name, ''))) = lower(btrim(coalesce(m.item_name, '')))
              and lower(btrim(coalesce(i.serial_number, ''))) = lower(btrim(coalesce(m.serial_number, ''))) loop
    perform public.upsert_product_from_sale(r.id);
  end loop;

  -- A machine with NO sale entry still changes hands, and the transfer is then
  -- the only thing that knows who owns it -- and, since 0328, which dealer it
  -- came through.
  update public.products p
     set party_name   = public.machine_current_party(p.item_name, p.serial_number),
         sold_through = coalesce(public.machine_sold_through(p.item_name, p.serial_number), p.sold_through)
   where p.machine_key = lower(btrim(coalesce(m.item_name, ''))) || '|' || lower(btrim(coalesce(m.serial_number, '')))
     and not exists (select 1 from public.sale_items i
                      where lower(btrim(coalesce(i.product_name, ''))) = lower(btrim(coalesce(m.item_name, '')))
                        and lower(btrim(coalesce(i.serial_number, ''))) = lower(btrim(coalesce(m.serial_number, ''))));
  return null;
end $$;

-- ---- 3. no installation call for a dealer -----------------------------------
create or replace function public.installation_call_not_for_dealer()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return new; end if;          -- a migration, a repair
  if tg_op = 'UPDATE' and new.party_name is not distinct from old.party_name then return new; end if;
  if public.party_is_dealer(new.party_name) then
    raise exception '% is a dealer: an installation call is not raised for a dealer -- it is raised from the Ownership Transfer when the dealer sells the machine (OT-PRODUCT-SERIAL)', btrim(new.party_name)
      using errcode = '23514';
  end if;
  return new;
end $$;
revoke execute on function public.installation_call_not_for_dealer() from public, anon, authenticated;
drop trigger if exists installation_call_not_for_dealer on public.installation_calls;
create trigger installation_call_not_for_dealer
  before insert or update on public.installation_calls
  for each row execute function public.installation_call_not_for_dealer();

-- ---- 4. once: Sold Through put back on the lines 0318 cleared ---------------
do $$
declare n int := 0;
begin
  if to_regclass('public.one_time_fixes_done') is null or to_regclass('public.sale_items_inherit_backup') is null then
    raise notice '0328: 0318 has not run here -- no Sold Through to put back (not marked done)';
    return;
  end if;
  if exists (select 1 from public.one_time_fixes_done where name = '0328_sold_through_restored') then
    raise notice '0328: Sold Through was put back before -- not touched again';
    return;
  end if;

  update public.sale_items i
     set sold_through = b.v
    from (select distinct on (k.item_id) k.item_id, btrim(k.before ->> 'sold_through') as v
            from public.sale_items_inherit_backup k
           where btrim(coalesce(k.before ->> 'sold_through', '')) <> ''
           order by k.item_id, k.id) b,
         public.sale_entries e
   where i.id = b.item_id
     and e.sa_number = i.sa_number
     -- still following its entry, as 0318 left it: an edit since is kept
     and i.sold_through is null
     -- lost (the entry has none) or replaced (the entry's differs)
     and btrim(coalesce(e.sold_through, '')) is distinct from b.v;
  get diagnostics n = row_count;

  insert into public.one_time_fixes_done (name, detail)
  values ('0328_sold_through_restored', format('%s machine line(s) given back their own Sold Through', n));
  raise notice '0328: % machine line(s) given back their own Sold Through', n;
end $$;

-- ------------------------------------------------------------------------
-- 0329_transferred_machine_carries_new_owner_address.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0329 — A TRANSFERRED MACHINE CARRIES ITS NEW OWNER'S ADDRESS (D-098)
--
-- The user, 2026-10-03: "Transferred machine should carry the new owner's
-- address."
--
-- upsert_product_from_sale() (0237, revised by 0238 and 0328) already gives a
-- transferred machine its NEW owner's NAME -- machine_current_party() -- but
-- went on writing the address, city, state and Service Engineer from the SALE,
-- i.e. the ORIGINAL buyer. Every re-save of a sale (and 0318's one-time update,
-- which re-saved all of them) therefore put the first buyer's address back on
-- a machine somebody else now holds. The transfer itself (transfer_to_product)
-- changed only the name.
--
-- Now, wherever the machine's current owner is NOT the sale's buyer, those four
-- come from the current owner's PARTY MASTER entry -- the same place a sale
-- entry takes its own address from (0318). A field the Party Master leaves
-- blank keeps what the machine row already has rather than being blanked: a
-- blank there says nothing is recorded, not that the machine has no address.
-- A machine still with its buyer is untouched by this file.
--
-- ONE-TIME REPAIR, with the BACKUP 0318 did not take: every machine currently
-- with a transferee is given that owner's Party Master address now. The four
-- old values of every row it changes are kept in
-- products_new_owner_address_backup (service role only). Guarded by
-- one_time_fixes_done, so a replayed bundle never repeats it.
--
-- Both functions are re-read from the database (0328's revisions) before being
-- replaced; only the address fields change.
-- ===========================================================================

create or replace function public.upsert_product_from_sale(p_item_id bigint)
returns void language plpgsql security definer set search_path = public as $$
declare i record; h record; v_party text; v_moved boolean;
        -- Plain variables, not a record: a record SELECTed into only when the
        -- machine moved is "not assigned yet" for every machine that did not,
        -- and the INSERT below names its fields either way.
        o_address text; o_city text; o_state text; o_engineer text;
begin
  select * into i from public.sale_items where id = p_item_id;
  if not found then return; end if;

  if btrim(coalesce(i.product_name, '')) = '' or btrim(coalesce(i.serial_number, '')) = '' then
    return;
  end if;

  select * into h from public.sale_entries where sa_number = i.sa_number;

  -- NOT h.party_name. A machine sold and later transferred belongs to whoever
  -- holds it now, and re-saving the sale must not hand it back to the buyer.
  v_party := public.machine_current_party(i.product_name, i.serial_number);

  -- AND NOT THE BUYER'S ADDRESS EITHER (0329, D-098): a machine now with
  -- somebody else carries that owner's Party Master address, city, state and
  -- Service Engineer.
  v_moved := btrim(coalesce(v_party, '')) <> ''
         and lower(btrim(v_party)) is distinct from lower(btrim(coalesce(h.party_name, '')));
  if v_moved then
    select nullif(btrim(p.address), ''), nullif(btrim(p.city), ''),
           nullif(btrim(p.state), ''), nullif(btrim(p.service_engineer), '')
      into o_address, o_city, o_state, o_engineer
      from public.parties p where p.name_key = lower(btrim(v_party)) limit 1;
  end if;

  insert into public.products as p (
    item_name, serial_number, party_name,
    item_code, warranty_number,
    warranty_start, warranty_end, warranty_status_keyed, pm_visits,
    sold_through, state, city, address, other_details, service_engineer)
  values (
    btrim(i.product_name), btrim(i.serial_number), coalesce(v_party, ''),
    coalesce(i.product_code, ''), coalesce(i.sa_number, ''),
    coalesce(i.warranty_start, h.warranty_start),
    coalesce(i.warranty_end,   h.warranty_end),
    coalesce(nullif(btrim(coalesce(i.warranty_status, '')), ''), h.warranty_status, ''),
    coalesce(i.pm_visits, h.pm_visits),
    -- THE DEALER A TRANSFER RECORDED wins (0328): re-saving the sale must not
    -- wipe it.
    coalesce(public.machine_sold_through(i.product_name, i.serial_number),
             nullif(btrim(coalesce(i.sold_through, '')), ''), h.sold_through, ''),
    case when v_moved then coalesce(o_state, '')
         else coalesce(nullif(btrim(coalesce(i.state, '')), ''), h.state, '') end,
    case when v_moved then coalesce(o_city, '')
         else coalesce(nullif(btrim(coalesce(i.city,  '')), ''), h.city,  '') end,
    case when v_moved then coalesce(o_address, '')
         else coalesce(h.address, '') end,
    coalesce(nullif(btrim(coalesce(i.other_details, '')), ''), h.other_details, ''),
    case when v_moved then coalesce(o_engineer, '')
         else coalesce(nullif(btrim(coalesce(i.engineer, '')), ''), h.engineer, '') end)
  on conflict (machine_key) do update set
    party_name            = excluded.party_name,
    item_code             = excluded.item_code,
    warranty_number       = excluded.warranty_number,
    warranty_start        = excluded.warranty_start,
    warranty_end          = excluded.warranty_end,
    warranty_status_keyed = excluded.warranty_status_keyed,
    pm_visits             = excluded.pm_visits,
    sold_through          = excluded.sold_through,
    -- A transferee's blank Party Master field keeps what the row has.
    state                 = case when v_moved and excluded.state = '' then p.state else excluded.state end,
    city                  = case when v_moved and excluded.city = '' then p.city else excluded.city end,
    address               = case when v_moved and excluded.address = '' then p.address else excluded.address end,
    other_details         = excluded.other_details,
    service_engineer      = case when v_moved and excluded.service_engineer = '' then p.service_engineer
                                 else excluded.service_engineer end;
  -- `inst_call` IS NO LONGER WRITTEN HERE AT ALL, and that reverses yesterday's
  -- rule at the user's instruction: the installation call now BELONGS to the
  -- machine only while it names the current owner, which is decided on read.
  -- The stored column keeps whatever the import put there, as the keyed value.
end $$;
revoke execute on function public.upsert_product_from_sale(bigint) from public, anon, authenticated;

create or replace function public.transfer_to_product()
returns trigger language plpgsql security definer set search_path = public as $$
declare r record; m record;
begin
  m := case when tg_op = 'DELETE' then old else new end;
  for r in select i.id from public.sale_items i
            where lower(btrim(coalesce(i.product_name, ''))) = lower(btrim(coalesce(m.item_name, '')))
              and lower(btrim(coalesce(i.serial_number, ''))) = lower(btrim(coalesce(m.serial_number, ''))) loop
    perform public.upsert_product_from_sale(r.id);
  end loop;

  -- A machine with NO sale entry still changes hands, and the transfer is then
  -- the only thing that knows who owns it -- and, since 0328, which dealer it
  -- came through; since 0329, it takes that owner's Party Master address, city,
  -- state and Service Engineer, a blank there keeping what the row has.
  update public.products p
     set party_name       = c.party,
         sold_through     = coalesce(public.machine_sold_through(p.item_name, p.serial_number), p.sold_through),
         address          = coalesce(nullif(btrim(pm.address), ''), p.address),
         city             = coalesce(nullif(btrim(pm.city), ''), p.city),
         state            = coalesce(nullif(btrim(pm.state), ''), p.state),
         service_engineer = coalesce(nullif(btrim(pm.service_engineer), ''), p.service_engineer)
    from (select public.machine_current_party(m.item_name, m.serial_number) as party) c
    left join public.parties pm on pm.name_key = lower(btrim(coalesce(c.party, '')))
   where p.machine_key = lower(btrim(coalesce(m.item_name, ''))) || '|' || lower(btrim(coalesce(m.serial_number, '')))
     and not exists (select 1 from public.sale_items i
                      where lower(btrim(coalesce(i.product_name, ''))) = lower(btrim(coalesce(m.item_name, '')))
                        and lower(btrim(coalesce(i.serial_number, ''))) = lower(btrim(coalesce(m.serial_number, ''))));
  return null;
end $$;

-- ---- the one-time repair, backed up first ---------------------------------
create table if not exists public.one_time_fixes_done (
  name       text primary key,
  applied_at timestamptz not null default now(),
  detail     text
);
alter table public.one_time_fixes_done enable row level security;
revoke all on public.one_time_fixes_done from anon, authenticated;

create table if not exists public.products_new_owner_address_backup (
  id          bigserial primary key,
  machine_key text not null,
  party_name  text,
  before      jsonb not null,
  saved_at    timestamptz not null default now()
);
alter table public.products_new_owner_address_backup enable row level security;
revoke all on public.products_new_owner_address_backup from anon, authenticated;
do $$
begin
  if to_regprocedure('public.sys_columns_attach(regclass)') is not null then
    perform public.sys_columns_attach('public.products_new_owner_address_backup'::regclass);
  end if;
end $$;

do $$
declare n integer;
begin
  if exists (select 1 from public.one_time_fixes_done where name = '0329_new_owner_address') then
    raise notice '0329: transferred machines were given their new owner''s address before -- not touched again';
    return;
  end if;

  -- Every machine a transfer has moved, with the owner it has NOW and whether
  -- that owner is someone other than its buyer (or it has no sale at all).
  create temporary table t0329 on commit drop as
  select p.machine_key, pm.address, pm.city, pm.state, pm.service_engineer
    from (select distinct lower(btrim(coalesce(t.item_name, ''))) || '|' || lower(btrim(coalesce(t.serial_number, ''))) as k
            from public.ownership_transfers t
           where btrim(coalesce(t.to_party, '')) <> '') x
    join public.products p on p.machine_key = x.k
    join public.parties pm on pm.name_key = lower(btrim(coalesce(p.party_name, '')))
   where lower(btrim(coalesce(p.party_name, ''))) = lower(btrim(coalesce(public.machine_current_party(p.item_name, p.serial_number), '')))
     and not exists (
       select 1 from public.sale_items i join public.sale_entries e on e.sa_number = i.sa_number
        where lower(btrim(coalesce(i.product_name, ''))) || '|' || lower(btrim(coalesce(i.serial_number, ''))) = p.machine_key
          and lower(btrim(coalesce(e.party_name, ''))) = lower(btrim(coalesce(p.party_name, ''))));

  insert into public.products_new_owner_address_backup (machine_key, party_name, before)
  select p.machine_key, p.party_name,
         jsonb_build_object('address', p.address, 'city', p.city, 'state', p.state,
                            'service_engineer', p.service_engineer)
    from public.products p join t0329 t on t.machine_key = p.machine_key;

  update public.products p
     set address          = coalesce(nullif(btrim(t.address), ''), p.address),
         city             = coalesce(nullif(btrim(t.city), ''), p.city),
         state            = coalesce(nullif(btrim(t.state), ''), p.state),
         service_engineer = coalesce(nullif(btrim(t.service_engineer), ''), p.service_engineer)
    from t0329 t
   where p.machine_key = t.machine_key
     and (p.address, p.city, p.state, p.service_engineer) is distinct from
         (coalesce(nullif(btrim(t.address), ''), p.address), coalesce(nullif(btrim(t.city), ''), p.city),
          coalesce(nullif(btrim(t.state), ''), p.state),
          coalesce(nullif(btrim(t.service_engineer), ''), p.service_engineer));
  get diagnostics n = row_count;

  insert into public.one_time_fixes_done (name, detail)
  values ('0329_new_owner_address',
          format('%s transferred machine(s) given their new owner''s Party Master address', n));
  raise notice '0329: % transferred machine(s) given their new owner''s Party Master address (old values in products_new_owner_address_backup)', n;
end $$;

-- ------------------------------------------------------------------------
-- 0330_registers_fill_product_database.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0330 — THE THREE REGISTERS FILL THE PRODUCT DATABASE, BY PRODUCT + SERIAL
--
-- The user, 2026-10-03:
--   "Whenever I add a new sale entry, Insert the Product+SerialNo into the
--    product database. And map the Warranty Sale number, start date, end date,
--    pm visit - basically all relevant fields in product database.
--    When I add a contract entry, it should update the product database for
--    that product+serial number - Contract No, Contract start date, contract
--    end date, Contract Type, PM Visits.. basically all contract details.
--    During ownership transfer, the product+serial no should get updated --
--    all those details as per details in ownership transfer."
-- and, asked: a contract's PM visits OVERWRITE the machine's PM Visits; the
-- transfer's Ref (OT No.) and Date are carried; the sale's Invoice No., Invoice
-- Date, Warranty Years / Months and Accessories Included get columns; a
-- contract for a machine the Product Database does not hold INSERTS it.
--
-- WHAT WAS WRONG. The sale already inserted its machines (0237). The CONTRACT
-- reached products only through sync_product_cover(serial) (0036): by SERIAL
-- ALONE, so two models sharing a serial wore each other's contract (the
-- ORION-G 2410 / CPX CARE MC5521 case of 2026-09-14); it carried no PM visits
-- and no status, and it never inserted a machine.
--
-- NOW one function, sync_product_machine(product, serial), does the lot for
-- ONE machine, keyed exactly as products is (machine_key), and every path
-- calls it: a sale line or entry, a contract line or entry, a transfer, an
-- additional entry, and the after-import refresh.
--   * Sale  -> Warranty No., start, end, PM visits, Invoice No./Date, Warranty
--              Years/Months, Accessories Included -- from the machine's LATEST
--              sale line (by warranty end), each field the line's own or else
--              its entry's.
--   * Contract -> Contract No., start, end, type, status and PM visits (which
--              then OVERWRITE the sale's) -- from the machine's LATEST contract
--              line (by contract end), line first, then entry.
--   * Transfer -> Transfer Ref and Transfer Date of the latest transfer; the
--              owner, Sold Through and address stay with 0238/0328/0329.
--   * Additional entry -> still only where the registers are silent.
-- A contract number the machine carries that belongs to ANOTHER model sharing
-- its serial -- what the serial-only sync wrote -- is cleared, with its dates
-- and type, and likewise a warranty number from another model's sale. A value
-- with no register line at all (an imported one) is left as it is.
--
-- ONE-TIME RE-SYNC of every machine, with every changed row's old values kept
-- in products_resync_backup (service role only); guarded by
-- one_time_fixes_done so a replayed bundle never repeats it.
-- ===========================================================================

-- ---- 1. the columns the user asked for ------------------------------------
alter table public.products add column if not exists invoice_no           text;
alter table public.products add column if not exists invoice_date         date;
alter table public.products add column if not exists warranty_years       numeric;
alter table public.products add column if not exists warranty_months      integer;
alter table public.products add column if not exists accessories_included boolean;
alter table public.products add column if not exists transfer_ref         text;
alter table public.products add column if not exists transfer_date        date;

-- The contract lines are now looked up by machine, as the sale lines (0252).
create index if not exists contract_items_machine_expr_idx on public.contract_items
  (lower(btrim(coalesce(product_name, ''))), lower(btrim(coalesce(serial_number, ''))));

-- ---- 2. one machine, every register ---------------------------------------
create or replace function public.sync_product_machine(p_item text, p_serial text)
returns void language plpgsql security definer set search_path = public as $$
declare
  n text := lower(btrim(coalesce(p_item, '')));
  s text := lower(btrim(coalesce(p_serial, '')));
  k text;
  w record; c record; a record; t record; cur record; pm record;
  v_party text;
  foreign_contract boolean := false;
  foreign_warranty boolean := false;
begin
  if n = '' or s = '' then return; end if;
  k := n || '|' || s;

  select i.sa_number,
         coalesce(i.warranty_start, h.warranty_start) as ws,
         coalesce(i.warranty_end,   h.warranty_end)   as we,
         coalesce(i.pm_visits,      h.pm_visits)      as pm,
         coalesce(nullif(btrim(coalesce(i.invoice_no, '')), ''), nullif(btrim(coalesce(h.invoice_no, '')), '')) as inv,
         coalesce(i.invoice_date,    h.invoice_date)    as invd,
         coalesce(i.warranty_years,  h.warranty_years)  as wy,
         coalesce(i.warranty_months, h.warranty_months) as wm,
         i.accessories_included as acc
    into w
    from public.sale_items i left join public.sale_entries h on h.sa_number = i.sa_number
   where lower(btrim(coalesce(i.product_name, ''))) = n
     and lower(btrim(coalesce(i.serial_number, ''))) = s
   order by coalesce(i.warranty_end, h.warranty_end) desc nulls last, i.id desc limit 1;

  select i.mc_number, i.product_code,
         coalesce(nullif(btrim(coalesce(i.contract_type, '')), ''), h.contract_type) as ct,
         coalesce(i.contract_start, h.contract_start) as cs,
         coalesce(i.contract_end,   h.contract_end)   as ce,
         coalesce(i.pm_visits_total, h.pm_visits_total) as pm,
         coalesce(nullif(btrim(coalesce(i.status, '')), ''), h.status) as st,
         coalesce(nullif(btrim(coalesce(i.party_name, '')), ''), h.party_name) as party
    into c
    from public.contract_items i left join public.contract_entries h on h.mc_number = i.mc_number
   where lower(btrim(coalesce(i.product_name, ''))) = n
     and lower(btrim(coalesce(i.serial_number, ''))) = s
   order by coalesce(i.contract_end, h.contract_end) desc nulls last, i.id desc limit 1;

  -- The recovered detail, used only where the registers are silent.
  select e.warranty_number, e.warranty_start, e.warranty_end,
         e.contract_number, e.contract_type, e.contract_start, e.contract_end
    into a
    from public.product_additional_entries e where e.machine_key = k limit 1;

  select x.reference_no as ref, x.transfer_date as d
    into t
    from public.ownership_transfers x
   where lower(btrim(coalesce(x.item_name, ''))) = n
     and lower(btrim(coalesce(x.serial_number, ''))) = s
   order by coalesce(x.transferred_at, x.created_at, x.transfer_date::timestamptz) desc nulls last, x.id desc
   limit 1;

  -- A CONTRACT FOR A MACHINE NOT YET HELD is inserted (the user's choice), for
  -- the owner the registers name, with that owner's Party Master address.
  if c.mc_number is not null and not exists (select 1 from public.products where machine_key = k) then
    v_party := coalesce(nullif(btrim(coalesce(public.machine_current_party(p_item, p_serial), '')), ''),
                        nullif(btrim(coalesce(c.party, '')), ''), '');
    select nullif(btrim(x.address), '') as address, nullif(btrim(x.city), '') as city,
           nullif(btrim(x.state), '') as state, nullif(btrim(x.service_engineer), '') as engineer
      into pm from public.parties x where x.name_key = lower(v_party) limit 1;
    insert into public.products (item_name, serial_number, party_name, item_code,
                                 address, city, state, service_engineer)
    values (btrim(p_item), btrim(p_serial), v_party, coalesce(c.product_code, ''),
            coalesce(pm.address, ''), coalesce(pm.city, ''), coalesce(pm.state, ''), coalesce(pm.engineer, ''))
    on conflict (machine_key) do nothing;
  end if;

  select p.contract_number, p.warranty_number into cur from public.products p where p.machine_key = k;
  if not found then return; end if;

  -- WHAT THE SERIAL-ONLY SYNC LEFT BEHIND: a number this machine carries that a
  -- register line DOES hold, but for another model sharing the serial.
  if c.mc_number is null and nullif(btrim(coalesce(a.contract_number, '')), '') is null
     and btrim(coalesce(cur.contract_number, '')) <> '' then
    foreign_contract := exists (select 1 from public.contract_items x where x.mc_number = cur.contract_number);
  end if;
  if w.sa_number is null and nullif(btrim(coalesce(a.warranty_number, '')), '') is null
     and btrim(coalesce(cur.warranty_number, '')) <> '' then
    foreign_warranty := exists (select 1 from public.sale_items x where x.sa_number = cur.warranty_number);
  end if;

  update public.products p set
    warranty_number = case when foreign_warranty then ''
                           else coalesce(w.sa_number, nullif(a.warranty_number, ''), p.warranty_number) end,
    warranty_start  = case when foreign_warranty then null else coalesce(w.ws, a.warranty_start, p.warranty_start) end,
    warranty_end    = case when foreign_warranty then null else coalesce(w.we, a.warranty_end,   p.warranty_end) end,
    invoice_no      = coalesce(w.inv,  p.invoice_no),
    invoice_date    = coalesce(w.invd, p.invoice_date),
    warranty_years  = coalesce(w.wy,   p.warranty_years),
    warranty_months = coalesce(w.wm,   p.warranty_months),
    accessories_included = coalesce(w.acc, p.accessories_included),
    contract_number = case when foreign_contract then ''
                           else coalesce(c.mc_number, nullif(a.contract_number, ''), p.contract_number) end,
    contract_start  = case when foreign_contract then null else coalesce(c.cs, a.contract_start, p.contract_start) end,
    contract_end    = case when foreign_contract then null else coalesce(c.ce, a.contract_end,   p.contract_end) end,
    contract_type   = case when foreign_contract then ''
                           else coalesce(nullif(c.ct, ''), nullif(a.contract_type, ''), p.contract_type) end,
    contract_status_keyed = case when foreign_contract then ''
                                 else coalesce(nullif(btrim(coalesce(c.st, '')), ''), p.contract_status_keyed) end,
    -- THE CONTRACT'S PM VISITS OVERWRITE THE SALE'S (the user's choice), while
    -- the machine has a contract line saying how many.
    pm_visits       = case when c.mc_number is not null and c.pm is not null then c.pm
                           else coalesce(w.pm, p.pm_visits) end,
    transfer_ref    = coalesce(nullif(btrim(coalesce(t.ref, '')), ''), p.transfer_ref),
    transfer_date   = coalesce(t.d, p.transfer_date),
    -- machine_cover's rule (0036): a current contract is its type, a current
    -- warranty WGP, and a machine the registers know with neither is OGP. One
    -- no register mentions keeps the status it was imported with.
    item_status     = case
      when coalesce(c.ce, a.contract_end) >= current_date
        then coalesce(nullif(c.ct, ''), nullif(a.contract_type, ''), 'CMC')
      when coalesce(w.we, a.warranty_end) >= current_date then 'WGP'
      when w.sa_number is not null or c.mc_number is not null or a.warranty_number is not null
        or a.contract_number is not null or foreign_contract or foreign_warranty then 'OGP'
      else p.item_status end
  where p.machine_key = k;
end $$;
revoke execute on function public.sync_product_machine(text, text) from public, anon, authenticated;

-- ---- 3. every path goes through it ----------------------------------------
-- The serial-only entry point stays for anything that still calls it, and now
-- syncs each machine bearing that serial on its OWN registers.
create or replace function public.sync_product_cover(p_serial text)
returns void language plpgsql security definer set search_path = public as $$
declare r record;
begin
  for r in select p.item_name, p.serial_number from public.products p
            where lower(btrim(p.serial_number)) = lower(btrim(coalesce(p_serial, ''))) loop
    perform public.sync_product_machine(r.item_name, r.serial_number);
  end loop;
end $$;

create or replace function public.cover_item_sync()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op <> 'DELETE' then
    perform public.sync_product_machine(new.product_name, new.serial_number);
  end if;
  if tg_op = 'DELETE' or (old.product_name, old.serial_number) is distinct from (new.product_name, new.serial_number) then
    perform public.sync_product_machine(old.product_name, old.serial_number);
  end if;
  return null;
end $$;

create or replace function public.cover_header_sync()
returns trigger language plpgsql security definer set search_path = public as $$
declare r record;
begin
  if tg_table_name = 'sale_entries' then
    for r in select product_name, serial_number from public.sale_items where sa_number = new.sa_number loop
      perform public.sync_product_machine(r.product_name, r.serial_number);
    end loop;
  else
    for r in select product_name, serial_number from public.contract_items where mc_number = new.mc_number loop
      perform public.sync_product_machine(r.product_name, r.serial_number);
    end loop;
  end if;
  return null;
end $$;

create or replace function public.product_additional_entry_apply()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.sync_product_machine(new.item_name, new.serial_number);
  return null;
end $$;

-- The sale's own write (0329) ends by re-syncing the machine, so a contract's
-- PM visits are not overwritten by the sale that runs after it.
do $$
declare src text;
begin
  src := pg_get_functiondef('public.upsert_product_from_sale(bigint)'::regprocedure);
  if position('sync_product_machine' in src) = 0 then
    src := replace(src,
      E'  -- `inst_call` IS NO LONGER WRITTEN HERE AT ALL',
      E'  -- THE REST OF THE MACHINE -- invoice, years/months, accessories, and the\n'
      || E'  -- contract that may overwrite PM visits -- from every register (0330).\n'
      || E'  perform public.sync_product_machine(i.product_name, i.serial_number);\n'
      || E'  -- `inst_call` IS NO LONGER WRITTEN HERE AT ALL');
    if position('sync_product_machine' in src) = 0 then
      raise exception '0330: upsert_product_from_sale() is not the shape this file expects -- read it from the database and edit by hand';
    end if;
    execute src;
  end if;
end $$;

-- A transfer ends the same way, which carries its Ref and Date.
do $$
declare src text;
begin
  src := pg_get_functiondef('public.transfer_to_product()'::regprocedure);
  if position('sync_product_machine' in src) = 0 then
    src := replace(src,
      E'  return null;\nend',
      E'  -- THE TRANSFER''S REF AND DATE (0330), and the rest of the machine.\n'
      || E'  perform public.sync_product_machine(m.item_name, m.serial_number);\n'
      || E'  return null;\nend');
    if position('sync_product_machine' in src) = 0 then
      raise exception '0330: transfer_to_product() is not the shape this file expects -- read it from the database and edit by hand';
    end if;
    execute src;
  end if;
end $$;

-- THE OLDEST TRANSFER RULE MOVED EVERY MACHINE SHARING THE SERIAL (0072,
-- D-060): transferring ORION 219 also handed the ANAVENT 219 to the new owner.
-- The user's rule is product + serial, so it now moves the ONE machine, to
-- whoever the latest dated evidence names (machine_current_party, 0238).
create or replace function public.ownership_transfer_move()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.products p
     set party_name = public.machine_current_party(p.item_name, p.serial_number)
   where p.machine_key = lower(btrim(coalesce(new.item_name, ''))) || '|' || lower(btrim(coalesce(new.serial_number, '')))
     and coalesce(public.machine_current_party(p.item_name, p.serial_number), '') <> ''
     and p.party_name is distinct from public.machine_current_party(p.item_name, p.serial_number);
  return null;
end $$;

-- The after-import refresh: every machine held, and every contract line for a
-- machine not yet held, each on its own registers.
create or replace function public.refresh_product_cover()
returns integer language plpgsql security definer set search_path = public
set statement_timeout to '600s' as $$
declare n integer := 0; r record;
begin
  -- 0247: THE COVER ADMIN ACTION IS FOR WHOEVER MAY EDIT COVER. This runs with
  -- the owner's rights over every sale, contract and machine, so it checks the
  -- caller itself. A call with nobody signed in (the SQL editor, a scheduled
  -- job) passes;
  -- the not-signed-in role cannot call it at all (0248 withdraws it).
  if auth.uid() is not null and not (public.is_admin() or public.has_perm('cover.edit.entries') or public.has_perm('contract.edit.entries')) then
    raise exception 'Only someone who may edit cover (cover.edit) can re-fold cover after an import.';
  end if;
  for r in
    select item_name as a, serial_number as b from public.products
    union
    select product_name, serial_number from public.contract_items
     where btrim(coalesce(product_name, '')) <> '' and btrim(coalesce(serial_number, '')) <> ''
  loop
    perform public.sync_product_machine(r.a, r.b);
    n := n + 1;
  end loop;
  return n;
end $$;

-- ---- 4. once: every machine re-synced, old values kept ---------------------
create table if not exists public.one_time_fixes_done (
  name       text primary key,
  applied_at timestamptz not null default now(),
  detail     text
);
alter table public.one_time_fixes_done enable row level security;
revoke all on public.one_time_fixes_done from anon, authenticated;

create table if not exists public.products_resync_backup (
  id          bigserial primary key,
  machine_key text not null,
  before      jsonb not null,
  saved_at    timestamptz not null default now()
);
alter table public.products_resync_backup enable row level security;
revoke all on public.products_resync_backup from anon, authenticated;
do $$
begin
  if to_regprocedure('public.sys_columns_attach(regclass)') is not null then
    perform public.sys_columns_attach('public.products_resync_backup'::regclass);
  end if;
end $$;

do $$
declare n_before integer; n_changed integer; n_added integer; r record;
begin
  if exists (select 1 from public.one_time_fixes_done where name = '0330_product_database_resync') then
    raise notice '0330: the Product Database was re-synced from the registers before -- not touched again';
    return;
  end if;
  select count(*) into n_before from public.products;

  create temporary table b0330 on commit drop as
  select p.machine_key, jsonb_build_object(
           'warranty_number', p.warranty_number, 'warranty_start', p.warranty_start, 'warranty_end', p.warranty_end,
           'contract_number', p.contract_number, 'contract_start', p.contract_start, 'contract_end', p.contract_end,
           'contract_type', p.contract_type, 'contract_status_keyed', p.contract_status_keyed,
           'pm_visits', p.pm_visits, 'item_status', p.item_status) as before
    from public.products p;

  for r in
    select item_name as a, serial_number as b from public.products
    union
    select product_name, serial_number from public.contract_items
     where btrim(coalesce(product_name, '')) <> '' and btrim(coalesce(serial_number, '')) <> ''
  loop
    perform public.sync_product_machine(r.a, r.b);
  end loop;

  insert into public.products_resync_backup (machine_key, before)
  select b.machine_key, b.before
    from b0330 b join public.products p on p.machine_key = b.machine_key
   where b.before is distinct from jsonb_build_object(
           'warranty_number', p.warranty_number, 'warranty_start', p.warranty_start, 'warranty_end', p.warranty_end,
           'contract_number', p.contract_number, 'contract_start', p.contract_start, 'contract_end', p.contract_end,
           'contract_type', p.contract_type, 'contract_status_keyed', p.contract_status_keyed,
           'pm_visits', p.pm_visits, 'item_status', p.item_status);
  get diagnostics n_changed = row_count;
  select count(*) - n_before into n_added from public.products;

  insert into public.one_time_fixes_done (name, detail)
  values ('0330_product_database_resync',
          format('%s machine(s) changed, %s added from contracts', n_changed, n_added));
  raise notice '0330: % machine(s) changed (old values in products_resync_backup), % added from contract lines', n_changed, n_added;
end $$;

-- ------------------------------------------------------------------------
-- 0331_install_solved_date_starts_warranty.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0331 — THE WARRANTY STARTS WHERE THE INSTALLING ENGINEER SAYS (WGP)
--
-- The user, 2026-10-03: "when I install the product in the customer's place
-- and update the report there is a selection that I make as an engineer --
-- warranty start date should be from the documented date as per PO or in the
-- warranty sale entry or as per the installation solved date ... if the
-- engineer chooses the solved date as the warranty start date then the
-- warranty start date gets updated as the installation call solved date."
-- Product means product + serial. Asked: the end is RECOMPUTED from the
-- warranty period; the report's date box goes back to the selection; the 328
-- installations already answered are applied once, backed up.
--
-- THE SELECTION IS THE CUSTOMER FEEDBACK'S "Warranty Start Date?" -- measured
-- on the live project (_warranty_start_answers.sql, 2026-10-03): of 8,315
-- feedback records, 328 installations answer "Installation Call Solved Date",
-- 78 "Invoice Date", and 28 hold a date typed into the box RITHI had put in
-- its place (left as they are, the user's choice).
--
--   "Installation Call Solved Date" -> warranty start = the day the machine's
--       latest installation call was SOLVED (open_state Solved, its latest
--       visit), read in India time; end = cover_period_end(start, months),
--       months the sale's period (months, else years x 12) -- the same rule
--       and arithmetic the registers and Product Database 2.0 use.
--   "Invoice Date" (or anything else) -> the documented start on the PO /
--       Warranty Sale Entry stays, as 0330 writes it.
--
-- Whenever an installation's feedback is saved, or its call's solved state
-- changes, that machine is re-synced (sync_product_machine, now carrying this
-- rule). One-time: every machine whose installation answered "Installation
-- Call Solved Date" is re-synced, old start/end kept in
-- products_install_start_backup.
-- ===========================================================================

-- ---- the answer, for one machine ------------------------------------------
create or replace function public.machine_install_warranty_start(p_item text, p_serial text)
returns date language sql stable security definer set search_path = public as $$
  select case
           when lower(btrim(coalesce(f.answers ->> 'Warranty Start Date?', ''))) = 'installation call solved date'
            and c.open_state = 'Solved' and c.last_visit_at is not null
           then (c.last_visit_at at time zone 'Asia/Kolkata')::date
         end
    from public.installation_calls c
    left join public.feedback f on f.ucn = c.ucn
   where lower(btrim(coalesce(c.product_name, ''))) = lower(btrim(coalesce(p_item, '')))
     and lower(btrim(coalesce(c.serial, ''))) = lower(btrim(coalesce(p_serial, '')))
   order by c.last_visit_at desc nulls last, c.ucn desc
   limit 1;
$$;
revoke execute on function public.machine_install_warranty_start(text, text) from public, anon, authenticated;

-- ---- the one machine sync, now with the installation's answer --------------
create or replace function public.sync_product_machine(p_item text, p_serial text)
returns void language plpgsql security definer set search_path = public as $$
declare
  n text := lower(btrim(coalesce(p_item, '')));
  s text := lower(btrim(coalesce(p_serial, '')));
  k text;
  w record; c record; a record; t record; cur record; pm record;
  v_party text;
  foreign_contract boolean := false;
  foreign_warranty boolean := false;
  v_inst date; v_months numeric; v_inst_end date;
begin
  if n = '' or s = '' then return; end if;
  k := n || '|' || s;

  select i.sa_number,
         coalesce(i.warranty_start, h.warranty_start) as ws,
         coalesce(i.warranty_end,   h.warranty_end)   as we,
         coalesce(i.pm_visits,      h.pm_visits)      as pm,
         coalesce(nullif(btrim(coalesce(i.invoice_no, '')), ''), nullif(btrim(coalesce(h.invoice_no, '')), '')) as inv,
         coalesce(i.invoice_date,    h.invoice_date)    as invd,
         coalesce(i.warranty_years,  h.warranty_years)  as wy,
         coalesce(i.warranty_months, h.warranty_months) as wm,
         i.accessories_included as acc
    into w
    from public.sale_items i left join public.sale_entries h on h.sa_number = i.sa_number
   where lower(btrim(coalesce(i.product_name, ''))) = n
     and lower(btrim(coalesce(i.serial_number, ''))) = s
   order by coalesce(i.warranty_end, h.warranty_end) desc nulls last, i.id desc limit 1;

  -- THE ENGINEER'S CHOICE AT INSTALLATION (0331, the user, 2026-10-03): where
  -- the installation's customer feedback answers "Warranty Start Date?" with
  -- "Installation Call Solved Date", the warranty starts on the day that call
  -- was solved and ends a warranty period later; "Invoice Date" keeps the
  -- documented start on the sale.
  v_inst := public.machine_install_warranty_start(p_item, p_serial);
  if v_inst is not null then
    select coalesce(i.warranty_months, h.warranty_months, i.warranty_years * 12, h.warranty_years * 12)
      into v_months
      from public.sale_items i left join public.sale_entries h on h.sa_number = i.sa_number
     where lower(btrim(coalesce(i.product_name, ''))) = n
       and lower(btrim(coalesce(i.serial_number, ''))) = s
     order by coalesce(i.warranty_end, h.warranty_end) desc nulls last, i.id desc limit 1;
    -- cover_period_end() (0218) reproduces the application's own arithmetic;
    -- asked by name because its module runs after this one on a fresh build.
    if v_months is not null and v_months > 0 and to_regprocedure('public.cover_period_end(date,numeric)') is not null then
      execute 'select public.cover_period_end($1, $2)' into v_inst_end using v_inst, v_months;
    end if;
  end if;

  select i.mc_number, i.product_code,
         coalesce(nullif(btrim(coalesce(i.contract_type, '')), ''), h.contract_type) as ct,
         coalesce(i.contract_start, h.contract_start) as cs,
         coalesce(i.contract_end,   h.contract_end)   as ce,
         coalesce(i.pm_visits_total, h.pm_visits_total) as pm,
         coalesce(nullif(btrim(coalesce(i.status, '')), ''), h.status) as st,
         coalesce(nullif(btrim(coalesce(i.party_name, '')), ''), h.party_name) as party
    into c
    from public.contract_items i left join public.contract_entries h on h.mc_number = i.mc_number
   where lower(btrim(coalesce(i.product_name, ''))) = n
     and lower(btrim(coalesce(i.serial_number, ''))) = s
   order by coalesce(i.contract_end, h.contract_end) desc nulls last, i.id desc limit 1;

  -- The recovered detail, used only where the registers are silent.
  select e.warranty_number, e.warranty_start, e.warranty_end,
         e.contract_number, e.contract_type, e.contract_start, e.contract_end
    into a
    from public.product_additional_entries e where e.machine_key = k limit 1;

  select x.reference_no as ref, x.transfer_date as d
    into t
    from public.ownership_transfers x
   where lower(btrim(coalesce(x.item_name, ''))) = n
     and lower(btrim(coalesce(x.serial_number, ''))) = s
   order by coalesce(x.transferred_at, x.created_at, x.transfer_date::timestamptz) desc nulls last, x.id desc
   limit 1;

  -- A CONTRACT FOR A MACHINE NOT YET HELD is inserted (the user's choice), for
  -- the owner the registers name, with that owner's Party Master address.
  if c.mc_number is not null and not exists (select 1 from public.products where machine_key = k) then
    v_party := coalesce(nullif(btrim(coalesce(public.machine_current_party(p_item, p_serial), '')), ''),
                        nullif(btrim(coalesce(c.party, '')), ''), '');
    select nullif(btrim(x.address), '') as address, nullif(btrim(x.city), '') as city,
           nullif(btrim(x.state), '') as state, nullif(btrim(x.service_engineer), '') as engineer
      into pm from public.parties x where x.name_key = lower(v_party) limit 1;
    insert into public.products (item_name, serial_number, party_name, item_code,
                                 address, city, state, service_engineer)
    values (btrim(p_item), btrim(p_serial), v_party, coalesce(c.product_code, ''),
            coalesce(pm.address, ''), coalesce(pm.city, ''), coalesce(pm.state, ''), coalesce(pm.engineer, ''))
    on conflict (machine_key) do nothing;
  end if;

  select p.contract_number, p.warranty_number into cur from public.products p where p.machine_key = k;
  if not found then return; end if;

  -- WHAT THE SERIAL-ONLY SYNC LEFT BEHIND: a number this machine carries that a
  -- register line DOES hold, but for another model sharing the serial.
  if c.mc_number is null and nullif(btrim(coalesce(a.contract_number, '')), '') is null
     and btrim(coalesce(cur.contract_number, '')) <> '' then
    foreign_contract := exists (select 1 from public.contract_items x where x.mc_number = cur.contract_number);
  end if;
  if w.sa_number is null and nullif(btrim(coalesce(a.warranty_number, '')), '') is null
     and btrim(coalesce(cur.warranty_number, '')) <> '' then
    foreign_warranty := exists (select 1 from public.sale_items x where x.sa_number = cur.warranty_number);
  end if;

  update public.products p set
    warranty_number = case when foreign_warranty then ''
                           else coalesce(w.sa_number, nullif(a.warranty_number, ''), p.warranty_number) end,
    warranty_start  = case when v_inst is not null then v_inst
                           when foreign_warranty then null else coalesce(w.ws, a.warranty_start, p.warranty_start) end,
    warranty_end    = case when v_inst is not null and v_inst_end is not null then v_inst_end
                           when foreign_warranty then null else coalesce(w.we, a.warranty_end,   p.warranty_end) end,
    invoice_no      = coalesce(w.inv,  p.invoice_no),
    invoice_date    = coalesce(w.invd, p.invoice_date),
    warranty_years  = coalesce(w.wy,   p.warranty_years),
    warranty_months = coalesce(w.wm,   p.warranty_months),
    accessories_included = coalesce(w.acc, p.accessories_included),
    contract_number = case when foreign_contract then ''
                           else coalesce(c.mc_number, nullif(a.contract_number, ''), p.contract_number) end,
    contract_start  = case when foreign_contract then null else coalesce(c.cs, a.contract_start, p.contract_start) end,
    contract_end    = case when foreign_contract then null else coalesce(c.ce, a.contract_end,   p.contract_end) end,
    contract_type   = case when foreign_contract then ''
                           else coalesce(nullif(c.ct, ''), nullif(a.contract_type, ''), p.contract_type) end,
    contract_status_keyed = case when foreign_contract then ''
                                 else coalesce(nullif(btrim(coalesce(c.st, '')), ''), p.contract_status_keyed) end,
    -- THE CONTRACT'S PM VISITS OVERWRITE THE SALE'S (the user's choice), while
    -- the machine has a contract line saying how many.
    pm_visits       = case when c.mc_number is not null and c.pm is not null then c.pm
                           else coalesce(w.pm, p.pm_visits) end,
    transfer_ref    = coalesce(nullif(btrim(coalesce(t.ref, '')), ''), p.transfer_ref),
    transfer_date   = coalesce(t.d, p.transfer_date),
    -- machine_cover's rule (0036): a current contract is its type, a current
    -- warranty WGP, and a machine the registers know with neither is OGP. One
    -- no register mentions keeps the status it was imported with.
    item_status     = case
      when coalesce(c.ce, a.contract_end) >= current_date
        then coalesce(nullif(c.ct, ''), nullif(a.contract_type, ''), 'CMC')
      when coalesce(case when v_inst is not null then v_inst_end end, w.we, a.warranty_end) >= current_date then 'WGP'
      when w.sa_number is not null or c.mc_number is not null or a.warranty_number is not null
        or a.contract_number is not null or foreign_contract or foreign_warranty then 'OGP'
      else p.item_status end
  where p.machine_key = k;
end $$;
revoke execute on function public.sync_product_machine(text, text) from public, anon, authenticated;

-- ---- when the answer or the solved state changes --------------------------
create or replace function public.install_start_to_product()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_item text; v_serial text;
begin
  if tg_table_name = 'feedback' then
    if upper(coalesce(new.call_type, '')) not like 'INSTALL%' then return null; end if;
    select c.product_name, c.serial into v_item, v_serial
      from public.installation_calls c where c.ucn = new.ucn limit 1;
  else
    if tg_op = 'UPDATE' and (old.open_state, old.last_visit_at) is not distinct from (new.open_state, new.last_visit_at) then
      return null;
    end if;
    v_item := new.product_name; v_serial := new.serial;
  end if;
  if coalesce(btrim(v_item), '') <> '' and coalesce(btrim(v_serial), '') <> '' then
    perform public.sync_product_machine(v_item, v_serial);
  end if;
  return null;
end $$;
revoke execute on function public.install_start_to_product() from public, anon, authenticated;

drop trigger if exists zz_install_start_to_product on public.feedback;
create trigger zz_install_start_to_product after insert or update on public.feedback
  for each row execute function public.install_start_to_product();
drop trigger if exists zz_install_start_to_product on public.installation_calls;
create trigger zz_install_start_to_product after update on public.installation_calls
  for each row execute function public.install_start_to_product();

-- ---- once: the installations already answered ------------------------------
create table if not exists public.one_time_fixes_done (
  name       text primary key,
  applied_at timestamptz not null default now(),
  detail     text
);
alter table public.one_time_fixes_done enable row level security;
revoke all on public.one_time_fixes_done from anon, authenticated;

create table if not exists public.products_install_start_backup (
  id          bigserial primary key,
  machine_key text not null,
  before      jsonb not null,
  saved_at    timestamptz not null default now()
);
alter table public.products_install_start_backup enable row level security;
revoke all on public.products_install_start_backup from anon, authenticated;
do $$
begin
  if to_regprocedure('public.sys_columns_attach(regclass)') is not null then
    perform public.sys_columns_attach('public.products_install_start_backup'::regclass);
  end if;
end $$;

do $$
declare n integer; r record;
begin
  if exists (select 1 from public.one_time_fixes_done where name = '0331_install_warranty_start') then
    raise notice '0331: installation warranty starts were applied before -- not touched again';
    return;
  end if;

  create temporary table t0331 on commit drop as
  select distinct p.machine_key, p.item_name, p.serial_number,
         jsonb_build_object('warranty_start', p.warranty_start, 'warranty_end', p.warranty_end,
                            'item_status', p.item_status) as before
    from public.feedback f
    join public.installation_calls c on c.ucn = f.ucn
    join public.products p
      on p.machine_key = lower(btrim(coalesce(c.product_name, ''))) || '|' || lower(btrim(coalesce(c.serial, '')))
   where lower(btrim(coalesce(f.answers ->> 'Warranty Start Date?', ''))) = 'installation call solved date';

  for r in select item_name, serial_number from t0331 loop
    perform public.sync_product_machine(r.item_name, r.serial_number);
  end loop;

  insert into public.products_install_start_backup (machine_key, before)
  select t.machine_key, t.before
    from t0331 t join public.products p on p.machine_key = t.machine_key
   where t.before is distinct from jsonb_build_object('warranty_start', p.warranty_start,
                                                      'warranty_end', p.warranty_end, 'item_status', p.item_status);
  get diagnostics n = row_count;

  insert into public.one_time_fixes_done (name, detail)
  values ('0331_install_warranty_start',
          format('%s of %s machine(s) given the installation solved date as warranty start', n, (select count(*) from t0331)));
  raise notice '0331: % of % machine(s) whose installation answered "Installation Call Solved Date" changed (old values in products_install_start_backup)',
    n, (select count(*) from t0331);
end $$;

-- ------------------------------------------------------------------------
-- 0332_installation_warranty_starts.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0332 — THE INSTALLATION'S WARRANTY DECISION, IN A TABLE OF ITS OWN
--
-- The user, 2026-10-03: "Store these in a separate table, I have details for
-- calls from 2018, I will upload it in one go. So build a bulk upload for old
-- inst calls." -- and, asked what one row holds: the call and machine, the
-- engineer's choice, the resulting warranty, the engineer and remarks.
--
-- public.installation_warranty_starts is ONE ROW PER INSTALLATION CALL (keyed
-- on the UCN, so a re-loaded file corrects rather than duplicates):
--   call & machine   ucn, call_number, product_name, serial, party_name, reg_date
--   the choice       warranty_choice ("Installation Call Solved Date" /
--                    "Invoice Date", as the feedback has always said),
--                    call_solved_at and solved_date
--   the result       warranty_start, warranty_end, period_months -- WRITTEN BY
--                    THE SYSTEM from the Product Database after it applies the
--                    choice, never typed
--   the engineer     engineer, visit_at, remarks
--   where it came    source: RITHI (a report filed here), Feedback (the
--                    customer feedback already on file), Upload (Bulk Uploads)
--
-- IT IS NOW THE SOURCE OF THE RULE (0331): machine_install_warranty_start()
-- reads the machine's latest row here, so an installation from 2018 that was
-- never a RITHI call decides its machine's warranty exactly as a new one does.
-- A RITHI installation fills its row when its feedback is saved or its call's
-- solved state changes; any row saved here re-syncs its product + serial.
--
-- Filled once from every installation feedback already on file.
-- ===========================================================================

create table if not exists public.installation_warranty_starts (
  id              bigserial primary key,
  ucn             text not null,
  ucn_key         text generated always as (lower(btrim(ucn))) stored,
  call_number     text not null default '',
  product_name    text not null default '',
  serial          text not null default '',
  machine_key     text generated always as
                    (lower(btrim(coalesce(product_name, ''))) || '|' || lower(btrim(coalesce(serial, '')))) stored,
  party_name      text not null default '',
  reg_date        date,
  warranty_choice text not null default '',
  call_solved_at  timestamptz,
  solved_date     date,
  warranty_start  date,
  warranty_end    date,
  period_months   numeric,
  engineer        text not null default '',
  visit_at        timestamptz,
  remarks         text not null default '',
  source          text not null default 'RITHI',
  extra           jsonb not null default '{}'::jsonb,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create unique index if not exists installation_warranty_starts_ucn_key on public.installation_warranty_starts (ucn_key);
create index if not exists installation_warranty_starts_machine on public.installation_warranty_starts (machine_key);

alter table public.installation_warranty_starts enable row level security;
-- READ like the Product Database it decides (signed in); WRITE by Bulk Uploads'
-- own key. A RITHI report fills its row through the trigger below, as the owner.
drop policy if exists iws_read on public.installation_warranty_starts;
create policy iws_read on public.installation_warranty_starts for select
  using (auth.role() = 'authenticated');
drop policy if exists iws_insert on public.installation_warranty_starts;
create policy iws_insert on public.installation_warranty_starts for insert
  with check ((select public.has_perm('bulk.upload')));
drop policy if exists iws_update on public.installation_warranty_starts;
create policy iws_update on public.installation_warranty_starts for update
  using ((select public.has_perm('bulk.upload'))) with check ((select public.has_perm('bulk.upload')));
grant select, insert, update on public.installation_warranty_starts to authenticated;
grant usage on sequence public.installation_warranty_starts_id_seq to authenticated;
do $$
begin
  if to_regprocedure('public.sys_columns_attach(regclass)') is not null then
    perform public.sys_columns_attach('public.installation_warranty_starts'::regclass);
  end if;
end $$;

-- ---- the stamps: a typed result is discarded, the day is derived ----------
create or replace function public.installation_warranty_starts_biu()
returns trigger language plpgsql set search_path = public as $$
begin
  new.updated_at := now();
  new.warranty_choice := btrim(coalesce(new.warranty_choice, ''));
  -- The solved DAY is India time, from the moment, where the file gave one.
  if new.solved_date is null and new.call_solved_at is not null then
    new.solved_date := (new.call_solved_at at time zone 'Asia/Kolkata')::date;
  end if;
  -- THE RESULT IS THE SYSTEM'S. A caller through the API cannot write it. The
  -- test is current_user, not the `role` setting: the write-back below runs in
  -- a SECURITY DEFINER function, where current_user is the owner but the
  -- setting still says `authenticated` for an upload -- testing the setting
  -- would discard the system's own result too.
  if current_user in ('authenticated', 'anon') then
    if tg_op = 'INSERT' then
      new.warranty_start := null; new.warranty_end := null; new.period_months := null;
    else
      new.warranty_start := old.warranty_start; new.warranty_end := old.warranty_end;
      new.period_months := old.period_months;
    end if;
  end if;
  return new;
end $$;
drop trigger if exists installation_warranty_starts_biu on public.installation_warranty_starts;
create trigger installation_warranty_starts_biu before insert or update on public.installation_warranty_starts
  for each row execute function public.installation_warranty_starts_biu();

-- ---- the rule now reads the table ------------------------------------------
create or replace function public.machine_install_warranty_start(p_item text, p_serial text)
returns date language sql stable security definer set search_path = public as $$
  select case when lower(w.warranty_choice) = 'installation call solved date' then w.solved_date end
    from public.installation_warranty_starts w
   where w.machine_key = lower(btrim(coalesce(p_item, ''))) || '|' || lower(btrim(coalesce(p_serial, '')))
   order by w.solved_date desc nulls last, w.id desc
   limit 1;
$$;
revoke execute on function public.machine_install_warranty_start(text, text) from public, anon, authenticated;

-- ---- a saved row re-syncs its machine, and records what it decided --------
create or replace function public.installation_warranty_to_product()
returns trigger language plpgsql security definer set search_path = public as $$
declare p record;
begin
  if tg_op = 'UPDATE' and (old.product_name, old.serial) is distinct from (new.product_name, new.serial) then
    perform public.sync_product_machine(old.product_name, old.serial);
  end if;
  perform public.sync_product_machine(new.product_name, new.serial);
  select x.warranty_start, x.warranty_end into p from public.products x where x.machine_key = new.machine_key;
  update public.installation_warranty_starts w
     set warranty_start = p.warranty_start,
         warranty_end   = p.warranty_end,
         period_months  = (select coalesce(i.warranty_months, h.warranty_months, i.warranty_years * 12, h.warranty_years * 12)
                             from public.sale_items i left join public.sale_entries h on h.sa_number = i.sa_number
                            where lower(btrim(coalesce(i.product_name, ''))) || '|' || lower(btrim(coalesce(i.serial_number, ''))) = new.machine_key
                            order by coalesce(i.warranty_end, h.warranty_end) desc nulls last, i.id desc limit 1)
   where w.id = new.id
     and (w.warranty_start, w.warranty_end) is distinct from (p.warranty_start, p.warranty_end)
         or (w.id = new.id and w.period_months is null);
  return null;
end $$;
revoke execute on function public.installation_warranty_to_product() from public, anon, authenticated;
drop trigger if exists zz_installation_warranty_to_product on public.installation_warranty_starts;
create trigger zz_installation_warranty_to_product
  after insert or update of product_name, serial, warranty_choice, solved_date, call_solved_at
  on public.installation_warranty_starts
  for each row execute function public.installation_warranty_to_product();

-- ---- a RITHI installation fills its own row --------------------------------
create or replace function public.install_start_to_product()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_ucn text; c record; f record;
begin
  if tg_table_name = 'feedback' then
    if upper(coalesce(new.call_type, '')) not like 'INSTALL%' then return null; end if;
    v_ucn := new.ucn;
  else
    if tg_op = 'UPDATE' and (old.open_state, old.last_visit_at) is not distinct from (new.open_state, new.last_visit_at) then
      return null;
    end if;
    v_ucn := new.ucn;
  end if;

  select x.ucn, x.call_number, x.product_name, x.serial, x.party_name, x.reg_date, x.allocated_to,
         x.open_state, x.last_visit_at
    into c from public.installation_calls x where x.ucn = v_ucn limit 1;
  if c.ucn is null then return null; end if;
  select y.answers, y.engineer, y.visit_at into f from public.feedback y where y.ucn = v_ucn
   order by y.id desc limit 1;
  -- Nothing to record until the engineer has answered.
  if btrim(coalesce(f.answers ->> 'Warranty Start Date?', '')) = '' then return null; end if;

  insert into public.installation_warranty_starts as w
    (ucn, call_number, product_name, serial, party_name, reg_date, warranty_choice,
     call_solved_at, engineer, visit_at, remarks, source)
  values (c.ucn, coalesce(c.call_number, ''), coalesce(c.product_name, ''), coalesce(c.serial, ''),
          coalesce(c.party_name, ''), c.reg_date, btrim(f.answers ->> 'Warranty Start Date?'),
          case when c.open_state = 'Solved' then c.last_visit_at end,
          coalesce(nullif(btrim(coalesce(f.engineer, '')), ''), coalesce(c.allocated_to, '')), f.visit_at,
          coalesce(f.answers ->> 'INSTALLATION/PM/FIELD-Remarks if any', ''), 'RITHI')
  on conflict (ucn_key) do update set
    call_number = excluded.call_number, product_name = excluded.product_name, serial = excluded.serial,
    party_name = excluded.party_name, reg_date = excluded.reg_date,
    warranty_choice = excluded.warranty_choice, call_solved_at = excluded.call_solved_at,
    solved_date = (excluded.call_solved_at at time zone 'Asia/Kolkata')::date,
    engineer = excluded.engineer, visit_at = excluded.visit_at, remarks = excluded.remarks;
  return null;
end $$;
revoke execute on function public.install_start_to_product() from public, anon, authenticated;

-- ---- what the Visit Entry shows: now, and after this report ---------------
-- Dates only, for one product + serial; the caller must be signed in.
create or replace function public.machine_warranty_preview(p_item text, p_serial text, p_solved_on date)
returns table (now_start date, now_end date, period_months numeric, solved_start date, solved_end date)
language plpgsql stable security definer set search_path = public as $$
declare k text := lower(btrim(coalesce(p_item, ''))) || '|' || lower(btrim(coalesce(p_serial, '')));
        m numeric; e date;
begin
  if auth.uid() is null then return; end if;
  select coalesce(i.warranty_months, h.warranty_months, i.warranty_years * 12, h.warranty_years * 12) into m
    from public.sale_items i left join public.sale_entries h on h.sa_number = i.sa_number
   where lower(btrim(coalesce(i.product_name, ''))) || '|' || lower(btrim(coalesce(i.serial_number, ''))) = k
   order by coalesce(i.warranty_end, h.warranty_end) desc nulls last, i.id desc limit 1;
  if p_solved_on is not null and m is not null and m > 0
     and to_regprocedure('public.cover_period_end(date,numeric)') is not null then
    execute 'select public.cover_period_end($1, $2)' into e using p_solved_on, m;
  end if;
  return query
    select p.warranty_start, p.warranty_end, m, p_solved_on, e
      from (select 1) one left join public.products p on p.machine_key = k;
end $$;
revoke execute on function public.machine_warranty_preview(text, text, date) from public, anon;
grant execute on function public.machine_warranty_preview(text, text, date) to authenticated;

-- ---- once: every installation feedback already on file ---------------------
create table if not exists public.one_time_fixes_done (
  name       text primary key,
  applied_at timestamptz not null default now(),
  detail     text
);
alter table public.one_time_fixes_done enable row level security;
revoke all on public.one_time_fixes_done from anon, authenticated;

do $$
declare n integer;
begin
  if exists (select 1 from public.one_time_fixes_done where name = '0332_installation_warranty_filled') then
    raise notice '0332: the installation warranty table was filled before -- not touched again';
    return;
  end if;
  insert into public.installation_warranty_starts
    (ucn, call_number, product_name, serial, party_name, reg_date, warranty_choice,
     call_solved_at, engineer, visit_at, remarks, source)
  select distinct on (lower(btrim(c.ucn)))
         c.ucn, coalesce(c.call_number, ''), coalesce(c.product_name, ''), coalesce(c.serial, ''),
         coalesce(c.party_name, ''), c.reg_date, btrim(f.answers ->> 'Warranty Start Date?'),
         case when c.open_state = 'Solved' then c.last_visit_at end,
         coalesce(nullif(btrim(coalesce(f.engineer, '')), ''), coalesce(c.allocated_to, '')), f.visit_at,
         coalesce(f.answers ->> 'INSTALLATION/PM/FIELD-Remarks if any', ''),
         -- imported_from is added by a module that runs after this one on a fresh
         -- build, so it is read off the row rather than named.
         case when btrim(coalesce(to_jsonb(f) ->> 'imported_from', '')) <> '' then 'Feedback' else 'RITHI' end
    from public.feedback f
    join public.installation_calls c on c.ucn = f.ucn
   where btrim(coalesce(f.answers ->> 'Warranty Start Date?', '')) <> ''
   order by lower(btrim(c.ucn)), f.id desc
  on conflict (ucn_key) do nothing;
  get diagnostics n = row_count;
  insert into public.one_time_fixes_done (name, detail)
  values ('0332_installation_warranty_filled', format('%s installation call(s) recorded from their feedback', n));
  raise notice '0332: % installation call(s) recorded from their feedback', n;
end $$;

-- ------------------------------------------------------------------------
-- 0351_dealer_guard_stands_aside_on_reload.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0351 — RE-LOADING THE INSTALLATION CALLS REGISTER IS NOT REFUSED FOR A CALL
--        ALREADY RAISED ON A DEALER  (second re-review, 2026-10-03: D-148)
--
-- installation_call_not_for_dealer (0328) is BEFORE INSERT OR UPDATE, and the
-- Installation Calls upload upserts on ucn. Postgres fires the BEFORE INSERT
-- trigger BEFORE it finds the conflict, so a call that already exists was
-- refused as if it were new. 0328 says calls already raised are left as they
-- are -- true for a plain UPDATE (measured: allowed), not for a re-load
-- (measured, signed in: refused with the dealer message), and one such row
-- stopped the whole upload.
--
-- THE RULE IS UNCHANGED for a new call and for a change of party: on INSERT
-- the guard now stands aside only when a call with that UCN ALREADY EXISTS
-- under the SAME party (case and outer spaces ignored) -- which is exactly
-- the row the upsert will turn into an UPDATE that leaves the party alone, the
-- case the UPDATE branch already lets through. A re-load that changes the
-- party to a dealer is still refused.
--
-- 0328's function VERBATIM with that one test added. Same module
-- (sales_contracts), after 0328.
-- ===========================================================================

create or replace function public.installation_call_not_for_dealer()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return new; end if;          -- a migration, a repair
  if tg_op = 'UPDATE' and new.party_name is not distinct from old.party_name then return new; end if;
  -- An upsert of a call that is already there, party unchanged (D-148).
  if tg_op = 'INSERT' and btrim(coalesce(new.ucn, '')) <> ''
     and exists (select 1 from public.installation_calls ic
                  where ic.ucn = new.ucn
                    and lower(btrim(coalesce(ic.party_name, ''))) = lower(btrim(coalesce(new.party_name, '')))) then
    return new;
  end if;
  if public.party_is_dealer(new.party_name) then
    raise exception '% is a dealer: an installation call is not raised for a dealer -- it is raised from the Ownership Transfer when the dealer sells the machine (OT-PRODUCT-SERIAL)', btrim(new.party_name)
      using errcode = '23514';
  end if;
  return new;
end $$;
revoke execute on function public.installation_call_not_for_dealer() from public, anon, authenticated;

-- ------------------------------------------------------------------------
-- 0361_sold_through_cleared_only_if_a_transfer_set_it.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0361 — A MACHINE'S SOLD THROUGH IS CLEARED ONLY WHERE A TRANSFER SET IT, AND
--        A CORRECTED TRANSFER'S OLD MACHINE IS RE-READ TOO
--        (second re-review D-149; the user's decision, 2026-10-04)
--
-- On a machine with NO sale entry, transfer_to_product writes
--   sold_through = coalesce(machine_sold_through(...), p.sold_through)
-- reading "no dealer transfer left" as "keep what is there". Measured: a
-- dealer -> clinic transfer set Sold Through to the dealer; correcting the
-- From party left the machine on the dealer. And on an UPDATE only NEW's
-- machine was re-derived, so changing a transfer's serial left the old one.
--
-- THE USER'S DECISION: "Blank it only if a transfer set it" -- a Sold Through
-- that came from a Product Database upload (or an edit, or a sale) is left
-- alone. That needs to know WHERE the value came from, so:
--   * products.sold_through_from_transfer -- true when the transfer path
--     wrote the value; any other change of sold_through sets it false
--     (products_sold_through_source, a BEFORE UPDATE trigger that reads a
--     transaction-local ticket only transfer_resync_machine() raises);
--   * the transfer path, finding no dealer transfer left, blanks Sold Through
--     only where the flag is true; otherwise it keeps the value, as before;
--   * ONCE, existing machines whose Sold Through equals their current dealer
--     transfer's are marked as set by a transfer -- the only ones that provably
--     were. Everything else starts false, i.e. kept: an unknown origin is not
--     guessed to be a transfer.
--   * transfer_to_product re-reads OLD's machine as well when an UPDATE moves
--     a transfer to another machine.
--
-- transfer_to_product's body is the DATABASE'S definition (pg_get_functiondef
-- on a database built from every migration), moved into
-- transfer_resync_machine(item, serial) with the Sold Through line changed.
-- In the sales_contracts module, after 0329 / 0330.
-- ===========================================================================

alter table public.products add column if not exists sold_through_from_transfer boolean not null default false;
comment on column public.products.sold_through_from_transfer is
  'True when the Sold Through was written by an ownership transfer (0361); a transfer correction that leaves no dealer transfer blanks it only then.';

-- ---- 1. any other change of sold_through says it is not the transfer's --------
create or replace function public.products_sold_through_source()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.sold_through is distinct from old.sold_through
     and coalesce(current_setting('rithi.sold_through_by_transfer', true), '') <> 'on' then
    new.sold_through_from_transfer := false;
  end if;
  return new;
end $$;
revoke execute on function public.products_sold_through_source() from public, anon, authenticated;
drop trigger if exists products_sold_through_source on public.products;
create trigger products_sold_through_source
  before update on public.products
  for each row execute function public.products_sold_through_source();

-- ---- 2. one machine, re-read from its sales and transfers -----------------------
create or replace function public.transfer_resync_machine(p_item text, p_serial text)
returns void language plpgsql security definer set search_path = public as $$
declare r record; v_st text;
begin
  for r in select i.id from public.sale_items i
            where lower(btrim(coalesce(i.product_name, ''))) = lower(btrim(coalesce(p_item, '')))
              and lower(btrim(coalesce(i.serial_number, ''))) = lower(btrim(coalesce(p_serial, ''))) loop
    perform public.upsert_product_from_sale(r.id);
  end loop;

  -- A machine with NO sale entry still changes hands, and the transfer is then
  -- the only thing that knows who owns it -- and, since 0328, which dealer it
  -- came through; since 0329, it takes that owner's Party Master address, city,
  -- state and Service Engineer, a blank there keeping what the row has.
  -- Since 0361: with no dealer transfer left, Sold Through is blanked only if
  -- a transfer had set it; a value from anywhere else is kept.
  v_st := public.machine_sold_through(p_item, p_serial);
  perform set_config('rithi.sold_through_by_transfer', 'on', true);
  update public.products p
     set party_name       = c.party,
         sold_through     = case when v_st is not null then v_st
                                 when p.sold_through_from_transfer then ''
                                 else p.sold_through end,
         sold_through_from_transfer = (v_st is not null),
         address          = coalesce(nullif(btrim(pm.address), ''), p.address),
         city             = coalesce(nullif(btrim(pm.city), ''), p.city),
         state            = coalesce(nullif(btrim(pm.state), ''), p.state),
         service_engineer = coalesce(nullif(btrim(pm.service_engineer), ''), p.service_engineer)
    from (select public.machine_current_party(p_item, p_serial) as party) c
    left join public.parties pm on pm.name_key = lower(btrim(coalesce(c.party, '')))
   where p.machine_key = lower(btrim(coalesce(p_item, ''))) || '|' || lower(btrim(coalesce(p_serial, '')))
     and not exists (select 1 from public.sale_items i
                      where lower(btrim(coalesce(i.product_name, ''))) = lower(btrim(coalesce(p_item, '')))
                        and lower(btrim(coalesce(i.serial_number, ''))) = lower(btrim(coalesce(p_serial, ''))));
  perform set_config('rithi.sold_through_by_transfer', 'off', true);
  -- THE TRANSFER'S REF AND DATE (0330), and the rest of the machine.
  perform public.sync_product_machine(p_item, p_serial);
end $$;
revoke execute on function public.transfer_resync_machine(text, text) from public, anon, authenticated;

-- ---- 3. the trigger: NEW's machine, and OLD's when the transfer moved -----------
create or replace function public.transfer_to_product()
returns trigger language plpgsql security definer set search_path = public as $$
declare m record;
begin
  m := case when tg_op = 'DELETE' then old else new end;
  perform public.transfer_resync_machine(m.item_name, m.serial_number);
  if tg_op = 'UPDATE'
     and (lower(btrim(coalesce(old.item_name, ''))) is distinct from lower(btrim(coalesce(new.item_name, '')))
          or lower(btrim(coalesce(old.serial_number, ''))) is distinct from lower(btrim(coalesce(new.serial_number, '')))) then
    perform public.transfer_resync_machine(old.item_name, old.serial_number);
  end if;
  return null;
end $$;
revoke execute on function public.transfer_to_product() from public, anon, authenticated;

-- ---- 4. once: the machines whose Sold Through a transfer provably set ----------
create table if not exists public.one_time_fixes_done (
  name       text primary key,
  applied_at timestamptz not null default now(),
  detail     text
);
alter table public.one_time_fixes_done enable row level security;
revoke all on public.one_time_fixes_done from anon, authenticated;

do $$
declare n bigint;
begin
  if exists (select 1 from public.one_time_fixes_done where name = '0361_sold_through_from_transfer_marked') then return; end if;
  perform set_config('rithi.sold_through_by_transfer', 'on', true);
  update public.products p
     set sold_through_from_transfer = true
   where btrim(coalesce(p.sold_through, '')) <> ''
     and not exists (select 1 from public.sale_items i
                      where lower(btrim(coalesce(i.product_name, ''))) = lower(btrim(coalesce(p.item_name, '')))
                        and lower(btrim(coalesce(i.serial_number, ''))) = lower(btrim(coalesce(p.serial_number, ''))))
     and lower(btrim(p.sold_through)) = lower(btrim(coalesce(public.machine_sold_through(p.item_name, p.serial_number), '')));
  get diagnostics n = row_count;
  perform set_config('rithi.sold_through_by_transfer', 'off', true);
  insert into public.one_time_fixes_done (name, detail)
  values ('0361_sold_through_from_transfer_marked', n || ' machine(s) marked as having their Sold Through from a transfer');
  raise notice '0361: % machine(s) marked as having their Sold Through from a transfer', n;
end $$;

-- ------------------------------------------------------------------------
-- 0362_installation_once_and_no_dealer_request.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0362 — ONE INSTALLATION CALL PER MACHINE AND PER CALL NUMBER; NO
--        INSTALLATION REQUEST FOR A DEALER
--        (second re-review D-150, D-154; the user's decisions, 2026-10-04)
--
-- D-150 -- "+ Installation call" is offered on every transfer and only the
-- browser stopped a second call: measured, two OT- installation calls with the
-- same call number were both registered. THE USER'S DECISION: the button only
-- on dealer transfers (the screen), AND the database refuses (a) a second
-- installation call with the same call number and (b) a second installation
-- call for a machine (product + serial) that already has one. A CANCELLED call
-- does not count (it installed nothing); the same call re-loaded (same UCN) is
-- not a second one; a connection with no session (a repair) is not stopped.
-- Existing duplicates are left as they are and listed by
-- _review_findings_on_live_data.sql row 8.
--
-- D-151 (the Party Master decides who is a dealer) needs no SQL: party_is_dealer()
-- already reads the Party Master, and the screens now ask the Party Master's
-- dealer list instead of the sale's own Type. A column on sale_entries was
-- tried and dropped: every update of a sale re-syncs its machines, so keeping
-- one in step would have re-written the Product Database for every dealer
-- sale, and the details view cannot gain a column a re-run of 0036 removes.
--
-- D-154 -- the dealer rule was on installation_calls alone; an installation
-- CALL REQUEST for a dealer was accepted and refused only at registration.
-- THE USER'S DECISION: refuse it when the request is raised. Same message as
-- 0328; a re-load of the same request line (reqid + product + serial) under the
-- same party stands aside, as 0351 does for the Installation Calls upload.
--
-- In the sales_contracts module, after 0361: party_is_dealer() is 0328's.
-- ===========================================================================

-- ---- D-150 ------------------------------------------------------------------
create or replace function public.installation_call_once()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_other record;
begin
  if auth.uid() is null then return new; end if;                -- a migration, a repair
  if new.cancelled_at is not null then return new; end if;
  if tg_op = 'UPDATE'
     and lower(btrim(coalesce(new.call_number, ''))) = lower(btrim(coalesce(old.call_number, '')))
     and lower(btrim(coalesce(new.product_name, ''))) = lower(btrim(coalesce(old.product_name, '')))
     and lower(btrim(coalesce(new.serial, ''))) = lower(btrim(coalesce(old.serial, ''))) then
    return new;
  end if;

  if btrim(coalesce(new.call_number, '')) <> '' then
    select ic.ucn, ic.call_number into v_other from public.installation_calls ic
     where ic.ucn is distinct from new.ucn and ic.cancelled_at is null
       and lower(btrim(coalesce(ic.call_number, ''))) = lower(btrim(new.call_number))
     limit 1;
    if found then
      raise exception 'Installation call % already carries call number % -- an installation call is raised once',
        v_other.ucn, btrim(new.call_number) using errcode = '23505';
    end if;
  end if;

  if btrim(coalesce(new.serial, '')) <> '' and btrim(coalesce(new.product_name, '')) <> '' then
    select ic.ucn, ic.call_number into v_other from public.installation_calls ic
     where ic.ucn is distinct from new.ucn and ic.cancelled_at is null
       and lower(btrim(coalesce(ic.product_name, ''))) = lower(btrim(new.product_name))
       and lower(btrim(coalesce(ic.serial, ''))) = lower(btrim(new.serial))
     limit 1;
    if found then
      raise exception '% % already has installation call % (%) -- a machine is installed once',
        btrim(new.product_name), btrim(new.serial), v_other.ucn, coalesce(nullif(btrim(v_other.call_number), ''), 'no call number')
        using errcode = '23505';
    end if;
  end if;
  return new;
end $$;
revoke execute on function public.installation_call_once() from public, anon, authenticated;
drop trigger if exists installation_call_once on public.installation_calls;
create trigger installation_call_once
  before insert or update of call_number, product_name, serial on public.installation_calls
  for each row execute function public.installation_call_once();

-- ---- D-154 ------------------------------------------------------------------
create or replace function public.call_request_not_installation_for_dealer()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return new; end if;                -- a migration, a repair
  if public.call_table_for(new.call_type) <> 'installation' then return new; end if;
  if tg_op = 'UPDATE'
     and lower(btrim(coalesce(new.party_name, ''))) = lower(btrim(coalesce(old.party_name, '')))
     and public.call_table_for(old.call_type) = 'installation' then
    return new;
  end if;
  -- A re-load of the same request line, party unchanged (the 0351 rule).
  if tg_op = 'INSERT' and exists (
       select 1 from public.call_requests cr
        where cr.reqid is not distinct from new.reqid
          and lower(btrim(coalesce(cr.product, ''))) = lower(btrim(coalesce(new.product, '')))
          and lower(btrim(coalesce(cr.serial_no, ''))) = lower(btrim(coalesce(new.serial_no, '')))
          and lower(btrim(coalesce(cr.party_name, ''))) = lower(btrim(coalesce(new.party_name, '')))) then
    return new;
  end if;
  if public.party_is_dealer(new.party_name) then
    raise exception '% is a dealer: an installation call is not raised for a dealer -- it is raised from the Ownership Transfer when the dealer sells the machine (OT-PRODUCT-SERIAL)', btrim(new.party_name)
      using errcode = '23514';
  end if;
  return new;
end $$;
revoke execute on function public.call_request_not_installation_for_dealer() from public, anon, authenticated;
drop trigger if exists call_request_not_installation_for_dealer on public.call_requests;
create trigger call_request_not_installation_for_dealer
  before insert or update of party_name, call_type on public.call_requests
  for each row execute function public.call_request_not_installation_for_dealer();

-- ------------------------------------------------------------------------
-- 0383_transfer_fresh_warranty.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0383 — A TRANSFER CAN GIVE THE NEW OWNER A FRESH WARRANTY
--
-- The user, 2026-10-05: "Need to be able to Update the Warranty Start Date,
-- Period, End Date, Same Logic as to Warranty Entry" -- "During Transfer, the
-- new Owner gets a Fresh warranty date." Asked: it is OPTIONAL per transfer,
-- and the Product Database's Warranty Number becomes the transfer's OT number
-- (its Reference no.).
--
-- ON THE TRANSFER, NOT ON THE SALE. The four columns below record what was
-- given and when; the original sale entry is not touched, so the Warranty
-- Register keeps saying what was sold.
--
-- THE SALE'S LOGIC (cover.ts): the start and the period in MONTHS are entered;
-- the years and the end are WORKED OUT, here as well as on the form, so a
-- value sent through the API cannot disagree with its own start and period.
-- The end is start + months - 1 day by cover_period_end()'s arithmetic (0218,
-- addPeriod()'s month overflow included), written inline because that
-- function's module runs after this one on a fresh build.
--
-- WHICH WARRANTY THE MACHINE WEARS (sync_product_machine, redefined from the
-- database's own current body -- 0330 + 0331 -- with only the fresh-warranty
-- lines added): the transfer's, when it starts on or after the one the sale or
-- the installation gives. A re-sale after the transfer starts later and takes
-- the warranty back; an old sale saved again starts earlier and does not.
-- ===========================================================================

alter table public.ownership_transfers add column if not exists warranty_start  date;
alter table public.ownership_transfers add column if not exists warranty_months numeric;
alter table public.ownership_transfers add column if not exists warranty_years  numeric;
alter table public.ownership_transfers add column if not exists warranty_end    date;

-- ---- the years and the end are worked out, never typed --------------------
create or replace function public.ownership_transfer_warranty()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.warranty_start is null then
    new.warranty_months := null; new.warranty_years := null; new.warranty_end := null;
    return new;
  end if;
  if new.warranty_months is null or new.warranty_months <= 0 then
    raise exception 'A fresh warranty needs its period in months (more than 0).';
  end if;
  -- The Warranty Number the machine will carry is this transfer's OT number.
  if btrim(coalesce(new.reference_no, '')) = '' then
    raise exception 'A fresh warranty needs the transfer''s Reference no. (its OT number) -- it becomes the machine''s Warranty Number.';
  end if;
  new.warranty_months := round(new.warranty_months);
  new.warranty_years  := round(new.warranty_months / 12.0, 2);
  new.warranty_end    := (date_trunc('month', new.warranty_start)::date
                          + make_interval(months => new.warranty_months::int)
                          + make_interval(days   => extract(day from new.warranty_start)::int - 1))::date - 1;
  return new;
end $$;
revoke execute on function public.ownership_transfer_warranty() from public, anon, authenticated;
drop trigger if exists ownership_transfer_warranty on public.ownership_transfers;
create trigger ownership_transfer_warranty before insert or update on public.ownership_transfers
  for each row execute function public.ownership_transfer_warranty();

-- ---- the machine wears it ---------------------------------------------------
create or replace function public.sync_product_machine(p_item text, p_serial text)
 returns void
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  n text := lower(btrim(coalesce(p_item, '')));
  s text := lower(btrim(coalesce(p_serial, '')));
  k text;
  w record; c record; a record; t record; cur record; pm record;
  v_party text;
  foreign_contract boolean := false;
  foreign_warranty boolean := false;
  v_inst date; v_months numeric; v_inst_end date;
  ft record; use_ft boolean := false;
begin
  if n = '' or s = '' then return; end if;
  k := n || '|' || s;

  select i.sa_number,
         coalesce(i.warranty_start, h.warranty_start) as ws,
         coalesce(i.warranty_end,   h.warranty_end)   as we,
         coalesce(i.pm_visits,      h.pm_visits)      as pm,
         coalesce(nullif(btrim(coalesce(i.invoice_no, '')), ''), nullif(btrim(coalesce(h.invoice_no, '')), '')) as inv,
         coalesce(i.invoice_date,    h.invoice_date)    as invd,
         coalesce(i.warranty_years,  h.warranty_years)  as wy,
         coalesce(i.warranty_months, h.warranty_months) as wm,
         i.accessories_included as acc
    into w
    from public.sale_items i left join public.sale_entries h on h.sa_number = i.sa_number
   where lower(btrim(coalesce(i.product_name, ''))) = n
     and lower(btrim(coalesce(i.serial_number, ''))) = s
   order by coalesce(i.warranty_end, h.warranty_end) desc nulls last, i.id desc limit 1;

  -- THE ENGINEER'S CHOICE AT INSTALLATION (0331, the user, 2026-10-03): where
  -- the installation's customer feedback answers "Warranty Start Date?" with
  -- "Installation Call Solved Date", the warranty starts on the day that call
  -- was solved and ends a warranty period later; "Invoice Date" keeps the
  -- documented start on the sale.
  v_inst := public.machine_install_warranty_start(p_item, p_serial);
  if v_inst is not null then
    select coalesce(i.warranty_months, h.warranty_months, i.warranty_years * 12, h.warranty_years * 12)
      into v_months
      from public.sale_items i left join public.sale_entries h on h.sa_number = i.sa_number
     where lower(btrim(coalesce(i.product_name, ''))) = n
       and lower(btrim(coalesce(i.serial_number, ''))) = s
     order by coalesce(i.warranty_end, h.warranty_end) desc nulls last, i.id desc limit 1;
    -- cover_period_end() (0218) reproduces the application's own arithmetic;
    -- asked by name because its module runs after this one on a fresh build.
    if v_months is not null and v_months > 0 and to_regprocedure('public.cover_period_end(date,numeric)') is not null then
      execute 'select public.cover_period_end($1, $2)' into v_inst_end using v_inst, v_months;
    end if;
  end if;

  select i.mc_number, i.product_code,
         coalesce(nullif(btrim(coalesce(i.contract_type, '')), ''), h.contract_type) as ct,
         coalesce(i.contract_start, h.contract_start) as cs,
         coalesce(i.contract_end,   h.contract_end)   as ce,
         coalesce(i.pm_visits_total, h.pm_visits_total) as pm,
         coalesce(nullif(btrim(coalesce(i.status, '')), ''), h.status) as st,
         coalesce(nullif(btrim(coalesce(i.party_name, '')), ''), h.party_name) as party
    into c
    from public.contract_items i left join public.contract_entries h on h.mc_number = i.mc_number
   where lower(btrim(coalesce(i.product_name, ''))) = n
     and lower(btrim(coalesce(i.serial_number, ''))) = s
   order by coalesce(i.contract_end, h.contract_end) desc nulls last, i.id desc limit 1;

  -- The recovered detail, used only where the registers are silent.
  select e.warranty_number, e.warranty_start, e.warranty_end,
         e.contract_number, e.contract_type, e.contract_start, e.contract_end
    into a
    from public.product_additional_entries e where e.machine_key = k limit 1;

  select x.reference_no as ref, x.transfer_date as d
    into t
    from public.ownership_transfers x
   where lower(btrim(coalesce(x.item_name, ''))) = n
     and lower(btrim(coalesce(x.serial_number, ''))) = s
   order by coalesce(x.transferred_at, x.created_at, x.transfer_date::timestamptz) desc nulls last, x.id desc
   limit 1;

  -- A FRESH WARRANTY GIVEN ON A TRANSFER (0383, the user, 2026-10-05: "During
  -- Transfer, the new Owner gets a Fresh warranty date"): the latest transfer
  -- of this machine that carries one. It decides the machine's warranty when
  -- it starts on or after the warranty the sale (or the installation) gives,
  -- so a re-sale after the transfer takes the warranty back, and an old sale
  -- saved again does not.
  select x.reference_no as ref, x.warranty_start as ws, x.warranty_end as we,
         x.warranty_months as wm, x.warranty_years as wy
    into ft
    from public.ownership_transfers x
   where lower(btrim(coalesce(x.item_name, ''))) = n
     and lower(btrim(coalesce(x.serial_number, ''))) = s
     and x.warranty_start is not null
   order by coalesce(x.transferred_at, x.created_at, x.transfer_date::timestamptz) desc nulls last, x.id desc
   limit 1;

  -- A CONTRACT FOR A MACHINE NOT YET HELD is inserted (the user's choice), for
  -- the owner the registers name, with that owner's Party Master address.
  if c.mc_number is not null and not exists (select 1 from public.products where machine_key = k) then
    v_party := coalesce(nullif(btrim(coalesce(public.machine_current_party(p_item, p_serial), '')), ''),
                        nullif(btrim(coalesce(c.party, '')), ''), '');
    select nullif(btrim(x.address), '') as address, nullif(btrim(x.city), '') as city,
           nullif(btrim(x.state), '') as state, nullif(btrim(x.service_engineer), '') as engineer
      into pm from public.parties x where x.name_key = lower(v_party) limit 1;
    insert into public.products (item_name, serial_number, party_name, item_code,
                                 address, city, state, service_engineer)
    values (btrim(p_item), btrim(p_serial), v_party, coalesce(c.product_code, ''),
            coalesce(pm.address, ''), coalesce(pm.city, ''), coalesce(pm.state, ''), coalesce(pm.engineer, ''))
    on conflict (machine_key) do nothing;
  end if;

  use_ft := ft.ws is not null
    and ft.ws >= coalesce(case when v_inst is not null then v_inst end, w.ws, a.warranty_start, '-infinity'::date);

  select p.contract_number, p.warranty_number into cur from public.products p where p.machine_key = k;
  if not found then return; end if;

  -- WHAT THE SERIAL-ONLY SYNC LEFT BEHIND: a number this machine carries that a
  -- register line DOES hold, but for another model sharing the serial.
  if c.mc_number is null and nullif(btrim(coalesce(a.contract_number, '')), '') is null
     and btrim(coalesce(cur.contract_number, '')) <> '' then
    foreign_contract := exists (select 1 from public.contract_items x where x.mc_number = cur.contract_number);
  end if;
  if w.sa_number is null and nullif(btrim(coalesce(a.warranty_number, '')), '') is null
     and btrim(coalesce(cur.warranty_number, '')) <> '' then
    foreign_warranty := exists (select 1 from public.sale_items x where x.sa_number = cur.warranty_number);
  end if;

  update public.products p set
    warranty_number = case when use_ft then ft.ref
                           when foreign_warranty then ''
                           else coalesce(w.sa_number, nullif(a.warranty_number, ''), p.warranty_number) end,
    warranty_start  = case when use_ft then ft.ws
                           when v_inst is not null then v_inst
                           when foreign_warranty then null else coalesce(w.ws, a.warranty_start, p.warranty_start) end,
    warranty_end    = case when use_ft then ft.we
                           when v_inst is not null and v_inst_end is not null then v_inst_end
                           when foreign_warranty then null else coalesce(w.we, a.warranty_end,   p.warranty_end) end,
    invoice_no      = coalesce(w.inv,  p.invoice_no),
    invoice_date    = coalesce(w.invd, p.invoice_date),
    warranty_years  = case when use_ft then ft.wy else coalesce(w.wy,   p.warranty_years) end,
    warranty_months = case when use_ft then ft.wm::integer else coalesce(w.wm,   p.warranty_months) end,
    accessories_included = coalesce(w.acc, p.accessories_included),
    contract_number = case when foreign_contract then ''
                           else coalesce(c.mc_number, nullif(a.contract_number, ''), p.contract_number) end,
    contract_start  = case when foreign_contract then null else coalesce(c.cs, a.contract_start, p.contract_start) end,
    contract_end    = case when foreign_contract then null else coalesce(c.ce, a.contract_end,   p.contract_end) end,
    contract_type   = case when foreign_contract then ''
                           else coalesce(nullif(c.ct, ''), nullif(a.contract_type, ''), p.contract_type) end,
    contract_status_keyed = case when foreign_contract then ''
                                 else coalesce(nullif(btrim(coalesce(c.st, '')), ''), p.contract_status_keyed) end,
    -- THE CONTRACT'S PM VISITS OVERWRITE THE SALE'S (the user's choice), while
    -- the machine has a contract line saying how many.
    pm_visits       = case when c.mc_number is not null and c.pm is not null then c.pm
                           else coalesce(w.pm, p.pm_visits) end,
    transfer_ref    = coalesce(nullif(btrim(coalesce(t.ref, '')), ''), p.transfer_ref),
    transfer_date   = coalesce(t.d, p.transfer_date),
    -- machine_cover's rule (0036): a current contract is its type, a current
    -- warranty WGP, and a machine the registers know with neither is OGP. One
    -- no register mentions keeps the status it was imported with.
    item_status     = case
      when coalesce(c.ce, a.contract_end) >= current_date
        then coalesce(nullif(c.ct, ''), nullif(a.contract_type, ''), 'CMC')
      when case when use_ft then ft.we
                else coalesce(case when v_inst is not null then v_inst_end end, w.we, a.warranty_end) end >= current_date then 'WGP'
      when use_ft or w.sa_number is not null or c.mc_number is not null or a.warranty_number is not null
        or a.contract_number is not null or foreign_contract or foreign_warranty then 'OGP'
      else p.item_status end
  where p.machine_key = k;
end $function$;
revoke execute on function public.sync_product_machine(text, text) from public, anon, authenticated;

comment on column public.ownership_transfers.warranty_start is
  'A fresh warranty given to the new owner on this transfer (0383); blank keeps the machine''s warranty. Months entered; years and end worked out.';

-- ------------------------------------------------------------------------
-- 0391_transfer_ot_number_invoice_files.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0391 — AN OWNERSHIP TRANSFER: ITS OT NUMBER, ITS INVOICE, ITS FILES
--
-- The user, 2026-10-06: "OT Number should be Auto Generated. Add Invoice No,
-- Invoice Date Provision in Ownership Transfer also a File Upload Option to
-- save important info regarding Ownership Transfer - Optional Field." Asked:
--   * the number CONTINUES the OTnnnn series already on file (OT1432 -> OT1433);
--   * an invoice on a transfer goes to the Product Database whether or not the
--     transfer gives a fresh warranty;
--   * the files go to an "Ownership Transfers" folder in Drive.
--
-- THE NUMBER IS THE DATABASE'S, given on insert where none is sent. A loaded
-- historical transfer keeps the OT number its file carries; a blank one is
-- numbered like a new one. An advisory lock serialises two saves at once, and
-- the next number reads only `OT` + digits, so a customer's own reference
-- typed into the column before today is never mistaken for one.
--
-- THE INVOICE (invoice_no, invoice_date) reaches the machine through
-- sync_product_machine -- redefined from the database's current body (0383)
-- with only the invoice lines added: the latest transfer naming an invoice
-- gives the machine that invoice while it is dated on or after the sale's.
--
-- THE FILES (attachments) are a list of {name, url, at, by}, the shape of the
-- Party Master's KYC records (kyc_docs): uploaded to Drive by the bridge, named here.
-- ===========================================================================

alter table public.ownership_transfers add column if not exists invoice_no   text not null default '';
alter table public.ownership_transfers add column if not exists invoice_date date;
alter table public.ownership_transfers add column if not exists attachments  jsonb not null default '[]'::jsonb;

-- ---- the next OT number ------------------------------------------------------
create or replace function public.ot_next_no()
returns text language plpgsql security definer set search_path = public as $$
declare n bigint;
begin
  perform pg_advisory_xact_lock(hashtext('ownership_transfer_ot_no'));
  select coalesce(max(substring(btrim(x.reference_no) from '^[Oo][Tt]([0-9]+)$')::bigint), 0)
    into n from public.ownership_transfers x
   where btrim(x.reference_no) ~ '^[Oo][Tt][0-9]+$';
  return 'OT' || (n + 1)::text;
end $$;
revoke execute on function public.ot_next_no() from public, anon, authenticated;

-- Named to run BEFORE ownership_transfer_sold_through and _warranty (triggers
-- of one timing run in name order): the fresh warranty needs the number.
create or replace function public.ownership_transfer_number()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if btrim(coalesce(new.reference_no, '')) = '' then
      new.reference_no := public.ot_next_no();
    end if;
  elsif btrim(coalesce(new.reference_no, '')) = '' then
    -- A number once given is not blanked by an edit.
    new.reference_no := old.reference_no;
  end if;
  new.invoice_no := btrim(coalesce(new.invoice_no, ''));
  if jsonb_typeof(coalesce(new.attachments, '[]'::jsonb)) <> 'array' then
    raise exception 'attachments must be a list.';
  end if;
  return new;
end $$;
revoke execute on function public.ownership_transfer_number() from public, anon, authenticated;
drop trigger if exists ownership_transfer_number on public.ownership_transfers;
create trigger ownership_transfer_number before insert or update on public.ownership_transfers
  for each row execute function public.ownership_transfer_number();

-- ---- the machine carries the transfer's invoice ------------------------------
create or replace function public.sync_product_machine(p_item text, p_serial text)
 returns void
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  n text := lower(btrim(coalesce(p_item, '')));
  s text := lower(btrim(coalesce(p_serial, '')));
  k text;
  w record; c record; a record; t record; cur record; pm record;
  v_party text;
  foreign_contract boolean := false;
  foreign_warranty boolean := false;
  v_inst date; v_months numeric; v_inst_end date;
  ft record; use_ft boolean := false;
  ti record; use_ti boolean := false;
begin
  if n = '' or s = '' then return; end if;
  k := n || '|' || s;

  select i.sa_number,
         coalesce(i.warranty_start, h.warranty_start) as ws,
         coalesce(i.warranty_end,   h.warranty_end)   as we,
         coalesce(i.pm_visits,      h.pm_visits)      as pm,
         coalesce(nullif(btrim(coalesce(i.invoice_no, '')), ''), nullif(btrim(coalesce(h.invoice_no, '')), '')) as inv,
         coalesce(i.invoice_date,    h.invoice_date)    as invd,
         coalesce(i.warranty_years,  h.warranty_years)  as wy,
         coalesce(i.warranty_months, h.warranty_months) as wm,
         i.accessories_included as acc
    into w
    from public.sale_items i left join public.sale_entries h on h.sa_number = i.sa_number
   where lower(btrim(coalesce(i.product_name, ''))) = n
     and lower(btrim(coalesce(i.serial_number, ''))) = s
   order by coalesce(i.warranty_end, h.warranty_end) desc nulls last, i.id desc limit 1;

  -- THE ENGINEER'S CHOICE AT INSTALLATION (0331, the user, 2026-10-03): where
  -- the installation's customer feedback answers "Warranty Start Date?" with
  -- "Installation Call Solved Date", the warranty starts on the day that call
  -- was solved and ends a warranty period later; "Invoice Date" keeps the
  -- documented start on the sale.
  v_inst := public.machine_install_warranty_start(p_item, p_serial);
  if v_inst is not null then
    select coalesce(i.warranty_months, h.warranty_months, i.warranty_years * 12, h.warranty_years * 12)
      into v_months
      from public.sale_items i left join public.sale_entries h on h.sa_number = i.sa_number
     where lower(btrim(coalesce(i.product_name, ''))) = n
       and lower(btrim(coalesce(i.serial_number, ''))) = s
     order by coalesce(i.warranty_end, h.warranty_end) desc nulls last, i.id desc limit 1;
    -- cover_period_end() (0218) reproduces the application's own arithmetic;
    -- asked by name because its module runs after this one on a fresh build.
    if v_months is not null and v_months > 0 and to_regprocedure('public.cover_period_end(date,numeric)') is not null then
      execute 'select public.cover_period_end($1, $2)' into v_inst_end using v_inst, v_months;
    end if;
  end if;

  select i.mc_number, i.product_code,
         coalesce(nullif(btrim(coalesce(i.contract_type, '')), ''), h.contract_type) as ct,
         coalesce(i.contract_start, h.contract_start) as cs,
         coalesce(i.contract_end,   h.contract_end)   as ce,
         coalesce(i.pm_visits_total, h.pm_visits_total) as pm,
         coalesce(nullif(btrim(coalesce(i.status, '')), ''), h.status) as st,
         coalesce(nullif(btrim(coalesce(i.party_name, '')), ''), h.party_name) as party
    into c
    from public.contract_items i left join public.contract_entries h on h.mc_number = i.mc_number
   where lower(btrim(coalesce(i.product_name, ''))) = n
     and lower(btrim(coalesce(i.serial_number, ''))) = s
   order by coalesce(i.contract_end, h.contract_end) desc nulls last, i.id desc limit 1;

  -- The recovered detail, used only where the registers are silent.
  select e.warranty_number, e.warranty_start, e.warranty_end,
         e.contract_number, e.contract_type, e.contract_start, e.contract_end
    into a
    from public.product_additional_entries e where e.machine_key = k limit 1;

  select x.reference_no as ref, x.transfer_date as d
    into t
    from public.ownership_transfers x
   where lower(btrim(coalesce(x.item_name, ''))) = n
     and lower(btrim(coalesce(x.serial_number, ''))) = s
   order by coalesce(x.transferred_at, x.created_at, x.transfer_date::timestamptz) desc nulls last, x.id desc
   limit 1;

  -- A FRESH WARRANTY GIVEN ON A TRANSFER (0383, the user, 2026-10-05: "During
  -- Transfer, the new Owner gets a Fresh warranty date"): the latest transfer
  -- of this machine that carries one. It decides the machine's warranty when
  -- it starts on or after the warranty the sale (or the installation) gives,
  -- so a re-sale after the transfer takes the warranty back, and an old sale
  -- saved again does not.
  select x.reference_no as ref, x.warranty_start as ws, x.warranty_end as we,
         x.warranty_months as wm, x.warranty_years as wy
    into ft
    from public.ownership_transfers x
   where lower(btrim(coalesce(x.item_name, ''))) = n
     and lower(btrim(coalesce(x.serial_number, ''))) = s
     and x.warranty_start is not null
   order by coalesce(x.transferred_at, x.created_at, x.transfer_date::timestamptz) desc nulls last, x.id desc
   limit 1;

  -- THE INVOICE A TRANSFER CARRIES (0391, the user, 2026-10-06: an invoice on
  -- a transfer goes to the Product Database, with or without a fresh
  -- warranty): the latest transfer of this machine that names one. It is the
  -- machine's invoice when it is dated on or after the sale's (a transfer with
  -- no invoice date is dated by the transfer), so a re-sale after it takes the
  -- invoice back and the old sale saved again does not.
  select nullif(btrim(coalesce(x.invoice_no, '')), '') as inv,
         x.invoice_date as invd,
         coalesce(x.invoice_date, x.transfer_date, (x.created_at at time zone 'Asia/Kolkata')::date) as on_day
    into ti
    from public.ownership_transfers x
   where lower(btrim(coalesce(x.item_name, ''))) = n
     and lower(btrim(coalesce(x.serial_number, ''))) = s
     and (btrim(coalesce(x.invoice_no, '')) <> '' or x.invoice_date is not null)
   order by coalesce(x.transferred_at, x.created_at, x.transfer_date::timestamptz) desc nulls last, x.id desc
   limit 1;
  use_ti := ti.on_day is not null and ti.on_day >= coalesce(w.invd, '-infinity'::date);

  -- A CONTRACT FOR A MACHINE NOT YET HELD is inserted (the user's choice), for
  -- the owner the registers name, with that owner's Party Master address.
  if c.mc_number is not null and not exists (select 1 from public.products where machine_key = k) then
    v_party := coalesce(nullif(btrim(coalesce(public.machine_current_party(p_item, p_serial), '')), ''),
                        nullif(btrim(coalesce(c.party, '')), ''), '');
    select nullif(btrim(x.address), '') as address, nullif(btrim(x.city), '') as city,
           nullif(btrim(x.state), '') as state, nullif(btrim(x.service_engineer), '') as engineer
      into pm from public.parties x where x.name_key = lower(v_party) limit 1;
    insert into public.products (item_name, serial_number, party_name, item_code,
                                 address, city, state, service_engineer)
    values (btrim(p_item), btrim(p_serial), v_party, coalesce(c.product_code, ''),
            coalesce(pm.address, ''), coalesce(pm.city, ''), coalesce(pm.state, ''), coalesce(pm.engineer, ''))
    on conflict (machine_key) do nothing;
  end if;

  use_ft := ft.ws is not null
    and ft.ws >= coalesce(case when v_inst is not null then v_inst end, w.ws, a.warranty_start, '-infinity'::date);

  select p.contract_number, p.warranty_number into cur from public.products p where p.machine_key = k;
  if not found then return; end if;

  -- WHAT THE SERIAL-ONLY SYNC LEFT BEHIND: a number this machine carries that a
  -- register line DOES hold, but for another model sharing the serial.
  if c.mc_number is null and nullif(btrim(coalesce(a.contract_number, '')), '') is null
     and btrim(coalesce(cur.contract_number, '')) <> '' then
    foreign_contract := exists (select 1 from public.contract_items x where x.mc_number = cur.contract_number);
  end if;
  if w.sa_number is null and nullif(btrim(coalesce(a.warranty_number, '')), '') is null
     and btrim(coalesce(cur.warranty_number, '')) <> '' then
    foreign_warranty := exists (select 1 from public.sale_items x where x.sa_number = cur.warranty_number);
  end if;

  update public.products p set
    warranty_number = case when use_ft then ft.ref
                           when foreign_warranty then ''
                           else coalesce(w.sa_number, nullif(a.warranty_number, ''), p.warranty_number) end,
    warranty_start  = case when use_ft then ft.ws
                           when v_inst is not null then v_inst
                           when foreign_warranty then null else coalesce(w.ws, a.warranty_start, p.warranty_start) end,
    warranty_end    = case when use_ft then ft.we
                           when v_inst is not null and v_inst_end is not null then v_inst_end
                           when foreign_warranty then null else coalesce(w.we, a.warranty_end,   p.warranty_end) end,
    invoice_no      = case when use_ti then coalesce(ti.inv, '') else coalesce(w.inv,  p.invoice_no) end,
    invoice_date    = case when use_ti then ti.invd else coalesce(w.invd, p.invoice_date) end,
    warranty_years  = case when use_ft then ft.wy else coalesce(w.wy,   p.warranty_years) end,
    warranty_months = case when use_ft then ft.wm::integer else coalesce(w.wm,   p.warranty_months) end,
    accessories_included = coalesce(w.acc, p.accessories_included),
    contract_number = case when foreign_contract then ''
                           else coalesce(c.mc_number, nullif(a.contract_number, ''), p.contract_number) end,
    contract_start  = case when foreign_contract then null else coalesce(c.cs, a.contract_start, p.contract_start) end,
    contract_end    = case when foreign_contract then null else coalesce(c.ce, a.contract_end,   p.contract_end) end,
    contract_type   = case when foreign_contract then ''
                           else coalesce(nullif(c.ct, ''), nullif(a.contract_type, ''), p.contract_type) end,
    contract_status_keyed = case when foreign_contract then ''
                                 else coalesce(nullif(btrim(coalesce(c.st, '')), ''), p.contract_status_keyed) end,
    -- THE CONTRACT'S PM VISITS OVERWRITE THE SALE'S (the user's choice), while
    -- the machine has a contract line saying how many.
    pm_visits       = case when c.mc_number is not null and c.pm is not null then c.pm
                           else coalesce(w.pm, p.pm_visits) end,
    transfer_ref    = coalesce(nullif(btrim(coalesce(t.ref, '')), ''), p.transfer_ref),
    transfer_date   = coalesce(t.d, p.transfer_date),
    -- machine_cover's rule (0036): a current contract is its type, a current
    -- warranty WGP, and a machine the registers know with neither is OGP. One
    -- no register mentions keeps the status it was imported with.
    item_status     = case
      when coalesce(c.ce, a.contract_end) >= current_date
        then coalesce(nullif(c.ct, ''), nullif(a.contract_type, ''), 'CMC')
      when case when use_ft then ft.we
                else coalesce(case when v_inst is not null then v_inst_end end, w.we, a.warranty_end) end >= current_date then 'WGP'
      when use_ft or w.sa_number is not null or c.mc_number is not null or a.warranty_number is not null
        or a.contract_number is not null or foreign_contract or foreign_warranty then 'OGP'
      else p.item_status end
  where p.machine_key = k;
end $function$;
revoke execute on function public.sync_product_machine(text, text) from public, anon, authenticated;

comment on column public.ownership_transfers.reference_no is
  'The OT number: OT + the next number after the highest on file, given by the database on insert when none is sent (0391).';
comment on column public.ownership_transfers.attachments is
  'Files kept with the transfer: a list of {name, url, at, by}, uploaded to the "Ownership Transfers" Drive folder (0391).';

-- ------------------------------------------------------------------------
-- 0044_sla_rules.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- SLA rules — the service-level targets, editable in Admin Config. Each rule is
-- a named target in hours with an on/off switch; the app computes each open
-- call's status (on track / due soon / breached) against the active rules and
-- highlights it for engineers. The rule LOGIC is fixed (which event each rule
-- measures); the hours and whether it applies are what admins edit.
-- ===========================================================================

create table if not exists public.sla_rules (
  key          text primary key,   -- fixed rule id (see seed)
  label        text not null,
  target_hours integer not null,
  active       boolean not null default true,
  sort_order   integer not null default 0,
  updated_at   timestamptz not null default now()
);

-- Seed the agreed rules (idempotent — an admin's later edits are preserved).
insert into public.sla_rules (key, label, target_hours, sort_order) values
  ('first_visit',             'First visit',                         72,  1),
  ('closure',                 'Call closure',                        120, 2),
  ('closure_spare',           'Closure — call includes a spare',     168, 3),
  ('closure_spare_noncover',  'Closure — spare & not in CMC / WGP',  240, 4),
  ('stores_dispatch',         'Stores dispatch — from final approval', 72, 5)
on conflict (key) do nothing;

create or replace function public.sla_rules_touch()
returns trigger language plpgsql as $$
begin new.updated_at := now(); return new; end $$;
drop trigger if exists sla_rules_touch on public.sla_rules;
create trigger sla_rules_touch before update on public.sla_rules
  for each row execute function public.sla_rules_touch();

alter table public.sla_rules enable row level security;
grant select, insert, update, delete on public.sla_rules to authenticated;

drop policy if exists sla_read on public.sla_rules;
create policy sla_read on public.sla_rules for select using (auth.role() = 'authenticated');

drop policy if exists sla_write on public.sla_rules;
create policy sla_write on public.sla_rules for all
  using (public.is_admin() or public.has_perm('config.manage'))
  with check (public.is_admin() or public.has_perm('config.manage'));

-- ------------------------------------------------------------------------
-- 0042_knowledge_base.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Knowledge Base — team-written field-solution articles. Anyone signed in can
-- read every article and contribute one; the author (or an admin) can edit or
-- delete their own. Stamped with the author so the team knows who to ask.
-- ===========================================================================

create table if not exists public.kb_articles (
  id           bigint generated always as identity primary key,
  title        text not null,
  body         text not null,
  category     text default '',      -- Field Issue / How-To / Product Tip / Other
  product      text default '',      -- optional: the product / model it concerns
  tags         text default '',      -- optional: comma-separated keywords
  attachments  jsonb not null default '[]',  -- [{name, url}] — links to files in Drive / on Pages / anywhere
  author_name  text default '',
  author_email text default '',
  created_by   uuid references auth.users (id),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index if not exists kb_articles_updated_idx  on public.kb_articles (updated_at desc);
create index if not exists kb_articles_category_idx  on public.kb_articles (category);

-- Stamp the author on insert (can't be spoofed) and updated_at on every write.
create or replace function public.kb_before_write()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' and auth.uid() is not null then
    new.created_by := auth.uid();
  end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists kb_biu on public.kb_articles;
create trigger kb_biu before insert or update on public.kb_articles
  for each row execute function public.kb_before_write();

alter table public.kb_articles enable row level security;
grant select, insert, update, delete on public.kb_articles to authenticated;

-- Read: everyone signed in. Contribute: any signed-in user (stamped as self).
-- Edit / delete: the author, or an admin.
drop policy if exists kb_read on public.kb_articles;
create policy kb_read on public.kb_articles for select
  using (auth.role() = 'authenticated');

drop policy if exists kb_insert on public.kb_articles;
create policy kb_insert on public.kb_articles for insert
  with check (auth.uid() is not null);

drop policy if exists kb_update on public.kb_articles;
create policy kb_update on public.kb_articles for update
  using (created_by = auth.uid() or public.is_admin())
  with check (created_by = auth.uid() or public.is_admin());

drop policy if exists kb_delete on public.kb_articles;
create policy kb_delete on public.kb_articles for delete
  using (created_by = auth.uid() or public.is_admin());

-- ------------------------------------------------------------------------
-- 0043_help_screenshots.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Help screenshots — one optional picture per task in the "How to use RITHI
-- CRM" guide, keyed by the task's section id (e.g. 'request', 'install'). Every
-- signed-in user sees them; only an admin can set or clear one. The image is a
-- downscaled data URL (same as Knowledge Base article images), so no separate
-- file store is needed.
-- ===========================================================================

create table if not exists public.help_screenshots (
  section_id  text primary key,             -- matches a guide section id
  image       text not null,                -- data URL (downscaled JPEG/PNG)
  caption     text not null default '',
  updated_by  uuid references auth.users (id),
  updated_at  timestamptz not null default now()
);

-- Stamp who/when on every write (can't be spoofed by the client).
create or replace function public.help_shot_before_write()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is not null then new.updated_by := auth.uid(); end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists help_shot_biu on public.help_screenshots;
create trigger help_shot_biu before insert or update on public.help_screenshots
  for each row execute function public.help_shot_before_write();

alter table public.help_screenshots enable row level security;
grant select, insert, update, delete on public.help_screenshots to authenticated;

-- Read: everyone signed in. Set / replace / clear: admins only.
drop policy if exists help_shot_read on public.help_screenshots;
create policy help_shot_read on public.help_screenshots for select
  using (auth.role() = 'authenticated');

drop policy if exists help_shot_insert on public.help_screenshots;
create policy help_shot_insert on public.help_screenshots for insert
  with check (public.is_admin());

drop policy if exists help_shot_update on public.help_screenshots;
create policy help_shot_update on public.help_screenshots for update
  using (public.is_admin()) with check (public.is_admin());

drop policy if exists help_shot_delete on public.help_screenshots;
create policy help_shot_delete on public.help_screenshots for delete
  using (public.is_admin());

-- ------------------------------------------------------------------------
-- 0301_knowledge_base_needs_a_profile.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE KNOWLEDGE BASE ASKS FOR A KNOWN LOGIN, NOT JUST A SIGNED-IN ONE (D-074).
--
-- 0042 let "everyone signed in" read Field Solutions and "any signed-in user"
-- write one. Signed in is not the same as known: a Supabase Auth account with
-- no profile and no User Master row is signed in, and FRS-210.5 says it holds
-- nothing. These two policies did not go through has_perm(), so 0300 could not
-- reach them.
--
-- A PROFILE is the test -- my_role() is NULL only when there is none (it reads
-- a blank role as engineer). Every person the app admits has one, so nobody
-- who can use Field Solutions today loses it. Wrapped in a sub-select so it is
-- asked once per query, not once per article (0250).
-- Edit and delete are untouched: they already need the author or an admin.
-- ===========================================================================

drop policy if exists kb_read on public.kb_articles;
create policy kb_read on public.kb_articles for select
  using ((select public.my_role()) is not null);

drop policy if exists kb_insert on public.kb_articles;
create policy kb_insert on public.kb_articles for insert
  with check ((select public.my_role()) is not null);

-- ------------------------------------------------------------------------
-- 0045_notifications.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- In-app notifications — a per-user bell. The database raises a notification
-- when a call is allotted to an engineer, or a spare they requested is
-- dispatched. Each user reads/marks only their own.
-- ===========================================================================

create table if not exists public.notifications (
  id              bigint generated always as identity primary key,
  recipient_id    uuid references auth.users (id),
  recipient_email text default '',
  kind            text default '',
  title           text not null,
  body            text default '',
  link            text default '',
  read            boolean not null default false,
  created_at      timestamptz not null default now()
);
create index if not exists notifications_recipient_idx on public.notifications (recipient_id, read, created_at desc);

alter table public.notifications enable row level security;
grant select, update on public.notifications to authenticated;
drop policy if exists notif_read on public.notifications;
create policy notif_read on public.notifications for select using (recipient_id = auth.uid());
drop policy if exists notif_update on public.notifications;
create policy notif_update on public.notifications for update
  using (recipient_id = auth.uid()) with check (recipient_id = auth.uid());
-- No insert policy: only the SECURITY DEFINER triggers below create rows.

-- Resolve an engineer (by email, else by directory name) to a login id.
create or replace function public.notify_resolve_uid(p_email text, p_name text)
returns uuid language sql stable security definer set search_path = public as $$
  select coalesce(
    (select id from public.profiles where lower(email) = lower(nullif(p_email, '')) limit 1),
    (select p.id from public.profiles p
       join public.user_directory d on lower(d.email) = lower(p.email)
      where lower(d.name) = lower(nullif(p_name, '')) limit 1)
  );
$$;

-- ---- call allotted ---------------------------------------------------------
create or replace function public.notify_call_allotted()
returns trigger language plpgsql security definer set search_path = public as $$
declare uid uuid;
begin
  if coalesce(new.allocated_to, '') = '' then return new; end if;
  if tg_op = 'UPDATE' and new.allocated_to is not distinct from old.allocated_to then return new; end if;
  uid := public.notify_resolve_uid(new.allocated_to_email, new.allocated_to);
  if uid is null then return new; end if;
  insert into public.notifications (recipient_id, recipient_email, kind, title, body, link)
  values (uid, coalesce(new.allocated_to_email, ''), 'call_allotted',
          'Call allotted to you',
          concat_ws(' · ', nullif(coalesce(new.ucn, ''), ''), nullif(coalesce(new.party_name, ''), ''), nullif(coalesce(new.product_name, ''), '')),
          '/' || case public.call_table_for(new.call_type)
                   when 'installation' then 'installations' when 'pm' then 'pm-calls' else 'field-calls' end);
  return new;
end $$;

-- ---- spare dispatched ------------------------------------------------------
create or replace function public.notify_spare_dispatched()
returns trigger language plpgsql security definer set search_path = public as $$
declare uid uuid; r record;
begin
  if coalesce(new.stores_status, '') !~* 'dispatch' then return new; end if;
  if tg_op = 'UPDATE' and coalesce(old.stores_status, '') ~* 'dispatch' then return new; end if;
  select engineer, engineer_email, ucn, party_name into r
    from public.spare_requests where uid = new.request_uid;
  uid := public.notify_resolve_uid(r.engineer_email, r.engineer);
  if uid is null then return new; end if;
  insert into public.notifications (recipient_id, recipient_email, kind, title, body, link)
  values (uid, coalesce(r.engineer_email, ''), 'spare_dispatched',
          'Spare dispatched',
          concat_ws(' · ', nullif(coalesce(new.part, ''), ''), nullif(coalesce(r.ucn, ''), ''), nullif(coalesce(r.party_name, ''), '')),
          '/spare-requests');
  return new;
end $$;

-- ---- attach the triggers ---------------------------------------------------
do $$
declare t text;
begin
  -- call allotted: on whichever call tables exist (split base tables, else calls).
  foreach t in array array['field_calls', 'installation_calls', 'pm_calls', 'calls'] loop
    if to_regclass('public.' || t) is not null
       and (select relkind from pg_class where oid = ('public.' || t)::regclass) = 'r' then
      execute format('drop trigger if exists notify_alloc on public.%I', t);
      execute format('create trigger notify_alloc after insert or update on public.%I for each row execute function public.notify_call_allotted()', t);
    end if;
  end loop;

  if to_regclass('public.spare_request_lines') is not null then
    drop trigger if exists notify_dispatch on public.spare_request_lines;
    create trigger notify_dispatch after update on public.spare_request_lines
      for each row execute function public.notify_spare_dispatched();
  end if;
end $$;

-- ------------------------------------------------------------------------
-- 0054_notify_uid_ambiguous.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Fix: "column reference \"uid\" is ambiguous" when Stores books out a spare.
--
-- notify_spare_dispatched() (0045) declared a plpgsql variable named `uid`, and
-- then looked the request up with `... from public.spare_requests where uid =
-- new.request_uid`. `uid` there is both the variable and spare_requests.uid, so
-- Postgres refuses the reference and the trigger aborts the UPDATE — which is
-- the update Pending Dispatch performs, so booking out failed outright.
--
-- Rename the variable to v_uid and qualify the column via an alias. Same for
-- notify_call_allotted(), which had the same variable name (harmless there, but
-- renamed so the pattern can't bite again).
-- ===========================================================================

create or replace function public.notify_call_allotted()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_uid uuid;
begin
  if coalesce(new.allocated_to, '') = '' then return new; end if;
  if tg_op = 'UPDATE' and new.allocated_to is not distinct from old.allocated_to then return new; end if;
  v_uid := public.notify_resolve_uid(new.allocated_to_email, new.allocated_to);
  if v_uid is null then return new; end if;
  insert into public.notifications (recipient_id, recipient_email, kind, title, body, link)
  values (v_uid, coalesce(new.allocated_to_email, ''), 'call_allotted',
          'Call allotted to you',
          concat_ws(' · ', nullif(coalesce(new.ucn, ''), ''), nullif(coalesce(new.party_name, ''), ''), nullif(coalesce(new.product_name, ''), '')),
          '/' || case public.call_table_for(new.call_type)
                   when 'installation' then 'installations' when 'pm' then 'pm-calls' else 'field-calls' end);
  return new;
end $$;

create or replace function public.notify_spare_dispatched()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_uid uuid; r record;
begin
  if coalesce(new.stores_status, '') !~* 'dispatch' then return new; end if;
  if tg_op = 'UPDATE' and coalesce(old.stores_status, '') ~* 'dispatch' then return new; end if;
  select sr.engineer, sr.engineer_email, sr.ucn, sr.party_name into r
    from public.spare_requests sr where sr.uid = new.request_uid;
  v_uid := public.notify_resolve_uid(r.engineer_email, r.engineer);
  if v_uid is null then return new; end if;
  insert into public.notifications (recipient_id, recipient_email, kind, title, body, link)
  values (v_uid, coalesce(r.engineer_email, ''), 'spare_dispatched',
          'Spare dispatched',
          concat_ws(' · ', nullif(coalesce(new.part, ''), ''), nullif(coalesce(r.ucn, ''), ''), nullif(coalesce(r.party_name, ''), '')),
          '/spare-requests');
  return new;
end $$;

-- ------------------------------------------------------------------------
-- 0123_clear_notifications_on_signout.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Signing out clears your notifications — in the database, not just on screen.
--
-- The bell is a session convenience: "a call was allotted to you", "a spare you
-- asked for has been dispatched". The durable record is the call and the spare
-- request themselves, which is where anyone goes to act on either. So once you
-- sign out, the notifications have served their purpose and the rows go.
--
-- UNREAD ONES GO TOO. Sign-out is the clearing event, not "having read it" —
-- otherwise the thing the user asked for (a clean slate at the start of a
-- session) would not happen for exactly the people who have most piled up. The
-- work itself is not lost: the call is still in the register and the spare is
-- still on the request.
--
-- A SECURITY DEFINER function rather than a delete policy, so `authenticated`
-- is never granted `delete` on the table at all. It takes no arguments and
-- filters on auth.uid(): there is no shape of this call that reaches another
-- person's rows, and nothing to get wrong at the call site.
-- ===========================================================================

create or replace function public.clear_my_notifications()
returns integer language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); n integer;
begin
  -- Not signed in: nothing of yours to clear. Never a bare delete.
  if me is null then return 0; end if;
  delete from public.notifications where recipient_id = me;
  get diagnostics n = row_count;
  return n;
end $$;

revoke all on function public.clear_my_notifications() from public;
grant execute on function public.clear_my_notifications() to authenticated;

-- ------------------------------------------------------------------------
-- 0262_rename_is_not_an_allotment.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A RENAME DOES NOT NOTIFY "CALL ALLOTTED TO YOU" (0259, finding 23).
--
-- `notify_call_allotted` (0045/0054) writes a notification whenever a call's
-- allottee changes. 0259 rewrites the allottee on every call filed under a
-- renamed person's old name, so without this a spelling correction sent them
-- one "Call allotted to you" per call they already had. Recognised by the
-- ticket 0259 files for its own transaction. Body taken from the database.
-- ===========================================================================

create or replace function public.notify_call_allotted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $$
declare v_uid uuid;
begin
  if coalesce(new.allocated_to, '') = '' then return new; end if;
  if tg_op = 'UPDATE' and new.allocated_to is not distinct from old.allocated_to then return new; end if;
  -- A USER MASTER RENAME (0259) is not an allotment: the call was already this
  -- person's. Without this, correcting a name sent them one notice per call.
  if tg_op = 'UPDATE' and public.engineer_rename_in_progress(old.allocated_to, new.allocated_to) then return new; end if;
  v_uid := public.notify_resolve_uid(new.allocated_to_email, new.allocated_to);
  if v_uid is null then return new; end if;
  insert into public.notifications (recipient_id, recipient_email, kind, title, body, link)
  values (v_uid, coalesce(new.allocated_to_email, ''), 'call_allotted',
          'Call allotted to you',
          concat_ws(' · ', nullif(coalesce(new.ucn, ''), ''), nullif(coalesce(new.party_name, ''), ''), nullif(coalesce(new.product_name, ''), '')),
          '/' || case public.call_table_for(new.call_type)
                   when 'installation' then 'installations' when 'pm' then 'pm-calls' else 'field-calls' end);
  return new;
end $$;

-- ------------------------------------------------------------------------
-- 0394_notify_silent_import.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0394  A HISTORICAL CALL LOAD SENDS NO "CALL ALLOTTED" NOTIFICATION (2026-10-06).
--
-- The user, asked whether loading the old DCCR register's calls should notify
-- each engineer of every call: "No notifications". notify_call_allotted() is
-- restated from the database (0262's body) with one early return, taken only
-- when the transaction-local setting rithi.silent_import is 'on' -- which
-- dccr_history_apply() (0395) sets for the length of one row and nothing
-- else does. Every live allotment notifies exactly as before.
-- ===========================================================================
CREATE OR REPLACE FUNCTION public.notify_call_allotted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid;
begin
  -- A HISTORICAL LOAD NOTIFIES NOBODY (0394, the user 2026-10-06: "No
  -- notifications"). Set, transaction-local, by dccr_history_apply() alone.
  if coalesce(current_setting('rithi.silent_import', true), '') = 'on' then return new; end if;
  if coalesce(new.allocated_to, '') = '' then return new; end if;
  if tg_op = 'UPDATE' and new.allocated_to is not distinct from old.allocated_to then return new; end if;
  -- A USER MASTER RENAME (0259) is not an allotment: the call was already this
  -- person's. Without this, correcting a name sent them one notice per call.
  if tg_op = 'UPDATE' and public.engineer_rename_in_progress(old.allocated_to, new.allocated_to) then return new; end if;
  v_uid := public.notify_resolve_uid(new.allocated_to_email, new.allocated_to);
  if v_uid is null then return new; end if;
  insert into public.notifications (recipient_id, recipient_email, kind, title, body, link)
  values (v_uid, coalesce(new.allocated_to_email, ''), 'call_allotted',
          'Call allotted to you',
          concat_ws(' · ', nullif(coalesce(new.ucn, ''), ''), nullif(coalesce(new.party_name, ''), ''), nullif(coalesce(new.product_name, ''), '')),
          '/' || case public.call_table_for(new.call_type)
                   when 'installation' then 'installations' when 'pm' then 'pm-calls' else 'field-calls' end);
  return new;
end $function$;

-- ------------------------------------------------------------------------
-- 0122_notifications_replay_tail.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- The refurbished-part notice, which module ORDER had been quietly discarding.
--
-- `notify_spare_dispatched()` is created by 0045, corrected by 0054, and
-- extended by 0064 to say when the dispatched part is a REFURBISHED one — the
-- thing an engineer most needs told. But 0064 lives in `handstock`, and
-- `notifications` runs AFTER handstock in ALL_ORDER, so 0054's version had the
-- last word on every database built from all.sql: the refurbished line has
-- never been sent. Replaying HandStock_X.sql put 0064's back, and replaying
-- notifications.sql took it away again.
--
-- Ending this module with 0064's definition settles all three at once — the
-- fresh apply, the handstock replay and the notifications replay.
--
-- The definition here is a COPY. `npm run check:bundles` compares it with
-- 0064 word for word and fails if either side moves.
-- ===========================================================================

do $mirror$
begin
  if to_regclass('public.spare_dispatch_lines') is null then
    raise notice 'skip notify_spare_dispatched — public.spare_dispatch_lines is not present yet';
    return;
  end if;
  execute $body$
create or replace function public.notify_spare_dispatched()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_uid uuid; r record; refurb_note text := '';
begin
  if coalesce(new.stores_status, '') !~* 'dispatch' then return new; end if;
  if tg_op = 'UPDATE' and coalesce(old.stores_status, '') ~* 'dispatch' then return new; end if;
  select sr.engineer, sr.engineer_email, sr.ucn, sr.party_name into r
    from public.spare_requests sr where sr.uid = new.request_uid;
  v_uid := public.notify_resolve_uid(r.engineer_email, r.engineer);
  if v_uid is null then return new; end if;

  if exists (select 1 from public.spare_dispatch_lines d
              where d.line_id = new.id and d.refurbished) then
    refurb_note := ' · REFURBISHED part';
  end if;

  insert into public.notifications (recipient_id, recipient_email, kind, title, body, link)
  values (v_uid, coalesce(r.engineer_email, ''), 'spare_dispatched',
          case when refurb_note <> '' then 'Spare dispatched (refurbished)' else 'Spare dispatched' end,
          concat_ws(' · ', nullif(coalesce(new.part, ''), ''), nullif(coalesce(r.ucn, ''), ''),
                    nullif(coalesce(r.party_name, ''), '')) || refurb_note,
          '/spare-requests');
  return new;
end $$;
  $body$;
end $mirror$;

-- ------------------------------------------------------------------------
-- 0046_validation_results.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Validation execution tracker — stores the executed result of each test case
-- (IQ/OQ/PQ) in the database instead of on paper, so the validation evidence
-- lives with the system. One current record per test id (latest execution).
-- QA / admins record results; everyone signed in may read them.
-- ===========================================================================

create table if not exists public.validation_results (
  test_id     text primary key,          -- e.g. 'OQ-02'
  result      text not null default '',   -- Pass | Fail | N/A | (blank = not executed)
  actual      text default '',
  tester      text default '',
  notes       text default '',
  executed_at timestamptz,
  recorded_by uuid references auth.users (id),
  updated_at  timestamptz not null default now()
);

create or replace function public.validation_results_stamp()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.updated_at := now();
  if auth.uid() is not null then new.recorded_by := auth.uid(); end if;
  if new.result is not null and new.result <> '' and new.executed_at is null then
    new.executed_at := now();
  end if;
  return new;
end $$;
drop trigger if exists validation_results_stamp on public.validation_results;
create trigger validation_results_stamp before insert or update on public.validation_results
  for each row execute function public.validation_results_stamp();

alter table public.validation_results enable row level security;
grant select, insert, update on public.validation_results to authenticated;

drop policy if exists valres_read on public.validation_results;
create policy valres_read on public.validation_results for select using (auth.role() = 'authenticated');

drop policy if exists valres_write on public.validation_results;
create policy valres_write on public.validation_results for all
  using (public.is_admin() or public.has_perm('config.manage'))
  with check (public.is_admin() or public.has_perm('config.manage'));

-- ------------------------------------------------------------------------
-- 0293_validation_manage_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0293 — RECORDING VALIDATION RESULTS HAS A KEY OF ITS OWN
--
-- Findings 57-67 (docs/PERMISSIONS_REVIEW.md), the user's decisions of
-- 2026-09-30: "63, 64: It should show the Individual View's Control Action and
-- its Check Box" -- each screen gets keys of its own, today's grants copied
-- across (0298) so nobody gains or loses anything on the day it ships -- and
-- "67: Break it down", with the old key kept as the PARENT of the new ones, so
-- a role holding it keeps everything until an administrator unticks it.
-- The parent rule itself is in has_perm() (0286, public.perm_parents).
--
-- This file: valres_write asked config.manage while the screen asked
-- config.manage OR users.manage (finding 64). Both now ask validation.manage.
-- ===========================================================================

drop policy if exists valres_write on public.validation_results;
create policy valres_write on public.validation_results for all
  using (public.is_admin() or public.has_perm('validation.manage'))
  with check (public.is_admin() or public.has_perm('validation.manage'));

-- ------------------------------------------------------------------------
-- 0130_quality_objectives.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- ALMS-INDIA QUALITY & BUSINESS OBJECTIVES, on their own page.
--
-- The user's Service Quality Objective workbook, 2026: twelve objectives, each
-- with a yearly target, how often it is measured, who is responsible, and the
-- month-by-month actual. Kept by hand in Excel until now.
--
-- "I need all these there and let's figure out later what all we can automate."
-- So this is the REGISTER first: every objective present, every actual visible
-- and editable, and nothing pretending to be computed that is not. As each one
-- is automated it stops being typed and starts being read from the calls —
-- `source` is what will say which, and today every row says 'manual'.
--
-- ONE ROW PER OBJECTIVE PER YEAR, twelve month columns, exactly as the sheet is
-- shaped. A month is NULL when it was not measured, which is how the sheet's
-- "NA" reads on a quarterly objective — not zero, which would drag an average
-- down and is a different claim entirely.
--
-- THE TOTAL IS STORED, NOT COMPUTED. In the workbook column V is a SUM on the
-- count rows and something closer to an average on the rate rows, and which it
-- is cannot be told from the row itself. Computing one number for both would
-- put a wrong figure on a quality record, so the sheet's own total is carried
-- across and stays typed until each objective is automated and can say how its
-- total is arrived at.
--
-- The targets stay TEXT: "<5%", ">75%", "To Monitor" are the sheet's own words
-- and they are what an auditor reads. Parsing them into a number and an
-- operator would be inventing precision the register does not have.
-- ===========================================================================

create table if not exists public.quality_objectives (
  id             bigint generated always as identity primary key,
  year           integer not null,
  sort_order     integer not null default 0,
  process        text    not null default '',     -- SERVICE | BUSINESS
  parameter      text    not null,                -- what is monitored
  yearly_target  text    not null default '',     -- "<5%", ">75%", "To Monitor"
  current_target text    not null default '',
  frequency      text    not null default '',     -- Monthly | 3 Months
  responsible    text    not null default '',
  m01 numeric, m02 numeric, m03 numeric, m04 numeric, m05 numeric, m06 numeric,
  m07 numeric, m08 numeric, m09 numeric, m10 numeric, m11 numeric, m12 numeric,
  total          numeric,
  -- 'manual' while somebody types the figure; the name of what computes it once
  -- it is automated. Nothing reads this yet; it is here so that when the first
  -- objective is automated, the page can say which are and which are not.
  source         text not null default 'manual',
  notes          text not null default '',
  updated_by     uuid,
  updated_at     timestamptz not null default now()
);

create unique index if not exists quality_objectives_year_param_uniq
  on public.quality_objectives (year, lower(btrim(parameter)));

alter table public.quality_objectives enable row level security;

-- Readable by anyone signed in who can see the register: an objective is the
-- company's, not one team's. Written by the people who own the numbers —
-- config.manage is what the admin screens already ask for.
drop policy if exists qo_read on public.quality_objectives;
create policy qo_read on public.quality_objectives for select
  using (public.has_perm('calls.view') or public.has_perm('reports.view'));
drop policy if exists qo_write on public.quality_objectives;
create policy qo_write on public.quality_objectives for all
  using (public.has_perm('config.manage')) with check (public.has_perm('config.manage'));
grant select, insert, update, delete on public.quality_objectives to authenticated;

create or replace function public.quality_objectives_stamp()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.updated_at := now();
  if auth.uid() is not null then new.updated_by := auth.uid(); end if;
  return new;
end $$;
drop trigger if exists zz_quality_objectives_stamp on public.quality_objectives;
create trigger zz_quality_objectives_stamp before insert or update on public.quality_objectives
  for each row execute function public.quality_objectives_stamp();

-- ---------------------------------------------------------------------------
-- The 2026 objectives, as the workbook has them. Jan-Jul carry actuals; August
-- onwards are blank because the sheet has not been filled in yet, and a blank
-- month is not a zero.
--
-- ON CONFLICT DO NOTHING: re-running this must not overwrite a figure somebody
-- has since typed on the screen. To reload a year deliberately, delete it first.
-- ---------------------------------------------------------------------------
insert into public.quality_objectives
