-- ------------------------------------------------------------------------
-- 0298_permission_grants_copied.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0298 — TODAY'S GRANTS, COPIED ONTO THE NEW PER-SCREEN KEYS, ONCE.
--
-- The user, 2026-09-30, on findings 63 and 64: "It should show the Individual
-- View's Control Action and its Check Box" -- answered with keys of their own
-- per screen (0286-0297). A key nobody holds would take every one of those
-- buttons away from everybody the day this ships, so each new key is given to
-- exactly the roles and people that hold the key it replaces:
--
--   install.* / pm.* / calls.reopen  <- the calls.* key it was checked under
--   contract.edit                    <- cover.edit
--   tracker.delete                   <- the Tracker page itself (everybody
--                                       who opens it could delete)
--   objective.manage, charts.share,
--   validation.manage, layouts.share <- config.manage, which the database
--                                       asked for each of them
--   pd2.rebuild                      <- masters.edit or cover.edit
--   stock.return.others              <- any spare approval stage or dispatch,
--                                       which is what the database asked
--
-- ONCE, AND SAID SO IN A TABLE. A re-run that copied again would hand a key
-- back to a role an administrator had deliberately unticked it from, which is
-- the one thing a permission migration must never do. The keys that are
-- CHILDREN of a key somebody holds (0286's perm_parents) are not copied at all:
-- the parent already grants them.
--
-- A role row with no permissions is left alone: an empty array means "not
-- configured" and falls back to the engineer defaults, so it inherits through
-- the engineer row, which is copied like any other.
--
-- Also, every run (finding 66, "Fix it"): the two ticks that did nothing are
-- taken off every role and person -- dashboard.view, which nothing tested, and
-- the User Access page (/users), which only redirects to the User Master.
-- ===========================================================================

create table if not exists public.permission_copies_done (
  name       text primary key,
  applied_at timestamptz not null default now()
);
alter table public.permission_copies_done enable row level security;
revoke all on public.permission_copies_done from anon, authenticated;
do $$
begin
  if to_regprocedure('public.sys_columns_attach(regclass)') is not null then
    perform public.sys_columns_attach('public.permission_copies_done'::regclass);
  end if;
end $$;

do $$
declare
  pair record;
  n_roles int; n_people int;
begin
  if to_regclass('public.app_roles') is null or to_regclass('public.profiles') is null then
    raise notice '0298: app_roles or profiles missing -- nothing copied';
    return;
  end if;
  if exists (select 1 from public.permission_copies_done where name = '0284_per_screen_keys') then
    raise notice '0298: the per-screen keys were copied before -- not copied again';
  else
    for pair in
      select * from (values
        ('install.edit',           array['calls.edit']),
        ('install.edit.complaint', array['calls.edit.complaint']),
        ('install.edit.customer',  array['calls.edit.customer']),
        ('install.edit.vigilance', array['calls.edit.vigilance']),
        ('install.edit.contact',   array['calls.edit.contact']),
        ('install.allot',          array['calls.allot']),
        ('install.report',         array['calls.report']),
        ('install.cancel',         array['calls.cancel']),
        ('install.reopen',         array['calls.create', 'pending.register']),
        ('pm.create',              array['calls.create']),
        ('pm.edit',                array['calls.edit']),
        ('pm.edit.complaint',      array['calls.edit.complaint']),
        ('pm.edit.customer',       array['calls.edit.customer']),
        ('pm.edit.vigilance',      array['calls.edit.vigilance']),
        ('pm.edit.contact',        array['calls.edit.contact']),
        ('pm.allot',               array['calls.allot']),
        ('pm.report',              array['calls.report']),
        ('pm.cancel',              array['calls.cancel']),
        ('pm.reopen',              array['calls.create', 'pending.register']),
        ('calls.reopen',           array['calls.create', 'pending.register']),
        ('contract.edit',          array['cover.edit']),
        ('tracker.delete',         array['mod:/tracker']),
        ('objective.manage',       array['config.manage']),
        ('charts.share',           array['config.manage']),
        ('validation.manage',      array['config.manage']),
        ('layouts.share',          array['config.manage']),
        ('pd2.rebuild',            array['masters.edit', 'cover.edit']),
        ('stock.return.others',    array['spare.approve_rm', 'spare.approve_commercial', 'spare.approve_nsm', 'spare.dispatch'])
      ) as t(new_key, old_keys)
    loop
      update public.app_roles
         set permissions = permissions || jsonb_build_array(pair.new_key), updated_at = now()
       where jsonb_array_length(permissions) > 0
         and permissions ?| pair.old_keys
         and not permissions ? pair.new_key;
      get diagnostics n_roles = row_count;
      update public.profiles
         set extra_permissions = coalesce(extra_permissions, '[]'::jsonb) || jsonb_build_array(pair.new_key)
       where coalesce(extra_permissions, '[]'::jsonb) ?| pair.old_keys
         and not coalesce(extra_permissions, '[]'::jsonb) ? pair.new_key;
      get diagnostics n_people = row_count;
      raise notice '0298: % given to % role(s) and % person(s) holding %', pair.new_key, n_roles, n_people, pair.old_keys;
    end loop;
    insert into public.permission_copies_done (name) values ('0284_per_screen_keys');
  end if;

  update public.app_roles
     set permissions = (select coalesce(jsonb_agg(e), '[]'::jsonb) from jsonb_array_elements(permissions) e
                         where e not in ('"dashboard.view"'::jsonb, '"mod:/users"'::jsonb)),
         updated_at = now()
   where permissions ?| array['dashboard.view', 'mod:/users'];
  update public.profiles
     set extra_permissions = (select coalesce(jsonb_agg(e), '[]'::jsonb) from jsonb_array_elements(extra_permissions) e
                               where e not in ('"dashboard.view"'::jsonb, '"mod:/users"'::jsonb))
   where coalesce(extra_permissions, '[]'::jsonb) ?| array['dashboard.view', 'mod:/users'];
end $$;

-- ------------------------------------------------------------------------
-- 0244_sys_columns.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- SYSTEM COLUMNS ON EVERY TABLE: sys_id, sys_created_by, sys_created_on,
-- sys_updated_by, sys_updated_on.
--
--   The user, 2026-09-26: "I need a key, Timestamp, sys_created_by,
--   sys_updated_by in all the tables" -- and then: "sys_created_by,
--   sys_created_on shouldn't overlap with any of the other fields". Their
--   answers to the four open questions:
--     * the key is a NEW sys_id on every table, not a business key;
--     * the author columns hold the LOGIN ID (auth.uid());
--     * rows that already exist are FILLED FROM EXISTING FIELDS;
--     * EVERY TABLE EXCEPT THE NUMBER COUNTERS.
--
-- "SHOULDN'T OVERLAP" IS THE DESIGN, and it is why none of these reuses a
-- column that already exists. `created_at`, `created_by`, `updated_at` and the
-- rest keep their BUSINESS meaning, which is not always "who wrote this row":
-- `field_calls.created_by` is the Hotline DESK a call is filed to (0114), and
-- `reports.updated_at` is the "Visit Entry Date" the Consumption Report prints.
-- The sys_* columns mean one thing on every table -- which login wrote the row,
-- and when -- and the DATABASE writes them:
--
--   sys_stamp() (a BEFORE INSERT OR UPDATE trigger, `zzz_sys_stamp`, named to
--   run LAST so every guard sees the row as the caller wrote it):
--     INSERT  -> a fresh sys_id; created_* and updated_* = this login, now().
--     UPDATE  -> sys_id and created_* kept from the old row; updated_* = this
--                login, now().
--   A SIGNED-IN CALLER CANNOT SET THEM. What the app sends is DISCARDED, not
--   refused -- the 0113/0114 rule: refusing makes an honest client fail (a row
--   read with select * and written back carries them), discarding makes a buggy
--   one harmless. Only a trusted role -- the SQL editor, a migration, a
--   SECURITY DEFINER function -- may supply a value, so a restore can put back
--   what it saved; left unsupplied, those are stamped too, from the real
--   caller's login (auth.uid() reads the session, not the definer).
--
-- THE ONE-TIME FILL, "FROM EXISTING FIELDS" -- same MEANING only, never a guess:
--     sys_created_on <- created_at
--     sys_created_by <- actual_created_by where the table has one (the three
--                       call tables: their created_by is the DESK, not the
--                       author, so it is deliberately NOT used), else
--                       created_by, else recorded_by -- uuid columns only
--     sys_updated_on <- updated_at
--     sys_updated_by <- updated_by
--   A table with no such field leaves that column blank, which means "not
--   recorded" -- nothing is invented. `spare_consumption.recorded_by` is a
--   typed NAME, not a login, so it is not used either.
--
-- HOW THE FILL IS DONE, because the obvious way is dangerous: an UPDATE over
-- every row would fire every guard, the audit trail, and -- on `reports` --
-- sync_call_last_visit(), which recomputes the status of every call. Instead
-- each column is ADDED as `generated always as (<source>) stored` and then
-- converted to a plain column with `drop expression`. That is a table rewrite,
-- which fires NO triggers, and it leaves exactly the values an UPDATE would
-- have written. One ALTER per table, so one rewrite per table.
--
-- NOT TOUCHED: the ten number-counter tables (their rows have no author);
-- `harness`, the test stand-in for Supabase's session; `schema_migrations`,
-- the auto-apply script's own ledger.
--
-- A TABLE ADDED LATER is covered by re-running this bundle: the loop at the end
-- attaches whatever is missing and leaves the rest alone. `_status.sql` row 187
-- names any table without the five columns and the trigger.
-- ===========================================================================

create or replace function public.sys_stamp()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
declare
  -- The API roles are the ones a client speaks as. Anything else -- postgres
  -- in the SQL editor, a migration, a SECURITY DEFINER function -- is trusted
  -- to supply a value (a restore putting back what it saved).
  trusted boolean := current_user not in ('authenticated', 'anon');
begin
  if tg_op = 'INSERT' then
    if not trusted then
      new.sys_id         := gen_random_uuid();
      new.sys_created_by := auth.uid();
      new.sys_created_on := now();
      new.sys_updated_by := auth.uid();
      new.sys_updated_on := now();
    else
      new.sys_id         := coalesce(new.sys_id, gen_random_uuid());
      new.sys_created_by := coalesce(new.sys_created_by, auth.uid());
      new.sys_created_on := coalesce(new.sys_created_on, now());
      new.sys_updated_by := coalesce(new.sys_updated_by, new.sys_created_by);
      new.sys_updated_on := coalesce(new.sys_updated_on, new.sys_created_on);
    end if;
    return new;
  end if;

  -- UPDATE
  if not trusted then
    new.sys_id         := old.sys_id;
    new.sys_created_by := old.sys_created_by;
    new.sys_created_on := old.sys_created_on;
    new.sys_updated_by := auth.uid();
    new.sys_updated_on := now();
  else
    -- A trusted statement that names a sys column keeps what it wrote (a
    -- repair); one that does not gets the stamp like anybody else.
    if new.sys_updated_on is not distinct from old.sys_updated_on then
      new.sys_updated_on := now();
    end if;
    if new.sys_updated_by is not distinct from old.sys_updated_by then
      new.sys_updated_by := auth.uid();
    end if;
  end if;
  return new;
end $$;

comment on function public.sys_stamp() is
  'Writes sys_id / sys_created_* / sys_updated_* on every insert and update (0244). A signed-in caller''s values are discarded; a trusted role may supply them.';

create or replace function public.sys_columns_attach(p_table regclass)
returns void
language plpgsql
set search_path = public, pg_temp
as $$
declare
  rel  name := (select c.relname from pg_class c where c.oid = p_table);
  adds text[] := '{}';
  gens text[] := '{}';
  src  text;
begin
  -- sys_id: a key of its own on every row, filled for the rows already there
  -- by the column default during the rewrite.
  if not exists (select 1 from pg_attribute where attrelid = p_table and attname = 'sys_id' and not attisdropped) then
    adds := array_append(adds, 'add column sys_id uuid not null default gen_random_uuid()');
  end if;

  -- sys_created_by <- actual_created_by, else created_by, else recorded_by (uuid only)
  if not exists (select 1 from pg_attribute where attrelid = p_table and attname = 'sys_created_by' and not attisdropped) then
    select a.attname into src
      from pg_attribute a
     where a.attrelid = p_table and not a.attisdropped
       and a.attname in ('actual_created_by', 'created_by', 'recorded_by')
       and a.atttypid = 'uuid'::regtype
     order by array_position(array['actual_created_by', 'created_by', 'recorded_by']::name[], a.attname)
     limit 1;
    if src is not null then
      adds := array_append(adds, format('add column sys_created_by uuid generated always as (%I) stored', src));
      gens := array_append(gens, 'sys_created_by');
    else
      adds := array_append(adds, 'add column sys_created_by uuid');
    end if;
  end if;

  -- sys_created_on <- created_at
  src := null;
  if not exists (select 1 from pg_attribute where attrelid = p_table and attname = 'sys_created_on' and not attisdropped) then
    select a.attname into src from pg_attribute a
     where a.attrelid = p_table and not a.attisdropped
       and a.attname = 'created_at' and a.atttypid = 'timestamptz'::regtype;
    if src is not null then
      adds := array_append(adds, format('add column sys_created_on timestamptz generated always as (%I) stored', src));
      gens := array_append(gens, 'sys_created_on');
    else
      adds := array_append(adds, 'add column sys_created_on timestamptz');
    end if;
  end if;

  -- sys_updated_by <- updated_by
  src := null;
  if not exists (select 1 from pg_attribute where attrelid = p_table and attname = 'sys_updated_by' and not attisdropped) then
    select a.attname into src from pg_attribute a
     where a.attrelid = p_table and not a.attisdropped
       and a.attname = 'updated_by' and a.atttypid = 'uuid'::regtype;
    if src is not null then
      adds := array_append(adds, format('add column sys_updated_by uuid generated always as (%I) stored', src));
      gens := array_append(gens, 'sys_updated_by');
    else
      adds := array_append(adds, 'add column sys_updated_by uuid');
    end if;
  end if;

  -- sys_updated_on <- updated_at
  src := null;
  if not exists (select 1 from pg_attribute where attrelid = p_table and attname = 'sys_updated_on' and not attisdropped) then
    select a.attname into src from pg_attribute a
     where a.attrelid = p_table and not a.attisdropped
       and a.attname = 'updated_at' and a.atttypid = 'timestamptz'::regtype;
    if src is not null then
      adds := array_append(adds, format('add column sys_updated_on timestamptz generated always as (%I) stored', src));
      gens := array_append(gens, 'sys_updated_on');
    else
      adds := array_append(adds, 'add column sys_updated_on timestamptz');
    end if;
  end if;

  -- ONE ALTER, so ONE rewrite; then the generated columns become plain ones,
  -- keeping the values the rewrite computed.
  if array_length(adds, 1) > 0 then
    execute format('alter table %s %s', p_table, array_to_string(adds, ', '));
  end if;
  if array_length(gens, 1) > 0 then
    execute format('alter table %s %s', p_table,
      (select string_agg(format('alter column %I drop expression', g), ', ') from unnest(gens) g));
  end if;

  if to_regclass(format('public.%I', rel || '_sys_id_key')) is null then
    execute format('create unique index %I on %s (sys_id)', rel || '_sys_id_key', p_table);
  end if;

  -- Created only when missing: its definition never changes (the FUNCTION is
  -- what 'create or replace' above keeps current), and a drop-then-create
  -- prints a notice per table, which in the SQL editor reads as a problem.
  if not exists (select 1 from pg_trigger where tgrelid = p_table and tgname = 'zzz_sys_stamp') then
    execute format('create trigger zzz_sys_stamp before insert or update on %s for each row execute function public.sys_stamp()', p_table);
  end if;
end $$;

comment on function public.sys_columns_attach(regclass) is
  'Adds the five sys_* columns, their unique key and the stamping trigger to one table, filling existing rows from same-meaning fields (0244). Idempotent.';

-- DDL, for migrations only. Nobody signed in has any business calling it.
revoke all on function public.sys_columns_attach(regclass) from public;
do $$ begin
  execute 'revoke all on function public.sys_columns_attach(regclass) from anon, authenticated';
exception when undefined_object then null; end $$;

-- Every table in `public`, except the counters and the two tooling tables.
do $$
declare r record;
begin
  for r in
    select c.oid::regclass as t
      from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relkind = 'r'
       and c.relname not in (
         -- the ten number counters (indoor_dc_counters, 0321): a row there has no author
         'call_number_seq', 'ffr_counters', 'indoor_dc_counters', 'indoor_job_counters',
         'material_return_counters', 'party_key_seq', 'spare_dispatch_counters',
         'spare_or_counters', 'stock_transfer_counters', 'ucn_counters',
         -- tooling, not application data
         'harness', 'schema_migrations')
     order by c.relname
  loop
    perform public.sys_columns_attach(r.t);
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0245_sys_columns_view_tail.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- GUARDED MIRROR (0245) -- the views that carry every column of their table,
-- rebuilt so they carry the sys_* columns 0244 has just added.
--
-- WHY THIS FILE EXISTS. Six views are written `select t.*` (or a union of
-- `select *`), and `*` is expanded when the view is CREATED. So after 0244 the
-- live views lack sys_*, while re-running the bundle that owns any of them
-- rebuilds it WITH sys_* -- a view whose shape depends on which bundle ran last.
-- `check:replay` refuses exactly that, and one of the six, export_schedule_state
-- (`s.*` FOLLOWED by a computed column), does not merely drift: re-running
-- data_export.sql would stop with "cannot change name of view column", because
-- `create or replace view` can only append.
--
-- So each is rebuilt here, once, after the columns exist -- and every definition
-- below is its OWNER'S, WORD FOR WORD, which `check:bundles` enforces (MIRRORS).
-- Edit one of the owners and this must be edited to match, or that check fails.
-- It must stay the LAST file in its module.
--
--   calls, pending_calls, calls_view_insert/update   <- 0114_call_registrant_split.sql
--   field_failure_register                           <- 0197_review_actual_product.sql
--   indoor_job_list                                  <- 0323_indoor_stages.sql
--   tracker_list                                     <- 0143_tracker.sql
--   export_schedule_state                            <- 0228_export_schedules.sql
--
-- The INSTEAD OF functions are regenerated from field_calls' column list, so
-- they now pass sys_* through to the table -- where sys_stamp() discards them
-- for any signed-in caller, because both functions run as the CALLER (not
-- SECURITY DEFINER). A client cannot forge them through the view either.
-- ===========================================================================

-- ---- calls, pending_calls, and writes through the view (0114, verbatim) ----
do $views$
begin
  if to_regclass('public.field_calls') is null then return; end if;
  create or replace view public.calls as
    select * from public.field_calls
    union all select * from public.installation_calls
    union all select * from public.pm_calls;
end $views$;

-- `create or replace view` DROPS security_invoker, and a view without it reads
-- as its OWNER — every signed-in user seeing every call, with no error and no
-- warning. It has happened three times in this project (0040/0050/0057), so it
-- is re-asserted on EVERY rebuild, here included.
alter view public.calls set (security_invoker = on);

-- pending_calls is `select * from calls`, so it needs the same treatment to
-- gain the column — and marking it invoker is not optional either: a view
-- marked invoker that reads a view running as its owner inherits the owner's
-- reach.
create or replace view public.pending_calls as
  select * from public.calls
   where cancelled_at is null
     and (open_state <> 'Solved' or reopened_at is not null);
alter view public.pending_calls set (security_invoker = on);
alter view public.call_state    set (security_invoker = on);

-- ---- 5. writes through the view carry it too ------------------------------
-- The INSTEAD OF functions were generated from the column list as it was.
-- Regenerated here, and the RETURNING clause gains `actual_created_by` so the
-- client sees the stamp it did not send.
do $regen$
declare ins_cols text; ins_vals text; set_list text;
begin
  if to_regclass('public.field_calls') is null then return; end if;
  select string_agg(quote_ident(column_name), ', ' order by ordinal_position),
         string_agg(
           case when column_default is not null
                then format('coalesce(new.%I, %s)', column_name, column_default)
                else 'new.' || quote_ident(column_name) end,
           ', ' order by ordinal_position),
         string_agg(quote_ident(column_name) || ' = new.' || quote_ident(column_name), ', ' order by ordinal_position)
    into ins_cols, ins_vals, set_list
    from information_schema.columns
   where table_schema = 'public' and table_name = 'field_calls'
     -- open_state EXCLUDED BY NAME, not only by being generated. 0226 turns
     -- it into an ordinary column kept by a trigger, so `is_generated`
     -- stops excluding it and this list would silently start writing a
     -- DERIVED value through the view. A no-op before 0226; the thing
     -- that holds after it. check:replay found exactly this.
     and is_generated = 'NEVER' and column_name not in ('id', 'open_state');

  execute format($f$
    create or replace function public.calls_view_insert() returns trigger language plpgsql as $b$
    begin
      case public.call_table_for(new.call_type)
        when 'installation' then
          insert into public.installation_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, actual_created_by, open_state, added_on, reg_at
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.actual_created_by, new.open_state, new.added_on, new.reg_at;
        when 'pm' then
          insert into public.pm_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, actual_created_by, open_state, added_on, reg_at
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.actual_created_by, new.open_state, new.added_on, new.reg_at;
        else
          insert into public.field_calls (%1$s) values (%2$s)
            returning id, ucn, call_number, reg_date, created_by, actual_created_by, open_state, added_on, reg_at
            into new.id, new.ucn, new.call_number, new.reg_date, new.created_by, new.actual_created_by, new.open_state, new.added_on, new.reg_at;
      end case;
      return new;
    end $b$;
  $f$, ins_cols, ins_vals);

  execute format($f$
    create or replace function public.calls_view_update() returns trigger language plpgsql as $b$
    begin
      case public.call_table_for(old.call_type)
        when 'installation' then update public.installation_calls set %1$s where ucn = old.ucn;
        when 'pm'           then update public.pm_calls           set %1$s where ucn = old.ucn;
        else                     update public.field_calls        set %1$s where ucn = old.ucn;
      end case;
      -- NOTHING WRITTEN IS NOTHING REPORTED (finding 48). When row-level
      -- security lets the caller see a call but not change it, the UPDATE above
      -- matches no row -- and returning NEW regardless told the client
      -- "UPDATE 1" over a call left exactly as it was. NULL makes the view
      -- report the row as not updated, which is the truth.
      if not found then return null; end if;
      return new;
    end $b$;
  $f$, set_list);
end $regen$;

-- ---- field_failure_register (0197, verbatim) -------------------------------
drop view if exists public.field_failure_register;
create view public.field_failure_register as
select
  f.*,
  -- THESE THREE ARE NOT DECORATION AND WERE THE REASON THE FIRST VERSION OF
  -- THIS FILE FAILED. It was written from 0179, which is not the last word on
  -- this view — 0167 and a later change added `live_call_status`,
  -- `live_last_visit_at` and `live_engineer` BEFORE the customer name, and
  -- omitting them made the replacement narrower than the view it replaced:
  -- `cannot drop columns from view`. The definition here is the one taken from
  -- a database built by the migrations, not the one read out of a file.
  c.open_state                      as live_call_status,
  c.last_visit_at                   as live_last_visit_at,
  c.allocated_to                    as live_engineer,
  c.party_name                      as live_customer_name,
  c.item_status                     as live_cover,
  (select count(*) from public.reports rp where rp.ucn = f.ucn)            as live_visit_count,
  (select coalesce(string_agg(distinct btrim(s.part), ', '), '')
     from public.spare_consumption s
    where s.ucn = f.ucn and coalesce(s.qty, 0) > 0)                        as live_spares_consumed,
  r.any_potential_effect            as live_any_potential_effect,
  r.risk_to_patient                 as live_risk_to_patient,
  r.warranty_failure                as live_warranty_failure,
  r.frequent_failure                as live_frequent_failure,
  r.complaint_grouping              as live_complaint_grouping,
  r.root_cause_keyword              as live_root_cause_keyword,
  r.spare_category                  as live_spare_category,
  r.review2_at                      as live_review2_at,
  r.review3_done                    as live_review3_done,
  -- WHAT ACTUALLY FAILED. The review's answer where it gave one, the report's
  -- otherwise. Every count, rate and Pareto reads THIS, so a failure moved onto
  -- an accessory is counted there and nowhere else.
  coalesce(nullif(btrim(r.actual_product), ''), f.product_name)            as live_product_name,
  -- ...and whether it was moved, so a screen can say so rather than leaving two
  -- product names to be noticed. A reader seeing CPX CARE on a report that
  -- names EXTEND-XT deserves to be told which is which.
  (coalesce(nullif(btrim(r.actual_product), ''), f.product_name)
     is distinct from f.product_name)                                      as live_product_changed
from public.field_failure_reports f
left join public.calls c        on c.ucn = f.ucn
left join public.call_reviews r on r.ucn = f.ucn;

alter view public.field_failure_register set (security_invoker = on);
grant select on public.field_failure_register to authenticated;

-- ---- indoor_job_list (0323, verbatim) --------------------------------------
-- GUARDED BY 0323's COLUMNS. Applied in FILE order (the test harness, a
-- rebuild from the migrations folder) this file runs BEFORE 0323, whose
-- definition it copies, and the columns that definition names do not exist
-- yet -- 0323 itself then rebuilds the view, sys_* included. Applied in BUNDLE
-- order (sys_columns is last) 0323 has already run and this rebuilds it with
-- sys_*.
do $indoor_list$
begin
  if not exists (select 1 from information_schema.columns
                  where table_schema = 'public' and table_name = 'indoor_jobs'
                    and column_name = 'report_uploaded_by') then
    return;
  end if;
drop view if exists public.indoor_job_list;
create view public.indoor_job_list as
  select j.*,
         coalesce(rb.name, '') as received_by_name,
         coalesce(cb.name, '') as cleaned_by_name,
         coalesce(qb.name, '') as qc_by_name,
         coalesce(db.name, '') as dispatched_by_name,
         coalesce(xb.name, '') as condemned_by_name,
         coalesce(ub.name, '') as updated_by_name,
         (j.status in ('Closed', 'Dispatched', 'Condemned')) as is_closed,
         -- A DEMO unit out past its due date, which is the one figure nothing
         -- else in this system produces. NULL rather than false where there is
         -- no due date: "not overdue" and "nobody said when" are different facts.
         (case when j.activity = 'Demo' and j.actual_return is null
                    and j.expected_return is not null
               then (j.expected_return < (now() at time zone 'Asia/Kolkata')::date)
          end) as demo_overdue,
         (select count(*) from public.indoor_job_accessories a where a.job_id = j.id)
           as accessory_count,
         (select count(*) from public.indoor_job_accessories a
           where a.job_id = j.id and not a.returned) as accessories_outstanding,
         coalesce(vb.name, '') as verified_by_name,
         (select string_agg(btrim(a.name) || case when a.qty <> 1 then ' x' || trim_scale(a.qty)::text else '' end,
                            ', ' order by a.id) from public.indoor_job_accessories a
           where a.job_id = j.id and btrim(a.name) <> '') as accessories_received,
         public.indoor_job_is_imported(j.product_name, j.serial) as product_imported,
         coalesce(rpb.name, '') as report_uploaded_by_name
    from public.indoor_jobs j
    left join public.app_user_names rb on rb.id = j.received_by
    left join public.app_user_names cb on cb.id = j.cleaned_by
    left join public.app_user_names qb on qb.id = j.qc_by
    left join public.app_user_names db on db.id = j.dispatched_by
    left join public.app_user_names xb on xb.id = j.condemned_by
    left join public.app_user_names ub on ub.id = j.updated_by
    left join public.app_user_names vb on vb.id = j.verified_by
    left join public.app_user_names rpb on rpb.id = j.report_uploaded_by;
alter view public.indoor_job_list set (security_invoker = on);
grant select on public.indoor_job_list to authenticated;
end $indoor_list$;

-- ---- tracker_list (0143, verbatim) -----------------------------------------
drop view if exists public.tracker_list;
create view public.tracker_list as
  select t.*,
         coalesce(cu.name, '') as created_by_name,
         coalesce(uu.name, '') as updated_by_name,
         (t.status in ('Done', 'Dropped')) as is_closed
    from public.tracker_items t
    left join public.app_user_names cu on cu.id = t.created_by
    left join public.app_user_names uu on uu.id = t.updated_by;
alter view public.tracker_list set (security_invoker = on);
grant select on public.tracker_list to authenticated;

-- ---- export_schedule_state (0228, verbatim) --------------------------------
-- `s.*` is followed by a computed column, so the new columns land in the MIDDLE
-- and `create or replace` cannot put them there: the drop is this file's own,
-- the definition is the owner's. Nothing depends on this view.
drop view if exists public.export_schedule_state;
create or replace view public.export_schedule_state as
select s.*,
       public.export_run_due_at(s.frequency, s.day_of_week, s.hour_ist, s.minute_ist, now())
         + case when s.frequency = 'weekly' then interval '7 days' else interval '1 day' end
         as next_run_at
  from public.export_schedules s;

alter view public.export_schedule_state set (security_invoker = on);
grant select on public.export_schedule_state to authenticated;

-- ------------------------------------------------------------------------
-- 0248_lock_down_internal_functions.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- WHAT THE PUBLIC KEY CAN REACH, NARROWED (findings 49, 50, 51, 52).
--
--   The user, 2026-09-26: "Fix all low hanging fruits", after the table review
--   (RITHI Table Atlas) measured, on a database built from the migrations:
--     49  the NOT-signed-in role set the Party Key counter to 999,999, and the
--         next key issued was Party-1000000 -- party_key_seq was the one table
--         with row-level security OFF, and Supabase grants every table to anon;
--     50  the not-signed-in role called raise_ffr() and a Field Failure Report
--         was raised on a call of its choosing -- an undeletable quality record
--         using up a number in the controlled R-SER-03 series;
--     51  register-wide maintenance functions ran for any caller;
--     52  every numbered series (UCN, OR, DC, MRN, ST, Party Key, Call Number)
--         could be consumed by a direct call, leaving gaps.
--
-- THE RULE APPLIED: a SECURITY DEFINER function that the APP does not call
-- is not the API's to call. Every one below is reached from inside the
-- database -- a trigger function or another function, EACH OF THEM SECURITY
-- DEFINER, checked against the catalogue before this was written -- so it runs
-- as the owner there and keeps working. Only the two roles a client speaks as
-- lose it: anon and authenticated. PUBLIC is revoked too, because that is where
-- a function's default EXECUTE comes from.
--
-- WHAT THE APP DOES CALL keeps authenticated and loses only anon:
--   next_call_reqid()        -- Request Registration mints a REQID
--   refresh_product_cover()  -- Data Import, after a cover import
--   cover_unpin_inherited()  -- the same step; 0247 makes both ask for cover.edit
--
-- IDEMPOTENT, and GUARDED: a function a project has not got yet is skipped, not
-- an error, so this can run on a project behind on other modules. It is the
-- LAST module for the same reason sys_columns was: a replay of the module that
-- owns one of these functions uses `create or replace`, which keeps the grants,
-- but a re-run of THIS bundle is also how to put them back if a rebuild did not.
-- `_status.sql` rows 188 and 189 say whether it holds.
-- ===========================================================================

-- ---- 49. the Party Key counter: row-level security on, no policy -----------
-- Exactly how the other eight counters are kept: nothing but a definer function
-- may read or write the row. next_party_key() is one, and the parties insert
-- trigger that calls it is another, so a new party still gets its key.
do $$
begin
  if to_regclass('public.party_key_seq') is null then return; end if;
  alter table public.party_key_seq enable row level security;
  revoke all on table public.party_key_seq from anon, authenticated;
end $$;

-- ---- 50, 51, 52. what the API may call ---------------------------------------
do $$
declare
  fn text;
  internal text[] := array[
    -- 50: raised by the review trigger (ffr_from_review) and backfill_ffrs()
    'public.raise_ffr(public.call_reviews)',
    -- 51: register-wide maintenance, reached only from definer triggers or cron
    'public.upsert_product_from_sale(bigint)',
    'public.sync_product_cover(text)',
    'public.sync_call_last_visit(text)',
    'public.purge_audit_log()',
    -- 52: the numbered series, each assigned by a definer trigger on insert
    'public.next_ucn(text)',
    'public.next_party_key()',
    'public.next_spare_or_no(date)',
    'public.next_mrn_uid(date)',
    'public.next_dispatch_no(text,date)',
    'public.next_stock_out_no(date)',
    'public.next_stock_transfer_no(date)',
    'public.next_direct_call_number(text)'];
  app_called text[] := array[
    'public.next_call_reqid()',
    'public.refresh_product_cover()',
    'public.cover_unpin_inherited()'];
begin
  foreach fn in array internal loop
    if to_regprocedure(fn) is null then continue; end if;
    execute format('revoke execute on function %s from public', fn);
    begin execute format('revoke execute on function %s from anon, authenticated', fn);
    exception when undefined_object then null; end;
  end loop;

  foreach fn in array app_called loop
    if to_regprocedure(fn) is null then continue; end if;
    execute format('revoke execute on function %s from public', fn);
    begin
      execute format('revoke execute on function %s from anon', fn);
      execute format('grant execute on function %s to authenticated', fn);
    exception when undefined_object then null; end;
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0338_helpers_not_public.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0338 — THREE DEFINER HELPERS ARE NOT CALLABLE WITHOUT SIGNING IN
--        (second re-review, 2026-10-03: D-134)
--
-- Postgres grants EXECUTE to PUBLIC and Supabase grants it to anon, so these
-- ran with the owner's rights for anybody holding the web key (CLAUDE.md, the
-- 0248 lockdown):
--   notify_resolve_uid(text, text)   turns an email or a name into a login id
--                                    (measured: as anon it returned one)
--   engineer_stock_available(text, text)  any engineer's balance of any part
--   due_export_schedules()           which scheduled exports are owed
-- WHO STILL CALLS THEM: the first two are called only from the stock and
-- notification triggers, which run as the owner; the third only from the
-- scheduled-export Edge Function, with the service role key (index.ts). No
-- screen calls any of them, so signed-in users keep exactly what they had --
-- EXECUTE for authenticated is granted back explicitly for the first two, since
-- revoking PUBLIC would otherwise take it from them too.
-- ===========================================================================
do $$
begin
  if to_regprocedure('public.notify_resolve_uid(text, text)') is not null then
    execute 'revoke execute on function public.notify_resolve_uid(text, text) from public, anon';
    execute 'grant execute on function public.notify_resolve_uid(text, text) to authenticated';
  end if;
  if to_regprocedure('public.engineer_stock_available(text, text)') is not null then
    execute 'revoke execute on function public.engineer_stock_available(text, text) from public, anon';
    execute 'grant execute on function public.engineer_stock_available(text, text) to authenticated';
  end if;
  if to_regprocedure('public.due_export_schedules()') is not null then
    execute 'revoke execute on function public.due_export_schedules() from public, anon, authenticated';
    begin
      execute 'grant execute on function public.due_export_schedules() to service_role';
    exception when undefined_object then null;   -- a plain Postgres has no service_role
    end;
  end if;
end $$;

commit;
